#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char *identifier;
} Record;

int process_requests(long *offsets, int *keys, Record **records, size_t num_records,
                     long start_index, long end_index, int target_sum) {
    if (start_index < 0 || end_index >= num_records || start_index > end_index) return -1;

    int count = 0;
    int current_sum = 0;

    for (long i = start_index; i <= end_index; ++i) {
        current_sum += records[i]->value;
        if (current_sum >= target_sum) {
            count++;
        }
    }

    return count;
}

Record *initialize_records(size_t num_records, int min_val, int max_val) {
    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;

        // Simulate fetching an identifier from an external source
        char *identifier = malloc(20); // Assume max identifier length is 20 chars
        if (!identifier) {
            perror("Failed to allocate memory for identifier");
            exit(EXIT_FAILURE);
        }
        snprintf(identifier, 20, "ID_%zu", i + 1);

        records[i].identifier = identifier;
    }

    return records;
}

void free_resources(long *offsets, int *keys, Record **records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i]->identifier);
    }
    free(*records);
    free(offsets);
    free(keys);
}

void manage_record_system(size_t num_records, int min_val, int max_val,
                          long start_index, long end_index, int target_sum) {

    // Allocate and initialize arrays
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));

    if (!offsets || !keys) {
        perror("Failed to allocate memory for offsets or keys");
        exit(EXIT_FAILURE);
    }

    Record *records = initialize_records(num_records, min_val, max_val);

    // Process request
    int result = process_requests(offsets, keys, &records, num_records,
                                  start_index, end_index, target_sum);

    printf("Count of records meeting or exceeding the target sum: %d\n", result);

    // Free resources
    free_resources(&offsets, &keys, &records, num_records);
}

int main() {
    size_t num_records = 1000;
    int min_val = 1, max_val = 100;
    long start_index = 10, end_index = 200;
    int target_sum = 500;

    manage_record_system(num_records, min_val, max_val, start_index, end_index, target_sum);

    return 0;
}
```

### Key Points:
- **Memory Management**: The code dynamically allocates memory for `offsets`, `keys`, and an array of `Record` structures. It ensures proper deallocation to prevent memory leaks.
- **Error Handling**: Uses `perror` for error messages and exits on allocation failure.
- **Random Initialization**: Initializes each record with a random integer value within a specified range.
- **Modular Design**: Functions are designed to handle specific tasks, making the system easy to extend or modify.']

