    fclose(fp);
    log_message("File processed successfully.");
    if (verbose) {
        printf("Processed file: %s\n", input_file);
    }
    return EXIT_SUCCESS;
}

int main(int argc, char *argv[]) {
    initialize_logging();

    int opt, verbose = 0;
    char delimiter = '\n'; // Default line delimiter
    const char *output_file = NULL;

    pthread_mutex_init(&file_access_mutex, NULL);

    if (argc < 2) {
        usage(argv[0]);
        exit(EXIT_FAILURE);
    }

    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"verbose", no_argument, 0, 'v'},
        {"output", required_argument, 0, 'o'},
        {"manpage", no_argument, 0, 1},
        {0, 0, 0, 0}
    };

    while ((opt = getopt_long(argc, argv, "hvo:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                usage(argv[0]);
                exit(EXIT_SUCCESS);
            case 'v':
                verbose = 1;
                break;
            case 'o':
                output_file = optarg;
                break;
            case 1:
                print_manpage(argv[0]);
                exit(EXIT_SUCCESS);
            default:
                usage(argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "Expected argument after options\n");
        usage(argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *input_file = argv[optind];

    // Check for custom delimiter option
    if (argc > optind + 1) {
        delimiter = argv[optind + 1][0]; // Assuming single-character delimiter provided as next argument
    }

    if (!output_file && getenv("DEFAULT_OUTPUT_FILE")) {
        output_file = getenv("DEFAULT_OUTPUT_FILE");
    } else if (!output_file) {
        output_file = DEFAULT_OUTPUT_FILE;
    }

    log_message(argv[0]);

    int result = process_file(input_file, output_file, delimiter, verbose);
    exit(result);
}
