#include <stdio.h>
#include <stdlib.h>
import jansson.h;
#include <pthread.h>
#include <dirent.h>
#include <sys/stat.h>
#include <string.h>
#include <unistd.h>

#define MAX_THREADS 8

typedef struct {
    char *input_dir;
    char *output_dir;
    json_t *config;
} thread_data_t;

void* process_files(void* arg) {
    thread_data_t *data = (thread_data_t*)arg;
    DIR *dir;
    struct dirent *entry;

    if (!(dir = opendir(data->input_dir))) {
        perror("opendir");
        return NULL;
    }

    while ((entry = readdir(dir)) != NULL) {
        if(entry->d_type == DT_REG && strstr(entry->d_name, ".bin")) {
            char input_path[1024];
            snprintf(input_path, sizeof(input_path), "%s/%s", data->input_dir, entry->d_name);

            // Open the binary file
            FILE *file = fopen(input_path, "rb");
            if (!file) {
                perror("fopen");
                continue;
            }

            fseek(file, 0, SEEK_END);
            long file_size = ftell(file);
            rewind(file);

            char *buffer = malloc(file_size);
            if (buffer == NULL) {
                fclose(file);
                fprintf(stderr, "Memory allocation failed for buffer\n");
                continue;
            }

            fread(buffer, 1, file_size, file);
            fclose(file);

            // Process the buffer according to transformation rules from config
            json_t *rules = json_object_get(data->config, "transformation_rules");

            // Apply transformations (example: inverting bytes)
            for (long i = 0; i < file_size; ++i) {
                buffer[i] ^= 0xFF;  // Example transformation
            }

            char output_path[1024];
            snprintf(output_path, sizeof(output_path), "%s/%s", data->output_dir, entry->d_name);

            file = fopen(output_path, "wb");
            if (!file) {
                perror("fopen for writing");
                free(buffer);
                continue;
            }

            fwrite(buffer, 1, file_size, file);
            fclose(file);

            free(buffer);
        }
    }

    closedir(dir);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <input_dir> <output_dir> <config_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *input_dir = argv[1];
    const char *output_dir = argv[2];
    const char *config_file_path = argv[3];

    json_error_t error;
    json_t *config = json_load_file(config_file_path, 0, &error);

    if (!config) {
        fprintf(stderr, "Error parsing JSON config: %s\n", error.text);
        exit(EXIT_FAILURE);
    }

    pthread_t threads[MAX_THREADS];
    thread_data_t data[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; ++i) {
        data[i].input_dir = input_dir;
        data[i].output_dir = output_dir;
        data[i].config = json_deep_copy(config);

        int rc = pthread_create(&threads[i], NULL, process_files, &data[i]);
        if (rc != 0) {
            fprintf(stderr, "Error creating thread: %d\n", rc);
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
        json_decref(data[i].config);
    }

    json_decref(config);

    return 0;
}
```

### Important Notes:
- **Concurrency:** Uses POSIX threads (`pthread`) for concurrent processing.
- **Memory Management:** Allocates memory dynamically for file reading and ensures cleanup.
