#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int read_integers_from_file(FILE *file, int ***array) {
    size_t capacity = 10;
    int count = 0;

    // Initial allocation for integers array
    *array = (int **)malloc(sizeof(int *));
    if (!*array) return -1;
    (**array) = (int *)malloc(capacity * sizeof(int));
    if (!(**array)) {
        free(*array);
        return -1;
    }

    while (!feof(file)) {
        int value;
        // Read integer from file
        if (fscanf(file, "%d", &value) != 1) {
            if (feof(file)) break;  // End of file reached
            else {
                // Handle read error, e.g., non-integer input
                free((**array));
                free(*array);
                return -1;
            }
        }

        // Check for integer overflow when adding to count or calculating sum
        if (count == capacity) {
            capacity *= 2;
            int *new_array = realloc((**array), capacity * sizeof(int));
            if (!new_array) {
                free(**array);
                free(*array);
                return -1;
            }
            **array = new_array;
        }

        // Safely add integer to the array
        (**array)[count++] = value;
    }

    // Resize the memory block to match the actual number of integers read
    int *final_array = realloc((**array), count * sizeof(int));
    if (!final_array) {
        free(**array);
        return -1;
    }
    **array = final_array;

    if (count == 0) { // Check for empty file case
        free(*array);
        *array = NULL;
    }

    return count > 0 ? 0 : -1; // Return error code for empty files
}

void find_largest_and_average(const int *array, size_t length) {
    if (length == 0) {
        printf("Array is empty.\n");
        return;
    }

    int largest = INT_MIN;
    long long sum = 0;

    for (size_t i = 0; i < length; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }

        // Using long long to avoid overflow during sum calculation
        sum += array[i];
    }

    double average = static_cast<double>(sum) / length;

    printf("Largest integer: %d\n", largest);
    printf("Average of integers: %.2f\n", average);
}

int main() {
    FILE *file = fopen("input.txt", "r");
    if (!file) {
        perror("Error opening file");
        return -1;
    }

    int **array = NULL;
    if (read_integers_from_file(file, &array) == 0 && array != NULL) {
        size_t length = 0;
        while (*array[length] != '\0') {
            ++length;
        }

        find_largest_and_average(*array, length);
        free(*array);
        free(array);
    } else {
        printf("No valid integers found in file or an error occurred.\n");
    }

    fclose(file);
    return 0;
}
