#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef enum {
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARN,
    LOG_LEVEL_ERROR
} LogLevel;

static LogLevel currentLogLevel = LOG_LEVEL_DEBUG;
static pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

// Configuration functions
void setLogLevel(LogLevel level) {
    pthread_mutex_lock(&logMutex);
    currentLogLevel = level;
    pthread_mutex_unlock(&logMutex);
}

LogLevel getLogLevel() {
    LogLevel level;
    pthread_mutex_lock(&logMutex);
    level = currentLogLevel;
    pthread_mutex_unlock(&logMutex);
    return level;
}

// Log message format
typedef struct {
    char *timestamp;
    char *userIdentifier;
} Metadata;

const char* logLevelToString(LogLevel level) {
    switch (level) {
        case LOG_LEVEL_DEBUG: return "DEBUG";
        case LOG_LEVEL_INFO:  return "INFO";
        case LOG_LEVEL_WARN:  return "WARN";
        case LOG_LEVEL_ERROR: return "ERROR";
        default:              return "UNKNOWN";
    }
}

// Thread-safe log function
void logMessage(LogLevel level, const Metadata *metadata, const char *format, ...) {
    if (level < getLogLevel()) return;

    pthread_mutex_lock(&logMutex);

    // Efficient message formatting
    va_list args;
    va_start(args, format);
    char buffer[1024];
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strcspn(timestamp, "\n")] = 0; // Remove newline

    printf("[%s] [%s] [%s] - %s\n", 
           timestamp,
           metadata ? metadata->userIdentifier : "N/A",
           logLevelToString(level),
           buffer);

    pthread_mutex_unlock(&logMutex);
}

// Error handling simulation
void handleError(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    // Implement additional error handling logic here
}

int main() {
    Metadata metadata = { .timestamp = "2023-10-01T12:00:00Z", .userIdentifier = "User123" };

    setLogLevel(LOG_LEVEL_INFO);

    logMessage(LOG_LEVEL_DEBUG, &metadata, "This is a debug message.");
    logMessage(LOG_LEVEL_INFO, &metadata, "Starting process...");
    logMessage(LOG_LEVEL_WARN, &metadata, "Low disk space warning!");
    logMessage(LOG_LEVEL_ERROR, &metadata, "Failed to connect to server.");

    handleError("Simulated error");

    return 0;
}
