        TypeData targetTypeData = typeCache.getOrDefault(targetType, fetchTypeData(targetType));
        if (targetTypeData == null) {
            throw new RuntimeException("Target type data not available");
        }

        Map<String, Double> weaknesses = new HashMap<>();
        Map<String, Double> resistances = new HashMap<>();

        for (String type : pokemon.types) {
            TypeData typeData = typeCache.get(type);
            if (typeData != null) {
                switch (typeData.effectivenessAgainst(targetType)) {
                    case "2x":
                        weaknesses.put(targetType, 2.0);
                        break;
                    case "0.5x":
                        resistances.put(targetType, 0.5);
                        break;
