        double overallEffectiveness = calculateMoveEffectiveness(pokemon.moves, targetTypeData, buffMultiplier, debuffMultiplier);

        BattleAnalysis analysis = new BattleAnalysis(
                pokemon.name,
                pokemon.types,
                weaknesses,
                resistances,
                overallEffectiveness
        );

        return objectMapper.writeValueAsString(analysis);
