    private double calculateMoveEffectiveness(Map<String, Double> moves, TypeData targetTypeData, double buffMultiplier, double debuffMultiplier) {
        double effectiveness = 1.0;
        for (Map.Entry<String, Double> move : moves.entrySet()) {
            // Calculate effectiveness based on move type and target weaknesses/resistances
            effectiveness *= move.getValue() * buffMultiplier / debuffMultiplier; // Simplified logic
        }
        return effectiveness;
    }

    public void shutdown() {
        scheduler.shutdown();
    }
