#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>
#include <string.h>

// Define a structure for semaphore with metadata
typedef struct {
    sem_t *sem;
    int initial_value;
} DynamicSemaphore;

// Global lock for managing access to the collection of semaphores
pthread_mutex_t semaphore_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Linked list node for maintaining dynamic semaphores
typedef struct SemaphoreNode {
    DynamicSemaphore *dyn_sem;
    struct SemaphoreNode *next;
} SemaphoreNode;

// Head pointer for the linked list of semaphores
SemaphoreNode *semaphore_head = NULL;

// Function to initialize a semaphore with error handling
int init_semaphore(DynamicSemaphore **dyn_sem, int initial_value) {
    *dyn_sem = (DynamicSemaphore *)malloc(sizeof(DynamicSemaphore));
    if (*dyn_sem == NULL) return -1;

    sem_init(&((*dyn_sem)->sem), 0, initial_value);
    (*dyn_sem)->initial_value = initial_value;

    return 0;
}

// Function to add a semaphore to the collection
int add_semaphore(int initial_value) {
    pthread_mutex_lock(&semaphore_list_lock);

    DynamicSemaphore *new_sem = NULL;
    if (init_semaphore(&new_sem, initial_value) != 0) {
        pthread_mutex_unlock(&semaphore_list_lock);
        return -1;
    }

    SemaphoreNode *node = (SemaphoreNode *)malloc(sizeof(SemaphoreNode));
    if (node == NULL) {
        sem_destroy(new_sem->sem);
        free(new_sem);
        pthread_mutex_unlock(&semaphore_list_lock);
        return -1;
    }

    node->dyn_sem = new_sem;
    node->next = semaphore_head;
    semaphore_head = node;

    pthread_mutex_unlock(&semaphore_list_lock);

    return 0;
}

// Function to remove a semaphore from the collection
int remove_semaphore() {
    if (semaphore_head == NULL) {
        return -1; // No semaphores available for removal
    }

    pthread_mutex_lock(&semaphore_list_lock);

    SemaphoreNode *node = semaphore_head;
    semaphore_head = node->next;

    sem_destroy(node->dyn_sem->sem);
    free(node->dyn_sem);
    free(node);

    pthread_mutex_unlock(&semaphore_list_lock);

    return 0;
}

// Function to increment a semaphore with timeout
int semaphore_increment(DynamicSemaphore *dyn_sem, unsigned int timeout) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout;

    return sem_timedwait(dyn_sem->sem, &ts);
}

// Function to decrement a semaphore with timeout
int semaphore_decrement(DynamicSemaphore *dyn_sem, unsigned int timeout) {
    if (sem_trywait(dyn_sem->sem) == -1 && errno != EAGAIN) {
        return -1; // Handle errors other than EAGAIN
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout;

    return sem_timedpost(dyn_sem->sem, &ts);
}

// Cleanup function to release all resources
void cleanup_all() {
    pthread_mutex_lock(&semaphore_list_lock);

    while (semaphore_head != NULL) {
        SemaphoreNode *node = semaphore_head;
        semaphore_head = node->next;

        sem_destroy(node->dyn_sem->sem);
        free(node->dyn_sem);
        free(node);
    }

    pthread_mutex_unlock(&semaphore_list_lock);
}

// Usage example
int main() {
    add_semaphore(1); // Initialize a semaphore with initial value 1

    SemaphoreNode *node = semaphore_head;
    if (node != NULL) {
        DynamicSemaphore *sem = node->dyn_sem;

        // Perform operations on the semaphore...
        semaphore_decrement(sem, 5); // Decrement with timeout
        semaphore_increment(sem, 5); // Increment with timeout
    }

    remove_semaphore(); // Remove a semaphore

    cleanup_all(); // Cleanup all semaphores
    pthread_mutex_destroy(&semaphore_list_lock);

    return 0;
}
```']

