// Mockup external data source retrieval function
int getExternalValue(const std::string& key) {
    // Simulate retrieving value from an external data source.
    // Return -1 to simulate a failure in fetching the value.
    if (key == "fail") return -1;  // Simulating an error condition
    return key.length();  // Example: use string length as mock value
}

void updateOrAddKey(std::unordered_map<std::string, int>& map,
                    const std::string& key, int newValue) {
    static std::mutex mtx;

    // Lock the mutex for thread safety during modification of the map
    std::lock_guard<std::mutex> lock(mtx);

    // Validate input: ensure the key is not empty and value is valid (e.g., non-negative)
    if (key.empty() || newValue < 0) {
        std::cerr << "Invalid input: Key must be non-empty, and value must be non-negative.\n";
        return;
    }

    try {
        // Check for uniqueness of the key
        if (map.count(key) > 0) {
            std::cerr << "Duplicate key detected. Aborting operation to maintain unique keys.\n";
            return;
        }

        // Retrieve and validate value from external source
        int externalValue = getExternalValue(key);

        if (externalValue == -1) {
            std::cerr << "Failed to retrieve external data for key: " << key << ". Using provided value.\n";
            map[key] = newValue;  // Use the new value if fetching fails
        } else {
            // If fetched successfully, use external value instead of provided one
            map[key] = externalValue;
        }
    } catch (const std::exception& e) {
        std::cerr << "Exception occurred: " << e.what() << ". Operation aborted.\n";
    }
}

// Example usage
int main() {
    std::unordered_map<std::string, int> myMap;

    // Example operations
    updateOrAddKey(myMap, "key1", 10);
    updateOrAddKey(myMap, "fail", 20);  // Simulate external data fetch failure
    updateOrAddKey(myMap, "", -5);      // Invalid input example

    for (const auto& [k, v] : myMap) {
        std::cout << k << ": " << v << "\n";
    }

    return 0;
}
