public class XmlProcessor
{
    public void ParseAndProcessXmlDocument(string filePath, string targetNodeName)
    {
        if (string.IsNullOrEmpty(filePath) || string.IsNullOrEmpty(targetNodeName))
            throw new ArgumentException("File path and node name must be provided.");

        try
        {
            using (XmlReader reader = XmlReader.Create(filePath))
            {
                while (reader.Read())
                {
                    if (reader.NodeType == XmlNodeType.Element && reader.Name.Equals(targetNodeName, StringComparison.OrdinalIgnoreCase))
                    {
                        // Process the node content
                        string nodeContent = reader.ReadString();
                        ProcessNodeContent(nodeContent);
                        break;  // Stop after processing the first instance
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error reading XML file: {ex.Message}");
        }
    }

