use std::collections::HashMap;
use std::fs::{self, DirEntry};
use std::path::{Path, PathBuf};
use log::{info, error};
use lazy_static::lazy_static;
use std::sync::{Arc, Mutex};

lazy_static! {
    static ref ENV_MANAGER: Arc<Mutex<EnvironmentVariableManager>> = Arc::new(Mutex::new(EnvironmentVariableManager::new()));
}

pub struct EnvironmentVariableManager {
    env_vars: HashMap<String, String>,
}

impl EnvironmentVariableManager {
    pub fn new() -> Self {
        EnvironmentVariableManager {
            env_vars: HashMap::new(),
        }
    }

    pub fn create_directory(&mut self, dir_path: &str) {
        let path = PathBuf::from(dir_path);
        match fs::create_dir_all(&path) {
            Ok(_) => info!("Directory created successfully: {}", dir_path),
            Err(e) if e.kind() == std::io::ErrorKind::PermissionDenied => error!("Permission denied: {}", dir_path),
            Err(e) if e.kind() == std::io::ErrorKind::NoSpaceLeftOnDevice => error!("Disk full while creating directory: {}", dir_path),
            Err(_) => error!("Failed to create directory: {}", dir_path),
        }
    }

    pub fn add_environment_variable(&mut self, key: &str, value: &str) {
        self.env_vars.insert(key.to_string(), value.to_string());
        info!("Environment variable added - Key: {}, Value: {}", key, value);
    }

    pub fn remove_environment_variable(&mut self, key: &str) {
        if let Some(_) = self.env_vars.remove(key) {
            info!("Environment variable removed - Key: {}", key);
        } else {
            error!("Failed to remove environment variable - Key: {}", key);
        }
    }

    pub fn safe_remove_directory(&self, dir_path: &str) {
        let path = PathBuf::from(dir_path);

        if fs::metadata(&path).is_ok() && fs::read_dir(&path).is_ok() {
            for entry in fs::read_dir(&path).unwrap_or_else(|_| Vec::new()) {
                if let Ok(entry) = entry {
                    let entry_path = entry.path();
                    if entry_path.is_file() || entry_path.is_symlink() {
                        match fs::remove_file(entry_path) {
                            Ok(_) => info!("Removed file: {}", entry.file_name().unwrap().to_string_lossy()),
                            Err(e) => error!("Failed to remove file {}: {}", entry.file_name().unwrap().to_string_lossy(), e),
                        }
                    } else if let Some(direntry) = entry.path().canonicalize().ok() {
                        self.safe_remove_directory(&direntry.to_str().unwrap());
                    }
                }
            }
        }

        match fs::remove_dir_all(path) {
            Ok(_) => info!("Directory removed successfully: {}", dir_path),
            Err(e) if e.kind() == std::io::ErrorKind::PermissionDenied => error!("Permission denied while removing directory: {}", dir_path),
            Err(_) => error!("Failed to remove directory: {}", dir_path),
        }
    }

    pub fn manage_directory(&mut self, dir_name: &str) {
        let home_dir = dirs::home_dir().unwrap();
        let full_path = home_dir.join(dir_name);

        if !full_path.exists() {
            self.create_directory(full_path.to_str().unwrap());
            self.add_environment_variable("MY_APP_DIR", full_path.to_str().unwrap());
        }
    }

    pub fn manage_environment_variables(&self) {
        let mut env_manager = ENV_MANAGER.lock().unwrap();
        // Example usage
        env_manager.add_environment_variable("TEST_VAR", "test_value");
        env_manager.remove_environment_variable("TEST_VAR");
    }
}

fn main() {
    env_logger::init();

    let mut env_manager = EnvironmentVariableManager::new();

    // Create a directory and manage environment variables
    env_manager.manage_directory("my_app_dir");

    // Safe removal of directories
    env_manager.safe_remove_directory("/path/to/remove");

    // Manage environment variables
    env_manager.manage_environment_variables();
}
