import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Level;
import java.util.logging.Logger;

public class MD5HashUtil {

    private static final Logger logger = Logger.getLogger(MD5HashUtil.class.getName());
    private Map<String, String> cache;
    private int cacheSize;

    public MD5HashUtil(int initialCacheSize) {
        this.cacheSize = initialCacheSize;
        this.cache = new LinkedHashMap<String, String>(initialCacheSize, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, String> eldest) {
                if (size() > MD5HashUtil.this.cacheSize) {
                    logger.log(Level.INFO, "Evicting entry: {0}", eldest.getKey());
                    return true;
                }
                return false;
            }
        };
    }

    public void resizeCache(int newSize) {
        this.cacheSize = newSize;
        while (this.cache.size() > this.cacheSize) {
            Map.Entry<String, String> eldest = this.cache.entrySet().iterator().next();
            logger.log(Level.INFO, "Evicting entry during resize: {0}", eldest.getKey());
            eldest.getValue(); // Access to trigger eviction
            this.cache.remove(eldest.getKey());
        }
    }

    public String getMD5Hash(String input) {
        if (input == null) {
            return null;
        }

        if (cache.containsKey(input)) {
            logger.log(Level.INFO, "Cache hit for input: {0}", input);
            return cache.get(input);
        }

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            BigInteger no = new BigInteger(1, messageDigest);
            String hashtext = no.toString(16);

            while (hashtext.length() < 32) {
                hashtext = "0" + hashtext;
            }

            logger.log(Level.INFO, "Cache miss for input: {0}", input);
            cache.put(input, hashtext);
            return hashtext;

        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }
}

// Unit Tests

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class MD5HashUtilTest {

    private MD5HashUtil md5Util;

    @BeforeEach
    void setUp() {
        md5Util = new MD5HashUtil(10);
    }

    @Test
    void testMD5NullInput() {
        assertNull(md5Util.getMD5Hash(null));
    }

    @Test
    void testMD5EmptyString() {
        assertEquals("d41d8cd98f00b204e9800998ecf8427e", md5Util.getMD5Hash(""));
    }

    @Test
    void testMD5RepeatedInput() {
        String input = "hello";
        String hash1 = md5Util.getMD5Hash(input);
        String hash2 = md5Util.getMD5Hash(input);
        assertEquals(hash1, hash2);
    }

    @Test
    void testCacheResizing() {
        for (int i = 0; i < 15; i++) {
            md5Util.getMD5Hash("test" + i);
        }

        md5Util.resizeCache(5);

        assertEquals(5, md5Util.cache.size());
    }

    @Test
    void testStressTesting() {
        for (int i = 0; i < 10000; i++) {
            String input = "test" + i;
            md5Util.getMD5Hash(input);
        }

        assertEquals(10, md5Util.cache.size());
    }
}
