<?php

function manageUserAccounts() {
    $response = ['status' => '', 'message' => ''];

    // Validate input data
    if (!validateRequest($_REQUEST)) {
        $response['status'] = 'error';
        $response['message'] = 'Invalid input data.';
        return json_encode($response);
    }

    try {
        $dbConnection = startDatabaseTransaction();

        if (isset($_REQUEST['sub_action']) && $_REQUEST['sub_action'] === 'delete') {
            handleDeleteAction($dbConnection, $_REQUEST);
        } elseif (isset($_REQUEST['id'])) {
            updateUserAccount($dbConnection, $_REQUEST);
        } else {
            createUserAccount($dbConnection, $_REQUEST);
        }

        commitDatabaseTransaction($dbConnection);

        $response['status'] = 'success';
        $response['message'] = 'Operation completed successfully.';
    } catch (Exception $e) {
        rollbackDatabaseTransaction($dbConnection);
        logError($e->getMessage());
        $response['status'] = 'error';
        $response['message'] = 'An error occurred while processing your request.';
    }

    return json_encode($response);
}

function validateRequest($data) {
    if (strlen($data['name']) < 2 || strlen($data['name']) > 50) {
        return false;
    }
    if (!filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
        return false;
    }
    if (!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[\W_]).{8,}$/', $data['password'])) {
        return false;
    }
    if (isset($data['role']) && !in_array($data['role'], ['admin', 'editor', 'viewer'])) {
        return false;
    }
    return true;
}

function startDatabaseTransaction() {
    // Establish a database connection and begin transaction
    // Implement connection pooling and load distribution strategies here
    $dbConnection = new PDO('mysql:host=localhost;dbname=ecommerce', 'user', 'password');
    $dbConnection->beginTransaction();
    return $dbConnection;
}

function commitDatabaseTransaction($dbConnection) {
    $dbConnection->commit();
}

function rollbackDatabaseTransaction($dbConnection) {
    $dbConnection->rollBack();
}

function logError($message) {
    // Log error message to a file or monitoring system
    error_log($message);
}

function createUserAccount($dbConnection, $data) {
    if (emailExists($dbConnection, $data['email'])) {
        throw new Exception('Email already exists.');
    }

    $hashedPassword = password_hash($data['password'], PASSWORD_BCRYPT);

    // Save user account data to the database
    saveUser($dbConnection, [
        'name' => $data['name'],
        'email' => $data['email'],
        'password' => $hashedPassword,
        'role' => $data['role'] ?? null
    ]);

    // Implement caching strategy for frequently accessed data
}

function updateUserAccount($dbConnection, $data) {
    $user = getUser($dbConnection, $data['id']);

    if (!$user) {
        throw new Exception('User not found.');
    }

    // Update user account data in the database
    saveUser($dbConnection, [
        'id' => $data['id'],
        'name' => $data['name'],
        'email' => $data['email'],
        'password' => password_hash($data['password'], PASSWORD_BCRYPT),
        'role' => $data['role'] ?? $user['role']
    ]);

    // Update shipping and billing preferences
}

function handleDeleteAction($dbConnection, $data) {
    $user = getUser($dbConnection, $data['id']);

    if (!$user) {
        throw new Exception('User not found.');
    }

    // Deactivate the user account and archive order history
    deactivateUser($dbConnection, $data['id']);
}

function emailExists($dbConnection, $email) {
    // Check if email exists in the database
    $stmt = $dbConnection->prepare('SELECT COUNT(*) FROM users WHERE email = :email');
    $stmt->execute([':email' => $email]);
    return $stmt->fetchColumn() > 0;
}

function saveUser($dbConnection, $userData) {
    // Save user data to the database
    $stmt = $dbConnection->prepare('INSERT INTO users (name, email, password, role) VALUES (:name, :email, :password, :role)');
    $stmt->execute([
        ':name' => $userData['name'],
        ':email' => $userData['email'],
        ':password' => $userData['password'],
        ':role' => $userData['role']
    ]);
}

function getUser($dbConnection, $id) {
    // Retrieve user data from the database
    $stmt = $dbConnection->prepare('SELECT * FROM users WHERE id = :id');
    $stmt->execute([':id' => $id]);
    return $stmt->fetch(PDO::FETCH_ASSOC);
}

function deactivateUser($dbConnection, $userId) {
    // Deactivate user account and archive order history
    $stmt = $dbConnection->prepare('UPDATE users SET active = 0 WHERE id = :id');
    $stmt->execute([':id' => $userId]);

    // Archive related orders
}

// Implement retry mechanism for transient database failures
function executeWithRetry($callback, $maxRetries = 3) {
    $attempt = 0;
    while ($attempt < $maxRetries) {
        try {
            return $callback();
        } catch (Exception $e) {
            if (++$attempt >= $maxRetries) {
                throw $e;
            }
        }
    }
}
