public static class Extensions
{
    public static IActionResult Forbid(this IActionResult result, string message) => new StatusCodeResult(403, message);
    public static IActionResult BadRequest(this IActionResult result, string message) => new StatusCodeResult(400, message);
    public static IActionResult Ok(this IActionResult result) => new StatusCodeResult(200);
    public class StatusCodeResult : IActionResult
    {
        public int StatusCode { get; }
        public string Message { get; }

        public StatusCodeResult(int statusCode, string message = null)
        {
            StatusCode = statusCode;
            Message = message;
        }
    }
}
