["```javascript
const fs = require('fs');
const path = require('path');
const util = require('util');
const readdir = util.promisify(fs.readdir);
const stat = util.promisify(fs.stat);
const readFile = util.promisify(fs.readFile);

async function processFiles(directory, filterOptions) {
    try {
        const files = await readdir(directory);

        for (let file of files) {
            let filePath = path.join(directory, file);

            // Get file stats asynchronously
            let stats = await stat(filePath);
            if (!stats.isFile()) continue;

            // Apply user-defined filters
            if (filterOptions.size && stats.size < filterOptions.size.min || 
                stats.size > filterOptions.size.max) continue;

            if (filterOptions.modifiedDate && new Date(stats.mtime) < filterOptions.modifiedDate.min ||
                new Date(stats.mtime) > filterOptions.modifiedDate.max) continue;

            // Check for specific content patterns
            let fileContent = await readFile(filePath, 'utf8');
            if (filterOptions.contentPattern &&
                !new RegExp(filterOptions.contentPattern).test(fileContent)) {
                    continue;
            }

            // Process the file here (example: log file path)
            console.log(`Processing file: ${filePath}`);
        }
    } catch (error) {
        console.error(`Error processing files in directory ${directory}:`, error);
    }
}

// Example usage:
const filterOptions = {
    size: { min: 1024, max: 1048576 }, // Size between 1KB and 1MB
    modifiedDate: { 
        min: new Date('2022-01-01'), 
        max: new Date('2023-12-31') 
    },
    contentPattern: 'specific pattern to match'
};

processFiles('/path/to/directory', filterOptions);

```

### Key Aspects:
1. **Asynchronous Operations**: Uses `promisify` for non-blocking file operations.
2. **Filtering**: Allows filtering by size, last modified date, and content patterns.
3. **Error Handling & Logging**: Catches and logs errors to facilitate debugging.
4. **Scalability Considerations**: Designed to handle large datasets with async/await to minimize blocking.
5. **Concurrency**: Processes files independently within an iteration loop which helps manage concurrency without explicit locks.

This setup can be extended for horizontal scaling by partitioning directories or using a distributed processing framework such as Apache Kafka or RabbitMQ to queue file paths for processing by multiple instances of this function."]

