const require = require('require');
const sinon = require('sinon');
const { performance } = require('perf_hooks');

// Simulated external test management system integration
const reportTestResult = async (testName, status, duration) => {
  // Placeholder for reporting logic to an external system
  console.log(`Reporting ${status} result for ${testName}: Duration - ${duration}ms`);
};

async function runTests(moduleName, tests, config = {}) {
  const defaultConfig = {
    retries: 1,
    timeout: 5000,
    logLevel: 'info', // can be 'none', 'minimal', 'info'
  };

  config = { ...defaultConfig, ...config };

  let module;
  try {
    module = require(moduleName);
  } catch (error) {
    console.error(`Error loading module ${moduleName}:`, error.message);
    return;
  }

  const log = (level, message) => {
    if (['info', 'minimal'].includes(config.logLevel)) {
      console.log(`[${new Date().toISOString()}] [${level.toUpperCase()}]: ${message}`);
    }
  };

  for (const test of tests) {
    let success = false;

    for (let attempt = 0; attempt <= config.retries; attempt++) {
      log('info', `Starting test: ${test.name}, Attempt: ${attempt + 1}`);

      const startTime = performance.now();
      let cleanupSpy;

      try {
        // Reset state and mock dependencies
        sinon.restore(); 
        cleanupSpy = sinon.spy(module, 'cleanup');

        await Promise.race([
          new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), config.timeout)),
          test.fn(module)
        ]);

        success = true;
      } catch (error) {
        log('warn', `Test failed: ${test.name} on attempt ${attempt + 1}, Error: ${error.message}`);
      } finally {
        if (cleanupSpy) cleanupSpy.restore();

        const endTime = performance.now();
        const duration = endTime - startTime;

        await reportTestResult(test.name, success ? 'Passed' : 'Failed', duration);

        log('info', `Completed test: ${test.name}, Duration: ${duration}ms`);

        if (success) break;
      }
    }

    if (!success) {
      console.error(`Test failed after ${config.retries + 1} attempts: ${test.name}`);
    }
  }

  log('info', 'All tests completed.');
}

