const cloudTermsRegex = /(?:aws|azure|gcp|lambda|s3|ec2|kubernetes|docker|vpc|rds|efs|cassandra|redis|jenkins|terraform|ansible|helm|istio|prometheus|grafana|consul|etcd|openstack|digitalocean|cloudflare|puppet)(?![a-zA-Z])/gi;
const stopWords = new Set(["and", "or", "but", "the", "is", "in", "at", "of", "on", "for", "with", "as"]);

// Cache to store previously computed results for synonym expansion
const synonymCache = new Map();

async function expandSynonyms(term) {
  if (synonymCache.has(term)) {
    return synonymCache.get(term);
  }

  // Mock API call to fetch synonyms, replace with actual API call logic
  const response = await fetch(`https://api.synonyms.com/${term}`);
  const data = await response.json();

  const expandedTerms = new Set([term, ...data.synonyms]);
  synonymCache.set(term, Array.from(expandedTerms));

  return Array.from(expandedTerms);
}

async function processDocuments(documents) {
  const termOccurrences = {};

  for (const doc of documents) {
    const { id, lines, type } = doc;

    for (let lineNumber = 0; lineNumber < lines.length; lineNumber++) {
      const line = lines[lineNumber].toLowerCase();
      let words = line.split(/\s+/);

      words.forEach(async (word) => {
        if (!stopWords.has(word)) {
          const expandedTerms = await expandSynonyms(word);

          for (const term of expandedTerms) {
            if (cloudTermsRegex.test(term)) {
              if (!termOccurrences[term]) {
                termOccurrences[term] = [];
              }

              const occurrence = termOccurrences[term].find(
                occ => occ.documentId === id
              );

              if (occurrence) {
                occurrence.frequency++;
                occurrence.lineNumbers.push(lineNumber + 1);
              } else {
                termOccurrences[term].push({
                  frequency: 1,
                  documentId: id,
                  lineNumbers: [lineNumber + 1],
                  documentType: type
                });
              }
            }
          }
        }
      });
    }
  }

  return termOccurrences;
}

module.exports = processDocuments;

