['```javascript
function renderFooterScripts(scripts, useCDN, cdnFallback) {
    if (!Array.isArray(scripts)) return '';

    const validTypes = ['text/javascript', 'module'];

    const createScriptTag = (src, async = false) => `<script src="${src}" ${async ? 'async' : ''}></script>`;

    let htmlOutput = [];

    for (const script of scripts) {
        if (
            typeof script !== 'object' ||
            !script.src ||
            typeof script.type !== 'string' ||
            !(script.async === true || script.async === false)
        ) {
            console.error('Invalid script object:', script);
            continue;
        }

        const { type, src, async } = script;

        if (!validTypes.includes(type)) {
            console.warn(`Unsupported script type "${type}" for script:`, script);
            continue;
        }

        let effectiveSrc = useCDN ? script.cdnUrl || src : src;

        const fetchScript = (src) => {
            return new Promise((resolve, reject) => {
                const img = document.createElement('img');
                img.onload = () => resolve(src);
                img.onerror = () => reject();
                img.src = `${src}&_=' + Math.random();`;
            });
        };

        if (useCDN && cdnFallback) {
            fetchScript(effectiveSrc)
                .then(() => htmlOutput.push(createScriptTag(effectiveSrc, async)))
                .catch(async () => {
                    await fetchScript(effectiveSrc).catch(() => {
                        console.error(`Failed to load from CDN: ${effectiveSrc}, falling back to local.`);
                        effectiveSrc = src;
                        htmlOutput.push(createScriptTag(effectiveSrc, async));
                    });
                });
        } else {
            htmlOutput.push(createScriptTag(effectiveSrc, async));
        }
    }

    return htmlOutput.join('');
}
