                self.evict_least_recently_used()

            checksum_valid = self.validate_checksum(bitmap_data)
            if not checksum_valid:
                bitmap_data = self.retry_download(bitmap_name)

            self.bitmap_cache[bitmap_name] = {
                'data': bitmap_data,
                'last_accessed': time.time(),
                'ref_count': 1
            }

    def evict_least_recently_used(self):
        lru_item = next(iter(self.bitmap_cache))
        del self.bitmap_cache[lru_item]

    def validate_checksum(self, data):
