                if response.status_code == 200:
                    return response.content
            except requests.RequestException as e:
                logging.warning(f"Download failed: {e}. Retrying...")
                time.sleep(2 ** attempt)  # Exponential backoff
        raise Exception("Failed to download bitmap after several attempts.")

    def integrate_image_processing(self, data):
        try:
            response = requests.post('https://image-service/optimization', files={'file': data})
            if response.status_code == 200:
                return response.content
        except requests.RequestException as e:
            logging.warning(f"Image processing service unavailable: {e}. Using local optimization.")

        return self.local_optimize(data)

    def local_optimize(self, data):
        # Dummy local optimization logic
        return data

    def start_background_cleaner(self):
        def background_task():
            while True:
                with self.lock:
                    current_time = time.time()
                    for name, info in list(self.bitmap_cache.items()):
                        if (current_time - info['last_accessed'] > 3600) or (info['ref_count'] == 0):
                            del self.bitmap_cache[name]

                time.sleep(BACKGROUND_CLEAR_INTERVAL)

        cleaner_thread = Thread(target=background_task, daemon=True)
        cleaner_thread.start()

