                name: {
                    'path': os.path.join(self.theme_dir, name),
                    'size': len(info['data']),
                    'creation_date': time.ctime(info['last_accessed'])
                } for name, info in self.bitmap_cache.items()
            }

        with open(file_path, 'w') as json_file:
            json.dump(cache_data, json_file)

def test_theme_cache_manager():
