        require_once $path;
    } else {
        // Handle file not found scenario, possibly logging the error
        echo "Autoloader not found in specified directory. Using fallback.\n";
        require_once __DIR__ . '/vendor/autoload.php'; // Fallback path
    }
}

// 3. Configuration File Loading and Runtime Switching
