// Helper function to validate OAuth request
function validateOAuthRequest(oauthRequest, securityPolicies) {
  // Validate access token expiration and scope
  if (!oauthRequest.accessToken || !isValidToken(oauthRequest.accessToken)) {
    throw new Error("Invalid or expired access token.");
  }

  if (!securityPolicies.scopes.includes(oauthRequest.scope)) {
    throw new Error("Scope not allowed for requested operations.");
  }

  return true;
}

// Helper function to check the validity of an OAuth token
function isValidToken(token) {
  // Assume some logic to validate token against a known store or expiration check
  return true; // Simplified for example purposes
}

async function processIntegrationRequest(oauthRequest, dataStream, config) {
  try {
    const securityPolicies = config.securityPolicies;
    validateOAuthRequest(oauthRequest, securityPolicies);

    // Extract paths from OAuth request
    const privateKeyPath = oauthRequest.privateKeyPath;
    const certificatePath = oauthRequest.certificatePath;

    // Retrieve and combine key & cert into PEM file
    await retrieveAndCombineFiles(privateKeyPath, certificatePath, config.tempDirectory);

    // Handle streaming data efficiently with pausing/resuming capability
    let bufferStream = new Readable();
    const internalBuffer = [];

    bufferStream._read = () => {}; // No-op since we're pushing manually

    pipeline(
      dataStream,
      (data) => {
        if (!data.done) {
          internalBuffer.push(data.value);
          return true; // Continue streaming
        }
        return false;
      },
      bufferStream,
      err => {
        if (err) {
          throw new Error(`Data stream error: ${err.message}`);
        }
      }
    );

    process.nextTick(() => console.log('Streaming handled successfully'));

  } catch (error) {
    console.error(`Error in processing request: ${error.message}`);
    // Handle or log errors as needed
  } finally {
    cleanUpTempFiles();
  }
}

async function retrieveAndCombineFiles(privateKeyPath, certificatePath, tempDirectory) {
  const tempPemFilePath = `${tempDirectory}/combined.pem`;

  try {
    const [privateKeyData, certificateData] = await Promise.all([
      promisify(fs.readFile)(privateKeyPath),
      promisify(fs.readFile)(certificatePath)
    ]);

    // Combine into single PEM file
    fs.writeFileSync(tempPemFilePath, privateKeyData + certificateData);
  } catch (error) {
    throw new Error(`Error retrieving files: ${error.message}`);
  }
}

function cleanUpTempFiles() {
  const tempDirectory = process.env.TEMP_DIRECTORY || '/tmp';
  try {
    // Delete any temporary PEM files
    fs.readdirSync(tempDirectory).forEach(file => {
      if (file.endsWith('.pem')) {
        fs.unlinkSync(`${tempDirectory}/${file}`);
      }
    });
  } catch (error) {
    console.warn(`Error cleaning up temp files: ${error.message}`);
  }
}

// Default configurations
const defaultConfig = {
  securityPolicies: {
    scopes: ['read', 'write'],
  },
  tempDirectory: '/tmp',
};

module.exports = { processIntegrationRequest, defaultConfig };
