function authenticateAndResolve($client_id, $client_secret, $redirect_uri, $auth_code, $hostname) {
    session_start();

    // Configure logging level based on environment
    $log_level = 'DEBUG'; // Change to 'ERROR' in production

    function logMessage($level, $message) {
        if ($GLOBALS['log_level'] === 'DEBUG' || $level === 'ERROR') {
            error_log("[$level] " . date('Y-m-d H:i:s') . ": $message");
        }
    }

    // OAuth 2.0 Token Request
    try {
        $token_url = 'https://example.com/oauth/token'; // Replace with actual token URL
        $response = file_get_contents($token_url, false, stream_context_create([
            'http' => [
                'method' => 'POST',
                'header' => "Content-Type: application/x-www-form-urlencoded\r\n",
                'content' => http_build_query([
                    'grant_type' => 'authorization_code',
                    'code' => $auth_code,
                    'client_id' => $client_id,
                    'client_secret' => $client_secret,
                    'redirect_uri' => $redirect_uri
                ])
            ]
        ]));

        if ($response === FALSE) {
            throw new Exception('OAuth 2.0 authentication failed');
        }

        $data = json_decode($response, true);
        if (!isset($data['access_token'])) {
            throw new Exception('Invalid OAuth token response');
        }

        // Securely store access token in session
        $_SESSION['access_token'] = $data['access_token'];
        logMessage('INFO', 'Access token stored securely in session');

    } catch (Exception $e) {
        logMessage('ERROR', $e->getMessage());
        return ['status' => 401, 'message' => 'Authentication failed'];
    }

    // DNS Resolution with Timeout and Rate Limiting
    $timeout = 2; // seconds
    $dns_result = dns_get_record($hostname, DNS_A | DNS_TXT);

    if ($dns_result === false) {
        logMessage('ERROR', "DNS resolution failed for hostname: $hostname");
        return ['status' => 404, 'message' => 'Hostname could not be resolved'];
    }

    // Simulate rate limiting (e.g., using Redis or in-memory store)
    static $last_request_time = null;
    $current_time = time();
    if ($last_request_time && ($current_time - $last_request_time < 1)) {
        usleep(500000); // Wait for 0.5 seconds
    }
    $last_request_time = $current_time;

    logMessage('INFO', "DNS resolution successful: $hostname -> " . implode(', ', array_column($dns_result, 'ip')));

    try {
        $ip_address = $dns_result[0]['ip'] ?? null;

        if (!$ip_address) {
            throw new Exception('IP address not found');
        }

        // Retrieve user information using the access token
        $user_info_url = "https://api.example.com/userinfo"; // Replace with actual URL
        $context_options = [
            'http' => [
                'method' => 'GET',
                'header' => "Authorization: Bearer {$_SESSION['access_token']}\r\n"
            ]
        ];

        $context = stream_context_create($context_options);
        $user_info_response = file_get_contents($user_info_url, false, $context);

        if ($user_info_response === FALSE) {
            throw new Exception('Failed to retrieve user information');
        }

        $user_data = json_decode($user_info_response, true);

        logMessage('INFO', 'User information retrieved successfully');

    } catch (Exception $e) {
        logMessage('ERROR', $e->getMessage());
        return ['status' => 503, 'message' => 'Service unavailable'];
    }

    return [
        'status' => 200,
        'user_info' => $user_data,
        'resolved_ip' => $ip_address
    ];
}
