<?php

class PasswordUpdateException extends Exception {}

class DAO {
    public function updateUserPassword($userId, $newPassword) {
        // Simulate updating user password in a database.
        return true; // Return false if the operation fails.
    }
}

class ExternalAuthService {
    public function validatePasswordPolicy($password) {
        // Simulate external authentication service call
        return strlen($password) >= 8 && preg_match('/[A-Z]/', $password)
            && preg_match('/[a-z]/', $password) && preg_match('/\d/', $password);
    }
}

function isPasswordStrong($password) {
    // Simple password strength validation logic
    return strlen($password) >= 8 && preg_match('/[A-Z]/', $password)
        && preg_match('/[a-z]/', $password) && preg_match('/\d/', $password);
}

function updatePasswordWithRetry($dao, $authService, $userId, $newPassword, $maxRetries = 3, $timeout = 2.0) {
    if (!isPasswordStrong($newPassword)) {
        throw new PasswordUpdateException('Password does not meet strength requirements.');
    }

    if (!$authService->validatePasswordPolicy($newPassword)) {
        throw new PasswordUpdateException('Password failed external validation policies.');
    }

    $attempt = 0;
    while ($attempt < $maxRetries) {
        try {
            $startTime = microtime(true);

            // Attempt to update the password
            if (!$dao->updateUserPassword($userId, $newPassword)) {
                throw new PasswordUpdateException('Failed to update password in the database.');
            }

            // Ensure timeout threshold is not exceeded
            if ((microtime(true) - $startTime) > $timeout) {
                throw new PasswordUpdateException('Operation exceeded timeout threshold.');
            }

            return true; // Success

        } catch (PasswordUpdateException $e) {
            error_log("Attempt {$attempt + 1}: " . $e->getMessage());

            if ($attempt == $maxRetries - 1) {
                throw new PasswordUpdateException("Failed to update password after {$maxRetries} attempts.");
            }

            // Implement backoff strategy for retries
            usleep(500000 * (2 ** $attempt)); // Exponential backoff
        }
    }
}

// Usage example
$dao = new DAO();
$authService = new ExternalAuthService();

try {
    updatePasswordWithRetry($dao, $authService, 12345, 'NewP@ssw0rd');
    echo "Password updated successfully.";
} catch (PasswordUpdateException $e) {
    error_log("Final failure: " . $e->getMessage());
}
