class DynamicOctree {
public:
    struct Node {
        bool isLeaf;
        std::vector<Node*> children;
        // Add additional data for leaf nodes as needed

        Node() : isLeaf(false), children(8, nullptr) {}
    };

    DynamicOctree(size_t featureSize, size_t maxDepth, size_t initialCapacity)
        : featureSize_(featureSize), maxDepth_(maxDepth), capacity_(initialCapacity),
          root_(new Node()), errorFlag_(false) {
        if (!initializeRootNode()) {
            errorFlag_ = true;
            std::cerr << "Error: Unable to initialize octree fully due to constraints." << std::endl;
        }
    }

    ~DynamicOctree() {
        clear(root_);
    }

    void addLeafNode(const int x, const int y, const int z) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (depth(root_, 0) < maxDepth_) {
            insertNode(root_, x, y, z, 0);
        } else {
            std::cerr << "Error: Maximum depth reached, cannot add more leaf nodes." << std::endl;
        }
    }

    void removeLeafNode(const int x, const int y, const int z) {
        std::lock_guard<std::mutex> lock(mutex_);
        // Implement removal logic
    }

    bool isInitialized() const {
        return !errorFlag_;
    }

private:
    size_t featureSize_, maxDepth_, capacity_;
    Node* root_;
    bool errorFlag_;
    mutable std::mutex mutex_;

    bool initializeRootNode() {
        try {
            // Try to allocate memory for initial nodes
            for (size_t i = 0; i < capacity_; ++i) {
                addLeafNode(0, 0, 0); // Example coordinates
            }
        } catch (...) {
            return false;
        }
        return true;
    }

    size_t depth(Node* node, size_t currentDepth) const {
        if (!node || node->isLeaf) return currentDepth;
        size_t maxChildDepth = 0;
        for (auto& child : node->children) {
            if (child) {
                size_t childDepth = depth(child, currentDepth + 1);
                maxChildDepth = std::max(maxChildDepth, childDepth);
            }
        }
        return maxChildDepth;
    }

    void insertNode(Node* node, int x, int y, int z, size_t currentDepth) {
        if (currentDepth == maxDepth_ || node->isLeaf) {
            // Convert to leaf and add data
            node->isLeaf = true;
            // Add additional logic for storing node data
        } else {
            int index = getChildIndex(x, y, z);
            if (!node->children[index]) {
                node->children[index] = new Node();
            }
            insertNode(node->children[index], x, y, z, currentDepth + 1);
        }
    }

    int getChildIndex(int x, int y, int z) const {
        return (x >= featureSize_ / 2 ? 4 : 0) | 
               (y >= featureSize_ / 2 ? 2 : 0) |
               (z >= featureSize_ / 2 ? 1 : 0);
    }

    void clear(Node* node) {
        if (!node) return;
        for (auto& child : node->children) {
            clear(child);
            delete child;
        }
    }
};

// Unit tests
void testDynamicOctree() {
    DynamicOctree octree(10, 5, 100);

    // Test initialization
    assert(octree.isInitialized());

    // Test adding leaf nodes
    octree.addLeafNode(1, 2, 3);
    octree.addLeafNode(4, 5, 6);

    // Test error on exceeding max depth
    for (int i = 0; i < 100; ++i) {
        octree.addLeafNode(i, i, i); // Add nodes until depth is reached
    }

    std::cout << "All tests passed!" << std::endl;
}

int main() {
    testDynamicOctree();
    return 0;
}
