#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define WINDOW_SIZE 1000 // Example window size
#define MAX_DATA_POINTS 10000

typedef struct {
    double values[WINDOW_SIZE];
    int index;
    double sum;
} SlidingWindow;

typedef struct {
    double mean;
    double stddev;
    int valid_calibration;
} CalibrationParams;

typedef struct {
    double throughput;
    double response_time;
    time_t last_update;
} PerformanceMetrics;

SlidingWindow* create_sliding_window() {
    SlidingWindow* window = (SlidingWindow*)malloc(sizeof(SlidingWindow));
    if (!window) return NULL;
    window->index = 0;
    window->sum = 0.0;
    for (int i = 0; i < WINDOW_SIZE; ++i) {
        window->values[i] = 0.0;
    }
    return window;
}

void update_sliding_window(SlidingWindow* window, double value) {
    if (!window) return;

    // Remove the oldest element from sum
    window->sum -= window->values[window->index];
    window->sum += value;

    // Add new value and increment index
    window->values[window->index] = value;
    window->index = (window->index + 1) % WINDOW_SIZE;
}

double calculate_mean(SlidingWindow* window) {
    if (!window || window->sum == 0) return 0.0;
    return window->sum / WINDOW_SIZE;
}

double calculate_stddev(SlidingWindow* window, double mean) {
    if (!window) return 0.0;

    double variance = 0.0;
    for (int i = 0; i < WINDOW_SIZE; ++i) {
        variance += pow(window->values[i] - mean, 2);
    }
    return sqrt(variance / WINDOW_SIZE);
}

double calculate_z_score(double value, double mean, double stddev) {
    if (stddev == 0) return 0.0;
    return (value - mean) / stddev;
}

void process_sensor_data(double* data_stream, size_t data_length, CalibrationParams calibration, PerformanceMetrics* metrics, int log_flag) {
    SlidingWindow* window = create_sliding_window();
    if (!window) {
        fprintf(stderr, "Failed to allocate sliding window\n");
        return;
    }

    double highest_anomaly_score = 0.0;
    time_t timestamp_of_anomaly = 0;

    for (size_t i = 0; i < data_length; ++i) {
        double value = data_stream[i];
        update_sliding_window(window, value);

        if (i >= WINDOW_SIZE - 1) { // Ensure we have enough data points
            double mean = calculate_mean(window);
            double stddev = calculate_stddev(window, mean);
            double z_score = calculate_z_score(value, mean, stddev);

            if (fabs(z_score) > calibration.stddev) {
                if (fabs(z_score) > highest_anomaly_score) {
                    highest_anomaly_score = fabs(z_score);
                    timestamp_of_anomaly = time(NULL);
                }
            }

            if (log_flag && z_score != 0.0) {
                printf("Data point: %f, Z-score: %f\n", value, z_score);
            }
        }
    }

    if (highest_anomaly_score > 0) {
        printf("Highest anomaly score: %f at timestamp: %ld\n", highest_anomaly_score, timestamp_of_anomaly);
    } else {
        printf("No significant anomalies detected.\n");
    }

    free(window);

    // Update performance metrics
    metrics->throughput = data_length / (double)(time(NULL) - metrics->last_update);
    metrics->response_time = (double)data_length / metrics->throughput;
    metrics->last_update = time(NULL);
}

int main() {
    double data_stream[MAX_DATA_POINTS];
    // Populate data_stream with sensor data
    CalibrationParams calibration = {0.0, 2.0, 1}; // Example values: mean=0.0, stddev=2.0, valid_calibration=1
    PerformanceMetrics metrics = {0.0, 0.0, time(NULL)};

    process_sensor_data(data_stream, MAX_DATA_POINTS, calibration, &metrics, 1);

    return 0;
}
```

This code implements a C function to process sensor data streams for anomaly detection using Z-score analysis with a sliding window approach. It maintains performance metrics and handles missing or stale calibration data gracefully. The logging framework is simulated by printing logs conditionally based on the `log_flag`.']

