class CombatCharacter {
public:
    enum AttackType { ATTACK_1 = 1, ATTACK_2 };

private:
    struct AttackRecord {
        AttackType type;
        std::time_t timestamp;

        AttackRecord(AttackType t, std::time_t ts) : type(t), timestamp(ts) {}
    };

    static const int MAX_ATTACKS_PER_MINUTE = 3;
    static const int COOLDOWN_ATTACK_1_SECONDS = 5; // Example cooldown period
    static const int COOLDOWN_ATTACK_2_SECONDS = 10;

    std::vector<AttackRecord> attackHistory;
    std::mutex mutex;
    std::chrono::steady_clock::time_point lastAttackTimes[2] = {std::chrono::steady_clock::now(), std::chrono::steady_clock::now()};
    int attacksThisMinute = 0;
    std::time_t startOfCurrentMinute;

    void logMessage(const std::string& message) {
        // Logging mechanism, e.g., to console or file
        std::cout << message << std::endl;
    }

    bool isAttackOnCooldown(AttackType attackType) {
        auto now = std::chrono::steady_clock::now();
        int cooldownPeriod = (attackType == ATTACK_1) ? COOLDOWN_ATTACK_1_SECONDS : COOLDOWN_ATTACK_2_SECONDS;

        if (std::chrono::duration_cast<std::chrono::seconds>(now - lastAttackTimes[attackType - 1]).count() < cooldownPeriod) {
            return true;
        }
        return false;
    }

    bool canPerformAttack() {
        auto now = std::time(nullptr);
        if (now >= startOfCurrentMinute + 60) {
            attacksThisMinute = 0;
            startOfCurrentMinute = now;
        }
        return attacksThisMinute < MAX_ATTACKS_PER_MINUTE;
    }

    void triggerExternalDependencies(AttackType attackType) {
        // Handle animations and sound effects
        // Fallback mechanism in case of failure or delay
        bool success = tryLoadAssets(attackType);
        if (!success) {
            logMessage("Failed to load assets for attack. Using fallback.");
        }
    }

    bool tryLoadAssets(AttackType attackType) {
        // Simulate loading resources, return false on failure
        std::this_thread::sleep_for(std::chrono::milliseconds(50)); // Simulated delay
        return true; // Assume success for this example
    }

public:
    CombatCharacter() : startOfCurrentMinute(std::time(nullptr)) {}

    void performAttack(AttackType attackType) {
        std::lock_guard<std::mutex> lock(mutex);
        auto now = std::chrono::steady_clock::now();

        if (isAttackOnCooldown(attackType)) {
            logMessage("Character is on cooldown.");
            return;
        }

        if (!canPerformAttack()) {
            logMessage("Cannot perform more than 3 attacks per minute.");
            return;
        }

        triggerExternalDependencies(attackType);

        lastAttackTimes[attackType - 1] = now;
        attackHistory.emplace_back(attackType, std::time(nullptr));
        ++attacksThisMinute;
    }

    const std::vector<AttackRecord>& getAttackRecords() {
        std::lock_guard<std::mutex> lock(mutex);
        return attackHistory;
    }
};

int main() {
    CombatCharacter character;

    // Simulate attacks
    character.performAttack(CombatCharacter::ATTACK_1);
    std::this_thread::sleep_for(std::chrono::seconds(3));
    character.performAttack(CombatCharacter::ATTACK_2);

    auto records = character.getAttackRecords();
    for (const auto& record : records) {
        std::cout << "Attack Type: " << record.type << ", Timestamp: " << std::ctime(&record.timestamp);
    }

    return 0;
}
