using System;
using System.Collections.Generic;
using System.Xml.Serialization;
using System.IO;
using System.Linq;

[XmlRoot("DynamicRangeValueGenerator")]
public class DynamicRangeValueGenerator
{
    private List<RangeConfig> rangeConfigs = new List<RangeConfig>();

    public void AddRange<T>(T start, T end, bool inclusiveStart, bool inclusiveEnd, double probabilityDistribution)
    {
        if (start is int && end is int)
        {
            rangeConfigs.Add(new RangeConfig(start, end, inclusiveStart, inclusiveEnd, typeof(int), probabilityDistribution));
        }
        else if (start is float && end is float)
        {
            rangeConfigs.Add(new RangeConfig(start, end, inclusiveStart, inclusiveEnd, typeof(float), probabilityDistribution));
        }
    }

    public T GenerateRandomValue<T>(string rangeIdentifier) where T : struct
    {
        var config = rangeConfigs.FirstOrDefault(c => c.Identifier == rangeIdentifier && c.DataType == typeof(T));
        if (config == null)
            throw new InvalidOperationException("Range configuration not found.");

        Random rand = new Random();
        double probability = config.ProbabilityDistribution;

        return GenerateRandom<T>(rand, config.Start, config.End, config.InclusiveStart, config.InclusiveEnd, probability);
    }

    private T GenerateRandom<T>(Random rand, object start, object end, bool inclusiveStart, bool inclusiveEnd, double probability) where T : struct
    {
        if (typeof(T) == typeof(int))
        {
            int min = Convert.ToInt32(start);
            int max = Convert.ToInt32(end);

            // Adjusting for inclusivity/exclusivity
            if (!inclusiveStart) min++;
            if (inclusiveEnd) max++;

            return (T)(object)SkewDistribution(rand.NextDouble(), min, max, probability);
        }
        else if (typeof(T) == typeof(float))
        {
            float minValue = Convert.ToSingle(start);
            float maxValue = Convert.ToSingle(end);

            // Adjusting for inclusivity/exclusivity
            if (!inclusiveStart) minValue += 0.0001f;
            if (inclusiveEnd) maxValue -= 0.0001f;

            return (T)(object)SkewDistribution(rand.NextDouble(), minValue, maxValue, probability);
        }

        throw new InvalidOperationException("Unsupported data type.");
    }

    private int SkewDistribution(double randValue, int min, int max, double probability)
    {
        // Simple linear skew: higher probability towards start or end based on probability value
        double range = max - min;
        return (int)(min + Math.Pow(randValue * probability, 2) * range);
    }

    private float SkewDistribution(double randValue, float minValue, float maxValue, double probability)
    {
        // Simple linear skew: higher probability towards start or end based on probability value
        float range = maxValue - minValue;
        return (float)(minValue + Math.Pow(randValue * probability, 2) * range);
    }

    public void SaveConfiguration(string filePath)
    {
        XmlSerializer serializer = new XmlSerializer(typeof(List<RangeConfig>));
        using (StreamWriter writer = new StreamWriter(filePath))
        {
            serializer.Serialize(writer, rangeConfigs);
        }
    }

    public void LoadConfiguration(string filePath)
    {
        XmlSerializer serializer = new XmlSerializer(typeof(List<RangeConfig>));
        using (StreamReader reader = new StreamReader(filePath))
        {
            rangeConfigs = (List<RangeConfig>)serializer.Deserialize(reader);
        }
    }

    public override string ToString()
    {
        return string.Join(Environment.NewLine, rangeConfigs.Select(c => c.ToString()));
    }
}

[XmlRoot("RangeConfig")]
public class RangeConfig
{
    [XmlAttribute]
    public string Identifier { get; set; } = Guid.NewGuid().ToString();

    [XmlElement("Start")]
    public object Start { get; set; }

    [XmlElement("End")]
    public object End { get; set; }

    [XmlElement("InclusiveStart")]
    public bool InclusiveStart { get; set; }

    [XmlElement("InclusiveEnd")]
    public bool InclusiveEnd { get; set; }

    [XmlIgnore]
    private Type dataType;

    [XmlElement("DataType")]
    public string DataType
    {
        get => dataType?.FullName;
        set => dataType = Type.GetType(value);
    }

    [XmlElement("ProbabilityDistribution")]
    public double ProbabilityDistribution { get; set; } = 1.0;

    public RangeConfig() { }

    public RangeConfig(object start, object end, bool inclusiveStart, bool inclusiveEnd, Type dataType, double probability)
    {
        Start = start;
        End = end;
        InclusiveStart = inclusiveStart;
        InclusiveEnd = inclusiveEnd;
        this.dataType = dataType;
        ProbabilityDistribution = probability;
    }

    public override string ToString()
    {
        return $"Range: {Start} to {End}, DataType: {dataType.Name}, " +
               $"Inclusive Start: {InclusiveStart}, Inclusive End: {InclusiveEnd}, " +
               $"Probability Distribution: {ProbabilityDistribution}";
    }
}
```

