```javascript
class AsyncReducer {
  constructor(retryConfig = { retries: 3, backoff: 100 }) {
    this.retryConfig = retryConfig;
  }

  async reduceAsync(dataSources, callback, initialValue, timeout = null) {
    let result = initialValue;

    for (const source of dataSources) {
      try {
        const value = await this.processSource(source, callback, timeout);
        if (typeof value === 'number') {
          result += value;
        }
      } catch (error) {
        console.error(`Error processing source: ${error.message}`);
      }
    }

    return result;
  }

  async processSource(source, callback, timeout) {
    let attempts = 0;

    while (attempts <= this.retryConfig.retries) {
      try {
        const result = await this.withTimeout(callback(source), timeout);
        if (typeof result === 'number') {
          return result;
        } else {
          throw new Error('Unexpected data type');
        }
      } catch (error) {
        attempts++;
        if (attempts > this.retryConfig.retries) {
          throw error;
        }
        await this.delay(this.calculateBackoff(attempts));
      }
    }
  }

  async withTimeout(promise, timeout) {
    const timeoutPromise = new Promise((_, reject) =>
      setTimeout(() => reject(new Error('Operation timed out')), timeout)
    );
    return Promise.race([promise, timeoutPromise]);
  }

  calculateBackoff(attempt) {
    return Math.min(this.retryConfig.backoff * (2 ** attempt), 5000);
  }

  delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

// Test cases
(async () => {
  const asyncReducer = new AsyncReducer({ retries: 3, backoff: 200 });

  const dataSources = [
    async () => 10,
    async () => { throw new Error('Network error'); },
    () => 5,
    async () => 20,
    async () => { throw new Error('Timeout error'); }
  ];

  try {
    const result = await asyncReducer.reduceAsync(dataSources, source => source(), 0, 1000);
    console.log(`Final Result: ${result}`);
  } catch (error) {
    console.error(error.message);
  }

  // Additional test cases for edge scenarios
  const mixedDataSources = [
    async () => 'string',
    async () => [1, 2, 3],
    async () => { throw new Error('Service unavailable'); },
    async () => 15
  ];

  try {
    const resultMixed = await asyncReducer.reduceAsync(mixedDataSources, source => source(), 0);
    console.log(`Final Result with Mixed Data: ${resultMixed}`);
  } catch (error) {
    console.error(error.message);
  }
})();
```

### Key Points:
- **Retry Logic**: Implemented with exponential backoff for handling service unavailability.
- **Timeout Handling**: Uses `Promise.race` to manage operation timeouts.
- **Error Handling**: Catches and logs errors, allowing the process to continue.
- **Graceful Degradation**: Skips non-numeric results without halting execution."]

