#define DEFAULT_THEME_DIR "/default/theme/dir"
#define BUFFER_SIZE 1024

// Function prototypes
void processFile(const char *filename);
char* readLine(FILE *file, size_t *len);
double calculateAverage(double num1, double num2);
void handlePngCache(const char *cacheRoot);

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *themeDir = getenv("THEME_DIR");
    if (!themeDir || strlen(themeDir) == 0) {
        themeDir = DEFAULT_THEME_DIR;
    }

    processFile(argv[1]);

    // Example of caching a PNG file
    handlePngCache("/cache/root/directory");

    return EXIT_SUCCESS;
}

void processFile(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    size_t len;
    char *line;

    while ((line = readLine(file, &len)) != NULL) {
        // Process each line to generate a CSV format
        char *lastComma = strrchr(line, ',');
        if (!lastComma) continue;  // Skip lines without commas

        double *num1 = NULL;
        double *num2 = NULL;

        char *token = strtok(lastComma + 1, ",");
        if (token) num1 = atof(token);

        token = strtok(NULL, ",");
        if (token) num2 = atof(token);

        if (num1 && num2) {
            double avg = calculateAverage(*num1, *num2);
            char newLine[BUFFER_SIZE];

            // Replace last comma with average
            snprintf(newLine, BUFFER_SIZE, "%.*s%.2f", 
                     (int)(lastComma - line), line, avg);

            printf("%s\n", newLine);
        }

        free(line);  // Free memory after processing the line
    }

    fclose(file);
}

char* readLine(FILE *file, size_t *len) {
    char *line = NULL;
    size_t capacity = BUFFER_SIZE;

    while (1) {
        if (*len >= capacity - 1) {
            capacity *= 2;
            char *new_line = realloc(line, capacity);
            if (!new_line) break; // Handle memory allocation failure
            line = new_line;
        }

        int c = fgetc(file);
        if (c == EOF || c == '\n') break;

        line[(*len)++] = (char)c;
    }

    if (*len > 0 && line[*len - 1] == '\n')
        line[--*len] = '\0'; // Remove newline character

    return *len ? line : NULL;
}

double calculateAverage(double num1, double num2) {
    return (num1 + num2) / 2.0;
}

void handlePngCache(const char *cacheRoot) {
    // Placeholder function to demonstrate handling of a PNG cache
    // This is where caching logic would be implemented.
    printf("Caching PNG from %s...\n", cacheRoot);
}
