#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>
#include "custom_text_processor.h"

typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
    char *error_message;
} ImageMetadata;

typedef struct {
    ImageMetadata metadata;
    char *processed_text;
    char *text_error_message;
} ProcessResult;

void logError(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

ImageMetadata parseTiffMetadata(TIFF *tiffFile) {
    ImageMetadata metadata = {0, 0, 0, NULL};

    if (TIFFGetField(tiffFile, TIFFTAG_BITSPERSAMPLE, &metadata.bits_per_sample)) {
        TIFFGetField(tiffFile, TIFFTAG_SAMPLESPERPIXEL, &metadata.samples_per_pixel);
        TIFFGetField(tiffFile, TIFFTAG_EXTRASAMPLES, NULL, &metadata.extra_samples);
    } else {
        metadata.error_message = "Failed to read image metadata.";
    }

    return metadata;
}

char *processText(const char *inputText) {
    // Assume custom_text_processor.h provides a function: process_custom_algorithm
    size_t bufferSize = strlen(inputText) + 1;
    char *processedBuffer = (char *)malloc(bufferSize);

    if (!processedBuffer) {
        logError("Failed to allocate memory for text processing.");
        return NULL;
    }

    int result = process_custom_algorithm(inputText, processedBuffer, &bufferSize);
    if (result != 0) {
        free(processedBuffer);
        return NULL;
    }

    return processedBuffer;
}

ProcessResult processImageAndProcessText(const char *tiffFilePath, const char *inputText) {
    ProcessResult result = {0};
    TIFF *tiffFile = TIFFOpen(tiffFilePath, "r");

    if (!tiffFile) {
        logError("Failed to open TIFF file.");
        return result;
    }

    result.metadata = parseTiffMetadata(tiffFile);

    if (result.metadata.error_message) {
        logError(result.metadata.error_message);
    } else {
        result.processed_text = processText(inputText);

        if (!result.processed_text) {
            result.text_error_message = "Failed to process text.";
        }
    }

    TIFFClose(tiffFile);

    return result;
}

int main() {
    const char *tiffFilePath = "example.tiff";
    const char *inputText = "Sample input text for processing.";

    ProcessResult result = processImageAndProcessText(tiffFilePath, inputText);

    if (result.metadata.error_message) {
        printf("Image metadata error: %s\n", result.metadata.error_message);
    } else {
        printf("Bits per Sample: %d\n", result.metadata.bits_per_sample);
        printf("Samples per Pixel: %d\n", result.metadata.samples_per_pixel);
        printf("Extra Samples: %d\n", result.metadata.extra_samples);

        if (result.processed_text) {
            printf("Processed Text: %s\n", result.processed_text);
            free(result.processed_text);
        } else {
            printf("Text processing error: %s\n", result.text_error_message);
        }
    }

    return 0;
}
