int is_valid_filename(const char *filename) {
    // Check for illegal characters: For example, using a simple set of invalid chars.
    const char *invalid_chars = "/\\?%*:|\"<>";

    while (*filename) {
        if (strchr(invalid_chars, *filename) || !isprint(*filename)) {
            return 0;
        }
        filename++;
    }

    // Check for excessive directory components
    int component_count = 1; // starts with at least one component
    while ((filename = strchr(filename, '/')) != NULL || (filename = strchr(filename, '\\'))) {
        component_count++;
        if (component_count > 10) { // Arbitrary limit to prevent path traversal issues
            return 0;
        }
    }

    return 1;
}

char *process_filename(const char *input_filename) {
    if (!input_filename || strlen(input_filename) >= MAX_FILENAME_LENGTH) {
        return strdup("");
    }

    if (!is_valid_filename(input_filename)) {
        return strdup("");
    }

    size_t len = strlen(input_filename);
    const char *base_name_end = strrchr(input_filename, '/');
    base_name_end = base_name_end ? base_name_end + 1 : input_filename;

    size_t base_len = strlen(base_name_end);
    if (base_len == 0) {
        return strdup("");
    }

    char *file_type;
    switch (tolower(base_name_end[0])) {
        case 'a': file_type = "txt"; break;
        case 'b': file_type = "bin"; break;
        // Add more cases as needed
        default: file_type = "dat";
    }

    size_t new_ext_len = strlen(file_type) + 1; // plus dot

    char *new_filename = (char *)malloc(MAX_TOTAL_LENGTH);
    if (!new_filename) {
        return strdup("");
    }

    snprintf(new_filename, MAX_TOTAL_LENGTH, "%.*s.", base_len - new_ext_len, base_name_end);

    char *dot_position = strrchr(input_filename, '.');
    dot_position = dot_position ? dot_position + 1 : input_filename + len;

    if (strlen(dot_position) > base_len) {
        snprintf(new_filename + strlen(new_filename), MAX_TOTAL_LENGTH - strlen(new_filename),
                 "%.*s.%s", base_len - new_ext_len, base_name_end, file_type);
    } else {
        snprintf(new_filename + strlen(new_filename), MAX_TOTAL_LENGTH - strlen(new_filename),
                 "%s%s", dot_position, file_type);
    }

    return new_filename;
}

// Example usage
int main() {
    const char *filename = "example/afile.txt";
    char *new_filename = process_filename(filename);

    if (strlen(new_filename) > 0) {
        printf("Processed filename: %s\n", new_filename);
    } else {
        printf("Invalid filename.\n");
    }

    free(new_filename);
    return 0;
}
