#include <openssl/rand.h>
#include <openssl/kdf.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define constants for AES-256-CBC
#define AES_KEY_LENGTH 32
#define IV_LENGTH 16

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[AES_KEY_LENGTH];
} CipherContext;

CipherContext* initialize_aes_256_cbc_cipher(const char *password, int iterations) {
    CipherContext *cipher = NULL;
    cipher = (CipherContext *)malloc(sizeof(CipherContext));
    if (!cipher) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Derive key using PBKDF2 with SHA-256
    unsigned char salt[16];
    if (1 != RAND_bytes(salt, sizeof(salt))) {
        fprintf(stderr, "Failed to generate random salt\n");
        free(cipher);
        return NULL;
    }

    int key_len = AES_KEY_LENGTH;
    if (1 != PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt),
                               iterations, EVP_sha256(), key_len, cipher->key)) {
        fprintf(stderr, "Failed to derive encryption key\n");
        free(cipher);
        return NULL;
    }

    // Initialize the AES-256-CBC context
    if (!(cipher->ctx = EVP_CIPHER_CTX_new())) {
        fprintf(stderr, "Failed to create cipher context\n");
        free(cipher);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, NULL)) {
        fprintf(stderr, "Failed to initialize encryption context\n");
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
        return NULL;
    }

    return cipher;
}

void cleanup_cipher_context(CipherContext *cipher) {
    if (cipher) {
        if (cipher->ctx) {
            EVP_CIPHER_CTX_free(cipher->ctx);
        }
        free(cipher);
    }
}

