static ThemeCacheEntry theme_cache[THEME_CACHE_SIZE];
static jstring default_theme_dir = NULL;

void initialize_default_theme_directory(JNIEnv *env, const char *default_path) {
    if (!default_theme_dir) {
        jclass stringClass = (*env)->FindClass(env, "java/lang/String");
        default_theme_dir = (*env)->NewStringUTF(env, default_path);
    }
