jobject get_cached_theme_bitmap(JNIEnv *env, jobject asset_manager, const char *file_name) {
    for (int i = 0; i < THEME_CACHE_SIZE; ++i) {
        if (theme_cache[i].bitmap && !theme_cache[i].in_use) {
            theme_cache[i].in_use = 1;
            return theme_cache[i].bitmap;
        }
    }

    // Load new bitmap from cache root directory
    jobject bitmap = load_bitmap_from_asset_manager(env, asset_manager, file_name);
    if (bitmap) {
        for (int i = 0; i < THEME_CACHE_SIZE; ++i) {
            if (!theme_cache[i].in_use) {
                theme_cache[i].bitmap = bitmap;
                theme_cache[i].in_use = 1;
                return bitmap;
            }
        }

        // If cache is full, recycle the least recently used (LRU) entry
        jobject lru_bitmap = theme_cache[0].bitmap;
        for (int i = 1; i < THEME_CACHE_SIZE; ++i) {
            if (!theme_cache[i].in_use && !theme_cache[lru_bitmap].in_use) {
                lru_bitmap = theme_cache[i].bitmap;
            }
        }

        (*env)->DeleteLocalRef(env, lru_bitmap);
        theme_cache[0].bitmap = bitmap;
    }

    return NULL;
}

void recycle_theme_bitmap(JNIEnv *env, jobject bitmap) {
    for (int i = 0; i < THEME_CACHE_SIZE; ++i) {
        if (theme_cache[i].bitmap == bitmap) {
            theme_cache[i].in_use = 0;
            (*env)->DeleteLocalRef(env, bitmap);
            break;
        }
    }
}

