            printf("Error: File size exceeds limit.\n");
        }
        pthread_mutex_unlock(&mutex);
        return 1;
    }

    void *deserializedObject = NULL;
    DeserializationStatus deserializationResult = deserializeObject(byteArray, byteArraySize, &deserializedObject);
    if (deserializationResult != DESERIALIZATION_SUCCESS) {
        if (deserializationResult == CLASS_NOT_FOUND) {
            printf("Warning: Class not found during deserialization.\n");
        } else if (deserializationResult == MEMORY_LIMIT_EXCEEDED) {
            printf("Error: Memory limit exceeded during deserialization.\n");
        } else {
            printf("Error: Deserialization failed.\n");
        }
    }

    pthread_mutex_unlock(&mutex);

    free(deserializedObject);
    return 0;
