#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>

#define MAX_COMMANDS 100

typedef struct {
    pid_t *pids;
    int count;
} ProcessGroup;

ProcessGroup processGroups[MAX_COMMANDS];
int groupCount = 0;

void handle_sigchld(int sig) {
    pid_t pid;
    int status;

    while ((pid = waitpid(-1, &status, WNOHANG)) > 0) {
        for (int i = 0; i < groupCount; ++i) {
            for (int j = 0; j < processGroups[i].count; ++j) {
                if (processGroups[i].pids[j] == pid) {
                    processGroups[i].pids[j] = -1;
                    break;
                }
            }
        }
    }
}

void cleanup() {
    for (int i = 0; i < groupCount; ++i) {
        free(processGroups[i].pids);
    }
}

void execute_commands(char *commands[], int numCommands) {
    if (numCommands > MAX_COMMANDS) {
        fprintf(stderr, "Exceeded maximum number of commands.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < numCommands; ++i) {
        pid_t pid = fork();
        if (pid == -1) {
            perror("fork failed");
            cleanup();
            exit(EXIT_FAILURE);
        } else if (pid == 0) {
            // Child process
            execlp("/bin/sh", "sh", "-c", commands[i], NULL);
            perror("execlp failed");
            exit(EXIT_FAILURE);
        } else {
            // Parent process
            ProcessGroup *pg = &processGroups[groupCount++];
            pg->count = 0;
            pg->pids = malloc(numCommands * sizeof(pid_t));

            if (!pg->pids) {
                perror("malloc failed");
                cleanup();
                exit(EXIT_FAILURE);
            }

            while (pg->count < numCommands && processGroups[i].pids[pg->count] != -1) {
                pg->pids[pg->count++] = pid;
            }
        }
    }
}

void setup_signal_handlers() {
    struct sigaction sa;

    sa.sa_handler = handle_sigchld;
    sa.sa_flags = SA_RESTART | SA_NOCLDSTOP;
    if (sigaction(SIGCHLD, &sa, NULL) == -1) {
        perror("sigaction failed");
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <command> [<command>...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    setup_signal_handlers();

    execute_commands(&argv[1], argc - 1);

    // Wait for all processes to finish
    while (groupCount > 0) {
        pause(); // Wait for a signal
    }

    cleanup();
    printf("All commands executed.\n");
    return EXIT_SUCCESS;
}
```

### Justification of Design Choices:
- **Process Groups:** Managed using an array of `ProcessGroup` structures to dynamically handle multiple groups of processes.
- **Signal Handling:** Implemented with `sigaction` for `SIGCHLD`, ensuring the program can handle terminated child processes without blocking, allowing graceful cleanup.
- **Resource Management:** Memory allocated for process IDs is carefully managed and freed upon exit or error, preventing leaks.
- **Scalability:** Supports up to `MAX_COMMANDS`, which is defined as 100. This provides a balance between scalability and resource management.
- **Error Handling:** Robust mechanisms are in place to handle errors during `fork` and `execlp`, ensuring that resources are cleaned up properly.
- **Concurrency Management:** Uses non-blocking wait via `waitpid` with the `WNOHANG` option, allowing the parent process to remain responsive and manage multiple child processes efficiently.']

