            ValidateSiteName(siteName);
            int validatedPort = ValidatePort(portNumber);

            string siteDirectory = Path.Combine(_baseDirectory, siteName);
            if (!EnsureValidDirectoryPath(siteDirectory))
                throw new Exception("Invalid directory path.");

            if (ExistsInDirectoryStructure(siteDirectory))
                throw new InvalidOperationException("Site name must be unique.");

            await CreateWebsiteDirectoryAsync(siteDirectory, validatedPort);

            // Validate configuration standards
            bool isValidConfig = await ValidateConfigurationStandards(configUrl);
            if (!isValidConfig)
                throw new Exception("Invalid site configuration.");

            _logger.Log($"Added website {siteName} on port {validatedPort}.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error adding website");
            throw;
        }
