    private void ValidateSiteName(string siteName)
    {
        if (string.IsNullOrWhiteSpace(siteName) || !Regex.IsMatch(siteName, @"^\w+$"))
            throw new ArgumentException("Invalid site name.");
    }

    private int ValidatePort(string portNumber)
    {
        if (!int.TryParse(portNumber, out int port))
            throw new ArgumentException("Invalid port number.");

        if (port < 1 || port > MaxPortNumber)
            throw new ArgumentOutOfRangeException(nameof(port), "Port must be between 1 and 65535.");

