import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class BatchProcessingEngine {

    private static final Logger logger = Logger.getLogger(BatchProcessingEngine.class.getName());
    private ExecutorService executor;
    private int maxThreads;
    private Path inputDir, outputDir;

    public BatchProcessingEngine(int maxThreads, Path inputDir, Path outputDir) {
        this.maxThreads = maxThreads;
        this.inputDir = inputDir;
        this.outputDir = outputDir;
        setupLogger();
        configureExecutor(maxThreads);
    }

    private void setupLogger() {
        try {
            FileHandler fileHandler = new FileHandler("BatchProcessing.log", true);
            fileHandler.setFormatter(new SimpleFormatter());
            logger.addHandler(fileHandler);
            logger.setLevel(Level.ALL);
        } catch (IOException e) {
            System.err.println("Failed to initialize log handler: " + e.getMessage());
        }
    }

    private void configureExecutor(int maxThreads) {
        this.executor = Executors.newFixedThreadPool(maxThreads);
    }

    public void processFiles() {
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(inputDir)) {
            for (Path filePath : stream) {
                executor.submit(() -> {
                    ProcessBuilder pb = new ProcessBuilder("java", "TextProcessor", filePath.toString(), outputDir.toString())
                            .redirectErrorStream(true);
                    Process process;
                    try {
                        process = pb.start();
                        logProcessOutput(process);

                        int exitCode = process.waitFor();
                        if (exitCode != 0) {
                            logger.warning("Processing failed for: " + filePath);
                        }
                    } catch (IOException | InterruptedException e) {
                        logger.severe("Exception during processing of file: " + filePath + " - " + e.getMessage());
                    }
                });
            }
        } catch (IOException e) {
            logger.severe("Error reading input directory: " + e.getMessage());
        }
    }

    private void logProcessOutput(Process process) throws IOException, InterruptedException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                logger.info(line);
            }
        }
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    public static void main(String[] args) {
        // Configuration parameters
        int maxThreads = Runtime.getRuntime().availableProcessors();  // Example: adjust based on resources
        Path inputDir = Paths.get("input");
        Path outputDir = Paths.get("output");

        BatchProcessingEngine engine = new BatchProcessingEngine(maxThreads, inputDir, outputDir);
        engine.processFiles();
        engine.shutdown();
    }
}
```

