// Mock database function for checking user_id uniqueness
int is_user_id_unique(const char *user_id) {
    // Simulate database check with a simple condition for illustration purposes
    return strlen(user_id) > 0; // Assume all non-empty IDs are unique
}

// Function to validate email format (basic example)
int is_valid_email_format(const char *email) {
    const char *at = strchr(email, '@');
    if (!at || at == email || at + 1 >= email + strlen(email)) return 0;

    for (const char *p = email; p < at; ++p) {
        if (*p == '.' && (*(p + 1) == '.' || *(p - 1) == '.')) return 0;
    }

    const char *dot = strchr(at, '.');
    if (!dot || dot == at + 1 || dot >= email + strlen(email)) return 0;

    return 1;
}

// Function to process JSON payload
int update_user_profile(const char *json_payload) {
    json_error_t error;
    json_t *root = json_loads(json_payload, 0, &error);

    if (!root) {
        fprintf(stderr, "JSON parsing error: %s\n", error.text);
        return -1;
    }

    // Check for required fields
    const char *user_id = json_string_value(json_object_get(root, "user_id"));
    const char *name = json_string_value(json_object_get(root, "name"));
    const char *email = json_string_value(json_object_get(root, "email"));

    if (!user_id || !name || !email) {
        fprintf(stderr, "Missing required fields\n");
        json_decref(root);
        return -1;
    }

    // Validate user_id
    if (strlen(user_id) == 0 || strlen(user_id) > MAX_USER_ID_LENGTH) {
        fprintf(stderr, "Invalid user_id length\n");
        json_decref(root);
        return -1;
    }

    // Check uniqueness of user_id with retries for robustness
    int max_retries = 3;
    while (max_retries-- > 0) {
        if (!is_user_id_unique(user_id)) {
            fprintf(stderr, "user_id must be unique\n");
            json_decref(root);
            return -1;
        }
        break; // Exit loop on success
    }

    // Validate name length
    if (strlen(name) == 0 || strlen(name) > MAX_NAME_LENGTH) {
        fprintf(stderr, "Invalid name length\n");
        json_decref(root);
        return -1;
    }

    // Validate email format
    if (!is_valid_email_format(email)) {
        fprintf(stderr, "Invalid email format\n");
        json_decref(root);
        return -1;
    }

    // Optional: address validation
    const char *address = json_string_value(json_object_get(root, "address"));
    if (address && (strlen(address) == 0 || strlen(address) > MAX_ADDRESS_LENGTH)) {
        fprintf(stderr, "Invalid address length\n");
        json_decref(root);
        return -1;
    }

    // Optional: phone_number validation can be added here similarly

    // If all checks pass
    printf("User profile update successful for user_id %s\n", user_id);

    json_decref(root); // Free memory
    return 0; // Success
}

// Example usage of the function
int main() {
    const char *json_payload = "{\"user_id\": \"12345\", \"name\": \"John Doe\", \"email\": \"john.doe@example.com\"}";
    int result = update_user_profile(json_payload);

    if (result == 0) {
        printf("Profile updated successfully.\n");
    } else {
        printf("Failed to update profile.\n");
    }

    return 0;
}
```

