char* ProcessString(const char* input, size_t sizeLimit) 
{
    if (strlen(input) > sizeLimit)
    {
        return NULL;
    }

    size_t newSize = strlen(input) + 2; // original string + '/' + '\0'
    char* result = (char*)malloc(newSize);

    if (!result)
    {
        return NULL;
    }

    strcpy(result, input);
    strcat(result, "/");

    return result;
}
