function getElementList(rootElement, selector, performanceThreshold) {
    const results = [];
    let startTime = Date.now();

    function traverse(node) {
        if (node === null || node.nodeType !== Node.ELEMENT_NODE) return;

        // Check performance threshold
        if (Date.now() - startTime > performanceThreshold) {
            throw new Error("Performance threshold exceeded");
        }

        const matches = Array.from(node.matches ? [node] : []).filter(el => el.matches(selector));

        results.push(...matches);

        for (let child of node.children) {
            traverse(child);
        }
    }

    traverse(rootElement);

    return results;
}
