using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json.Linq;

public class MessageProcessor
{
    public enum ProcessingResult
    {
        Success,
        InvalidConfiguration,
        DecryptionFailed
    }

    public struct ProcessedMessageResult
    {
        public ProcessingResult ResultCode;
        public string Message;
    }

    public ProcessedMessageResult DecryptMessage(string base64EncodedMessage, string jsonConfig)
    {
        try
        {
            // Validate JSON configuration
            var config = JObject.Parse(jsonConfig);
            if (!config["TripleDESKey"]?.Type == JTokenType.String ||
                !config["InitializationVector"]?.Type == JTokenType.String ||
                config["TripleDESKey"].ToString().Length != 24 || 
                config["InitializationVector"].ToString().Length != 8)
            {
                Log("Invalid configuration received. Check key and IV lengths.");
                return new ProcessedMessageResult { ResultCode = ProcessingResult.InvalidConfiguration, Message = "Invalid configuration." };
            }

            // Extract the Base64-encoded message
            byte[] encryptedBytes;
            try
            {
                encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
            }
            catch (FormatException)
            {
                Log("Decryption failed: Invalid base64 string.");
                return new ProcessedMessageResult { ResultCode = ProcessingResult.DecryptionFailed, Message = "Invalid input format." };
            }

            // Decrypt the message
            using (var des = TripleDESCryptoServiceProvider.Create())
            {
                des.Key = Convert.FromBase64String(config["TripleDESKey"].ToString());
                des.IV = Convert.FromBase64String(config["InitializationVector"].ToString());
                des.Mode = CipherMode.CBC;
                des.Padding = PaddingMode.PKCS7;

                try
                {
                    using (var decryptor = des.CreateDecryptor(des.Key, des.IV))
                    using (var msDecrypt = new MemoryStream(encryptedBytes))
                    using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    using (var srDecrypt = new StreamReader(csDecrypt))
                    {
                        string decryptedMessage = srDecrypt.ReadToEnd();
                        return new ProcessedMessageResult { ResultCode = ProcessingResult.Success, Message = decryptedMessage };
                    }
                }
                catch
                {
                    Log("Decryption failed: An error occurred during the decryption process.");
                    return new ProcessedMessageResult { ResultCode = ProcessingResult.DecryptionFailed, Message = "An error occurred during processing." };
                }
            }
        }
        catch (Exception ex)
        {
            // General exception handling to prevent sensitive information leak
            Log("An unexpected error occurred: " + ex.Message);
            return new ProcessedMessageResult { ResultCode = ProcessingResult.DecryptionFailed, Message = "An error occurred during processing." };
        }
    }

    private void Log(string message)
    {
        // Logging implementation (e.g., to a file or monitoring service) goes here.
        Console.WriteLine($"[Log]: {message}");
    }
}
