using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public class FileProcessor
{
    private static readonly HashSet<string> ValidExtensions = new HashSet<string>(new[] { ".txt", ".log" }, StringComparer.OrdinalIgnoreCase);

    public async Task ProcessFilesAsync(IEnumerable<string> filePaths, int maxConcurrency)
    {
        var fileTasks = new List<Task>();
        using (var semaphore = new SemaphoreSlim(maxConcurrency))
        {
            foreach (var path in filePaths)
            {
                if (!IsValidFilePath(path) || !File.Exists(path)) continue;

                await semaphore.WaitAsync();

                fileTasks.Add(Task.Run(async () =>
                {
                    try
                    {
                        var md5Hash = await CalculateMd5Async(path);
                        Console.WriteLine($"MD5 for {path}: {md5Hash}");
                    }
                    catch (Exception ex)
                    {
                        Console.Error.WriteLine($"Error processing {path}: {ex.Message}");
                    }
                    finally
                    {
                        semaphore.Release();
                    }
                }));
            }

            await Task.WhenAll(fileTasks);
        }
    }

    private bool IsValidFilePath(string path)
    {
        return ValidExtensions.Any(ext => path.EndsWith(ext, StringComparison.OrdinalIgnoreCase));
    }

    private async Task<string> CalculateMd5Async(string filePath)
    {
        int retryCount = 0;
        const int maxRetries = 3;

        while (retryCount < maxRetries)
        {
            try
            {
                using (var md5 = MD5.Create())
                using (var stream = File.OpenRead(filePath))
                {
                    var hashBytes = await md5.ComputeHashAsync(stream);
                    return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
                }
            }
            catch (IOException) when (retryCount < maxRetries - 1)
            {
                retryCount++;
                Console.WriteLine($"Retry {retryCount} for file {filePath} due to IO exception.");
                await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, retryCount))); // Exponential backoff
            }
        }

        throw new IOException("Max retries reached. Could not compute MD5 hash.");
    }
}

// Usage
public class Program
{
    public static async Task Main(string[] args)
    {
        var fileProcessor = new FileProcessor();
        var filePaths = Directory.GetFiles("path/to/directory", "*.*"); // Sample directory path

        int maxConcurrency = Environment.ProcessorCount; // Adjust based on system resources and load
        await fileProcessor.ProcessFilesAsync(filePaths, maxConcurrency);
    }
}
