using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class AesCbcDecryptor
{
    private const int BlockSize = 128; // AES block size in bits
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly int _maxRetries;

    public AesCbcDecryptor(byte[] key, byte[] iv, int maxRetries = 3)
    {
        if (key == null || iv == null) throw new ArgumentNullException();
        if (key.Length != 16 && key.Length != 24 && key.Length != 32) // Key sizes: 128, 192, or 256 bits
            throw new ArgumentException("Invalid AES key size.");
        if (iv.Length != BlockSize / 8)
            throw new ArgumentException("Invalid IV length.");

        _key = key;
        _iv = iv;
        _maxRetries = maxRetries;
    }

    public async Task<byte[]> DecryptAsync(byte[] ciphertext, Func<Task<string>> fetchMetadataAsync, string expectedChecksum)
    {
        if (ciphertext == null) throw new ArgumentNullException(nameof(ciphertext));

        byte[] decryptedBytes;
        try
        {
            using var aesAlg = Aes.Create();
            aesAlg.Key = _key;
            aesAlg.IV = _iv;
            aesAlg.Mode = CipherMode.CBC;
            aesAlg.Padding = PaddingMode.PKCS7;

            using var decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            int blockSizeBytes = aesAlg.BlockSize / 8;
            using (var msOutput = new MemoryStream())
            {
                using (var csDecrypt = new CryptoStream(msOutput, decryptor, CryptoStreamMode.Write))
                {
                    for (int i = 0; i < ciphertext.Length; i += blockSizeBytes)
                    {
                        int chunkSize = Math.Min(blockSizeBytes, ciphertext.Length - i);
                        await csDecrypt.WriteAsync(ciphertext, i, chunkSize).ConfigureAwait(false);
                    }

                    csDecrypt.FlushFinalBlock();
                }

                decryptedBytes = msOutput.ToArray();
            }
        }
        catch (CryptographicException ex)
        {
            LogError(ex.Message); // Implement a logging mechanism
            throw;
        }

        string metadata = await RetryAsync(fetchMetadataAsync).ConfigureAwait(false);

        if (!ValidateChecksum(decryptedBytes, expectedChecksum) || !metadataIsValid(metadata))
        {
            LogError("Decryption or checksum validation failed.");
            throw new InvalidOperationException("Failed to decrypt and validate data.");
        }

        return decryptedBytes;
    }

    private async Task<string> RetryAsync(Func<Task<string>> operation)
    {
        for (int attempt = 0; attempt < _maxRetries; attempt++)
        {
            try
            {
                return await operation().ConfigureAwait(false);
            }
            catch (Exception ex) when (attempt < _maxRetries - 1)
            {
                LogError($"Attempt {attempt + 1} failed: {ex.Message}");
                await Task.Delay(1000 * (attempt + 1)); // Exponential backoff
            }
        }

        throw new TimeoutException("Operation failed after retries.");
    }

    private bool metadataIsValid(string metadata)
    {
        // Implement validation logic based on the external service's response structure.
        return !string.IsNullOrEmpty(metadata); // Placeholder for actual implementation
    }

    private static void LogError(string message)
    {
        Console.Error.WriteLine(message); // Replace with a robust logging system
    }

    private bool ValidateChecksum(byte[] data, string expectedChecksum)
    {
        using var sha256 = SHA256.Create();
        byte[] hashBytes = sha256.ComputeHash(data);
        string actualChecksum = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();

        return StringComparison.Ordinal.Equals(actualChecksum, expectedChecksum.ToLowerInvariant());
    }
}
