public class ConfigurationLoader
{
    private readonly string _filePath;
    private readonly IConfigurationService _configService;
    private ConfigurationData _cachedConfig;

    public ConfigurationLoader(string filePath, IConfigurationService configService)
    {
        _filePath = filePath;
        _configService = configService;
    }

    public async Task<ConfigurationData> LoadConfigurationAsync()
    {
        try
        {
            if (_cachedConfig != null)
                return _cachedConfig;

            if (File.Exists(_filePath))
            {
                using var stream = new FileStream(_filePath, FileMode.Open, FileAccess.Read);
                var formatter = new BinaryFormatter();
                var config = (ConfigurationData)formatter.Deserialize(stream);

                if (config.Version == GetCurrentVersion())
                    _cachedConfig = config;
                else
                    HandleIncompatibleVersion(config.Version);
            }
        }
        catch (IOException)
        {
            // Log the exception or handle file access errors here
        }
        catch (SerializationException)
        {
            // Handle deserialization issues, such as corrupted files
        }

        return await LoadDynamicConfigWithRetryAsync();
    }

    private int GetCurrentVersion()
    {
        return 1; // Current version of your configuration format
    }

    private void HandleIncompatibleVersion(int fileVersion)
    {
        // Implement logic to handle incompatible versions here, e.g., upgrade or notify user
    }

    private async Task<ConfigurationData> LoadDynamicConfigWithRetryAsync()
    {
        int retryCount = 3;
        for (int attempt = 0; attempt < retryCount; attempt++)
        {
            try
            {
                var dynamicConfig = await _configService.FetchDynamicConfigAsync();
                if (dynamicConfig != null && dynamicConfig.Version == GetCurrentVersion())
                    return dynamicConfig;

                HandleIncompatibleVersion(dynamicConfig?.Version ?? -1);
            }
            catch (Exception ex)
            {
                // Log or handle the exception from external service
                if (attempt < retryCount - 1)
                    await Task.Delay(1000); // Wait before retrying
                else
                    throw new Exception("Failed to load dynamic configuration.", ex);
            }
        }

        return null; // Or fallback to default config
    }

    public void SaveConfiguration(ConfigurationData config)
    {
        try
        {
            using var stream = new FileStream(_filePath, FileMode.Create, FileAccess.Write);
            var formatter = new BinaryFormatter();
            formatter.Serialize(stream, config);
            _cachedConfig = config;
        }
        catch (IOException)
        {
            // Handle file write errors here
        }
    }
}
