#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_array(size_t count) {
    if (count <= 0) return NULL;

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize each structure
    for (size_t i = 0; i < count; ++i) {
        array[i].CRC_INDICATION_REL8_TAG.RX_UE_INFORMATION_TAG = rand() % 100;
        array[i].CRC_INDICATION_REL8_TAG.RNTI = rand() % 1000;
        array[i].CRCFLAG = rand() % 2;
    }

    return array;
}

int* read_integers_and_find_largest(int *size) {
    if (!size) return NULL;

    int number;
    int largest = INT_MIN;
    size_t capacity = 10;
    size_t count = 0;

    // Allocate initial memory for integers
    int *numbers = (int*)malloc(capacity * sizeof(int));
    if (!numbers) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    while (scanf("%d", &number) == 1) {
        // Check for integer overflow/underflow conditions when adding new number
        if ((largest < INT_MAX && number > largest) || (largest == INT_MIN)) {
            largest = number;
        }

        if (count >= capacity) {
            capacity *= 2; // Double the capacity to handle more numbers
            int *temp = realloc(numbers, capacity * sizeof(int));
            if (!temp) {
                free(numbers);
                fprintf(stderr, "Memory reallocation failed\n");
                exit(EXIT_FAILURE);
            }
            numbers = temp;
        }

        numbers[count++] = number;
    }

    // Handle case where no valid integers were read
    if (count == 0) {
        free(numbers);
        return NULL;
    }

    *size = count; // Update the size to actual count of integers read
    return numbers;
}

void print_largest_integer(int* array, size_t size) {
    if (!array || size == 0) {
        printf("No valid integer input.\n");
        return;
    }

    int largest = INT_MIN;
    for (size_t i = 0; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

int main() {
    size_t nfa_count;
    printf("Enter the number of NFAPI_CRC_INDICATION_PDU_T structures to allocate: ");
    if (scanf("%zu", &nfa_count) != 1 || nfa_count <= 0) {
        fprintf(stderr, "Invalid input for structure count.\n");
        return EXIT_FAILURE;
    }

    // Allocate and initialize array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* nfa_array = allocate_and_initialize_array(nfa_count);

    // Handle integer reading and finding largest integer
    int num_size;
    int *integers = read_integers_and_find_largest(&num_size);

    if (integers) {
        print_largest_integer(integers, num_size);
        free(integers); // Free dynamically allocated memory for integers
    }

    free(nfa_array); // Free dynamically allocated memory for structures
    return EXIT_SUCCESS;
}
