namespace RandomUtils {

    class DataProcessor {
    public:
        std::mt19937 rng;

        DataProcessor(unsigned int seed) : rng(seed) {}

        ~DataProcessor() = default;

        int generateRandomInt(int min, int max) {
            std::uniform_int_distribution<int> dist(min, max);
            return dist(rng);
        }
    };

}

typedef struct record {
    int value;
    char* identifier;
} Record;

int processRequests(const std::vector<std::pair<int, int>>& requests,
                    const std::vector<long>& offsets,
                    const std::vector<int>& keys,
                    Record* records,
                    size_t numRecords,
                    int targetSum) {

    int count = 0;

    for (const auto& request : requests) {
        int start = request.first;
        int end = request.second;

        if (start < 0 || end >= numRecords || start > end)
            continue;

        int sum = 0;

        for (int i = start; i <= end; ++i) {
            sum += records[i].value;
        }

        if (sum >= targetSum) {
            count++;
        }
    }

    return count;
}

void initializeArraysAndRecords(std::vector<long>& offsets,
                                std::vector<int>& keys,
                                std::vector<Record>& records,
                                size_t numElements,
                                int minVal,
                                int maxVal,
                                unsigned int seed) {

    RandomUtils::DataProcessor processor(seed);

    offsets.resize(numElements);
    keys.resize(numElements);

    for (size_t i = 0; i < numElements; ++i) {
        offsets[i] = static_cast<long>(processor.generateRandomInt(1, 100));
        keys[i] = processor.generateRandomInt(1, 50);
        records.push_back({processor.generateRandomInt(minVal, maxVal), nullptr});

        // Allocate and initialize a unique identifier string for each record
        std::string idStr = "Record_" + std::to_string(i);
        records.back().identifier = new char[idStr.size() + 1];
        std::copy(idStr.begin(), idStr.end(), records.back().identifier);
        records.back().identifier[idStr.size()] = '\0';
    }
}

int main() {
    size_t numElements = 100000; // Example size, adjust as necessary
    int minVal = 10;
    int maxVal = 100;
    unsigned int seed = std::random_device{}();

    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<Record> records;

    initializeArraysAndRecords(offsets, keys, records, numElements, minVal, maxVal, seed);

    // Example requests: each pair represents a range of indices [start, end]
    std::vector<std::pair<int, int>> requests = {{0, 50000}, {25000, 75000}};

    int targetSum = 100000; // Example target sum

    int result = processRequests(requests, offsets, keys, records.data(), records.size(), targetSum);

    std::cout << "Number of ranges meeting or exceeding the target sum: " << result << std::endl;

    for (auto& record : records) {
        delete[] record.identifier;
    }

    return 0;
}
