#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 100
#define LOG_ERROR(message) printf("ERROR: %s\n", message)
#define LOG_WARNING(message) printf("WARNING: %s\n", message)

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;
int entry_count = 0;
const int max_entries = MAX_ENTRIES;

// Function to generate a random CRCFLAG
unsigned char generate_random_crc_flag() {
    return rand() % 2; // Returns either 0 or 1 randomly
}

// Check if RX_UE_INFORMATION_TAG is unique in the list
int is_unique_tag(int tag) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == tag) {
            return 0; // Duplicate found
        }
        current = current->next;
    }
    return 1; // Unique tag
}

// Add a new entry to the linked list
int add_entry(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (entry_count >= max_entries) {
        LOG_WARNING("Maximum number of entries reached.");
        return -1;
    }

    if (!is_unique_tag(pdu->RX_UE_INFORMATION_TAG)) {
        LOG_WARNING("Duplicate RX_UE_INFORMATION_TAG detected, skipping entry.");
        return -2;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        LOG_ERROR("Memory allocation failed for new node.");
        return -3;
    }

    new_node->data = *pdu;
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crc_flag();
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);
    if (head == NULL) {
        head = new_node;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    entry_count++;
    pthread_mutex_unlock(&list_mutex);

    return 0; // Success
}

// Thread function to periodically refresh the list from an external data source
void* refresh_list(void* arg) {
    while (1) {
        sleep(5); // Simulate delay for refreshing
        pthread_mutex_lock(&list_mutex);

        Node* current = head;
        while (current != NULL) {
            // Simulating fetching new data for the entry
            NFAPI_CRC_INDICATION_PDU_T updated_pdu;
            updated_pdu.RX_UE_INFORMATION_TAG = current->data.RX_UE_INFORMATION_TAG; 
            updated_pdu.RNTI = current->data.RNTI;
            updated_pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crc_flag();

            *current = (Node){ .data = updated_pdu, .next = current->next };
            current = current->next;
        }

        pthread_mutex_unlock(&list_mutex);
    }

    return NULL;
}

// Main function to demonstrate the list management
int main() {
    srand(time(NULL)); // Initialize random seed

    pthread_t refresh_thread;
    if (pthread_create(&refresh_thread, NULL, refresh_list, NULL) != 0) {
        LOG_ERROR("Failed to create refresh thread.");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 12345, .RNTI = 67890 };
    if (add_entry(&pdu) != 0) {
        // Handle errors
    }

    pthread_join(refresh_thread, NULL); // Join thread for cleanup in a real program

    return 0;
}
