use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::net::{ToSocketAddrs, TcpStream};
use std::sync::{Arc, Mutex};
use tokio::runtime::Runtime;
use tokio_rustls::TlsConnector;
use webpki_roots;

fn create_http_client(disable_cert_validation: bool) -> Result<reqwest::ClientBuilder, Box<dyn std::error::Error>> {
    let mut builder = reqwest::Client::builder();

    if disable_cert_validation {
        // Create a TLS connector that does not verify certificates
        let mut root_store = webpki_roots::TLS_SERVER_ROOTS;
        root_store.clear();

        let tls_connector = TlsConnector::from(Arc::new(root_store));
        builder.use_proxy(false).default_tls_client(tls_connector);
    }

    Ok(builder)
}

fn resolve_hostname(hostname: &str) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
    for addr in hostname.to_socket_addrs()? {
        if let Some(ip) = addr.ip() {
            return Ok(ip.octets().to_vec());
        }
    }

    Err("DNS resolution failed".into())
}

fn process_large_file(file_path: &str) -> io::Result<()> {
    let file = File::open(file_path)?;
    let reader = BufReader::new(file);

    for (index, line) in reader.lines().enumerate() {
        if let Ok(line_str) = line {
            let mut fields: Vec<String> = line_str.split(',').map(|s| s.trim().to_string()).collect();

            // Parse numerical fields and compute the average of the last two
            let nums: Result<Vec<f64>, _> = fields.iter()
                .filter_map(|f| f.parse::<f64>().ok())
                .collect();

            if let Ok(num_vec) = nums {
                if num_vec.len() >= 2 {
                    let avg = (num_vec[num_vec.len() - 1] + num_vec[num_vec.len() - 2]) / 2.0;
                    fields.push(avg.to_string());
                } else {
                    eprintln!("Line {}: Less than two numerical fields, cannot compute average.", index);
                    continue; // Skip to the next line
                }
            }

            let output_line = fields.join(", ");
            println!("{}", output_line);

        } else {
            eprintln!("Error reading line at index {}: {:?}", index, line.err());
        }
    }

    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Setup runtime for async operations
    let rt = Runtime::new()?;

    // Create HTTP client with certificate validation disabled
    let _client_builder = create_http_client(true)?;

    // Resolve hostname example
    if let Ok(ip) = resolve_hostname("example.com") {
        println!("Resolved IP: {:?}", ip);
    }

    // Process a large text file
    process_large_file("large_text_file.txt")?;

    // Execute additional async tasks as needed
    rt.block_on(async {
        // Example of concurrent task handling using tokio (if necessary)
    });

    Ok(())
}
