}

class UnionFind {
public:
    UnionFind(size_t size) : parent(size), rank(size, 0) {
        for (size_t i = 0; i < size; ++i) parent[i] = i;
    }

    int find(int u) {
        if (parent[u] != u)
            parent[u] = find(parent[u]);
        return parent[u];
    }

    void unite(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);

        if (rootU != rootV) {
            if (rank[rootU] > rank[rootV]) {
                parent[rootV] = rootU;
            } else if (rank[rootU] < rank[rootV]) {
                parent[rootU] = rootV;
            } else {
                parent[rootV] = rootU;
                ++rank[rootU];
            }
        }
    }

private:
    std::vector<int> parent;
    std::vector<int> rank;
};

size_t allocateAndPopulateNFAPIAPIArray(size_t array_size) {
    if (array_size == 0) return 0;

    NFAPI_CRC_INDICATION_PDU_T* array = nullptr;
    size_t allocated_count = 0;
    std::mutex mtx;

    auto start_time = std::chrono::high_resolution_clock::now();

    try {
        // Allocate memory for the structures
        array = new NFAPI_CRC_INDICATION_PDU_T[array_size];

        UnionFind uf(array_size);
        std::unordered_set<uint16_t> unique_rntis;
        int disjoint_pairs = 0;

        for (size_t i = 0; i < array_size; ++i) {
            auto allocation_start_time = std::chrono::high_resolution_clock::now();

            // Populate each structure
            array[i].rx_ue_info_tag = RX_UE_INFORMATION_TAG(); // Assume default constructor is sufficient

            uint16_t rnti;
            while (true) { // Ensure unique RNTI for disjoint set
                rnti = getRNTIFromDataSource();
                if (unique_rntis.find(rnti) == unique_rntis.end()) {
                    array[i].rnti = rnti;
                    unique_rntis.insert(rnti);
                    break;
                }
            }

            array[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

            // Record the RNTI in the union-find structure
            int rnti_index = static_cast<int>(unique_rntis.find(rnti) - unique_rntis.begin());
            uf.unite(static_cast<int>(allocated_count), rnti_index);

            ++allocated_count;

            auto allocation_end_time = std::chrono::high_resolution_clock::now();
            std::lock_guard<std::mutex> lock(mtx);
            std::cout << "Allocation and initialization of structure " 
                      << i + 1 << " took: "
                      << std::chrono::duration_cast<std::chrono::milliseconds>(allocation_end_time - allocation_start_time).count()
                      << " ms\n";
        }

        // Count disjoint pairs
        for (size_t i = 0; i < array_size; ++i) {
            if (uf.find(static_cast<int>(allocated_count)) != uf.find(i)) {
                ++disjoint_pairs;
            }
        }

    } catch (...) {
        std::cerr << "Memory allocation failed, releasing allocated resources.\n";
        delete[] array;
        array = nullptr;
        return 0; // Return zero count if there's a failure
    }

    auto end_time = std::chrono::high_resolution_clock::now();
    std::lock_guard<std::mutex> lock(mtx);
    std::cout << "Total time taken: "
              << std::chrono::duration_cast<std::chrono::milliseconds>(end_time - start_time).count()
              << " ms\n";

    return disjoint_pairs;
}

int main() {
    srand(static_cast<unsigned int>(time(nullptr))); // Seed random number generator
    size_t array_size = 10; // Example size

    size_t count_disjoint_pairs = allocateAndPopulateNFAPIAPIArray(array_size);
    std::cout << "Number of disjoint pairs: " << count_disjoint_pairs << "\n";

    return 0;
}
