int process_numbers(int fd, NumberList *list) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;
    size_t total_capacity = 0;

    while ((bytes_read = read(fd, buffer, BUFFER_SIZE - 1)) > 0) {
        buffer[bytes_read] = '\0';

        char *token = strtok(buffer, " \n");
        while (token != NULL) {
            double number;
            if (sscanf(token, "%lf", &number) == 1 && number > 0) {
                pthread_mutex_lock(&list->lock);

                // Ensure capacity and append
                if (list->count >= total_capacity) {
                    size_t new_capacity = total_capacity == 0 ? 10 : total_capacity * 2;
                    double *new_numbers = realloc(list->numbers, new_capacity * sizeof(double));
                    if (!new_numbers) {
                        pthread_mutex_unlock(&list->lock);
                        return -1; // Memory allocation error
                    }
                    list->numbers = new_numbers;
                    total_capacity = new_capacity;
                }

                list->numbers[list->count++] = number;
                pthread_mutex_unlock(&list->lock);
            } else {
                log_error("Invalid or non-positive number encountered");
            }
            token = strtok(NULL, " \n");
        }
    }

    return bytes_read < 0 ? -1 : 0; // Return error if read fails
}

