int executeCommandSequence(char **commands, int numCommands) {
    pid_t pid;
    int status;

    for (int i = 0; i < numCommands; i++) {
        int retries = 0;
        while (retries < MAX_RETRIES) {
            pid = fork();
            if (pid == -1) {
                logError("fork");
                return -1;
            } else if (pid == 0) { // Child process
                execvp(commands[i], &commands[i]);
                exit(EXIT_FAILURE); // If exec fails
            } else { // Parent process
                int wstatus;
                waitpid(pid, &wstatus, 0);
                if (WIFEXITED(wstatus)) {
                    status = WEXITSTATUS(wstatus);
                    if (status == 0) break; // Success, move to next command
                }
                retries++;
                logError("Command failed, retrying...");
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to execute command %d after %d attempts.\n", i + 1, MAX_RETRIES);
            return -1;
        }
    }
    return 0; // Success
}

void populatePduList(NFAPI_CRC_INDICATION_PDU_T *pdus, int count) {
    srand(time(NULL));
