    NFAPI_CRC_INDICATION_PDU_T pdus[pduCount];

    populatePduList(pdus, pduCount);

    char *commands[MAX_COMMANDS] = {NULL};
    int numCommands = 0;

    while (numCommands < MAX_COMMANDS && getEnvironmentVariable("COMMAND_%d", commands[numCommands])) {
        commands[++numCommands] = strdup(commands[numCommands - 1]);
    }

    if (executeCommandSequence(commands, numCommands) != 0) {
        fprintf(stderr, "Failed to execute command sequence.\n");
    }

    for (int i = 0; i < numCommands; i++) {
        free(commands[i]);
    }
}

char* getEnvironmentVariable(const char *nameFormat, char *valueBuffer) {
    int index;
    snprintf(nameFormat + strlen(nameFormat), sizeof(nameFormat) - strlen(nameFormat), "%d", &index);
    valueBuffer = getenv(nameFormat);
    return valueBuffer ? strdup(valueBuffer) : NULL;
}
