            throw new Exception("Requested length exceeds the available character set size.");
        }

        $chars = str_split($charset);
        shuffle($chars);
        return implode('', array_slice($chars, 0, $length));
    }

    // Validate string with external service
    function validateWithExternalService($string) {
        $url = "https://example.com/validate?string=" . urlencode($string);

        for ($attempt = 0; $attempt < $GLOBALS['maxRetries']; $attempt++) {
            try {
                $response = file_get_contents($url);
                if ($response === FALSE) {
                    throw new Exception("Network error.");
                }

                $data = json_decode($response, true);
                if (json_last_error() !== JSON_ERROR_NONE || !$data['isValid']) {
                    throw new Exception("Invalid response or string not in whitelist.");
                }

                return true;
            } catch (Exception $e) {
                logMessage("Attempt " . ($attempt + 1) . ": " . $e->getMessage(), $GLOBALS['logFile']);
                if ($attempt < $GLOBALS['maxRetries'] - 1) {
                    sleep($GLOBALS['retryDelay']);
                }
            }
        }

        return false;
    }

    // Main function logic
    $randomString = '';
    do {
        try {
            $randomString = generateRandomString($length, $charset);
            if (!validateWithExternalService($randomString)) {
                throw new Exception("Validation failed after maximum retries.");
            }
        } catch (Exception $e) {
            logMessage($e->getMessage(), $GLOBALS['logFile']);
            // Retry generating a new string
        }
    } while (!$randomString);

    // Hash the given password
    if ($passwordToHash === '') {
        throw new Exception("Password to hash cannot be empty.");
    }

    $hashedPassword = password_hash($passwordToHash, $hashAlgorithm);
    if ($hashedPassword === false) {
        logMessage("Failed to hash password.", $GLOBALS['logFile']);
        throw new Exception("Password hashing failed.");
    }

    return [
        'randomString' => $randomString,
        'hashedPassword' => $hashedPassword
    ];
}

?>
```

### Key Considerations:

1. **Retries and Logging**: The function includes retry logic for handling network failures or service unavailability, logging each attempt for audit purposes.

2. **Character Set Flexibility**: Supports customizable character sets, ensuring compatibility with international characters.

3. **Performance Optimization**: Uses `shuffle` to randomize the character set efficiently without repeating characters, balancing speed and uniqueness.

4. **Error Handling**: Gracefully handles errors from both string generation and external validation, logging them for auditing.

5. **Password Hashing**: Ensures secure password hashing using a specified algorithm, with error handling if hashing fails.

This code is designed to be robust against network issues and rate limits while maintaining performance under high request volumes.']

