using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Text.Json;
using System.Threading;

public class InvalidRangeException : Exception
{
    public InvalidRangeException(string message) : base(message) { }
}

public class ValueGenerator
{
    private readonly float minValueInclusive, maxValueInclusive, minValueExclusive, maxValueExclusive;
    private readonly object rangeLock = new object();

    private int intCount;
    private int floatCount;

    private ConcurrentQueue<int> intBuffer = new ConcurrentQueue<int>();
    private ConcurrentQueue<float> floatBuffer = new ConcurrentQueue<float>();

    public ValueGenerator(float minInclusive, float maxInclusive, bool inclusive)
    {
        if (minInclusive > maxInclusive) 
            throw new InvalidRangeException("Minimum value cannot be greater than maximum value.");

        minValueInclusive = minInclusive;
        maxValueInclusive = maxInclusive;

        if (!inclusive)
        {
            minValueExclusive = minInclusive + float.Epsilon;
            maxValueExclusive = maxInclusive - float.Epsilon;
        }
    }

    public int GenerateInt(bool inclusive = true)
    {
        lock (rangeLock)
        {
            Random rand = new Random();
            int result = rand.Next((int)minValueInclusive, (int)maxValueInclusive + 1);
            if (!inclusive && (result == minValueInclusive || result == maxValueInclusive))
                result = GenerateInt(inclusive); // Retry until valid

            Interlocked.Increment(ref intCount);

            if (intBuffer.Count < 100)
                intBuffer.Enqueue(result);

            return result;
        }
    }

    public float GenerateFloat(bool inclusive = true)
    {
        lock (rangeLock)
        {
            Random rand = new Random();
            float result = minValueInclusive + (float)rand.NextDouble() * (maxValueInclusive - minValueInclusive);

            if (!inclusive && (result <= minValueExclusive || result >= maxValueExclusive))
                return GenerateFloat(inclusive); // Retry until valid

            Interlocked.Increment(ref floatCount);

            if (floatBuffer.Count < 100)
                floatBuffer.Enqueue(result);

            return result;
        }
    }

    public bool ValidateValue(float value, bool inclusive = true)
    {
        lock (rangeLock)
        {
            if (!inclusive)
            {
                return value > minValueExclusive && value < maxValueExclusive;
            }
            else
            {
                return value >= minValueInclusive && value <= maxValueInclusive;
            }
        }
    }

    public void UpdateRange(float newMin, float newMax, bool inclusive = true)
    {
        lock (rangeLock)
        {
            if (newMin > newMax) 
                throw new InvalidRangeException("Minimum value cannot be greater than maximum value.");

            minValueInclusive = newMin;
            maxValueInclusive = newMax;

            if (!inclusive)
            {
                minValueExclusive = newMin + float.Epsilon;
                maxValueExclusive = newMax - float.Epsilon;
            }
        }
    }

    public override string ToString()
    {
        lock (rangeLock)
        {
            return $"Range: [{minValueInclusive}, {maxValueInclusive}], " +
                   $"Generated Ints: {intCount}, Floats: {floatCount}";
        }
    }

    public string SerializeState()
    {
        lock (rangeLock)
        {
            var state = new
            {
                RangeMin = minValueInclusive,
                RangeMax = maxValueInclusive,
                IntCount = intCount,
                FloatCount = floatCount,
                IntBuffer = intBuffer.ToArray(),
                FloatBuffer = floatBuffer.ToArray()
            };

            return JsonSerializer.Serialize(state);
        }
    }

    public void DeserializeState(string serializedState)
    {
        lock (rangeLock)
        {
            var state = JsonSerializer.Deserialize<Dictionary<string, object>>(serializedState);

            minValueInclusive = (float)state["RangeMin"];
            maxValueInclusive = (float)state["RangeMax"];

            intCount = (int)state["IntCount"];
            floatCount = (int)state["FloatCount"];

            foreach (var value in state["IntBuffer"])
                intBuffer.Enqueue((int)value);

            foreach (var value in state["FloatBuffer"])
                floatBuffer.Enqueue((float)value);
        }
    }
}
