typedef int (*DataFetcherFunc)(int*);

char* processInput(char* inputBuffer, int maxCapacity, int* elementCount, DataFetcherFunc dataFetcher) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    *elementCount = 0;
    char* buffer = (char*)malloc(sizeof(int));
    if (!buffer) return NULL;

    bool keepReading = true;
    while (keepReading && *elementCount < maxCapacity) {
        // Read from standard input
        int value;
        if (scanf("%d", &value) == 1) {
            pthread_mutex_lock(&lock);
            buffer = realloc(buffer, (*elementCount + 1) * sizeof(int));
            if (!buffer || (*elementCount + 1) >= maxCapacity) {
                keepReading = false;
                printf("Capacity exceeded\n");
                free(buffer);
                return NULL;
            }
            ((int*)buffer)[*elementCount] = value;
            (*elementCount)++;
            pthread_mutex_unlock(&lock);
        } else {
            // Attempt to fetch from external source
            int fetchedValue;
            if (dataFetcher(&fetchedValue) == 0 && fetchedValue != -1) { // Assuming -1 indicates failure
                pthread_mutex_lock(&lock);
                buffer = realloc(buffer, (*elementCount + 1) * sizeof(int));
                if (!buffer || (*elementCount + 1) >= maxCapacity) {
                    keepReading = false;
                    printf("Capacity exceeded\n");
                    free(buffer);
                    return NULL;
                }
                ((int*)buffer)[*elementCount] = fetchedValue;
                (*elementCount)++;
                pthread_mutex_unlock(&lock);
            } else {
                keepReading = false; // No more data
            }
        }
    }

    inputBuffer = buffer;
    pthread_mutex_destroy(&lock);
    return inputBuffer;
}

