#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

// Function to initialize AES-256-GCM with given password
EVP_CIPHER_CTX* init_aes_256_gcm(const char *password, const int password_len) {
    EVP_CIPHER_CTX *ctx = NULL;
    unsigned char salt[16];
    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    const int iterations = 100000; // Adjust based on performance/security trade-offs
    const int key_length = 32;     // AES-256 requires a 256-bit key

    // Generate random salt and IV
    if (!RAND_bytes(salt, sizeof(salt)) || !RAND_bytes(iv, EVP_AEAD_AES_256_GCM_TAG_LEN)) {
        return NULL;
    }

    // Derive the encryption key using PBKDF2
    if (PKCS5_PBKDF2_HMAC(password, password_len,
                          salt, sizeof(salt),
                          iterations, EVP_sha256(),
                          key_length, key) != 1) {
        return NULL;
    }

    // Initialize cipher context for AES-256-GCM
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set additional IV length for AES-GCM, which requires a longer nonce
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, sizeof(iv), NULL) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Example usage:
// EVP_CIPHER_CTX* cipher_ctx = init_aes_256_gcm("your-password", strlen("your-password"));
