        onFailure("Password is empty or NULL.");
        return ERROR_EMPTY_PASSWORD;
    }

    if (!module->connection || !module->connection->title || strlen(module->connection->title) == 0) {
        onFailure("Connection title is missing.");
        return ERROR_MISSING_TITLE;
    }

    if (!module->beforeTest) {
