#include <pthread.h>
#include <semaphore.h>

// Assuming these structures are defined elsewhere in the codebase
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Global semaphore for synchronization
sem_t global_semaphore;

int createAndPopulateNFACRCListWithSemaphore(int N, NFAPI_CRC_INDICATION_PDU_T **list) {
    // Initialize semaphore with initial value of N
    if (sem_init(&global_semaphore, 0, N) != 0) {
        return -1; // Semaphore initialization failed
    }

    *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        sem_destroy(&global_semaphore); // Cleanup semaphore on failure
        return -1; // Memory allocation failed
    }

    for (int i = 0; i < N; ++i) {
        sem_wait(&global_semaphore); // Wait for the semaphore

        // Populate the list with random values
        (*list)[i].crc_indication_rel8_tag.RX_UE_INFORMATION_TAG = rand() % 100;
        (*list)[i].crc_indication_rel8_tag.RNTI = rand() % 1000;
        (*list)[i].CRCFLAG = rand() % 2;

        sem_post(&global_semaphore); // Signal the semaphore
    }

    return 0; // Success
}

void cleanupNFACRCListWithSemaphore(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list != NULL) {
        free(list);
    }
    sem_destroy(&global_semaphore);
}
