#define MEMORY_LIMIT_MB 1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex and condition variable for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

void *generatePDUs(void *args) {
    long num_pdus = *(long *)args;
    size_t pdu_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t memory_limit_bytes = MEMORY_LIMIT_MB * 1024 * 1024;
    size_t current_memory_usage = 0;

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(pdu_size * num_pdus);
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (long i = 0; i < num_pdus; ++i) {
        pthread_mutex_lock(&mutex);

        if (current_memory_usage + pdu_size > memory_limit_bytes * 0.8) {
            printf("Warning: Memory usage exceeded 80%% of limit\n");
            break;
        }

        pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdus[i].RNTI = rand();
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 256;

        current_memory_usage += pdu_size;
        pthread_mutex_unlock(&mutex);
    }

    free(pdus);
    return NULL;
}

void executeCommand(const char *command, const char *env_settings, long timeout) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return;
    }

    if (pid == 0) { // Child process
        setenv("COMMAND_ENV", env_settings, 1);
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);

        perror("execl");
        exit(EXIT_FAILURE);
    } else { // Parent process
        int status;
        struct timespec ts = {.tv_sec = timeout, .tv_nsec = 0};

        if (pthread_timedjoin_np(pid, NULL, &ts) != 0) {
            printf("Command execution timed out\n");
            kill(pid, SIGKILL);
        } else {
            waitpid(pid, &status, 0);
            if (WIFEXITED(status)) {
                printf("Command exited with status %d\n", WEXITSTATUS(status));
            }
        }
    }
}

void logPerformanceMetrics(long num_pdus_generated, size_t total_memory_used, long command_duration) {
    // Log metrics
    printf("PDUs Generated: %ld\n", num_pdus_generated);
    printf("Total Memory Used: %zu bytes\n", total_memory_used);
    printf("Command Execution Duration: %ld seconds\n", command_duration);
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <num_pdus> <command> <timeout>\n", argv[0]);
        return EXIT_FAILURE;
    }

    long num_pdus = atol(argv[1]);
    const char *command = argv[2];
    long timeout = atol(argv[3]);

    pthread_t pdu_thread;
    pthread_create(&pdu_thread, NULL, generatePDUs, &num_pdus);
    pthread_join(pdu_thread, NULL);

    clock_t start_time = clock();
    executeCommand(command, "example_env_setting", timeout);
    clock_t end_time = clock();

    long command_duration = (end_time - start_time) / CLOCKS_PER_SEC;

    logPerformanceMetrics(num_pdus, MEMORY_LIMIT_MB * 1024 * 1024, command_duration);

    return EXIT_SUCCESS;
}
