int load_job_sequence(const char *config_file, JOB_STATUS_T **jobs, int *job_count) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        log_error("Failed to open config file.");
        return -1;
    }

    struct json_object *parsed_json;
    struct json_object *jobs_array;
    parsed_json = json_object_from_file(file);
    fclose(file);

    if (!parsed_json) {
        log_error("Failed to parse JSON configuration.");
        return -1;
    }

    json_object_object_get_ex(parsed_json, "jobs", &jobs_array);
    *job_count = json_object_array_length(jobs_array);

    *jobs = malloc(*job_count * sizeof(JOB_STATUS_T));
    for (int i = 0; i < *job_count; ++i) {
        struct json_object *job_obj = json_object_array_get_idx(jobs_array, i);
        JOB_STATUS_T job;
        job.job_id = json_object_get_int(json_object_object_get_ex(job_obj, "id", NULL));
        job.status = PENDING;
        job.error_message = strdup("");
        job.start_time = 0;
        job.end_time = 0;

        (*jobs)[i] = job;
    }

    json_object_put(parsed_json);
    return 0;
}

// Function to execute a single job
int execute_job(JOB_STATUS_T *job, DATA_TRANSFORM_REQUEST_T *request) {
    // Simulate job execution logic
    job->start_time = time(NULL);
    int success = transform_data(request);

    if (success == 0) {
        job->status = SUCCESS;
    } else {
        job->status = FAILED;
        strcpy(job->error_message, "Transformation failed.");
    }

    job->end_time = time(NULL);
    return success ? 0 : -1;
}

// Function to handle batch processing
void *processBatchOfDataTransformsAndExecuteJobs(void *arg) {
    DATA_TRANSFORM_REQUEST_T *requests = (DATA_TRANSFORM_REQUEST_T *)arg;
    int request_count = sizeof(requests) / sizeof(DATA_TRANSFORM_REQUEST_T);

    JOB_STATUS_T *jobs = NULL;
    int job_count = 0;

    if (load_job_sequence("config.json", &jobs, &job_count) != 0) {
        log_error("Error loading job sequence.");
        return NULL;
    }

    for (int i = 0; i < request_count; ++i) {
        DATA_TRANSFORM_REQUEST_T *request = &requests[i];

        // Populate valid transformation parameters
        if (!request->transformation_params) {
            // Example: Assign default params or fetch from some source
            request->transformation_params = strdup("default_params");
        }

        int retries = 0;
        while (retries < MAX_RETRIES) {
            for (int j = 0; j < job_count; ++j) {
                JOB_STATUS_T *job = &jobs[j];

                if (job->status == PENDING || job->status == FAILED) {
                    int result = execute_job(job, request);
                    if (result == 0) break;

                    log_error("Job failed. Retrying...");
                    retries++;
                }
            }

            if (retries >= MAX_RETRIES) {
                log_error("Max retries reached for request.");
                break; // Exit the retry loop
            }
        }
    }

    // Cleanup
    for (int i = 0; i < job_count; ++i) {
        free(jobs[i].error_message);
    }
    free(jobs);

    return NULL;
}

int main() {
    DATA_TRANSFORM_REQUEST_T batch_requests[5] = {
        {"input1", NULL, "output1"},
        {"input2", NULL, "output2"},
        {"input3", NULL, "output3"},
        {"input4", NULL, "output4"},
        {"input5", NULL, "output5"}
    };

    pthread_t thread;
    pthread_create(&thread, NULL, processBatchOfDataTransformsAndExecuteJobs, batch_requests);
    pthread_join(thread, NULL);

    return 0;
}
