void add_record(NFDataRecord** records, int* size, pthread_mutex_t* lock) {
    pthread_mutex_lock(lock);

    *size += 1;
    *records = realloc(*records, (*size) * sizeof(NFDataRecord));
    if (!*records) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    // Create a new record (with default ID handling)
    NFDataRecord new_record;
    new_record.id = rand();  // For demonstration; consider generating unique IDs
    (*records)[*size - 1] = new_record;

    sync_with_database(&(*records)[*size - 1], 1);

    pthread_mutex_unlock(lock);
}

// Function to retrieve an NFDataRecord by ID
NFDataRecord* get_record_by_id(NFDataRecord* records, int size, int id, pthread_mutex_t* lock) {
    pthread_mutex_lock(lock);

    for (int i = 0; i < size; i++) {
        if (records[i].id == id) {
            pthread_mutex_unlock(lock);
            return &records[i];
        }
    }

    pthread_mutex_unlock(lock);
    return NULL;
}

// Function to remove an NFDataRecord by ID
int remove_record_by_id(NFDataRecord** records, int* size, int id, pthread_mutex_t* lock) {
    pthread_mutex_lock(lock);

    for (int i = 0; i < *size; i++) {
        if ((*records)[i].id == id) {
            sync_with_database(&(*records)[i], 0);

            // Move the last element to fill the gap
            (*records)[i] = (*records)[*size - 1];

            *size -= 1;
            *records = realloc(*records, (*size) * sizeof(NFDataRecord));
            if (!*records && *size > 0) {
                perror("Failed to reallocate memory");
                exit(EXIT_FAILURE);
            }

            pthread_mutex_unlock(lock);
            return 1;  // Record found and removed
        }
    }

    pthread_mutex_unlock(lock);
    return 0;  // Record not found
}

// Example usage:
int main() {
    NFDataRecord* records = NULL;
    int size = 0;
    pthread_mutex_t lock;

    pthread_mutex_init(&lock, NULL);

    add_record(&records, &size, &lock);
    NFDataRecord* record = get_record_by_id(records, size, /* ID to find */, &lock);
    if (record) {
        // Use the found record
    }

    int removed = remove_record_by_id(&records, &size, /* ID to remove */, &lock);

    pthread_mutex_destroy(&lock);
    free(records);
    return 0;
}
