        tag_count++;

        manager->indication_list[i].RX_UE_INFORMATION_TAG = rx_tag;
        manager->indication_list[i].RNTI = rnti;

        int crc_flag = compute_crc_flag(rnti);
        if (crc_flag < 0) {
            free(manager->indication_list);
            callback(CRC_COMPUTATION_ERROR);
            return;
        }

        manager->indication_list[i].CRCFLAG = (unsigned char)crc_flag;
    }

    manager->list_size = num_structs;
    manager->allocated_size = num_structs * max_struct_size;

    // Asynchronous processing simulation
    if (callback) {
        callback(SUCCESS);
    }
}

void indication_callback(ErrorCode result) {
