            break;
        case CRC_COMPUTATION_ERROR:
            fprintf(stderr, "Error: CRC computation failed.\n");
            break;
        case WARN_MEMORY_LIMIT_EXCEEDED:
            printf("Warning: Memory limit exceeded, processing with reduced count.\n");
            break;
        default:
            fprintf(stderr, "Unknown error occurred.\n");
    }
}

