        return 0;
    }

    int current_sum = 0, count_meeting_target = 0;
    for (size_t i = start_idx; i <= end_idx; ++i) {
        current_sum += records[i].value;
        if (current_sum >= target_sum) {
            ++count_meeting_target;
        }
    }

    return count_meeting_target;
}

void free_resources(Record *records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].identifier);
    }
    free(records);
}

int main() {
    size_t num_records = 100;
    int min_value = 1, max_value = 100;

    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    init_random();

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].identifier = fetch_identifier(i, MAX_RETRIES);
        if (!records[i].identifier) {
            fprintf(stderr, "Skipping record %zu due to identifier fetch failure\n", i);
            continue;
        }
        // For simplicity, using index as offset reference
        records[i].offsetIndex = i;
    }

    size_t start_idx = 10, end_idx = 50;
    int target_sum = 500;

    int result = handle_request(start_idx, end_idx, target_sum, records, num_records);
    printf("Count of records meeting/exceeding target sum: %d\n", result);

    free_resources(records, num_records);

    return EXIT_SUCCESS;
}
```

### Key Components:
- **Record Structure**: Holds an integer value, a dynamic string identifier, and an offset index reference.
- **Random Initialization**: Initializes random values within the specified range for record values.
- **Fetch Identifiers**: Simulates fetching identifiers from an external source with retry logic for network failures.
- **Handle Requests**: Processes requests to calculate sums over specific ranges of records and returns count meeting target sum criteria.
- **Memory Management**: Ensures proper allocation, initialization, and deallocation of resources to prevent memory leaks.
- **Concurrency Consideration**: Although not implemented due to complexity in this sample, consider using threads or a thread pool for handling large datasets concurrently.

This implementation balances between functionality and simplicity while providing an extensible foundation for future enhancements.']

