#include <float.h>

void readFloatsAndCalculateAverage(FILE *logFile) {
    int limit, i = 0;
    double sum = 0.0, number;

    if (scanf("%d", &limit) != 1 || limit <= 0) {
        fprintf(logFile, "Invalid input for limit.\n");
        return;
    }

    float *array = NULL;
    array = realloc(array, sizeof(float) * limit);
    if (!array) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    while (i < limit && scanf("%lf", &number) == 1) {
        if ((sum > 0 && number > DBL_MAX - sum) || (sum < 0 && number < DBL_MIN - sum)) {
            fprintf(logFile, "Overflow detected during summation.\n");
            break;
        }

        array[i] = number;
        sum += number;
        i++;
    }

    if (i < limit) {
        printf("Warning: Not all numbers were processed. Processed %d out of %d.\n", i, limit);
        fprintf(logFile, "Not all numbers were processed. Processed %d out of %d.\n", i, limit);
    }

    double average = (i > 0) ? sum / i : 0;
    printf("Total elements processed: %d\n", i);
    printf("Running average: %.6f\n", average);

    fprintf(logFile, "Total elements processed: %d\n", i);
    fprintf(logFile, "Resource usage: Memory allocated for %d elements.\n", limit);

    free(array);
}

int main() {
    FILE *logFile = fopen("logfile.txt", "w");
    if (!logFile) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    readFloatsAndCalculateAverage(logFile);

    fclose(logFile);
    return 0;
}
