```c
#include <stdio.h>
#include <stdlib.h>
#include <mysql/mysql.h>

typedef struct {
    char name[100];
    char city[50];
    char address[200];
} EmployeeDetails;

void fetch_employee_details(MYSQL* conn, int supervisor_id) {
    MYSQL_STMT* stmt;
    MYSQL_BIND bind[3];
    unsigned long lengths[3] = {0};
    my_bool is_null[3] = {0};

    const char* query = "SELECT name, city, address FROM Employees WHERE supervisor_id = ?";
    stmt = mysql_stmt_init(conn);
    if (!stmt) {
        fprintf(stderr, "mysql_stmt_init(), out of memory\n");
        return;
    }

    if (mysql_stmt_prepare(stmt, query, strlen(query))) {
        fprintf(stderr, "mysql_stmt_prepare(), %s\n", mysql_stmt_error(stmt));
        return;
    }

    memset(bind, 0, sizeof(bind));

    bind[0].buffer_type = MYSQL_TYPE_LONG;
    bind[0].buffer = (char*)&supervisor_id;

    if (mysql_stmt_bind_param(stmt, bind)) {
        fprintf(stderr, "mysql_stmt_bind_param(), %s\n", mysql_stmt_error(stmt));
        return;
    }

    if (mysql_stmt_execute(stmt)) {
        fprintf(stderr, "mysql_stmt_execute(), %s\n", mysql_stmt_error(stmt));
        return;
    }

    MYSQL_RES* result = mysql_stmt_result_metadata(stmt);
    if (!result) {
        fprintf(stderr, "mysql_stmt_result_metadata(), %s\n", mysql_stmt_error(stmt));
        return;
    }

    int num_fields = mysql_num_fields(result);
    my_bool use_eof = 0;

    EmployeeDetails emp_details[num_fields];

    for (int i = 0; i < num_fields; ++i) {
        MYSQL_FIELD* field = mysql_fetch_field(result);
        if (!field) break;

        switch (i) {
            case 0:
                bind[i].buffer_type = MYSQL_TYPE_STRING;
                bind[i].buffer = emp_details[i].name;
                bind[i].buffer_length = sizeof(emp_details[i].name);
                bind[i].length = &lengths[i];
                bind[i].is_null = &is_null[i];
                break;
            case 1:
                bind[i].buffer_type = MYSQL_TYPE_STRING;
                bind[i].buffer = emp_details[i].city;
                bind[i].buffer_length = sizeof(emp_details[i].city);
                bind[i].length = &lengths[i];
                bind[i].is_null = &is_null[i];
                break;
            case 2:
                bind[i].buffer_type = MYSQL_TYPE_STRING;
                bind[i].buffer = emp_details[i].address;
                bind[i].buffer_length = sizeof(emp_details[i].address);
                bind[i].length = &lengths[i];
                bind[i].is_null = &is_null[i];
                break;
        }
    }

    if (mysql_stmt_bind_result(stmt, bind)) {
        fprintf(stderr, "mysql_stmt_bind_result(), %s\n", mysql_stmt_error(stmt));
        return;
    }

    while (!mysql_stmt_fetch(stmt)) {
        for (int i = 0; i < num_fields; ++i) {
            printf("Name: %s, City: %s, Address: %s\n",
                   emp_details[i].name,
                   emp_details[i].city,
                   emp_details[i].address);
        }
    }

    mysql_free_result(result);
    mysql_stmt_close(stmt);
}

int main() {
    MYSQL* conn = mysql_init(NULL);
    if (!conn) {
        fprintf(stderr, "mysql_init() failed\n");
        return EXIT_FAILURE;
    }

    if (!mysql_real_connect(conn, "host", "user", "password", "database", 0, NULL, 0)) {
        fprintf(stderr, "mysql_real_connect() failed: %s\n", mysql_error(conn));
        mysql_close(conn);
        return EXIT_FAILURE;
    }

    fetch_employee_details(conn, 1); // Example supervisor ID

    mysql_close(conn);
    return EXIT_SUCCESS;
}
```

