['```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;
using System.Threading.Tasks;

public class ConfigurationManager<TEnvironment>
{
    private readonly string _configFilePath;
    private ConcurrentDictionary<string, ParameterState> _parameters = new();
    private TEnvironment _environment;

    public ConfigurationManager(string configFilePath)
    {
        _configFilePath = configFilePath;
    }

    public void LoadConfiguration(bool async = false)
    {
        try
        {
            var json = File.ReadAllText(_configFilePath);
            var configuration = JsonSerializer.Deserialize<Dictionary<string, ParameterConfig>>(json);

            if (configuration == null) throw new FormatException("Invalid JSON format.");

            foreach (var config in configuration.Values)
            {
                _parameters[config.Key] = new ParameterState(config.State, config.Condition);
            }
        }
        catch (Exception ex)
        {
            LogError($"Failed to load configuration: {ex.Message}");
            // Handle errors
        }

        if (async)
        {
            Task.Run(() => LoadConfiguration(false));
        }
    }

    public async Task LoadConfigurationAsync()
    {
        await Task.Run(() => LoadConfiguration(true));
    }

    public void SaveConfiguration(bool async = false)
    {
        try
        {
            var configuration = new Dictionary<string, ParameterConfig>();

            foreach (var parameter in _parameters.Values)
            {
                configuration[parameter.Key] = new ParameterConfig(parameter.State, parameter.Condition);
            }

            string json = JsonSerializer.Serialize(configuration);
            File.WriteAllText(_configFilePath, json);

            LogInfo("Configuration saved successfully.");
        }
        catch (Exception ex)
        {
            LogError($"Failed to save configuration: {ex.Message}");
            // Handle errors
        }

        if (async)
        {
            Task.Run(() => SaveConfiguration(false));
        }
    }

    public async Task SaveConfigurationAsync()
    {
        await Task.Run(() => SaveConfiguration(true));
    }

    public void EvaluateParameters(TEnvironment environment)
    {
        _environment = environment;

        foreach (var parameter in _parameters.Values)
        {
            if (parameter.State == ParameterState.Conditional && parameter.Condition != null)
            {
                try
                {
                    bool conditionMet = parameter.Condition(environment);
                    parameter.IsActive = conditionMet;
                }
                catch (Exception ex)
                {
                    LogError($"Condition evaluation failed for {parameter.Key}: {ex.Message}");
                    // Handle errors
                }
            }
        }
    }

    public void ApplyTransformation(Func<string, object> transformFunction)
    {
        foreach (var parameter in _parameters.Values)
        {
            try
            {
                var transformedValue = transformFunction(parameter.Key);
