['Here's a C implementation for managing semaphores in a multi-threaded application:

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>

#define MAX_SEMAPHORES 100

typedef struct {
    sem_t semaphore;
    int initialized;
    pthread_mutex_t lock;
} SemaphoreItem;

SemaphoreItem globalSemaphores[MAX_SEMAPHORES];
int count = 0;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

// Error logging function
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Function to initialize a semaphore with a given initial value
sem_t* create_semaphore(int init_value, int *error_code) {
    if (count >= MAX_SEMAPHORES) {
        *error_code = -1;
        log_error("Max semaphores limit reached");
        return NULL;
    }

    pthread_rwlock_wrlock(&rwlock);
    SemaphoreItem *item = &globalSemaphores[count++];
    int result = sem_init(&item->semaphore, 0, init_value);

    if (result != 0) {
        pthread_rwlock_unlock(&rwlock);
        *error_code = -2;
        log_error("Semaphore initialization failed");
        return NULL;
    }

    item->initialized = 1;
    pthread_mutex_init(&item->lock, NULL);
    pthread_rwlock_unlock(&rwlock);

    *error_code = 0;
    return &item->semaphore;
}

// Function to delete a semaphore
int delete_semaphore(sem_t *sem) {
    if (sem == NULL) {
        log_error("Attempted to delete an uninitialized semaphore");
        return -1;
    }

    pthread_rwlock_rdlock(&rwlock);
    for (int i = 0; i < count; ++i) {
        pthread_mutex_lock(&globalSemaphores[i].lock);

        if (&globalSemaphores[i].semaphore == sem) {
            int is_initialized = globalSemaphores[i].initialized;
            pthread_mutex_unlock(&globalSemaphores[i].lock);

            pthread_rwlock_unlock(&rwlock);
            if (is_initialized) {
                sem_destroy(sem);
                for (int j = i; j < count - 1; ++j) {
                    globalSemaphores[j] = globalSemaphores[j + 1];
                }
                --count;
            } else {
                log_error("Attempted to delete an already uninitialized semaphore");
            }
            return 0;
        }

        pthread_mutex_unlock(&globalSemaphores[i].lock);
    }

    pthread_rwlock_unlock(&rwlock);
    log_error("Semaphore not found");
    return -1;
}

// Function to check if a semaphore is in use
int is_semaphore_in_use(sem_t *sem) {
    if (sem == NULL) {
        log_error("Invalid semaphore passed for usage check");
        return 0;
    }

    pthread_rwlock_rdlock(&rwlock);
    for (int i = 0; i < count; ++i) {
        pthread_mutex_lock(&globalSemaphores[i].lock);

        if (&globalSemaphores[i].semaphore == sem && globalSemaphores[i].initialized) {
            pthread_mutex_unlock(&globalSemaphores[i].lock);
            pthread_rwlock_unlock(&rwlock);
            return 1;
        }

        pthread_mutex_unlock(&globalSemaphores[i].lock);
    }

    pthread_rwlock_unlock(&rwlock);
    return 0;
}

// Mock function to simulate external configuration management service
int update_semaphore_parameters(sem_t *sem, int new_value) {
    if (sem == NULL) {
        log_error("Invalid semaphore passed for parameter update");
        return -1;
    }

    // Simulate fetching and applying configuration
    sem_setvalue(sem, &new_value);
    return 0;
}

// Thread-safe function to access a semaphore by index
sem_t* get_semaphore_by_index(int index) {
    if (index < 0 || index >= count) {
        log_error("Invalid semaphore index accessed");
        return NULL;
    }

    pthread_rwlock_rdlock(&rwlock);
    SemaphoreItem *item = &globalSemaphores[index];
    pthread_mutex_lock(&item->lock);

    sem_t *sem = item->initialized ? &item->semaphore : NULL;

    pthread_mutex_unlock(&item->lock);
    pthread_rwlock_unlock(&rwlock);
    return sem;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_rwlock_t` for read-write locks and `pthread_mutex_t` for individual semaphore protection.
- **Dynamic Management**: Allows dynamic creation, deletion, and access to up to 100 semaphores.
- **Error Handling**: Logs errors and manages error codes for operations.
- **Configuration Integration**: Simulates external configuration updates with `update_semaphore_parameters`.
- **Resource Optimization**: Efficient memory usage by reusing array slots after deletions.']

