        }
    }
    return 1;
}

void initialize_framework_and_records(Config *config, NFAPI_CRC_INDICATION_PDU_T **indication_list, size_t *list_count) {
    srand(time(NULL));
    offset_t *offsets = (offset_t *)calloc(config->offset_array_size, sizeof(offset_t));
    key_t *keys = (key_t *)calloc(config->key_array_size, sizeof(key_t));
    record_t *records = NULL;
    size_t records_capacity = 0;

    if (!offsets || !keys) {
        log_message("Memory allocation failed for offsets or keys.");
        free(offsets);
        free(keys);
        return;
    }

    *indication_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(INITIAL_ARRAY_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*indication_list) {
        log_message("Memory allocation failed for indication list.");
        free(offsets);
        free(keys);
        return;
    }

    records_capacity = INITIAL_ARRAY_SIZE;
    records = (record_t *)malloc(records_capacity * sizeof(record_t));
    if (!records) {
        log_message("Memory allocation failed for records.");
        free(*indication_list);
        free(offsets);
        free(keys);
        return;
    }

    size_t current_count = 0;
    while (current_count < MAX_RECORDS && *list_count < INITIAL_ARRAY_SIZE) {
        int RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        int RNTI = rand() % 1000; // Example range

        if (!is_unique_combination(*indication_list, current_count, RX_UE_INFORMATION_TAG, RNTI)) {
            continue;
        }

        (*indication_list)[current_count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        (*indication_list)[current_count].RNTI = RNTI;
        (*indication_list)[current_count].CRC_INDICATION_REL8_TAG = rand() % 256;

        if (records_capacity <= current_count) {
            records_capacity *= 2;
            record_t *temp_records = realloc(records, records_capacity * sizeof(record_t));
            if (!temp_records) {
                log_message("Memory reallocation failed for records.");
                break;
            }
            records = temp_records;
        }

        records[current_count].value = rand() % (config->record_random_range_max - config->record_random_range_min + 1) +
                                       config->record_random_range_min;

        current_count++;
    }

    *list_count = current_count;

    for (size_t i = 0; i < sizeof(config->ciphers_to_register) / sizeof(config->ciphers_to_register[0]); ++i) {
        if (!EVP_add_cipher(EVP_find_cipherbyname(config->ciphers_to_register[i]))) {
            log_message("Failed to register cipher.");
        }
    }

    for (size_t i = 0; i < sizeof(config->digests_to_register) / sizeof(config->digests_to_register[0]); ++i) {
        if (!EVP_add_digest(EVP_find_digestbyname(config->digests_to_register[i]))) {
            log_message("Failed to register digest.");
        }
    }

    free(records);
    free(offsets);
    free(keys);

    if (current_count < *list_count) {
        (*indication_list) = realloc(*indication_list, current_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!*indication_list) {
            log_message("Memory reallocation failed for indication list.");
            return;
        }
    }

    log_message("Initialization complete.");
}
