#include <stdio.h>
#include <stdlib.h>
import time.h
#include <pthread.h>

#define MAX_MEMORY_PER_CORE_MB 2
#define TOTAL_MEMORY_LIMIT_MB 50

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mock CRC computation interface
typedef void (*CRC_COMPUTE_FUNC)(unsigned int* data, size_t length);

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* structures;
    size_t count;
    CRC_COMPUTE_FUNC crc_compute;
} ProcessingContext;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Probabilistic hash function to generate unique RX_UE_INFORMATION_TAG
unsigned int probabilistic_hash(unsigned int seed) {
    unsigned int a = 1664525, c = 1013904223; // Linear Congruential Generator parameters
    return (a * seed + c) & 0xFFFFFFFF;
}

// CRC computation mock implementation
void default_crc_compute(unsigned int* data, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        data[i] ^= 0xA5A5A5A5; // Simple XOR operation as a placeholder
    }
}

// Function to dynamically create and populate the list of structures
void create_and_populate_structures(size_t N, CRC_COMPUTE_FUNC crc_compute, void (*callback)(ProcessingContext*)) {
    pthread_mutex_lock(&lock);

    const size_t maxStructuresPerCore = (MAX_MEMORY_PER_CORE_MB * 1024 * 1024) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    const size_t totalMaxStructures = (TOTAL_MEMORY_LIMIT_MB * 1024 * 1024) / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (N > totalMaxStructures || N > maxStructuresPerCore) {
        printf("Warning: Requested number exceeds memory limits. Reducing count.\n");
        size_t adjustedCount = (N > totalMaxStructures) ? totalMaxStructures : maxStructuresPerCore;
        N = (adjustedCount < N) ? adjustedCount : N;
    }

    ProcessingContext* context = malloc(sizeof(ProcessingContext));
    if (!context) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    context->structures = calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!context->structures) {
        free(context);
        printf("Error: Memory allocation for structures failed.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    unsigned int seed = time(NULL);
    size_t uniqueTags = 0;

    while (uniqueTags < N) {
        unsigned int tag = probabilistic_hash(seed++);

        if (tag >= (1 << 30)) { // Simulate a simple range check for uniqueness
            continue; // Collision or invalid tag, try another seed
        }

        context->structures[uniqueTags].RX_UE_INFORMATION_TAG = tag;
        context->structures[uniqueTags].RNTI = rand() % 1000;
        context->structures[uniqueTags].CRC_INDICATION_REL8_TAG = rand();
        context->structures[uniqueTags].CRCFLAG = rand() & 1; // Randomly set CRCFLAG

        crc_compute(&context->structures[uniqueTags], sizeof(NFAPI_CRC_INDICATION_PDU_T));

        uniqueTags++;
    }

    context->count = N;
    context->crc_compute = crc_compute;

    pthread_mutex_unlock(&lock);

    if (callback) {
        callback(context);
    }
}

// Example callback function
void processing_complete(ProcessingContext* context) {
    printf("Processing completed with %zu structures.\n", context->count);
    free(context->structures);
    free(context);
}

int main() {
    create_and_populate_structures(1000000, default_crc_compute, processing_complete);
    return 0;
}
