    const char *p = mac;
    int colons = 0;

    while (*p != '\0') {
        if (*p == ':')
            ++colons;
        else if ((*p < '0' || *p > '9') && (*p < 'a' || *p > 'f') &&
                 (*p < 'A' || *p > 'F'))
            return 0;

        p++;
    }

    return (colons == 5);
}

