        log_message("Array resize failed or reached max capacity", verbose);
        pthread_mutex_unlock(&arr->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &arr->data[arr->size++];
    fetch_RX_UE_INFORMATION_TAG(&pdu->RX_UE_INFORMATION_TAG);
    fetch_RNTI(&pdu->RNTI);

