    for (int i = 0; i < 4; ++i) {
        pdu->CRC_INDICATION_REL8_TAG[i] = arr->size + i;
    }

    // Set checksum validation flag
    pdu->checksum_validation_flag = 1; // Assuming a valid checksum

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

// Function to free the array resources
