        if (init_res != 0 || validate_frame_quality(&collection->frames[i]) != 0) {
            // Handle initialization or validation failure
            free(collection->frames);
            free(collection);
            return NULL;
        }
    }

    return collection;
}

// Function to safely destroy a frame collection
void destroy_frame_collection(FrameCollection *collection) {
    if (collection) {
        pthread_mutex_destroy(&collection->lock);
        free(collection->frames);
        free(collection);
    }
