#define MAX_RESOURCES 100
#define NFAPI_CRC_INDICATION_PDU_T_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)
#define STATUS_SUCCESS 0
#define STATUS_FAILURE -1

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ResourceNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ResourceNode* next;
} ResourceNode;

typedef struct {
    ResourceNode* pool[MAX_RESOURCES];
    pthread_mutex_t lock;
    size_t count;
} ResourceManager;

ResourceManager resourceManager;

void initializeResourceManager() {
    memset(resourceManager.pool, 0, sizeof(resourceManager.pool));
    pthread_mutex_init(&resourceManager.lock, NULL);
    resourceManager.count = 0;
}

ResourceNode* allocateResource() {
    pthread_mutex_lock(&resourceManager.lock);
    if (resourceManager.count < MAX_RESOURCES) {
        ResourceNode* node = malloc(sizeof(ResourceNode));
        if (!node) {
            pthread_mutex_unlock(&resourceManager.lock);
            return NULL;
        }
        resourceManager.pool[resourceManager.count++] = node;
        pthread_mutex_unlock(&resourceManager.lock);
        return node;
    }
    pthread_mutex_unlock(&resourceManager.lock);
    return NULL;
}

void deallocateResource(ResourceNode* node) {
    pthread_mutex_lock(&resourceManager.lock);
    if (resourceManager.count > 0) {
        for (size_t i = 0; i < resourceManager.count; ++i) {
            if (resourceManager.pool[i] == node) {
                free(node);
                resourceManager.pool[i] = NULL;
                --resourceManager.count;
                break;
            }
        }
    }
    pthread_mutex_unlock(&resourceManager.lock);
}

int initializeResourceManagerAndPopulateCRCList(NFAPI_CRC_INDICATION_PDU_T* list, size_t numEntries) {
    initializeResourceManager();

    for (size_t i = 0; i < numEntries; ++i) {
        ResourceNode* node = allocateResource();
        if (!node) {
            while (resourceManager.count > 0) {
                deallocateResource(resourceManager.pool[resourceManager.count - 1]);
            }
            return STATUS_FAILURE;
        }

        list[i].RX_UE_INFORMATION_TAG = rand() % 65536;
        list[i].RNTI = rand() % 65536;
        list[i].CRC_INDICATION_REL8_TAG = rand();
        list[i].CRCFLAG = rand() % 2;

        memcpy(&node->data, &list[i], NFAPI_CRC_INDICATION_PDU_T_SIZE);
    }

    return STATUS_SUCCESS;
}
