    uint8_t message_type;
    size_t payload_size;
} nas_message_header;

#define MAX_CHAR_SET_SIZE 256

// Function prototypes
void *generateRandomString(size_t length, const char *charset);
char *hashPassword(const char *password);

sem_t resourceSemaphore;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int manageResourcePoolWithConcurrency(int N, size_t numMessages, const char *charset, size_t charsetLength, const char *password) {
    // Initialize semaphore
    if (sem_init(&resourceSemaphore, 0, N) != 0) {
        return -1;
    }

    nas_message_header **messages = malloc(numMessages * sizeof(nas_message_header *));
    if (!messages) {
        sem_destroy(&resourceSemaphore);
        return -1;
    }

    // Seed random number generator
    srand(time(NULL));

    for (size_t i = 0; i < numMessages; ++i) {
        // Wait on semaphore to manage resource access
        sem_wait(&resourceSemaphore);

        nas_message_header *header = malloc(sizeof(nas_message_header));
        if (!header) {
            // Release resources on failure
            for (size_t j = 0; j < i; ++j) {
                free(messages[j]);
            }
            free(messages);
            sem_destroy(&resourceSemaphore);
            return -1;
        }

        pthread_mutex_lock(&mutex);

        header->transaction_id = rand(); // Generate unique transaction ID
        header->message_type = rand() % 10; // Example message type range

        // Calculate payload size based on message type
        switch (header->message_type) {
            case 0:
                header->payload_size = rand() % 128;
                break;
            case 1:
                header->payload_size = rand() % 256;
                break;
            default:
                header->payload_size = rand() % 512;
                break;
        }

        pthread_mutex_unlock(&mutex);
        messages[i] = header;

        // Release semaphore
        sem_post(&resourceSemaphore);
    }

    // Generate random string and hash password
    void *randomString = generateRandomString(16, charset); // Example length of 16
    char *hashedPassword = hashPassword(password);

    // Clean up resources
    for (size_t i = 0; i < numMessages; ++i) {
        free(messages[i]);
    }
    free(messages);
    sem_destroy(&resourceSemaphore);

    printf("%s\n%s\n", (char *)randomString, hashedPassword);
    free(randomString);
    free(hashedPassword);

    return 0;
}

void *generateRandomString(size_t length, const char *charset) {
    void *string = malloc(length + 1);
    if (!string) return NULL;

    for (size_t i = 0; i < length; ++i) {
        size_t index = rand() % strlen(charset);
        ((char *)string)[i] = charset[index];
    }
    ((char *)string)[length] = '\0';
    return string;
}

char *hashPassword(const char *password) {
    // Dummy hash function for demonstration purposes
    unsigned int hash = 5381;
    int c;

    while ((c = *password++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c

    char *hashedPassword = malloc(32); // Example size for hashed password
    if (!hashedPassword) return NULL;
    sprintf(hashedPassword, "%u", hash);
    return hashedPassword;
}
