#include <iostream>
#include <vector>
#include <array>
#include <random>
#include <openssl/evp.h>
#include <memory>
#include <stdexcept>

namespace rng {

class RandomNumberGenerator {
public:
    static RandomNumberGenerator& getInstance() {
        static RandomNumberGenerator instance;
        return instance;
    }

    int generateRandomNumbers(int min, int max) {
        std::uniform_int_distribution<int> dist(min, max);
        return dist(generator_);
    }

private:
    RandomNumberGenerator() : generator_(std::random_device{}()) {}
    std::mt19937 generator_;
};

} // namespace rng

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRC_INDICATION_REL8_TAG;
};

struct offset_t {};
struct key_t {};
struct record_t {
    int value;
};

class Configuration {
public:
    std::vector<std::string> ciphers;
    std::vector<std::string> digests;
    size_t offsetArraySize;
    size_t keyArraySize;
    int minValue;
    int maxValue;

    Configuration(const std::vector<std::string>& ciphers,
                  const std::vector<std::string>& digests,
                  size_t offsetArraySize, size_t keyArraySize,
                  int minValue, int maxValue)
        : ciphers(ciphers), digests(digests),
          offsetArraySize(offsetArraySize), keyArraySize(keyArraySize),
          minValue(minValue), maxValue(maxValue) {}
};

void initializeFrameworkAndRecords(Configuration config) {
    using namespace rng;
    auto& rngInstance = RandomNumberGenerator::getInstance();

    std::vector<NFAPI_CRC_INDICATION_PDU_T> pduList;
    std::set<std::pair<int, int>> uniquePairs;

    while (pduList.size() < config.offsetArraySize + config.keyArraySize) {
        int rxTag = rngInstance.generateRandomNumbers(1, 1000);
        int rnti = rngInstance.generateRandomNumbers(1, 1000);
        bool crcTag = static_cast<bool>(rngInstance.generateRandomNumbers(0, 1));

        if (uniquePairs.insert({rxTag, rnti}).second) {
            pduList.emplace_back(NFAPI_CRC_INDICATION_PDU_T{rxTag, rnti, crcTag});
        }
    }

    std::vector<offset_t> offsetArray(config.offsetArraySize);
    std::vector<key_t> keyArray(config.keyArraySize);

    std::vector<std::unique_ptr<record_t[]>> recordArrays;
    for (size_t i = 0; i < config.offsetArraySize + config.keyArraySize; ++i) {
        auto records = std::make_unique<record_t[]>(config.maxValue - config.minValue + 1);
        if (!records) throw std::runtime_error("Memory allocation failed");

        for (int j = 0; j <= config.maxValue - config.minValue; ++j) {
            records[j].value = config.minValue + j;
        }

        recordArrays.push_back(std::move(records));
    }

    for (const auto& cipherName : config.ciphers) {
        if (!EVP_add_cipher(EVP_get_cipherbyname(cipherName.c_str()))) {
            throw std::runtime_error("Failed to add cipher: " + cipherName);
        }
    }

