    pthread_mutex_init(&rm->lock, NULL);
    pthread_cond_init(&rm->cond_var, NULL);

    rm->resources = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!rm->resources) {
