    for (size_t i = 0; i < initial_capacity; ++i) {
        initResource(&rm->resources[i]);
    }

    // Start a thread to monitor and adjust resources
    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, []() -> void* {
        while (1) {
            sleep(60);  // Adjust every minute

            pthread_mutex_lock(rm->lock);
            float utilization = ((float)rm->in_use / rm->capacity) * 100;

            if (utilization > 80.0f && rm->capacity < MAX_RESOURCES) {
                size_t new_capacity = rm->capacity + RESOURCE_INCREMENT;
                NFAPI_CRC_INDICATION_PDU_T *new_resources = realloc(rm->resources, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

                if (new_resources) {
