                size_t new_capacity = rm->capacity - RESOURCE_INCREMENT;
                NFAPI_CRC_INDICATION_PDU_T *new_resources = realloc(rm->resources, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

                if (new_resources) {
                    rm->resources = new_resources;
                    rm->capacity = new_capacity;
                } else {
                    // Handle allocation failure
                }
            }

            pthread_mutex_unlock(rm->lock);
        }
    }, NULL) != 0) {
        free(rm->resources);
        pthread_mutex_destroy(&rm->lock);
        pthread_cond_destroy(&rm->cond_var);
        return -1;
    }

    pthread_detach(monitor_thread);

    return 0; // Success
}
