// Thread-safe logging mechanism
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static int successful_allocations = 0;
static int allocation_failures = 0;

void log_allocation_result(int success) {
    pthread_mutex_lock(&log_mutex);
    if (success) {
        successful_allocations++;
    } else {
        allocation_failures++;
    }
    pthread_mutex_unlock(&log_mutex);
}

int validate_nfa_handle(NFAPI_Handle_Type *nfaHandle) {
