        crcTag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        array[i].someField = (int)crcTag; // Store pointer as int for example purposes
    }

    log_allocation_result(1);

    return array;
}

void free_nfa_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array, int count) {
    if (array == NULL) {
        return;
    }

    for (int i = 0; i < count; ++i) {
        CRC_INDICATION_REL8_TAG *crcTag = (CRC_INDICATION_REL8_TAG*)(array[i].someField);
        free(crcTag);
