    }

    if (buffer_count + N > MAX_EVENTS) {
        log_event_to_service(event_buffer[0], buffer_count); // Log existing events
        buffer_count = 0;
    }

    for (int i = 0; i < N; ++i) {
        event_buffer[buffer_count++] = &new_events[i];
    }

    free(new_events);
    pthread_mutex_unlock(&event_mutex);

    if (buffer_count >= MAX_EVENTS / 2) { // Trigger logging when buffer is half full
        log_event_to_service(event_buffer[0], buffer_count);
        buffer_count = 0;
    }
}

