    return rand() % 2;
}

void manage_nfa_pcu_list(NFAPI_CRC_INDICATION_PDU_T **pdus, int M, size_t max_memory_usage,
                         const char *log_directory, int enable_logging) {

    if (!enable_logging) {
        log_directory = NULL; // Disable logging by setting to NULL
    }

    srand(time(NULL));  // Seed the random number generator

    NFAPI_CRC_INDICATION_PDU_T *allocated_pdus = NULL;
    size_t current_memory_usage = 0;
    int allocated_count = 0;

    for (int i = 0; i < M && current_memory_usage <= max_memory_usage; ++i) {
        size_t pdu_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

        if (current_memory_usage + pdu_size > max_memory_usage) {
            // Log allocation failure and break
            if (enable_logging) {
                FILE *log_file = fopen(log_directory, "a");
                if (log_file) {
                    fprintf(log_file, "Failed to allocate memory for PDU %d\n", i);
                    fclose(log_file);
                }
            }
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(pdu_size);
        if (!new_pdu) {
            // Log allocation failure and clean up
            if (enable_logging) {
                FILE *log_file = fopen(log_directory, "a");
                if (log_file) {
                    fprintf(log_file, "Memory allocation failed at PDU %d\n", i);
                    fclose(log_file);
                }
            }

            // Free any previously allocated memory
            for (int j = 0; j < allocated_count; ++j) {
                free(allocated_pdus[j]);
            }
            free(allocated_pdus);
            *pdus = NULL;
            return;
        }

        // Initialize PDU structure with random data and valid information
        new_pdu->rx_ue_information_tag = /* Set RX_UE_INFORMATION_TAG */;
        new_pdu->rnti = /* Set RNTI */;
        new_pdu->crc_indication_rel8_tag.CRCFLAG = rand_boolean();

        // Resize the allocated_pdus array to hold one more PDU
        NFAPI_CRC_INDICATION_PDU_T *new_allocated_array = realloc(allocated_pdus,
                                                                  (allocated_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_allocated_array) {
            free(new_pdu);

            // Log allocation failure and clean up
            if (enable_logging) {
                FILE *log_file = fopen(log_directory, "a");
                if (log_file) {
                    fprintf(log_file, "Re-allocation failed after allocating PDU %d\n", i);
                    fclose(log_file);
                }
            }

            // Free any previously allocated memory
            for (int j = 0; j < allocated_count; ++j) {
                free(allocated_pdus[j]);
            }
            free(allocated_pdus);

            *pdus = NULL;
            return;
        }

        allocated_pdus = new_allocated_array;
        allocated_pdus[allocated_count++] = new_pdu;

        // Update memory usage
        current_memory_usage += pdu_size;

        if (enable_logging) {
            FILE *log_file = fopen(log_directory, "a");
            if (log_file) {
                fprintf(log_file, "Successfully allocated PDU %d\n", i);
                fclose(log_file);
            }
        }
    }

    // Set the output parameter to point to the fully or partially allocated list
    *pdus = allocated_pdus;
}
```

### Key Points:
