typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint16_t rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a random CRC flag
int generate_random_crc_flag() {
