}

// Fallback function to generate unique RNTI and RX_UE_INFORMATION_TAG if APIs fail
void fallback_generate_unique_tags(RX_UE_INFORMATION_TAG* tag, uint16_t* rnti) {
    static uint64_t last_rnti = 0;
    while (true) {
        last_rnti++;
        *rnti = last_rnti & 0xFFFF; // Simulate a unique RNTI within bounds
        tag->rnti = last_rnti;
        if (tag->rnti != 0) { // Ensure non-zero value
            break;
        }
    }
}

// Function to check if RX_UE_INFORMATION_TAG is already in the array
int is_tag_unique(RX_UE_INFORMATION_TAG* tag, NFAPI_CRC_INDICATION_PDU_T* pdu_array, size_t count) {
    for (size_t i = 0; i < count; i++) {
