                pdu_array[i].rx_ue_information_tag.crc_flag = generate_random_crc_flag();
                unique_count++;
            } else {
                free(pdu_array);
                break; // Break to retry allocation if a duplicate is found
            }
        }

        if (unique_count == N) {
            return pdu_array;
        }
    }
}

// Example usage
int main() {
