#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <sys/stat.h>

#define MAX_FILE_SIZE 104857600 // 100 MB in bytes

// Function prototypes
void log_message(const char *message);
int handle_file_operation(const char *filename, const char *operation_mode, int key_length);
EVP_CIPHER_CTX* initialize_cipher(const char *operation_mode, int key_length, unsigned char **key, unsigned char **iv);

void log_message(const char *message) {
    FILE *log_file = fopen("operation.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    } else {
        fprintf(stderr, "Failed to open log file.\n");
    }
}

int handle_file_operation(const char *filename, const char *operation_mode, int key_length) {
    struct stat st;
    if (stat(filename, &st) == -1) {
        log_message("Error: Unable to access the file.");
        return -1;
    }

    if (st.st_size > MAX_FILE_SIZE) {
        log_message("Error: File size exceeds 100 MB limit.");
        return -1;
    }

    FILE *file = fopen(filename, "rb+");
    if (!file) {
        log_message("Error: Unable to open the file.");
        return -1;
    }

    unsigned char *key = NULL;
    unsigned char *iv = NULL;
    EVP_CIPHER_CTX *ctx = initialize_cipher(operation_mode, key_length, &key, &iv);
    if (!ctx) {
        fclose(file);
        log_message("Error: Cipher initialization failed.");
        return -1;
    }

    // Buffer to read/write file content
    size_t buffer_size = 4096; // Example buffer size, can be adjusted
    unsigned char *buffer = (unsigned char *)malloc(buffer_size);
    if (!buffer) {
        log_message("Error: Memory allocation failed.");
        EVP_CIPHER_CTX_free(ctx);
        fclose(file);
        return -1;
    }

    int out_len, final_out_len;
    do {
        size_t read_bytes = fread(buffer, 1, buffer_size, file);

        // Encrypt or decrypt the buffer
        if (strcmp(operation_mode, "encrypt") == 0) {
            EVP_EncryptUpdate(ctx, buffer, &out_len, buffer, read_bytes);
        } else if (strcmp(operation_mode, "decrypt") == 0) {
            EVP_DecryptUpdate(ctx, buffer, &out_len, buffer, read_bytes);
        } else {
            log_message("Error: Invalid operation mode.");
            free(buffer);
            EVP_CIPHER_CTX_free(ctx);
            fclose(file);
            return -1;
        }

        // Write the output to file
        fwrite(buffer, 1, out_len, file);

    } while (fread(buffer, 1, buffer_size, file) > 0);

    if (strcmp(operation_mode, "encrypt") == 0) {
        EVP_EncryptFinal_ex(ctx, buffer, &final_out_len);
    } else if (strcmp(operation_mode, "decrypt") == 0) {
        EVP_DecryptFinal_ex(ctx, buffer, &final_out_len);
    }

    fwrite(buffer, 1, final_out_len, file);

    free(buffer);
    EVP_CIPHER_CTX_free(ctx);
    fclose(file);

    log_message("Operation completed successfully.");
    return 0;
}

EVP_CIPHER_CTX* initialize_cipher(const char *operation_mode, int key_length, unsigned char **key, unsigned char **iv) {
    const EVP_CIPHER *cipher = NULL;

    if (strcmp(operation_mode, "encrypt") == 0 || strcmp(operation_mode, "decrypt") == 0) {
        cipher = EVP_aes_256_cbc(); // Default to AES-256-CBC
    } else {
        log_message("Error: Unsupported operation mode.");
        return NULL;
    }

    *key = (unsigned char *)malloc(key_length / 8);
    if (!*key) {
        log_message("Error: Key memory allocation failed.");
        return NULL;
    }

    // Example key initialization, replace with secure key generation
    for (int i = 0; i < key_length / 8; ++i) {
        (*key)[i] = rand() % 256;
    }

    *iv = (unsigned char *)malloc(EVP_CIPHER_block_size(cipher));
    if (!*iv) {
        log_message("Error: IV memory allocation failed.");
        free(*key);
        return NULL;
    }

    // Example IV initialization, replace with secure IV generation
    for (int i = 0; i < EVP_CIPHER_block_size(cipher); ++i) {
        (*iv)[i] = rand() % 256;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        log_message("Error: Cipher context allocation failed.");
        free(*key);
        free(*iv);
        return NULL;
    }

    int init_result = (strcmp(operation_mode, "encrypt") == 0) 
                      ? EVP_EncryptInit_ex(ctx, cipher, NULL, *key, *iv)
                      : EVP_DecryptInit_ex(ctx, cipher, NULL, *key, *iv);

    if (!init_result) {
        log_message("Error: Cipher initialization failed.");
        EVP_CIPHER_CTX_free(ctx);
        free(*key);
        free(*iv);
        return NULL;
    }

    return ctx;
}
