### PHP Script

Now, you can write a PHP script that interfaces with this C code:

```php
<?php
// Assuming the compiled shared library is named 'libnfa.so'
$sharedLib = '/path/to/libnfa.so';

// Initialize and load the shared library
if (!extension_loaded('ffi')) {
    dl('FFI');
}

$ffi = \FFI::cdef("
    typedef struct {
        unsigned int RX_UE_INFORMATION_TAG;
        unsigned int RNTI;
        unsigned short CRC_INDICATION_REL8_TAG;
        unsigned char CRCFLAG;
    } NFAPI_CRC_INDICATION_PDU_T;

    int initialize_nfa_crc_pdu(NFAPI_CRC_INDICATION_PDU_T **pdu_list, size_t num_pdus);
    void free_nfa_crc_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu_list);
", $sharedLib);

// Function to call C function from PHP
function initializeNfaPduList($numPdus) {
    global $ffi;

    $pduList = null;
    try {
        $result = $ffi->initialize_nfa_crc_pdu($pduList, $numPdus);

        if ($result !== 0) {
            throw new Exception('Failed to initialize NFA CRC PDU list. Error code: ' . $result);
        }

        return $pduList;
    } catch (Exception $e) {
        echo "Error: ",  $e->getMessage(), "\n";
        if ($pduList !== null) {
            $ffi->free_nfa_crc_pdu($pduList);
        }
        return false;
    }
}

// Example usage
