if ($pduList !== false) {
    // Use $pduList for further processing
    echo "Successfully initialized PDU list.\n";
    // Don't forget to free the memory when done
    $ffi->free_nfa_crc_pdu($pduList);
} else {
    echo "Initialization failed.\n";
}
?>
