    // Basic MAC address validation logic
    return (strlen(mac) == 17 && sscanf(mac, "%hhx:%hhx:%hhx:%hhx:%hhx:%hhx", 
                                        &((unsigned char*)mac)[0], &((unsigned char*)mac)[1],
                                        &((unsigned char*)mac)[3], &((unsigned char*)mac)[4],
                                        &((unsigned char*)mac)[6], &((unsigned char*)mac)[7]) == 6);
}

int validate_ip_address(const char *ip) {
    // Basic IP address validation logic
    unsigned int parts[4];
    return (sscanf(ip, "%u.%u.%u.%u", &parts[0], &parts[1], &parts[2], &parts[3]) == 4 &&
            parts[0] <= 255 && parts[1] <= 255 && parts[2] <= 255 && parts[3] <= 255);
