             (parts[0] == 255 && parts[1] == 254) ||
             (parts[0] == 255 && parts[1] == 252) ||
             (parts[0] == 255 && parts[1] == 248) ||
             (parts[0] == 255 && parts[1] == 240) ||
             (parts[0] == 255 && parts[1] == 224) ||
             (parts[0] == 255 && parts[1] == 192) ||
             (parts[0] == 255 && parts[1] == 128) ||
             (parts[0] == 255)));
}

NICArray* init_nic_array(int initial_size) {
    NICArray *nic_array = (NICArray*)malloc(sizeof(NICArray));
    if (!nic_array) {
        perror("Failed to allocate NICArray");
        return NULL;
    }

    nic_array->num_nics = initial_size > 0 && initial_size <= MAX_NICS ? initial_size : MAX_NICS;
    nic_array->nics = (NICConfig*)calloc(nic_array->num_nics, sizeof(NICConfig));
    if (!nic_array->nics) {
        perror("Failed to allocate NIC configurations");
        free(nic_array);
        return NULL;
    }

    pthread_mutex_init(&nic_array->lock, NULL);
    return nic_array;
}

void free_nic_array(NICArray *nic_array) {
    if (nic_array) {
        if (nic_array->nics) {
            free(nic_array->nics);
        }
        pthread_mutex_destroy(&nic_array->lock);
        free(nic_array);
    }
