```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_BUFFER_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned long CRC_INDICATION_REL8_TAG; // Assuming a simple checksum value
    int checksum_valid;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char log_buffer[MAX_LOG_BUFFER_SIZE];
} Logger;

void log_message(Logger *logger, const char *message) {
    snprintf(logger->log_buffer, MAX_LOG_BUFFER_SIZE, "%s", message);
    printf("%s\n", logger->log_buffer); // Replace with actual logging system call
}

pthread_mutex_t lock;
Logger logger;

unsigned long generate_checksum(int rnti) {
    unsigned long checksum = 0;
    while (rnti != 0) {
        checksum += rnti % 10;
        rnti /= 10;
    }
    return checksum;
}

int validate_checksum(unsigned long tag, int expected_rnti) {
    unsigned long calculated_checksum = generate_checksum(expected_rnti);
    return (calculated_checksum == tag) ? 1 : 0;
}

NFAPI_CRC_INDICATION_PDU_T* initialize_nfa_array(int size, int verbose) {
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_message(&logger, "Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand(); // Random unique value
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG = generate_checksum(array[i].RNTI);
        array[i].checksum_valid = validate_checksum(array[i].CRC_INDICATION_REL8_TAG, array[i].RNTI);

        if (verbose) {
            char log_entry[MAX_LOG_BUFFER_SIZE];
            snprintf(log_entry, MAX_LOG_BUFFER_SIZE,
                     "Initialized: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%lu, Checksum_Valid=%d",
                     array[i].RX_UE_INFORMATION_TAG, array[i].RNTI, array[i].CRC_INDICATION_REL8_TAG,
                     array[i].checksum_valid);
            log_message(&logger, log_entry);
        }
    }

    pthread_mutex_unlock(&lock);
    return array;
}

void resize_nfa_array(NFAPI_CRC_INDICATION_PDU_T **array, int current_size, int new_size) {
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(*array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        log_message(&logger, "Memory reallocation failed");
        pthread_mutex_unlock(&lock);
        return;
    }

    if (new_size > current_size) {
        for (int i = current_size; i < new_size; ++i) {
            (*new_array)[i].RX_UE_INFORMATION_TAG = rand();
            (*new_array)[i].RNTI = rand();
            (*new_array)[i].CRC_INDICATION_REL8_TAG = generate_checksum((*new_array)[i].RNTI);
            (*new_array)[i].checksum_valid = validate_checksum((*new_array)[i].CRC_INDICATION_REL8_TAG, (*new_array)[i].RNTI);
        }
    }

    *array = new_array;
    pthread_mutex_unlock(&lock);
}

void* process_batch(void *arg) {
    int size = *((int *)arg);
    NFAPI_CRC_INDICATION_PDU_T *array = initialize_nfa_array(size, 1); // Verbose logging enabled

    if (array) {
        resize_nfa_array(&array, size, size + 5); // Example: Adding 5 more elements
        free(array);
    }

    return NULL;
}

int main() {
    pthread_t threads[4];
    int sizes[] = {10, 20, 30, 40};

    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, process_batch, &sizes[i]);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&lock);
    return 0;
}
