        NFAPI_CRC_INDICATION_PDU_T* new_pdu = realloc(pdu_list, (pdus_generated + 1) * pdu_size);
        if (!new_pdu) {
            perror("Failed to allocate memory for PDU");
            cleanup_resources();
            pthread_mutex_unlock(&pdu_list_mutex);
            break;
        }

        pdu_list = new_pdu;

        // Populate the PDU
        pdu_list[pdus_generated].RX_UE_INFORMATION_TAG = rand() % 1000; // Example random value
        pdu_list[pdus_generated].RNTI = rand() % 256; // Example random value
        pdu_list[pdus_generated].CRC_INDICATION_REL8_TAG = rand() % 256; // Example random value
        pdu_list[pdus_generated].CRCFLAG = generate_random_crcflag();

        current_memory_usage += pdu_size;
        pdus_generated++;

        pthread_mutex_unlock(&pdu_list_mutex);
    }

    printf("Generated PDUs: %d\n", pdus_generated);

    // Execute the command with adaptive timeout
    int adaptive_timeout = 10; // Example timeout value, adjust based on system load or other factors
    execute_command(command_path, adaptive_timeout);

    cleanup_resources();
}

void log_warning(const char *message) {
    fprintf(stderr, "WARNING: %s\n", message);
}

int get_available_system_memory() {
