    return 1024 * 1024 * 1024; // Assume 1 GB is available
}

void execute_command(const char *command_path, int adaptive_timeout) {
    pid_t pid = fork();
    if (pid == 0) {
        execl(command_path, command_path, NULL);
        perror("Failed to execute command");
        exit(EXIT_FAILURE);
    } else if (pid > 0) {
        waitpid(pid, NULL, WUNTRACED | adaptive_timeout * 1000); // Convert seconds to milliseconds
    } else {
        perror("Fork failed");
    }
}

void cleanup_resources() {
    free(pdu_list);
    pthread_mutex_destroy(&pdu_list_mutex);
    pthread_cond_destroy(&condition_var);
}

int main(int argc, char **argv) {
