        NFAPI_RX_FRAME_INFO_T** new_frames = realloc(collection->frames,
                                                     sizeof(NFAPI_RX_FRAME_INFO_T*) * new_capacity);
        if (!new_frames) {
            handle_error("Memory allocation failed during resize");
            collection->lock.release();
            return -1;
        }
        for (size_t i = collection->num_frames; i < new_capacity; ++i) {
