using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.IO;
using System.Threading;

public class TempDirectoryManager
{
    private static readonly object _envVarLock = new object();

    public static IDataReader ExecuteSqlInTempDir(List<object> values, SqlConnection connection, string sqlCommand, string directoryName)
    {
        // Verify and create the temporary directory if necessary
        string tempDirPath;
        lock (_envVarLock)  // Ensure thread safety when setting environment variables
        {
            tempDirPath = Environment.GetEnvironmentVariable(directoryName);
            if (string.IsNullOrEmpty(tempDirPath))
            {
                tempDirPath = Path.Combine(Path.GetTempPath(), directoryName);
                Directory.CreateDirectory(tempDirPath);

                // Set the environment variable for future use, ensuring thread safety
                Environment.SetEnvironmentVariable(directoryName, tempDirPath);
            }
        }

        try
        {
            using (SqlCommand command = new SqlCommand(sqlCommand, connection))
            {
                if (values != null)
                {
                    int index = 1;
                    foreach (var value in values)
                    {
                        command.Parameters.AddWithValue($"@param{index++}", value ?? DBNull.Value);
                    }
                }

                return command.ExecuteReader(CommandBehavior.SequentialAccess); // Use SequentialAccess to minimize memory usage
            }
        }
        catch (Exception ex) when (!(ex is OutOfMemoryException))
        {
            // Handle exceptions other than out of memory gracefully
            throw new InvalidOperationException("An error occurred during SQL execution.", ex);
        }
    }
}
```

### Key Points:
- **Thread Safety**: The lock around environment variable setting ensures thread safety.
- **Resource Management**: `SequentialAccess` is used to minimize memory usage by reading data in a streaming manner.
- **Error Handling**: Exceptions are caught and rethrown with additional context, except for `OutOfMemoryException`.
- **Environment Variable**: Ensures the directory path is stored once and reused efficiently.']

