#define MAX_BANDS 100
#define THRESHOLD 10

typedef struct {
    int RRC_VERSION;
    int *supported_bands;
    size_t band_count;
} UECapabilityRequest;

typedef struct {
    UECapabilityRequest *requests;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicUECapabilityList;

void init_list(DynamicUECapabilityList *list) {
    list->count = 0;
    list->capacity = THRESHOLD;
    list->requests = malloc(list->capacity * sizeof(UECapabilityRequest));
    if (!list->requests) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(DynamicUECapabilityList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->requests[i].supported_bands);
    }
    free(list->requests);
    pthread_mutex_destroy(&list->lock);
}

static void resize_list_if_needed(DynamicUECapabilityList *list) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        UECapabilityRequest *new_requests = realloc(list->requests, new_capacity * sizeof(UECapabilityRequest));
        if (!new_requests) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        list->requests = new_requests;
        list->capacity = new_capacity;
    }
}

void add_request(DynamicUECapabilityList *list, int rrc_version, size_t band_count, const int *bands) {
    pthread_mutex_lock(&list->lock);

    resize_list_if_needed(list);

    UECapabilityRequest req;
    req.RRC_VERSION = rrc_version;
    req.supported_bands = malloc(band_count * sizeof(int));
    if (!req.supported_bands) {
        perror("Failed to allocate memory for bands");
        pthread_mutex_unlock(&list->lock);
        exit(EXIT_FAILURE);
    }
    memcpy(req.supported_bands, bands, band_count * sizeof(int));
    req.band_count = band_count;

    list->requests[list->count++] = req;

    pthread_mutex_unlock(&list->lock);
}

void populate_randomly(DynamicUECapabilityList *list) {
    srand(time(NULL));

    for (size_t i = 0; i < THRESHOLD; ++i) {
        int rrc_version = rand() % 5 + 1;
        size_t band_count = rand() % MAX_BANDS + 1;
        int *bands = malloc(band_count * sizeof(int));
        if (!bands) {
            perror("Failed to allocate memory for bands");
            continue;
        }
        for (size_t j = 0; j < band_count; ++j) {
            bands[j] = rand() % MAX_BANDS + 1;
        }

        add_request(list, rrc_version, band_count, bands);
        free(bands);
    }
}

int main() {
    DynamicUECapabilityList list;
    init_list(&list);

    populate_randomly(&list);

    // Use the list...

    destroy_list(&list);
    return 0;
}
