#include <iostream>
#include <fstream>
#include <string>
#include <thread>
#include <mutex>
#include <chrono>
#include <atomic>
#include <tinyxml2.h> // Ensure TinyXML-2 library is included

struct GameConfig {
    int worldWidth;
    int worldHeight;
    int tileSize;
    float cameraSpeed;
};

std::atomic<GameConfig> currentConfig = {100, 100, 32, 5.0f};
std::mutex configMutex;

class Logger {
public:
    void log(const std::string& message) {
        std::lock_guard<std::mutex> lock(logMutex);
        std::cout << "[LOG] " << message << std::endl;
    }
private:
    std::mutex logMutex;
};

Logger logger;

void loadConfigFromFile(const std::string& filePath, GameConfig& config) {
    tinyxml2::XMLDocument doc;
    if (doc.LoadFile(filePath.c_str()) == tinyxml2::XML_SUCCESS) {
        auto* worldWidth = doc.FirstChildElement("Settings")->FirstChildElement("WorldWidth");
        auto* worldHeight = doc.FirstChildElement("Settings")->FirstChildElement("WorldHeight");
        auto* tileSize = doc.FirstChildElement("Settings")->FirstChildElement("TileSize");
        auto* cameraSpeed = doc.FirstChildElement("Settings")->FirstChildElement("CameraSpeed");

        if (worldWidth) config.worldWidth = std::stoi(worldWidth->GetText());
        if (worldHeight) config.worldHeight = std::stoi(worldHeight->GetText());
        if (tileSize) config.tileSize = std::stoi(tileSize->GetText());
        if (cameraSpeed) config.cameraSpeed = std::stof(cameraSpeed->GetText());

        logger.log("Configuration reloaded successfully.");
    } else {
        logger.log("Failed to load configuration file.");
    }
}

void reloadConfigPeriodically(const std::string& filePath) {
    GameConfig newConfig;
    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(5));
        loadConfigFromFile(filePath, newConfig);
        std::lock_guard<std::mutex> lock(configMutex);
        currentConfig = newConfig;
    }
}

class Character {
public:
    enum AttackType { ATTACK1, ATTACK2 };

private:
    AttackType lastAttack;
    std::chrono::time_point<std::chrono::steady_clock> lastAttackTime;

public:
    void performAttack() {
        auto now = std::chrono::steady_clock::now();
        if (std::chrono::duration_cast<std::chrono::seconds>(now - lastAttackTime).count() >= 9) {
            int attackChoice = rand() % 2;
            lastAttack = static_cast<AttackType>(attackChoice);
            logger.log("Attack performed: " + std::to_string(lastAttack));
            lastAttackTime = now;
        } else {
            logger.log("Attack on cooldown.");
        }
    }

    void update() {
        performAttack();
    }
};

void gameLoop(Character& character) {
    while (true) {
        std::lock_guard<std::mutex> lock(configMutex);
        GameConfig config = currentConfig.load();

        // Update game world using `config` and manage character behavior
        character.update();

        std::this_thread::sleep_for(std::chrono::milliseconds(16)); // Simulate frame rate (60 FPS)
    }
}

int main() {
    std::string configFilePath = "game_config.xml";

    Character playerCharacter;

    std::thread configThread(reloadConfigPeriodically, configFilePath);
    configThread.detach();

    gameLoop(playerCharacter);

    return 0;
}
