    $id = isset($_REQUEST['id']) ? (int)$_REQUEST['id'] : null;

    try {
        $pdo->beginTransaction();

        switch ($sub_action) {
            case SUB_ACTION_CREATE:
                if ($stmt = $pdo->prepare("INSERT INTO users (first_name, last_name, email, phone, address, dob) VALUES (:first_name, :last_name, :email, :phone, :address, :dob)")) {
                    $data['id'] = $pdo->lastInsertId();
                } else {
                    throw new Exception('Failed to prepare statement for user creation');
                }
                break;

            case SUB_ACTION_UPDATE:
                if ($stmt = $pdo->prepare("UPDATE users SET first_name=:first_name, last_name=:last_name, email=:email, phone=:phone, address=:address, dob=:dob WHERE id=:id")) {
                    $data['id'] = $id;
                } else {
                    throw new Exception('Failed to prepare statement for user update');
                }
                break;

            case SUB_ACTION_DELETE:
                if ($stmt = $pdo->prepare("DELETE FROM users WHERE id=:id")) {
                    $data['id'] = $id;
                } else {
                    throw new Exception('Failed to prepare statement for user deletion');
                }
                break;

            case SUB_ACTION_RETRIEVE:
                if ($stmt = $pdo->prepare("SELECT * FROM users WHERE id=:id")) {
                    $stmt->execute([':id' => $id]);
                    $data = $stmt->fetch(PDO::FETCH_ASSOC);
                } else {
                    throw new Exception('Failed to prepare statement for user retrieval');
                }
                break;

            default:
                return jsonResponse('Invalid sub_action', null, false);
        }

        if (isset($stmt) && !$stmt->execute($data)) {
            throw new Exception('Database operation failed');
        }

        $pdo->commit();

        // Return appropriate response based on action
        if ($sub_action === SUB_ACTION_RETRIEVE || $sub_action === SUB_ACTION_UPDATE || $sub_action === SUB_ACTION_CREATE) {
            return jsonResponse('Operation successful', ['data' => $data], true);
        } elseif ($sub_action === SUB_ACTION_DELETE) {
            return jsonResponse('User deleted successfully', null, true);
        }
    } catch (Exception $e) {
        $pdo->rollBack();
        return jsonResponse($e->getMessage(), null, false);
    }

    function validateWithExternalService($data) {
