} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_valid(NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Implement validation logic
    return pdu.RX_UE_INFORMATION_TAG > 0 && pdu.RNTI > 0 && pdu.CRC_INDICATION_REL8_TAG > 0;
}

void add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!is_valid(data)) return;

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void remove_node(LinkedList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    Node **current = &list->head;
    while (*current) {
        if ((*current)->data.RNTI == RNTI) {
            Node *to_delete = *current;
            *current = to_delete->next;
            free(to_delete);
            list->count--;
            break;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_list(LinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        callback(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* to_free = current;
        current = current->next;
        free(to_free);
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void resize_list(LinkedList* list) {
    // Implement resizing logic if needed
}

int compare_rnti(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_a = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pdu_b = (NFAPI_CRC_INDICATION_PDU_T*)b;
    return (pdu_a->RNTI - pdu_b->RNTI);
}

void sort_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node** array = (Node**)malloc(list->count * sizeof(Node*));
    Node* current = list->head;
    size_t i = 0;

    while (current) {
        array[i++] = current;
        current = current->next;
    }

    qsort(array, list->count, sizeof(Node*), compare_rnti);

    for (size_t j = 0; j < list->count - 1; ++j) {
        array[j]->next = array[j + 1];
    }
    if (list->count > 0) {
        array[list->count - 1]->next = NULL;
    }

    list->head = array[0];

    free(array);

    pthread_mutex_unlock(&list->lock);
}

void example_callback(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RNTI: %d\n", pdu->RNTI);
}
