    if (!node) return NULL;
    node->key = connection_id;
    node->value = info;
    node->next = NULL;
    return node;
}

void insert_or_update(TCP_CONNECTION_INFO info) {
    unsigned int index = hash_function(info.connection_id);
    Node* head = hash_table[index];

    // Lock-free insertion or update
    while (1) {
        for (Node* current = head; current != NULL; current = current->next) {
            if (current->key == info.connection_id) {
                memcpy(&current->value, &info, sizeof(TCP_CONNECTION_INFO));
                return;
            }
        }

        Node* new_node = create_node(info.connection_id, info);
        if (!new_node) return;

        new_node->next = head;
        if (__sync_bool_compare_and_swap((void**)&hash_table[index], (void*)head, (void*)new_node)) {
            return;
        } else {
            free(new_node); // CAS failed; free node and retry
        }
    }
}

// Logging function
void log_connection_info(TCP_CONNECTION_INFO info, int verbose) {
    if (!verbose) return;

    printf("Connection ID: %u\n", info.connection_id);
    printf("Source IP: %s\n", info.source_ip);
    printf("Destination IP: %s\n", info.dest_ip);
    printf("Sequence Number: %lu\n", info.sequence_number);
    printf("Ack Flag: %d\n", atomic_load(&info.ack_flag));
}

// Main function to initialize and populate TCP_CONNECTION_INFO array
void init_tcp_connections(TCP_CONNECTION_INFO* connections, size_t num_connections,
                          int verbose_logging) {
    for (size_t i = 0; i < num_connections; ++i) {
        uint32_t connection_id = i + 1;
        snprintf(connections[i].source_ip, sizeof(connections[i].source_ip), "192.168.0.%u", rand() % 255);
        snprintf(connections[i].dest_ip, sizeof(connections[i].dest_ip), "10.0.0.%u", rand() % 255);
        connections[i].connection_id = connection_id;
        connections[i].sequence_number = (uint64_t)rand() << 32 | rand();
        atomic_store(&connections[i].ack_flag, 0);

        insert_or_update(connections[i]);

        if (verbose_logging) {
            log_connection_info(connections[i], verbose_logging);
        }
    }
}

// Usage example
int main() {
    TCP_CONNECTION_INFO connections[MAX_CONNECTIONS];
    memset(hash_table, 0, sizeof(hash_table));

    init_tcp_connections(connections, MAX_CONNECTIONS, 1);

    return 0;
}
