    free(offsets.data);
    free(keys.data);
    free(records.data);

    return 0;
}

// Initialize dynamic array with specified capacity and element size
int init_dynamic_array(DynamicArray* arr, size_t initial_capacity, size_t element_size) {
    arr->data = malloc(initial_capacity * element_size);
    if (!arr->data) return -1;

    arr->element_size = element_size;
    arr->capacity = initial_capacity;
    arr->size = 0;
    return 0; // Success
}

// Resize dynamic array if needed (double the capacity)
void resize_dynamic_array_if_needed(DynamicArray* arr) {
    if (arr->size >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        void* new_data = realloc(arr->data, new_capacity * arr->element_size);
        if (!new_data) return; // Memory allocation failure

        arr->data = new_data;
        arr->capacity = new_capacity;
    }
}

// Add a record to the dynamic array
int add_record(DynamicArray* records, int value, char status_flag) {
    resize_dynamic_array_if_needed(records);

    Record* record_ptr = (Record*)(records->data + records->size * records->element_size);
    record_ptr->value = value;
    record_ptr->creation_time = time(NULL);  // Log creation time
    record_ptr->status_flag = status_flag;

    records->size++;
    return 0; // Success
}
