#define UPPER_THRESHOLD 1000
#define LOWER_THRESHOLD 10
#define MAX_RETRY_INTERVAL 64
#define LOGGING_SERVICE_BATCH_SIZE 50

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Probabilistically set to 0 or 1
