} NetworkEventRecord;

pthread_mutex_t event_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void *network_function(void *arg);
int validate_and_populate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int index);
double calculate_event_severity();
void retry_messaging_with_backoff(int *retry_count);

void log_message(const char *message) {
