    return rand() % (UPPER_THRESHOLD + 1);
}

void *network_function(void *arg) {
    int N = *(int *)arg;
    if (N < LOWER_THRESHOLD || N > UPPER_THRESHOLD) {
        log_message("Event count is out of threshold limits, handling gracefully.");
        N = max(min(N, UPPER_THRESHOLD), LOWER_THRESHOLD);
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        log_message("Memory allocation failed for PDU list.");
        return NULL;
    }

    pthread_mutex_lock(&event_lock);

    NetworkEventRecord *record_array = calloc(N, sizeof(NetworkEventRecord));
    if (!record_array) {
        free(pdu_list);
        log_message("Memory allocation failed for event records.");
        pthread_mutex_unlock(&event_lock);
        return NULL;
    }

    int retry_count = 0;

    // Simulate handling of network events
    for (int i = 0; i < N; i++) {
        if (!validate_and_populate_pdu(&pdu_list[i], i)) {
            log_message("Validation failed, skipping event.");
            continue;
        }

        NetworkEventRecord record = {
            .EventID = i,
            .Timestamp = time(NULL),
            .EventType = "NetworkEvent",
            .EventSeverity = calculate_event_severity()
        };

        memcpy(&record_array[i], &record, sizeof(NetworkEventRecord));

        retry_messaging_with_backoff(&retry_count);
    }

    // Integrate with external logging service (batch process)
    for (int i = 0; i < N; i += LOGGING_SERVICE_BATCH_SIZE) {
        int batch_size = min(N - i, LOGGING_SERVICE_BATCH_SIZE);
        log_message("Batch sending to logging service.");

        // Simulate potential delay or failure
        if (rand() % 10 < 2) {  // 20% chance of failure
            log_message("Logging service temporarily unavailable. Buffering data.");
            continue;
        }

        for (int j = 0; j < batch_size; ++j) {
            log_message("Sending record to logging service.");
        }
    }

    free(pdu_list);
    free(record_array);

    pthread_mutex_unlock(&event_lock);

    return NULL;
}

int validate_and_populate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int index) {
    if (pdu == NULL) return 0;

    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rand() % 500;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 200;

    // Probabilistic setting of CRCFLAG
    pdu->CRCFLAG = (rand() % 10) < 7 ? 1 : 0; // 70% chance to set to 1

    return 1;
}

double calculate_event_severity() {
    return rand() / (double)(RAND_MAX) * 10.0; // Example severity calculation
}

void retry_messaging_with_backoff(int *retry_count) {
    int base_interval = 1;
    for (*retry_count = 0; *retry_count < MAX_RETRY_INTERVAL; ++(*retry_count)) {
        if (rand() % 2 == 0) { // Simulate success with a simple probability
            return;
        }

        int sleep_time = base_interval << *retry_count; // Exponential backoff
        usleep(sleep_time * 1000);
    }

    log_message("Max retries reached for messaging.");
}

int main() {
    srand(time(NULL));

    pthread_t threads[5];
    int event_counts[] = {20, 500, 800, 1200, 50};

