#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

// Assuming these are defined somewhere in your project
typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to simulate fetching RNTI values from an external source
bool fetch_RNTI(unsigned int* rnti) {
    // Simulate a delay or failure in fetching RNTI
    if (rand() % 10 < 2) { // 20% chance of failure
        return false;
    }
    *rnti = rand() % 10000 + 1; // Random RNTI value for simplicity
    return true;
}

Node* populate_nfa_crc_indication_list(size_t max_size) {
    if (max_size == 0) return NULL;

    Node* head = NULL;
    Node* tail = NULL;
    unsigned int prev_rnti = 0;
    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < max_size; ++i) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed at node %zu\n", i);
            break;
        }

        // Generate unique RX_UE_INFORMATION_TAG
        new_node->data.RX_UE_INFORMATION_TAG = rand();

        unsigned int rnti;
        do {
            if (!fetch_RNTI(&rnti)) {
                fprintf(stderr, "Failed to fetch RNTI for node %zu\n", i);
                free(new_node);
                return head; // Return partially built list
            }
        } while (rnti == prev_rnti); // Ensure no consecutive nodes have the same RNTI

        new_node->data.RNTI = rnti;
        new_node->data.crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG
        prev_rnti = rnti;

        if (!head) {
            head = new_node;
        } else {
            tail->next = new_node;
        }
        tail = new_node;
    }

    return head;
}

void print_nfa_crc_indication_list(Node* head) {
    Node* current = head;
    while (current) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.crc_indication_rel8_tag.CRCFLAG);
        current = current->next;
    }
}

void free_nfa_crc_indication_list(Node* head) {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    size_t max_size = 10; // Example maximum size
    Node* list = populate_nfa_crc_indication_list(max_size);

    if (list) {
        print_nfa_crc_indication_list(list);
        free_nfa_crc_indication_list(list);
    }

    return 0;
}
