                try {
                    const response = await axios.get(`https://external-api.com/books/${encodeURIComponent(book)}`);

                    // Assume the API returns a 'valid' field to indicate canonical books
                    if (response.data.valid) {
                        apiResultsCache[book] = true;
                    } else {
                        delete bookOccurrences[book];
                    }
                } catch (error) {
                    console.error(`Error validating book "${book}":`, error.message);
                    // Optional: Implement retry logic or other error handling here
                }
            }
        }
    }

    await validateAndEnhanceBookNames();

    const endProcessingTime = performance.now();

    // Logging metrics such as processing time, memory usage (optional), and throughput
    console.log(`Text Processing Time: ${endProcessingTime - startProcessingTime}ms`);
    console.log('Memory Usage:', process.memoryUsage());
    console.log('Throughput:', Object.keys(bookOccurrences).length);

    return bookOccurrences;
}

