function generateTOC(sections) {
    // Helper function to create nested list items for sections and subsections
    function renderSection(section) {
        const listItem = document.createElement('li');

        // Create anchor element to navigate to section and back to top
        const anchorToSection = document.createElement('a');
        anchorToSection.href = `#${section.id}`;
        anchorToSection.textContent = section.title;
        anchorToSection.setAttribute('aria-label', `Go to ${section.title}`);
        listItem.appendChild(anchorToSection);

        // Anchor element for navigating back to the top
        const anchorToTop = document.createElement('a');
        anchorToTop.href = '#top';
        anchorToTop.textContent = '↥ Back to Top';
        anchorToTop.style.marginLeft = '10px';
        listItem.appendChild(anchorToTop);

        // Check if there are subsections and recursively create nested list items
        if (section.subsections && section.subsections.length > 0) {
            const sublist = document.createElement('ul');

            section.subsections.forEach(subsection => {
                const subItem = renderSection(subsection);
                sublist.appendChild(subItem);
            });

            listItem.appendChild(sublist);
        }

        return listItem;
    }

    // Create the main TOC element
    const tocContainer = document.createElement('nav');
    tocContainer.setAttribute('aria-label', 'Table of Contents');

    const tocList = document.createElement('ul');
    sections.forEach(section => {
        const sectionItem = renderSection(section);
        tocList.appendChild(sectionItem);
    });

    // Add a link to the top at the beginning for better usability
    const anchorToTop = document.createElement('a');
    anchorToTop.href = '#top';
    anchorToTop.textContent = '⬆️ Back to Top';
    tocContainer.appendChild(anchorToTop);

    tocList.setAttribute('id', 'toc-list');
    tocContainer.appendChild(tocList);

    // Return the rendered HTML as a string
    const containerDiv = document.createElement('div');
    containerDiv.appendChild(tocContainer);
    return containerDiv.innerHTML;
}

// Example usage:
const sections = [
    { title: "Introduction", id: "intro" },
    {
        title: "Chapter 1",
        id: "chapter-1",
        subsections: [
            { title: "Section 1.1", id: "section-1-1" },
            { title: "Section 1.2", id: "section-1-2" }
        ]
    },
    { title: "Conclusion", id: "conclusion" }
];

document.body.innerHTML = generateTOC(sections);
