#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

// Define the necessary structures with alignment considerations.
typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Cache structure for RNTIs using LRU eviction policy.
#define CACHE_SIZE 1000

typedef struct CacheEntry {
    unsigned int rnti;
    struct CacheEntry* prev;
    struct CacheEntry* next;
} CacheEntry;

typedef struct {
    CacheEntry* head;
    CacheEntry* tail;
    unsigned int size;
    CacheEntry** map;
} LRUCache;

LRUCache* createCache() {
    LRUCache* cache = (LRUCACHE*)malloc(sizeof(LRUCache));
    cache->head = NULL;
    cache->tail = NULL;
    cache->size = 0;
    cache->map = (CacheEntry**)calloc(CACHE_SIZE, sizeof(CacheEntry*));
    return cache;
}

void putInCache(LRUCache* cache, unsigned int rnti) {
    CacheEntry* entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    entry->rnti = rnti;
    entry->prev = NULL;
    entry->next = cache->head;

    if (cache->size == CACHE_SIZE) {
        // Evict the least recently used RNTI.
        unsigned int old_rnti = cache->tail->rnti;
        CacheEntry* to_remove = cache->tail;
        cache->tail = cache->tail->prev;
        if (cache->tail != NULL) {
            cache->tail->next = NULL;
        }
        free(to_remove);
        cache->map[old_rnti % CACHE_SIZE] = NULL;
        cache->size--;
    }

    if (cache->head == NULL) {
        cache->tail = entry;
    } else {
        cache->head->prev = entry;
    }
    cache->head = entry;

    cache->map[rnti % CACHE_SIZE] = entry;
    cache->size++;
}

unsigned int getFromCache(LRUCache* cache, unsigned int rnti) {
    if (cache->map[rnti % CACHE_SIZE] == NULL) return 0; // Cache miss.

    CacheEntry* entry = cache->map[rnti % CACHE_SIZE];
    if (entry->prev != NULL) {
        entry->prev->next = entry->next;
    }
    if (entry->next != NULL) {
        entry->next->prev = entry->prev;
    }
    if (cache->head == entry) {
        cache->head = entry->next;
    } else {
        entry->prev = NULL;
    }

    entry->next = cache->head;
    if (cache->head != NULL) {
        cache->head->prev = entry;
    } else {
        cache->tail = entry;
    }
    cache->head = entry;

    return entry->rnti;
}

// Function to generate NFAPI_CRC_INDICATION_PDU_T structures.
void generateNFAPICRCIndicationPDU(unsigned int numStructures) {
    if (numStructures <= 0) return;

    // Create and initialize the cache for RNTI values.
    LRUCache* rntiCache = createCache();

    NFAPI_CRC_INDICATION_PDU_T* pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Performance measurement start
    clock_t startTime = clock();
    srand(time(NULL));

    for (unsigned int i = 0; i < numStructures; ++i) {
        // Simulate fetching RNTI from external source with caching.
        unsigned int rnti;
        if ((rnti = getFromCache(rntiCache, rand() % CACHE_SIZE)) == 0) { // Cache miss
            rnti = rand();  // Simulate retrieval from a database or external service.
            putInCache(rntiCache, rnti);
        }

        pduArray[i].ue_info_tag.RNTI = rnti;
        pduArray[i].ue_info_tag.crc_tag.CRCFLAG = (rand() % 2) ? true : false; // Randomly set CRCFLAG
    }

    // Performance measurement end
    clock_t endTime = clock();
    double totalTime = ((double)(endTime - startTime)) / CLOCKS_PER_SEC;
    printf("Time taken to populate structures: %.6f seconds\n", totalTime);

    // Cleanup
    free(pduArray);
    for (unsigned int i = 0; i < CACHE_SIZE && rntiCache->map[i] != NULL; ++i) {
        CacheEntry* entry = rntiCache->map[i];
        while (entry != NULL) {
            CacheEntry* toFree = entry;
            entry = entry->next;
            free(toFree);
        }
    }
    free(rntiCache->map);
    free(rntiCache);
}

int main() {
    unsigned int numStructures = 10000000; // Example size of 10 million
    generateNFAPICRCIndicationPDU(numStructures);
    return 0;
}
