['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int phrConfiguration;
    int mclTag;
    int ulPowerControl;
} LTE_PHY_Layer_Config;

typedef struct ListNode {
    LTE_PHY_Layer_Config config;
    struct ListNode *next;
    unsigned long version;  // Versioning for dependency management
} ListNode;

typedef struct {
    ListNode *head;
    pthread_rwlock_t lock;
} ListManager;

ListManager* create_list_manager() {
    ListManager *manager = malloc(sizeof(ListManager));
    if (!manager) return NULL;

    manager->head = NULL;
    pthread_rwlock_init(&manager->lock, NULL);
    return manager;
}

int add_configuration(ListManager *manager, LTE_PHY_Layer_Config config) {
    ListNode *new_node = malloc(sizeof(ListNode));
    if (!new_node) return -1;

    new_node->config = config;
    new_node->next = NULL;
    new_node->version = 0; // Initial version

    pthread_rwlock_wrlock(&manager->lock);

    if (manager->head == NULL) {
        manager->head = new_node;
    } else {
        ListNode *current = manager->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_rwlock_unlock(&manager->lock);
    return 0;
}

int remove_configuration(ListManager *manager, int index) {
    if (!manager || index < 0) return -1;

    pthread_rwlock_wrlock(&manager->lock);

    ListNode **indirect = &manager->head;
    while (*indirect && index > 0) {
        indirect = &(*indirect)->next;
        index--;
    }

    if (*indirect == NULL) {
        pthread_rwlock_unlock(&manager->lock);
        return -1; // Index out of range
    }

    ListNode *to_remove = *indirect;
    *indirect = to_remove->next;
    free(to_remove);

    pthread_rwlock_unlock(&manager->lock);
    return 0;
}

void update_configuration(ListManager *manager, int index, LTE_PHY_Layer_Config new_config) {
    if (!manager || index < 0) return;

    pthread_rwlock_wrlock(&manager->lock);

    ListNode *current = manager->head;
    while (current && index > 0) {
        current = current->next;
        index--;
    }

    if (current) {
        current->config = new_config;
        current->version++; // Increment version for dependency management
    }

    pthread_rwlock_unlock(&manager->lock);
}

void iterate_and_process(ListManager *manager, void (*process)(LTE_PHY_Layer_Config*)) {
    if (!manager || !process) return;

    pthread_rwlock_rdlock(&manager->lock);

    ListNode *current = manager->head;
    while (current) {
        process(&(current->config));
        current = current->next;
    }

    pthread_rwlock_unlock(&manager->lock);
}

void free_list_manager(ListManager *manager) {
    if (!manager) return;

    pthread_rwlock_wrlock(&manager->lock);

    ListNode *current = manager->head;
    while (current) {
        ListNode *temp = current;
        current = current->next;
        free(temp);
    }

    manager->head = NULL;

    pthread_rwlock_unlock(&manager->lock);
    pthread_rwlock_destroy(&manager->lock);
    free(manager);
}

// Sample process function
void sample_process(LTE_PHY_Layer_Config* config) {
    printf("PHR: %d, MCL: %d, UL Power Control: %d\n", 
           config->phrConfiguration, config->mclTag, config->ulPowerControl);
}

int main() {
    ListManager *manager = create_list_manager();

    LTE_PHY_Layer_Config config1 = {10, 20, 30};
    add_configuration(manager, config1);

    LTE_PHY_Layer_Config config2 = {15, 25, 35};
    add_configuration(manager, config2);

    iterate_and_process(manager, sample_process);

    update_configuration(manager, 0, (LTE_PHY_Layer_Config){12, 22, 32});

    iterate_and_process(manager, sample_process);

    remove_configuration(manager, 1);

    iterate_and_process(manager, sample_process);

    free_list_manager(manager);

    return 0;
}
```

### Explanation:

- **ListManager**: A structure to manage the list with a read-write lock (`pthread_rwlock_t`) for concurrency.

- **add_configuration**: Adds a new configuration and locks the list for writing.

- **remove_configuration**: Removes a configuration at a specified index, safely handling concurrent access.

- **update_configuration**: Updates a specific configuration and increments its version to manage dependencies.

- **iterate_and_process**: Iterates over configurations using a read lock to ensure concurrency.

- **free_list_manager**: Cleans up resources, ensuring the list is locked for writing during cleanup.

This implementation addresses scalability, concurrency, error handling, maintainability, and performance constraints.']

