    if (temp_keys == NULL) {
        fprintf(stderr, "Failed to generate keys.\n");
        goto cleanup;
    }

    // Remove duplicates while maintaining order
    int *unique_keys = malloc(sizeof(int) * num_offsets);
    if (!unique_keys) {
        perror("Memory allocation for unique keys failed.");
        goto cleanup;
    }

    size_t key_index = 0;
    for (size_t i = 0; i < num_offsets; ++i) {
        int is_duplicate = 0;
        for (size_t j = 0; j < key_index; ++j) {
            if (unique_keys[j] == temp_keys[i]) {
                is_duplicate = 1;
                break;
            }
        }
        if (!is_duplicate) {
            unique_keys[key_index++] = temp_keys[i];
        }
    }

    keys = realloc(unique_keys, sizeof(int) * key_index);
    if (!keys) {
        perror("Memory reallocation for keys failed.");
        goto cleanup;
