int initializeAndConnect(NFAPI_CRC_INDICATION_PDU_T **array, size_t num_entries, const char *remote_address, 
                         int port, int verbose_logging) {
    if (num_entries <= 0 || !array || !remote_address) {
        return -1; // Error: Invalid input
    }

