            (*array)[i].CRC_INDICATION_REL8_TAG[j] = (unsigned char)(i ^ j);
        }
        (*array)[i].checksum_validation_flag = i % 2;

        if (verbose_logging) {
            printf("Initialized entry %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n",
                   i, (*array)[i].RX_UE_INFORMATION_TAG, (*array)[i].RNTI);
        }
    }

    // Connection status and metadata
    int connection_status = 0; // Assume 0 for success, non-zero for failure

    try {
        // Java part for handling the channel connection
        SocketChannel socketChannel = SocketChannel.open();
        socketChannel.configureBlocking(false);

        Selector selector = Selector.open();
        socketChannel.register(selector, SelectionKey.OP_CONNECT);

        InetSocketAddress remoteAddr = new InetSocketAddress(remote_address, port);
        socketChannel.connect(remoteAddr);

        if (verbose_logging) {
            System.out.println("Attempting to connect to " + remote_address + ":" + port);
        }

        while (!socketChannel.finishConnect()) {
            // Implement a backoff strategy for retries
            try {
                selector.select(1000); // 1 second timeout
            } catch (IOException e) {
                if (verbose_logging) {
                    System.err.println("Selection error: " + e.getMessage());
                }
                connection_status = -2; // Connection failure
                break;
            }

            for (SelectionKey key : selector.selectedKeys()) {
                if (key.isConnectable() && socketChannel.isConnectionPending()) {
                    if (!socketChannel.finishConnect()) {
                        continue;
                    } else {
                        key.interestOps(SelectionKey.OP_READ);
                        if (verbose_logging) {
                            System.out.println("Connected to " + remote_address + ":" + port);
                        }
                    }
                }
            }

            selector.selectNow(); // Handle dynamic adjustment
        }
    } catch (IOException e) {
        perror("Java connection error: " + e.getMessage());
        connection_status = -3; // IO exception during connection setup
    }

    return connection_status;
}
