typedef struct {
    time_t timestamp;
    pid_t process_id;
    double probability;
} record;

// Function prototypes
void* initialize_data(size_t num_records, char** buffer);
void cleanup(void* offsets, int* identifiers, record* records, char* buffer);

// Global mutex for thread safety (assuming shared resources)
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* initialize_data(size_t num_records, char** buffer) {
    if (num_records == 0 || num_records > 1024) return NULL;

    size_t offset_size = sizeof(long) * num_records;
    size_t identifier_size = sizeof(int) * num_records;
    size_t record_size = sizeof(record) * num_records;

    // Allocate memory for arrays
    long* offsets = (long*)malloc(offset_size);
    int* identifiers = (int*)malloc(identifier_size);
    record* records = (record*)malloc(record_size);

    if (!offsets || !identifiers || !records) {
        free(offsets); free(identifiers); free(records);
        return NULL;
    }

    // Initialize offsets
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = (long)i;
    }

    srand(time(NULL));

    // Initialize identifiers and records
    for (size_t i = 0; i < num_records; ++i) {
        identifiers[i] = rand() % 1000 + 1;

        records[i].timestamp = time(NULL);
        records[i].process_id = getpid();
        records[i].probability = ((double)rand()) / RAND_MAX;
    }

    // Calculate buffer size
    size_t min_buffer_size = 1024;
    size_t max_buffer_size = 8192;
    size_t record_serialized_size = snprintf(NULL, 0, "%ld %d %f", 
                                             records[0].timestamp, 
                                             records[0].process_id, 
                                             records[0].probability);
    size_t buffer_size = num_records * (record_serialized_size + 1); // +1 for null termination
    buffer_size = buffer_size < min_buffer_size ? min_buffer_size : (buffer_size > max_buffer_size ? max_buffer_size : buffer_size);

    // Allocate and serialize into buffer
    char* buf = (char*)malloc(buffer_size);
    if (!buf) {
        free(offsets); free(identifiers); free(records);
        return NULL;
    }

    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < num_records; ++i) {
        snprintf(buf + i * record_serialized_size, buffer_size - (i * record_serialized_size), "%ld %d %f", 
                 records[i].timestamp, 
                 records[i].process_id, 
                 records[i].probability);
    }
    buf[buffer_size - 1] = '\0'; // Ensure null-termination
    pthread_mutex_unlock(&lock);

    *buffer = buf;
    return (void*)offsets;
}

void cleanup(void* offsets, int* identifiers, record* records, char* buffer) {
    free((long*)offsets);
    free(identifiers);
    free(records);
    free(buffer);
}
