#define MAX_MEMORY_USAGE 1024 * 1024 // 1MB limit for demonstration

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[256];
    int checksum_valid; // Flag indicating if the checksum is valid
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int get_dynamic_latency() {
    return rand() % 100 + 1; // Simulate latency in ms
}

char* generate_crc_tag(int tag_length) {
    char *tag = (char *)malloc(tag_length);
    if (!tag) return NULL;

    for (int i = 0; i < tag_length - 1; ++i) {
        tag[i] = 'A' + rand() % 26;
    }
    tag[tag_length - 1] = '\0'; // Null-terminate the string
    return tag;
}

void simulate_packet_loss(int *tag) {
    if (rand() % 10 < 2) { // Simulate a 20% packet loss rate
        memset(tag, 0, sizeof(*tag));
    }
}

int validate_checksum(const char* crc_tag) {
    int sum = 0;
    for (const char* p = crc_tag; *p != '\0'; ++p) {
        sum += *p;
    }
    return sum % 256 == 0; // Simple checksum validation
}

void log_verbose(NFAPI_CRC_INDICATION_PDU_T pdu, int verbose) {
    if (!verbose) return;
    printf("RX_UE_INFORMATION_TAG: %d\n", pdu.RX_UE_INFORMATION_TAG);
    printf("RNTI: %d\n", pdu.RNTI);
    printf("CRC_INDICATION_REL8_TAG: %s\n", pdu.CRC_INDICATION_REL8_TAG);
    printf("Checksum Valid: %d\n", pdu.checksum_valid);
}

void* validate_crc_integrity(void *data) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)data;
    int i;

    pthread_mutex_lock(&mutex);

    for (i = 0; i < MAX_MEMORY_USAGE / sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i) {
        if (!validate_checksum(pdu_array[i].CRC_INDICATION_REL8_TAG)) {
            printf("Discrepancy found in tag %d\n", i);
            pdu_array[i].checksum_valid = 0;
        }
    }

    pthread_mutex_unlock(&mutex);

    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* initialize_nfaapi_crc_pdu_array(size_t n, int verbose) {
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_t validation_thread;

    for (size_t i = 0; i < n; ++i) {
        pthread_mutex_lock(&mutex);

        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand();

        int latency = get_dynamic_latency();
        char *crc_tag = generate_crc_tag(255);

        if (!crc_tag) {
            perror("CRC Tag generation failed");
            free(array);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        simulate_packet_loss((int*)crc_tag);

        strncpy(array[i].CRC_INDICATION_REL8_TAG, crc_tag, sizeof(array[i].CRC_INDICATION_REL8_TAG));
        array[i].checksum_valid = validate_checksum(crc_tag);

        free(crc_tag);

        log_verbose(array[i], verbose);

        pthread_mutex_unlock(&mutex);
    }

    if (pthread_create(&validation_thread, NULL, validate_crc_integrity, (void *)array) != 0) {
        perror("Failed to create validation thread");
        free(array);
        return NULL;
    }

    pthread_detach(validation_thread); // Detach so it cleans up after itself

    return array;
}

int main() {
    size_t num_pdus = 100;
    int verbose_logging = 1;

    NFAPI_CRC_INDICATION_PDU_T *pdus = initialize_nfaapi_crc_pdu_array(num_pdus, verbose_logging);

    if (pdus) {
        free(pdus); // Clean up allocated memory
    }

    return 0;
}
