#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define TABLE_SIZE 1024

typedef struct record {
    long offset;
    int key;
    double value;
    char *name;
} record;

typedef struct hash_table_entry {
    int key;
    record *data;
    struct hash_table_entry *next;
} hash_table_entry;

hash_table_entry **hash_table = NULL;
pthread_mutex_t table_lock[TABLE_SIZE];

void initialize_hash_table(size_t size) {
    hash_table = calloc(size, sizeof(hash_table_entry *));
    if (!hash_table) exit(EXIT_FAILURE);

    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_init(&table_lock[i], NULL);
        hash_table[i] = NULL;
    }
}

unsigned int hash_function(int key) {
    return key % TABLE_SIZE;
}

record* create_record(int key, double min_value, double max_value) {
    record *new_record = malloc(sizeof(record));
    if (!new_record) exit(EXIT_FAILURE);

    new_record->offset = rand();
    new_record->key = key;
    new_record->value = (double)rand() / RAND_MAX * (max_value - min_value) + min_value;

    // Simulate network call for string assignment
    int retries = 3;
    while (retries--) {
        // Placeholder for actual network call
        char *name_buffer = malloc(20);
        if (!name_buffer) continue; // Retry on allocation failure

        snprintf(name_buffer, 20, "Name_%d", key);
        new_record->name = name_buffer;
        return new_record;
    }

    free(new_record);
    return NULL;
}

void insert_record(record *new_record) {
    unsigned int index = hash_function(new_record->key);
    pthread_mutex_lock(&table_lock[index]);

    hash_table_entry *entry = hash_table[index];
    while (entry) {
        if (entry->key == new_record->key) {
            free(entry->data->name);
            entry->data = new_record;
            pthread_mutex_unlock(&table_lock[index]);
            return;
        }
        entry = entry->next;
    }

    entry = malloc(sizeof(hash_table_entry));
    if (!entry) {
        free(new_record->name);
        free(new_record);
        pthread_mutex_unlock(&table_lock[index]);
        exit(EXIT_FAILURE);
    }

    entry->key = new_record->key;
    entry->data = new_record;
    entry->next = hash_table[index];
    hash_table[index] = entry;

    pthread_mutex_unlock(&table_lock[index]);
}

record* lookup_record(int key) {
    unsigned int index = hash_function(key);
    pthread_mutex_lock(&table_lock[index]);

    hash_table_entry *entry = hash_table[index];
    while (entry) {
        if (entry->key == key) {
            record *res = entry->data;
            pthread_mutex_unlock(&table_lock[index]);
            return res;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&table_lock[index]);
    return NULL;
}

void free_records(size_t size) {
    for (size_t i = 0; i < size; ++i) {
        hash_table_entry *entry = hash_table[i];
        while (entry) {
            hash_table_entry *next = entry->next;

            free(entry->data->name);
            free(entry->data);

            free(entry);
            entry = next;
        }

        pthread_mutex_destroy(&table_lock[i]);
    }
    free(hash_table);
}

void manage_dynamic_dataset(int num_records, double min_value, double max_value) {
    initialize_hash_table(TABLE_SIZE);

    for (int i = 0; i < num_records; ++i) {
        record *new_record = create_record(i, min_value, max_value);
        if (!new_record) continue;
        insert_record(new_record);
    }

    // Example usage
    int key_to_lookup = 5;
    record *retrieved = lookup_record(key_to_lookup);
    if (retrieved) {
        printf("Record found: Key=%d, Value=%.2f, Name=%s\n", retrieved->key, retrieved->value, retrieved->name);
    } else {
        printf("Record not found for key %d\n", key_to_lookup);
    }

    free_records(TABLE_SIZE);
}

int main() {
    srand(time(NULL));
    manage_dynamic_dataset(1000, 1.0, 10.0);
    return 0;
}
```

