```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_ELEMENTS 1000

typedef struct {
    int valid_RX_UE_INFORMATION_TAG; // Example type, replace as necessary
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t lock;
} NFAPIDynamicList;

// Initialize the dynamic list
void nfapi_list_init(NFAPIDynamicList* list) {
    list->count = 0;
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        list->elements[i] = NULL;
    }
    pthread_mutex_init(&list->lock, NULL);
}

// Add a new element to the list
bool nfapi_list_add(NFAPIDynamicList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (list->count >= MAX_ELEMENTS) return false;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        if (list->elements[i] == NULL) {
            list->elements[i] = pdu;
            list->count++;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }

    // Should never reach here due to check at the start
    pthread_mutex_unlock(&list->lock);
    return false;
}

// Remove an element by RNTI
bool nfapi_list_remove_by_rnti(NFAPIDynamicList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        if (list->elements[i] != NULL && list->elements[i]->RNTI == rnti) {
            free(list->elements[i]);
            list->elements[i] = NULL;
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return false;
}

// Retrieve an element by index
NFAPI_CRC_INDICATION_PDU_T* nfapi_list_get_by_index(NFAPIDynamicList* list, size_t index) {
    if (index >= list->count) return NULL;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* pdu = list->elements[index];

    pthread_mutex_unlock(&list->lock);
    return pdu;
}

// Cleanup the dynamic list
void nfapi_list_cleanup(NFAPIDynamicList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        if (list->elements[i] != NULL) {
            free(list->elements[i]);
            list->elements[i] = NULL;
        }
    }
    list->count = 0;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    NFAPIDynamicList list;
    nfapi_list_init(&list);

    NFAPI_CRC_INDICATION_PDU_T* pdu1 = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // Initialize pdu1 as needed
    if (nfapi_list_add(&list, pdu1)) {
        printf("PDU added successfully.\n");
    } else {
        printf("Failed to add PDU.\n");
    }

    // Further operations...

    nfapi_list_cleanup(&list);
    return 0;
}
```

### Explanation of Choices:
- **Mutex Locks**: The use of `pthread_mutex_t` ensures that the list is thread-safe. It locks critical sections, such as adding, removing, and retrieving elements to prevent race conditions.

- **Performance Consideration**: While mutexes introduce some overhead, they are simple and effective for this size of data structure. This choice balances performance with safety due to its relatively low contention in typical scenarios.

- **Error Handling**: The functions return `false` or `NULL` on errors (e.g., invalid index or RNTI) to allow the calling code to handle these gracefully without affecting other operations.

This implementation provides a thread-safe mechanism for managing a dynamic list with minimal performance overhead, appropriate for real-time processing environments.']

