#include <pthread.h>
#include <time.h>

typedef struct record {
    int key;
    long offset;
    struct record* next;
} record;

record *head = NULL;
pthread_mutex_t lock;

void init_random_seed() {
    srand(time(NULL));
}

int generate_unique_key(int min, int max) {
    int key = rand() % (max - min + 1) + min;
    pthread_mutex_lock(&lock);
    record *current = head;
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&lock);
            return generate_unique_key(min, max); // Retry with another key
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
    return key;
}

record* create_record(int min_key, int max_key, long offset_min, long offset_max) {
    record *new_record = (record*)malloc(sizeof(record));
    if (!new_record) {
        perror("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }

    new_record->key = generate_unique_key(min_key, max_key);
    new_record->offset = rand() % (offset_max - offset_min + 1) + offset_min;
    new_record->next = NULL;

    pthread_mutex_lock(&lock);
    if (!head) {
        head = new_record;
    } else {
        record *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }
    pthread_mutex_unlock(&lock);

    return new_record;
}

void delete_record(int key) {
    pthread_mutex_lock(&lock);
    record **curr = &head, *temp;
    while (*curr) {
        if ((*curr)->key == key) {
            temp = *curr;
            *curr = (*curr)->next;
            free(temp); // Free the memory
            printf("Record with key %d deleted\n", key); // Log deletion
            break;
        }
        curr = &((*curr)->next);
    }
    pthread_mutex_unlock(&lock);
}

