```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_BATCH_SIZE 1000
#define TIMEOUT_MS 5000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    int success;
    unsigned long memory_usage;
    time_t start_time;
} BatchInfo;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

BatchInfo* create_batch(size_t batch_size) {
    BatchInfo* batch = (BatchInfo*)malloc(sizeof(BatchInfo));
    if (!batch) return NULL;

    batch->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(batch_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!batch->data) {
        free(batch);
        return NULL;
    }

    batch->size = batch_size;
    batch->success = 1;
    batch->memory_usage = (unsigned long)batch->data * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    batch->start_time = time(NULL);

    return batch;
}

void destroy_batch(BatchInfo* batch) {
    if (batch) {
        free(batch->data);
        free(batch);
    }
}

int process_batch(BatchInfo* batch) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < batch->size; ++i) {
        batch->data[i].RX_UE_INFORMATION_TAG = rand() % 65536;
        batch->data[i].RNTI = rand() % 65536;
        batch->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        if (batch->data[i].RX_UE_INFORMATION_TAG == 0 && 
            batch->data[i].RNTI == 0 &&
            batch->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG == 0) {
            batch->success = 0;
            break;
        }
    }

    pthread_mutex_unlock(&lock);

    time_t current_time = time(NULL);
    if (difftime(current_time, batch->start_time) > TIMEOUT_MS / 1000.0) {
        batch->success = 0;
    }

    return batch->success;
}

void log_batch(BatchInfo* batch, int success) {
    printf("Batch processed: %s\n", success ? "SUCCESS" : "FAILED");
    printf("Memory Usage: %lu bytes\n", batch->memory_usage);
    if (!success) {
        printf("Error: Batch processing failed or timed out.\n");
    }
}

void* batch_worker(void* arg) {
    BatchInfo* batch = (BatchInfo*)arg;
    int success = process_batch(batch);
    log_batch(batch, success);
    destroy_batch(batch);
    return NULL;
}

int main() {
    srand(time(NULL));

    size_t num_batches = 10; // Example number of batches
    pthread_t threads[num_batches];

    for (size_t i = 0; i < num_batches; ++i) {
        BatchInfo* batch = create_batch(MAX_BATCH_SIZE);
        if (!batch) {
            fprintf(stderr, "Failed to allocate memory for batch %zu\n", i);
            continue;
        }

        pthread_create(&threads[i], NULL, batch_worker, (void*)batch);
    }

    for (size_t i = 0; i < num_batches; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

