#include <stdbool.h>

// Define the structure for CRC indication PDU
typedef struct {
    uint16_t valid_RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG; // Randomly set CRC flag
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for managing list with thread safety and dynamic updates
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    uint16_t rnti_min_range;
    uint16_t rnti_max_range;
} CRC_INDICATOR_LIST;

// Function to initialize the list
void init_list(CRC_INDICATOR_LIST *list, size_t initial_capacity) {
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to resize the dynamic array
void ensure_capacity(CRC_INDICATOR_LIST *list) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data) {
            list->data = new_data;
            list->capacity = new_capacity;
        }
    }
}

// Function to add a valid structure
bool add_crc_indication_pdu(CRC_INDICATOR_LIST *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (pdu.RNTI < list->rnti_min_range || pdu.RNTI > list->rnti_max_range) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
    }

    ensure_capacity(list);

    // Add the new PDU
    list->data[list->count++] = pdu;

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Function to sort and retrieve structures based on RNTI ranges
void get_sorted_pdus(CRC_INDICATOR_LIST *list, uint16_t rnti_min, uint16_t rnti_max,
                     NFAPI_CRC_INDICATION_PDU_T **output, size_t *count) {
    pthread_mutex_lock(&list->lock);

    // Temporary buffer for valid PDUs
    size_t output_count = 0;
    while (output_count < list->count && ((NFAPI_CRC_INDICATION_PDU_T *)output)->RNTI <= rnti_max) {
        if ((*output)->RNTI >= rnti_min) {
            (*output)[output_count++] = (*output)[++(*count)];
        }
    }

    // Sort the valid PDUs by RNTI
    qsort((*output), output_count, sizeof(NFAPI_CRC_INDICATION_PDU_T), 
          [](const void *a, const void *b) -> int {
              return ((NFAPI_CRC_INDICATION_PDU_T *)a)->RNTI - ((NFAPI_CRC_INDICATION_PDU_T *)b)->RNTI;
          });

    pthread_mutex_unlock(&list->lock);
}

// Function to free the list
void free_list(CRC_INDICATOR_LIST *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
}

// Utility function for setting a random CRCFLAG
void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->CRCFLAG = rand() % 2;
}
