unsigned int hash_function(unsigned int rnti) {
    return (rnti * 2654435761U) % HASH_SIZE;
}

// Function to check and insert RNTI into the hash table
int is_rnti_unique(unsigned int rnti, unsigned char hash_table[HASH_SIZE]) {
    if (hash_table[hash_function(rnti)] == 0) {
        hash_table[hash_function(rnti)] = 1;
        return 1; // Unique
    }
    return 0; // Duplicate
}

// Function to generate a random RX_UE_INFORMATION_TAG
