#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 1000
#define MAX_THREADS 10
#define LOGGING_INTERVAL 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

pthread_mutex_t rnti_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;
unsigned long used_rntis[MAX_STRUCTURES] = {0};
int created_structures = 0;
int logging_countdown = LOGGING_INTERVAL;

void *populate_structure(void *arg) {
    MemoryPool *mp = (MemoryPool *)arg;
    NFAPI_CRC_INDICATION_PDU_T *structure = NULL;

    while (1) {
        pthread_mutex_lock(&rnti_lock);
        if (created_structures >= mp->pool_size) {
            pthread_mutex_unlock(&rnti_lock);
            break;
        }

        int is_unique_rnti_found = 0;
        for (int i = 0; i < MAX_STRUCTURES && !is_unique_rnti_found; ++i) {
            unsigned long rnti = rand() % (1 << 16); // Example range for RNTI
            for (size_t j = 0; j < created_structures; ++j) {
                if (mp->pool[j].RNTI == rnti) {
                    goto retry;
                }
            }
            is_unique_rnti_found = 1;

            structure = &mp->pool[created_structures++];
            structure->RX_UE_INFORMATION_TAG = rand() % 100; // Example valid range
            structure->RNTI = rnti;
            structure->CRC_INDICATION_REL8_TAG = rand() % 10; // Example valid range
            structure->CRCFLAG = rand() % 2;

            pthread_mutex_unlock(&rnti_lock);

            // Log performance metrics every LOGGING_INTERVAL structures
            if (created_structures % LOGGING_INTERVAL == 0) {
                printf("Created %d structures\n", created_structures);
            }
            return NULL;
        retry:;
        }
        pthread_mutex_unlock(&rnti_lock);
    }

    return NULL;
}

void initialize_memory_pool(MemoryPool *mp, size_t pool_size) {
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mp->pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    mp->pool_size = pool_size;
    pthread_mutex_init(&mp->lock, NULL);
}

void free_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

int main() {
    srand(time(NULL));

    MemoryPool mp;
    initialize_memory_pool(&mp, MAX_STRUCTURES);

    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        if (thread_count < MAX_THREADS && created_structures < MAX_STRUCTURES) {
            pthread_create(&threads[thread_count++], NULL, populate_structure, &mp);
        } else {
            for (int j = 0; j < thread_count; ++j) {
                pthread_join(threads[j], NULL);
            }
            thread_count = 0;
        }
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("All structures created. Total: %d\n", created_structures);

    free_memory_pool(&mp);

    return 0;
}
```

This code defines a multi-threaded C program that creates and populates an array of `NFAPI_CRC_INDICATION_PDU_T` structures with unique `RNTI` values, randomly set `CRCFLAG`, and valid other fields. It uses a memory pool to manage structure allocation efficiently and logs performance metrics periodically. The code ensures thread safety using mutexes and handles resource management by limiting the number of concurrent threads.']

