#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>

#define MAX_LINE_LENGTH 256

typedef struct {
    time_t timestamp;
    int sensor_id;
    float temperature;
} SensorData;

typedef struct {
    SensorData *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

// Function prototypes
DynamicArray* create_dynamic_array();
void destroy_dynamic_array(DynamicArray *array);
int read_csv_file(const char *filepath, DynamicArray *array);
int load_remote_data(DynamicArray *array);
int sort_sensor_data(DynamicArray *array, int by_temperature_desc);

// CSV reading and parsing function
int parse_csv_line(char *line, SensorData *sensor) {
    return sscanf(line, "%ld,%d,%f", &sensor->timestamp, &sensor->sensor_id, &sensor->temperature) == 3;
}

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    pthread_mutex_init(&array->lock, NULL);
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;

    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->data);
    free(array);
}

int read_csv_file(const char *filepath, DynamicArray *array) {
    FILE *file = fopen(filepath, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    pthread_mutex_lock(&array->lock);

    while (1) {
        if (array->size == array->capacity) {
            size_t new_capacity = array->capacity == 0 ? 10 : array->capacity * 2;
            SensorData *new_data = realloc(array->data, new_capacity * sizeof(SensorData));
            if (!new_data) {
                perror("Failed to allocate memory");
                pthread_mutex_unlock(&array->lock);
                fclose(file);
                return -1;
            }
            array->data = new_data;
            array->capacity = new_capacity;
        }

        char line[MAX_LINE_LENGTH];
        if (fgets(line, MAX_LINE_LENGTH, file) == NULL) break;

        SensorData sensor;
        if (!parse_csv_line(line, &sensor)) {
            fprintf(stderr, "Malformed CSV line: %s", line);
            pthread_mutex_unlock(&array->lock);
            fclose(file);
            return -1;
        }

        array->data[array->size++] = sensor;
    }

    pthread_mutex_unlock(&array->lock);
    fclose(file);
    return 0;
}

int load_remote_data(DynamicArray *array) {
    // Placeholder for remote data loading logic
    // This function should be implemented to handle asynchronous data fetching
    return 0;
}

int sort_sensor_data(DynamicArray *array, int by_temperature_desc) {
    pthread_mutex_lock(&array->lock);

    qsort(array->data, array->size, sizeof(SensorData), (by_temperature_desc)
        ? [](const void *a, const void *b) -> int {
            SensorData sa = *(SensorData *)a;
            SensorData sb = *(SensorData *)b;
            return (sb.temperature - sa.temperature);
        }
        : [](const void *a, const void *b) -> int {
            SensorData sa = *(SensorData *)a;
            SensorData sb = *(SensorData *)b;
            if (sa.timestamp < sb.timestamp) return -1;
            if (sa.timestamp > sb.timestamp) return 1;
            return (sb.temperature - sa.temperature);
        });

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Usage example
int main() {
    DynamicArray *sensor_data_array = create_dynamic_array();
    if (!sensor_data_array) {
        fprintf(stderr, "Failed to create dynamic array\n");
        return EXIT_FAILURE;
    }

    // Example of reading from a local CSV file
    const char *csv_file_path = "./data/sensor_data.csv";
    if (read_csv_file(csv_file_path, sensor_data_array) != 0) {
        destroy_dynamic_array(sensor_data_array);
        return EXIT_FAILURE;
    }

    // Sort data by temperature in descending order
    sort_sensor_data(sensor_data_array, 1);

    // Clean up
    destroy_dynamic_array(sensor_data_array);
    return EXIT_SUCCESS;
}
