    if (pthread_create(&thread_id, NULL, periodic_update, (void*)structures)) {
        fprintf(stderr, "Error creating thread\n");
        free_structures(structures);
        return -1;
    }

    pthread_join(thread_id, NULL);

    free_structures(structures);
    free(dialog_fields);

