int* read_integers(int* size) {
    int capacity = 0;
    printf("Enter initial capacity: ");

    if (scanf("%d", &capacity) != 1 || capacity <= 0) {
        fprintf(stderr, "Invalid input for capacity.\n");
        exit(EXIT_FAILURE);
    }

    int *array = malloc(capacity * sizeof(int));
