        array[(*size)++] = value;

        if (*size == capacity) { // Resize when full
            int new_capacity = capacity * 2;
            int* temp_array = realloc(array, new_capacity * sizeof(int));

            if (!temp_array) {
                perror("Memory reallocation failed");
                free(array);
                exit(EXIT_FAILURE);
            }

            array = temp_array;
            capacity = new_capacity;
        }
    }

    // Ignore any remaining characters in input buffer
    while (getchar() != '\n');

    return array;
}

