NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_pdu_array(size_t count, 
                                                            allocation_callback callback) {
    if (callback == NULL) return NULL;

    pthread_mutex_lock(&allocation_mutex);

    // Dynamically allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_array) {
        callback(-1, NULL);  // Allocation failure
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Populate each structure in the array
    for (size_t i = 0; i < count; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 10000;  // Example range
        pdu_array[i].RNTI = rand() % 5000;  // Example range
        pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;  // Randomly set to 0 or 1
    }

    pthread_mutex_unlock(&allocation_mutex);

    callback(0, pdu_array);  // Allocation success

    return pdu_array;
}

void free_pdu_array(NFAPI_CRC_INDICATION_PDU_T* pdu_array) {
    if (pdu_array) {
        free(pdu_array);
    }
}

