NumberArray* create_number_array() {
    NumberArray* array = (NumberArray*)malloc(sizeof(NumberArray));
    if (!array) return NULL;
    array->numbers = NULL;
    array->count = 0;
    return array;
}

void free_number_array(NumberArray* array) {
    if (array) {
        free(array->numbers);
        free(array);
    }
}

int is_valid_number(const char *str, double *value) {
    char *endptr;
    errno = 0;
    *value = strtod(str, &endptr);
    if (errno == ERANGE || endptr == str || *endptr != '\0') {
        return 0; // Invalid number
    }
    return 1; // Valid number
}

double calculate_average(NumberArray* array) {
    double sum = 0.0;
    for (size_t i = 0; i < array->count; ++i) {
        sum += array->numbers[i];
    }
    return array->count > 0 ? sum / array->count : 0.0;
}

int count_integers(NumberArray* array) {
    int integer_count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if ((int)(array->numbers[i]) == array->numbers[i]) {
            ++integer_count;
        }
    }
    return integer_count;
}

void log_error(FILE *log_file, const char *message) {
    fprintf(log_file, "Error: %s\n", message);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <csv-file-path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *file_path = argv[1];
    FILE *input_file = fopen(file_path, "r");
    if (!input_file) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    FILE *error_log = fopen("error.log", "w");
    if (!error_log) {
        perror("Error opening error log file");
        fclose(input_file);
        return EXIT_FAILURE;
    }

    NumberArray* numbers = create_number_array();
    char line[MAX_LINE_LENGTH];
    double value;

    while (fgets(line, sizeof(line), input_file)) {
        char *token = strtok(line, ",");
        while (token) {
            if (is_valid_number(token, &value)) {
                numbers->numbers = realloc(numbers->numbers, (numbers->count + 1) * sizeof(double));
                if (!numbers->numbers) {
                    fprintf(stderr, "Memory allocation failed\n");
                    free_number_array(numbers);
                    fclose(input_file);
                    fclose(error_log);
                    return EXIT_FAILURE;
                }
                numbers->numbers[numbers->count++] = value;
            } else {
                log_error(error_log, token);
            }
            token = strtok(NULL, ",");
        }
    }

    double average = calculate_average(numbers);
    int integer_count = count_integers(numbers);

    printf("Average: %.2f\n", average);
    printf("Total Integers: %d\n", integer_count);

    free_number_array(numbers);
    fclose(input_file);
    fclose(error_log);

    return EXIT_SUCCESS;
}
