#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define MAX_EVENTS 1024
#define NUM_THREADS 4

typedef struct {
    int id;
    double latency;
    size_t data_size;
} NetworkEvent;

typedef struct {
    double throughput_threshold;
    double latency_threshold;
} Config;

Config config = {1000.0, 200.0}; // Example thresholds for throughput and latency
sem_t sem_event;
pthread_mutex_t mutex_metrics;
double total_throughput = 0;
double total_latency = 0;
size_t event_count = 0;

void* process_events(void* arg) {
    NetworkEvent events[MAX_EVENTS];

    while (1) {
        // Wait for new events
        sem_wait(&sem_event);

        pthread_mutex_lock(&mutex_metrics);

        size_t processed_count = 0;
        time_t start_time = time(NULL);
        for (size_t i = 0; i < MAX_EVENTS && processed_count < event_count; ++i) {
            NetworkEvent *event = &events[i];

            // Filtering events based on thresholds
            if (event->data_size > config.throughput_threshold || event->latency > config.latency_threshold) {
                total_throughput += event->data_size;
                total_latency += event->latency;
                processed_count++;
            }
        }

        time_t end_time = time(NULL);
        printf("Processed %zu events in %ld seconds\n", processed_count, end_time - start_time);

        // Reset metrics and count
        event_count = 0;

        pthread_mutex_unlock(&mutex_metrics);
    }

    return NULL;
}

void add_event(NetworkEvent *event) {
    sem_wait(&sem_event); // Acquire semaphore to ensure mutual exclusion

    static NetworkEvent events_buffer[MAX_EVENTS];
    static size_t buffer_index = 0;

    if (buffer_index < MAX_EVENTS) {
        events_buffer[buffer_index++] = *event;
        event_count++;

        if (event_count >= MAX_EVENTS - 1) {
            sem_post(&sem_event); // Signal that new data is available
        }
    } else {
        printf("Buffer full. Dropping event.\n"); // Implement backpressure handling
    }

    sem_post(&sem_event);
}

void initialize_system() {
    sem_init(&sem_event, 0, 1);
    pthread_mutex_init(&mutex_metrics, NULL);

    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, process_events, NULL);
    }
}

void cleanup_system() {
    sem_destroy(&sem_event);
    pthread_mutex_destroy(&mutex_metrics);

    // Join threads if necessary
}

int main() {
    initialize_system();

    NetworkEvent event1 = {1, 150.0, 500};
    NetworkEvent event2 = {2, 250.0, 1200};

    add_event(&event1);
    add_event(&event2);

    // Simulate running system
    sleep(5);

    cleanup_system();

    return 0;
}
```

### Key Points:
- The `process_events` function processes incoming events in a separate thread pool.
- Events are filtered based on configurable throughput and latency thresholds.
- A semaphore (`sem_event`) ensures that only one thread can add or process events at a time, implementing backpressure handling.
- Aggregated metrics (total throughput and latency) are calculated using a mutex to prevent data races.
- The `add_event` function adds events to a buffer and triggers processing when the buffer is nearly full. If the buffer overflows, it drops events to maintain system stability.

### Configuration:
Adjust the thresholds in the `Config` struct to filter events based on your requirements. Monitor memory usage and adjust `MAX_EVENTS` as needed for optimal performance under different load conditions.']

