['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // 1MB memory limit for demonstration

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int priority; // User-defined criteria
    NFAPI_CRC_INDICATION_PDU_T pdu;
} UE_Processing_Node;

// Priority queue node
typedef struct Node {
    UE_Processing_Node data;
    struct Node* next;
} Node;

// Priority queue structure
typedef struct {
    Node* head;
    pthread_mutex_t lock; // Minimal locking mechanism
} PriorityQueue;

PriorityQueue pq = {NULL, PTHREAD_MUTEX_INITIALIZER};

// Function prototypes
void enqueue(UE_Processing_Node node);
UE_Processing_Node dequeue();
NFAPI_CRC_INDICATION_PDU_T* createBatch(int batch_size);
void processBatch(NFAPI_CRC_INDICATION_PDU_T* batch, int size);
int getCurrentMemoryUsage();
void logPerformanceMetrics(const char* message);

// Priority queue functions
void enqueue(UE_Processing_Node node) {
    pthread_mutex_lock(&pq.lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = node;
    new_node->next = NULL;

    if (!pq.head || pq.head->data.priority < node.priority) {
        new_node->next = pq.head;
        pq.head = new_node;
    } else {
        Node* current = pq.head;
        while (current->next && current->next->data.priority >= node.priority) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&pq.lock);
}

UE_Processing_Node dequeue() {
    pthread_mutex_lock(&pq.lock);

    if (!pq.head) {
        pthread_mutex_unlock(&pq.lock);
        return (UE_Processing_Node){0};
    }

    Node* temp = pq.head;
    UE_Processing_Node node = temp->data;
    pq.head = pq.head->next;
    free(temp);

    pthread_mutex_unlock(&pq.lock);
    return node;
}

// Function to create and populate batch
