```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>

// Define constants for RNTI size
#define MAX_RNTI 65536

typedef struct {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    struct {
        bool CRCFLAG;
    } crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for RNTI tracking and thread safety
static uint16_t used_rntis[MAX_RNTI] = {0};
static pthread_mutex_t rnti_mutex = PTHREAD_MUTEX_INITIALIZER;

bool is_valid_rnti(uint16_t rnti) {
    return rnti != 0 && !used_rntis[rnti];
}

void mark_rnti_used(uint16_t rnti) {
    if (rnti < MAX_RNTI) {
        used_rntis[rnti] = 1;
    }
}

void unmark_rnti_used(uint16_t rnti) {
    if (rnti < MAX_RNTI) {
        used_rntis[rnti] = 0;
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(size_t count) {
    NFAPI_CRC_INDICATION_PDU_T *nfa_list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfa_list) {
        perror("Failed to allocate memory for NFA list");
        return NULL;
    }

    uint16_t last_rnti = 0;

    pthread_mutex_lock(&rnti_mutex);

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &nfa_list[i];

        // Generate valid RNTI
        uint16_t rnti;
        do {
            rnti = rand() % MAX_RNTI + 1; // Ensure non-zero RNTI
        } while (rnti == last_rnti || !is_valid_rnti(rnti));

        mark_rnti_used(rnti);
        pdu->rx_ue_information_tag = rand(); // Assuming some valid range or generation logic
        pdu->rnti = rnti;
        pdu->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG

        last_rnti = rnti;
    }

    pthread_mutex_unlock(&rnti_mutex);

    return nfa_list;
}

void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T *nfa_list, size_t count) {
    if (nfa_list) {
        // Unmark RNTIs before freeing
        pthread_mutex_lock(&rnti_mutex);
        for (size_t i = 0; i < count; ++i) {
            unmark_rnti_used(nfa_list[i].rnti);
        }
        pthread_mutex_unlock(&rnti_mutex);

        free(nfa_list);
    }
}

int main() {
    size_t list_size = 10;
    NFAPI_CRC_INDICATION_PDU_T *nfa_list = create_nfa_list(list_size);
    if (nfa_list) {
        // Use the nfa_list as needed
        free_nfa_list(nfa_list, list_size);
    }
    return 0;
}
```

### Key Points:
- **Thread Safety**: The function uses a mutex to ensure thread-safe access to the global `used_rntis` array.
- **Memory Management**: Allocates memory for the list and ensures it is freed properly, with RNTI values unmarked before deallocation.
- **Error Handling**: Checks for allocation failures and handles them gracefully.
- **Performance Considerations**: Uses efficient data structures and minimizes locking duration to optimize performance under concurrency.
- **Scalability**: The solution scales well by using a fixed-size array for tracking used RNTIs, which is efficient in terms of both speed and memory usage.']

