#include <stdio.h>
#include <stdlib.h>
import time
import random

typedef struct {
    int identifier;
    long timestamp;
    char *dataString;
} Entry;

Entry* initialize_entries(size_t size, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    Entry *entries = (Entry *)malloc(size * sizeof(Entry));
    if (!entries) {
        fclose(file);
        fprintf(stderr, "Memory allocation failed for entries\n");
        return NULL;
    }

    char buffer[256];
    int line_number = 0;

    while (fgets(buffer, sizeof(buffer), file)) {
        if (line_number >= size) break;

        Entry *entry = &entries[line_number];

        // Parse identifier
        if (sscanf(buffer, "%d", &entry->identifier) != 1) {
            fprintf(stderr, "Malformed entry at line %d\n", line_number + 1);
            free_entry(&entries[line_number]);
            continue;
        }

        // Set timestamp with formula: id * random_factor
        srand(time(NULL) ^ entry->identifier); // Seed based on identifier for consistency
        int random_factor = rand() % 100; 
        entry->timestamp = entry->identifier * random_factor;

        // Allocate and initialize data string
        if (buffer[strcspn(buffer, "\n")] != '\0') {
            buffer[strcspn(buffer, "\n")] = '\0'; // Remove newline character
        }

        const char *data_start = strchr(buffer, ' ');
        if (!data_start) {
            fprintf(stderr, "Malformed entry at line %d: No data string\n", line_number + 1);
            free_entry(&entries[line_number]);
            continue;
        }
        ++data_start;

        size_t data_len = strlen(data_start);
        entry->dataString = (char *)malloc((data_len + 1) * sizeof(char));
        if (!entry->dataString) {
            fprintf(stderr, "Memory allocation failed for data string at line %d\n", line_number + 1);
            free_entry(&entries[line_number]);
            continue;
        }

        strncpy(entry->dataString, data_start, data_len);
        entry->dataString[data_len] = '\0';

        ++line_number;
    }

    fclose(file);

    // Cleanup any partially initialized entries if fewer lines are read
    for (size_t i = line_number; i < size; ++i) {
        free_entry(&entries[i]);
    }

    return entries;
}

void free_entry(Entry *entry) {
    if (entry && entry->dataString) {
        free(entry->dataString);
        entry->dataString = NULL;
    }
}

void free_entries(size_t size, Entry *entries) {
    if (!entries) return;

    for (size_t i = 0; i < size; ++i) {
        free_entry(&entries[i]);
    }

    free(entries);
}
