// Define structures based on your specific needs

typedef struct {
    time_t timestamp;
} RX_UE_INFORMATION_TAG;

typedef uint16_t RNTI;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a dynamic list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t capacity;
    size_t count;
} NFAPIDynamicList;

// Initialize the list with an initial capacity
NFAPIDynamicList* nfapi_create_list(size_t initial_capacity) {
    NFAPIDynamicList *list = malloc(sizeof(NFAPIDynamicList));
    if (!list) return NULL;

    list->elements = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;

    return list;
}

// Add an element to the dynamic list
int nfapi_add_pdu(NFAPIDynamicList *list, RNTI rnti) {
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) return -1;

        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    // Populate a new element with current timestamp and random CRCFLAG
    NFAPI_CRC_INDICATION_PDU_T *pdu = &list->elements[list->count++];
    pdu->rx_ue_info_tag.timestamp = time(NULL);
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

    return 0;
}

// Free the dynamic list
void nfapi_free_list(NFAPIDynamicList *list) {
    if (list) {
        free(list->elements);
        free(list);
    }
}

// Serialize the list to a file
int nfapi_serialize_list(const NFAPIDynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&list->count, sizeof(size_t), 1, file);
    fwrite(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);

    fclose(file);
    return 0;
}

// Deserialize the list from a file
NFAPIDynamicList* nfapi_deserialize_list(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    NFAPIDynamicList *list = malloc(sizeof(NFAPIDynamicList));
    if (!list) {
        fclose(file);
        return NULL;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    list->elements = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        fclose(file);
        return NULL;
    }

    list->capacity = count;
    list->count = count;

    fread(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);

    fclose(file);
    return list;
}

// Validate the integrity of the list
int nfapi_validate_list(const NFAPIDynamicList *list) {
    if (!list || !list->elements) return -1;

    // Example validation: check for duplicate RNTI values
    for (size_t i = 0; i < list->count; ++i) {
        for (size_t j = i + 1; j < list->count; ++j) {
            if (list->elements[i].rnti == list->elements[j].rnti) {
                return -1; // Duplicate found
            }
        }
    }

    return 0;
}

int main() {
    srand((unsigned int)time(NULL)); // Seed the random number generator

    NFAPIDynamicList *list = nfapi_create_list(4);
    if (!list) return EXIT_FAILURE;

    nfapi_add_pdu(list, 1001);
    nfapi_add_pdu(list, 1002);

    nfapi_serialize_list(list, "nfa_list.dat");

    NFAPIDynamicList *loaded_list = nfapi_deserialize_list("nfa_list.dat");
    if (!loaded_list) return EXIT_FAILURE;

    if (nfapi_validate_list(loaded_list) == -1) {
        printf("Validation failed.\n");
    } else {
        printf("List is valid.\n");
    }

    nfapi_free_list(list);
    nfapi_free_list(loaded_list);

    return EXIT_SUCCESS;
}
