["```javascript
async function executeTestSuite(moduleName, testCases, mockResetStrategy, environmentConfig) {
    let module;
    const testResults = [];

    // Function to load a module with retry logic for network-related issues.
    async function loadModuleWithRetry() {
        try {
            if (!module) {
                module = await requireAsync(moduleName);
            }
            return module;
        } catch (error) {
            if (environmentConfig.retryCount > 0) {
                console.warn(`Retrying to load module ${moduleName}...`);
                environmentConfig.retryCount--;
                return await new Promise(resolve => setTimeout(() => resolve(loadModuleWithRetry()), environmentConfig.retryDelay));
            }
            throw new Error(`Failed to load module ${moduleName}: ${error.message}`);
        }
    }

    // Helper function to require a module asynchronously.
    async function requireAsync(name) {
        return new Promise((resolve, reject) => {
            try {
                resolve(require(name));
            } catch (err) {
                reject(err);
            }
        });
    }

    try {
        const loadedModule = await loadModuleWithRetry();

        for (const testCase of testCases) {
            let testName = testCase.name || 'Unnamed Test';
            console.log(`Running ${moduleName} - ${testName}`);

            let error;
            let passed = false;

            // Execute the test case with retry logic.
            for (let attempt = 0; attempt <= environmentConfig.retryCount; attempt++) {
                try {
                    const result = await testCase(loadedModule);
                    passed = result === true;
                    break;
                } catch (e) {
                    error = e.message || String(e);
                    if (attempt < environmentConfig.retryCount) {
                        console.warn(`Retrying test ${testName} due to failure: ${error}`);
                        await new Promise(resolve => setTimeout(resolve, environmentConfig.retryDelay));
                    }
                }
            }

            // Reset the mock after each test case.
            try {
                mockResetStrategy();
            } catch (resetError) {
                console.error(`Error during mock reset for test ${testName}: ${resetError.message}`);
            }

            const status = passed ? 'pass' : 'fail';
            console.log(`${moduleName} - ${testName}: ${status}`);

            testResults.push({
                testName,
                status,
                errorMessage: error || null
            });
        }
    } catch (loadError) {
        console.error(`Module load error for ${moduleName}: ${loadError.message}`);
        return { results: [{ testName: 'Module Load', status: 'fail', errorMessage: loadError.message }] };
    }

    return { results: testResults };
}
```

This code implements the `executeTestSuite` function according to the specified requirements. It handles dynamic module loading with retry logic, executes each test case while managing errors and retries, resets mocks after each test, logs detailed information about test execution, and returns an object containing test results. The implementation considers performance implications by using asynchronous operations and efficient data structures for storing results."]

['```c
#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG; // Assuming it includes a CRCFLAG value
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DynamicList;

bool is_valid_RX_UE_INFORMATION_TAG(int tag) {
    // Implement validation logic for RX_UE_INFORMATION_TAG
    return (tag > 0); // Example condition
}

bool is_valid_RNTI(int rnti) {
    // Implement validation logic for RNTI
    return (rnti > 0); // Example condition
}

void initialize_list(DynamicList *list, size_t initial_capacity) {
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void resize_list(DynamicList *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data != NULL) {
        list->data = new_data;
        list->capacity = new_capacity;
    }
}

void add_pdu(DynamicList *list, int rx_ue_tag, int rnti, int crcflag) {
    pthread_mutex_lock(&list->mutex);

    if (!is_valid_RX_UE_INFORMATION_TAG(rx_ue_tag) || !is_valid_RNTI(rnti)) {
        pthread_mutex_unlock(&list->mutex);
        return; // Invalid data
    }

    if (list->count == list->capacity) {
        resize_list(list);
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {rx_ue_tag, rnti, crcflag};
    list->data[list->count++] = pdu;

    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(DynamicList *list, size_t index) {
    pthread_mutex_lock(&list->mutex);

    if (index >= list->count) {
        pthread_mutex_unlock(&list->mutex);
        return NULL; // Invalid index
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &list->data[index];
    pthread_mutex_unlock(&list->mutex);
    return pdu;
}

size_t get_count(DynamicList *list) {
    size_t count;
    pthread_mutex_lock(&list->mutex);

    count = list->count;

    pthread_mutex_unlock(&list->mutex);
    return count;
}

void free_list(DynamicList *list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->data);
}
