['```c
#include <stdio.h>
#include <stdlib.h>
import time

typedef struct {
    int *array;
    size_t size;
    size_t capacity;
} IntStream;

int append_to_stream(IntStream *stream, int value) {
    if (stream->size == stream->capacity) {
        size_t new_capacity = (stream->capacity == 0) ? 1 : stream->capacity * 2;
        int *new_array = realloc(stream->array, new_capacity * sizeof(int));
        if (!new_array) return -1; // Memory allocation failed
        stream->array = new_array;
        stream->capacity = new_capacity;
    }
    stream->array[stream->size++] = value;
    return 0;
}

void find_and_print_largest(IntStream *stream) {
    if (stream->size == 0) {
        printf("No integers to process.\n");
        return;
    }

    int largest = stream->array[0];
    for (size_t i = 1; i < stream->size; ++i) {
        if (stream->array[i] > largest) {
            largest = stream->array[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

void calculate_and_print_average(IntStream *stream) {
    if (stream->size == 0) {
        printf("No integers to process.\n");
        return;
    }

    int sum = 0;
    for (size_t i = 0; i < stream->size; ++i) {
        sum += stream->array[i];
    }
    double average = (double)sum / stream->size;
    printf("Average: %.2f\n", average);
}

void track_and_report_positives_negatives(IntStream *stream) {
    int positives = 0, negatives = 0;
    for (size_t i = 0; i < stream->size; ++i) {
        if (stream->array[i] > 0) positives++;
        else if (stream->array[i] < 0) negatives++;
    }
    printf("Positives: %d, Negatives: %d\n", positives, negatives);
}

int read_stream(IntStream *stream, size_t max_memory, int log_stats) {
    int c;
    long num = 0;
    int sign = 1;
    time_t start_time, end_time;

    stream->array = NULL;
    stream->size = 0;
    stream->capacity = 0;

    if (log_stats) start_time = time(NULL);

    while ((c = getchar()) != EOF) {
        if (c == '-' && num == 0) {
            sign = -1;
        } else if (c >= '0' && c <= '9') {
            num = num * 10 + (c - '0');
        } else if (num != 0 || c == '-') {
            if (append_to_stream(stream, sign * num) == -1) return -1;

            num = 0;
            sign = 1;

            size_t current_memory_usage = stream->capacity * sizeof(int);
            if (current_memory_usage > max_memory) {
                printf("Memory limit exceeded.\n");
                free(stream->array);
                return -1;
            }
        }

        // Handle non-integer characters by resetting the number
        if ((c < '0' || c > '9') && c != '-' && num == 0) continue;
    }

    // Append last number if any
    if (num != 0) {
        if (append_to_stream(stream, sign * num) == -1) return -1;
    }

    if (log_stats) {
        end_time = time(NULL);
        printf("Processed %zu elements in %ld seconds.\n", stream->size, end_time - start_time);
    }

    return 0;
}

int main() {
    IntStream stream;
    size_t max_memory_threshold = 1024 * sizeof(int); // Example threshold
    int log_statistics = 1; // Log statistics or not

    if (read_stream(&stream, max_memory_threshold, log_statistics) == -1) {
        return EXIT_FAILURE;
    }

    find_and_print_largest(&stream);
    calculate_and_print_average(&stream);
    track_and_report_positives_negatives(&stream);

    free(stream.array);
    return EXIT_SUCCESS;
}
