// HTMLProcessor.js

class HTMLProcessor {
    constructor(htmlString) {
        this.doc = new DOMParser().parseFromString(htmlString, 'text/html');
    }

    traverseAndFilter(predicateFn) {
        const results = [];
        this._traverse(this.doc.body, predicateFn, results);
        return results;
    }

    _traverse(node, predicateFn, results) {
        if (node.nodeType === Node.ELEMENT_NODE && predicateFn(node)) {
            results.push(node);
        }
        node.childNodes.forEach(child => this._traverse(child, predicateFn, results));
    }

    filterByAttribute(attrName, attrValue = null) {
        return this.traverseAndFilter(node =>
            node.hasAttribute(attrName) &&
            (attrValue === null || node.getAttribute(attrValue) === attrValue)
        );
    }
}

// Usage Example
/*
const htmlContent = '<div><span id="test" class="example">Hello</span></div>';
const processor = new HTMLProcessor(htmlContent);

const elementsWithIdTest = processor.filterByAttribute('id', 'test');
console.log(elementsWithIdTest);

const elementsWithClassExample = processor.filterByAttribute('class');
console.log(elementsWithClassExample);
*/

export default HTMLProcessor;
```

