        this.RNTI = rnti;
    }
}

class Worker implements Runnable {
    private final List<NFAPI_CRC_INDICATION_PDU_T> pduList;
    private static final Random random = new Random();

    public Worker(List<NFAPI_CRC_INDICATION_PDU_T> pduList) {
        this.pduList = pduList;
    }

    @Override
    public void run() {
        try {
            int rxUeInformationTag = random.nextInt(1000); // Example value
            int rnti = random.nextInt(10000); // Example value

            for (int i = 0; i < 10; i++) { // Arbitrary number of instances per thread
                NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T(rxUeInformationTag, rnti);
                pdu.CRC_INDICATION_REL8_TAG = random.nextInt(100); // Example value
                pdu.CRCFLAG = random.nextBoolean();
                synchronized (pduList) {
                    pduList.add(pdu);
                }
            }

            sendMessage(pduList.size(), pduList);

        } catch (Exception e) {
            logException(e);
        }
    }

    private void sendMessage(int size, List<NFAPI_CRC_INDICATION_PDU_T> list) {
