        System.out.println("Message sent: " + size + " items, Status: Running");
    }

    private void logException(Exception e) {
        System.err.println("Exception occurred: " + e.getMessage());
    }
}

public class DynamicServiceManager {

    private ExecutorService executor;
    private boolean running = false;

    public void startService(int numThreads) {
        if (running) return;
        running = true;
        executor = Executors.newFixedThreadPool(numThreads);
        System.out.println("Service started with " + numThreads + " threads.");
    }

    public void stopService() throws InterruptedException {
        if (!running) return;
        running = false;
        List<NFAPI_CRC_INDICATION_PDU_T> pduList = new ArrayList<>();
        for (int i = 0; i < executor.getMaximumPoolSize(); i++) {
            executor.submit(new Worker(pduList));
        }
        executor.shutdown();
        if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
            System.err.println("Service did not terminate in the specified time.");
        }
        System.out.println("Service stopped.");
    }

    public void restartService() throws InterruptedException {
        stopService();
        Random random = new Random();
        int delay = random.nextInt(5000); // Random delay up to 5 seconds
        TimeUnit.MILLISECONDS.sleep(delay);
        startService(executor.getMaximumPoolSize());
    }

    public static void main(String[] args) {
        DynamicServiceManager manager = new DynamicServiceManager();
        try {
            manager.startService(10); // Start with 10 threads as an example
            TimeUnit.SECONDS.sleep(5); // Simulate service running for a while
            manager.restartService(); // Restart service with delay
            TimeUnit.SECONDS.sleep(5);
            manager.stopService(); // Stop the service
        } catch (InterruptedException e) {
            logException(e);
        }
    }

    private static void logException(Exception e) {
        System.err.println("Exception occurred: " + e.getMessage());
    }
}
