['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_SIZE 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG* crc_tag;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array[MAX_SIZE];
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray* da) {
    da->count = 0;
    pthread_mutex_init(&da->lock, NULL);
}

int random_crcflag() {
    return rand() % 2; // Randomly returns 0 or 1
}

// Error handling utility function for memory allocation
void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int insert_at_position(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T item, int position) {
    pthread_mutex_lock(&da->lock);

    if (da->count >= MAX_SIZE || position < 0 || position > da->count) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Error: array is full or invalid position
    }

    for (int i = da->count; i > position; --i) {
        da->array[i] = da->array[i - 1];
    }

    item.crc_tag = safe_malloc(sizeof(CRC_INDICATION_REL8_TAG));
    da->array[position] = &item;
    ++da->count;

    pthread_mutex_unlock(&da->lock);
    return 0; // Success
}

int remove_from_position(DynamicArray* da, int position) {
    pthread_mutex_lock(&da->lock);

    if (position < 0 || position >= da->count) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Error: invalid position
    }

    free(da->array[position]->crc_tag);
    for (int i = position; i < da->count - 1; ++i) {
        da->array[i] = da->array[i + 1];
    }

    da->array[da->count - 1] = NULL;
    --da->count;

    pthread_mutex_unlock(&da->lock);
    return 0; // Success
}

void free_dynamic_array(DynamicArray* da) {
    for (size_t i = 0; i < da->count; ++i) {
        free(da->array[i]->crc_tag);
    }
    pthread_mutex_destroy(&da->lock);
}

// Unit tests

#include <assert.h>

void test_insert_remove() {
    DynamicArray da;
    init_dynamic_array(&da);

    NFAPI_CRC_INDICATION_PDU_T item1 = { .CRCFLAG = random_crcflag() };
    insert_at_position(&da, item1, 0);
    assert(da.count == 1);

    NFAPI_CRC_INDICATION_PDU_T item2 = { .CRCFLAG = random_crcflag() };
    insert_at_position(&da, item2, 1);
    assert(da.count == 2);

    remove_from_position(&da, 0);
    assert(da.count == 1);

    remove_from_position(&da, 0);
    assert(da.count == 0);

    free_dynamic_array(&da);
}

void test_error_conditions() {
    DynamicArray da;
    init_dynamic_array(&da);

    NFAPI_CRC_INDICATION_PDU_T item = { .CRCFLAG = random_crcflag() };
    for (int i = 0; i < MAX_SIZE + 1; ++i) {
        int res = insert_at_position(&da, item, i);
        if (i >= MAX_SIZE) {
            assert(res == -1); // Expect failure on overflow
        } else {
            assert(res == 0); // Success within bounds
        }
    }

    remove_from_position(&da, MAX_SIZE);
    assert(da.count == 0);

    int res = remove_from_position(&da, 0);
    assert(res == -1); // Attempt to remove from empty array

    free_dynamic_array(&da);
}

int main() {
    srand(time(NULL));
    test_insert_remove();
    test_error_conditions();

    printf("All tests passed successfully!\n");
    return 0;
}
```

### Explanation:
- **DynamicArray**: Manages an array of `NFAPI_CRC_INDICATION_PDU_T` structures, with mutex for thread safety.
- **init_dynamic_array**, **insert_at_position**, and **remove_from_position** manage the dynamic array operations.
- **random_crcflag** generates a random CRC flag value.
- Error handling is implemented in memory allocation and insertion/removal checks.
- Unit tests verify functionality under normal and error conditions.']

