```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

bool is_duplicate_rnti(List* list, uint16_t rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) return true;
        current = current->next;
    }
    return false;
}

int add_pdu(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_LIST_SIZE) {
        printf("Error: List size exceeded maximum limit.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (is_duplicate_rnti(list, pdu.RNTI)) {
        printf("Duplicate RNTI detected. Skipping addition.\n");
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void update_externally(List* list, uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Simulate external data source update
    add_pdu(list, pdu);
}

int main() {
    List* nfa_list = create_list();

    if (!nfa_list) {
        printf("Failed to create list.\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T sample_pdu = { .RX_UE_INFORMATION_TAG = 123, .RNTI = 456, .CRC_INDICATION_REL8_TAG = 78, .CRCFLAG = true };

    update_externally(nfa_list, sample_pdu.RNTI, sample_pdu);

    free_list(nfa_list);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex` to ensure safe concurrent access.
- **Duplicate Handling**: Checks for duplicate RNTI before adding a new entry.
- **Error Handling**: Handles memory allocation failures and list size limits.
- **Memory Management**: Dynamically allocates nodes for linked list entries and frees them when done.
- **Logging**: Simple `printf` statements to log errors and actions. This can be expanded with more sophisticated logging mechanisms if needed.

This implementation uses a linked list, which is suitable for dynamic growth but may have performance implications due to poor cache locality compared to an array-based approach. However, it allows easy handling of varying data sizes without predefined limits.']

