        return;
    }

    // Adjust MTU based on network metrics
    config->mtu_size = (config->mtu_size > MAX_MTU_SIZE) ? MAX_MTU_SIZE : config->mtu_size;

    // Ensure IP versions are supported
    if (!(config->supported_ip_versions & (1 << 0)) && !(config->supported_ip_versions & (1 << 1))) {
        fprintf(stderr, "At least one of IPv4 or IPv6 must be supported.\n");
        return;
    }

    // Allocate PacketMetadata pool based on expected packet load
    metadata_count = expected_packet_load * 2; // Double for overhead handling
    pthread_mutex_lock(&lock);
    if (metadata_pool) {
        free(metadata_pool);
    }

    metadata_pool = (PacketMetadata *)malloc(sizeof(PacketMetadata) * metadata_count);
    if (!metadata_pool) {
        fprintf(stderr, "Memory allocation failed for PacketMetadata pool.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Initialize each PacketMetadata structure
    for (size_t i = 0; i < metadata_count; ++i) {
        metadata_pool[i].header = NULL; // Placeholder; actual header parsing logic needed.
        metadata_pool[i].flow_id.flow_id = rand() % ((1ULL << DEFAULT_FLOW_SEQ_NUM_BITS) - 1);
        metadata_pool[i].sequence_number = rand() % (UINT64_MAX + 1); 
        metadata_pool[i].timestamp = time(NULL);
        metadata_pool[i].checksum = compute_checksum(&metadata_pool[i]);
    }

    pthread_mutex_unlock(&lock);

    // Note: Further implementation would include dynamic rate limiting,
    // traffic prioritization adjustments based on load, and cleanup logic.
}

void free_resources() {
    if (metadata_pool) {
        free(metadata_pool);
        metadata_pool = NULL;
    }
}

