    unsigned short rnti;
    unsigned int crc_indication_rel8_tag;
} NFAPI_Packet;

void initialize_communication_framework(SystemSettings *settings, const char *hostname) {
    if (!settings || !hostname) return; // Basic error checking.

    settings->ciphers_supported = AES_ENCRYPTION | CHACHA20_ENCRYPTION;
    settings->digests_supported = SHA256_DIGEST | BLAKE2B_DIGEST;
    settings->offset_size = sizeof(size_t);
    settings->key_size = 32; // Example size for keys.
    settings->min_random_value = 0;
    settings->max_random_value = RAND_MAX;

    struct addrinfo hints, *res, *p;
    int status;
    unsigned char ip[INET6_ADDRSTRLEN] = {0};

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }
        inet_ntop(p->ai_family, addr, ip, sizeof(ip));
        break; // Use the first resolved address.
    }

    freeaddrinfo(res); // Free the linked list.

    printf("Resolved IP: %s\n", ip);

    // Setup random number generator.
    srand(time(NULL));

    // Example NFAPI Packet Initialization
    NFAPI_Packet packet = {
        .rx_ue_information_tag = 0x1234,
        .rnti = 0xABCD,
        .crc_indication_rel8_tag = rand() % (settings->max_random_value - settings->min_random_value + 1) + settings->min_random_value
    };

    // Example DataPacket allocation and setup.
    size_t packet_size = sizeof(DataPacket) + 1024; // Assume payload size of 1024 bytes.
    DataPacket *data_packet = (DataPacket *)malloc(packet_size);
    if (!data_packet) {
        fprintf(stderr, "Failed to allocate memory for data packet.\n");
        return;
    }

    memset(data_packet, 0, packet_size);
    data_packet->payload_length = 1024;
    data_packet->sequence_number = rand(); // Unique sequence number.

    // Calculate checksum (simple example)
    data_packet->checksum = 0; // Initialize checksum.
    for (size_t i = 0; i < data_packet->payload_length; ++i) {
        data_packet->checksum += ((unsigned char *)data_packet)[sizeof(DataPacket) + i];
    }

    // Free allocated resources on completion.
    free(data_packet);

    printf("Communication framework initialized.\n");
}
