    pthread_mutex_t listLock;  // To control access to the records array
} NFDataManager;

NFDataManager manager = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void* addOrUpdateNFDataRecord(void* arg) {
    NFDataRecord* recordToUpdate = (NFDataRecord*)arg;

    pthread_mutex_lock(&manager.listLock);
    if (manager.count >= MAX_RECORDS) {
        logPerformanceMetrics("Max records limit reached or exceeded.");
    }

    int found = 0;
    for (size_t i = 0; i < manager.count; ++i) {
        pthread_mutex_lock(&manager.records[i]->lock);
        if (manager.records[i]->rxUeInformationTag.rnti == recordToUpdate->rxUeInformationTag.rnti) {
            if (recordToUpdate->version > manager.records[i]->version) {
                *manager.records[i] = *recordToUpdate;
                found = 1;
            }
            pthread_mutex_unlock(&manager.records[i]->lock);
            break;
        }
        pthread_mutex_unlock(&manager.records[i]->lock);
    }

    if (!found) {
        if (manager.count < MAX_RECORDS) {
            manager.records = realloc(manager.records, sizeof(NFDataRecord*) * (manager.count + 1));
            manager.records[manager.count] = malloc(sizeof(NFDataRecord));
            memcpy(manager.records[manager.count], recordToUpdate, sizeof(NFDataRecord));
            pthread_mutex_init(&manager.records[manager.count]->lock, NULL);
            manager.count++;
        }
    }

    pthread_mutex_unlock(&manager.listLock);

    serializeRecords();
    sendNotification("Add/Update", recordToUpdate);
    return NULL;
}

void logPerformanceMetrics(const char* message) {
    FILE* logFile = fopen(LOG_FILE, "a");
    if (logFile) {
        time_t now = time(NULL);
        fprintf(logFile, "%s: %s\n", ctime(&now), message);
        fclose(logFile);
    }
}

void serializeRecords() {
    pthread_mutex_lock(&manager.listLock);
    FILE* file = fopen(PERSISTENCE_FILE, "wb");
    if (file) {
        fwrite(&manager.count, sizeof(size_t), 1, file);
        for (size_t i = 0; i < manager.count; ++i) {
            fwrite(manager.records[i], sizeof(NFDataRecord), 1, file);
        }
        fclose(file);
    }
    pthread_mutex_unlock(&manager.listLock);
}

void deserializeRecords() {
    FILE* file = fopen(PERSISTENCE_FILE, "rb");
    if (file) {
        fread(&manager.count, sizeof(size_t), 1, file);
        manager.records = malloc(sizeof(NFDataRecord*) * manager.count);
        for (size_t i = 0; i < manager.count; ++i) {
            manager.records[i] = malloc(sizeof(NFDataRecord));
            fread(manager.records[i], sizeof(NFDataRecord), 1, file);
            pthread_mutex_init(&manager.records[i]->lock, NULL);
        }
        fclose(file);
    }
}

void sendNotification(const char* operation, NFDataRecord* record) {
    // Simulate sending a notification (e.g., via an external messaging system)
    printf("Notification: %s operation for RNTI %d at version %u\n", 
           operation, record->rxUeInformationTag.rnti, record->version);
}

int main() {
    deserializeRecords();

    NFDataRecord newRecord = {1, {}, {}, {12345}, PTHREAD_MUTEX_INITIALIZER};
    pthread_t thread;
    pthread_create(&thread, NULL, addOrUpdateNFDataRecord, &newRecord);
    pthread_join(thread, NULL);

    serializeRecords();
    return 0;
}
```

### Key Features:

- **Concurrency Control**: Uses `pthread_mutex` for both record-level and list-level locking to handle concurrent access.

- **Persistence**: Serializes the records to a binary file for efficient storage and retrieval.

- **Performance Monitoring**: Logs performance metrics such as reaching max record limits to a log file.

- **External Messaging Simulation**: Simulates sending notifications on add/update operations.

- **Initialization/Serialization**: Deserializes existing data from a file upon startup and serializes changes back to the file. 

This implementation provides a foundation for managing `NFDataRecord` structures with concurrency, persistence, and performance considerations. Adjustments can be made based on specific system requirements or integration needs.']

