void manageMemory(int offsetCount, int minKey, int maxKey, int minValue, int maxValue, unsigned int seed) {
    // Initialize random number generator with the given seed
    srand(seed);

    long *offsetsArray = NULL;
    int *keysArray = NULL;
    record *recordsArray = NULL;

    // Allocate memory for offsetsArray and check for errors.
    offsetsArray = (long *)malloc(offsetCount * sizeof(long));
    if (!offsetsArray) {
        fprintf(stderr, "Memory allocation failed for offsetsArray.\n");
        return;
    }

    // Calculate keysArray size as offsetCount / 2
    int keysSize = offsetCount / 2;

    // Allocate memory for keysArray and check for errors.
    keysArray = (int *)malloc(keysSize * sizeof(int));
    if (!keysArray) {
        fprintf(stderr, "Memory allocation failed for keysArray.\n");
        free(offsetsArray);
        return;
    }

    // Allocate memory for recordsArray and check for errors.
    recordsArray = (record *)malloc(offsetCount * sizeof(record));
    if (!recordsArray) {
        fprintf(stderr, "Memory allocation failed for recordsArray.\n");
        free(offsetsArray);
        free(keysArray);
        return;
    }

    // Initialize offsetsArray with sequential values starting from 0
    for (int i = 0; i < offsetCount; ++i) {
        offsetsArray[i] = i;
    }

    // Initialize keysArray with unique random values within [minKey, maxKey]
    int *keyPresence = (int *)calloc(maxKey - minKey + 1, sizeof(int));
    if (!keyPresence) {
        fprintf(stderr, "Memory allocation failed for keyPresence.\n");
        free(offsetsArray);
        free(keysArray);
        free(recordsArray);
        return;
    }

    int keysGenerated = 0;
    while (keysGenerated < keysSize) {
        int randomKey = minKey + rand() % (maxKey - minKey + 1);

        // Ensure uniqueness of the key
        if (!keyPresence[randomKey - minKey]) {
            keysArray[keysGenerated++] = randomKey;
            keyPresence[randomKey - minKey] = 1;  // Mark as used
        }
    }

    free(keyPresence);  // Free temporary memory

    // Initialize recordsArray with random values within [minValue, maxValue]
    for (int i = 0; i < offsetCount; ++i) {
        recordsArray[i].value = minValue + rand() % (maxValue - minValue + 1);
    }

    // Simulate logging framework integration
    printf("Memory usage log: Successfully allocated and initialized arrays.\n");

    // Free all dynamically allocated memory
    free(offsetsArray);
    free(keysArray);
    free(recordsArray);

    // Logging framework cleanup simulation
    printf("Resources cleaned up successfully.\n");
}

// Example usage
int main() {
