['```c
#include <stdio.h>
#include <stdlib.h>
import threading

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    threading.Lock lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->head = array->tail = NULL;
    array->size = 0;
    threading.Lock_init(&array->lock);
    return array;
}

void free_node(Node* node) {
    if (node) {
        free(node);
    }
}

void insert(DynamicArray* array, int index, NFAPI_CRC_INDICATION_PDU_T item) {
    threading.Lock_lock(&array->lock);

    if (index < 0 || index > array->size) {
        printf("Index out of bounds\n");
        threading.Lock_unlock(&array->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        threading.Lock_unlock(&array->lock);
        return;
    }
    new_node->data = item;

    if (index == 0) {
        new_node->next = array->head;
        new_node->prev = NULL;
        if (array->head != NULL) {
            array->head->prev = new_node;
        } else {
            array->tail = new_node;
        }
        array->head = new_node;
    } else if (index == array->size) {
        new_node->next = NULL;
        new_node->prev = array->tail;
        if (array->tail != NULL) {
            array->tail->next = new_node;
        } else {
            array->head = new_node;
        }
        array->tail = new_node;
    } else {
        Node* current = array->head;
        for (int i = 0; i < index; ++i) {
            current = current->next;
        }
        new_node->prev = current->prev;
        new_node->next = current;
        current->prev->next = new_node;
        current->prev = new_node;
    }

    array->size++;
    threading.Lock_unlock(&array->lock);
}

NFAPI_CRC_INDICATION_PDU_T remove(DynamicArray* array, int index) {
    NFAPI_CRC_INDICATION_PDU_T item = {0};

    threading.Lock_lock(&array->lock);

    if (index < 0 || index >= array->size) {
        printf("Index out of bounds\n");
        threading.Lock_unlock(&array->lock);
        return item;
    }

    Node* current = array->head;
    for (int i = 0; i < index; ++i) {
        current = current->next;
    }

    if (current == array->head) {
        array->head = current->next;
        if (array->head != NULL) {
            array->head->prev = NULL;
        }
    } else {
        current->prev->next = current->next;
    }

    if (current == array->tail) {
        array->tail = current->prev;
        if (array->tail != NULL) {
            array->tail->next = NULL;
        }
    } else {
        current->next->prev = current->prev;
    }

    item = current->data;
    free_node(current);
    array->size--;

    threading.Lock_unlock(&array->lock);
    return item;
}

void destroy_dynamic_array(DynamicArray* array) {
    threading.Lock_lock(&array->lock);

    Node* current = array->head;
    while (current != NULL) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }

    threading.Lock_unlock(&array->lock);
    free(array);
}

int main() {
    DynamicArray* array = create_dynamic_array();
    if (!array) return -1;

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T item;
        item.RX_UE_INFORMATION_TAG = rand() % 100;
        item.RNTI = rand() % 100;
        item.CRC_INDICATION_REL8.CRCFLAG = rand() % 2;

        insert(array, i, item);
    }

    NFAPI_CRC_INDICATION_PDU_T removed_item = remove(array, MAX_ELEMENTS / 2);

    destroy_dynamic_array(array);

    return 0;
}
```

