['```cpp
#include <forward_list>
#include <mutex>
#include <random>
#include <string>

struct NFAPI_CRC_INDICATION_PDU_T {
    std::string RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
};

class UserManager {
public:
    UserManager(size_t n, const std::vector<std::string>& user_identities, int seed)
        : m_user_identities(user_identities), m_seed(seed) {
        initializeList(n);
    }

    void insertAfterUserTag(const std::forward_list<NFAPI_CRC_INDICATION_PDU_T>& list,
                            const std::string& firstString, const std::string& secondString) {
        std::lock_guard<std::mutex> lock(m_mutex);

        auto it = list.before_begin();
        for (auto curr_it = list.begin(); curr_it != list.end(); ++curr_it) {
            if (curr_it->RX_UE_INFORMATION_TAG == firstString) {
                m_pList.insert_after(curr_it, {secondString, generateRNTI(), getRandomCRCFlag()});
                break;
            }
            it = curr_it;
        }

        // If not found, insert at the end
        if (it != list.end()) {
            m_pList.insert_after(it, {secondString, generateRNTI(), getRandomCRCFlag()});
        }
    }

private:
    std::forward_list<NFAPI_CRC_INDICATION_PDU_T> m_pList;
    const std::vector<std::string>& m_user_identities;
    int m_seed;
    mutable std::mutex m_mutex;

    void initializeList(size_t n) {
        for (size_t i = 0; i < n && i < m_user_identities.size(); ++i) {
            m_pList.push_front({m_user_identities[i], generateRNTI(), getRandomCRCFlag()});
        }
    }

    int generateRNTI() {
        std::mt19937 gen(m_seed + rand());
        return gen();
    }

    bool getRandomCRCFlag() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::bernoulli_distribution dist(0.5);
        return dist(gen);
    }
};
```

