    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(list->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Function to resize the array
bool resize_list(NFList* list) {
    if (!list || !list->data) return false;

    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_data) return false;

    list->data = new_data;
    list->capacity = new_capacity;

    return true;
}

// Function to add an element
bool add_element(NFList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || !pdu) return false;

    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity && !resize_list(list)) {
        pthread_mutex_unlock(&list->lock);
