}

// Function to free the list
void destroy_list(NFList* list) {
    if (!list) return;

    pthread_mutex_destroy(&list->lock);
    free(list->data);
    free(list);
}

int main() {
    NFList* nf_list = create_list();
    if (!nf_list) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 100; ++i) { // Example: Adding 100 elements
        NFAPI_CRC_INDICATION_PDU_T pdu = {.valid_RX_UE_INFORMATION_TAG = i + 1};
        if (!add_element(nf_list, pdu)) {
            fprintf(stderr, "Failed to add element\n");
            destroy_list(nf_list);
            return EXIT_FAILURE;
        }
    }

    if (!validate_list(nf_list)) {
        fprintf(stderr, "Validation failed\n");
        destroy_list(nf_list);
        return EXIT_FAILURE;
    }

    printf("All elements added and validated successfully.\n");

    destroy_list(nf_list);

    return EXIT_SUCCESS;
}
