bool conditional_log(const char *message) {
#ifdef ENABLE_LOGGING
    printf("%s\n", message);
#endif
    return true; // Placeholder for a more complex logging mechanism.
}

void initialize_nfarray(NFArray *nfarray, size_t initial_size, bool (*log_callback)(const char*)) {
    nfarray->array = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfarray->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    nfarray->size = 0;
    nfarray->capacity = initial_size;
    pthread_mutex_init(&nfarray->lock, NULL);
    nfarray->log_callback = log_callback ? log_callback : conditional_log;

    if (nfarray->log_callback("NFArray initialized")) {
        // Logging success.
    }
}

void resize_nfarray(NFArray *nfarray) {
    size_t new_capacity = nfarray->capacity * 2;
    if (new_capacity > MAX_SIZE) {
        if (nfarray->log_callback("Reached maximum capacity limit")) {
            // Logging success.
        }
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(nfarray->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }

    nfarray->array = new_array;
    nfarray->capacity = new_capacity;

    if (nfarray->log_callback("NFArray resized")) {
        // Logging success.
    }
}

void add_to_nfarray(NFArray *nfarray, uint32_t rx_ue_info_tag, uint16_t rnti) {
    pthread_mutex_lock(&nfarray->lock);

    if (nfarray->size == nfarray->capacity) {
        resize_nfarray(nfarray);
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &nfarray->array[nfarray->size++];
    element->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    element->RNTI = rnti;
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

    pthread_mutex_unlock(&nfarray->lock);

    if (nfarray->log_callback("Element added to NFArray")) {
        // Logging success.
    }
}

void free_nfarray(NFArray *nfarray) {
    free(nfarray->array);
    pthread_mutex_destroy(&nfarray->lock);
    nfarray->array = NULL;
    nfarray->size = 0;
    nfarray->capacity = 0;

    if (nfarray->log_callback("NFArray freed")) {
        // Logging success.
    }
}

void update_ue_info_concurrently(NFArray *nfarray, uint32_t rx_ue_info_tag, uint16_t rnti) {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, (void *(*)(void *))add_to_nfarray, nfarray);
    pthread_join(thread_id, NULL);
}

int main() {
    srand(time(NULL));

    NFArray nfarray;
    initialize_nfarray(&nfarray, INITIAL_SIZE, conditional_log);

    // Simulate updates
    for (uint32_t i = 0; i < 50; ++i) { // More than initial size to trigger resizing
        update_ue_info_concurrently(&nfarray, i, rand() % 65535);
    }

    free_nfarray(&nfarray);
    return 0;
}
