// Function to generate a unique RNTI
int generate_unique_rnti(int *existing_rntis, int count) {
    const int max_rnti = 1023; // Assuming RNTI range is from 0 to 1023
    int rnti;
    do {
        rnti = rand() % (max_rnti + 1);
    } while (count > 0 && bsearch(&rnti, existing_rntis, count, sizeof(int), cmpfunc));
    return rnti;
}

// Comparator function for qsort and bsearch
int cmpfunc(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_pi_crc_array(int num_users, int *status) {
    if (num_users > 1000 || num_users <= 0) {
        *status = -1;
        log_event("Allocation failed: Number of users out of range.");
        return NULL;
    }

    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(num_users * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int *existing_rntis = malloc(num_users * sizeof(int));

    if (!array || !existing_rntis) {
        log_event("Allocation failed: Memory allocation error.");
        pthread_mutex_unlock(&mutex);
        free(array);
        free(existing_rntis);
        *status = -2;
        return NULL;
    }

    srand(time(NULL));  // Initialize random number generator
    for (int i = 0; i < num_users; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand();  // Assuming these values can be randomized
        array[i].RNTI = generate_unique_rnti(existing_rntis, i);
        if (array[i].RNTI == -1) {  // Failed to find a unique RNTI
            log_event("Allocation failed: Unable to allocate unique RNTIs.");
            free(array);
            free(existing_rntis);
            *status = -3;
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        existing_rntis[i] = array[i].RNTI;  // Store this RNTI as used

        array[i].CRC_INDICATION_REL8_TAG = rand();  // Assigning random value
        array[i].CRCFLAG = rand() % 2;  // Randomly setting CRCFLAG to 0 or 1
    }

    qsort(existing_rntis, num_users, sizeof(int), cmpfunc);  // Sort RNTIs for binary search efficiency

    free(existing_rntis);
    *status = 0;
    log_event("Allocation successful: Array populated successfully.");

    pthread_mutex_unlock(&mutex);
    return array;
}

