```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PduList;

PduList* createPduList() {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void appendToPduList(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = pdu;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

void freePduList(PduList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T generatePdu(uint16_t rnti, uint32_t timestamp) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = (uint16_t)(timestamp & 0xFFFF);
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    return pdu;
}

void logMessage(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

PduList* generateNfarApiPduList(uint16_t* rnti_list, size_t num_rntis, size_t num_pdus_to_generate) {
    if (rnti_list == NULL || num_rntis == 0 || num_pdus_to_generate == 0) {
        logMessage("Invalid input parameters.");
        return createPduList();
    }

    PduList* pduList = createPduList();
    uint32_t totalGenerationTime = 0;

    for (size_t i = 0; i < num_pdus_to_generate; ++i) {
        time_t startTime = time(NULL);

        if (i % num_rntis == 0 || num_rntis == 1) {
            size_t rntiIndex = rand() % num_rntis;
            uint32_t timestamp = (uint32_t)time(NULL);
            NFAPI_CRC_INDICATION_PDU_T pdu = generatePdu(rnti_list[rntiIndex], timestamp);

            appendToPduList(pduList, pdu);

            time_t endTime = time(NULL);
            totalGenerationTime += difftime(endTime, startTime);
        }
    }

    double averageTimePerPdu = (double)totalGenerationTime / num_pdus_to_generate;
    logMessage("Average time per PDU generation: ");
    printf("%.6f seconds\n", averageTimePerPdu);

    return pduList;
}

int main() {
    uint16_t rnti_list[] = {1001, 1002, 1003};
    size_t num_rntis = sizeof(rnti_list) / sizeof(rnti_list[0]);
    size_t num_pdus_to_generate = 10;

    PduList* pduList = generateNfarApiPduList(rnti_list, num_rntis, num_pdus_to_generate);

    // Example of how to use the generated list
    Node* current = pduList->head;
    while (current != NULL) {
        printf("RNTI: %d, CRCFLAG: %d\n", current->data.RNTI, current->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
        current = current->next;
    }

    freePduList(pduList);

    return 0;
}
```

### Key Points:
- **Thread Safety:** The function uses a mutex to ensure thread-safe operations on the linked list.
- **Logging:** Logs are printed with timestamps for tracking the generation process.
- **Error Handling:** Checks for invalid input parameters and logs an appropriate message.
- **Resource Management:** Ensures memory is allocated and freed properly, preventing leaks.
- **Performance Metrics:** Calculates and logs the average time taken to generate each PDU.']

