ConcurrentNFAPIList* initialize_list(size_t initial_capacity) {
    ConcurrentNFAPIList* list = (ConcurrentNFAPIList*) malloc(sizeof(ConcurrentNFAPIList));
    if (!list) {
        log_error("Failed to allocate memory for list");
        return NULL;
    }

    list->array = (NFAPI_CRC_INDICATION_PDU_T*) calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        free(list);
        log_error("Failed to allocate memory for NFAPI structures");
        return NULL;
    }

    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void populate_list(ConcurrentNFAPIList *list, size_t num_entries, uint16_t rnti_min, uint16_t rnti_max, uint32_t crc_threshold) {
    if (!list || !list->array) {
        log_error("Invalid list provided");
        return;
    }

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < num_entries; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *entry = &list->array[list->size];

        // Simulate RNTI value retrieval
        entry->RNTI = rnti_min + rand() % (rnti_max - rnti_min + 1);
        entry->RX_UE_INFORMATION_TAG = i; // Placeholder for actual tag

        // Randomly set CRCFLAG based on threshold
        entry->crcTag.CRCFLAG = ((double)rand() / RAND_MAX > crc_threshold) ? 0 : 1;

        list->size++;
    }

    pthread_mutex_unlock(&list->lock);
}

void cleanup_list(ConcurrentNFAPIList *list) {
    if (list) {
        free(list->array);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int main() {
    srand(time(NULL));

    size_t num_entries = 1000;
    uint16_t rnti_min = 1, rnti_max = 1000;
    uint32_t crc_threshold = 0.5;

    ConcurrentNFAPIList* list = initialize_list(num_entries);
    if (!list) {
        return EXIT_FAILURE;
    }

    populate_list(list, num_entries, rnti_min, rnti_max, crc_threshold);

    // Example: safely print some entries
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size && i < 10; ++i) {
        printf("RNTI: %u, RX_UE_INFORMATION_TAG: %u, CRCFLAG: %u\n",
               list->array[i].RNTI,
               list->array[i].RX_UE_INFORMATION_TAG,
               list->array[i].crcTag.CRCFLAG);
    }
    pthread_mutex_unlock(&list->lock);

    cleanup_list(list);

    return EXIT_SUCCESS;
}
```

### Key Considerations:
