    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray* dyn_array) {
    dyn_array->array = malloc(INITIAL_CAPACITY * sizeof(LTE_DL_FRAME_MSG));
    dyn_array->capacity = INITIAL_CAPACITY;
    dyn_array->size = 0;
    pthread_mutex_init(&dyn_array->lock, NULL);
}

