}

void initialize_phy_stats(PHY_STATS_TAG* phy_stats, int report_count) {
    phy_stats->count = report_count;
    phy_stats->reports = malloc(report_count * sizeof(PHY_STATS_REPORT_T));

    for (int i = 0; i < report_count; ++i) {
        phy_stats->reports[i].some_statistic = rand() % 100; // Random statistic
    }
}

void add_lte_dl_frame_msg(DynamicArray* dyn_array, unsigned int ue_context_tag, unsigned int cell_id, int report_count) {
    pthread_mutex_lock(&dyn_array->lock);

    if ((dyn_array->size + sizeof(LTE_DL_FRAME_MSG)) > MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory threshold exceeded.\n");
        pthread_mutex_unlock(&dyn_array->lock);
        return;
    }

    if (dyn_array->size >= dyn_array->capacity) {
        size_t new_capacity = dyn_array->capacity * 2;
        LTE_DL_FRAME_MSG* temp = realloc(dyn_array->array, new_capacity * sizeof(LTE_DL_FRAME_MSG));
        if (!temp) {
            fprintf(stderr, "Failed to reallocate memory.\n");
            pthread_mutex_unlock(&dyn_array->lock);
            return;
        }
        dyn_array->array = temp;
        dyn_array->capacity = new_capacity;
    }

    LTE_DL_FRAME_MSG* msg = &dyn_array->array[dyn_array->size++];
    msg->ue_context_tag = ue_context_tag;
    msg->cell_id = cell_id;

    initialize_phy_stats(&msg->phy_stats_tag, report_count);

    pthread_mutex_unlock(&dyn_array->lock);
}

void free_dynamic_array(DynamicArray* dyn_array) {
    for (size_t i = 0; i < dyn_array->size; ++i) {
        free(dyn_array->array[i].phy_stats_tag.reports);
    }
    free(dyn_array->array);
    pthread_mutex_destroy(&dyn_array->lock);
}

int main() {
    srand(time(NULL));
    DynamicArray dyn_array;
    init_dynamic_array(&dyn_array);

    unsigned int ue_context_tag, cell_id;

    if (!fetch_initial_config(&ue_context_tag, &cell_id)) {
        fprintf(stderr, "Failed to fetch initial configuration.\n");
        free_dynamic_array(&dyn_array);
        return 1;
    }

    add_lte_dl_frame_msg(&dyn_array, ue_context_tag, cell_id, 5);

    // Add more messages as needed
    for (size_t i = 0; i < dyn_array.size; ++i) {
        printf("UE Context Tag: %u, Cell ID: %u, PHY Stats Count: %u\n",
               dyn_array.array[i].ue_context_tag,
               dyn_array.array[i].cell_id,
               dyn_array.array[i].phy_stats_tag.count);
    }

    free_dynamic_array(&dyn_array);
    return 0;
}
```

### Key Points:
