#include "external_logging_library.h" // Placeholder for actual logging library

#define MAX_RNTI 65535
#define NFAPI_CRC_INDICATION_PDU_T_SIZE 1000 // Example size, adjust as needed
#define CRC_THRESHOLD 50

typedef struct {
    int value;
    time_t creation_time;
    int status_flag;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t capacity;
    pthread_mutex_t lock;
} DataStructureManager;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int initialize_data_structure_manager(DataStructureManager *manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->lock, NULL);

    manager->offsets = (long *)malloc(initial_capacity * sizeof(long));
    manager->keys = (int *)malloc(initial_capacity * sizeof(int));
    manager->records = (Record **)malloc(initial_capacity * sizeof(Record *));
    manager->capacity = initial_capacity;

    if (!manager->offsets || !manager->keys || !manager->records) {
        external_log_error("Memory allocation failed");
        return -1; // Error code for memory allocation failure
    }

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < initial_capacity; ++i) {
        manager->offsets[i] = i;
        manager->keys[i] = rand() % 100; // Random number within a specified range

        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            external_log_error("Memory allocation failed for record");
            return -2; // Error code for memory allocation failure
        }

        record->value = rand() % 100;
        record->creation_time = time(NULL);
        record->status_flag = 1;
        manager->records[i] = record;
    }
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success code
}

int resize_data_structure_manager(DataStructureManager *manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->lock);

    long *new_offsets = (long *)realloc(manager->offsets, new_capacity * sizeof(long));
    int *new_keys = (int *)realloc(manager->keys, new_capacity * sizeof(int));
    Record **new_records = (Record **)realloc(manager->records, new_capacity * sizeof(Record *));

    if (!new_offsets || !new_keys || !new_records) {
        external_log_error("Memory reallocation failed");
        pthread_mutex_unlock(&manager->lock);
        return -3; // Error code for memory reallocation failure
    }

    manager->offsets = new_offsets;
    manager->keys = new_keys;
    manager->records = new_records;
    manager->capacity = new_capacity;

    for (size_t i = manager->capacity / 2; i < new_capacity; ++i) {
        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            external_log_error("Memory allocation failed for record");
            pthread_mutex_unlock(&manager->lock);
            return -4; // Error code for memory allocation failure
        }

        record->value = rand() % 100;
        record->creation_time = time(NULL);
        record->status_flag = 1;
        manager->records[i] = record;
    }

    pthread_mutex_unlock(&manager->lock);

    return 0; // Success code
}

NFAPI_CRC_INDICATION_PDU_T *create_nfa_pi_crc_indication_pdu_array(size_t num_elements) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_array) {
        external_log_error("Memory allocation failed for PDU array");
        return NULL; // Error code for memory allocation failure
    }

    for (size_t i = 0; i < num_elements; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pdu_array[i].RNTI = rand() % MAX_RNTI + 1; // Ensure RNTI is within range
        pdu_array[i].CRC_INDICATION_REL8_TAG = rand() % 10;

        int random_value = rand();
        pdu_array[i].CRCFLAG = (random_value > CRC_THRESHOLD) ? 1 : 0;
    }

    return pdu_array; // Success code
}

void cleanup_data_structure_manager(DataStructureManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->capacity; ++i) {
        free(manager->records[i]);
    }
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Example usage
int main() {
    DataStructureManager manager;
    if (initialize_data_structure_manager(&manager, 10) != 0) {
        return -1; // Handle initialization error
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = create_nfa_pi_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T_SIZE);
    if (!pdu_array) {
        cleanup_data_structure_manager(&manager);
        return -2; // Handle PDU array creation error
    }

    // Perform operations with pdu_array...

    free(pdu_array);

    cleanup_data_structure_manager(&manager);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` for thread-safe access.
- **Memory Management**: Allocates and resizes arrays dynamically, handling allocation failures gracefully.
- **Logging**: Integrates with an external logging library for error reporting.
- **Randomization**: Populates records and PDU structures with random values within specified ranges.
- **Error Handling**: Returns specific error codes for different failure scenarios.
