typedef struct NFAPI_CRC_INDICATION_PDU_T {
    UE_Information ue_info;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

// Global logger for tracking allocations and failures
typedef struct Logger {
    int success_count;
    int failure_count;
} Logger;

Logger global_logger = {0, 0};

// Mutex for thread-safe operations
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* head = NULL;

int validate_UE_information(UE_Information* ue_info) {
    return (ue_info->RX_UE_INFORMATION_TAG > 0 &&
            ue_info->RNTI > 0 &&
            ue_info->CRC_INDICATION_REL8_TAG != 0);
}

void log_allocation(int success) {
    pthread_mutex_lock(&list_mutex);
    if (success) {
        global_logger.success_count++;
    } else {
        global_logger.failure_count++;
    }
    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CRC_INDICATION_PDU_T* create_node(UE_Information ue_info) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        log_allocation(0);
        return NULL;
    }

    new_node->ue_info = ue_info;
    new_node->next = NULL;
    log_allocation(1);
    return new_node;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T* new_node) {
    pthread_mutex_lock(&list_mutex);
    if (!head) {
        head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* temp = head;
        while (temp->next) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
    pthread_mutex_unlock(&list_mutex);
}

void remove_from_list(unsigned long rnti) {
    pthread_mutex_lock(&list_mutex);
    NFAPI_CRC_INDICATION_PDU_T *temp = head, *prev = NULL;

    while (temp != NULL && temp->ue_info.RNTI != rnti) {
        prev = temp;
        temp = temp->next;
    }

    if (!temp) { // Node not found
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    if (prev == NULL) { // Head needs to be removed
        head = temp->next;
    } else {
        prev->next = temp->next;
    }

    free(temp);
    pthread_mutex_unlock(&list_mutex);
}

void iterate_list(void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list_mutex);
    NFAPI_CRC_INDICATION_PDU_T* current = head;

    while (current) {
        callback(current);
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
}

void free_list() {
    pthread_mutex_lock(&list_mutex);
    NFAPI_CRC_INDICATION_PDU_T *temp;

    while (head) {
        temp = head;
        head = head->next;
        free(temp);
    }

    pthread_mutex_unlock(&list_mutex);
}

// Example callback function for iteration
void print_node(NFAPI_CRC_INDICATION_PDU_T* node) {
    printf("RNTI: %lu, RX Tag: %d, CRC TAG: %u, CRC FLAG: %d\n",
           node->ue_info.RNTI,
           node->ue_info.RX_UE_INFORMATION_TAG,
           node->ue_info.CRC_INDICATION_REL8_TAG,
           node->ue_info.CRCFLAG);
}

// Example sorting function (not implemented for brevity)
void sort_list() {
    // Implement a stable sorting algorithm based on RNTI or other criteria
}

int main() {
    UE_Information ue_info1 = {1, 100, 2, rand() % 2};
    UE_Information ue_info2 = {1, 200, 3, rand() % 2};

    if (!validate_UE_information(&ue_info1) || !validate_UE_information(&ue_info2)) {
        fprintf(stderr, "Invalid UE information\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T* node1 = create_node(ue_info1);
    if (node1 == NULL) {
        fprintf(stderr, "Memory allocation failed for node 1\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T* node2 = create_node(ue_info2);
    if (node2 == NULL) {
        free(node1);
        fprintf(stderr, "Memory allocation failed for node 2\n");
        return EXIT_FAILURE;
    }

    add_to_list(node1);
    add_to_list(node2);

    iterate_list(print_node);

    remove_from_list(100);
    iterate_list(print_node);

    sort_list(); // Call the sorting function

    free_list();

    printf("Allocations succeeded: %d, failed: %d\n", global_logger.success_count, global_logger.failure_count);

    return EXIT_SUCCESS;
}
