#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CONFIG_LINE_LENGTH 256
#define CONFIG_FILE_PATH "config.cfg"

typedef struct {
    int valid;
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned short RNTI;
} UE_SPECIFIC_SETTINGS;

typedef struct {
    unsigned char CRCFLAG; // Randomly set CRC flag
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rxInfoTag;
    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

int loadConfiguration(const char *filePath, UE_SPECIFIC_SETTINGS **settingsList, size_t *numEntries);
void freeSettings(UE_SPECIFIC_SETTINGS *settingsList);

NFAPI_CRC_INDICATION_PDU_T* manageNfaPackets(int numUes, const UE_SPECIFIC_SETTINGS *ueSettings, int *error) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *nfaPackets = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numUes * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaPackets) {
        *error = -1; // Memory allocation error
        return NULL;
    }

    for (int i = 0; i < numUes; ++i) {
        nfaPackets[i].rxInfoTag.valid = 1; // Assuming always valid for simplicity
        nfaPackets[i].RNTI = ueSettings[i].RNTI;
        nfaPackets[i].crcIndicationRel8Tag.CRCFLAG = rand() % 2; // Randomly set CRC flag (0 or 1)
    }

    return nfaPackets;
}

int main(int argc, char *argv[]) {
    int error = 0;
    UE_SPECIFIC_SETTINGS *ueSettings = NULL;
    size_t numUes = 0;

    if (loadConfiguration(CONFIG_FILE_PATH, &ueSettings, &numUes) != 0) {
        printf("Failed to load configuration.\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *nfaPackets = manageNfaPackets(numUes, ueSettings, &error);
    if (error != 0 || !nfaPackets) {
        printf("Error managing NFA packets: %d\n", error);
        freeSettings(ueSettings);
        return -1;
    }

    // Use nfaPackets...

    free(nfaPackets);
    freeSettings(ueSettings);

    return 0;
}

int loadConfiguration(const char *filePath, UE_SPECIFIC_SETTINGS **settingsList, size_t *numEntries) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        return -1; // File open error
    }

    char line[MAX_CONFIG_LINE_LENGTH];
    UE_SPECIFIC_SETTINGS tempSettings;
    *settingsList = NULL;
    *numEntries = 0;

    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%hu", &tempSettings.RNTI) == 1) {
            *settingsList = realloc(*settingsList, (*numEntries + 1) * sizeof(UE_SPECIFIC_SETTINGS));
            if (!*settingsList) {
                fclose(file);
                return -2; // Memory allocation error
            }
            (*settingsList)[*numEntries] = tempSettings;
            ++(*numEntries);
        } else {
            printf("Invalid configuration format.\n");
            freeSettings(*settingsList);
            fclose(file);
            return -3; // Invalid content error
        }
    }

    fclose(file);
    return 0;
}

void freeSettings(UE_SPECIFIC_SETTINGS *settingsList) {
    if (settingsList) {
        free(settingsList);
    }
}
