        $this->redis->connect('127.0.0.1', 6379);
    }

    public function isAllowed($ipAddress) {
        $key = "rate_limit:{$ipAddress}";
        $current = $this->redis->get($key);

        if ($current === false) {
            $this->redis->setex($key, 60, 1);
            return true;
        }

        if ((int)$current < 5) {
            $this->redis->incr($key);
            return true;
        }

        return false;
    }
}

