<?php

class UserService {
    private $authService;
    private $loggingService;
    private $metricsApi;

    public function __construct($authService, $loggingService, $metricsApi) {
        $this->authService = $AuthService;
        $this->loggingService = $LoggingService;
        $this->metricsApi = $MetricsAPI;
    }

    public function updatePassword($userId, $newPassword, $idempotencyToken) {
        // Validate password strength
        if (!$this->isStrongPassword($newPassword)) {
            throw new Exception("Password does not meet the required criteria.");
        }

        try {
            $this->handleRetry(function() use ($userId, $newPassword, $idempotencyToken) {
                $this->performPasswordUpdate($userId, $newPassword, $idempotencyToken);
            });
        } catch (Exception $e) {
            $this->loggingService->logError("Failed to update password for user {$userId}: " . $e->getMessage());
            throw new Exception("Password update failed.");
        }
    }

    private function isStrongPassword($password) {
        // Example criteria: Minimum 8 characters, at least one letter and one number
        return preg_match('/^(?=.*[A-Za-z])(?=.*\d)[A-Za-z\d]{8,}$/', $password);
    }

    private function handleRetry(callable $function) {
        $maxRetries = 5;
        $delay = 100; // Initial delay in milliseconds

        for ($attempt = 0; $attempt < $maxRetries; $attempt++) {
            try {
                call_user_func($function);
                return;
            } catch (TransientNetworkException $e) {
                if ($attempt == $maxRetries - 1) {
                    throw $e;
                }
                usleep($delay * 1000); // Convert ms to microseconds
                $delay *= 2; // Exponential backoff
            }
        }
    }

    private function performPasswordUpdate($userId, $newPassword, $idempotencyToken) {
        if (!$this->isIdempotent($userId, $idempotencyToken)) {
            throw new Exception("Duplicate request detected.");
        }

        // Simulate external service call with timeout
        $result = $this->authService->updatePasswordWithTimeout(
            $userId,
            $newPassword,
            2 // Timeout in seconds
        );

        if (!$result) {
            throw new TransientNetworkException("Failed to update password due to network issue.");
        }

        $this->loggingService->logInfo("Password updated for user {$userId}");
        $this->metricsApi->recordMetric('password_update_success');
    }

    private function isIdempotent($userId, $idempotencyToken) {
        // Check if the idempotency token has been used before
        return !$this->authService->isTokenUsed($userId, $idempotencyToken);
    }
}

class TransientNetworkException extends Exception {}

