#define MAX_SIZE 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t capacity;
} CRCArray;

void initArray(CRCArray *a, size_t initialCapacity) {
    a->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!a->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    a->used = 0;
    a->capacity = initialCapacity;
}

void insertElement(CRCArray *a, NFAPI_CRC_INDICATION_PDU_T element) {
    if (a->used == a->capacity) {
        size_t newCapacity = a->capacity * 2;
        if (newCapacity > MAX_SIZE) {
            fprintf(stderr, "Exceeded maximum allowed capacity\n");
            return;
        }

        NFAPI_CRC_INDICATION_PDU_T *tempArray = realloc(a->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!tempArray) {
            fprintf(stderr, "Memory reallocation failed\n");
            // Gracefully handle the failure
            return;
        }
        a->array = tempArray;
        a->capacity = newCapacity;
    }

    a->array[a->used++] = element;

    // Randomly set CRCFLAG based on a probability to simulate real-world behavior
    if ((rand() % 100) < 5) { // Simulate a 5% failure rate
        a->array[a->used - 1].CRC_INDICATION_REL8_TAG |= 0x01; // Set a specific flag bit
    }
}

void freeArray(CRCArray *a) {
    free(a->array);
    a->array = NULL;
    a->used = a->capacity = 0;
}

void shrinkToFit(CRCArray *a) {
    if (a->used <= a->capacity / 4 && a->capacity > MAX_SIZE / 10) {
        size_t newCapacity = a->capacity / 2;

        NFAPI_CRC_INDICATION_PDU_T *tempArray = realloc(a->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (tempArray) {
            a->array = tempArray;
            a->capacity = newCapacity;
        } else {
            fprintf(stderr, "Memory reallocation failed during shrink\n");
        }
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    CRCArray a;
    initArray(&a, 10); // Initial capacity of 10 elements

    for (size_t i = 0; i < 5000; ++i) { // Insert 5,000 elements
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = rand(),
            .RNTI = rand(),
            .CRC_INDICATION_REL8_TAG = 0
        };
        insertElement(&a, pdu);
    }

    shrinkToFit(&a); // Attempt to shrink memory usage if needed

    freeArray(&a);

    return 0;
}
