LTEPHYctx_t* initialize_lte_contexts(int numCells, phyConfig_t** phyConfigs, rrcConfig_t** rrcConfigs) {
    if (!phyConfigs || !rrcConfigs) {
        log_message("Null configuration pointers provided.");
        return NULL;
    }

    LTEPHYctx_t* contexts = (LTEPHYctx_t*)malloc(numCells * sizeof(LTEPHYctx_t));
    if (!contexts) {
        log_message("Memory allocation for LTEPHYctx_t array failed.");
        return NULL;
    }

    for (int i = 0; i < numCells; ++i) {
        if (i >= numCells || !phyConfigs[i] || !rrcConfigs[i]) {
            log_message("Invalid configuration pointers detected, partial initialization.");
            // Attempt to free already allocated contexts
            for (int j = 0; j < i; ++j) {
                free(contexts[j].phyConfig);
                free(contexts[j].rrcConfig);
            }
            free(contexts);
            return NULL;
        }

        contexts[i].cellId = i;

        // Allocate and initialize phyConfig
        contexts[i].phyConfig = (phyConfig_t*)malloc(sizeof(phyConfig_t));
        if (!contexts[i].phyConfig) {
            log_message("Memory allocation for phyConfig failed.");
            break;  // Break to handle partial cleanup below
        }
        memcpy(contexts[i].phyConfig, phyConfigs[i], sizeof(phyConfig_t));

        // Allocate and initialize rrcConfig
        contexts[i].rrcConfig = (rrcConfig_t*)malloc(sizeof(rrcConfig_t));
        if (!contexts[i].rrcConfig) {
            log_message("Memory allocation for rrcConfig failed.");
