uint16_t calculate_checksum_a(const MAC_RX_FRAME *frame, size_t extended_headers_size) {
    uint32_t sum = frame->mac_header.field1 + frame->mac_header.field2;
    if (extended_headers_size > 0 && frame->extended_headers != NULL) {
