    if (extended_headers_size > 0 && frame->extended_headers != NULL) {
        const uint8_t *headers = frame->extended_headers;
        for (size_t i = 0; i < extended_headers_size; ++i) {
            product *= headers[i];
            product %= 65535; // To prevent overflow
        }
    }
    return (uint16_t)(product % 65536);
}

