// Function to generate random CRCFLAG
uint8_t generate_random_crcflag() {
    return rand() % 2; // Randomly returns 0 or 1
}

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_crc_pdu_array(uint32_t N, uint16_t *rx_ue_info_tags, uint32_t *rntis) {
    if (N == 0 || rx_ue_info_tags == NULL || rntis == NULL) {
        return NULL; // Graceful error handling for invalid input
    }

    pthread_mutex_lock(&mutex); // Ensures thread safety

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Handle allocation failure
    }

    for (uint32_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rx_ue_info_tags[i];
        array[i].RNTI = rntis[i];
        array[i].CRC_INDICATION_REL8_TAG = generate_random_crcflag();
        array[i].CRCFLAG = generate_random_crcflag();
    }

    pthread_mutex_unlock(&mutex); // Release the lock

    return array;
}

// Example usage
int main() {
    uint32_t N = 10; 
    uint16_t rx_ue_info_tags[N] = {0}; // Fill with appropriate values
    uint32_t rntis[N] = {0}; // Fill with appropriate values

    NFAPI_CRC_INDICATION_PDU_T *result = allocate_and_populate_crc_pdu_array(N, rx_ue_info_tags, rntis);

    if (result == NULL) {
        fprintf(stderr, "Error allocating memory or invalid input.\n");
        return 1;
    }

    // Use the array...

    free(result); // Don't forget to free allocated memory

    return 0;
}
