        if ((*pdu_array)[i].pdu_data_buffer == NULL) {
            // Free previously allocated buffers and array before returning error
            while (--i >= 0) {
                free((*pdu_array)[i].pdu_data_buffer);
            }
            free(*pdu_array);
            *pdu_array = NULL;
            return -4; // Memory allocation failed for PDU data buffer
        }
    }

    return 0; // Success
}

void cleanup_pdu_array(LTE_PDCP_PDU *pdu_array, size_t array_size) {
