typedef struct {
    int value;
} record_t;

typedef size_t offset_t;
typedef unsigned int key_t;

// Function to initialize and register OpenSSL ciphers and digests
void register_crypto_functions() {
    // Register AES ciphers
    EVP_add_cipher(EVP_aes_128_cbc());
    EVP_add_cipher(EVP_aes_192_cbc());
    EVP_add_cipher(EVP_aes_256_cbc());

    // Register Camellia ciphers
    EVP_add_cipher(EVP_camellia_128_cbc());
    EVP_add_cipher(EVP_camellia_192_cbc());
    EVP_add_cipher(EVP_camellia_256_cbc());

    // Additional block cipher example (could be any valid one)
    EVP_add_cipher(EVP_des_cbc());

    // Register digests
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    EVP_add_digest(EVP_sha256());
    EVP_add_digest(EVP_sha512());
}

// Function to check for duplicate entries
int is_duplicate(NFAPI_CRC_INDICATION_PDU_T *array, int size, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    for (int i = 0; i < size; ++i) {
        if (array[i].RX_UE_INFORMATION_TAG == new_entry.RX_UE_INFORMATION_TAG &&
            array[i].RNTI == new_entry.RNTI) {
            return 1;
        }
    }
    return 0;
}

// Initialize and populate the structures
int initialize_framework_and_records(NFAPI_CRC_INDICATION_PDU_T **pdus, offset_t *offsets, key_t *keys, record_t **records, int *num_records) {
    register_crypto_functions();

    srand(time(NULL));
    const int max_pdus = 100;
    int current_pdu_count = 0;

    // Allocate memory for structures
    *pdus = malloc(max_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdus) {
        perror("Failed to allocate pdus");
        return -1;
    }

    offsets = calloc(max_pdus, sizeof(offset_t));
    if (!offsets) {
        free(*pdus);
        perror("Failed to allocate offsets");
        return -1;
    }

    keys = calloc(max_pdus, sizeof(key_t));
    if (!keys) {
        free(*pdus);
        free(offsets);
        perror("Failed to allocate keys");
        return -1;
    }

    *records = malloc(max_pdus * sizeof(record_t));
    if (!*records) {
        free(*pdus);
        free(offsets);
        free(keys);
        perror("Failed to allocate records");
        return -1;
    }

    for (int i = 0; i < max_pdus && current_pdu_count < max_pdus; ++i) {
        NFAPI_CRC_INDICATION_PDU_T new_pdu;
        do {
            new_pdu.RX_UE_INFORMATION_TAG = rand() % 10000;
            new_pdu.RNTI = rand() % 5000;
            new_pdu.CRC_INDICATION_REL8_TAG = rand();
        } while (is_duplicate(*pdus, current_pdu_count, new_pdu));

        (*pdus)[current_pdu_count] = new_pdu;

        // Populate offsets and keys
        offsets[current_pdu_count] = i * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        keys[current_pdu_count] = rand() % 10000;

        // Populate record with a random value within range
        (*records)[current_pdu_count].value = CONFIGURABLE_RANGE_MIN + (rand() % (CONFIGURABLE_RANGE_MAX - CONFIGURABLE_RANGE_MIN + 1));

        current_pdu_count++;
    }

    *num_records = current_pdu_count;
    return 0;
}

// Function to free allocated resources
void cleanup(NFAPI_CRC_INDICATION_PDU_T *pdus, offset_t *offsets, key_t *keys, record_t *records) {
    if (pdus) free(pdus);
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;
    offset_t *offsets = NULL;
    key_t *keys = NULL;
    record_t *records = NULL;
    int num_records = 0;

    if (initialize_framework_and_records(&pdus, offsets, keys, &records, &num_records) == -1) {
        fprintf(stderr, "Initialization failed.\n");
        return EXIT_FAILURE;
    }

    // Example usage of the structures
    for (int i = 0; i < num_records; ++i) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %lu, Record Value: %d\n",
               pdus[i].RX_UE_INFORMATION_TAG,
               pdus[i].RNTI,
               pdus[i].CRC_INDICATION_REL8_TAG,
               records[i].value);
    }

    cleanup(pdus, offsets, keys, records);
    return EXIT_SUCCESS;
}
