#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTS 1000

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[256]; // Assume a fixed size for simplicity
    unsigned char CRCFLAG; // Randomly set flag
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_STRUCTS];
    pthread_mutex_t lock;
    int count;
} CRC_Indication_Manager;

static void log_error(const char *message) {
    // Implement the logging mechanism here
    fprintf(stderr, "Error: %s\n", message);
}

int load_resource_bundle() {
    // Simulate loading a resource bundle; return 0 on success, -1 on failure.
    return 0;
}

unsigned int generate_unique_rnti(CRC_Indication_Manager *manager) {
    unsigned int rnti;
    do {
        rnti = rand() % (UINT_MAX / 2); // Generate a pseudo-random RNTI
    } while (rnti == 0 || !is_rnti_unique(manager, rnti));
    return rnti;
}

int is_rnti_unique(CRC_Indication_Manager *manager, unsigned int rnti) {
    for (int i = 0; i < manager->count; ++i) {
        if (manager->data[i]->RNTI == rnti) {
            return 0; // RNTI is not unique
        }
    }
    return 1; // RNTI is unique
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        log_error("Memory allocation failed for CRC indication PDU");
        return NULL;
    }
    memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->RX_UE_INFORMATION_TAG = rand(); // Simulate generating valid information tag
    pdu->RNTI = generate_unique_rnti(NULL); // Assuming manager is provided or initialized elsewhere
    memset(pdu->CRC_INDICATION_REL8_TAG, rand() % 256, sizeof(pdu->CRC_INDICATION_REL8_TAG)); // Random content
    pdu->CRCFLAG = rand() & 1; // Randomly set CRCFLAG to 0 or 1

    return pdu;
}

int init_crc_indication_manager(CRC_Indication_Manager *manager) {
    if (load_resource_bundle() != 0) {
        log_error("Failed to load resource bundle");
        return -1;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
    for (int i = 0; i < MAX_STRUCTS; ++i) {
        manager->data[i] = create_crc_indication_pdu();
        if (!manager->data[i]) {
            log_error("Failed to initialize CRC indication PDU");
            pthread_mutex_destroy(&manager->lock);
            return -1;
        }
    }
    return 0;
}

int add_crc_indication_pdu(CRC_Indication_Manager *manager) {
    if (pthread_mutex_lock(&manager->lock) != 0) {
        log_error("Mutex lock failed");
        return -1;
    }

    if (manager->count >= MAX_STRUCTS) {
        pthread_mutex_unlock(&manager->lock);
        log_error("Exceeded maximum number of PDU structures");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = create_crc_indication_pdu();
    if (!pdu) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->data[manager->count++] = pdu;

    if (pthread_mutex_unlock(&manager->lock) != 0) {
        log_error("Mutex unlock failed");
        free(pdu); // Clean up on error
        return -1;
    }

    return 0;
}

void cleanup_crc_indication_manager(CRC_Indication_Manager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; ++i) {
        free(manager->data[i]);
    }
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
}

// Example usage
int main() {
    srand(time(NULL));

    CRC_Indication_Manager manager;
    if (init_crc_indication_manager(&manager) != 0) {
        return -1; // Initialization failed
    }

    for (int i = 0; i < MAX_STRUCTS; ++i) {
        if (add_crc_indication_pdu(&manager) != 0) {
            log_error("Failed to add CRC indication PDU");
            break;
        }
    }

    cleanup_crc_indication_manager(&manager);
    return 0;
}
