    MAC_HEADER mac_header;
    CHECKSUM_INFO checksum_info;
    void *extended_headers;  // Optional
    uint16_t RNTI;
    uint32_t RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG crc_indication;
} MAC_RX_FRAME;

typedef enum {
    CHECKSUM_ALGO_SIMPLE,
    CHECKSUM_ALGO_ADVANCED
} ChecksumAlgorithm;

// Function prototypes
MAC_RX_FRAME* initialize_mac_rx_frames(size_t count, int enable_logging, ChecksumAlgorithm algo);
void free_mac_rx_frames(MAC_RX_FRAME* frames, size_t count);
uint32_t generate_checksum(const MAC_HEADER* header, ChecksumAlgorithm algo);
void log_frame_contents(const MAC_RX_FRAME* frame, int enable_logging);

MAC_RX_FRAME* initialize_mac_rx_frames(size_t count, int enable_logging, ChecksumAlgorithm algo) {
    if (count == 0) return NULL;

    MAC_RX_FRAME* frames = malloc(count * sizeof(MAC_RX_FRAME));
    if (!frames) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < count; ++i) {
        frames[i].mac_header.version = rand() % 256;
        frames[i].mac_header.length = rand() % 1024;

        frames[i].checksum_info.checksum_value = generate_checksum(&frames[i].mac_header, algo);
        frames[i].checksum_info.checksum_valid = (rand() % 2 == 0); // Randomly set valid/invalid

        frames[i].RNTI = rand() % 65536;
        frames[i].RX_UE_INFORMATION_TAG = rand();

        frames[i].crc_indication.CRCFLAG = (rand() % 2 == 0);

        if ((rand() % 10) > 7) { // Randomly decide to add extended headers
            frames[i].extended_headers = malloc(256); // Example size for extended headers
            if (!frames[i].extended_headers) {
                fprintf(stderr, "Extended header allocation failed\n");
                free_mac_rx_frames(frames, i);
                return NULL;
            }
        }

        log_frame_contents(&frames[i], enable_logging);
    }

    return frames;
}

void free_mac_rx_frames(MAC_RX_FRAME* frames, size_t count) {
    if (!frames) return;

    for (size_t i = 0; i < count; ++i) {
        if (frames[i].extended_headers) {
            free(frames[i].extended_headers);
        }
    }

    free(frames);
}

uint32_t generate_checksum(const MAC_HEADER* header, ChecksumAlgorithm algo) {
    switch (algo) {
        case CHECKSUM_ALGO_SIMPLE:
            return (header->version + header->length) % 0xFFFFFFFF;
        case CHECKSUM_ALGO_ADVANCED:
            return ((header->version * 3 + header->length * 5) ^ 0xA5A5A5A5) % 0xFFFFFFFF;
        default:
            return 0;
    }
}

void log_frame_contents(const MAC_RX_FRAME* frame, int enable_logging) {
    if (!enable_logging) return;

    printf("MAC Header Version: %u\n", frame->mac_header.version);
    printf("MAC Header Length: %u\n", frame->mac_header.length);
    printf("Checksum Value: %u, Valid: %d\n", frame->checksum_info.checksum_value, frame->checksum_info.checksum_valid);
    printf("RNTI: %u\n", frame->RNTI);
    printf("RX UE Information Tag: %u\n", frame->RX_UE_INFORMATION_TAG);
    printf("CRC FLAG: %u\n", frame->crc_indication.CRCFLAG);
}

// Example usage
int main() {
    size_t num_frames = 10;
    int logging_enabled = 1;
    ChecksumAlgorithm algo = CHECKSUM_ALGO_SIMPLE;

    MAC_RX_FRAME* frames = initialize_mac_rx_frames(num_frames, logging_enabled, algo);
    if (frames) {
        // Process frames...

        free_mac_rx_frames(frames, num_frames);
    }

    return 0;
}
