    for (int i = 0; i < numStructures; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 100;
        list[i].RNTI = rand();
        list[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        list[i].CRCFLAG = rand() % 2;
    }

    return list;
}

// Function to free the allocated memory
void freeNFAPICRCIndicationList(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list != NULL) {
        free(list);
    }
}
