using System;
using System.Collections.Generic;
using System.Data.SqlClient;

public class DatabaseHandler
{
    public void InsertNFAPICRCIndications(List<NFAPI_CRC_INDICATION_PDU_T> structures, string connectionString, string sqlCommandTemplate)
    {
        try
        {
            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                connection.Open();
                SqlTransaction transaction = connection.BeginTransaction();

                foreach (var structure in structures)
                {
                    using (SqlCommand command = new SqlCommand(sqlCommandTemplate, connection, transaction))
                    {
                        command.Parameters.AddWithValue("@RXUEINFORMATIONTAG", structure.RX_UE_INFORMATION_TAG);
                        command.Parameters.AddWithValue("@RNTI", structure.RNTI);
                        command.Parameters.AddWithValue("@CRCINDICATIONREL8TAG", structure.CRC_INDICATION_REL8_TAG);
                        command.Parameters.AddWithValue("@CRCFLAG", structure.CRCFLAG);

                        try
                        {
                            command.ExecuteNonQuery();
                        }
                        catch (SqlException ex)
                        {
                            Console.WriteLine("An error occurred: " + ex.Message);
                            transaction.Rollback(); // Rollback on error
                            throw;
                        }
                    }
                }

                transaction.Commit(); // Commit the transaction if all commands succeed
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Database operation failed: {ex.Message}");
            throw; // Re-throw the exception to allow higher-level handling
        }
    }
}

