import java.nio.ByteBuffer;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.locks.ReentrantLock;
import org.reactivestreams.Publisher;
import reactor.core.publisher.Mono;
import reactor.netty.NettyOutboundConnection;
import reactor.netty.http.client.HttpClient;
import java.nio.channels.ClosedChannelException;

public class ConnectionManager {

    private final HttpClient client = HttpClient.create().port(8080);
    private final ReentrantLock lock = new ReentrantLock();
    private long[] offsets;
    private int[] keys;
    private List<Record> records;
    private static final Random random = new Random();

    public void manageConnection() {
        try (NettyOutboundConnection connection = client.connect().block()) {
            connection.addHandler((ctx, msg) -> {
                // Handle message and state changes
                System.out.println("Received: " + msg.contentUtf8());
                return ctx.writeAndFlush(msg);
            }).handle((in, out) -> Mono.just(out))
              .doOnError(e -> logError(e))
              .subscribe();
        } catch (ClosedChannelException e) {
            logError(e);
        }
    }

    public void initializeDataStructures(int initialSize) {
        lock.lock();
        try {
            offsets = new long[initialSize];
            keys = new int[initialSize];
            records = new ArrayList<>(initialSize);

            for (int i = 0; i < initialSize; i++) {
                Record record = new Record(random.nextInt(100), Instant.now(), true);
                populateRecord(record);
                records.add(record);
            }
        } finally {
            lock.unlock();
        }
    }

    private void populateRecord(Record record) {
        record.setData(random.nextInt(1000)); // Random data within a range
    }

    public List<NFAPI_CRC_INDICATION_PDU_T> createPduList(int count, int rntiRange, double crcThreshold) {
        lock.lock();
        try {
            List<NFAPI_CRC_INDICATION_PDU_T> pduList = new ArrayList<>(count);

            for (int i = 0; i < count; i++) {
                NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();
                int rnti = random.nextInt(rntiRange);
                boolean crcFlag = random.nextDouble() > crcThreshold;

                pdu.setRNTI(rnti);
                pdu.setCRCFLAG(crcFlag);
                pduList.add(pdu);
            }

            return pduList;
        } finally {
            lock.unlock();
        }
    }

    private void logError(Throwable e) {
        // Use an external logging library
        System.err.println("Error: " + e.getMessage());
        e.printStackTrace();
    }

    public static class Record {
        private final int value;
        private final Instant creationTime;
        private final boolean statusFlag;

        public Record(int value, Instant creationTime, boolean statusFlag) {
            this.value = value;
            this.creationTime = creationTime;
            this.statusFlag = statusFlag;
        }

        public void setData(int data) {
            // Set additional data
        }
    }

    public static class NFAPI_CRC_INDICATION_PDU_T {
        private int rnti;
        private boolean crcFlag;

        public void setRNTI(int rnti) {
            this.rnti = rnti;
        }

        public void setCRCFLAG(boolean crcFlag) {
            this.crcFlag = crcFlag;
        }
    }

    public static void main(String[] args) {
        ConnectionManager manager = new ConnectionManager();
        manager.initializeDataStructures(100);
        List<NFAPI_CRC_INDICATION_PDU_T> pduList = manager.createPduList(50, 5000, 0.5);

        manager.manageConnection();
    }
}
```

### Key Points:
- **Reactive Programming**: Uses Project Reactor for asynchronous handling of network connections.
- **Thread Safety**: Utilizes `ReentrantLock` to ensure thread-safe access to shared resources.
- **Dynamic Memory Management**: Initializes arrays and lists with a specified size, allowing for potential resizing (not explicitly shown here).
- **Random Data Generation**: Populates records with random data within specified ranges.
- **Error Handling**: Logs errors using a simple `System.err.println` method, which can be replaced by an external logging library.
