import json
import requests
from cachetools import TTLCache
from threading import Lock

class UserPreferencesManager:
    def __init__(self):
        self.cache = TTLCache(maxsize=1000, ttl=300)  # Cache with max size and TTL of 5 minutes
        self.lock = Lock()
        self.default_preferences = self.load_default_preferences()

    def load_default_preferences(self):
        try:
            with open('default_config.json', 'r') as file:
                return json.load(file)
        except FileNotFoundError:
            return {}

    def fetch_from_api(self, user_id):
        try:
            response = requests.get(f'https://api.example.com/preferences/{user_id}')
            response.raise_for_status()
            return response.json()
        except requests.RequestException:
            return None

    def get_preferences(self, user_id):
        if user_id in self.cache:
            return self.cache[user_id]

        # Check local storage
        local_prefs = self.load_local_storage(user_id)
        if local_prefs is not None:
            self.update_cache(user_id, local_prefs)
            return local_prefs

        # Fallback to API or defaults
        api_prefs = self.fetch_from_api(user_id)
        if api_prefs is not None:
            self.update_cache(user_id, api_prefs)
            return api_prefs

        return self.default_preferences

    def load_local_storage(self, user_id):
        try:
            with open(f'{user_id}_prefs.json', 'r') as file:
                return json.load(file)
        except FileNotFoundError:
            return None

    def update_cache(self, user_id, preferences):
        with self.lock:
            self.cache[user_id] = preferences
            self.save_local_storage(user_id, preferences)

    def save_local_storage(self, user_id, preferences):
        with open(f'{user_id}_prefs.json', 'w') as file:
            json.dump(preferences, file)

    def export_preferences_to_json(self, user_id):
        prefs = self.get_preferences(user_id)
        with open(f'{user_id}_preferences_backup.json', 'w') as file:
            json.dump(prefs, file)

    def update_preference(self, user_id, key, value):
        prefs = self.get_preferences(user_id)
        prefs[key] = value
        self.update_cache(user_id, prefs)
        self.sync_with_api(user_id, prefs)

    def sync_with_api(self, user_id, preferences):
        try:
            requests.post(f'https://api.example.com/preferences/{user_id}', json=preferences)
        except requests.RequestException:
            pass

    def propagate_changes(self, user_id):
        # Placeholder for notifying other clients of changes
        pass

# Example usage:
manager = UserPreferencesManager()
prefs = manager.get_preferences('user123')
manager.update_preference('user123', 'theme', 'dark')
manager.export_preferences_to_json('user123')
