// Node structure for the Octree
struct OctreeNode {
    bool isLeaf;
    std::unique_ptr<OctreeNode> children[8];
    std::vector<SensorData> sensorData;

    OctreeNode() : isLeaf(true) {}

    void subdivide() {
        isLeaf = false;
        for (auto& child : children) {
            child.reset(new OctreeNode());
        }
    }
};

// Class for the Octree
class Octree {
private:
    std::unique_ptr<OctreeNode> root;

public:
    Octree() {
        root = std::make_unique<OctreeNode>();
    }

    void insertData(const SensorData& data) {
        auto* node = root.get();
        // Simplified logic to decide where to insert
        if (node->isLeaf && node->sensorData.size() < 10) { // Arbitrary limit for simplicity
            node->sensorData.push_back(data);
        } else if (node->isLeaf) {
            node->subdivide();
            // Redistribute data among children
            for (auto& existingData : node->sensorData) {
                insertData(existingData); // Reinsert existing data into correct child
            }
            node->sensorData.clear(); // Clear current node's data after redistribution
            // Now, insert the new data
            insertData(data);
        } else {
            // Determine which child to insert into and recurse
            // Simplified: always choose first child for illustration
            node->children[0]->insertData(data);
        }
    }

    void printOctree(const OctreeNode* node = nullptr, int depth = 0) const {
        if (!node) node = root.get();
        std::cout << std::string(depth * 2, ' ') << "Node at Depth " << depth
                  << ", Data Count: " << node->sensorData.size() << "\n";
        for (const auto& child : node->children) {
            if (child) {
                printOctree(child.get(), depth + 1);
