['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_TRANSACTIONS 10000
#define WINDOW_SIZE 60
#define TOP_N 10

typedef struct {
    int transaction_id;
    double weight;
    time_t timestamp;
} Transaction;

typedef struct {
    pthread_mutex_t lock;
    size_t count;
    Transaction *transactions[MAX_TRANSACTIONS];
    double weights_cache[256]; // Example cache for weights, assuming max 256 types
    int last_updated_timestamps[256];
    size_t total_processed;
    double cumulative_weight_sum;
    size_t valid_transactions;
} TransactionProcessor;

typedef struct {
    double max_weighted_sum;
    int transaction_id_with_max_sum;
    int top_transaction_ids[TOP_N];
} Result;

void init_processor(TransactionProcessor *processor) {
    pthread_mutex_init(&processor->lock, NULL);
    processor->count = 0;
    for (int i = 0; i < MAX_TRANSACTIONS; ++i)
        processor->transactions[i] = NULL;
    for (int i = 0; i < 256; ++i) {
        processor->weights_cache[i] = -1.0;
        processor->last_updated_timestamps[i] = -1;
    }
    processor->total_processed = 0;
    processor->cumulative_weight_sum = 0.0;
    processor->valid_transactions = 0;
}

double get_weight_from_source(int type) {
    // Simulate external call to retrieve weight based on type
    return (double)(type + 1); // Placeholder for actual weight fetching logic
}

void cache_weight(TransactionProcessor *processor, int type, double weight) {
    processor->weights_cache[type] = weight;
    processor->last_updated_timestamps[type] = time(NULL);
}

double get_cached_weight(TransactionProcessor *processor, int type) {
    if (processor->weights_cache[type] == -1.0 || 
        (time(NULL) - processor->last_updated_timestamps[type]) > 60) { // Invalidate cache every minute
        double weight = get_weight_from_source(type);
        cache_weight(processor, type, weight);
    }
    return processor->weights_cache[type];
}

void process_transaction(TransactionProcessor *processor, Transaction transaction) {
    pthread_mutex_lock(&processor->lock);

    time_t now = time(NULL);
    if (now - transaction.timestamp > 5) {
        // Ignore old transactions
        pthread_mutex_unlock(&processor->lock);
        return;
    }

    // Check frequency: only count latest in the last 60 seconds
    int window_start = MAX(0, processor->count - WINDOW_SIZE);
    size_t recent_count = 0;
    for (size_t i = window_start; i < processor->count && i > 0; ++i) {
        if (processor->transactions[i]->transaction_id == transaction.transaction_id &&
            now - processor->transactions[i]->timestamp <= 60)
            ++recent_count;
    }

    if (recent_count >= 10) {
        pthread_mutex_unlock(&processor->lock);
        return;
    }

    // Calculate weighted sum
    double weight = get_cached_weight(processor, transaction.type);
    double weighted_sum = weight; // For the current transaction

    // Add to processor transactions
    processor->transactions[processor->count % MAX_TRANSACTIONS] = &transaction;
    ++(processor->count);

    if (recent_count == 0) {
        // Update metrics for new valid transaction
        ++(processor->valid_transactions);
        processor->cumulative_weight_sum += weight;
    }

    // Update total processed count
    ++(processor->total_processed);

    pthread_mutex_unlock(&processor->lock);
}

Result compute_top_transactions(TransactionProcessor *processor) {
    Result result = {0.0, -1, {-1}};
    double weighted_sums[256] = {0}; // Assume transaction types map to 0-255

    pthread_mutex_lock(&processor->lock);

    for (size_t i = 0; i < processor->count && i > 0; ++i) {
        Transaction *trans = processor->transactions[i % MAX_TRANSACTIONS];
        if (!trans) continue;

        double weight = get_cached_weight(processor, trans->type);
        weighted_sums[trans->transaction_id] += weight;
    }

    // Find top transactions
    int indices[TOP_N] = {-1};
    for (int i = 0; i < TOP_N; ++i) {
        int max_index = -1;
        double max_sum = 0.0;

        for (size_t j = 0; j < processor->count && j > 0; ++j) {
            Transaction *trans = processor->transactions[j % MAX_TRANSACTIONS];
            if (!trans) continue;

            double sum = weighted_sums[trans->transaction_id];
            if (sum > max_sum) {
                max_sum = sum;
                max_index = trans->transaction_id;
            }
        }

        if (max_index != -1 && indices[i] == -1) {
            result.top_transaction_ids[i] = max_index;
            weighted_sums[max_index] = 0; // Invalidate
        }
    }

    // Determine the transaction with the maximum weighted sum in the last minute
    for (int i = TOP_N - 1; i >= 0; --i) {
        if (result.top_transaction_ids[i] != -1) {
            result.max_weighted_sum = weighted_sums[result.top_transaction_ids[i]];
            result.transaction_id_with_max_sum = result.top_transaction_ids[i];
            break;
        }
    }

    pthread_mutex_unlock(&processor->lock);
    return result;
}

void cleanup_processor(TransactionProcessor *processor) {
    pthread_mutex_destroy(&processor->lock);
}

int main() {
    TransactionProcessor processor;
    init_processor(&processor);

    // Simulate processing transactions
    for (size_t i = 0; i < MAX_TRANSACTIONS; ++i) {
        Transaction transaction = { .transaction_id = rand() % 256, .weight = 1.0, .timestamp = time(NULL) - (rand() % 10) };
        process_transaction(&processor, transaction);
    }

    Result result = compute_top_transactions(&processor);

    printf("Max Weighted Sum: %.2f\n", result.max_weighted_sum);
    printf("Transaction ID with Max Sum: %d\n", result.transaction_id_with_max_sum);
    printf("Top 10 Transaction IDs:\n");
    for (int i = 0; i < TOP_N; ++i) {
        if (result.top_transaction_ids[i] != -1)
            printf("%d ", result.top_transaction_ids[i]);
    }
    printf("\n");

    cleanup_processor(&processor);
    return 0;
}
