// C# Code: SQL Execution using parameterized commands

using System;
using System.Collections.Generic;
using System.Data.SqlClient;

public class SqlExecutor {
    public IDataReader ExecuteParameterizedQuery(SqlConnection connection, string commandText, List<Tuple<int, byte[], byte[], byte>> values) {
        SqlCommand cmd = new SqlCommand(commandText, connection);

        for (int i = 0; i < values.Count; i++) {
            var valueTuple = values[i];
            int index = i + 1;

            SqlParameter rntiParam = new SqlParameter($"@RNTI_{index}", SqlDbType.Int);
            rntiParam.Value = valueTuple.Item1;
            cmd.Parameters.Add(rntiParam);

            SqlParameter rxTagParam = new SqlParameter($"@RX_TAG_{index}", SqlDbType.VarBinary, 4);
            rxTagParam.Value = valueTuple.Item2;
            cmd.Parameters.Add(rxTagParam);

            SqlParameter crcTagParam = new SqlParameter($"@CRC_TAG_{index}", SqlDbType.TinyInt);
            crcTagParam.Value = BitConverter.ToUInt16(valueTuple.Item3, 0); // Convert byte array to ushort
            cmd.Parameters.Add(crcTagParam);

            SqlParameter crcFlagParam = new SqlParameter($"@CRC_FLAG_{index}", SqlDbType.TinyInt);
            crcFlagParam.Value = valueTuple.Item4;
            cmd.Parameters.Add(crcFlagParam);
        }

        connection.Open();
        return cmd.ExecuteReader();
    }
}
