using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.IO;
using System.Threading;

public class DatabaseHandler
{
    private readonly object _lockObject = new object();
    private readonly string _connectionString;
    private readonly string _logFilePath;
    private int _maxConcurrentConnections;

    public DatabaseHandler(string connectionString, string logFilePath, int maxConcurrentConnections)
    {
        _connectionString = connectionString;
        _logFilePath = logFilePath;
        _maxConcurrentConnections = maxConcurrentConnections;
    }

    public void InsertData(List<NFAPI_CRC_INDICATION_PDU_T> records, string sqlCommandTemplate)
    {
        try
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                connection.Open();
                using (var transaction = connection.BeginTransaction())
                {
                    int processedRecords = 0;

                    foreach (var record in records)
                    {
                        lock (_lockObject) // Ensuring thread safety
                        {
                            var command = new SqlCommand(sqlCommandTemplate, connection, transaction);
                            command.Parameters.AddWithValue("@RX_UE_INFORMATION_TAG", record.RX_UE_INFORMATION_TAG);
                            command.Parameters.AddWithValue("@RNTI", record.RNTI);
                            command.Parameters.AddWithValue("@CRC_INDICATION_REL8_TAG", record.CRC_INDICATION_REL8_TAG);
                            command.Parameters.AddWithValue("@CRCFLAG", record.CRCFLAG);

                            try
                            {
                                command.ExecuteNonQuery();
                                processedRecords++;
                            }
                            catch (SqlException ex)
                            {
                                LogError($"SQL Error: {ex.Message}");
                                transaction.Rollback();
                                return;
                            }
                        }
                    }

                    transaction.Commit();
                }
            }

            LogInfo($"Processed {processedRecords} records successfully.");
        }
        catch (Exception ex)
        {
            LogError($"Database operation failed: {ex.Message}");
        }
    }

    private void LogInfo(string message)
    {
        lock (_lockObject)
        {
            File.AppendAllText(_logFilePath, $"{DateTime.Now}: INFO - {message}\n");
        }
    }

    private void LogError(string message)
    {
        lock (_lockObject)
        {
            File.AppendAllText(_logFilePath, $"{DateTime.Now}: ERROR - {message}\n");
        }
    }

    public static class Logger
    {
        private static readonly string logDirectory = "Logs";
        private static int maxLogSizeMB = 5;
        private static LogLevel currentLogLevel = LogLevel.INFO;

        public enum LogLevel { INFO, DEBUG, ERROR }

        public static void ConfigureLogging(int maxLogSize, LogLevel level)
        {
            maxLogSizeMB = maxLogSize;
            currentLogLevel = level;
            if (!Directory.Exists(logDirectory))
                Directory.CreateDirectory(logDirectory);
        }

        public static void RotateLogs()
        {
            string logFilePath = Path.Combine(logDirectory, $"log_{DateTime.Now:yyyyMMdd}.txt");
            if (File.Exists(logFilePath) && new FileInfo(logFilePath).Length > maxLogSizeMB * 1024 * 1024)
            {
                File.Move(logFilePath, Path.Combine(logDirectory, $"{DateTime.Now:yyyyMMdd}_backup.txt"));
            }
        }

        public static void Log(string level, string message)
        {
            if (level == currentLogLevel.ToString() || level.Equals("ERROR"))
            {
                RotateLogs();
                string logFilePath = Path.Combine(logDirectory, $"log_{DateTime.Now:yyyyMMdd}.txt");
                File.AppendAllText(logFilePath, $"{DateTime.UtcNow}: {level} - {message}\n");
            }
        }

        public static void LogInfo(string message) => Log("INFO", message);
        public static void LogError(string message) => Log("ERROR", message);
    }
}

public struct NFAPI_CRC_INDICATION_PDU_T
{
    public uint RX_UE_INFORMATION_TAG;
    public ushort RNTI;
    public byte CRC_INDICATION_REL8_TAG;
    public byte CRCFLAG;
}
