    ErrorCode error_code = SUCCESS;

    if (num_entries <= 0 || num_entries > MAX_NFAPI_CRC_INDICATION_ENTRIES || !hostname || !ip_addr_array) {
        strncpy((char*)status_message, "Invalid input parameters", sizeof(status_message));
        return FAILURE_INVALID_INPUT;
    }

    pthread_mutex_init(&lock, NULL);
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T* nfa_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfa_list) {
        strncpy((char*)status_message, "Memory allocation failed", sizeof(status_message));
        pthread_mutex_unlock(&lock);
        return FAILURE_MEMORY_ALLOCATION;
