        nfa_list[i].RNTI = rand() % 10000;
        snprintf(nfa_list[i].RX_UE_INFORMATION_TAG, sizeof(nfa_list[i].RX_UE_INFORMATION_TAG), "Tag_%d", i);
        nfa_list[i].CRC_INDICATION_REL8_TAG = rand();
        nfa_list[i].CRCFLAG = (unsigned short)(rand() % (1 << CRCFLAG_BIT_WIDTH));
    }

    struct hostent* host_info = gethostbyname(hostname);
    if (!host_info) {
        strncpy((char*)status_message, "DNS resolution failed", sizeof(status_message));
        free(nfa_list);
        pthread_mutex_unlock(&lock);
        return FAILURE_DNS_RESOLUTION;
    }

    memcpy(ip_addr_array, host_info->h_addr, host_info->h_length);

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);
    free(nfa_list);

    snprintf((char*)status_message, sizeof(status_message), "Success: IP address resolved and list created");
    return SUCCESS;
}
