#define MAX_PDU_COUNT 100

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RNTI;
    unsigned short RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

void log_error(const char *error_message) {
    // Placeholder for centralized logging service integration
    fprintf(stderr, "Error: %s\n", error_message);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu_data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed for node");
        return NULL;
    }
    new_node->data = pdu_data;
    new_node->next = NULL;
    return new_node;
}

void append_to_list(Node** head, NFAPI_CRC_INDICATION_PDU_T pdu_data) {
    Node* new_node = create_node(pdu_data);
    if (!new_node) return;

    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

Node* populate_list(int count, int max_pdu_count) {
    if (count > max_pdu_count) {
        log_error("Requested list size exceeds maximum allowed");
        return NULL;
    }

    Node* head = NULL;
    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu_data;
        pdu_data.RX_UE_INFORMATION_TAG = rand() % 10000;
        pdu_data.RNTI = rand() % 100000;
        pdu_data.crc_tag.CRCFLAG = rand() % 2;

        append_to_list(&head, pdu_data);
    }

    return head;
}

void serialize_list(Node* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_error("Failed to open file for writing");
        return;
    }

    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next_node;

    while (current != NULL) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    *head = NULL;
}

int main() {
    int pdu_count = 50; // Example count
    const char* filename = "nfa_crc_data.bin";

    Node* list_head = populate_list(pdu_count, MAX_PDU_COUNT);
    if (list_head == NULL) return EXIT_FAILURE;

    serialize_list(list_head, filename);

    free_list(&list_head);
    return EXIT_SUCCESS;
}
