int initializeDataPackets(DataPacket **data_packets, size_t max_length, int (*getData)(void *, size_t)) {
    if (max_length > MAX_PACKETS) {
        fprintf(stderr, "Error: Exceeded maximum packet limit.\n");
        return -1;
