// Definitions for NFAPI_CRC_INDICATION_PDU_T and related structures
typedef struct {
    uint8_t *rnti; // Assuming RNTI is represented as a byte array
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint16_t crcValue;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    uint8_t rntiSize; // To store the size of RNTI
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    int crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
void generate_pdus(int count);
int perform_parity_check(uint8_t *rnti, uint32_t rntiSize);
void* log_performance(void *arg);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int main() {
    int num_pdus = 1000; // Example number of PDUs to generate
    generate_pdus(num_pdus);

    return 0;
}

void generate_pdus(int count) {
    if (count > 1000 || count <= 0) {
        printf("Count must be between 1 and 1000.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    if (!pdus) {
        perror("Memory allocation failed");
        return;
    }

    pthread_t logger_thread;
    if (pthread_create(&logger_thread, NULL, log_performance, pdus) != 0) {
        perror("Failed to create logging thread");
        free(pdus);
        return;
    }

    clock_t start_time = clock();

    for (int i = 0; i < count; ++i) {
        pdus[i].rxUeInformationTag.rnti = malloc(5); // Example size
        if (!pdus[i].rxUeInformationTag.rnti) {
            perror("Memory allocation failed");
            free(pdus);
            return;
        }

        // Populate RNTI with example data (could be replaced by real values)
        for (int j = 0; j < 5; ++j) {
            pdus[i].rxUeInformationTag.rnti[j] = rand() % 256;
        }
        pdus[i].rntiSize = 5;

        // Perform parity check and set CRC flag
        pdus[i].crcFlag = perform_parity_check(pdus[i].rxUeInformationTag.rnti, pdus[i].rntiSize);

        // Example CRC value (could be replaced with real calculations)
        pdus[i].crcIndicationRel8Tag.crcValue = rand() % 65536;
    }

    clock_t end_time = clock();
    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;

    pthread_mutex_lock(&lock);
    printf("Time taken: %.6f seconds\n", time_taken);
    free(pdus); // Free the main array of PDUs
    pthread_mutex_unlock(&lock);

    if (pthread_join(logger_thread, NULL) != 0) {
        perror("Failed to join logging thread");
    }
}

int perform_parity_check(uint8_t *rnti, uint32_t rntiSize) {
    int parity = 0;
    for (uint32_t i = 0; i < rntiSize; ++i) {
        parity ^= rnti[i];
    }
    return parity == 0 ? 1 : 0; // Return 1 if even parity, 0 otherwise
}

void* log_performance(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)arg;

    pthread_mutex_lock(&lock);
    int allocation_failures = 0;

    for (int i = 0; i < 1000; ++i) {
        if (!pdus[i].rxUeInformationTag.rnti) {
            allocation_failures++;
        }
    }

    printf("Number of allocation failures: %d\n", allocation_failures);

    pthread_mutex_unlock(&lock);
    return NULL;
}
