#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>

#define DEFAULT_TIMEOUT 30

// Utility function to check file existence and type
int is_valid_jpeg(const char *filename) {
    struct stat st;
    if (stat(filename, &st) != 0) return 0;

    FILE *file = fopen(filename, "rb");
    if (!file) return 0;

    unsigned char magic[2];
    fread(magic, sizeof(unsigned char), 2, file);
    fclose(file);

    // Check for JPEG header
    return (magic[0] == 0xFF && magic[1] == 0xD8);
}

// Utility function to create directories if they don't exist
int ensure_directory(const char *path) {
    struct stat st = {0};
    if (stat(path, &st) == -1) {
        return mkdir(path, 0700);
    }
    return 0;
}

// Function to execute a command with timeout and error handling
int execute_command_with_timeout(char *cmd, int timeout_seconds) {
    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", cmd, NULL);
        exit(EXIT_FAILURE); // If execl fails
    } else if (pid < 0) {
        return -1; // Fork failed
    }

    int status;
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    do {
        pid_t wpid = waitpid(pid, &status, WNOHANG);
        if (wpid == 0) { // Still running
            clock_gettime(CLOCK_MONOTONIC, &end);
            double elapsed = end.tv_sec - start.tv_sec + (end.tv_nsec - start.tv_nsec) / 1e9;
            if (elapsed >= timeout_seconds) {
                kill(pid, SIGKILL);
                return -1; // Timeout
            }
            usleep(100000); // Sleep for 0.1 seconds
        } else if (wpid == pid) {
            break; // Process finished
        }
    } while (1);

    return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 0 : -1;
}

// Main function to convert JPEG to PDF
int jpeg_to_pdf(const char *input_file, const char *output_file, 
                const char *page_size, const char *orientation, int quality, int timeout) {
    if (!is_valid_jpeg(input_file)) {
        fprintf(stderr, "Input file is not a valid JPEG.\n");
        return 1;
    }

    // Ensure output directory exists
    char output_dir[PATH_MAX];
    snprintf(output_dir, sizeof(output_dir), "%s", dirname(output_file));
    if (ensure_directory(output_dir) != 0) {
        perror("Failed to create output directory");
        return 1;
    }

    // Check for conflicting file paths
    if (strcmp(input_file, output_file) == 0) {
        fprintf(stderr, "Input and output files cannot be the same.\n");
        return 1;
    }

    char cmd[512];
    snprintf(cmd, sizeof(cmd), 
             "convert %s -quality %d -page %s -rotate %s %s", 
             input_file, quality, page_size ? page_size : "A4", orientation ? orientation : "0", output_file);

    // Execute the conversion command with a timeout
    if (execute_command_with_timeout(cmd, timeout < 1 ? DEFAULT_TIMEOUT : timeout) != 0) {
        fprintf(stderr, "Conversion failed or timed out.\n");
        return 1;
    }

    return 0; // Success
}

// Main entry point for testing the function
int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    const char *input_file = argv[1];
    const char *output_file = argv[2];

    // Example configuration options
    const char *page_size = "A4";
    const char *orientation = "0";
    int quality = 90; // Default quality
    int timeout = DEFAULT_TIMEOUT;

    return jpeg_to_pdf(input_file, output_file, page_size, orientation, quality, timeout);
}
