// Function Implementations
LinkedListManager* create_linked_list_manager(size_t max_limit, unsigned int seed) {
    LinkedListManager* manager = (LinkedListManager*)malloc(sizeof(LinkedListManager));
    if (!manager) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->head = NULL;
    manager->count = 0;

    srand(seed); // Seed for reproducibility

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, refresh_data_source, (void*)manager) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        free(manager);
        return NULL;
    }

    pthread_detach(thread_id);

    return manager;
}

void free_linked_list(LinkedListManager* manager) {
    Node* current = manager->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_entry(LinkedListManager* manager, NFAPI_CRC_INDICATION_PDU_T entry, size_t max_limit) {
    if (max_limit == 0 || manager->count >= max_limit) return -1;

    pthread_mutex_lock(&manager->lock);

    // Check for duplicate RX_UE_INFORMATION_TAG
    Node* current = manager->head;
    while (current != NULL) {
        if (current->data.rx_ue_info_tag.RX_UE_INFORMATION_TAG == entry.rx_ue_info_tag.RX_UE_INFORMATION_TAG) {
            fprintf(stderr, "Duplicate RX_UE_INFORMATION_TAG detected: %d\n", entry.rx_ue_info_tag.RX_UE_INFORMATION_TAG);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        current = current->next;
    }

    // Allocate new node
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation error\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    // Initialize new entry with random CRCFLAG
    newNode->data = entry;
    newNode->data.crc_indication_rel8_tag.CRCFLAG = rand() % 2;

    // Add to list
    newNode->next = manager->head;
    manager->head = newNode;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

