#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define MAX_PROCESSES 20
#define COMMAND_TIMEOUT 30
#define RETRY_LIMIT 3

typedef struct {
    char command[256];
} CommandRequest;

int active_processes = 0;
sem_t process_sem;
FILE *log_files[MAX_PROCESSES];

void handle_sigchld(int sig) {
    pid_t pid;
    int status;
    while ((pid = waitpid(-1, &status, WNOHANG)) > 0) {
        if (WIFEXITED(status) || WIFSIGNALED(status)) {
            active_processes--;
            sem_post(&process_sem);
        }
    }
}

void execute_command(const char *command, int attempt) {
    pid_t pid;
    int status;
    char log_filename[256];
    snprintf(log_filename, sizeof(log_filename), "%s.log", command);

    FILE *log_file = fopen(log_filename, "a");
    if (!log_file) {
        perror("fopen");
        return;
    }
    log_files[attempt] = log_file;

    pid = fork();
    if (pid == 0) { // Child process
        signal(SIGTERM, SIG_DFL);
        dup2(fileno(log_file), STDOUT_FILENO);
        dup2(fileno(log_file), STDERR_FILENO);

        execl("/bin/sh", "sh", "-c", command, NULL);
        perror("execl");
        exit(EXIT_FAILURE);
    } else if (pid < 0) {
        perror("fork");
    } else { // Parent process
        struct timespec start_time, current_time;
        clock_gettime(CLOCK_REALTIME, &start_time);

        while ((active_processes < MAX_PROCESSES || pid != waitpid(pid, &status, WNOHANG)) && active_processes > 0) {
            clock_gettime(CLOCK_REALTIME, &current_time);
            long elapsed = (current_time.tv_sec - start_time.tv_sec) * 1000000000L + (current_time.tv_nsec - start_time.tv_nsec);

            if (elapsed / 1000000000L >= COMMAND_TIMEOUT) {
                kill(pid, SIGTERM);
                waitpid(pid, &status, 0); // Ensure cleanup
                fprintf(log_file, "Command timed out\n");
            }
        }

        fclose(log_file);
    }
}

void *process_command(void *arg) {
    CommandRequest *request = (CommandRequest *)arg;
    int attempt;

    for (attempt = 0; attempt < RETRY_LIMIT; ++attempt) {
        execute_command(request->command, attempt);

        // Simulate command execution check
        pid_t pid = waitpid(-1, NULL, WNOHANG);
        if (pid == request->command[0] - '0') { // Placeholder for success check
            break;
        }
    }

    return NULL;
}

void handle_commands(CommandRequest *requests, size_t count) {
    pthread_t threads[MAX_PROCESSES];
    sem_init(&process_sem, 0, MAX_PROCESSES);

    signal(SIGCHLD, handle_sigchld);

    for (size_t i = 0; i < count; ++i) {
        while (sem_trywait(&process_sem) == -1); // Wait if max processes are active

        pthread_create(&threads[i % MAX_PROCESSES], NULL, process_command, &requests[i]);
        active_processes++;
    }

    for (size_t i = 0; i < count; ++i) {
        pthread_join(threads[i % MAX_PROCESSES], NULL);
    }
}

int main() {
    CommandRequest requests[] = {
        {"echo 'Command 1'"},
        {"echo 'Command 2'"},
        // Add more commands as needed
    };

    size_t request_count = sizeof(requests) / sizeof(requests[0]);
    handle_commands(requests, request_count);

    sem_destroy(&process_sem);
    return 0;
}
```']

