    unsigned int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef void (*CompletionCallback)(int result, NFAPI_CRC_INDICATION_PDU_T *data, size_t count);

// Configuration structure
typedef struct {
    size_t max_memory_usage; // in bytes
    size_t max_structures_per_rnti;
} Config;

// Global configuration
Config config = {1024 * 1024, 100}; // Example values

// Mutex for thread safety
threading.Lock lock = threading.Lock();

// Logging setup
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("NFAPI_CRC_INDICATION")

// Function to allocate and populate the array
int create_crc_indication_pdu_array(size_t n, int compress, CompletionCallback callback) {
    with lock:
        // Validate input
        if (n == 0 || callback == NULL) return -1;

        size_t required_memory = sizeof(NFAPI_CRC_INDICATION_PDU_T) * n;
        if (required_memory > config.max_memory_usage) {
            logger.error("Exceeded maximum allowed memory usage")
            return -2; // Memory limit exceeded
        }

        NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(required_memory);
        if (!array) {
            logger.error("Memory allocation failed")
            return -3; // Allocation failure
        }

        // Populate the array with example data
        for (size_t i = 0; i < n; ++i) {
            array[i].RX_UE_INFORMATION_TAG = rand() % 256;
            array[i].RNTI = i + 1;
            array[i].CRCFLAG = rand() % 2;
        }

        // Optional compression
        if (compress) {
            unsigned long compressed_size = compressBound(required_memory);
            unsigned char *compressed_data = (unsigned char *)malloc(compressed_size);
            if (!compressed_data) {
                free(array);
                logger.error("Compression memory allocation failed")
                return -4; // Compression allocation failure
            }

            int result = compress2(compressed_data, &compressed_size, (const Bytef *)array, required_memory, Z_BEST_COMPRESSION);
            if (result != Z_OK) {
                free(compressed_data);
                free(array);
                logger.error("Compression failed")
                return -5; // Compression failure
            }

            free(array); // Original data no longer needed
            array = (NFAPI_CRC_INDICATION_PDU_T *)compressed_data;
        }

        if (callback != NULL) {
            callback(0, array, n);
            return 0;
        }
    return 0; // Success in synchronous mode
}

// Asynchronous version using threading
void create_crc_indication_pdu_array_async(size_t n, int compress, CompletionCallback callback) {
    threading.Thread(target=create_crc_indication_pdu_array, args=(n, compress, callback)).start()
}

// Decompression function (assuming the data is compressed)
int decompress_data(NFAPI_CRC_INDICATION_PDU_T *compressed_data, size_t compressed_size, NFAPI_CRC_INDICATION_PDU_T **decompressed_data) {
    unsigned long decompressed_size = config.max_memory_usage; // Max possible size
    *decompressed_data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(decompressed_size);
    if (!*decompressed_data) return -1;

    int result = uncompress((Bytef *)(*decompressed_data), &decompressed_size, compressed_data, compressed_size);
    if (result != Z_OK) {
        free(*decompressed_data);
        return -2; // Decompression failure
    }

    return 0; // Success
}

// Example usage of the async function with a callback
void completion_callback(int result, NFAPI_CRC_INDICATION_PDU_T *data, size_t count) {
    if (result == 0) {
        logger.info("Data creation completed successfully")
    } else {
        logger.error(f"Data creation failed with error code {result}")
    }

    // Free resources after use
    free(data)
}

int main() {
    create_crc_indication_pdu_array_async(10, 1, completion_callback)

    return 0;
}
