#include <pthread.h>

typedef struct {
    uint8_t destinationAddress[6]; // Assuming MAC addresses for simplicity
    uint8_t sourceAddress[6];
    size_t payloadSize;
    uint8_t *payloadData; // Pointer to the allocated payload data
} NetworkLayerPacketInfo;

#define MAX_PAYLOAD_SIZE 1500 // Example max size, can be adjusted based on network standards

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

typedef enum {
    SUCCESS,
    ERROR_MEMORY_ALLOCATION_FAILED,
    ERROR_INVALID_INPUT
} ErrorCode;

ErrorCode initializeNetworkLayerPackets(NetworkLayerPacketInfo *packets, size_t packetCount) {
    if (!packets || packetCount == 0) {
        return ERROR_INVALID_INPUT;
    }

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < packetCount; ++i) {
        // Simulate random MAC addresses
        for (int j = 0; j < 6; ++j) {
            packets[i].destinationAddress[j] = rand() % 256;
            packets[i].sourceAddress[j] = rand() % 256;
        }

        // Example payload size, should be determined based on system requirements
        packets[i].payloadSize = (rand() % MAX_PAYLOAD_SIZE) + 1;

        packets[i].payloadData = malloc(packets[i].payloadSize);
        if (!packets[i].payloadData) {
            pthread_mutex_unlock(&mutex);
            return ERROR_MEMORY_ALLOCATION_FAILED;
        }

        // Fill the payload with random bytes
        for (size_t j = 0; j < packets[i].payloadSize; ++j) {
            ((uint8_t *)packets[i].payloadData)[j] = rand() % 256;
        }
    }

    pthread_mutex_unlock(&mutex);
    return SUCCESS;
}

void freeNetworkLayerPackets(NetworkLayerPacketInfo *packets, size_t packetCount) {
    if (!packets || packetCount == 0) {
        return;
    }

    for (size_t i = 0; i < packetCount; ++i) {
        free(packets[i].payloadData);
        packets[i].payloadData = NULL;
    }
}

int main() {
    size_t packetCount = 10; // Example packet count
    NetworkLayerPacketInfo *packets = malloc(packetCount * sizeof(NetworkLayerPacketInfo));
    if (!packets) {
        fprintf(stderr, "Memory allocation failed for packet array.\n");
        return EXIT_FAILURE;
    }

    ErrorCode result = initializeNetworkLayerPackets(packets, packetCount);
    if (result != SUCCESS) {
        fprintf(stderr, "Failed to initialize packets: %d\n", result);
        free(packets);
        return EXIT_FAILURE;
    }

    // Example usage of the packets
    for (size_t i = 0; i < packetCount; ++i) {
        printf("Packet %zu: Source Address: ", i + 1);
        for (int j = 0; j < 6; ++j) {
            printf("%02x", packets[i].sourceAddress[j]);
            if (j < 5) printf(":");
        }
        printf(", Payload Size: %zu\n", packets[i].payloadSize);
    }

    freeNetworkLayerPackets(packets, packetCount);
    free(packets);

    return EXIT_SUCCESS;
}
```

### Key Points:

1. **Memory Management**: The function allocates memory for each packet's payload and ensures it is freed after use.

