// Define the structure for CRC indication PDU
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG:1; // Assuming a single bit for CRC flag
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a structure to manage the list of PDUs
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PduList;

// Function prototypes
void initializePduList(PduList *list, size_t initialCapacity);
void resizePduList(PduList *list);
void addPdu(PduList *list);
void deallocatePduList(PduList *list);
void logEntry(const NFAPI_CRC_INDICATION_PDU_T *pdu, int index);
int validatePdu(const NFAPI_CRC_INDICATION_PDU_T *pdu);

// Initialize the PDU list
void initializePduList(PduList *list, size_t initialCapacity) {
    pthread_mutex_init(&list->lock, NULL);
    list->capacity = initialCapacity;
    list->size = 0;
    list->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Resize the PDU list when capacity is exceeded
void resizePduList(PduList *list) {
    size_t newCapacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *newPdus = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->pdus, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newPdus) {
        list->pdus = newPdus;
        list->capacity = newCapacity;
    } else {
        perror("Failed to resize PDU list");
        exit(EXIT_FAILURE);
    }
}

// Add a new PDU to the list
void addPdu(PduList *list) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        resizePduList(list);
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &list->pdus[list->size];
    pdu->RX_UE_INFORMATION_TAG = rand() % 100; // Example random value
    pdu->RNTI = rand() % 1000;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) ? 1 : 0;

    if (validatePdu(pdu)) {
        list->size++;
        logEntry(pdu, list->size - 1);
    } else {
        printf("Invalid PDU at index %zu\n", list->size);
    }

    pthread_mutex_unlock(&list->lock);
}

// Deallocate the PDU list
void deallocatePduList(PduList *list) {
    free(list->pdus);
    pthread_mutex_destroy(&list->lock);
}

// Log entry for a PDU
void logEntry(const NFAPI_CRC_INDICATION_PDU_T *pdu, int index) {
    time_t now = time(NULL);
    printf("Index: %d, Timestamp: %ld, RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %u\n",
           index, now, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);
}

// Validate a PDU
int validatePdu(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Example validation logic
    return pdu->RX_UE_INFORMATION_TAG > 0 && pdu->RNTI > 0;
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL)); // Seed random number generator

    PduList list;
    initializePduList(&list, 10);

    for (int i = 0; i < 20; ++i) {
        addPdu(&list);
    }

    deallocatePduList(&list);
    return 0;
}
```

This code provides a thread-safe implementation for managing a list of `NFAPI_CRC_INDICATION_PDU_T` structures. It includes functions to initialize, resize, add, and deallocate the list while ensuring efficient memory usage and minimizing heap fragmentation. The logging function captures relevant details for each PDU entry, and validation ensures only valid entries are processed.']

