#define PAYLOAD_SIZE_LIMIT 1024

typedef struct {
    char DestinationAddress[256];
    char SourceAddress[256];
    size_t PayloadSize;
    unsigned char* PayloadData;
} NetworkLayerPacketInfo;

int isStringValid(const char *str, size_t maxSize) {
    return str != NULL && strlen(str) < maxSize;
}

size_t calculateOptimalBufferSize() {
    // Placeholder for logic to determine optimal buffer size
    // This should consider network latency, packet loss rate,
    // and current system resource usage.
    return PAYLOAD_SIZE_LIMIT;  // Example fixed size
}

NetworkLayerPacketInfo* initializeAndProcessNetworkData(const char *destinationAddress, const char *sourceAddress, size_t payloadSizeLimit, DOMElement domElement) {
    if (!isStringValid(destinationAddress, sizeof(NetworkLayerPacketInfo).DestinationAddress) ||
        !isStringValid(sourceAddress, sizeof(NetworkLayerPacketInfo).SourceAddress)) {
        return NULL;
    }

    if (strlen(destinationAddress) >= sizeof(NetworkLayerPacketInfo).DestinationAddress - 1) {
        return NULL; // No space for '/'
    }
    strcat(destinationAddress, "/");

    NetworkLayerPacketInfo *packets = malloc(MAX_PACKETS * sizeof(NetworkLayerPacketInfo));
    if (!packets) {
        return NULL;
    }

    size_t bufferSize = calculateOptimalBufferSize();
    if (bufferSize > payloadSizeLimit) {
        free(packets);
        return NULL;
    }

    for (int i = 0; i < MAX_PACKETS; ++i) {
        packets[i].PayloadSize = bufferSize;

        packets[i].PayloadData = malloc(bufferSize);
        if (!packets[i].PayloadData) {
            // Free previously allocated memory
            while (--i >= 0) {
                free(packets[i].PayloadData);
            }
            free(packets);
            return NULL;
        }

        strncpy(packets[i].DestinationAddress, destinationAddress, sizeof(packets[i].DestinationAddress) - 1);
        packets[i].DestinationAddress[sizeof(packets[i].DestinationAddress) - 1] = '\0';
        strncpy(packets[i].SourceAddress, sourceAddress, sizeof(packets[i].SourceAddress) - 1);
        packets[i].SourceAddress[sizeof(packets[i].SourceAddress) - 1] = '\0';

        // Fill payload with random data
        srand(time(NULL) + i); // Seed for randomness
        for (size_t j = 0; j < bufferSize; ++j) {
            packets[i].PayloadData[j] = rand() % 256;
        }
    }

    return packets;
}
