```javascript
function getElementList(element, selector) {
    const matchesSelector = (node, selector) => node.matches(selector);
    let result = [];

    function traverse(node) {
        if (!node || typeof node !== 'object') return;

        // Apply the provided function to check if it matches the selector
        if (matchesSelector(node, selector)) {
            result.push(node);
        }

        for (let child of node.children) {
            traverse(child);
        }
    }

    traverse(element);

    return result;
}
```

