#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RETRIES 5
#define INITIAL_BACKOFF_MS 100

typedef struct {
    unsigned char DestinationAddress[6];
    unsigned char SourceAddress[6];
    size_t PayloadSize;
    void *PayloadData;
} NetworkLayerPacketInfo;

// Function to generate random bytes for payload
void fill_random_bytes(void *buffer, size_t size) {
    if (buffer && size > 0) {
        srand(time(NULL));
        unsigned char *ptr = buffer;
        while (size--) {
            *(ptr++) = rand() % 256;
        }
    }
}

// Retry logic with exponential backoff
int fetch_nic_settings_with_retry(int (*fetch_func)(void)) {
    int retries = 0;
    int delay_ms = INITIAL_BACKOFF_MS;

    while (retries < MAX_RETRIES) {
        if (fetch_func()) {
            return 1; // Success
        }
        usleep(delay_ms * 1000); // Convert ms to us
        delay_ms *= 2;
        retries++;
    }
    return 0; // Failure after max retries
}

// Thread-safe function to initialize packet info array
NetworkLayerPacketInfo* init_packet_info_array(size_t count, int (*fetch_nic_settings)(void)) {
    if (count == 0) {
        fprintf(stderr, "Invalid input parameter: count is zero.\n");
        return NULL;
    }

    NetworkLayerPacketInfo *packetArray = malloc(count * sizeof(NetworkLayerPacketInfo));
    if (!packetArray) {
        perror("Failed to allocate memory for packet info array");
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&lock);

        // Fetch NIC settings with retry logic
        if (!fetch_nic_settings_with_retry(fetch_nic_settings)) {
            fprintf(stderr, "Failed to fetch NIC settings\n");
            free(packetArray);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        // Initialize packet info structure
        fill_random_bytes(packetArray[i].DestinationAddress, sizeof(packetArray[i].DestinationAddress));
        fill_random_bytes(packetArray[i].SourceAddress, sizeof(packetArray[i].SourceAddress));
        packetArray[i].PayloadSize = rand() % 1024; // Example payload size limit

        packetArray[i].PayloadData = malloc(packetArray[i].PayloadSize);
        if (!packetArray[i].PayloadData) {
            perror("Failed to allocate memory for payload data");
            free(packetArray); // Free already allocated structures
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        fill_random_bytes(packetArray[i].PayloadData, packetArray[i].PayloadSize);

        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
    return packetArray;
}

// Example NIC settings fetch function (stub)
int example_fetch_nic_settings(void) {
    // Simulate network latency and transient error handling
    static int failure_count = 0;
    if (failure_count++ < 3) {
        return 0; // Simulate failure
    }
    return 1; // Simulate success after retries
}

// Example usage
int main() {
    size_t packet_count = 10;

    NetworkLayerPacketInfo *packets = init_packet_info_array(packet_count, example_fetch_nic_settings);
    if (packets) {
        printf("Successfully initialized %zu packet info structures.\n", packet_count);

        // Free allocated resources
        for (size_t i = 0; i < packet_count; ++i) {
            free(packets[i].PayloadData);
        }
        free(packets);
    } else {
        fprintf(stderr, "Failed to initialize packet info array.\n");
    }

    return 0;
}
