#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>  // For DNS resolution functions
#include <netdb.h>      // For getaddrinfo and freeaddrinfo

#define MAX_STRUCTURES 1024
#define BIT_WIDTH 8
#define SUCCESS 0
#define FAILURE -1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG : BIT_WIDTH; // Ensuring bit width compatibility
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int resolve_hostname_to_ip(const char *hostname, u_char ip_address[4]) {
    struct addrinfo hints, *res, *p;
    int status;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return FAILURE; // DNS resolution failed
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        if (ipv4) {
            memcpy(ip_address, &(ipv4->sin_addr), sizeof(struct in_addr));
            freeaddrinfo(res);
            return SUCCESS;
        }
    }

    freeaddrinfo(res);
    return FAILURE; // No valid address found
}

int create_and_process_structures(int N, const char *hostname) {
    if (N > MAX_STRUCTURES || N <= 0) {
        printf("Invalid number of structures requested.\n");
        return FAILURE;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T *structures = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        perror("Memory allocation failed");
        return FAILURE;
    }

    // Populate the array with random CRCFLAG
    for (int i = 0; i < N; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
        structures[i].RNTI = rand() % 1000;
        structures[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (unsigned char)(rand() % (1 << BIT_WIDTH));
    }

    u_char ip_address[4];
    int dns_status = resolve_hostname_to_ip(hostname, ip_address);
    if (dns_status == FAILURE) {
        free(structures);
        printf("DNS resolution failed for hostname: %s\n", hostname);
        return FAILURE;
    }

    // Read sequence of integers from standard input
    char line[256];
    int *integers = NULL;
    size_t count = 0;

    while (fgets(line, sizeof(line), stdin)) {
        if (count == 0) { // First line to determine initial capacity
            integers = (int *)malloc(10 * sizeof(int));
            if (!integers) {
                perror("Memory allocation failed");
                free(structures);
                return FAILURE;
            }
        } else if (count % 10 == 0) { // Reallocate as needed
            int *temp = (int *)realloc(integers, (count + 10) * sizeof(int));
            if (!temp) {
                perror("Memory reallocation failed");
                free(structures);
                free(integers);
                return FAILURE;
            }
            integers = temp;
        }

        char *endptr;
        int value = strtol(line, &endptr, 10);

        // Check for invalid integer input
        if (*endptr != '\n' && *endptr != '\0') {
            printf("Invalid integer data encountered: %s\n", line);
            free(structures);
            free(integers);
            return FAILURE;
        }

        integers[count++] = value;
    }

    // Find the largest integer
    if (count == 0) {
        free(structures);
        free(integers);
        printf("No valid integers were provided.\n");
        return FAILURE;
    }

    int max_value = integers[0];
    for (size_t i = 1; i < count; ++i) {
        if (integers[i] > max_value) {
            max_value = integers[i];
        }
    }

    printf("Largest integer: %d\n", max_value);

    // Clean up
    free(structures);
    free(integers);

    return SUCCESS;
}
