['Below is a Python implementation of the described task. It uses environment variables to determine the running context (development, staging, production), fetches keys/certificates for OAuth scopes from a mock configuration service, handles multiple certificates per scope, and concatenates them into a PEM file.

```python
import os
import logging
from typing import List

# Mock function to simulate fetching data from a configuration service.
def fetch_from_config_service(scope: str, environment: str):
    # Simulated response with private keys and certificates for different scopes and environments.
    config_data = {
        'development': {
            'scope1': {'key': 'dev_key_1', 'certs': ['dev_cert_1']},
            'scope2': {'key': 'dev_key_2', 'certs': ['dev_cert_2']},
        },
        'staging': {
            'scope1': {'key': 'stage_key_1', 'certs': ['stage_cert_1', 'fallback_stage_cert_1']},
            'scope3': {'key': 'stage_key_3', 'certs': ['stage_cert_3']},
        },
        'production': {
            'scope1': {'key': 'prod_key_1', 'certs': ['prod_cert_1']},
            'scope2': {'key': 'prod_key_2', 'certs': ['prod_cert_2']},
            'scope4': {'key': 'prod_key_4', 'certs': ['prod_cert_4']},
        }
    }

    # Simulate service unavailability.
    if os.urandom(1)[0] % 10 == 0:
        raise ConnectionError("Configuration service unavailable.")

    return config_data.get(environment, {}).get(scope)

def process_oauth_request(scopes: List[str], environment: str) -> str:
    pem_content = []
    missing_scopes = []

    for scope in scopes:
        try:
            # Fetch key and certificates for the given scope.
            data = fetch_from_config_service(scope, environment)

            if not data:
                logging.error(f"No configuration found for scope '{scope}' in environment '{environment}'.")
                missing_scopes.append(scope)
                continue

            pem_content.append(data['key'])
            pem_content.extend(data['certs'])

        except ConnectionError as e:
            logging.warning(f"Connection error while fetching for scope '{scope}': {e}")
            continue
        except Exception as e:
            logging.error(f"Unexpected error for scope '{scope}': {e}")

    if missing_scopes:
        raise ValueError(f"Scopes not found in configuration: {', '.join(missing_scopes)}")

    # Concatenate keys and certificates into a single PEM format.
    pem_file_content = '\n'.join([f'-----BEGIN CERTIFICATE-----\n{pem}\n-----END CERTIFICATE-----' if 'cert' in pem else f'PRIVATE KEY\n{pem}' for pem in pem_content])

    return pem_file_content

if __name__ == "__main__":
    # Example usage
    try:
        scopes = ['scope1', 'scope2']
        environment = os.getenv('ENVIRONMENT', 'development')
        pem_data = process_oauth_request(scopes, environment)
        print("PEM File Content:")
        print(pem_data)
    except ValueError as e:
        logging.error(e)
```

### Key Features:

- **Environment Handling**: Determines the current environment using an `ENVIRONMENT` environment variable.

