        pdu->RX_UE_INFORMATION_TAG = rand() % 10000 + 1; // Replace with valid range
        pdu->RNTI = rand() % 1000 + 1;                   // Replace with valid range
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

