            free(pdu);
            log_message("Validation failed for PDU data.");
            errorCount++;
            continue;
        }

        pdus_list[*list_size] = pdu;
        (*list_size)++;
        totalPDUsCreated++;
    }

    pthread_mutex_unlock(&lock);
}

// Function to clean up resources
void cleanup_resources(NFAPI_CRC_INDICATION_PDU_T **pdus_list, int list_size) {
