```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} UE_INFO_T;

typedef struct {
    int CRCFLAG;
    int CRC_INDICATION_REL8_TAG;
} CRC_TAG_T;

typedef struct {
    UE_INFO_T ue_info;
    CRC_TAG_T crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
} ArrayManager;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int initializeArray(ArrayManager* manager, size_t num_elements) {
    if (num_elements == 0 || num_elements > MAX_RNTI) return -1;

    manager->size = num_elements;
    manager->array = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) return -2; // Memory allocation failed

    srand(time(NULL));

    for (size_t i = 0; i < num_elements; ++i) {
        int rnti;
        do {
            rnti = rand() % MAX_RNTI + 1;
        } while (!is_unique_rnti(manager->array, i, rnti));

        manager->array[i].ue_info.RX_UE_INFORMATION_TAG = (int)i + 1; // Example tag
        manager->array[i].ue_info.RNTI = rnti;

        manager->array[i].crc_tag.CRCFLAG = rand() % 2;
        manager->array[i].crc_tag.CRC_INDICATION_REL8_TAG = (int)(i * 10) + 1; // Example tag
    }

    return 0;
}

int is_unique_rnti(NFAPI_CRC_INDICATION_PDU_T* array, size_t current_index, int rnti) {
    for (size_t i = 0; i < current_index; ++i) {
        if (array[i].ue_info.RNTI == rnti) return 0;
    }
    return 1;
}

void freeArray(ArrayManager* manager) {
    pthread_mutex_lock(&lock);
    free(manager->array);
    manager->size = 0;
    pthread_mutex_unlock(&lock);
}

int filterArray(const ArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T** filtered_array,
                size_t min_rnti, size_t max_rnti) {
    if (min_rnti > max_rnti || max_rnti > MAX_RNTI) return -1;

    size_t count = 0;
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].ue_info.RNTI >= min_rnti && manager->array[i].ue_info.RNTI <= max_rnti)
            count++;
    }

    *filtered_array = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*filtered_array) return -2;

    size_t index = 0;
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].ue_info.RNTI >= min_rnti && manager->array[i].ue_info.RNTI <= max_rnti)
            (*filtered_array)[index++] = manager->array[i];
    }

    return 0;
}

int compareCRCFLAG(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* entryA = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* entryB = (NFAPI_CRC_INDICATION_PDU_T*)b;
    return entryA->crc_tag.CRCFLAG - entryB->crc_tag.CRCFLAG;
}

void sortArray(NFAPI_CRC_INDICATION_PDU_T* array, size_t size) {
    qsort(array, size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compareCRCFLAG);
}

int exportToCSV(const NFAPI_CRC_INDICATION_PDU_T* array, size_t size, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return -1;

    for (size_t i = 0; i < size; ++i) {
        fprintf(file, "%d,%d,%d,%d\n", 
                array[i].ue_info.RX_UE_INFORMATION_TAG,
                array[i].ue_info.RNTI,
                array[i].crc_tag.CRCFLAG,
                array[i].crc_tag.CRC_INDICATION_REL8_TAG);
    }

    fclose(file);
    return 0;
}

void* threadFunction(void* arg) {
    ArrayManager* manager = (ArrayManager*)arg;

    // Thread-safe filtering and sorting
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T* filtered_array;
    if (filterArray(manager, &filtered_array, 1, MAX_RNTI / 2) == 0) {
        sortArray(filtered_array, manager->size);
        exportToCSV(filtered_array, manager->size, "output.csv");
        free(filtered_array);
    }

    pthread_mutex_unlock(&lock);

    return NULL;
}

void runTest() {
    ArrayManager manager;
    if (initializeArray(&manager, 100) != 0) {
        fprintf(stderr, "Failed to initialize array.\n");
        return;
    }

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, threadFunction, &manager);
    pthread_create(&thread2, NULL, threadFunction, &manager);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    freeArray(&manager);
}

int main() {
    runTest();
    return 0;
}
```

