#include <thread>
#include <mutex>
#include <random>
#include <chrono>
#include <condition_variable>
#include <atomic>

// Define structures and constants
struct RX_UE_INFORMATION_TAG {
    int RNTI;
    bool CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;

    void set_random_values() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> rnti_dist(1, 65535);
        std::bernoulli_distribution crc_dist(0.5);

        RNTI = rnti_dist(gen);
        CRC_INDICATION_REL8_TAG = crc_dist(gen);
        CRCFLAG = crc_dist(gen);
    }
};

struct State {
    RX_UE_INFORMATION_TAG ue_info;
    State* next = nullptr;
};

struct FSA {
    std::atomic<State*> head{nullptr};
    std::mutex mtx;
    bool is_running = false;
    int num_threads = 0;

    void send_status() {
        // Simulate sending status to an external messaging system
        std::cout << "FSA Status: Running\n";
        std::cout << "Worker Threads in Use: " << num_threads << "\n";
        State* current = head.load();
        while (current) {
            std::cout << "RNTI: " << current->ue_info.RNTI
                      << ", CRC_INDICATION_REL8_TAG: " << current->ue_info.CRC_INDICATION_REL8_TAG
                      << ", CRCFLAG: " << current->ue_info.CRCFLAG << "\n";
            current = current->next;
        }
    }

    void create_and_populate_state_list(int* states, int num_states, State*& new_list, int last_state_index) {
        std::unique_lock<std::mutex> lock(mtx);
        try {
            new_list = static_cast<State*>(std::malloc(num_states * sizeof(State)));
            if (!new_list) throw std::bad_alloc();

            for (int i = 0; i < num_states; ++i) {
                new_list[i].ue_info.set_random_values();
            }

            State* last_state = &new_list[last_state_index];
            last_state->next = head.load();
            head.store(new_list);
        } catch (...) {
            std::free(new_list);
            new_list = nullptr;
        }
    }

    void start() {
        is_running = true;
        num_threads++;
        while (is_running) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100 + rand() % 400));
            State* new_list = nullptr;
            create_and_populate_state_list(nullptr, 10, new_list, 9);
            send_status();
        }
    }

    void stop() {
        is_running = false;
    }

    void restart() {
        stop();
        start();
    }
};

int main() {
    FSA fsa;

    std::thread worker([&fsa]() { fsa.start(); });

    // Simulate external control
    std::this_thread::sleep_for(std::chrono::seconds(2));
    fsa.restart();

    std::this_thread::sleep_for(std::chrono::seconds(5));

    fsa.stop();
    if (worker.joinable()) {
        worker.join();
    }

    return 0;
}
