        (*array)[i].RX_UE_INFORMATION_TAG = (uint16_t)i + 1; // Unique tag
        (*array)[i].RNTI = (uint32_t)(i + 1) * 1001;         // Unique RNTI

        uint8_t data[] = {0x01, 0x02, 0x03, (uint8_t)i};   // Example data for CRC
        (*array)[i].CRC_INDICATION_REL8_TAG[0] = calculate_crc(data, sizeof(data) - 1);
        memcpy(&(*array)[i].CRC_INDICATION_REL8_TAG[1], &data[sizeof(data) - 1], 3);

        int signal_strength = measure_signal_strength();
        (*array)[i].checksum_valid = (calculate_crc((uint8_t *)(&(*array)[i]), sizeof(NFAPI_RX_INDICATION_PDU_T) - 4) == 
                                      (*array)[i].CRC_INDICATION_REL8_TAG[0]);

        if (signal_strength < signal_strength_threshold) {
            free(*array);
            *array = NULL;
            fprintf(stderr, "Packet discarded due to insufficient signal strength\n");
