#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int incoming;
    int outgoing;
} TrafficStats;

typedef struct {
    char imsi[16]; // Assuming IMSI is a 15-digit number with padding for null-termination
    int rnti;
    TrafficStats stats;
} UEContext;

typedef struct UEContextNode {
    UEContext context;
    struct UEContextNode* next;
} UEContextNode;

typedef struct {
    UEContextNode* head;
    pthread_mutex_t lock;
} UEContextList;

// Function prototypes
UEContextList* create_context_list();
void destroy_context_list(UEContextList* list);
int add_or_update_uecontext(UEContextList* list, const char* imsi, int rnti, TrafficStats stats);
UEContext* get_uecontext(const UEContextList* list, const char* imsi);
void integrate_with_database(UEContextList* list);
int database_insert_or_update(const char* imsi, int rnti, TrafficStats stats);
UEContext fetch_from_database(const char* imsi);

// Function definitions
UEContextList* create_context_list() {
    UEContextList* list = (UEContextList*)malloc(sizeof(UEContextList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_context_list(UEContextList* list) {
    if (!list) return;
    UEContextNode* current = list->head;
    while (current) {
        UEContextNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_or_update_uecontext(UEContextList* list, const char* imsi, int rnti, TrafficStats stats) {
    if (!list || !imsi) return -1;

    pthread_mutex_lock(&list->lock);

    UEContextNode* current = list->head;
    while (current) {
        if (strcmp(current->context.imsi, imsi) == 0) {
            current->context.rnti = rnti;
            current->context.stats = stats;
            pthread_mutex_unlock(&list->lock);
            return 0; // Updated existing context
        }
        current = current->next;
    }

    UEContextNode* new_node = (UEContextNode*)malloc(sizeof(UEContextNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    strcpy(new_node->context.imsi, imsi);
    new_node->context.rnti = rnti;
    new_node->context.stats = stats;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0; // Added new context
}

UEContext* get_uecontext(const UEContextList* list, const char* imsi) {
    if (!list || !imsi) return NULL;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    UEContextNode* current = list->head;
    while (current) {
        if (strcmp(current->context.imsi, imsi) == 0) {
            pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
            return &current->context;
        }
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return NULL; // Not found
}

void integrate_with_database(UEContextList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    UEContextNode* current = list->head;
    while (current) {
        database_insert_or_update(current->context.imsi, current->context.rnti, current->context.stats);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

int database_insert_or_update(const char* imsi, int rnti, TrafficStats stats) {
    // Placeholder for actual database integration logic
    printf("Database operation: Insert/Update IMSI %s\n", imsi);
    return 0; // Success
}

