    context.rnti = 1001;
    context.stats.incoming = 5000;
    context.stats.outgoing = 3000;

    return context; // Simulated fetch
}

int main() {
    UEContextList* list = create_context_list();
    if (!list) {
        fprintf(stderr, "Failed to initialize UE context list\n");
        return -1;
    }

    TrafficStats stats = {1000, 2000};
    add_or_update_uecontext(list, "123456789012345", 1001, stats);
    integrate_with_database(list);

    UEContext* context = get_uecontext(list, "123456789012345");
    if (context) {
        printf("Retrieved IMSI: %s, RNTI: %d\n", context->imsi, context->rnti);
    }

    destroy_context_list(list);
    return 0;
}
