#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} CRC_List;

// Initialize the linked list
void init_crc_list(CRC_List *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Validate the integrity of the linked list
int validate_crc_list(const NFAPI_CRC_INDICATION_PDU_T *node) {
    while (node != NULL) {
        if (node->crc_indication_rel8_tag.CRCFLAG < 0 || node->crc_indication_rel8_tag.CRCFLAG > 1)
            return 0; // Invalid CRCFLAG
        node = node->next;
    }
    return 1;
}

// Add a new element to the list
int add_crc_pdu(CRC_List *list, unsigned int rx_ue_info_tag, unsigned int rnti) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    new_node->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->RNTI = rnti;
    srand(time(NULL) ^ pthread_self()); // Seed with time and thread ID
    new_node->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG (0 or 1)
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Validate the integrity of the linked list
int validate_crc_list(CRC_List *list) {
    pthread_mutex_lock(&list->lock);
    int valid = validate_crc_list(list->head);
    pthread_mutex_unlock(&list->lock);

    if (!valid)
        fprintf(stderr, "Data corruption detected\n");

    return valid;
}

// Free the linked list
void free_crc_list(CRC_List *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    CRC_List list;
    init_crc_list(&list);

    add_crc_pdu(&list, 1, 100);
    add_crc_pdu(&list, 2, 101);

    if (!validate_crc_list(&list)) {
        fprintf(stderr, "Validation failed\n");
        free_crc_list(&list);
        return -1;
    }

    free_crc_list(&list);

    return 0;
}
