#define MAX_RNTIS 1000
#define MAX_CRC_FLAGS 16

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint16_t RNTI;
    int retry_count;
} RetryInfo;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

List list = {NULL, PTHREAD_MUTEX_INITIALIZER};
RetryInfo retry_info[MAX_RNTIS];
uint8_t used_crc_flags[MAX_CRC_FLAGS] = {0};

void initialize_retry_info() {
    for (int i = 0; i < MAX_RNTIS; ++i) {
        retry_info[i].RNTI = 0;
        retry_info[i].retry_count = 0;
    }
}

bool find_rnti(uint16_t rnti) {
    for (int i = 0; i < MAX_RNTIS; ++i) {
        if (retry_info[i].RNTI == rnti) {
            return true;
        }
    }
    return false;
}

void update_retry_count(uint16_t rnti, int increment) {
    for (int i = 0; i < MAX_RNTIS; ++i) {
        if (retry_info[i].RNTI == rnti) {
            retry_info[i].retry_count += increment;
            break;
        }
    }
}

bool find_crc_flag(bool crcflag) {
    return used_crc_flags[crcflag];
}

void mark_crc_flag(bool crcflag) {
    used_crc_flags[crcflag] = 1;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->pdu = pdu;
    new_node->next = NULL;
    return new_node;
}

void append_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list.lock);

    Node* new_node = create_node(pdu);

    if (list.head == NULL) {
        list.head = new_node;
    } else {
        Node* current = list.head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&list.lock);
}

void generate_pdus(int num_pdus) {
    for (int i = 0; i < num_pdus; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % MAX_RNTIS + 1;

        bool crcflag_set = false;
        while (!crcflag_set) {
            pdu.CRC_INDICATION_REL8_TAG = rand() % MAX_CRC_FLAGS;
            if (!find_crc_flag(pdu.CRC_INDICATION_REL8_TAG)) {
                crcflag_set = true;
                mark_crc_flag(pdu.CRC_INDICATION_REL8_TAG);
            }
        }

        pdu.CRCFLAG = (rand() % 2) == 0;

        pthread_mutex_lock(&list.lock);

        if (!find_rnti(pdu.RNTI)) {
            for (int j = 0; j < MAX_RNTIS; ++j) {
                if (retry_info[j].RNTI == 0) {
                    retry_info[j].RNTI = pdu.RNTI;
                    retry_info[j].retry_count = 1;
                    break;
                }
            }
        } else {
            update_retry_count(pdu.RNTI, 1);
        }

        append_node(pdu);

        pthread_mutex_unlock(&list.lock);
    }
}

void free_list() {
    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list.head = NULL;

    pthread_mutex_unlock(&list.lock);
}

void cleanup() {
    free_list();
    // No need to explicitly destroy mutex in C11, but if using a different standard:
    // pthread_mutex_destroy(&list.lock);
}
