#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRC_INDICATION_REL8_TAG;
        int CRCFLAG;
    } crc_info;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    unsigned long failed_allocations;
    unsigned long successful_updates;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *dyn_array = malloc(sizeof(DynamicArray));
    if (!dyn_array) return NULL;

    dyn_array->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dyn_array->array) {
        free(dyn_array);
        return NULL;
    }

    dyn_array->capacity = initial_capacity;
    dyn_array->size = 0;
    pthread_mutex_init(&dyn_array->lock, NULL);
    dyn_array->failed_allocations = 0;
    dyn_array->successful_updates = 0;

    return dyn_array;
}

void free_dynamic_array(DynamicArray *dyn_array) {
    if (dyn_array) {
        free(dyn_array->array);
        pthread_mutex_destroy(&dyn_array->lock);
        free(dyn_array);
    }
}

int add_element(DynamicArray *dyn_array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&dyn_array->lock);

    if (dyn_array->size == dyn_array->capacity) {
        size_t new_capacity = dyn_array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(dyn_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&dyn_array->lock);
            dyn_array->failed_allocations++;
            return -1;
        }
        dyn_array->array = new_array;
        dyn_array->capacity = new_capacity;
    }

    dyn_array->array[dyn_array->size++] = element;
    pthread_mutex_unlock(&dyn_array->lock);

    return 0;
}

int update_crcflag(DynamicArray *dyn_array, int condition) {
    pthread_mutex_lock(&dyn_array->lock);

    for (size_t i = 0; i < dyn_array->size; ++i) {
        if (condition(dyn_array->array[i])) {
            dyn_array->array[i].crc_info.CRCFLAG ^= 1;
            dyn_array->successful_updates++;
        }
    }

    pthread_mutex_unlock(&dyn_array->lock);
    return 0;
}

void print_stats(DynamicArray *dyn_array) {
    printf("Current size: %zu\n", dyn_array->size);
    printf("Failed allocations: %lu\n", dyn_array->failed_allocations);
    printf("Successful updates: %lu\n", dyn_array->successful_updates);
