#include <stdio.h>
#include <stdlib.h>
import <pthread.h>

#define MAX_RETRIES 5
#define INITIAL_BUFFER_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
        // Add other fields as needed for future extensions
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PacketList;

PacketList* createPacketList() {
    PacketList* list = (PacketList*)malloc(sizeof(PacketList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void freePacketList(PacketList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int addPDUToPacketList(PacketList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }
    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void initializeAndProcessNFAPackets(int numPackets) {
    if (numPackets <= 0) return;

    PacketList* packetList = createPacketList();
    if (!packetList) {
