            else if (retry == MAX_RETRIES - 1) {
                fprintf(stderr, "Failed to add PDU after %d retries\n", MAX_RETRIES);
                freePacketList(packetList);
                return;
            }
        }

        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = crcFlag;

        // Process the packet (placeholder for actual processing logic)
    }

    // Placeholder for cleanup and further processing

    freePacketList(packetList);
}

