    fprintf(stderr, "Error: %s\n", message);
}

// Function to validate encryption key
int is_valid_key(const unsigned char *key, int length) {
    if (length != KEY_LENGTH || !RAND_bytes(key, length)) {
        log_error("Invalid encryption key");
        return 0;
    }
    return 1;
}

// Thread-safe mutex for cipher object access
pthread_mutex_t lock;

EVP_CIPHER_CTX *initialize_cipher(const char *cipher_mode) {
    EVP_CIPHER_CTX *ctx = NULL;
    int result;

    if (!(ctx = EVP_CIPHER_CTX_new())) {
        log_error("Failed to create cipher context");
        return NULL;
    }

    pthread_mutex_lock(&lock);
    result = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
    pthread_mutex_unlock(&lock);

    if (!result) {
        EVP_CIPHER_CTX_free(ctx);
        log_error("Failed to initialize cipher");
        return NULL;
    }

    return ctx;
}

EVP_CIPHER_CTX *create_cipher(const char *key, const char *cipher_mode) {
    unsigned char encryption_key[KEY_LENGTH];
    memcpy(encryption_key, key, KEY_LENGTH);

    if (!is_valid_key(encryption_key, KEY_LENGTH)) {
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = initialize_cipher(cipher_mode);
    pthread_mutex_lock(&lock);
    int result = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, encryption_key, NULL);
    pthread_mutex_unlock(&lock);

    if (!result) {
        EVP_CIPHER_CTX_free(ctx);
        log_error("Failed to set cipher key");
        return NULL;
    }

    return ctx;
}

void destroy_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_cleanup(ctx);
        EVP_CIPHER_CTX_free(ctx);
    }
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <key> <cipher_mode>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *key = argv[1];
    const char *cipher_mode = argv[2];

    pthread_mutex_init(&lock, NULL);

    EVP_CIPHER_CTX *ctx = create_cipher(key, cipher_mode);
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher object\n");
        return EXIT_FAILURE;
    }

    // Use the context for encryption/decryption...

    destroy_cipher(ctx);

    pthread_mutex_destroy(&lock);
    return EXIT_SUCCESS;
}
