// Function to read and parse the configuration file
int read_config(const char *config_path, char **settings) {
    FILE *file = fopen(config_path, "r");
    if (!file) {
        log_error("Failed to open config file: %s", strerror(errno));
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    rewind(file);

    *settings = (char *)malloc(length + 1);
    if (*settings == NULL) {
        log_error("Failed to allocate memory for config settings.");
        fclose(file);
        return -1;
    }

    fread(*settings, 1, length, file);
    (*settings)[length] = '\0';

    fclose(file);
    return 0;
}

