    Cipher *cipher = create_cipher(config_settings);
    if (!cipher) {
        log_error("Failed to initialize cipher with provided settings.");
        return NULL;
    }

    return cipher;
}

Cipher *setup_cipher(const char *config_file_path) {
    char *settings = NULL;

    // Check for file existence and read permissions
    FILE *file_test = fopen(config_file_path, "r");
    if (!file_test) {
        log_error("Configuration file not found or lacking permission: %s", strerror(errno));
        return NULL;
    }
    fclose(file_test);

    // Read configuration settings
    if (read_config(config_file_path, &settings) != 0) {
        free(settings);
        return NULL;
    }

    // Initialize the cipher
    Cipher *cipher = initialize_cipher(settings);
    free(settings);

    if (!cipher) {
        log_error("Cipher initialization failed. Attempting fallback strategy.");

        // Fallback to a default or safe configuration.
        char default_settings[] = "default_cipher_option";
        cipher = initialize_cipher(default_settings);
        if (!cipher) {
            log_error("Fallback cipher initialization also failed.");
            return NULL;
        }
    }

    // Log successful initialization
    log_info("Cipher initialized successfully.");

    return cipher;
}

void release_resources(Cipher *cipher) {
    if (cipher) {
        // Assume `destroy_cipher` is available to free up resources.
        destroy_cipher(cipher);
    }
}
```

### Key Points:
