```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define M 100 // Maximum number of elements

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG:1;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > M) return NULL;

    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = initial_capacity;
    pthread_mutex_init(&da->mutex, NULL);

    return da;
}

int add_element(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&da->mutex);

    if (da->capacity == 0) {
        pthread_mutex_unlock(&da->mutex);
        return -1; // Error: No capacity
    }

    for (size_t i = 0; i < da->capacity; ++i) {
        if (da->array[i].RX_UE_INFORMATION_TAG == element.RX_UE_INFORMATION_TAG &&
            da->array[i].RNTI == element.RNTI) {
            pthread_mutex_unlock(&da->mutex);
            return -2; // Error: Duplicate entry
        }
    }

    for (size_t i = 0; i < da->capacity; ++i) {
        if (da->array[i].RX_UE_INFORMATION_TAG == 0 && da->array[i].RNTI == 0) {
            da->array[i] = element;
            pthread_mutex_unlock(&da->mutex);
            return 0; // Success
        }
    }

    size_t new_capacity = da->capacity * 2 > M ? M : da->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        pthread_mutex_unlock(&da->mutex);
        return -3; // Error: Reallocation failed
    }

    da->array = new_array;
    da->capacity = new_capacity;

    for (size_t i = 0; i < da->capacity; ++i) {
        if (da->array[i].RX_UE_INFORMATION_TAG == 0 && da->array[i].RNTI == 0) {
            da->array[i] = element;
            pthread_mutex_unlock(&da->mutex);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&da->mutex);
    return -4; // Error: Should not happen
}

void destroy_dynamic_array(DynamicArray* da) {
    if (!da) return;

    pthread_mutex_lock(&da->mutex);
    free(da->array);
    pthread_mutex_unlock(&da->mutex);

    pthread_mutex_destroy(&da->mutex);
    free(da);
}

void populate_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* element) {
    if (element) {
        element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }
}

int main() {
    DynamicArray* da = create_dynamic_array(10);
    if (!da) {
        fprintf(stderr, "Failed to create dynamic array\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < M; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element = {
            .RX_UE_INFORMATION_TAG = rand() % 1000,
            .RNTI = rand() % 1000
        };
        populate_random_crcflag(&element);

        int result = add_element(da, element);
        if (result != 0) {
            fprintf(stderr, "Failed to add element: %d\n", result);
        }
    }

    destroy_dynamic_array(da);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Concurrency**: Uses `pthread_mutex_t` for synchronization.
- **Error Handling**: Handles allocation failures and duplicates.
- **Dynamic Resizing**: Doubles capacity until it reaches the maximum limit `M`.
- **Random CRCFLAG**: Sets a random value for `CRCFLAG`.
- **Memory Management**: Ensures no memory leaks with proper cleanup.']

