    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int initialize_nic_settings(NICSettings *nics, int num_nics) {
    srand(time(NULL));
    pthread_t threads[MAX_NICS];

    for (int i = 0; i < num_nics; ++i) {
        if (pthread_create(&threads[i], NULL, (void *(*)(void *))initialize_single_nic, &nics[i])) {
            log_error("Failed to create thread");
            return -1;
        }
    }

    for (int i = 0; i < num_nics; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

void *initialize_single_nic(void *arg) {
    NICSettings *settings = (NICSettings *)arg;

    retry_count = 0;
    while (retry_count < RETRY_LIMIT) {
        if (fetch_from_external_service(settings) == 0 || fetch_from_local_database(settings) == 0) {
            settings->additional_info.CRCFLAG = rand() % 2; // Random CRC flag
            break;
        }
        retry_count++;
    }

    if (retry_count == RETRY_LIMIT) {
        log_error("Failed to initialize NIC settings after retries");
        return NULL;
    }

    pthread_mutex_lock(&lock);
    if (!validate_mac_address(settings->nic_config.mac_address)) {
        log_error("Invalid MAC address");
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    if (!validate_ip_address(settings->nic_config.ip_address)) {
        log_error("Invalid IP address");
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    pthread_mutex_unlock(&lock);

    return NULL;
}

int main() {
    NICSettings nics[MAX_NICS];
    int num_nics = MAX_NICS;

    if (initialize_nic_settings(nics, num_nics) != 0) {
        fprintf(stderr, "Failed to initialize NIC settings\n");
        return EXIT_FAILURE;
    }

    printf("NIC settings initialized successfully.\n");
    return EXIT_SUCCESS;
}
