```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} List;

int validate_pdu(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu || pdu->RX_UE_INFORMATION_TAG == 0 || pdu->RNTI == 0) {
        fprintf(stderr, "Validation error: Invalid PDU structure\n");
        return 0;
    }
    // Additional validation logic
    return 1;
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_warning(const char* message) {
    fprintf(stderr, "Warning: %s\n", message);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed for node");
        return NULL;
    }
    new_node->data = pdu;
    new_node->next = NULL;
    return new_node;
}

int list_insert(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);

    if (!validate_pdu(&pdu)) {
        log_warning("Skipping insertion due to validation failure");
        pthread_mutex_unlock(&list->mutex);
        return 0;
    }

    Node* new_node = create_node(pdu);
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return 0;
    }

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->mutex);
    return 1;
}

void free_list(List* list) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head, *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->mutex);
}

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        log_error("Memory allocation failed for list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

int main() {
    List* pdu_list = create_list();
    if (!pdu_list) return 1;

    // Example: populate the list with dummy data
    for (int i = 0; i < MAX_LIST_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = i + 1;
        pdu.RNTI = i * 2;
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        if (!list_insert(pdu_list, pdu)) {
            log_warning("Failed to insert PDU into list");
        }
    }

    free_list(pdu_list);
    pthread_mutex_destroy(&pdu_list->mutex);
    free(pdu_list);

    return 0;
}
