["```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <assert.h>

typedef struct {
    int sequence_number;
    char transaction_type[32];
    size_t data_buffer_size;
    // Add more fields as necessary.
} MAC_TRANSACTION;

#define INITIAL_POOL_SIZE 10
#define MAX_RETRY_ATTEMPTS 3

typedef struct Node {
    MAC_TRANSACTION* transaction;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
    // Additional fields as necessary for pool management.
} LRUCache;

MAC_TRANSACTION* create_transaction(int sequence_number, const char* transaction_type, size_t data_buffer_size) {
    MAC_TRANSACTION* txn = (MAC_TRANSACTION*)malloc(sizeof(MAC_TRANSACTION));
    if (!txn) return NULL;  // Handle allocation failure.

    txn->sequence_number = sequence_number;
    strncpy(txn->transaction_type, transaction_type, sizeof(txn->transaction_type) - 1);
    txn->transaction_type[sizeof(txn->transaction_type) - 1] = '\0';
    txn->data_buffer_size = data_buffer_size;

    return txn;
}

void destroy_transaction(MAC_TRANSACTION* txn) {
    if (txn) free(txn);
}

LRUCache* create_lru_cache() {
    LRUCache* cache = (LRUCache*)malloc(sizeof(LRUCache));
    pthread_mutex_init(&cache->lock, NULL);
    cache->head = NULL;
    cache->tail = NULL;
    cache->count = 0;

    return cache;
}

void lru_put(LRUCache* cache, MAC_TRANSACTION* txn) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return;  // Handle allocation failure.

    node->transaction = txn;
    pthread_mutex_lock(&cache->lock);

    if (!cache->head || cache->count == INITIAL_POOL_SIZE) { // Simplistic eviction policy
        while (cache->count > INITIAL_POOL_SIZE / 2) {
            MAC_TRANSACTION* old_txn = cache->tail->transaction;
            Node* old_node = cache->tail;
            cache->tail = cache->tail->prev;
            if (cache->tail) cache->tail->next = NULL;
            free(old_node);
            destroy_transaction(old_txn);
            cache->count--;
        }
    }

    node->next = cache->head;
    if (node->next) {
        node->next->prev = node;
    } else {
        cache->tail = node;
    }
    cache->head = node;

    cache->count++;
    pthread_mutex_unlock(&cache->lock);
}

MAC_TRANSACTION* lru_get(LRUCache* cache, int sequence_number) {
    pthread_mutex_lock(&cache->lock);

    Node* current = cache->head;
    while (current != NULL) {
        if (current->transaction->sequence_number == sequence_number) {
            if (current != cache->head) {
                if (current->next) current->next->prev = current->prev;
                if (current->prev) current->prev->next = current->next;
                if (!current->prev) cache->head = current->next;

                current->next = NULL;
                current->prev = cache->head;
                if (cache->head) cache->head->prev = current;
                else cache->tail = current;

                cache->head = current;
            }
            MAC_TRANSACTION* txn = current->transaction;
            pthread_mutex_unlock(&cache->lock);
            return txn;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL; // Transaction not found.
}

void lru_remove(LRUCache* cache, int sequence_number) {
    pthread_mutex_lock(&cache->lock);

    Node* current = cache->head;
    while (current != NULL) {
        if (current->transaction->sequence_number == sequence_number) {
            if (current->next) current->next->prev = current->prev;
            if (current->prev) current->prev->next = current->next;
            if (!current->prev) cache->head = current->next;
            if (!current->next) cache->tail = current->prev;

            free(current);
            destroy_transaction(current->transaction);

            cache->count--;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache->lock);
}

void clear_lru_cache(LRUCache* cache) {
    pthread_mutex_lock(&cache->lock);

    Node* current = cache->head;
    while (current != NULL) {
        MAC_TRANSACTION* txn = current->transaction;
        current = current->next;
        destroy_transaction(txn);
        free(current);
    }

    cache->head = NULL;
    cache->tail = NULL;
    cache->count = 0;

    pthread_mutex_unlock(&cache->lock);
}

void destroy_lru_cache(LRUCache* cache) {
    clear_lru_cache(cache);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

// Unit and integration tests would be implemented separately.
```"]

