#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>
#include <time.h>

#define CACHE_LINE_SIZE 64 // Common cache line size, adjust as needed

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread-safe operations
pthread_mutex_t lock;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void reset_structures(NFAPI_CRC_INDICATION_PDU_T **array, size_t n) {
    if (array && *array) {
        free(*array);
        *array = NULL;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate(size_t n, const char *input_file) {
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(CACHE_LINE_SIZE, n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    FILE *file = fopen(input_file, "r");
    if (!file) {
        log_error("Failed to open input file");
        free(array);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    char line[256];
    for (size_t i = 0; i < n && fgets(line, sizeof(line), file); ++i) {
        int rnti = atoi(strtok(line, " \t\n"));
        if (rnti <= 0) {
            fprintf(stderr, "Warning: Invalid RNTI value %d on line %zu\n", rnti, i + 1);
            continue;
        }

        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rnti;
        array[i].CRC_INDICATION_REL8_TAG = rand();
        array[i].CRCFLAG = rand() % 2;

        // Align to cache line size
        size_t padding = CACHE_LINE_SIZE - (sizeof(NFAPI_CRC_INDICATION_PDU_T) % CACHE_LINE_SIZE);
        if (padding != CACHE_LINE_SIZE) {
            memset((char *)&array[i] + sizeof(NFAPI_CRC_INDICATION_PDU_T), 0, padding);
        }
    }

    fclose(file);

    pthread_mutex_unlock(&lock);
    return array;
}

void parse_arguments(int argc, char *argv[], size_t *n, const char **input_file) {
    int opt;
    while ((opt = getopt(argc, argv, "hcs:o:")) != -1) {
        switch (opt) {
            case 'c':
                printf("Usage information...\n");
                exit(0);
            case 's':
                *n = atoi(optarg);
                if (*n <= 0 || *n > 1000000) { // Example max limit
                    fprintf(stderr, "Invalid number of structures\n");
                    exit(EXIT_FAILURE);
                }
                break;
            case 'o':
                // Output file handling (if needed)
                break;
            default:
                printf("Usage information...\n");
                exit(1);
        }
    }

    if (optind < argc) {
        *input_file = argv[optind];
    } else {
        fprintf(stderr, "Input file required\n");
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char *argv[]) {
    size_t n;
    const char *input_file;

    parse_arguments(argc, argv, &n, &input_file);

    pthread_mutex_init(&lock, NULL);
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T *array = allocate_and_populate(n, input_file);

    if (array) {
        // Use the array as needed
        free(array); // Free memory when done
    }

    pthread_mutex_destroy(&lock);
    return 0;
}
