#include <stdio.h>
#include <stdlib.h>
import jsmn.h

#define INITIAL_CAPACITY 10
#define LOG_FILE "connection_log.txt"

typedef struct {
    char device_id[50];
    time_t timestamp;
    int connection_quality;
} ConnectionStatus;

typedef struct {
    ConnectionStatus *connections;
    size_t capacity;
    size_t count;
} ConnectionManager;

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int resize_connections(ConnectionManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    ConnectionStatus *new_array = realloc(manager->connections, new_capacity * sizeof(ConnectionStatus));
    if (new_array == NULL) {
        log_message("Memory allocation failed during resizing.");
        return -1; // Memory allocation error
    }
    manager->connections = new_array;
    manager->capacity = new_capacity;
    return 0;
}

int load_initial_data_from_json(const char *filename, ConnectionManager *manager) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        log_message("Failed to open JSON file.");
        return -1; // File opening error
    }

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *buffer = malloc(length + 1);
    if (buffer == NULL) {
        log_message("Memory allocation failed for JSON buffer.");
        fclose(file);
        return -2; // Memory allocation error
    }

    fread(buffer, 1, length, file);
    buffer[length] = '\0';
    fclose(file);

    jsmn_parser parser;
    jsmntok_t tokens[128]; // Assume a max of 128 JSON tokens for simplicity

    if (jsmn_init(&parser) < 0) {
        log_message("Failed to initialize JSON parser.");
        free(buffer);
        return -3; // Parser initialization error
    }

    int token_count = jsmn_parse(&parser, buffer, length, tokens, sizeof(tokens)/sizeof(tokens[0]));
    if (token_count < 0) {
        log_message("JSON parsing failed.");
        free(buffer);
        return -4; // JSON parsing error
    }

    if (tokens[token_count - 1].type != JSMN_ARRAY) {
        log_message("Unexpected JSON structure.");
        free(buffer);
        return -5; // Invalid JSON structure
    }

    for (int i = 1; i < token_count; ++i) { // Skip the root array token
        if (tokens[i].type == JSMN_OBJECT && manager->count < manager->capacity) {
            const char *key;
            int value_type;

            for (jsmntok_t *t = &tokens[i]; t != &tokens[token_count]; ++t) {
                key = buffer + tokens[t->parent].start;

                if (strcmp(key, "device_id") == 0 && t->type == JSMN_STRING) {
                    snprintf(manager->connections[manager->count].device_id, sizeof(manager->connections[manager->count].device_id),
                             "%.*s", t->end - t->start, buffer + t->start);
                } else if (strcmp(key, "timestamp") == 0 && t->type == JSMN_PRIMITIVE) {
                    manager->connections[manager->count].timestamp = atoi(buffer + t->start);
                } else if (strcmp(key, "connection_quality") == 0 && t->type == JSMN_PRIMITIVE) {
                    manager->connections[manager->count].connection_quality = atoi(buffer + t->start);
                }
            }

            ++manager->count;
        } else if (manager->count >= manager->capacity) {
            int resize_result = resize_connections(manager);
            if (resize_result != 0) return -6; // Resize failed
        }
    }

    free(buffer);

    log_message("Initial data loaded successfully.");
    return 0; // Success
}

ConnectionManager *initialize_connection_manager() {
    ConnectionManager *manager = malloc(sizeof(ConnectionManager));
    if (manager == NULL) {
        log_message("Memory allocation for ConnectionManager failed.");
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;

    if ((manager->connections = calloc(manager->capacity, sizeof(ConnectionStatus))) == NULL) {
        log_message("Memory allocation for connections array failed.");
        free(manager);
        return NULL;
    }

    log_message("ConnectionManager initialized successfully.");
    return manager;
}

void update_connection_status(ConnectionManager *manager, const char *device_id, time_t timestamp, int connection_quality) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->connections[i].device_id, device_id) == 0) {
            manager->connections[i].timestamp = timestamp;
            manager->connections[i].connection_quality = connection_quality;
            return;
        }
    }

    if (manager->count >= manager->capacity) {
        int resize_result = resize_connections(manager);
        if (resize_result != 0) return; // Handle resize failure gracefully
    }

    snprintf(manager->connections[manager->count].device_id, sizeof(manager->connections[manager->count].device_id), "%s", device_id);
    manager->connections[manager->count].timestamp = timestamp;
    manager->connections[manager->count].connection_quality = connection_quality;
    ++manager->count;

    log_message("Connection status updated successfully.");
}

void free_connection_manager(ConnectionManager *manager) {
    if (manager != NULL) {
        free(manager->connections);
        free(manager);
        log_message("ConnectionManager resources freed successfully.");
    }
}
