#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <uuid/uuid.h>
#include <time.h>

#define MAX_ENTRIES 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG; // Randomly set CRCFLAG in the CRC_INDICATION_REL8_TAG
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    uuid_t uuid;
    time_t timestamp;
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock;
    int debug_mode;
} DoublyLinkedList;

void init_list(DoublyLinkedList* list, int debug_mode) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->debug_mode = debug_mode;
}

int random_crcflag() {
    return rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    uuid_generate(node->uuid);
    node->timestamp = time(NULL);
    node->data = data;
    node->prev = NULL;
    node->next = NULL;

    // Set CRCFLAG randomly
    node->data.CRCFLAG = random_crcflag();

    return node;
}

int insert_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_ENTRIES) {
        // Resource management: Remove oldest entry
        Node* temp = list->head;
        if (temp) {
            list->head = temp->next;
            if (list->head) list->head->prev = NULL;
            free(temp);
            list->size--;
            if (list->debug_mode)
                printf("Removed oldest node to maintain size constraint.\n");
        } else {
            pthread_mutex_unlock(&list->lock);
            return -1; // Error: List is empty, cannot remove
        }
    }

    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation error
    }

    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
    }

    list->size++;

    if (list->debug_mode)
        printf("Inserted node with UUID: %s\n", uuid_unparse(new_node->uuid, NULL));

    pthread_mutex_unlock(&list->lock);
    return 0;
}

Node* find_by_rnti(DoublyLinkedList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti)
            break;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return current; // Returns NULL if not found
}

void flush_to_storage(DoublyLinkedList* list, const char* file_path) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen(file_path, "a");
    if (!file) {
        printf("Error opening file for writing.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* current = list->head;
    while (current) {
        fprintf(file, "UUID: %s Timestamp: %ld RNTI: %d CRCFLAG: %d\n",
                uuid_unparse(current->uuid, NULL),
                current->timestamp,
                current->data.RNTI,
                current->data.CRCFLAG);
        current = current->next;
    }

    fclose(file);

    if (list->debug_mode)
        printf("Flushed list to storage: %s\n", file_path);

    pthread_mutex_unlock(&list->lock);
}

void free_list(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);

    if (list->debug_mode)
        printf("Freed all nodes and destroyed lock.\n");
}

void periodic_flush(DoublyLinkedList* list, const char* file_path, int interval_sec) {
    while (1) {
        sleep(interval_sec); // Wait for the specified interval
        flush_to_storage(list, file_path);
    }
}
