// Import necessary modules
const { exec } = require('child_process');
const EventEmitter = require('events');

class CommandExecutor extends EventEmitter {
    constructor() {
        super();
        this.commandQueue = [];
        this.isExecuting = false;
    }

    executeCommands(commands) {
        commands.forEach((cmd, index) => {
            setTimeout(() => {
                this.runCommand(cmd).then(result => {
                    if (index === commands.length - 1) {
                        this.emit('completed', result);
                    }
                }).catch(error => {
                    console.error(`Error executing command at index ${index}:`, error);
                    if (index === commands.length - 1) {
                        this.emit('failed');
                    }
                });
            }, index * 1000); // Adding delay to simulate sequential execution
        });
    }

    runCommand(commandString) {
        return new Promise((resolve, reject) => {
            exec(commandString, { timeout: 5000, maxBuffer: 1024 * 1024 * 2 }, (error, stdout, stderr) => {
                if (error) {
                    console.error(`Execution error for command "${commandString}":`, error);
                    return reject(error);
                }
                if (stderr) {
                    console.warn(`Command stderr for "${commandString}":`, stderr);
                }
                resolve(stdout.trim());
            });
        });
    }

    onCompleted(callback) {
        this.on('completed', callback);
    }

    onFailed(callback) {
        this.on('failed', callback);
    }
}

// Example usage
const executor = new CommandExecutor();

executor.onCompleted((results) => {
    console.log('All commands executed successfully:', results);
});

executor.onFailed(() => {
    console.error('One or more commands failed.');
});

const userCommands = [
    'echo "Hello World"',
    `ls -la && echo "Directory listing complete"`,
    'sleep 2 && echo "Delayed execution test"'
];

executor.executeCommands(userCommands);

// Integrate into a larger application framework
// This example shows basic usage; integration depends on the specific application context.
```

