#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <errno.h>

#define MAX_CONNECTIONS 1000
#define RETRY_LIMIT 3
#define INITIAL_BACKOFF 100000 // in microseconds

typedef struct {
    int socket_id;
    struct sockaddr_in address;
} SocketConnection;

int* initialize_tcp_connections(const char *server_ip, int server_port, int num_connections, SocketConnection **connections) {
    if (num_connections > MAX_CONNECTIONS || !server_ip || !connections) return NULL;

    *connections = malloc(num_connections * sizeof(SocketConnection));
    if (*connections == NULL) return NULL;

    for (int i = 0; i < num_connections; ++i) {
        int retry_count = 0;
        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_port = htons(server_port);

        if (inet_pton(AF_INET, server_ip, &addr.sin_addr) <= 0) {
            free(*connections);
            return NULL;
        }

        int sockfd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, IPPROTO_TCP);
        if (sockfd < 0) {
            retry_count++;
            continue;
        }

        while (retry_count < RETRY_LIMIT) {
            if (connect(sockfd, (struct sockaddr *)&addr, sizeof(addr)) == -1) {
                if (errno == EINPROGRESS || errno == EINTR || errno == EAGAIN) {
                    // Wait for the connection to complete
                    struct timeval timeout;
                    fd_set writefds;
                    FD_ZERO(&writefds);
                    FD_SET(sockfd, &writefds);
                    timeout.tv_sec = 5; // Timeout after 5 seconds
                    timeout.tv_usec = 0;

                    int select_result = select(sockfd + 1, NULL, &writefds, NULL, &timeout);
                    if (select_result > 0) {
                        int so_error;
                        socklen_t len = sizeof(so_error);

                        getsockopt(sockfd, SOL_SOCKET, SO_ERROR, &so_error, &len);
                        if (so_error == 0) break; // Successfully connected
                    } else {
                        retry_count++;
                        usleep(INITIAL_BACKOFF * (1 << retry_count)); // Exponential backoff
                        continue;
                    }
                } else {
                    close(sockfd);
                    retry_count++;
                    usleep(INITIAL_BACKOFF * (1 << retry_count));
                    sockfd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, IPPROTO_TCP);
                    if (sockfd < 0) break;
                }
            }
        }

        if (retry_count == RETRY_LIMIT) {
            close(sockfd);
            // Adjust allocations since this connection failed
            free(*connections);
            *connections = realloc(*connections, (num_connections - i - 1) * sizeof(SocketConnection));
            num_connections--;
            continue; // Try to establish the next connection
        }

        (*connections)[i].socket_id = sockfd;
        (*connections)[i].address = addr;
    }

    int *status_indicators = malloc(num_connections * sizeof(int));
    if (status_indicators == NULL) {
        free(*connections);
        return NULL;
    }

    for (int i = 0; i < num_connections; ++i) {
        status_indicators[i] = (*connections)[i].socket_id >= 0 ? 1 : 0; // 1 for success, 0 for failure
    }

    return status_indicators;
}

void cleanup_connections(SocketConnection *connections, int num_connections) {
    if (!connections) return;

    for (int i = 0; i < num_connections; ++i) {
        close(connections[i].socket_id);
    }

    free(connections);
}
