#define SESSION_TIMEOUT_SECONDS 300

typedef enum {
    STATE_IDLE,
    STATE_ACTIVE,
    STATE_CLOSED
} SessionState;

typedef struct NetworkSession {
    int SessionID;
    char ClientAddress[128];
    char ServerAddress[128];
    SessionState SessionState;
    time_t LastActiveTime;
    pthread_mutex_t mutex;
} NetworkSession;

typedef struct Node {
    NetworkSession *session;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t rwlock;
} SessionList;

SessionList* create_session_list() {
    SessionList* list = (SessionList*)malloc(sizeof(SessionList));
    list->head = NULL;
    pthread_rwlock_init(&list->rwlock, NULL);
    return list;
}

void destroy_session_list(SessionList* list) {
    pthread_rwlock_wrlock(&list->rwlock);
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->session);
        free(current);
        current = next;
    }
    pthread_rwlock_unlock(&list->rwlock);
    pthread_rwlock_destroy(&list->rwlock);
    free(list);
}

void add_session(SessionList* list, NetworkSession* session) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->session = session;

    pthread_rwlock_wrlock(&list->rwlock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_rwlock_unlock(&list->rwlock);

    log_session_event(session, "Session added");
}

void update_session(SessionList* list, int session_id, SessionState state) {
    Node* current = list->head;

    pthread_rwlock_wrlock(&list->rwlock);
    while (current != NULL) {
        if (current->session->SessionID == session_id) {
            current->session->SessionState = state;
            current->session->LastActiveTime = time(NULL);
            log_session_event(current->session, "Session updated");
            break;
        }
        current = current->next;
    }
    pthread_rwlock_unlock(&list->rwlock);
}

void remove_session(SessionList* list, int session_id) {
    Node **current_link = &list->head;

    pthread_rwlock_wrlock(&list->rwlock);
    while (*current_link != NULL) {
        Node *entry = *current_link;
        if (entry->session->SessionID == session_id) {
            *current_link = entry->next;
            free(entry->session);
            free(entry);
            log_session_event(entry->session, "Session removed");
            break;
        }
        current_link = &entry->next;
    }
    pthread_rwlock_unlock(&list->rwlock);
}

void cleanup_expired_sessions(SessionList* list) {
    Node **current_link = &list->head;

    pthread_rwlock_wrlock(&list->rwlock);
    while (*current_link != NULL) {
        Node *entry = *current_link;
        if (time(NULL) - entry->session->LastActiveTime > SESSION_TIMEOUT_SECONDS) {
            *current_link = entry->next;
            log_session_event(entry->session, "Session expired and removed");
            free(entry->session);
            free(entry);
        } else {
            current_link = &entry->next;
        }
    }
    pthread_rwlock_unlock(&list->rwlock);
}

void log_session_event(NetworkSession* session, const char *event) {
    // Implement logging to a remote service here
    printf("Logging: SessionID=%d Event='%s'\n", session->SessionID, event);
}

void monitor_sessions(SessionList* list) {
    while (1) {
        cleanup_expired_sessions(list);
        sleep(10);  // Adjust the frequency as needed
    }
}

int main() {
    SessionList *session_list = create_session_list();
    pthread_t monitor_thread;

    pthread_create(&monitor_thread, NULL, (void *(*)(void *))monitor_sessions, session_list);

    NetworkSession* new_session = (NetworkSession*)malloc(sizeof(NetworkSession));
    new_session->SessionID = 1;
    strcpy(new_session->ClientAddress, "192.168.1.1");
    strcpy(new_session->ServerAddress, "10.0.0.1");
    new_session->SessionState = STATE_IDLE;
    new_session->LastActiveTime = time(NULL);

