    // Simulate some operations
    update_session(session_list, 1, STATE_ACTIVE);
    sleep(310);  // Wait for session to timeout

    remove_session(session_list, 1);

    pthread_join(monitor_thread, NULL);
    destroy_session_list(session_list);

    return 0;
}
