Node* create_node(int ue_id, const char* rrc_state, int cell_id) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->data.UE_ID = ue_id;
    strcpy(new_node->data.RRC_STATE, rrc_state);
    new_node->data.ServingCellID = cell_id;
    new_node->avg_RSRP = 0.0f;
    new_node->next = NULL;

    return new_node;
}

// Function to add a measurement report
void update_rsrp(int ue_id, float rsrp) {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    while (current) {
        if (current->data.UE_ID == ue_id) {
            // Update RSRP and calculate average
            static int count = 0; // Persistent across calls for simplicity
            current->avg_RSRP = ((current->avg_RSRP * count) + rsrp) / (count + 1);
            ++count;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
}

// Function to add a new UEState node
