        Node* current = head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
}

// Function to free the linked list
void cleanup_list() {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    head = NULL;

    pthread_mutex_unlock(&list_mutex);
}

// Function to log the status of the linked list
void log_list_status() {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    int ue_count = 0;
    while (current) {
        printf("UE_ID: %d, RRC_STATE: %s, ServingCellID: %d, Avg_RSRP: %.2f\n",
               current->data.UE_ID,
               current->data.RRC_STATE,
               current->data.ServingCellID,
               current->avg_RSRP);
        ++ue_count;
        current = current->next;
    }

    printf("Total UEs in list: %d\n", ue_count);

    pthread_mutex_unlock(&list_mutex);
}

int main() {
    // Example usage
    add_ue_state(1, "Connected", 100);
    update_rsrp(1, -95.5);
    log_list_status();

    cleanup_list();
    return 0;
}
```

### Key Points:

- **Thread Safety**: The `pthread_mutex_t` ensures thread-safe operations on the linked list.
- **Dynamic Memory Management**: Uses `malloc` and `free` to manage memory for each node, preventing leaks with a cleanup function.
- **RSRP Averaging**: Calculates an average RSRP value for each UE as new reports are added.
- **Logging**: Provides a simple mechanism to log the status of the list.

This code should be run in a multi-threaded environment where real-time updates and concurrent access occur, ensuring thread safety. Adjust buffer size and logging frequency based on performance needs.']

