    pthread_mutex_lock(&manager->mutex);

    if (manager->count >= MAX_TRAFFIC_FLOWS) {
        logError("Max traffic flows reached.");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    if (calculateChecksum(flow.sourceAddress) != calculateChecksum(flow.destinationAddress)) {
        logError("Checksum validation failed.");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    manager->flows = realloc(manager->flows, sizeof(TrafficFlow) * (manager->count + 1));
    if (!manager->flows) {
        logError("Memory allocation failed.");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    manager->flows[manager->count++] = flow;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int removeTrafficFlow(TrafficFlowManager *manager, int index) {
    pthread_mutex_lock(&manager->mutex);

    if (index < 0 || index >= manager->count) {
        logError("Invalid index.");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    memmove(&manager->flows[index], &manager->flows[index + 1],
            sizeof(TrafficFlow) * (manager->count - index - 1));
    manager->count--;

    if (manager->count > 0 && manager->count <= MAX_TRAFFIC_FLOWS / 2) {
        manager->flows = realloc(manager->flows, sizeof(TrafficFlow) * manager->count);
    }

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

