    pthread_rwlock_wrlock(&manager->rwlock);

    if (manager->count >= MAX_NFAPI_ELEMENTS) {
        logError("Max NFAPI elements reached.");
        pthread_rwlock_unlock(&manager->rwlock);
        return -1;
    }

    manager->elements = realloc(manager->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (manager->count + 1));
    if (!manager->elements) {
        logError("Memory allocation failed.");
        pthread_rwlock_unlock(&manager->rwlock);
        return -1;
    }

    manager->elements[manager->count++] = element;
    pthread_rwlock_unlock(&manager->rwlock);
    return 0;
}

int removeNFAPICRCElement(NFAPICRCManager *manager, int index) {
    pthread_rwlock_wrlock(&manager->rwlock);

    if (index < 0 || index >= manager->count) {
        logError("Invalid index.");
        pthread_rwlock_unlock(&manager->rwlock);
        return -1;
    }

    memmove(&manager->elements[index], &manager->elements[index + 1],
            sizeof(NFAPI_CRC_INDICATION_PDU_T) * (manager->count - index - 1));
    manager->count--;

    if (manager->count > 0 && manager->count <= MAX_NFAPI_ELEMENTS / 2) {
        manager->elements = realloc(manager->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * manager->count);
    }

