unsigned long calculateChecksum(unsigned long address) {
    // Simple checksum calculation
    unsigned long sum = 0;
    while (address != 0) {
        sum += address & 0xFF;
        address >>= 8;
    }
    return sum;
}

void logError(const char *message) {
