['Below is a C implementation of a thread-safe dynamic array manager for `UplinkTransmissionData` structures using mutexes for synchronization and a custom memory allocator:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int TimingAdvanceCommand;
    int PowerHeadroomReport;
    int RRCConnectionReconfigurationComplete;
} UplinkTransmissionData;

typedef struct {
    UplinkTransmissionData* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

// Custom memory allocator for better performance under heavy load
void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void custom_free(void* ptr) {
    free(ptr);
}

// Initialize the dynamic array
DynamicArray* create_dynamic_array() {
    DynamicArray* da = custom_malloc(sizeof(DynamicArray));
    da->capacity = 10; // Initial capacity
    da->size = 0;
    da->array = custom_malloc(da->capacity * sizeof(UplinkTransmissionData));
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

// Resize the dynamic array
void resize_dynamic_array(DynamicArray* da) {
    size_t new_capacity = da->capacity * 2;
    UplinkTransmissionData* new_array = custom_malloc(new_capacity * sizeof(UplinkTransmissionData));
    for (size_t i = 0; i < da->size; ++i) {
        new_array[i] = da->array[i];
    }
    custom_free(da->array);
    da->array = new_array;
    da->capacity = new_capacity;
}

// Add an element to the dynamic array
void add_element(DynamicArray* da, UplinkTransmissionData data) {
    pthread_mutex_lock(&da->lock);
    if (da->size == da->capacity) {
        resize_dynamic_array(da);
    }
    da->array[da->size++] = data;
    pthread_mutex_unlock(&da->lock);
}

// Remove an element from the dynamic array
void remove_element(DynamicArray* da, size_t index) {
    pthread_mutex_lock(&da->lock);
    if (index < da->size) {
        for (size_t i = index; i < da->size - 1; ++i) {
            da->array[i] = da->array[i + 1];
        }
        --da->size;
    }
    pthread_mutex_unlock(&da->lock);
}

// Iterate over the dynamic array
void iterate_array(DynamicArray* da, void (*callback)(UplinkTransmissionData)) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->size; ++i) {
        callback(da->array[i]);
    }
    pthread_mutex_unlock(&da->lock);
}

// Periodic cleanup function
void cleanup_inactive_entries(DynamicArray* da, int (*is_active)(UplinkTransmissionData)) {
    pthread_mutex_lock(&da->lock);
    size_t write_index = 0;
    for (size_t i = 0; i < da->size; ++i) {
        if (is_active(da->array[i])) {
            da->array[write_index++] = da->array[i];
        }
    }
    da->size = write_index;
    pthread_mutex_unlock(&da->lock);
}

// Destroy the dynamic array
void destroy_dynamic_array(DynamicArray* da) {
    custom_free(da->array);
    pthread_mutex_destroy(&da->lock);
    custom_free(da);
}

int main() {
    // Example usage of the dynamic array manager

    DynamicArray* da = create_dynamic_array();

    UplinkTransmissionData data1 = {1, 2, 3};
    add_element(da, data1);

    UplinkTransmissionData data2 = {4, 5, 6};
    add_element(da, data2);

    // Define a simple callback function
    void print_data(UplinkTransmissionData data) {
        printf("TimingAdvanceCommand: %d, PowerHeadroomReport: %d, RRCConnectionReconfigurationComplete: %d\n",
               data.TimingAdvanceCommand, data.PowerHeadroomReport, data.RRCConnectionReconfigurationComplete);
    }

    iterate_array(da, print_data);

    // Define a simple active check function
    int is_active(UplinkTransmissionData data) {
        return data.TimingAdvanceCommand > 0;
    }

    cleanup_inactive_entries(da, is_active);

    destroy_dynamic_array(da);

    return 0;
}
```

### Key Points:
