class SensorData {
public:
    double temperature;
    double humidity;
    double pressure;

    SensorData(double temp = 0, double hum = 0, double pres = 0)
        : temperature(temp), humidity(hum), pressure(pres) {}
};

class SensorDataManager {
private:
    std::vector<SensorData> dataCollection;
    mutable std::mutex mtx;
    std::condition_variable cv;

    bool isOutlier(const SensorData& data, const SensorData& mean) const {
        // Simple outlier detection logic (e.g., z-score or fixed thresholds)
        return std::abs(data.temperature - mean.temperature) > 10 ||
               std::abs(data.humidity - mean.humidity) > 5 ||
               std::abs(data.pressure - mean.pressure) > 50;
    }

    SensorData calculateMean() const {
        if (dataCollection.empty()) return SensorData();

        double sumTemp = 0, sumHum = 0, sumPres = 0;
        for (const auto& data : dataCollection) {
            sumTemp += data.temperature;
            sumHum += data.humidity;
            sumPres += data.pressure;
        }
        size_t count = dataCollection.size();
        return SensorData(sumTemp / count, sumHum / count, sumPres / count);
    }

public:
    void addSensorData(const SensorData& newData) {
        std::unique_lock<std::mutex> lock(mtx);

        // Calculate current mean
        SensorData mean = calculateMean();

        if (!isOutlier(newData, mean)) {
            dataCollection.push_back(newData);
            cv.notify_all();
        }
    }

    bool removeSensorData(size_t index) {
        std::unique_lock<std::mutex> lock(mtx);

        if (index < dataCollection.size()) {
            dataCollection.erase(dataCollection.begin() + index);
            return true;
        }
        return false;
    }

    SensorData getSensorData(size_t index) const {
        std::lock_guard<std::mutex> lock(mtx);

        if (index < dataCollection.size()) {
            return dataCollection[index];
        }
        throw std::out_of_range("Index out of range");
    }

    void processIncomingData() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !dataCollection.empty(); });

        // Placeholder for dynamic strategy adjustment logic
        // Adjust processing based on data characteristics

        lock.unlock();
    }
};

int main() {
    SensorDataManager manager;

    // Example usage with threads
    std::thread producer([&manager]() {
        manager.addSensorData(SensorData(25.0, 60.0, 1013.0));
        manager.addSensorData(SensorData(26.5, 62.0, 1012.0));
    });

    std::thread consumer([&manager]() {
        try {
            SensorData data = manager.getSensorData(0);
            std::cout << "Temperature: " << data.temperature
                      << ", Humidity: " << data.humidity
                      << ", Pressure: " << data.pressure << std::endl;
        } catch (const std::out_of_range& e) {
            std::cerr << e.what() << std::endl;
        }
