```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int TimingAdvanceCommand;
    float PowerHeadroomReport;
} UplinkTransmissionData;

typedef struct Node {
    UplinkTransmissionData data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void initList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addElement(LinkedList* list, UplinkTransmissionData data) {
    pthread_mutex_lock(&list->lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
}

void removeElement(LinkedList* list, int index) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    for (int i = 0; current != NULL && i < index; i++) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);

    pthread_mutex_unlock(&list->lock);
}

void iterateList(LinkedList* list, void (*func)(UplinkTransmissionData*)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        func(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void freeList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void printData(UplinkTransmissionData* data) {
    printf("TimingAdvanceCommand: %d, PowerHeadroomReport: %.2f\n", 
           data->TimingAdvanceCommand, data->PowerHeadroomReport);
}

int main(int argc, char** argv) {
    LinkedList list;
    initList(&list);

    // Example usage
    UplinkTransmissionData data1 = {1, 10.5};
    addElement(&list, data1);

    iterateList(&list, printData);

    freeList(&list);
    return 0;
}
