#define MAX_EVENTS 1000

typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    // Add more event types as needed
} EventType;

typedef struct {
    time_t timestamp;
    EventType event_type;
    int cell_id;
    char* event_source; // Assume a fixed max length for simplicity
} TrafficEvent;

typedef struct {
    TrafficEvent* events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} EventManager;

EventManager* init_event_manager(size_t initial_capacity) {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    if (!manager) return NULL;

    manager->events = (TrafficEvent*)calloc(initial_capacity, sizeof(TrafficEvent));
    if (!manager->events) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;

    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond_var, NULL);

    return manager;
}

int add_event(EventManager* manager, EventType type, int cell_id, const char* source) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        TrafficEvent* new_events = (TrafficEvent*)realloc(manager->events, new_capacity * sizeof(TrafficEvent));
        if (!new_events) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->events = new_events;
        manager->capacity = new_capacity;
    }

    TrafficEvent* event = &manager->events[manager->count++];
    event->timestamp = time(NULL);
    event->event_type = type;
    event->cell_id = cell_id;

    size_t source_len = strlen(source) + 1;
    if (source_len > sizeof(event->event_source)) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Source too long
    }
    strncpy(event->event_source, source, sizeof(event->event_source));

    pthread_cond_signal(&manager->cond_var);
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void cleanup_old_events(EventManager* manager, time_t cutoff) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count;) {
        if (manager->events[i].timestamp < cutoff) {
            memmove(&manager->events[i], &manager->events[i + 1],
                    (manager->count - i - 1) * sizeof(TrafficEvent));
            manager->count--;
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void destroy_event_manager(EventManager* manager) {
    if (!manager) return;

    free(manager->events);
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond_var);
    free(manager);
}
