        msg->payload = malloc(payload_size);
        if (msg->payload == NULL) {
            perror("Failed to allocate memory for NAS message payload");
            free_messages(*messages, count); // Cleanup already allocated messages
            exit(EXIT_FAILURE);
        }

        memcpy(msg->payload, &mm_context, payload_size);

        // Verify integrity of the NAS message after construction
        if (!verify_message_integrity(msg)) {
            fprintf(stderr, "Message integrity verification failed for message %d\n", i);
            free(msg->payload);  // Free specific message's allocated memory on failure
            continue;            // Continue to next message in case of a single error
        }
    }
}

// Deallocate memory used by messages array and its payloads
void free_messages(LTE_Uplink_NAS_Message *messages, int count) {
    if (messages == NULL) return;

    for (int i = 0; i < count; ++i) {
