typedef struct {
    int value;
    char *identifier;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicRecordSystem;

DynamicRecordSystem* create_system(size_t initial_capacity) {
    DynamicRecordSystem *system = (DynamicRecordSystem*)malloc(sizeof(DynamicRecordSystem));
    if (!system) return NULL;

    system->offsets = (long*)malloc(initial_capacity * sizeof(long));
    system->keys = (int*)malloc(initial_capacity * sizeof(int));
    system->records = (record**)malloc(initial_capacity * sizeof(record*));

    system->capacity = initial_capacity;
    pthread_mutex_init(&system->lock, NULL);

    if (!system->offsets || !system->keys || !system->records) {
        free(system->offsets);
        free(system->keys);
        free(system->records);
        free(system);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        system->offsets[i] = rand() % 1000; // Random offset
        system->keys[i] = rand() % 100;
        system->records[i] = (record*)malloc(sizeof(record));

        if (!system->records[i]) {
            for (size_t j = 0; j < i; ++j) free(system->records[j]);
            free(system->offsets);
            free(system->keys);
            free(system->records);
            free(system);
            return NULL;
        }

        system->records[i]->value = rand() % 100;
        size_t id_len = strlen("UniqueID") + 1; // Example identifier length
        system->records[i]->identifier = (char*)malloc(id_len);

        if (!system->records[i]->identifier) {
            free(system->records[i]);
            for (size_t j = 0; j < i; ++j) free(system->records[j]);
            free(system->offsets);
            free(system->keys);
            free(system->records);
            free(system);
            return NULL;
        }

        sprintf(system->records[i]->identifier, "ID%d", (int)i); // Example unique identifier
    }

    return system;
}

void destroy_system(DynamicRecordSystem *system) {
    if (!system) return;

    for (size_t i = 0; i < system->capacity; ++i)
        free(system->records[i]->identifier);
    free(system->records);

    pthread_mutex_destroy(&system->lock);
    free(system->offsets);
    free(system->keys);
    free(system->records);
    free(system);
}

int compute_sum(DynamicRecordSystem *system, size_t start, size_t end, int target_sum) {
    if (!system || start >= system->capacity || end > system->capacity || start > end)
        return -1;

    pthread_mutex_lock(&system->lock);

    int sum = 0;
    int count = 0;
    for (size_t i = start; i < end; ++i) {
        sum += system->records[i]->value;
    }

    for (size_t i = start; i < end && sum >= target_sum; ++i) {
        if (system->records[i]->value > 0) count++;
    }

    pthread_mutex_unlock(&system->lock);
    return count;
}

void update_record(DynamicRecordSystem *system, const char *identifier, int new_value) {
    if (!system || !identifier)
        return;

    pthread_mutex_lock(&system->lock);

    for (size_t i = 0; i < system->capacity; ++i) {
        if (strcmp(system->records[i]->identifier, identifier) == 0) {
            system->records[i]->value = new_value;
            break;
        }
    }

    pthread_mutex_unlock(&system->lock);
}

void prune_records(DynamicRecordSystem *system, int threshold) {
    if (!system)
        return;

    pthread_mutex_lock(&system->lock);

    size_t valid_count = 0;
    for (size_t i = 0; i < system->capacity; ++i) {
        if (system->records[i]->value <= threshold) {
            system->records[valid_count++] = system->records[i];
        } else {
            free(system->records[i]->identifier);
            free(system->records[i]);
        }
    }

    system->capacity = valid_count;
    pthread_mutex_unlock(&system->lock);
}

void log_operation(const char *operation) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), operation);
}

// Example usage of the system
int main() {
    srand(time(NULL));
    DynamicRecordSystem *system = create_system(100);

    if (system) {
        log_operation("System created");

        int count = compute_sum(system, 0, 50, 2500);
        printf("Count meeting target sum: %d\n", count);

        update_record(system, "ID10", 500);
        prune_records(system, 100);

        destroy_system(system);
    }

    return 0;
}
