```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRCFLAG;  // Assuming it's a single byte flag for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int value;
    char *identifier;
} Record;

typedef struct Node {
    void *data;
    struct Node *next;
} QueueNode;

typedef struct {
    QueueNode *front, *rear;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} ThreadSafeQueue;

// Function prototypes
ThreadSafeQueue* create_queue();
void enqueue(ThreadSafeQueue *queue, void *data);
void* dequeue(ThreadSafeQueue *queue);
void free_queue(ThreadSafeQueue *queue);
NFAPI_CRC_INDICATION_PDU_T* initialize_pdu_array(size_t num_entries);
Record* initialize_record_array(size_t num_records);
void populate_pdu_array(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t count);
void populate_record_array(Record *records, size_t count);

// Thread-safe queue implementation
ThreadSafeQueue* create_queue() {
    ThreadSafeQueue *queue = malloc(sizeof(ThreadSafeQueue));
    if (!queue) {
        perror("Failed to allocate memory for queue");
        exit(EXIT_FAILURE);
    }
    queue->front = queue->rear = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond_var, NULL);
    return queue;
}

void enqueue(ThreadSafeQueue *queue, void *data) {
    QueueNode *new_node = malloc(sizeof(QueueNode));
    if (!new_node) {
        perror("Failed to allocate memory for queue node");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&queue->lock);
    if (queue->rear == NULL) {
        queue->front = queue->rear = new_node;
    } else {
        queue->rear->next = new_node;
        queue->rear = new_node;
    }
    pthread_cond_signal(&queue->cond_var);
    pthread_mutex_unlock(&queue->lock);
}

void* dequeue(ThreadSafeQueue *queue) {
    pthread_mutex_lock(&queue->lock);
    while (queue->front == NULL) {
        pthread_cond_wait(&queue->cond_var, &queue->lock);
    }
    QueueNode *temp = queue->front;
    void *data = temp->data;
    queue->front = queue->front->next;
    if (queue->front == NULL) {
        queue->rear = NULL;
    }
    free(temp);
    pthread_mutex_unlock(&queue->lock);
    return data;
}

void free_queue(ThreadSafeQueue *queue) {
    while (queue->front != NULL) {
        dequeue(queue);
    }
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->cond_var);
    free(queue);
}

// Function to initialize and populate an array of NFAPI_CRC_INDICATION_PDU_T
NFAPI_CRC_INDICATION_PDU_T* initialize_pdu_array(size_t num_entries) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Failed to allocate memory for PDUs");
        exit(EXIT_FAILURE);
    }
    populate_pdu_array(pdus, num_entries);
    return pdus;
}

void populate_pdu_array(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t count) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].RNTI = rand() % 10000;
        pdus[i].CRCFLAG = rand() & 1;  // Randomly set CRCFLAG to 0 or 1
    }
}

// Function to initialize and populate a record array
Record* initialize_record_array(size_t num_records) {
    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
    populate_record_array(records, num_records);
    return records;
}

void populate_record_array(Record *records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % 100;
        char identifier[20];
        snprintf(identifier, sizeof(identifier), "ID_%zu", i);
        records[i].identifier = strdup(identifier);
        if (!records[i].identifier) {
            perror("Failed to allocate memory for identifier");
            exit(EXIT_FAILURE);
        }
    }
}

// Main function for demonstration
int main() {
    size_t num_pdus = 100;
    size_t num_records = 50;

    NFAPI_CRC_INDICATION_PDU_T *pdus = initialize_pdu_array(num_pdus);
    Record *records = initialize_record_array(num_records);

    ThreadSafeQueue *queue = create_queue();
    enqueue(queue, pdus);
    enqueue(queue, records);

    // Dequeue and use data
    NFAPI_CRC_INDICATION_PDU_T *dequeued_pdus = dequeue(queue);
    Record *dequeued_records = dequeue(queue);

    // Clean up
    free(dequeued_pdus);
    for (size_t i = 0; i < num_records; ++i) {
        free(dequeued_records[i].identifier);
    }
    free(dequeued_records);
    free_queue(queue);

    return 0;
}
