public class DataHandler
{
    private static readonly string filePath = "data.bin";
    private static readonly IExternalDataSource externalDataSource = new ExternalDataSource();

    public CustomDataStructure LoadOrInitializeData()
    {
        if (!File.Exists(filePath))
        {
            InitializeDefaultData();
            return defaultInstance;
        }

        try
        {
            using (FileStream fileStream = File.OpenRead(filePath))
            {
                BinaryFormatter formatter = new BinaryFormatter();
                CustomDataStructure data = (CustomDataStructure)formatter.Deserialize(fileStream);

                // Ensure backward compatibility by checking version
                if (data.Version < GetCurrentVersion())
                {
                    data = UpgradeData(data);
                }

                SupplementDataWithExternalSources(ref data);

                return data;
            }
        }
        catch (Exception ex)
        {
            LogError($"Deserialization failed: {ex.Message}");
            InitializeDefaultData();
            return defaultInstance;
        }
