        free(crypto_engine);
        *status_code = -2; // Error populating list
        return NULL;
    }

    return crypto_engine;
}
```

This code implements a doubly linked list with thread-safe access and initializes it with data structures. It also sets up a flexible cryptographic engine supporting multiple cipher modes, including optional null encryption for testing purposes. The function `init_system` returns a pointer to the initialized cryptographic engine or NULL in case of failure, along with an error status code.']

['Here is a C implementation for managing a dynamic array of custom data structures representing network events:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    // Add more event types as needed
} EventType;

// Metadata structure
typedef struct {
    char key[64];
    char value[256];
} Metadata;

// Network Event structure
typedef struct {
    long timestamp;
    EventType type;
    Metadata metadata;
} NetworkEvent;

// Node for a linked list to manage dynamic array
typedef struct EventNode {
    NetworkEvent event;
    struct EventNode* next;
} EventNode;

// Dynamic Array of Network Events with Thread Safety
typedef struct {
    EventNode* head;
    pthread_mutex_t lock;
} EventArray;

// Function declarations
void init_event_array(EventArray* arr);
int add_event(EventArray* arr, const NetworkEvent* new_event);
int update_event(EventArray* arr, long timestamp, const NetworkEvent* updated_event);
int retrieve_events(EventArray* arr, long start_time, long end_time, NetworkEvent** events, int* count);
void free_event_array(EventArray* arr);

// Initialize the event array
void init_event_array(EventArray* arr) {
    arr->head = NULL;
    pthread_mutex_init(&arr->lock, NULL);
}

// Add a new event to the array
int add_event(EventArray* arr, const NetworkEvent* new_event) {
    pthread_mutex_lock(&arr->lock);

    EventNode** current = &arr->head;

    while (*current != NULL && (*current)->event.timestamp < new_event->timestamp) {
        current = &(*current)->next;
    }

    EventNode* newNode = (EventNode*)malloc(sizeof(EventNode));
    if (!newNode) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Memory allocation failed
    }

    *newNode = (EventNode){ .event = *new_event, .next = *current };
    *current = newNode;

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

// Update an existing event in the array based on timestamp
int update_event(EventArray* arr, long timestamp, const NetworkEvent* updated_event) {
    pthread_mutex_lock(&arr->lock);

    EventNode** current = &arr->head;

    while (*current != NULL) {
        if ((*current)->event.timestamp == timestamp) {
            memcpy(&(*current)->event, updated_event, sizeof(NetworkEvent));
            pthread_mutex_unlock(&arr->lock);
            return 0; // Successfully updated
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&arr->lock);
    return -1; // Event not found
}

// Retrieve events within a specified timestamp range
int retrieve_events(EventArray* arr, long start_time, long end_time, NetworkEvent** events, int* count) {
    pthread_mutex_lock(&arr->lock);

    int capacity = 10;
    *events = (NetworkEvent*)malloc(capacity * sizeof(NetworkEvent));
    if (!(*events)) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Memory allocation failed
    }

    *count = 0;
    EventNode* current = arr->head;

    while (current != NULL) {
        if (current->event.timestamp >= start_time && current->event.timestamp <= end_time) {
            if (*count == capacity) {
                capacity *= 2;
                *events = realloc(*events, capacity * sizeof(NetworkEvent));
                if (!(*events)) {
                    pthread_mutex_unlock(&arr->lock);
                    return -1; // Memory allocation failed
                }
            }
            (*events)[*count] = current->event;
            (*count)++;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

// Free the allocated memory for the event array
void free_event_array(EventArray* arr) {
    pthread_mutex_lock(&arr->lock);

    EventNode* current = arr->head;
    while (current != NULL) {
        EventNode* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
}
```

### Notes:
- **Thread Safety**: The implementation uses `pthread_mutex_t` to ensure thread safety during operations on the dynamic array.
- **Dynamic Array Management**: A linked list is used for dynamic management of events, allowing efficient insertions and updates based on timestamps.
- **Retrieval Optimization**: Events are retrieved in a single pass within the specified timestamp range, minimizing latency.
- **Scalability Considerations**: While this implementation uses an in-memory structure, integrating with distributed storage solutions like databases or key-value stores would be necessary for horizontal scaling.
- **Schema Validation and Error Handling**: These aspects can be integrated by adding validation functions before adding/updating events. Robust error handling is demonstrated through memory allocation checks and return codes.

This solution balances efficiency, usability, and maintainability while providing a foundation for further scalability enhancements.']

