```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define VALID_UE_ID_MIN 1
#define VALID_UE_ID_MAX 1000

typedef struct {
    int L1_config;
    int L2_config;
} L1_TEST_TX_RX_CONFIG_T;

typedef struct {
    int L1_config;
    int L2_config;
} L2_TEST_TX_RX_CONFIG_T;

typedef struct {
    int UE_ID;
    time_t timestamp;
    L1_TEST_TX_RX_CONFIG_T l1_config;
    L2_TEST_TX_RX_CONFIG_T l2_config;
} LTE_PHY_TEST_PDU_T;

typedef struct Node {
    LTE_PHY_TEST_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PDUList;

PDUList* create_pdu_list() {
    PDUList* list = (PDUList*)malloc(sizeof(PDUList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_valid_ue_id(int ue_id) {
    return ue_id >= VALID_UE_ID_MIN && ue_id <= VALID_UE_ID_MAX;
}

void insert_pdu(PDUList* list, LTE_PHY_TEST_PDU_T pdu) {
    if (!is_valid_ue_id(pdu.UE_ID)) {
        fprintf(stderr, "Invalid UE_ID: %d\n", pdu.UE_ID);
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current && ((*current)->pdu.timestamp < pdu.timestamp || 
                        ((*current)->pdu.timestamp == pdu.timestamp && 
                         (*current)->pdu.UE_ID != pdu.UE_ID))) {
        if ((*current)->pdu.UE_ID == pdu.UE_ID) {
            pthread_mutex_unlock(&list->lock);
            fprintf(stderr, "Duplicate UE_ID: %d\n", pdu.UE_ID);
            return;
        }
        current = &(*current)->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->pdu = pdu;
    new_node->next = *current;
    *current = new_node;

    pthread_mutex_unlock(&list->lock);
}

void free_pdu_list(PDUList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    PDUList* pdu_list = create_pdu_list();

    LTE_PHY_TEST_PDU_T pdu1 = { .UE_ID = 100, .timestamp = time(NULL) - 10 };
    LTE_PHY_TEST_PDU_T pdu2 = { .UE_ID = 200, .timestamp = time(NULL) + 5 };

    insert_pdu(pdu_list, pdu1);
    insert_pdu(pdu_list, pdu2);

    free_pdu_list(pdu_list);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The list is protected by a mutex to ensure thread-safe operations.
- **Validation**: Checks for valid `UE_ID` and prevents duplicates.
- **Chronological Order**: Inserts new nodes in order based on timestamps.
- **Memory Management**: Properly allocates and frees memory for nodes.
- **Error Handling**: Provides basic error messages for invalid operations.

This code is designed to be efficient, scalable, and maintainable while minimizing dependencies.']

