    min_size = (min_size < (sizeof(doubles) / sizeof(doubles[0]))) ? min_size : (sizeof(doubles) / sizeof(doubles[0]));

    for (size_t i = 0; i < size; ++i) {
        dataArray[i] = (Data *)malloc(sizeof(Data));
        if (!dataArray[i]) {
            fprintf(stderr, "Memory allocation failed for Data element at index %zu\n", i);
            // Free previously allocated memory on failure.
            while (i-- > 0) free(dataArray[i]);
            free(dataArray);
            return NULL;
