        dataArray[i]->number = compute_int_value(chars[i], doubles[i]);
        dataArray[i]->decimalValue = doubles[i];
        dataArray[i]->text = "Sample Text"; // Placeholder for actual text data.
    }

    // Handle excess allocation by setting them to NULL if they were allocated.
    for (size_t i = min_size; i < size; ++i) {
