#include <resolv.h>

#define MAX_STRUCTURES 1000
#define MAX_MEMORY_USAGE 2 * 1024 * 1024 // 2MB in bytes
#define MAX_DNS_QUERIES 10

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char hostname[256];
    NFAPI_CRC_INDICATION_PDU_T *pdu;
} DNSQuery;

pthread_mutex_t dnsMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t condVar = PTHREAD_COND_INITIALIZER;
DNSQuery dnsQueue[MAX_DNS_QUERIES];
int queueSize = 0;

void log_message(const char *message) {
    printf("%s\n", message);
}

int resolve_dns(DNSQuery *query) {
    struct hostent *host;
    host = gethostbyname(query->hostname);

    if (host == NULL) {
        log_message("DNS resolution failed for hostname: ");
        log_message(query->hostname);
        return -1; // DNS Resolution failure
    }

    inet_ntop(AF_INET, *(struct in_addr **)host->h_addr_list, query->pdu->RX_UE_INFORMATION_TAG, sizeof(query->pdu->RX_UE_INFORMATION_TAG));
    log_message("DNS resolution successful for hostname: ");
    log_message(query->hostname);
    return 0; // Success
}

void* dns_worker(void *arg) {
    while (1) {
        pthread_mutex_lock(&dnsMutex);

        while (queueSize == 0) {
            pthread_cond_wait(&condVar, &dnsMutex);
        }

        DNSQuery query = dnsQueue[--queueSize];
        pthread_mutex_unlock(&dnsMutex);

        if (resolve_dns(&query)) {
            log_message("Error resolving DNS. Check logs.");
        }
    }
}

void process_structures(NFAPI_CRC_INDICATION_PDU_T **structures, int numStructures) {
    int totalMemoryUsage = 0;
    for (int i = 0; i < numStructures; ++i) {
        structures[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structures[i]) {
            log_message("Memory allocation failed.");
            exit(EXIT_FAILURE);
        }

        totalMemoryUsage += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        // Fill in structure data, including random CRCFLAG
        structures[i]->RX_UE_INFORMATION_TAG = rand();
        structures[i]->RNTI = rand() & 0xFFFF;
        structures[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        if (totalMemoryUsage > MAX_MEMORY_USAGE) {
            log_message("Warning: Memory usage exceeded threshold.");
            break;
        }
    }

    pthread_t threads[MAX_DNS_QUERIES];
    for (int i = 0; i < MAX_DNS_QUERIES; ++i) {
        pthread_create(&threads[i], NULL, dns_worker, NULL);
    }

    int processedStructures = 0;
    while (processedStructures < numStructures && queueSize < MAX_DNS_QUERIES) {
        if (resolve_dns(&dnsQueue[queueSize])) {
            log_message("Error resolving DNS. Check logs.");
        } else {
            pthread_mutex_lock(&dnsMutex);
            queueSize++;
            pthread_cond_signal(&condVar);
            pthread_mutex_unlock(&dnsMutex);

            processedStructures++;
        }
    }

    while (queueSize > 0) {
        pthread_mutex_lock(&dnsMutex);
        pthread_cond_wait(&condVar, &dnsMutex);
        pthread_mutex_unlock(&dnsMutex);
    }

    for (int i = 0; i < MAX_DNS_QUERIES; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void free_structures(NFAPI_CRC_INDICATION_PDU_T **structures, int numStructures) {
    for (int i = 0; i < numStructures; ++i) {
        if (structures[i]) {
            free(structures[i]);
        }
    }
}
