#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef enum {
    TERMINATION_CAUSE_NONE = 0,
    TERMINATION_CAUSE_TIMEOUT,
    TERMINATION_CAUSE_USER_REQUEST,
    // Add more causes as needed
} SessionTerminationCause;

typedef struct {
    int FlowID;
    char Direction[10];
    int PDUSessionID;
    SessionTerminationCause TerminationCause;
} TrafficFlowConfig;

typedef struct {
    TrafficFlowConfig *configs;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Function prototypes
void initDynamicArray(DynamicArray *array);
void freeDynamicArray(DynamicArray *array);
int addTrafficFlowConfig(DynamicArray *array, int FlowID, const char *Direction, int PDUSessionID);
void assignRandomTerminationCause(TrafficFlowConfig *config);
int validateTrafficFlowConfig(const TrafficFlowConfig *config);
void logConfigurationChange(const TrafficFlowConfig *config);

// Initialize the dynamic array
void initDynamicArray(DynamicArray *array) {
    pthread_mutex_init(&array->lock, NULL);
    array->capacity = 10;
    array->count = 0;
    array->configs = malloc(array->capacity * sizeof(TrafficFlowConfig));
}

// Free the dynamic array resources
void freeDynamicArray(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->configs);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

// Add a new TrafficFlowConfig to the array
int addTrafficFlowConfig(DynamicArray *array, int FlowID, const char *Direction, int PDUSessionID) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        TrafficFlowConfig *new_configs = realloc(array->configs, new_capacity * sizeof(TrafficFlowConfig));
        if (!new_configs) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->configs = new_configs;
        array->capacity = new_capacity;
    }

    TrafficFlowConfig config = { .FlowID = FlowID, .PDUSessionID = PDUSessionID };
    strncpy(config.Direction, Direction, sizeof(config.Direction) - 1);
    config.Direction[sizeof(config.Direction) - 1] = '\0';

    assignRandomTerminationCause(&config);

    if (!validateTrafficFlowConfig(&config)) {
        pthread_mutex_unlock(&array->lock);
        return -2; // Validation failed
    }

    array->configs[array->count++] = config;
    logConfigurationChange(&config);

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Assign a random termination cause based on predefined probabilities
void assignRandomTerminationCause(TrafficFlowConfig *config) {
    // Example probability distribution
    const double probabilities[] = {0.7, 0.2, 0.1}; // Adjust as needed
    double rand_val = (double)rand() / RAND_MAX;

    if (rand_val < probabilities[TERMINATION_CAUSE_TIMEOUT]) {
        config->TerminationCause = TERMINATION_CAUSE_TIMEOUT;
    } else if (rand_val < probabilities[TERMINATION_CAUSE_TIMEOUT] + probabilities[TERMINATION_CAUSE_USER_REQUEST]) {
        config->TerminationCause = TERMINATION_CAUSE_USER_REQUEST;
    } else {
        config->TerminationCause = TERMINATION_CAUSE_NONE;
    }
}

// Validate the TrafficFlowConfig
int validateTrafficFlowConfig(const TrafficFlowConfig *config) {
    if (config->FlowID <= 0 || strlen(config->Direction) == 0 || config->PDUSessionID < 0) {
        return 0; // Invalid configuration
    }
    return 1;
}

// Log configuration changes for debugging and auditing
void logConfigurationChange(const TrafficFlowConfig *config) {
    printf("Config Change: FlowID=%d, Direction='%s', PDUSessionID=%d, TerminationCause=%d\n",
           config->FlowID, config->Direction, config->PDUSessionID, config->TerminationCause);
}

// Example usage
int main() {
    DynamicArray array;
    initDynamicArray(&array);

    addTrafficFlowConfig(&array, 1, "UP", 1001);
    addTrafficFlowConfig(&array, 2, "DOWN", 1002);

    freeDynamicArray(&array);
    return 0;
}
