    void* ptr = aligned_alloc(64, n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ptr) {
        perror("Memory allocation failed");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)ptr;

    // Initialize each structure with predefined values and random CRCFLAG
    for (size_t i = 0; i < n; ++i) {
        initialize_crc_pdu(&pdu_array[i]);
    }

    return ptr;
}

// Function to initialize a single NFAPI_CRC_INDICATION_PDU_T structure
void initialize_crc_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Set RX_UE_INFORMATION_TAG, RNTI with predefined values (adjust as necessary)
    pdu->rx_ue_info.tag = 0x12345678; // Example value
    pdu->rnti.rnti = rand() % 65536;   // Random RNTI

    // Set CRC_INDICATION_REL8_TAG with a random CRCFLAG
    pdu->crc_indication_rel8_tag.crcflag = rand() & 0x01;
}

// Function to deallocate the allocated array and prevent memory leaks
void free_crc_pdu_array(void** array, size_t n) {
    if (array && *array) {
        free(*array);
        *array = NULL;
    }
}

// Thread-safe function to verify CRC integrity with redundancy checks
int verify_crc_integrity(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&crc_pdu_mutex);

    // Implement verification logic (example: basic checksum validation)
    int is_valid = 1; // Assume valid by default, replace with actual checks

