        parity ^= ((uint8_t*)pdu)[i];
    }
    if (parity != pdu->crc_indication_rel8_tag.crcflag) {
        is_valid = 0;
    }

    pthread_mutex_unlock(&crc_pdu_mutex);
    return is_valid;
