    // Implement validation logic, e.g., check if tags are non-zero
    return (pdu->RX_UE_INFORMATION_TAG != 0 && pdu->RNTI != 0);
}

void initializeList(List* list) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for node");
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void addElement(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (isValid(&pdu)) {
        Node* newNode = createNode(pdu);
        if (!newNode) {
            pthread_mutex_unlock(&list->lock);
            return;
        }

        newNode->next = list->head;
        list->head = newNode;
        list->count++;

        if (list->count > MAX_ELEMENTS) {
            // Handle overflow, e.g., remove oldest element
            Node* temp = list->head;
            list->head = list->head->next;
            free(temp);
            list->count--;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void freeList(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

