    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for the linked list
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} ThreadSafeList;

// Function prototypes
ThreadSafeList* create_list();
void destroy_list(ThreadSafeList *list);
bool add_pdu(ThreadSafeList *list, const UE_INFORMATION_TAG *ue_info_tag, RNTI rnti);
bool remove_pdu(ThreadSafeList *list, RNTI rnti);
void print_pdu_list(const ThreadSafeList *list);

// Helper functions
static NFAPI_CRC_INDICATION_PDU_T* create_pdu_node(const UE_INFORMATION_TAG *ue_info_tag, RNTI rnti);

ThreadSafeList* create_list() {
    ThreadSafeList *list = (ThreadSafeList *)malloc(sizeof(ThreadSafeList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(ThreadSafeList *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool add_pdu(ThreadSafeList *list, const UE_INFORMATION_TAG *ue_info_tag, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = create_pdu_node(ue_info_tag, rnti);
    if (!new_node) return false;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return true;
}

bool remove_pdu(ThreadSafeList *list, RNTI rnti) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T **indirect = &list->head;
    while (*indirect) {
        NFAPI_CRC_INDICATION_PDU_T *entry = *indirect;
        if (entry->rnti == rnti) {
            *indirect = entry->next;
            free(entry);
            pthread_mutex_unlock(&list->lock);
            return true;
        }
        indirect = &entry->next;
    }

    pthread_mutex_unlock(&list->lock);
    return false;
}

void print_pdu_list(const ThreadSafeList *list) {
    pthread_mutex_lock((pthread_mutex_t *)&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        printf("RNTI: %u, RX_UE_INFORMATION_TAG: %d, CRCFLAG: %s\n",
               current->rnti,
               current->ue_info_tag.RX_UE_INFORMATION_TAG,
               current->crc_indication_rel8_tag.CRCFLAG ? "true" : "false");
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t *)&list->lock);
}

static NFAPI_CRC_INDICATION_PDU_T* create_pdu_node(const UE_INFORMATION_TAG *ue_info_tag, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;

    node->ue_info_tag = *ue_info_tag;
    node->rnti = rnti;
    node->crc_indication_rel8_tag.CRCFLAG = rand() % 2 == 0; // Random CRCFLAG
    node->next = NULL;

    return node;
}

// Example usage and testing
void test_thread_safe_list() {
