    UE_INFORMATION_TAG ue_info_tag2 = {456};
    add_pdu(list, &ue_info_tag2, 1002);

    printf("List after additions:\n");
    print_pdu_list(list);

    remove_pdu(list, 1001);

    printf("List after removal of RNTI 1001:\n");
    print_pdu_list(list);

    destroy_list(list);
}

int main() {
    test_thread_safe_list();
    return 0;
}
