#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <jansson.h> // JSON library

#define MEMORY_POOL_SIZE 1024 * 1024 // 1MB pool size

typedef struct {
    char* memory;
    size_t offset;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct {
    char id[256];
    void (*factory)(void**);
} FactoryFunction;

typedef struct JSONObject {
    char* RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[256];
    int CRCFLAG;
} JSONObject;

// Global variables
MemoryPool mem_pool = { .memory = NULL, .offset = 0 };
FactoryFunction registry[100]; // Example size
size_t registry_size = 0;
pthread_mutex_t registry_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_memory_pool() {
    mem_pool.memory = malloc(MEMORY_POOL_SIZE);
    if (!mem_pool.memory) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&mem_pool.lock, NULL);
}

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&mem_pool.lock);
    if (mem_pool.offset + size > MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&mem_pool.lock);
        fprintf(stderr, "Memory pool exhausted\n");
        return NULL;
    }
    void* ptr = mem_pool.memory + mem_pool.offset;
    mem_pool.offset += size;
    pthread_mutex_unlock(&mem_pool.lock);
    return ptr;
}

void register_factory_function(const char* id, void (*factory)(void**)) {
    pthread_mutex_lock(&registry_lock);
    strncpy(registry[registry_size].id, id, sizeof(registry[registry_size].id) - 1);
    registry[registry_size].factory = factory;
    registry_size++;
    pthread_mutex_unlock(&registry_lock);
}

JSONObject* create_json_object_from_string(const char* json_str) {
    JSONObject* obj = allocate_from_pool(sizeof(JSONObject));
    if (!obj) return NULL;

    json_error_t error;
    json_t* root = json_loads(json_str, 0, &error);
    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        free(obj);
        return NULL;
    }

    json_t* rx_ue_info = json_object_get(root, "RX_UE_INFORMATION_TAG");
    json_t* rnti = json_object_get(root, "RNTI");
    json_t* crc_ind = json_object_get(root, "CRC_INDICATION_REL8_TAG");

    obj->RX_UE_INFORMATION_TAG = json_string_value(rx_ue_info);
    obj->RNTI = json_integer_value(rnti);

    strncpy(obj->CRC_INDICATION_REL8_TAG, json_string_value(crc_ind), sizeof(obj->CRC_INDICATION_REL8_TAG) - 1);
    obj->CRCFLAG = rand() % 256; // Random CRCFLAG

    json_decref(root);
    return obj;
}

char* json_object_to_string(JSONObject* obj) {
    json_t* root = json_pack("{s:s, s:i, s:s, s:i}", 
                             "RX_UE_INFORMATION_TAG", obj->RX_UE_INFORMATION_TAG,
                             "RNTI", obj->RNTI,
                             "CRC_INDICATION_REL8_TAG", obj->CRC_INDICATION_REL8_TAG,
                             "CRCFLAG", obj->CRCFLAG);
    if (!root) {
        fprintf(stderr, "Error creating JSON object\n");
        return NULL;
    }

    char* json_str = json_dumps(root, 0);
    json_decref(root);
    return json_str;
}

void factory_example(void** ptr) {
    *ptr = allocate_from_pool(sizeof(JSONObject));
    if (*ptr) {
        JSONObject* obj = (JSONObject*)*ptr;
        obj->RX_UE_INFORMATION_TAG = "ExampleTag";
        obj->RNTI = 1234;
        strcpy(obj->CRC_INDICATION_REL8_TAG, "ExampleIndication");
        obj->CRCFLAG = rand() % 256;
    }
}

int main() {
    srand(time(NULL));
    initialize_memory_pool();

    register_factory_function("example", factory_example);

    void* instance_ptr;
    FactoryFunction func = registry[0]; // Example access
    func.factory(&instance_ptr);

    JSONObject* obj = (JSONObject*)instance_ptr;
    char* json_str = json_object_to_string(obj);
    printf("%s\n", json_str);
    free(json_str);

    free(mem_pool.memory);
    return 0;
}
```

### Key Points:
- **Memory Pool**: A simple memory pool is implemented to manage dynamic allocations efficiently.
- **Thread Safety**: Mutexes ensure thread-safe access to shared resources like the memory pool and factory registry.
- **JSON Handling**: Uses `jansson` for JSON parsing and serialization.
- **Factory Registry**: Allows registration of factory functions for creating instances dynamically.
- **Error Handling**: Basic error handling is included, with logging to `stderr`.
- **Modularity**: The design allows easy extension and integration.

### Trade-offs:
- **Memory Efficiency vs. Fragmentation**: A fixed-size memory pool reduces fragmentation but may limit flexibility if the size isn't well-tuned.
- **Thread Safety vs. Performance**: Mutexes ensure thread safety but can introduce contention under high concurrency.
- **Scalability**: The design supports scalability through modular components and efficient memory management.

This code provides a foundation for managing JSON objects in a concurrent environment, with considerations for performance and maintainability.']

