    stats->reports = (MeasurementReport*)calloc(initialSize, sizeof(MeasurementReport));

    if (!stats->setupRequests || !stats->rejects || !stats->reports) {
        free(stats->setupRequests);
        free(stats->rejects);
        free(stats->reports);
        free(stats);
        return NULL;
    }

    stats->setupCount = 0;
    stats->rejectCount = 0;
    stats->reportCount = 0;

    return stats;
}

void populateUeSessionStats(UeSessionStats *stats, size_t dataSize) {
    // Simulate data population with dummy values
    for (size_t i = 0; i < dataSize; ++i) {
        if (stats->setupCount >= sizeof(stats->setupRequests) / sizeof(RrcConnectionSetupRequest)) {
            stats->setupRequests = realloc(stats->setupRequests, (stats->setupCount + 1) * sizeof(RrcConnectionSetupRequest));
        }
        stats->setupRequests[stats->setupCount].id = i;
        ++stats->setupCount;

        if (stats->rejectCount >= sizeof(stats->rejects) / sizeof(RrcConnectionReject)) {
            stats->rejects = realloc(stats->rejects, (stats->rejectCount + 1) * sizeof(RrcConnectionReject));
        }
        stats->rejects[stats->rejectCount].setupRequestId = i;
        ++stats->rejectCount;

        if (stats->reportCount >= sizeof(stats->reports) / sizeof(MeasurementReport)) {
            stats->reports = realloc(stats->reports, (stats->reportCount + 1) * sizeof(MeasurementReport));
        }
        stats->reports[stats->reportCount].setupId = i;
        stats->reports[stats->reportCount].rejectId = i; // Simulating a matching reject
        ++stats->reportCount;
    }
}

int validateSessionStats(UeSessionStats *stats) {
    for (size_t i = 0; i < stats->reportCount; ++i) {
        int setupFound = 0, rejectFound = 0;

        for (size_t j = 0; j < stats->setupCount; ++j) {
            if (stats->setupRequests[j].id == stats->reports[i].setupId) {
                setupFound = 1;
                break;
            }
        }

        for (size_t k = 0; k < stats->rejectCount; ++k) {
            if (stats->rejects[k].setupRequestId == stats->reports[i].rejectId) {
                rejectFound = 1;
                break;
            }
        }

        if (!setupFound || !rejectFound) return -1;
    }
    return 0;
}

void freeUeSessionStats(UeSessionStats *stats) {
    if (stats) {
        free(stats->setupRequests);
        free(stats->rejects);
        free(stats->reports);
        free(stats);
    }
}
