// Define the DataPacket structure
typedef struct {
    int packetId;
    char sourceAddress[256];
    char destinationAddress[256];
    long timestamp;
} DataPacket;

// Define a dynamic array for managing packets
typedef struct {
    DataPacket *packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} PacketArray;

// Function prototypes
void initPacketArray(PacketArray *array, size_t initialCapacity);
void freePacketArray(PacketArray *array);
int addPacket(PacketArray *array, DataPacket packet);
int removePacketById(PacketArray *array, int packetId);
int updateTimestampById(PacketArray *array, int packetId, long newTimestamp);
void logOperation(const char *operation);

// Initialize the dynamic array
void initPacketArray(PacketArray *array, size_t initialCapacity) {
    pthread_mutex_init(&array->lock, NULL);
    array->capacity = initialCapacity;
    array->size = 0;
    array->packets = (DataPacket *)malloc(array->capacity * sizeof(DataPacket));
}

// Free the dynamic array
void freePacketArray(PacketArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->packets);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

// Add a new packet to the array
int addPacket(PacketArray *array, DataPacket packet) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        DataPacket *newPackets = (DataPacket *)realloc(array->packets, newCapacity * sizeof(DataPacket));

        if (!newPackets) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }

        array->packets = newPackets;
        array->capacity = newCapacity;
    }

    int index = array->size++;
    array->packets[index] = packet;

    logOperation("Add packet");

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

// Remove a packet by its ID
int removePacketById(PacketArray *array, int packetId) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->packets[i].packetId == packetId) {
            memmove(&array->packets[i], &array->packets[i + 1],
                    (--array->size - i) * sizeof(DataPacket));

            logOperation("Remove packet");

            pthread_mutex_unlock(&array->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Packet not found
}

// Update the timestamp of a packet by its ID
int updateTimestampById(PacketArray *array, int packetId, long newTimestamp) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->packets[i].packetId == packetId) {
            array->packets[i].timestamp = newTimestamp;

            logOperation("Update timestamp");

            pthread_mutex_unlock(&array->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Packet not found
}

// Dummy logging function for demonstration purposes
void logOperation(const char *operation) {
    printf("Log: %s\n", operation); // Replace with real logging integration
}
