        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int instance_id;
    int service_state; // 0: stopped, 1: started
    time_t current_time;
    int iteration_number;
    char log_message[256];
} NetworkInstanceState;

NetworkInstanceState networkInstances[MAX_NETWORK_INSTANCES];
int activeInstanceCount = 0;
pthread_mutex_t resourceMutex;

void initializePDU(NFAPI_CRC_INDICATION_PDU_T *pdu, int instance_id) {
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Simulate valid tag
    pdu->RNTI = instance_id;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG (0 or 1)
}

void logStateTransition(int instance_id, int service_state) {
    NetworkInstanceState *state = &networkInstances[instance_id];
    state->service_state = service_state;
    time(&state->current_time);
    state->iteration_number++;

    snprintf(state->log_message,
             sizeof(state->log_message),
             "Instance %d: State %s at Time %ld, Iteration %d",
             instance_id,
             (service_state == 1 ? "Started" : "Stopped"),
             state->current_time,
             state->iteration_number);

    printf("%s\n", state->log_message); // Replace with actual logging mechanism
}

void* manageInstance(void *arg) {
    int instance_id = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T pdu;

    initializePDU(&pdu, instance_id);

    pthread_mutex_lock(&resourceMutex);
    logStateTransition(instance_id, 1); // Log starting state
    activeInstanceCount++;
    pthread_mutex_unlock(&resourceMutex);

    // Simulate processing work
    sleep(rand() % 3 + 1);

    pthread_mutex_lock(&resourceMutex);
    logStateTransition(instance_id, 0); // Log stopping state
    activeInstanceCount--;
    pthread_mutex_unlock(&resourceMutex);

    return NULL;
}

void initializeNetworkInstances(int max_instances) {
    srand(time(NULL));
    pthread_t threads[max_instances];
    int instance_ids[max_instances];

    for (int i = 0; i < max_instances; ++i) {
        networkInstances[i].instance_id = i;
        instance_ids[i] = i;

        if (pthread_create(&threads[i], NULL, manageInstance, &instance_ids[i]) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < max_instances; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    pthread_mutex_init(&resourceMutex, NULL);

    initializeNetworkInstances(MAX_NETWORK_INSTANCES);

    pthread_mutex_destroy(&resourceMutex);

    return 0;
}
