typedef struct {
    unsigned int version;
    unsigned int type;
    unsigned short length;
} MAC_HEADER;

typedef struct {
    char tag[16];
    unsigned int rnti;
    unsigned int frameSyncStatus;
    int alignmentOffset;
} RX_UE_INFORMATION_TAG;

typedef struct {
    MAC_HEADER header;
    unsigned char *data; // Dynamic data payload
    unsigned int checksum;
    int checksumValid;
    int extendedHeaderPresent;
    RX_UE_INFORMATION_TAG rxInfo;
} MAC_RX_FRAME;

typedef enum {
    CHECKSUM_ALGORITHM_A,
    CHECKSUM_ALGORITHM_B
} ChecksumAlgorithmType;

MAC_RX_FRAME* initialize_mac_rx_frames(int numFrames, int enableLogging, ChecksumAlgorithmType checksumType) {
    if (numFrames <= 0) return NULL;

    MAC_RX_FRAME *frames = (MAC_RX_FRAME *)malloc(numFrames * sizeof(MAC_RX_FRAME));
    if (!frames) {
        perror("Memory allocation failed for frames");
        return NULL;
    }

    // Example external data source fetch simulation
    int latency = fetch_latency_from_external_source();
    int bandwidth = fetch_bandwidth_from_external_source();

    for (int i = 0; i < numFrames; ++i) {
        frames[i].header.version = 1;
        frames[i].header.type = i % 3 + 1; // Example type cycling
        frames[i].header.length = 100 + (i * 10); // Example length logic

        size_t dataSize = frames[i].header.length - sizeof(MAC_HEADER);
        frames[i].data = (unsigned char *)malloc(dataSize);
        if (!frames[i].data) {
            perror("Memory allocation failed for frame data");
            for (int j = 0; j < i; ++j) free(frames[j].data); // Free previously allocated
            free(frames);
            return NULL;
        }

        memset(frames[i].data, 0xAB, dataSize); // Fill with dummy data

        frames[i].checksum = calculate_checksum(frames[i].data, dataSize, checksumType);
        frames[i].checksumValid = validate_checksum(frames[i].data, dataSize, frames[i].checksum);

        frames[i].extendedHeaderPresent = (i % 2 == 0) ? 1 : 0; // Example logic for optional extended headers

        snprintf(frames[i].rxInfo.tag, sizeof(frames[i].rxInfo.tag), "Tag-%04d", i);
        frames[i].rxInfo.rnti = calculate_rnti(i);

        frames[i].rxInfo.frameSyncStatus = 1; // Assume frame sync success
        frames[i].rxInfo.alignmentOffset = calculate_alignment_offset(latency, bandwidth, dataSize);

        if (enableLogging) {
            log_frame_details(&frames[i]);
        }
    }

    return frames;
}

unsigned int calculate_checksum(unsigned char *data, size_t length, ChecksumAlgorithmType type) {
    unsigned int checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        if (type == CHECKSUM_ALGORITHM_A)
            checksum += data[i] + i;
        else
            checksum += (data[i] * (i+1)) % 256;
    }
    return checksum % 65536;
}

int validate_checksum(unsigned char *data, size_t length, unsigned int expectedChecksum) {
    return calculate_checksum(data, length, CHECKSUM_ALGORITHM_A) == expectedChecksum;
}

unsigned int calculate_rnti(int index) {
    // Simplified RNTI calculation
    return (index + 1) * 1234 % 10000;
}

int calculate_alignment_offset(int latency, int bandwidth, size_t dataSize) {
    // Example alignment offset calculation based on performance metrics
    return (latency + dataSize / bandwidth) % 8; 
}

void log_frame_details(const MAC_RX_FRAME *frame) {
    printf("MAC Header Version: %u\n", frame->header.version);
    printf("MAC Header Type: %u\n", frame->header.type);
    printf("Checksum Valid: %d\n", frame->checksumValid);
    printf("RX UE Tag: %s\n", frame->rxInfo.tag);
    printf("RNTI: %u\n", frame->rxInfo.rnti);
    // Add more logging details as needed
}

int fetch_latency_from_external_source() {
    // Simulated latency fetching logic
    return 10; 
}

int fetch_bandwidth_from_external_source() {
    // Simulated bandwidth fetching logic
    return 1000; 
}

void free_mac_rx_frames(MAC_RX_FRAME *frames, int numFrames) {
    if (frames) {
        for (int i = 0; i < numFrames; ++i) {
            if (frames[i].data) free(frames[i].data);
        }
        free(frames);
    }
}
