int validateSRSConfig(SRSConfig config) {
    return config.SRSConfigParameter >= PERFORMANCE_THRESHOLD;
}

Node* createNode(UEContextInfo context) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    newNode->context = context;
    newNode->next = NULL;
    return newNode;
}

void addContext(UEContextList* list, UEContextInfo context) {
    Node* newNode = createNode(context);

    if (!list->head) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = newNode;
    }

    list->size++;
}

void initializeUEContexts(UEContextList* list, size_t numUe) {
    if (!list || numUe == 0) return;

    for (size_t i = 0; i < numUe; ++i) {
        UEContextInfo context;
        context.UEID = i + 1;
        context.RNTI = rand() % 1000 + 1;
        context.SRSConfig.SRSConfigParameter = generateSRSConfigParameter();

        if (validateSRSConfig(context.SRSConfig)) {
            addContext(list, context);
        } else {
            printf("Invalid SRS Config for UEID %d\n", context.UEID);
        }
    }
}

void cleanupContexts(UEContextList* list) {
    Node* current = list->head;
    while (current) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }
    list->head = NULL;
    list->size = 0;
}

int main() {
    UEContextList ueContexts = {NULL, 0};

    initializeRandom();
    initializeUEContexts(&ueContexts, 10);

    // For demonstration purposes: Print the number of valid contexts
    printf("Number of valid contexts: %zu\n", ueContexts.size);

    cleanupContexts(&ueContexts);
    return 0;
}
