    int RNTI;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the dynamic array structure with thread-safety mechanisms
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} DynamicArray;

// Initialize the dynamic array
int init_dynamic_array(DynamicArray* arr, size_t initial_capacity) {
    if (initial_capacity == 0)
        return -1;

    arr->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->data) {
        return -1; // Memory allocation failure
    }

    arr->capacity = initial_capacity;
    arr->count = 0;
    pthread_mutex_init(&arr->lock, NULL);
    pthread_cond_init(&arr->cond_var, NULL);

    return 0;
}

// Resize the dynamic array when needed
static int resize_dynamic_array(DynamicArray* arr) {
    size_t new_capacity = arr->capacity * 2;

    NFAPI_CRC_INDICATION_PDU_T* temp_data = realloc(arr->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp_data)
        return -1; // Memory allocation failure

    arr->data = temp_data;
    arr->capacity = new_capacity;

    return 0;
}

// Add a new element to the dynamic array
int add_element(DynamicArray* arr, int rx_ue_info_tag, int rnti) {
    pthread_mutex_lock(&arr->lock);

    if (arr->count == arr->capacity) {
        int resize_result = resize_dynamic_array(arr);
        if (resize_result != 0) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // Memory allocation failure
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* element = &arr->data[arr->count];
    element->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    element->RNTI = rnti;
    element->crc_indication_rel8_tag.CRCFLAG = rand() % 256; // Random CRCFLAG

    arr->count++;

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

// Modify a specific element based on conditions
int modify_element(DynamicArray* arr, int rx_ue_info_tag, uint32_t new_crcflag) {
    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->count; ++i) {
        if (arr->data[i].RX_UE_INFORMATION_TAG == rx_ue_info_tag) {
            arr->data[i].crc_indication_rel8_tag.CRCFLAG = new_crcflag;
            pthread_mutex_unlock(&arr->lock);
            return 0; // Element modified
        }
    }

    pthread_mutex_unlock(&arr->lock);
    return -1; // Element not found
}

// Clean up the dynamic array
void destroy_dynamic_array(DynamicArray* arr) {
    pthread_mutex_lock(&arr->lock);

    free(arr->data);
    arr->data = NULL;
    arr->capacity = 0;
    arr->count = 0;

    pthread_mutex_unlock(&arr->lock);

    pthread_mutex_destroy(&arr->lock);
    pthread_cond_destroy(&arr->cond_var);
}

// Example usage
int main() {
    DynamicArray dynamic_array;

    if (init_dynamic_array(&dynamic_array, 4) != 0) {
        fprintf(stderr, "Failed to initialize the dynamic array.\n");
        return EXIT_FAILURE;
    }

    add_element(&dynamic_array, 1, 100);
    add_element(&dynamic_array, 2, 200);

    modify_element(&dynamic_array, 1, 123); // Modify CRCFLAG for RX_UE_INFORMATION_TAG = 1

    destroy_dynamic_array(&dynamic_array);

    return EXIT_SUCCESS;
}
