#define MAX_CONTEXTS 1000 // Predefined system limit for contexts
#define ALIGNMENT 4

typedef struct {
    uint32_t incoming;
    uint32_t outgoing;
} TrafficStats;

typedef struct {
    char imsi[16]; // IMSI as a string
    uint32_t rnti; 
    TrafficStats traffic_stats;
} UEContext;

// Forward declaration of the database functions for persistence
void save_context_to_db(const UEContext* context);
int load_contexts_from_db(UEContext** contexts, size_t* count);

typedef struct {
    UEContext* contexts[MAX_CONTEXTS];
    size_t current_count;
    pthread_rwlock_t lock; // Read-write lock for concurrent access
} ContextManager;

// Function prototypes
void initialize_manager(ContextManager* manager);
int add_context(ContextManager* manager, const char* imsi, uint32_t rnti, TrafficStats traffic_stats);
UEContext* get_context_by_imsi(const ContextManager* manager, const char* imsi);
void update_traffic_stats(UEContext* context, uint32_t incoming_delta, uint32_t outgoing_delta);
void cleanup_manager(ContextManager* manager);

// Helper function for aligned memory allocation
static void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Allocation failed
    }
    return ptr;
}

void initialize_manager(ContextManager* manager) {
    memset(manager, 0, sizeof(*manager));
    pthread_rwlock_init(&manager->lock, NULL);
    // Load existing contexts from the database into memory (lazy initialization)
    load_contexts_from_db(manager->contexts, &manager->current_count);
}

int add_context(ContextManager* manager, const char* imsi, uint32_t rnti, TrafficStats traffic_stats) {
    pthread_rwlock_wrlock(&manager->lock);

    if (manager->current_count >= MAX_CONTEXTS) {
        pthread_rwlock_unlock(&manager->lock);
        return -1; // Context limit exceeded
    }

    UEContext* context = aligned_alloc(ALIGNMENT, sizeof(UEContext));
    if (!context) {
        pthread_rwlock_unlock(&manager->lock);
        return -2; // Memory allocation failed
    }

    strncpy(context->imsi, imsi, sizeof(context->imsi) - 1);
    context->imsi[sizeof(context->imsi) - 1] = '\0';
    context->rnti = rnti;
    context->traffic_stats = traffic_stats;

    manager->contexts[manager->current_count++] = context;
    save_context_to_db(context); // Persist new context to the database

    pthread_rwlock_unlock(&manager->lock);
    return 0; // Success
}

UEContext* get_context_by_imsi(const ContextManager* manager, const char* imsi) {
    pthread_rwlock_rdlock(&manager->lock);

    for (size_t i = 0; i < manager->current_count; ++i) {
        if (strcmp(manager->contexts[i]->imsi, imsi) == 0) {
            UEContext* context = manager->contexts[i];
            pthread_rwlock_unlock(&manager->lock);
            return context;
        }
    }

    pthread_rwlock_unlock(&manager->lock);
    return NULL; // Context not found
}

void update_traffic_stats(UEContext* context, uint32_t incoming_delta, uint32_t outgoing_delta) {
    if (context) {
        context->traffic_stats.incoming += incoming_delta;
        context->traffic_stats.outgoing += outgoing_delta;

        save_context_to_db(context); // Update the database with new stats
    }
}

void cleanup_manager(ContextManager* manager) {
    pthread_rwlock_wrlock(&manager->lock);

    for (size_t i = 0; i < manager->current_count; ++i) {
        free(manager->contexts[i]);
    }

    pthread_rwlock_unlock(&manager->lock);
    pthread_rwlock_destroy(&manager->lock);
}

// Mock implementations of database functions
void save_context_to_db(const UEContext* context) {
    // Implement actual database persistence logic here
}

int load_contexts_from_db(UEContext** contexts, size_t* count) {
    // Implement actual database loading logic here
    *count = 0;
    return 0; // Success or error code
}
