    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        SensorEvent **new_events = realloc(manager->events, new_capacity * sizeof(SensorEvent *));
        if (!new_events) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Out of memory
        }
        manager->events = new_events;
        manager->capacity = new_capacity;
    }

    manager->events[manager->count] = malloc(sizeof(SensorEvent));
    *manager->events[manager->count] = *event;

    if (!geospatial_index_add(manager->index, event)) {
        free(manager->events[manager->count]);
        pthread_mutex_unlock(&manager->lock);
        return -1; // Failed to add to geospatial index
    }

    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

