#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the structure
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRC_INDICATION_REL8_TAG[4];
        int CRCFLAG;
    } crc_info;
} NFAPI_CRC_INDICATION_PDU_T;

// Node for linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Dynamic list structure with mutex for thread safety
typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int size;
} CRCList;

// Checksum function (simple XOR checksum as an example)
int verify_checksum(uint8_t* tag, int length) {
    uint8_t checksum = 0;
    for (int i = 0; i < length; ++i) {
        checksum ^= tag[i];
    }
    return checksum == 0; // Assuming a valid checksum results in zero
}

// Initialize the CRCList
void init_crc_list(CRCList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
}

// Add an element to the CRCList
int add_to_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!verify_checksum(pdu.crc_info.CRC_INDICATION_REL8_TAG, sizeof(pdu.crc_info.CRC_INDICATION_REL8_TAG))) {
        return -1; // Invalid CRC tag
    }

    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }
    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

// Serialize the CRCList to a binary file
int serialize_crc_list(const char* filename, CRCList* list) {
    pthread_mutex_lock(&list->lock);
    FILE* file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&list->lock);
        return -1; // File opening failed
    }

    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Function to generate a random CRCFLAG
void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    srand(time(NULL));
    pdu->crc_info.CRCFLAG = rand() % 2;
}

// Example usage function
void example_usage() {
    CRCList crc_list;
    init_crc_list(&crc_list);

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = 12345678; // Example data
    pdu.RNTI = 1111;                       // Example data
    memcpy(pdu.crc_info.CRC_INDICATION_REL8_TAG, "abcd", sizeof("abcd")); // Set a dummy tag

    set_random_crcflag(&pdu);

    if (add_to_crc_list(&crc_list, pdu) == 0) {
        printf("PDU added successfully\n");
    } else {
        printf("Failed to add PDU\n");
    }

    serialize_crc_list("output.bin", &crc_list);
}

int main() {
    example_usage();
    return 0;
}
```

