    size_t count;
    size_t capacity;
    pthread_mutex_t lock; // For thread safety
} DynamicUEArray;

// Function to initialize a new MeasurementReport
MeasurementReport* create_measurement_report(int cell_id, float rsrp, float rsrq) {
