    report->CELL_ID = cell_id;
    report->RSRP = rsrp;
    report->RSRQ = rsrq;
    return report;
}

// Function to initialize a new UEContext
UEContext* create_ue_context(int ue_id, const char *rrc_state) {
    UEContext *context = (UEContext*) malloc(sizeof(UEContext));
    context->UE_ID = ue_id;
    strncpy(context->RRC_STATE, rrc_state, sizeof(context->RRC_STATE) - 1);
    context->reports = NULL;
    context->report_count = 0;
    context->capacity = 0;
    return context;
}

// Function to initialize the dynamic array
