    array->contexts = (UEContext**) malloc(INITIAL_CAPACITY * sizeof(UEContext*));
    array->count = 0;
    array->capacity = INITIAL_CAPACITY;
    return array;
}

// Helper function to resize the dynamic array
void resize_dynamic_ue_array(DynamicUEArray *array) {
    size_t new_capacity = array->capacity * 2;
    UEContext **new_contexts = (UEContext**) realloc(array->contexts, new_capacity * sizeof(UEContext*));
    if (new_contexts) {
