}

// Function to add a UE context
void add_ue_context(DynamicUEArray *array, int ue_id, const char *rrc_state) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        resize_dynamic_ue_array(array);
    }
    UEContext *context = create_ue_context(ue_id, rrc_state);
    array->contexts[array->count++] = context;
    pthread_mutex_unlock(&array->lock);
}

// Function to add a measurement report to a specific UE
void add_measurement_report(DynamicUEArray *array, int ue_id, int cell_id, float rsrp, float rsrq) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->contexts[i]->UE_ID == ue_id) {
            UEContext *context = array->contexts[i];
            if (context->report_count == context->capacity) {
                size_t new_capacity = context->capacity ? context->capacity * 2 : INITIAL_CAPACITY;
                context->reports = (MeasurementReport*) realloc(context->reports, new_capacity * sizeof(MeasurementReport));
                context->capacity = new_capacity;
            }
            MeasurementReport *report = create_measurement_report(cell_id, rsrp, rsrq);
            context->reports[context->report_count++] = *report;
            free(report);
            break;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

// Function to retrieve measurement reports for a specific UE
MeasurementReport* get_measurement_reports(DynamicUEArray *array, int ue_id, size_t *count) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->contexts[i]->UE_ID == ue_id) {
            UEContext *context = array->contexts[i];
            *count = context->report_count;
            pthread_mutex_unlock(&array->lock);
            return context->reports;
        }
    }
    pthread_mutex_unlock(&array->lock);
    *count = 0;
    return NULL;
}

// Function to free memory
void free_dynamic_ue_array(DynamicUEArray *array) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->contexts[i]->reports) {
            free(array->contexts[i]->reports);
        }
        free(array->contexts[i]);
    }
    free(array->contexts);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

// Example usage
int main() {
    DynamicUEArray *ue_array = init_dynamic_ue_array();

    add_ue_context(ue_array, 1, "Connected");
    add_measurement_report(ue_array, 1, 101, -95.0f, -12.0f);

    size_t report_count;
    MeasurementReport *reports = get_measurement_reports(ue_array, 1, &report_count);

    if (reports) {
        for (size_t i = 0; i < report_count; ++i) {
            printf("Cell ID: %d, RSRP: %.2f, RSRQ: %.2f\n", reports[i].CELL_ID, reports[i].RSRP, reports[i].RSRQ);
        }
    }

    free_dynamic_ue_array(ue_array);

    return 0;
}
```

