int read_static_configs(const char *file_path, struct in_addr **static_ips, size_t *count) {
    FILE *file = fopen(file_path, "r");
    if (!file) return -1;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        struct in_addr ip;
        inet_aton(strtok(line, ","), &ip);
        // Add to static IPs list
    }

    fclose(file);
    return 0;
}

int is_ip_in_use(struct in_addr *ip, struct in_addr **static_ips, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (memcmp(ip, &static_ips[i], sizeof(struct in_addr)) == 0)
            return 1;
    }
    return 0;
}

int generate_random_ip(struct in_addr *subnet_base, struct in_addr *subnet_mask, struct in_addr *ip) {
    struct in_addr net = { .s_addr = subnet_base->s_addr & subnet_mask->s_addr };
    unsigned int host_part = rand() % (INADDR_MAX - INADDR_MIN);
    ip->s_addr = net.s_addr + host_part;
    return 0;
}

NetworkInterfaceList* initialize_nicp_configs(const char *config_file, const struct in_addr *subnet_base,
                                              const struct in_addr *subnet_mask) {
    NetworkInterfaceList *list = malloc(sizeof(NetworkInterfaceList));
    if (!list) return NULL;

    NICPConfig *configs = calloc(MAX_INTERFACES, sizeof(NICPConfig));
    if (!configs) {
        free(list);
        return NULL;
    }

    struct in_addr *static_ips = NULL;
    size_t static_count = 0;
    read_static_configs(config_file, &static_ips, &static_count);

    srand(time(NULL)); // Seed for random IP generation
    list->count = 0;

    while (list->count < MAX_INTERFACES) {
        NICPConfig *config = &configs[list->count];

        snprintf(config->interface_id, sizeof(config->interface_id), "eth%d", list->count + 1);

        struct in_addr ip;
        if (generate_random_ip(subnet_base, subnet_mask, &ip)) continue;

        while (is_ip_in_use(&ip, static_ips, static_count)) {
            generate_random_ip(subnet_base, subnet_mask, &ip);
        }

        config->ip_address = ip;
        memcpy(&config->subnet_mask, subnet_mask, sizeof(struct in_addr));
        generate_random_ip(subnet_base, subnet_mask, &config->gateway_address);

        list->configs = configs;
        list->count++;
    }

    free(static_ips);
    return list;
}

void cleanup_network_interface_list(NetworkInterfaceList *list) {
    if (list && list->configs)
        free(list->configs);
    free(list);
}
