typedef enum {
    PDU_CRC,
    PDU_RACH
} PDU_TYPE;

typedef struct PDU_T {
    PDU_TYPE type;
    union {
        NFAPI_CRC_INDICATION_PDU_T crc_pdu;
        RACH_REQUEST_PDU_T rach_pdu;
    } data;
} PDU_T;

