}

// Mock function to generate random RACH_FLAG
int generate_random_rach_flag() {
    return rand() % 16; // Random preamble sequence length
}

// Mock function to generate a unique UE_ID
uint32_t generate_unique_ue_id(pthread_mutex_t *lock) {
    static uint32_t last_ue_id = 0;
    pthread_mutex_lock(lock);
    last_ue_id++;
    pthread_mutex_unlock(lock);
    return last_ue_id;
}

void process_pdu(PDU_T *pdu) {
    // Simulate processing
    if (pdu->type == PDU_CRC) {
        printf("Processing CRC PDU with RNTI: %u\n", pdu->data.crc_pdu.RNTI);
    } else {
        printf("Processing RACH PDU with UE_ID: %u\n", pdu->data.rach_pdu.UE_ID);
    }
}

void *async_process_pdus(void *arg) {
    PDU_T **pdus = (PDU_T **)arg;
    int count = *(int *)arg - 1; // First element is the count
    for (int i = 0; i < count; ++i) {
        process_pdu(pdus[i]);
    }
    return NULL;
}

void generate_and_process_pdu_list(int n, CompletionCallback callback) {
    pthread_t thread_id;
    int error_code = 0;

    srand(time(NULL));

    // Calculate the maximum number of PDUs that can be allocated within memory limit
    size_t pdu_size = sizeof(PDU_T);
    int max_pdus = MAX_MEMORY_USAGE / pdu_size;

    if (n > max_pdus) {
        fprintf(stderr, "Warning: Requested count exceeds memory limit. Reducing to %d.\n", max_pdus);
        n = max_pdus;
    }

    PDU_T *pdus = malloc(n * sizeof(PDU_T));
    if (!pdus) {
        error_code = 1; // Memory allocation failed
        callback(error_code);
        return;
    }

    int pdu_count = 0;
    for (int i = 0; i < n; ++i) {
        PDU_T *pdu = &pdus[i];
        if ((rand() % 2) == 0) { // Randomly choose PDU type
            pdu->type = PDU_CRC;
            pdu->data.crc_pdu.RNTI = rand();
            pdu->data.crc_pdu.RX_UE_INFORMATION_TAG = rand() % 100;
            pdu->data.crc_pdu.CRC_INDICATION_REL8_TAG = generate_random_crc_flag();
        } else {
            pdu->type = PDU_RACH;
            pdu->data.rach_pdu.CELL_ID = rand();
            pdu->data.rach_pdu.UE_ID = generate_unique_ue_id(&lock);
            int rach_flag = generate_random_rach_flag();
            snprintf(pdu->data.rach_pdu.PREAMBLE_SEQUENCE, sizeof(pdu->data.rach_pdu.PREAMBLE_SEQUENCE), "%d", rach_flag);
            pdu->data.rach_pdu.RACH_FLAG = rach_flag;
        }
        pdu_count++;
    }

    // Store the count at the beginning of the array for async processing
    pdus[0].type = PDU_CRC; // Dummy value to store the count
    ((int *)pdus)[0] = pdu_count;

    if (pthread_create(&thread_id, NULL, async_process_pdus, (void *)pdus)) {
        error_code = 2; // Thread creation failed
        free(pdus);
        callback(error_code);
        return;
    }

    pthread_detach(thread_id);

    // Wait for processing to complete or handle asynchronously
    // For simplicity, we assume it completes instantly here.
    callback(error_code);
}

// Example completion callback function
void on_completion(int error_code) {
    if (error_code == 0) {
        printf("Processing completed successfully.\n");
    } else {
        printf("Error occurred during processing: %d\n", error_code);
    }
}

int main() {
    int n = 100; // Example number of PDUs to generate
    generate_and_process_pdu_list(n, on_completion);
    return 0;
}
