#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define DEFAULT_MAX_ENTRIES 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp; // For cleanup policy
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t current_size;
    size_t max_entries;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    unsigned int rate_limit;
    time_t last_insertion_time;
    size_t retention_count; // For fixed number of entries policy
} ListManager;

ListManager* create_list_manager(size_t max_entries, unsigned int rate_limit) {
    ListManager* manager = malloc(sizeof(ListManager));
    if (!manager) {
        log_error("Memory allocation failed for list manager");
        return NULL;
    }

    manager->head = manager->tail = NULL;
    manager->current_size = 0;
    manager->max_entries = max_entries ? max_entries : DEFAULT_MAX_ENTRIES;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond_var, NULL);
    manager->rate_limit = rate_limit; // e.g., milliseconds between insertions
    manager->last_insertion_time = 0;
    manager->retention_count = manager->max_entries / 10; // Example retention policy

    return manager;
}

void log_error(const char* message) {
    // Integrate with existing logging mechanism
    fprintf(stderr, "Error: %s\n", message);
}

int compute_crc_flag(unsigned int RX_UE_INFORMATION_TAG, unsigned int RNTI) {
    // Placeholder for cryptographic hash function to determine CRCFLAG
    return (RX_UE_INFORMATION_TAG ^ RNTI) & 0xFF; // Simple XOR operation as example
}

void cleanup_list(ListManager* manager) {
    pthread_mutex_lock(&manager->lock);

    time_t now = time(NULL);
    Node* current = manager->head;
    while (current && current->next) {
        if ((now - current->timestamp > 60) || // Time-based policy, e.g., remove entries older than 1 min
            (manager->current_size > manager->retention_count)) { // Fixed retention count

            Node* to_delete = current;
            current = current->next;

            pthread_mutex_unlock(&manager->lock);
            free(to_delete); // Free memory
            log_error("Entry cleaned up based on policy");
            pthread_mutex_lock(&manager->lock);

            manager->current_size--;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void* refresh_list_async(void* arg) {
    // Placeholder function for asynchronous integration with an external data source
    ListManager* manager = (ListManager*)arg;

    while (1) {
        sleep(10); // Refresh every 10 seconds

        pthread_mutex_lock(&manager->lock);
        cleanup_list(manager);
        pthread_mutex_unlock(&manager->lock);
    }
}

int insert_entry(ListManager* manager, unsigned int RX_UE_INFORMATION_TAG, unsigned int RNTI) {
    if (manager == NULL)
        return -1;

    time_t now = time(NULL);

    // Rate limiting check
    if (now < manager->last_insertion_time + manager->rate_limit) {
        pthread_cond_wait(&manager->cond_var, &manager->lock);
    }

    pthread_mutex_lock(&manager->lock);

    cleanup_list(manager);  // Clean up before insertion

    if (manager->current_size >= manager->max_entries) {
        log_error("List is full");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed for node");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;

    // Calculate CRC flag
    unsigned char crc_flag = compute_crc_flag(RX_UE_INFORMATION_TAG, RNTI);
    memcpy(new_node->data.CRC_INDICATION_REL8_TAG, &crc_flag, sizeof(crc_flag));

    new_node->timestamp = now;
    new_node->next = NULL;

    if (manager->tail) {
        manager->tail->next = new_node;
    } else {
        manager->head = new_node;
    }

    manager->tail = new_node;
    manager->current_size++;
    manager->last_insertion_time = now;

    pthread_cond_signal(&manager->cond_var);
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void destroy_list_manager(ListManager* manager) {
    if (!manager)
        return;

    Node* current = manager->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond_var);
    free(manager);
}

int main() {
    ListManager* manager = create_list_manager(0, 100); // Default max size and rate limit of 100 ms
    if (!manager) return -1;

    // Start the asynchronous refresh thread
    pthread_t refresh_thread;
    if (pthread_create(&refresh_thread, NULL, refresh_list_async, manager)) {
        log_error("Failed to create async refresh thread");
    }

    // Example usage
    insert_entry(manager, 12345, 67890);

    destroy_list_manager(manager);

    return 0;
}
