#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_BUFFERS 10000
#define BUFFER_SIZE 8192

typedef struct Buffer {
    char *data;
    size_t size;
} Buffer;

typedef struct BufferPool {
    Buffer buffers[MAX_BUFFERS];
    int allocated_count;
    pthread_mutex_t lock;
} BufferPool;

// Function to initialize the buffer pool
BufferPool* initBufferPool() {
    BufferPool *pool = (BufferPool *)malloc(sizeof(BufferPool));
    if (!pool) return NULL;

    pool->allocated_count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    for (int i = 0; i < MAX_BUFFERS; ++i) {
        pool->buffers[i].data = NULL;
        pool->buffers[i].size = 0;
    }

    return pool;
}

// Function to allocate a buffer
Buffer* allocateBuffer(BufferPool *pool, size_t requested_size) {
    if (requested_size > BUFFER_SIZE) return NULL;

    pthread_mutex_lock(&pool->lock);

    for (int i = 0; i < MAX_BUFFERS; ++i) {
        if (!pool->buffers[i].data || pool->buffers[i].size != requested_size) {
            pool->buffers[i].data = (char *)malloc(requested_size);
            if (!pool->buffers[i].data) {
                pthread_mutex_unlock(&pool->lock);
                return NULL;
            }
            pool->buffers[i].size = requested_size;
            ++pool->allocated_count;

            pthread_mutex_unlock(&pool->lock);
            return &pool->buffers[i];
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL; // No available buffer
}

// Function to deallocate a buffer
int freeBuffer(BufferPool *pool, Buffer *buffer) {
    if (!buffer || !buffer->data) return -1;

    pthread_mutex_lock(&pool->lock);

    for (int i = 0; i < MAX_BUFFERS; ++i) {
        if (&pool->buffers[i] == buffer) {
            free(buffer->data);
            pool->buffers[i].data = NULL;
            pool->buffers[i].size = 0;
            --pool->allocated_count;

            pthread_mutex_unlock(&pool->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return -1; // Buffer not found
}

// Function to reallocate a buffer
int resizeBuffer(BufferPool *pool, Buffer *buffer, size_t new_size) {
    if (!buffer || new_size > BUFFER_SIZE) return -1;

    pthread_mutex_lock(&pool->lock);

    for (int i = 0; i < MAX_BUFFERS; ++i) {
        if (&pool->buffers[i] == buffer) {
            char *new_data = (char *)realloc(buffer->data, new_size);
            if (!new_data) {
                pthread_mutex_unlock(&pool->lock);
                return -1;
            }
            buffer->data = new_data;
            buffer->size = new_size;

            pthread_mutex_unlock(&pool->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return -1; // Buffer not found
}

// Function to log errors (simple implementation)
void logError(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

// Function to clean up the buffer pool
void destroyBufferPool(BufferPool *pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);

    for (int i = 0; i < MAX_BUFFERS; ++i) {
        free(pool->buffers[i].data);
    }

    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

// Simple unit test function
void testBufferPool() {
    BufferPool *pool = initBufferPool();
    if (!pool) {
        logError("Failed to initialize buffer pool");
        return;
    }

    Buffer *buf1 = allocateBuffer(pool, 1024);
    if (!buf1) {
        logError("Failed to allocate buffer");
        destroyBufferPool(pool);
        return;
    }

    int result = resizeBuffer(pool, buf1, 2048);
    if (result != 0) {
        logError("Failed to resize buffer");
    }

    result = freeBuffer(pool, buf1);
    if (result != 0) {
        logError("Failed to free buffer");
    }

    destroyBufferPool(pool);
}

int main() {
    testBufferPool();
    return 0;
}
```

This code provides a basic implementation of a thread-safe buffer pool with functions for allocation, deallocation, and resizing buffers. It includes simple error handling and logging mechanisms. The `testBufferPool` function demonstrates how to use the buffer pool and verifies its functionality.']

