#include <stdio.h>
#include <stdlib.h>
import <pthread.h>

#define MAX_PCI 503 // Maximum PCI value in LTE

typedef struct {
    int pci;
    float rsrp; 
    unsigned int qos_profile_id; 
} PciInfo;

typedef struct Node {
    PciInfo data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} PciList;

// Assume these are defined elsewhere
extern int fetch_qos_profile(unsigned int profile_id);
extern void log_error(const char* message);

PciList* create_list() {
    PciList* list = (PciList*)malloc(sizeof(PciList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(PciList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_valid_pci(int pci) {
    return pci >= 0 && pci <= MAX_PCI;
}

int is_valid_qos_profile(unsigned int profile_id) {
    // Simulate external service call and validation
    return fetch_qos_profile(profile_id) == 1;
}

void add_pci_info(PciList* list, PciInfo info) {
    if (!is_valid_pci(info.pci)) {
        log_error("Invalid PCI");
        return;
    }

    pthread_mutex_lock(&list->lock);

    int valid_qos = is_valid_qos_profile(info.qos_profile_id);
    if (!valid_qos) {
        log_error("Invalid QoS profile ID");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed for new node");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = info;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
}

void serialize_list(const char* filename, PciList* list) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_error("Failed to open file for serialization");
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(PciInfo), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

void deserialize_list(const char* filename, PciList* list) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_error("Failed to open file for deserialization");
        return;
    }

    pthread_mutex_lock(&list->lock);

    while (fread(&(PciInfo){0}, sizeof(PciInfo), 1, file)) {
        add_pci_info(list, *(PciInfo*)malloc(sizeof(PciInfo)));
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    PciList* list = create_list();

    // Add PCI information as needed
    PciInfo info1 = {123, -95.0f, 10};
    add_pci_info(list, info1);

    // Serialize and deserialize example
    serialize_list("pci_data.bin", list);
    PciList* new_list = create_list();
    deserialize_list("pci_data.bin", new_list);

    free_list(list);
    free_list(new_list);

    return 0;
}
```

### Key Points:
