#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a structure for a message object
typedef struct {
    int sender_id;
    time_t timestamp;
    char *payload;
} Message;

// Node for the linked list to store messages
typedef struct Node {
    Message *message;
    struct Node *next;
} Node;

// Messaging system structure
typedef struct {
    Node *head;
    pthread_mutex_t lock; // Mutex for thread safety
} MessageSystem;

// Function prototypes
MessageSystem* create_message_system();
void destroy_message_system(MessageSystem *system);
int add_message(MessageSystem *system, int sender_id, time_t timestamp, const char *payload);
int update_message(MessageSystem *system, int sender_id, time_t new_timestamp, const char *new_payload);
Node* get_messages_in_range(MessageSystem *system, time_t start_time, time_t end_time);

// Create a new message system
MessageSystem* create_message_system() {
    MessageSystem *system = (MessageSystem *)malloc(sizeof(MessageSystem));
    if (!system) return NULL;
    system->head = NULL;
    pthread_mutex_init(&system->lock, NULL);
    return system;
}

// Destroy the message system and free memory
void destroy_message_system(MessageSystem *system) {
    Node *current = system->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->message->payload);
        free(current->message);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&system->lock);
    free(system);
}

// Add a new message to the system
int add_message(MessageSystem *system, int sender_id, time_t timestamp, const char *payload) {
    pthread_mutex_lock(&system->lock);

    Message *new_message = (Message *)malloc(sizeof(Message));
    if (!new_message) {
        pthread_mutex_unlock(&system->lock);
        return -1;
    }
    new_message->sender_id = sender_id;
    new_message->timestamp = timestamp;
    new_message->payload = strdup(payload);
    if (!new_message->payload) {
        free(new_message);
        pthread_mutex_unlock(&system->lock);
        return -1;
    }

    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        free(new_message->payload);
        free(new_message);
        pthread_mutex_unlock(&system->lock);
        return -1;
    }
    new_node->message = new_message;
    new_node->next = system->head;
    system->head = new_node;

    pthread_mutex_unlock(&system->lock);
    return 0;
}

// Update an existing message by sender ID
int update_message(MessageSystem *system, int sender_id, time_t new_timestamp, const char *new_payload) {
    pthread_mutex_lock(&system->lock);

    Node *current = system->head;
    while (current != NULL) {
        if (current->message->sender_id == sender_id) {
            free(current->message->payload);
            current->message->timestamp = new_timestamp;
            current->message->payload = strdup(new_payload);
            pthread_mutex_unlock(&system->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&system->lock);
    return -1; // Message not found
}

// Retrieve messages within a specified time range
Node* get_messages_in_range(MessageSystem *system, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&system->lock);

    Node *dummy = (Node *)malloc(sizeof(Node));
    if (!dummy) {
        pthread_mutex_unlock(&system->lock);
        return NULL;
    }
    dummy->next = NULL;

    Node **tail = &dummy->next;

    Node *current = system->head;
    while (current != NULL) {
        if (current->message->timestamp >= start_time && current->message->timestamp <= end_time) {
            Node *new_node = (Node *)malloc(sizeof(Node));
            if (!new_node) {
                // Free allocated nodes in case of error
                Node *temp;
                while (*tail != NULL) {
                    temp = *tail;
                    *tail = (*tail)->next;
                    free(temp);
                }
                free(dummy);
                pthread_mutex_unlock(&system->lock);
                return NULL;
            }
            new_node->message = current->message; // Shallow copy
            new_node->next = NULL;
            *tail = new_node;
            tail = &new_node->next;
        }
        current = current->next;
    }

    Node *result = dummy->next;
    free(dummy);
    pthread_mutex_unlock(&system->lock);

    return result;
}

// Example usage
int main() {
    MessageSystem *system = create_message_system();
    if (!system) return 1;

    add_message(system, 1, time(NULL), "Hello");
    add_message(system, 2, time(NULL) - 100, "World");

    Node *messages = get_messages_in_range(system, time(NULL) - 200, time(NULL));
    for (Node *n = messages; n != NULL; n = n->next) {
        printf("Sender: %d, Payload: %s\n", n->message->sender_id, n->message->payload);
    }

    destroy_message_system(system);

    return 0;
}
```

This code implements a basic C-based messaging system with thread-safe operations for adding, updating, and retrieving messages. It uses a linked list to store messages and a mutex for concurrency control. The `get_messages_in_range` function retrieves messages within a specified time range. Memory management is handled carefully to avoid leaks, and the system can be extended to integrate with external services or handle more complex scenarios.']

