#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <curl/curl.h>

#define INITIAL_SIZE 1000
#define MAX_RETRIES 5
#define BACKOFF_FACTOR 2

typedef struct {
    int valid; // Simplified representation of RX_UE_INFORMATION_TAG
    unsigned long rnti;
    struct {
        int crcflag;
    } crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t size;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *data;
    pthread_mutex_t lock; // For thread safety
} CRCList;

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    // Callback function for libcurl to handle response data
    char **response = (char **)userdata;
    *response = realloc(*response, strlen(ptr) + 1);
    strcat(*response, ptr);
    return size * nmemb;
}

int get_crcflag_from_api(int *crcflag) {
    CURL *curl;
    CURLcode res;
    char *response = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/api/crcflags");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

        int retries = 0;
        while (retries < MAX_RETRIES) {
            res = curl_easy_perform(curl);
            if(res == CURLE_OK) {
                // Parse the response to extract crcflag
                *crcflag = rand() % 2; // Placeholder for actual parsing logic
                free(response);
                return 0;
            } else {
                retries++;
                sleep(pow(BACKOFF_FACTOR, retries)); // Exponential backoff
            }
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    if (response) {
        free(response);
    }
    return -1; // Error retrieving crcflag from API
}

void resize_crc_list(CRCList *list, size_t new_capacity) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data) {
        list->capacity = new_capacity;
        list->data = new_data;
    }
    pthread_mutex_unlock(&list->lock);
}

int populate_crc_list(CRCList *list, size_t num_entries) {
    if (!list || num_entries == 0) return -1;

    if (num_entries > list->capacity) {
        resize_crc_list(list, num_entries > list->capacity * 2 ? num_entries : list->capacity * 2);
    }

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < num_entries && i < list->capacity; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.valid = rand() % 2; // Simplified valid check
        pdu.rnti = rand();

        int crcflag = -1;
        if (get_crcflag_from_api(&crcflag) == 0) {
            pdu.crc_indication_rel8_tag.crcflag = crcflag;
        } else {
            fprintf(stderr, "Error retrieving CRC flag from API.\n");
            pdu.crc_indication_rel8_tag.crcflag = rand() % 2; // Default/fallback value
        }

        list->data[i] = pdu;
    }

    list->size = num_entries;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void init_crc_list(CRCList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->capacity = INITIAL_SIZE;
    list->data = malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
}

void free_crc_list(CRCList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
}

int main() {
    CRCList list;
    init_crc_list(&list);

    populate_crc_list(&list, 10000); // Populate with up to 10,000 entries

    for (size_t i = 0; i < list.size && i < 10; ++i) { // Print first 10 entries
        printf("Entry %zu: Valid=%d, RNTI=%lu, CRCFLAG=%d\n", i + 1,
               list.data[i].valid, list.data[i].rnti, 
               list.data[i].crc_indication_rel8_tag.crcflag);
    }

    free_crc_list(&list);
    return 0;
}
```

