#define MAX_RNTI 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int validate_rnti(int rnti) {
    return (rnti >= MIN_RNTI && rnti <= MAX_RNTI);
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_array(int num_elements, int *error_status) {
    if (num_elements > MAX_ELEMENTS || num_elements <= 0) {
        *error_status = -1; // Error: Invalid number of elements
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        *error_status = -2; // Error: Memory allocation failed
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_elements; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 256;
        do {
            array[i].RNTI = rand() % (MAX_RNTI + 1);
        } while (!validate_rnti(array[i].RNTI));

        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i].CRCFLAG = rand() % 2; // Randomly set to 0 or 1
    }

    *error_status = 0; // Success
    return array;
}

void free_nfa_crc_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}
```

### Explanation:

- **Structure Definition**: Defines the structure `NFAPI_CRC_INDICATION_PDU_T` with required fields.

- **Validation Function**: Implements a function to validate RNTI values.

- **Main Function (`create_nfa_crc_array`)**:
  - Validates the number of elements against constraints.
  - Allocates memory for the array and checks if allocation is successful.
  - Populates each structure in the array with random but valid data, ensuring `RNTI` falls within a valid range.
  - Returns an error status indicating success or specific failure reasons.

- **Memory Cleanup**: Provides a function to free allocated memory, preventing leaks. 

