import hashlib
import os
from concurrent.futures import ThreadPoolExecutor, as_completed
from queue import Queue
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)

def md5_chunked(file_path, chunk_size=8192):
    """Calculate MD5 hash of a file in chunks."""
    try:
        hasher = hashlib.md5()
        with open(file_path, 'rb') as f:
            while chunk := f.read(chunk_size):
                hasher.update(chunk)
        return hasher.hexdigest()
    except FileNotFoundError:
        logging.error(f"File not found: {file_path}")
    except IOError as e:
        logging.error(f"I/O error({e.errno}): {e.strerror} - {file_path}")

def process_file(file_queue, results, max_retries=5):
    """Process files from the queue and compute their MD5 hashes."""
    while not file_queue.empty():
        file_path = file_queue.get()
        retries = 0
        success = False
        while retries < max_retries and not success:
            result = md5_chunked(file_path)
            if result is not None:
                results[file_path] = result
                success = True
            else:
                retries += 1
                wait_time = min(2 ** retries, 60)  # Exponential backoff
                logging.warning(f"Retrying {file_path} in {wait_time}s (Attempt {retries})")
                time.sleep(wait_time)
        if not success:
            results[file_path] = None

def calculate_md5_files(file_paths, num_workers=4):
    """Calculate MD5 hashes for multiple files using concurrent workers."""
    file_queue = Queue()
    results = {}

    # Add file paths to the queue
    for path in file_paths:
        file_queue.put(path)

    with ThreadPoolExecutor(max_workers=num_workers) as executor:
        futures = [executor.submit(process_file, file_queue, results) for _ in range(num_workers)]

        for future in as_completed(futures):
            try:
                future.result()
            except Exception as e:
                logging.error(f"Error processing files: {e}")

    return results

# Example usage
if __name__ == "__main__":
    paths = ["file1.txt", "file2.txt", "file3.txt"]  # Replace with actual file paths
    md5_results = calculate_md5_files(paths, num_workers=4)
    for path, md5_hash in md5_results.items():
        if md5_hash:
            logging.info(f"MD5 of {path}: {md5_hash}")
        else:
            logging.error(f"Failed to compute MD5 for {path}")
```']

