    array->size = 0;
    array->capacity = 10; // Initial capacity
    array->records = (LTE_PHY_TX_RECORD *)malloc(array->capacity * sizeof(LTE_PHY_TX_RECORD));
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->records);
    free(array);
}

int is_power_level_valid(int power_level) {
    return power_level >= PERMISSIBLE_POWER_LEVEL_MIN && power_level <= PERMISSIBLE_POWER_LEVEL_MAX;
}

void resize_if_needed(DynamicArray *array) {
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_PHY_TX_RECORD *new_records = (LTE_PHY_TX_RECORD *)malloc(new_capacity * sizeof(LTE_PHY_TX_RECORD));
        for (size_t i = 0; i < array->size; i++) {
            new_records[i] = array->records[i];
        }
        free(array->records);
        array->records = new_records;
        array->capacity = new_capacity;
    }
}

void add_record(DynamicArray *array, LTE_PHY_TX_RECORD record) {
    if (!is_power_level_valid(record.tx_power_level)) {
        printf("Invalid power level: %d\n", record.tx_power_level);
        return;
    }

    pthread_mutex_lock(&array->lock);

    resize_if_needed(array);
    array->records[array->size++] = record;

    pthread_mutex_unlock(&array->lock);
}

void update_record(DynamicArray *array, size_t index, LTE_PHY_TX_RECORD new_record) {
    if (!is_power_level_valid(new_record.tx_power_level)) {
        printf("Invalid power level: %d\n", new_record.tx_power_level);
        return;
    }

    pthread_mutex_lock(&array->lock);

    if (index < array->size) {
        array->records[index] = new_record;
    } else {
        printf("Index out of bounds: %zu\n", index);
    }

    pthread_mutex_unlock(&array->lock);
}

void iterate_and_check(DynamicArray *array, int (*condition)(RF_CHANNEL_CONFIG)) {
