```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_LIST_T;

NFAPI_CRC_INDICATION_LIST_T* create_list() {
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) return NULL;

    list->array = calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    if (list) {
        free(list->array);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_pdu(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failure
        }
        list->array = new_array;
        list->capacity = new_capacity;
    }

    list->array[list->size++] = pdu;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_pdu(NFAPI_CRC_INDICATION_LIST_T *list, size_t index, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (index >= list->size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Out of bounds
    }

    list->array[index] = pdu;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_pdu(NFAPI_CRC_INDICATION_LIST_T *list, size_t index) {
    pthread_mutex_lock(&list->lock);

    if (index >= list->size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Out of bounds
    }

    memmove(&list->array[index], &list->array[index + 1], (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size--;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void handle_external_data_source(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Simulate periodic updates from external data source
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = rand(), .RNTI = rand(), .CRC_INDICATION_REL8_TAG = rand() };

        if (add_pdu(list, pdu) != 0) {
            // Handle error (e.g., log or retry)
        }

        usleep(100000); // Sleep for 100 ms
    }
}

int main() {
    NFAPI_CRC_INDICATION_LIST_T *list = create_list();
    if (!list) return EXIT_FAILURE;

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, (void *(*)(void *))handle_external_data_source, list) != 0) {
        destroy_list(list);
        return EXIT_FAILURE;
    }

    // Simulate other operations
    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 2, .CRC_INDICATION_REL8_TAG = 3 };
    add_pdu(list, pdu);

    pthread_join(thread_id, NULL);
    destroy_list(list);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: The use of `pthread_mutex_t` ensures that concurrent access to the dynamic array is thread-safe.
- **Dynamic Memory Management**: The list dynamically resizes when necessary, minimizing fragmentation and optimizing memory usage.
- **Error Handling**: Functions return error codes for invalid operations, such as out-of-bounds access or memory allocation failures.
- **Concurrency**: A separate thread simulates periodic updates from an external data source, demonstrating how the system can handle concurrent operations.']

