    char ip_config[64]; // Supports both IPv4 and IPv6
    char subnet_mask[64]; // Supports both IPv4 and IPv6
} NIC;

// Custom memory pool structure
typedef struct MemoryPool {
    size_t block_size;
    void *pool;
    size_t total_blocks;
    pthread_mutex_t lock;
} MemoryPool;

// JSON Object Structure
typedef struct {
    char RX_UE_INFORMATION_TAG[64];
    unsigned int RNTI;
    char CRC_INDICATION_REL8_TAG[64];
    unsigned int CRCFLAG;
} JSONObject;

MemoryPool *initialize_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    mp->block_size = block_size;
    mp->total_blocks = total_blocks;
    mp->pool = malloc(block_size * total_blocks);
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

void *allocate_from_pool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (!mp || !mp->pool) {
        pthread_mutex_unlock(&mp->lock);
        return NULL;
    }
    void *block = mp->pool;
    mp->pool = (char *)mp->pool + mp->block_size;
    pthread_mutex_unlock(&mp->lock);
    return block;
}

typedef struct {
    NIC **nics;
    size_t count;
    pthread_rwlock_t lock;
} NICManager;

NICManager *create_nic_manager(size_t initial_capacity) {
