    manager->nics = malloc(initial_capacity * sizeof(NIC *));
    manager->count = 0;
    pthread_rwlock_init(&manager->lock, NULL);
    return manager;
}

void destroy_nic_manager(NICManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->nics[i]);
    }
    free(manager->nics);
    pthread_rwlock_destroy(&manager->lock);
    free(manager);
}

int add_nic(NICManager *manager, NIC *nic) {
    pthread_rwlock_wrlock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity ? 2 * manager->capacity : 1;
        NIC **new_array = realloc(manager->nics, new_capacity * sizeof(NIC *));
        if (!new_array) {
            pthread_rwlock_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->nics = new_array;
        manager->capacity = new_capacity;
    }
    manager->nics[manager->count++] = nic;
    pthread_rwlock_unlock(&manager->lock);
    return 0;
}

int remove_nic(NICManager *manager, size_t index) {
    pthread_rwlock_wrlock(&manager->lock);
    if (index >= manager->count) {
        pthread_rwlock_unlock(&manager->lock);
        return -1; // Invalid index
    }
    free(manager->nics[index]);
    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->nics[i] = manager->nics[i + 1];
    }
    --manager->count;
    pthread_rwlock_unlock(&manager->lock);
    return 0;
}

JSONObject *create_json_object(const char *rx_ue_tag, unsigned int rnti, const char *crc_tag) {
    JSONObject *obj = malloc(sizeof(JSONObject));
    if (!obj) return NULL;
    strncpy(obj->RX_UE_INFORMATION_TAG, rx_ue_tag, sizeof(obj->RX_UE_INFORMATION_TAG) - 1);
    obj->RNTI = rnti;
    strncpy(obj->CRC_INDICATION_REL8_TAG, crc_tag, sizeof(obj->CRC_INDICATION_REL8_TAG) - 1);
    obj->CRCFLAG = rand() % 256; // Random CRC flag
    return obj;
}

char *json_object_to_string(const JSONObject *obj) {
    if (!obj) return NULL;

    json_t *root = json_object();
    json_object_set_new(root, "RX_UE_INFORMATION_TAG", json_string(obj->RX_UE_INFORMATION_TAG));
    json_object_set_new(root, "RNTI", json_integer(obj->RNTI));
    json_object_set_new(root, "CRC_INDICATION_REL8_TAG", json_string(obj->CRC_INDICATION_REL8_TAG));
    json_object_set_new(root, "CRCFLAG", json_integer(obj->CRCFLAG));

    char *json_str = json_dumps(root, JSON_ENCODE_ANY);
    json_decref(root);
    return json_str;
}

JSONObject *create_json_from_string(const char *json_str) {
    if (!json_str) return NULL;

    json_error_t error;
    json_t *root = json_loads(json_str, 0, &error);
    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return NULL;
    }

    JSONObject *obj = malloc(sizeof(JSONObject));
    if (!obj) {
        json_decref(root);
        return NULL;
    }

    json_unpack_ex(root, &error,
                   0,
                   "{s:s, s:i, s:s, s:i}",
                   "RX_UE_INFORMATION_TAG", &obj->RX_UE_INFORMATION_TAG,
                   "RNTI", &obj->RNTI,
                   "CRC_INDICATION_REL8_TAG", &obj->CRC_INDICATION_REL8_TAG,
                   "CRCFLAG", &obj->CRCFLAG);

    json_decref(root);
    return obj;
}

// Example usage
int main() {
    MemoryPool *mp = initialize_memory_pool(sizeof(NIC), 100);

    NICManager *manager = create_nic_manager(10);

    NIC *nic1 = allocate_from_pool(mp);
    strncpy(nic1->mac_address, "00:1A:2B:3C:4D:5E", sizeof(nic1->mac_address));
    strcpy(nic1->ip_config, "192.168.0.1");
    strcpy(nic1->subnet_mask, "255.255.255.0");

    add_nic(manager, nic1);

    JSONObject *json_obj = create_json_object("Tag1", 1234, "CRC_Tag");
    char *json_str = json_object_to_string(json_obj);
    printf("%s\n", json_str);
    free(json_str);

    JSONObject *parsed_obj = create_json_from_string(json_str);
    if (parsed_obj) {
        // Use parsed_obj
        free(parsed_obj);
    }

    destroy_memory_pool(mp);
    destroy_nic_manager(manager);

    return 0;
}
```

### Key Design Choices:
1. **Thread Safety**: Used `pthread_rwlock_t` for read-write locks in NICManager to allow concurrent reads and exclusive writes.
2. **Memory Pool**: Implemented a custom memory pool to reduce fragmentation and improve allocation speed, essential under high-load conditions.
3. **Dynamic Array**: Chose dynamic array for NICs due to efficient random access, with resizing strategy doubling the capacity when needed.
4. **JSON Handling**: Used `jansson` library for JSON operations, ensuring robust parsing and serialization.
5. **Error Handling**: Incorporated error checks for memory allocation failures and invalid indices.
6. **Modularity**: Structured code into functions for initialization, management, and cleanup to facilitate future updates.

This implementation balances thread safety, performance, and maintainability while being scalable for high-performance network device management systems.']

