['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAX_SESSIONS 1000
#define MIN_RNTI 1
#define MAX_RNTI 65535

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Session {
    NFAPI_CRC_INDICATION_PDU_T* pduArray;
    size_t count;
    size_t capacity;
} Session;

static Session* sessionPool[MAX_SESSIONS];
static int activeSessions = 0;
static const size_t initialCapacity = 10;

void initializeSession(Session* session, size_t count) {
    session->pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!session->pduArray) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    session->count = 0;
    session->capacity = initialCapacity;

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &session->pduArray[i];
        pdu->RX_UE_INFORMATION_TAG = i + 1; // Unique tag
        pdu->RNTI = MIN_RNTI + (rand() % (MAX_RNTI - MIN_RNTI + 1)); // Valid RNTI range
        pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
    }
}

void resizeSession(Session* session, size_t newCount) {
    if (newCount > session->capacity) {
        size_t newSize = session->capacity * 2;
        while (newSize < newCount) {
            newSize *= 2;
        }
        NFAPI_CRC_INDICATION_PDU_T* newArray = realloc(session->pduArray, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newArray) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        session->pduArray = newArray;
        session->capacity = newSize;
    }
}

Session* allocateSession(size_t count) {
    if (activeSessions >= MAX_SESSIONS) {
        fprintf(stderr, "Maximum number of sessions reached\n");
        return NULL;
    }

    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (!sessionPool[i]) {
            sessionPool[i] = malloc(sizeof(Session));
            if (!sessionPool[i]) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
            initializeSession(sessionPool[i], count);
            activeSessions++;
            return sessionPool[i];
        }
    }

    return NULL;
}

void freeAllSessions() {
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (sessionPool[i]) {
            free(sessionPool[i]->pduArray);
            free(sessionPool[i]);
            sessionPool[i] = NULL;
        }
    }
    activeSessions = 0;
}

void cleanupSession(Session* session) {
    if (session) {
        free(session->pduArray);
        session->pduArray = NULL;
        free(session);
    }
}

// Example usage
int main() {
    size_t numPDUs = 20;

    // Allocate a new session
    Session* session = allocateSession(numPDUs);
    if (session) {
        printf("Allocated session with %zu PDUs\n", session->count);

        // Resize session to add more PDUs
        resizeSession(session, numPDUs * 2);
        printf("Resized session to %zu capacity\n", session->capacity);

        // Free all sessions when done
        freeAllSessions();
    }

    return 0;
}
