#define MAX_STRUCTURES 10000

// Global variables for thread safety
NFAPI_CRC_INDICATION_PDU_T* nfaPduArray = NULL;
size_t arraySize = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initializeNFAPIDynamicList(size_t numStructures) {
    if (numStructures > MAX_STRUCTURES || numStructures == 0) {
        fprintf(stderr, "Invalid number of structures requested.\n");
        return;
    }

    pthread_mutex_lock(&mutex);

    nfaPduArray = realloc(nfaPduArray, numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaPduArray) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    for (size_t i = 0; i < numStructures; ++i) {
        nfaPduArray[i].RX_UE_INFORMATION_TAG = rand(); // Random value
        nfaPduArray[i].RNTI = rand() % 10000; // Example RNTI generation logic

        // Set CRCFLAG randomly to 0 or 1
        nfaPduArray[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    arraySize = numStructures;
    pthread_mutex_unlock(&mutex);
}

void verifyCRCIndicationTags(void) {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < arraySize; ++i) {
        if (nfaPduArray[i].CRC_INDICATION_REL8_TAG.CRCFLAG > 1 || nfaPduArray[i].CRC_INDICATION_REL8_TAG.CRCFLAG < 0) {
            fprintf(stderr, "Verification failed for structure %zu\n", i);
        }
    }

    pthread_mutex_unlock(&mutex);
}

void cleanupNFAPIDynamicList(void) {
    pthread_mutex_lock(&mutex);

    free(nfaPduArray);
    nfaPduArray = NULL;
    arraySize = 0;

    pthread_mutex_unlock(&mutex);
}

int main() {
    // Seed the random number generator
    srand((unsigned int)time(NULL));

    initializeNFAPIDynamicList(5000); // Example call with 5000 structures

    verifyCRCIndicationTags(); // Verify CRC_INDICATION_REL8_TAG

    cleanupNFAPIDynamicList(); // Clean up allocated memory

    return 0;
}
