    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t mutex;
    FILE* log_file;
} ThreadSafeLinkedList;

ThreadSafeLinkedList* create_list() {
    ThreadSafeLinkedList* list = (ThreadSafeLinkedList*)malloc(sizeof(ThreadSafeLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->list->mutex, NULL);
    list->log_file = fopen("list_operations.log", "a");
    if (!list->log_file) {
        free(list);
        return NULL;
    }
    return list;
}

void log_operation(const char* operation) {
    if (current_list && current_list->log_file) {
        pthread_mutex_lock(&current_list->mutex);
        fprintf(current_list->log_file, "%s\n", operation);
        fflush(current_list->log_file);
        pthread_mutex_unlock(&current_list->mutex);
    }
}

void add_node(ThreadSafeLinkedList* list) {
    if (!list || list->size >= MAX_LIST_SIZE) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data.RX_UE_INFORMATION_TAG = rand() % 10000;
    new_node->data.RNTI = rand() % 65535;
    new_node->data.CRC_INDICATION_REL8_TAG = rand() % 256;
    new_node->data.CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG

    pthread_mutex_lock(&list->mutex);
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    log_operation("Node added");
    pthread_mutex_unlock(&list->mutex);

    free(new_node); // Free immediately to avoid memory leak
}

void update_crcflag(ThreadSafeLinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        current->data.CRCFLAG = (rand() % 2) ? 1 : 0; // Update CRCFLAG
        current = current->next;
    }
    log_operation("CRCFLAG updated");
    pthread_mutex_unlock(&list->mutex);
}

void clear_list(ThreadSafeLinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->size = 0;
    log_operation("List cleared");
    pthread_mutex_unlock(&list->mutex);
}

void iterate_list(ThreadSafeLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        callback(&current->data);
        current = current->next;
    }
    log_operation("List iteration");
    pthread_mutex_unlock(&list->mutex);
}

void free_list(ThreadSafeLinkedList* list) {
    if (!list) return;

    clear_list(list);
    fclose(list->log_file);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int main() {
    srand(time(NULL));

    ThreadSafeLinkedList* list = create_list();
    if (!list) {
        printf("Failed to create list\n");
        return 1;
    }

    for (int i = 0; i < MAX_LIST_SIZE + 10; ++i) {
        add_node(list);
    }

    update_crcflag(list);

    iterate_list(list, [](NFAPI_CRC_INDICATION_PDU_T* data) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n",
               data->RX_UE_INFORMATION_TAG, data->RNTI, data->CRCFLAG);
    });

    clear_list(list);

    free_list(list);

    return 0;
}
