int is_unique_rnti(RNTICache* cache, int rnti) {
    for (size_t i = 0; i < cache->size; ++i) {
        if (cache->rntis[i] == rnti) return 0;
    }
    return 1;
}

void add_rnti(RNTICache* cache, int rnti) {
    if (cache->size >= cache->capacity) {
        cache->capacity *= 2;
        cache->rntis = (int*)realloc(cache->rntis, cache->capacity * sizeof(int));
    }
    cache->rntis[cache->size++] = rnti;
}

