#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/resource.h>
#include <pthread.h>

// Assuming these structures are defined somewhere in your codebase
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;  // 0 or 1 for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    void *memory_pool;
    size_t pool_size;
    size_t element_size;
    size_t elements_in_use;
    pthread_mutex_t lock;
} MemoryPool;

// Function to initialize the memory pool
int init_memory_pool(MemoryPool *pool, size_t pool_size, size_t element_size) {
    pool->memory_pool = malloc(pool_size);
    if (!pool->memory_pool) return -1;
    pool->pool_size = pool_size;
    pool->element_size = element_size;
    pool->elements_in_use = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return 0;
}

// Function to allocate an element from the memory pool
void *allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->elements_in_use * pool->element_size >= pool->pool_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;  // Pool exhausted
    }
    void *ptr = (char *)pool->memory_pool + pool->elements_in_use * pool->element_size;
    pool->elements_in_use++;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Function to free the memory pool
void free_memory_pool(MemoryPool *pool) {
    if (pool->memory_pool) free(pool->memory_pool);
    pthread_mutex_destroy(&pool->lock);
}

// Function to get current resident set size
size_t get_rss() {
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    return usage.ru_maxrss;  // Resource usage in kilobytes
}

// Main function to generate the NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *generate_nfa_pi_crc_indications(size_t n) {
    MemoryPool pool;
    if (init_memory_pool(&pool, sizeof(NFAPI_CRC_INDICATION_PDU_T) * n, sizeof(NFAPI_CRC_INDICATION_PDU_T)) != 0) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *result = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result) {
        free_memory_pool(&pool);
        fprintf(stderr, "Failed to allocate result array\n");
        return NULL;
    }

    time_t start_time = time(NULL);
    size_t initial_rss = get_rss();

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)allocate_from_pool(&pool);
        if (!pdu) {
            fprintf(stderr, "Memory pool exhausted\n");
            free(result);
            free_memory_pool(&pool);
            return NULL;
        }

        // Custom parsing logic for UE information
        pdu->RX_UE_INFORMATION_TAG = i;  // Example assignment
        pdu->RNTI = i + 1;               // Example assignment
        pdu->CRC_INDICATION_REL8_TAG = i + 2;  // Example assignment

        // Randomly set CRCFLAG
        srand(time(NULL) ^ ((intptr_t)pdu << 16));
        pdu->CRCFLAG = rand() % 2;

        result[i] = *pdu;
    }

    size_t final_rss = get_rss();
    time_t end_time = time(NULL);

    printf("Time taken: %ld seconds\n", end_time - start_time);
    printf("Initial RSS: %zu KB, Final RSS: %zu KB\n", initial_rss, final_rss);

    free_memory_pool(&pool);
    return result;
}

int main() {
    size_t num_pdus = 1000;  // Example number of PDUs to generate
    NFAPI_CRC_INDICATION_PDU_T *pdus = generate_nfa_pi_crc_indications(num_pdus);
    if (pdus) {
        printf("Generated %zu PDUs\n", num_pdus);
        free(pdus);
    }
    return 0;
}
