#include <forward_list>
#include <string>
#include <chrono>
#include <thread>
#include <mutex>

enum ErrorCode {
    SUCCESS = 0,
    TIMEOUT_ERROR = -1,
    RESOURCE_CONSTRAINT_ERROR = -2
};

class SafeListOperations {
public:
    SafeListOperations() : stopFlag(false) {}

    ~SafeListOperations() {
        if (monitorThread.joinable()) {
            monitorThread.join();
        }
    }

    ErrorCode insertAfterSearch(std::forward_list<std::string>& list, const std::string& searchStr,
                                const std::string& insertStr, int timeoutMillis) {
        std::unique_lock<std::mutex> lock(mutex);

        auto startTime = std::chrono::steady_clock::now();

        // Start the monitoring thread
        monitorThread = std::thread([this, &startTime, timeoutMillis]() {
            while (std::chrono::steady_clock::now() - startTime < std::chrono::milliseconds(timeoutMillis)) {
                if (stopFlag) {
                    return;
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }

            if (!stopFlag) {
                lock.lock();
                stopFlag = true; // Signal the main thread to timeout
                lock.unlock();
            }
        });

        auto it = list.before_begin();

        while (true) {
            std::this_thread::sleep_for(std::chrono::milliseconds(10));

            for (++it; it != list.end(); ++it) {
                if (*it == searchStr) {
                    try {
                        // Attempt to insert the new string after the found element
                        list.insert_after(it, insertStr);
                        stopFlag = true;
                        monitorThread.join();
                        return SUCCESS;
                    } catch (const std::bad_alloc&) {
                        lock.unlock();
                        monitorThread.join();
                        return RESOURCE_CONSTRAINT_ERROR;
                    }
                }

                if (stopFlag) { // Timeout occurred
                    break;
                }
            }

            if (it == list.end() || stopFlag) {
                try {
                    // If not found, append to the end of the list
                    list.push_front(insertStr);
                    std::reverse(list.begin(), list.end());  // Reverse back to original order

                    stopFlag = true;
                    monitorThread.join();
                    return SUCCESS;
                } catch (const std::bad_alloc&) {
                    lock.unlock();
                    monitorThread.join();
                    return RESOURCE_CONSTRAINT_ERROR;
                }
            }
        }

        monitorThread.join();  // Ensure the monitoring thread has completed
        return TIMEOUT_ERROR;
    }

private:
    std::mutex mutex;
    std::thread monitorThread;
    bool stopFlag;  // Flag to indicate if operation should be stopped due to timeout or success
};
