} NfapiCrcIndicationPduT;

void handle_invalid_input(const char *message) {
    printf("%s\n", message);
}

int get_validated_integer() {
    int num;
    while (scanf("%d", &num) != 1 || num <= 0) {
        handle_invalid_input("Invalid input. Please enter a positive integer.");
        while (getchar() != '\n'); // clear the buffer
    }
    return num;
}

void get_user_list(int *list, int list_size) {
    char input[1024];
    printf("Enter a list of integers separated by spaces: ");
    if (!fgets(input, sizeof(input), stdin)) {
        handle_invalid_input("Failed to read input.");
        exit(EXIT_FAILURE);
    }

    int index = 0;
    char *token = strtok(input, " \n");
    while (token != NULL && index < list_size) {
        long val = strtol(token, NULL, 10);
        if (val > 0) {
            list[index++] = (int)val;
        } else {
            handle_invalid_input("Invalid input. Please enter positive integers only.");
            exit(EXIT_FAILURE);
        }
        token = strtok(NULL, " \n");
    }

    while (index < list_size) { // fill remaining with zeros if fewer numbers entered
        list[index++] = 0;
    }
}

int find_largest_integer(int *list, int size) {
    int largest = -1;
    for (int i = 0; i < size; ++i) {
        if (list[i] > largest) {
            largest = list[i];
        }
    }
    return largest;
}

void process_structures(NfapiCrcIndicationPduT *structures, int num_structures, int user_list[], int largest_integer) {
    for (int i = 0; i < num_structures; ++i) {
        structures[i].crc_flag = (largest_integer == user_list[i]) ? 1 : 0;
    }
}

void print_structures(NfapiCrcIndicationPduT *structures, int num_structures) {
    printf("List of Structures:\n");
    for (int i = 0; i < num_structures; ++i) {
        printf("Tag: %d, RNTI: %u, CRC: %d, Flag: %d\n",
               structures[i].rx_ue_information_tag,
               structures[i].rnti,
               structures[i].crc_indication,
               structures[i].crc_flag);
    }
}

int main() {
    srand(time(NULL));

    int num_structures;
    while (1) {
        printf("Enter the number of structures to allocate (between 1 and %d): ", MAX_STRUCTURES);
        if (scanf("%d", &num_structures) == 1 && num_structures > 0 && num_structures <= MAX_STRUCTURES) {
            break;
        }
        handle_invalid_input("Invalid input. Please enter a number between 1 and 1000.");
        while (getchar() != '\n'); // clear the buffer
    }

    NfapiCrcIndicationPduT *structures = malloc(num_structures * sizeof(NfapiCrcIndicationPduT));
    if (!structures) {
        printf("Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_structures; ++i) {
        structures[i].rx_ue_information_tag = i + 1;
        structures[i].rnti = rand() % 65536;
        structures[i].crc_indication = rand() % 256;
        structures[i].crc_flag = 0;
    }

    int user_list[MAX_STRUCTURES];
    get_user_list(user_list, num_structures);

    int largest_integer = find_largest_integer(user_list, num_structures);
    process_structures(structures, num_structures, user_list, largest_integer);

    print_structures(structures, num_structures);

    free(structures);
    return EXIT_SUCCESS;
}
