typedef struct {
    int value;
} Record;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG : 1; // Assuming 1-bit width for CRCFLAG
    } CRC_INDICATION_REL8_TAG;
