int resolve_hostname_to_ip(const char *hostname, u_char ip_array[4]) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return -1; // DNS resolution failed
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        ip_array[0] = ipv4->sin_addr.s_addr >> 24;
        ip_array[1] = (ipv4->sin_addr.s_addr >> 16) & 0xFF;
        ip_array[2] = (ipv4->sin_addr.s_addr >> 8) & 0xFF;
        ip_array[3] = ipv4->sin_addr.s_addr & 0xFF;
        break;
    }

    freeaddrinfo(res);
    return 0; // Success
}

int allocate_and_initialize_records(int min_value, int max_value, Record **records, size_t *size) {
    if (min_value > max_value) return -1;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    pthread_mutex_lock(&lock);

    *size = (rand() % MAX_RECORDS) + 1; // Randomly determine the number of records
    if (*size == 0 || *size > MAX_RECORDS) {
        pthread_mutex_unlock(&lock);
        return -2;
    }

    *records = malloc(*size * sizeof(Record));
    if (*records == NULL) {
        pthread_mutex_unlock(&lock);
        return -3;
    }

    for (size_t i = 0; i < *size; ++i) {
        (*records)[i].value = min_value + rand() % (max_value - min_value + 1);
    }

