typedef struct {
    // Example MAC frame structure; define fields as needed
    unsigned char mac_header[6];
} MAC_FRAME;

typedef struct {
    MAC_FRAME frame;
    int pdu_session_id;
    int status; // 0: pending, 1: processed, -1: errored
} RX_FRAME_INFO;

typedef struct {
    RX_FRAME_INFO *frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} BufferPool;

// Function prototypes
BufferPool* initialize_buffer_pool(size_t initial_size);
void resize_buffer_pool(BufferPool *pool, size_t new_capacity);
void free_buffer_pool(BufferPool *pool);
void populate_mac_header(MAC_FRAME *frame);

// Initialize buffer pool with a given number of frames
BufferPool* initialize_buffer_pool(size_t initial_size) {
    BufferPool *pool = (BufferPool *)malloc(sizeof(BufferPool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->capacity = initial_size;
    pool->count = 0;
    pool->frames = (RX_FRAME_INFO *)calloc(pool->capacity, sizeof(RX_FRAME_INFO));

    // Populate with random MAC headers
    for (size_t i = 0; i < pool->capacity; ++i) {
        populate_mac_header(&pool->frames[i].frame);
        pool->frames[i].pdu_session_id = rand(); // Random session ID
        pool->frames[i].status = 0; // Pending status
    }

    return pool;
}

// Resize buffer pool dynamically
void resize_buffer_pool(BufferPool *pool, size_t new_capacity) {
    pthread_mutex_lock(&pool->lock);

    if (new_capacity > pool->capacity && new_capacity <= MAX_BUFFER_SIZE) {
        RX_FRAME_INFO *new_frames = (RX_FRAME_INFO *)realloc(pool->frames, new_capacity * sizeof(RX_FRAME_INFO));
        if (!new_frames) {
            pthread_mutex_unlock(&pool->lock);
            return;
        }
        memset(new_frames + pool->capacity, 0, (new_capacity - pool->capacity) * sizeof(RX_FRAME_INFO));

        for (size_t i = pool->capacity; i < new_capacity; ++i) {
            populate_mac_header(&new_frames[i].frame);
            new_frames[i].pdu_session_id = rand();
            new_frames[i].status = 0;
        }

        pool->frames = new_frames;
        pool->capacity = new_capacity;
    }

    pthread_mutex_unlock(&pool->lock);
}

// Free buffer pool resources
void free_buffer_pool(BufferPool *pool) {
    if (pool) {
        if (pool->frames) {
            free(pool->frames);
        }
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

// Populate a MAC frame with random data for simulation purposes
void populate_mac_header(MAC_FRAME *frame) {
    srand((unsigned int)time(NULL));
    for (int i = 0; i < sizeof(frame->mac_header); ++i) {
        frame->mac_header[i] = rand() % 256;
    }
}

// Example usage
int main() {
    BufferPool *pool = initialize_buffer_pool(INITIAL_BUFFER_SIZE);

    // Simulate dynamic resizing based on traffic conditions
    resize_buffer_pool(pool, INITIAL_BUFFER_SIZE * 2);
    resize_buffer_pool(pool, INITIAL_BUFFER_SIZE * 4);

    free_buffer_pool(pool);

    return 0;
}
