@app.route('/update', methods=['POST'])
def update_element():
    data = request.json
    section_id = data.get('section_id')
    element_id = data.get('element_id')
    html_content = data.get('html_content')

    if not all([section_id, element_id, html_content]):
        return jsonify({'error': 'Missing parameters'}), 400

    key = (section_id, element_id)

    with lock:
        page_elements[key] = PageElement()
        page_elements[key].content = html_content
        # Simulate a commit operation
        # Trigger page refresh only after successful update
        return jsonify({'status': 'success'})

if __name__ == '__main__':
    app.run(threaded=True)
