NFAPI_CRC_INDICATION_PDU_T pduArray[MAX_STRUCTURES];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* generateRandomData(void *data) {
    unsigned char *crcTag = (unsigned char *) data;
    for (int i = 0; i < 16; ++i)
        crcTag[i] = rand() % 256;
    return NULL;
}

int initializeAndPopulateNfaApiPdu(int numStructures, int verbose) {
    if (numStructures > MAX_STRUCTURES) {
        fprintf(stderr, "Error: Exceeded maximum structures limit.\n");
        return -1;
    }

    pthread_t threads[MAX_STRUCTURES];
    for (int i = 0; i < numStructures; ++i) {
        int rc = pthread_mutex_lock(&mutex);
        if (rc) { fprintf(stderr, "Mutex Lock Error: %d\n", rc); continue; }

        pduArray[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        pduArray[i].RNTI = rand() % 65536;

        pthread_t crcThread;
        pthread_create(&crcThread, NULL, generateRandomData, (void*)pduArray[i].CRC_INDICATION_REL8_TAG);
        pthread_join(crcThread, NULL);

        pduArray[i].CRCFLAG = rand() % 2;

        if (verbose) {
            printf("Structure %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_FLAG=%d\n", i,
                   pduArray[i].RX_UE_INFORMATION_TAG, pduArray[i].RNTI, pduArray[i].CRCFLAG);
        }

        rc = pthread_mutex_unlock(&mutex);
        if (rc) fprintf(stderr, "Mutex Unlock Error: %d\n", rc);
    }
    return 0;
}
