["```javascript
const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');

async function fetchFileMetadata(filePath) {
  const metadataUrl = `https://api.example.com/metadata?file=${encodeURIComponent(filePath)}`;
  let attempts = 0;

  while (attempts < 3) {
    try {
      const response = await axios.get(metadataUrl);
      return response.data;
    } catch (error) {
      if (error.response && error.response.status === 429) { // Handle rate limiting
        console.log(`Rate limited. Retrying ${metadataUrl}...`);
        attempts++;
        await new Promise(resolve => setTimeout(resolve, 1000)); // Wait a second before retrying
      } else {
        console.error(`Failed to fetch metadata for ${filePath}:`, error.message);
        break;
      }
    }
  }

  return null; // Return null if we failed after retries
}

async function processFile(filePath) {
  try {
    const fileContent = await fs.readFile(filePath, 'utf8');
    const metadata = await fetchFileMetadata(filePath);

    return { content: fileContent, metadata };
  } catch (error) {
    console.error(`Error processing file ${filePath}:`, error.message);
    return null; // Return null on errors
  }
}

async function processFilesInDirectory(directoryPath) {
  try {
    const files = await fs.readdir(directoryPath);

    const tasks = files.reduce((acc, fileName) => {
      if (fileName.startsWith('.')) return acc; // Skip hidden files

      const filePath = path.join(directoryPath, fileName);
      acc.push(() => processFile(filePath));

      if (acc.length >= 50) {
        acc.push(null); // Delimiter for Promise.allSettled
      }

      return acc;
    }, []);

    let results = {};

    while (tasks.length > 0) {
      const currentBatch = tasks.splice(0, 51); // Batch of up to 50 files + delimiter

      await Promise.all(currentBatch.filter(task => task)).then(async processedFiles => {
        for (const processResult of processedFiles) {
          if (processResult !== null && processResult !== undefined) {
            const fileName = path.basename(path.dirname(processedFiles));
            results[fileName] = processResult.content;
          }
        }
      });
    }

    return results;

  } catch (error) {
    console.error(`Error reading directory ${directoryPath}:`, error.message);
    return {};
  }
}

module.exports = { processFilesInDirectory };
```

This code snippet demonstrates how to asynchronously process files in a specified directory, handling up to 50 concurrent tasks for optimized resource usage. It integrates an external API call to fetch metadata about each file and includes robust error-handling mechanisms. The function logs progress and issues, is modular, and handles various failure scenarios gracefully."]

