```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_TRANSPORT_CONTEXTS 10000

typedef struct {
    int ip_address;
    int port_number;
} LTE_U_TRANSPORT_CONTEXT;

typedef struct TransportContextNode {
    LTE_U_TRANSPORT_CONTEXT context;
    struct TransportContextNode *next;
} TransportContextNode;

typedef struct {
    int cell_id;
    TransportContextNode *contexts_head;
} LTE_ENB_CONFIG_R;

typedef struct {
    LTE_ENB_CONFIG_R *configs;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Helper function to find context by IP and port
TransportContextNode* find_context(TransportContextNode *head, int ip_address, int port_number) {
    TransportContextNode *current = head;
    while (current != NULL) {
        if (current->context.ip_address == ip_address && current->context.port_number == port_number) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Initialize dynamic array
DynamicArray* init_dynamic_array() {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) {
        perror("Failed to allocate memory for DynamicArray");
        exit(EXIT_FAILURE);
    }
    array->configs = NULL;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

// Add transport context
int add_transport_context(DynamicArray *array, int cell_id, int ip_address, int port_number) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->configs[i].cell_id == cell_id) {
            TransportContextNode *new_node = malloc(sizeof(TransportContextNode));
            if (!new_node) {
                perror("Failed to allocate memory for new transport context node");
                pthread_mutex_unlock(&array->lock);
                return -1;
            }

            new_node->context.ip_address = ip_address;
            new_node->context.port_number = port_number;
            new_node->next = array->configs[i].contexts_head;
            array->configs[i].contexts_head = new_node;

            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }

    // If cell_id not found, reallocate memory
    size_t new_size = array->count + 1;
    LTE_ENB_CONFIG_R *new_configs = realloc(array->configs, new_size * sizeof(LTE_ENB_CONFIG_R));
    if (!new_configs) {
        perror("Failed to allocate memory for new cell configuration");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    array->configs = new_configs;
    array->configs[array->count].cell_id = cell_id;
    array->configs[array->count].contexts_head = NULL;
    ++array->count;

    // Add transport context to the newly created cell
    TransportContextNode *new_node = malloc(sizeof(TransportContextNode));
    if (!new_node) {
        perror("Failed to allocate memory for new transport context node");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    new_node->context.ip_address = ip_address;
    new_node->context.port_number = port_number;
    new_node->next = array->configs[array->count - 1].contexts_head;
    array->configs[array->count - 1].contexts_head = new_node;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Retrieve transport context
TransportContextNode* get_transport_context(DynamicArray *array, int cell_id, int ip_address, int port_number) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->configs[i].cell_id == cell_id) {
            TransportContextNode *context_node = find_context(array->configs[i].contexts_head, ip_address, port_number);
            pthread_mutex_unlock(&array->lock);
            return context_node;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return NULL;
}

// Free dynamic array
void free_dynamic_array(DynamicArray *array) {
    if (!array) return;

    for (size_t i = 0; i < array->count; ++i) {
        TransportContextNode *current = array->configs[i].contexts_head;
        while (current != NULL) {
            TransportContextNode *temp = current;
            current = current->next;
            free(temp);
        }
    }

    free(array->configs);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int main() {
    DynamicArray *array = init_dynamic_array();

    // Example usage
    add_transport_context(array, 1, 19216801, 8080);
    TransportContextNode *context = get_transport_context(array, 1, 19216801, 8080);
    if (context) {
        printf("Found context: IP %d, Port %d\n", context->context.ip_address, context->context.port_number);
    } else {
        printf("Context not found.\n");
    }

    free_dynamic_array(array);
    return 0;
}
```

