// Mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

char* process_string(const char* input, size_t limit, int trim) {
    pthread_mutex_lock(&mutex);

    char *result = NULL;
    const char *str = input;
    size_t length = strlen(input);

    if (trim) {
        str = input + strspn(input, " \t\n\r");
        length -= strspn(input, " \t\n\r") - strspn(str, " \t\n\r");
    }

    if (length < limit) {
        size_t new_length = length + 2; // For '/' and '\0'
        result = malloc(new_length);
        if (result != NULL) {
            strcpy(result, str);
            strcat(result, "/");
        }
    } else {
        return NULL;
    }

    pthread_mutex_unlock(&mutex);

    return result;
}

