import java.util.LinkedList;
import java.util.Queue;
import java.util.Random;

public class ServiceManager {
    private static final int MAX_LOG_ENTRIES = 1000;
    private Queue<String> logEntries = new LinkedList<>();

    public void startService(String input, int sizeLimit, boolean trim) {
        Random random = new Random();
        long delay = random.nextInt(5000); // Delay between 0 and 5000 ms
        try {
            Thread.sleep(delay);
            String result = nativeProcessString(input, sizeLimit, trim);
            log("Service started. Input: " + input + ", Result: " + (result != null ? "Processed" : "Exceeded limit") + ", Size: " + (result == null ? length(input) : result.length()));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void stopService() {
        Random random = new Random();
        long delay = random.nextInt(5000); // Delay between 0 and 5000 ms
        try {
            Thread.sleep(delay);
            log("Service stopped.");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private void log(String message) {
        if (logEntries.size() >= MAX_LOG_ENTRIES) {
            logEntries.poll();
        }
        logEntries.offer(message);
        System.out.println(message); // For simplicity, printing to console
    }

    private native String nativeProcessString(String input, int sizeLimit, boolean trim);

    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager();
        manager.startService("example", 10, true);
        manager.stopService();
    }
}
