void initialize_packet(SensorDataPacket *packet, int sensorID, float measurementValue, SensorType type) {
    static int packetCounter = 0;
    pthread_mutex_lock(&buffer.lock);

    if (buffer.count < MAX_PACKETS) {
        packet->PacketID = ++packetCounter;
        packet->timestamp = time(NULL);
        packet->sensorID = sensorID;
