    // Reset the packet count after processing
    buffer.count = 0;
    pthread_mutex_unlock(&buffer.lock);
}

void *data_processing_thread(void *arg) {
    while (1) {
        if (buffer.count >= buffer.thresholdLow) {
            processDataBatch();
        }
        sleep(1); // Simulate periodic check
    }
    return NULL;
}

