#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>
#include <time.h>
#include <pthread.h>

#define MAX_INPUT_STRING_LENGTH 256

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG:1;
    } CRC_INDICATION_REL8_TAG;
    unsigned char MD5_HASH[MD5_DIGEST_LENGTH];
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void secure_seed_rng() {
    // Seed the RNG with /dev/urandom
    FILE *fp = fopen("/dev/urandom", "rb");
    if (fp == NULL) {
        fprintf(stderr, "Could not open /dev/urandom\n");
        exit(EXIT_FAILURE);
    }
    unsigned int seed;
    fread(&seed, sizeof(seed), 1, fp);
    fclose(fp);

    // Use the seed for the RNG
    srand(seed);
}

unsigned char* compute_md5_hash(const char *inputString) {
    if (strlen(inputString) == 0 || strlen(inputString) > MAX_INPUT_STRING_LENGTH) {
        return NULL;
    }

    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)inputString, strlen(inputString), hash);

    unsigned char* result = malloc(MD5_DIGEST_LENGTH);
    if (result == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memcpy(result, hash, MD5_DIGEST_LENGTH);

    return result;
}

NFAPI_CRC_INDICATION_PDU_T* generateAndProcessPduList(size_t N, const char *inputString) {
    if (strlen(inputString) == 0 || strlen(inputString) > MAX_INPUT_STRING_LENGTH) {
        fprintf(stderr, "Invalid input string\n");
        return NULL;
    }

    secure_seed_rng();

    pthread_mutex_lock(&lock);

    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* pduList = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pduList == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Compute the MD5 hash once for reuse
    unsigned char* md5Hash = compute_md5_hash(inputString);
    if (md5Hash == NULL) {
        free(pduList);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        pduList[i].RX_UE_INFORMATION_TAG = rand(); // Random valid tag
        pduList[i].RNTI = rand() & 0xFFFFFFF;      // Random valid RNTI

        // Securely generate CRCFLAG using a secure pseudo-random number generator
        pduList[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        // Store the computed MD5 hash in each structure
        memcpy(pduList[i].MD5_HASH, md5Hash, MD5_DIGEST_LENGTH);
    }

    free(md5Hash);

    pthread_mutex_unlock(&lock);

    return pduList;
}
