typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int valid;  // Flag to indicate if the entry is valid
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
int add_crc_pdu(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size, unsigned long rnti, int sort_order);
void free_list(NFAPI_CRC_INDICATION_PDU_T **list);

// Helper function to check if RNTI exists in the list
int rnti_exists(NFAPI_CRC_INDICATION_PDU_T *list, size_t size, unsigned long rnti) {
    for (size_t i = 0; i < size; ++i) {
        if (list[i].valid && list[i].ue_info_tag.RNTI == rnti) {
            return 1;
        }
    }
    return 0;
}

// Function to add a CRC PDU to the list
int add_crc_pdu(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size, unsigned long rnti, int sort_order) {
    if (*list == NULL) {
        *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (*list == NULL) return -1;
        *size = 0;
    }

    if (rnti_exists(*list, *size, rnti)) {
        return 0; // RNTI already exists
    }

    NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(*list, (*size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_list == NULL) {
        free(*list);
        return -1;
    }
    *list = new_list;

    (*list)[*size].ue_info_tag.RNTI = rnti;
    (*list)[*size].crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG
    (*list)[*size].valid = 1;
    (*size)++;

    // Sort the list based on RNTI
    qsort(*list, *size, sizeof(NFAPI_CRC_INDICATION_PDU_T), 
          [sort_order](const void *a, const void *b) -> int {
              NFAPI_CRC_INDICATION_PDU_T *entry_a = (NFAPI_CRC_INDICATION_PDU_T *)a;
              NFAPI_CRC_INDICATION_PDU_T *entry_b = (NFAPI_CRC_INDICATION_PDU_T *)b;
              if (!entry_a->valid || !entry_b->valid) return 0; // Ignore invalid entries
              int result = entry_a->ue_info_tag.RNTI - entry_b->ue_info_tag.RNTI;
              return sort_order == 1 ? result : -result;
          });

    return 0;
}

// Function to free the allocated list
void free_list(NFAPI_CRC_INDICATION_PDU_T **list) {
    if (list && *list) {
        free(*list);
        *list = NULL;
    }
}
