#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define constants
#define INITIAL_CAPACITY 10
#define SUCCESS 0
#define ERROR_MEMORY_ALLOCATION -1
#define ERROR_INVALID_ID -2

typedef struct {
    int nas_message_id;
    char ptmsi[20]; // Assuming P-TMSI is a fixed size for simplicity
    char kasme_key[32];
} UPLINK_NAS_MESSAGE;

// Dynamic array structure
typedef struct {
    UPLINK_NAS_MESSAGE *messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // Mutex for thread safety
} MessageArray;

// Function prototypes
MessageArray* create_message_array();
int add_message(MessageArray *array, int nas_message_id, const char *ptmsi, const char *kasme);
int update_message(MessageArray *array, int nas_message_id, const char *ptmsi, const char *kasme);
int remove_message(MessageArray *array, int nas_message_id);
void free_message_array(MessageArray *array);

// Function implementations

MessageArray* create_message_array() {
    MessageArray *array = (MessageArray*)malloc(sizeof(MessageArray));
    if (!array) return NULL;

    array->messages = (UPLINK_NAS_MESSAGE*)calloc(INITIAL_CAPACITY, sizeof(UPLINK_NAS_MESSAGE));
    if (!array->messages) {
        free(array);
        return NULL;
    }

    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

int add_message(MessageArray *array, int nas_message_id, const char *ptmsi, const char *kasme) {
    pthread_mutex_lock(&array->lock);

    // Check for existing message
    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i].nas_message_id == nas_message_id) {
            pthread_mutex_unlock(&array->lock);
            return ERROR_INVALID_ID;
        }
    }

    // Resize if necessary
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        UPLINK_NAS_MESSAGE *new_messages = realloc(array->messages, new_capacity * sizeof(UPLINK_NAS_MESSAGE));
        if (!new_messages) {
            pthread_mutex_unlock(&array->lock);
            return ERROR_MEMORY_ALLOCATION;
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }

    // Add message
    UPLINK_NAS_MESSAGE *message = &array->messages[array->size++];
    message->nas_message_id = nas_message_id;
    strncpy(message->ptmsi, ptmsi, sizeof(message->ptmsi) - 1);
    strncpy(message->kasme_key, kasme, sizeof(message->kasme_key) - 1);

    pthread_mutex_unlock(&array->lock);
    return SUCCESS;
}

int update_message(MessageArray *array, int nas_message_id, const char *ptmsi, const char *kasme) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i].nas_message_id == nas_message_id) {
            strncpy(array->messages[i].ptmsi, ptmsi, sizeof(array->messages[i].ptmsi) - 1);
            strncpy(array->messages[i].kasme_key, kasme, sizeof(array->messages[i].kasme_key) - 1);

            pthread_mutex_unlock(&array->lock);
            return SUCCESS;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return ERROR_INVALID_ID;
}

int remove_message(MessageArray *array, int nas_message_id) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i].nas_message_id == nas_message_id) {
            memmove(&array->messages[i], &array->messages[i + 1], 
                    (--array->size - i) * sizeof(UPLINK_NAS_MESSAGE));
            pthread_mutex_unlock(&array->lock);
            return SUCCESS;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return ERROR_INVALID_ID;
}

void free_message_array(MessageArray *array) {
    if (array) {
        free(array->messages);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}
```

