#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int preamble_power;
    int preamble_zero_correlation_zone_size;
    int srs_periodicity;
} PHY_RACH_CONFIG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    PHY_RACH_CONFIG phy_rach_config;
} LTE_UE_CONTEXT;

typedef struct Node {
    LTE_UE_CONTEXT data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} UEList;

// Initialize the list
void init_list(UEList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a new LTE_UE_CONTEXT to the list
void add_context(UEList* list, LTE_UE_CONTEXT context) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return; // Handle memory allocation failure

    new_node->data = context;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

// Remove a LTE_UE_CONTEXT by RNTI
void remove_context(UEList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return; // Context not found
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
}

// Iterate over the list and apply a function to each LTE_UE_CONTEXT
void iterate_list(UEList* list, void (*func)(LTE_UE_CONTEXT*)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;

    while (current != NULL) {
        func(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example function to print LTE_UE_CONTEXT
void print_context(LTE_UE_CONTEXT* context) {
    printf("RNTI: %d, RX_INFO_TAG: %d\n", context->RNTI, context->RX_UE_INFORMATION_TAG);
}

int main() {
    UEList list;
    init_list(&list);

    LTE_UE_CONTEXT context1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100, 
                               .phy_rach_config = { .preamble_power = 10, .preamble_zero_correlation_zone_size = 2, .srs_periodicity = 5 } };
    add_context(&list, context1);

    LTE_UE_CONTEXT context2 = { .RX_UE_INFORMATION_TAG = 2, .RNTI = 101, 
                               .phy_rach_config = { .preamble_power = 15, .preamble_zero_correlation_zone_size = 3, .srs_periodicity = 6 } };
    add_context(&list, context2);

    iterate_list(&list, print_context);
    remove_context(&list, 100);

    iterate_list(&list, print_context);

    return 0;
}
