#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    float BLER;
    float Throughput;
} L1Metrics;

typedef struct {
    int RRCConnectionID;
    int MACEntityID;
    L1Metrics l1Metrics;
} UEContext;

typedef struct {
    UEContext* contexts;
    size_t capacity;
    size_t count;
} ContextList;

// Function prototypes
void initializeContextList(ContextList* list, size_t initialCapacity);
void freeContextList(ContextList* list);
int addUEContext(ContextList* list, int RRCConnectionID, int MACEntityID, L1Metrics l1Metrics);
int removeUEContext(ContextList* list, int RRCConnectionID);
int getUEContext(const ContextList* list, int RRCConnectionID, UEContext* context);

void serializeContextsToFile(const ContextList* list, const char* filename);
int deserializeContextsFromFile(ContextList* list, const char* filename);

static void resizeIfNeeded(ContextList* list);

// Function implementations
void initializeContextList(ContextList* list, size_t initialCapacity) {
    list->contexts = malloc(initialCapacity * sizeof(UEContext));
    if (!list->contexts) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->capacity = initialCapacity;
    list->count = 0;
}

void freeContextList(ContextList* list) {
    free(list->contexts);
    list->contexts = NULL;
    list->capacity = 0;
    list->count = 0;
}

static void resizeIfNeeded(ContextList* list) {
    if (list->count >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        UEContext* newContexts = realloc(list->contexts, newCapacity * sizeof(UEContext));
        if (!newContexts) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        list->contexts = newContexts;
        list->capacity = newCapacity;
    }
}

int addUEContext(ContextList* list, int RRCConnectionID, int MACEntityID, L1Metrics l1Metrics) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i].RRCConnectionID == RRCConnectionID) {
            return -1; // Context already exists
        }
    }

    resizeIfNeeded(list);
    UEContext newContext = {RRCConnectionID, MACEntityID, l1Metrics};
    list->contexts[list->count++] = newContext;
    return 0; // Success
}

int removeUEContext(ContextList* list, int RRCConnectionID) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i].RRCConnectionID == RRCConnectionID) {
            memmove(&list->contexts[i], &list->contexts[i + 1],
                    (list->count - i - 1) * sizeof(UEContext));
            --list->count;
            return 0; // Success
        }
    }
    return -1; // Context not found
}

int getUEContext(const ContextList* list, int RRCConnectionID, UEContext* context) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i].RRCConnectionID == RRCConnectionID) {
            *context = list->contexts[i];
            return 0; // Success
        }
    }
    return -1; // Context not found
}

void serializeContextsToFile(const ContextList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(&list->count, sizeof(size_t), 1, file);
    fwrite(list->contexts, sizeof(UEContext), list->count, file);

    if (ferror(file)) {
        perror("Error during serialization");
    }
    fclose(file);
}

int deserializeContextsFromFile(ContextList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    resizeIfNeeded(list);

    list->count = count;
    fread(list->contexts, sizeof(UEContext), count, file);

    if (ferror(file)) {
        perror("Error during deserialization");
        fclose(file);
        return -1;
    }
    fclose(file);
    return 0; // Success
}
```

### Trade-offs:
- **Memory Consumption**: The list is dynamically resized using a doubling strategy, which minimizes the number of allocations but can temporarily allocate more memory than needed.
- **Processing Time**: Resizing and serialization/deserialization operations are optimized for speed but may require additional time during large updates.
- **Ease of Maintenance**: The API is designed to be flexible and extensible, allowing easy addition of new attributes without significant refactoring. Error handling ensures robustness against file I/O issues.']

