// Assuming the structure is defined as follows:
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI 1024

static unsigned int allocated_rnti[MAX_RNTI] = {0};

// Function to log allocation details
void log_allocation_details(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    printf("[%04d-%02d-%02d %02d:%02d:%02d] %s\n", t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
           t->tm_hour, t->tm_min, t->tm_sec, message);
}

// Function to check if RNTI is unique
bool is_unique_rnti(unsigned int rnti) {
    return allocated_rnti[rnti % MAX_RNTI] == 0;
}

// Function to allocate and initialize array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indications(size_t n, size_t *success_count) {
    if (n == 0) {
        *success_count = 0;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_allocation_details("Memory allocation failed");
        *success_count = 0;
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed for random CRCFLAG generation
    size_t count = 0;

    for (size_t i = 0; i < n; ++i) {
        unsigned int rnti;
        do {
            rnti = rand() % MAX_RNTI;
        } while (!is_unique_rnti(rnti));

        array[i].RX_UE_INFORMATION_TAG = rand(); // Example initialization
        array[i].RNTI = rnti;
        array[i].CRC_INDICATION_REL8_TAG = rand(); // Example initialization
        array[i].CRCFLAG = rand() % 2; // Random CRC flag

        allocated_rnti[rnti % MAX_RNTI] = rnti + 1; // Mark RNTI as used
        count++;
    }

    *success_count = count;
    log_allocation_details("Memory allocation successful");
    return array;
}

// Function to free the allocated memory and reset RNTI tracking
void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T *array, size_t n) {
    if (array) {
        memset(array, 0, n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(array);
        log_allocation_details("Memory deallocation successful");

        // Reset the RNTI tracking
        for (size_t i = 0; i < MAX_RNTI; ++i) {
            allocated_rnti[i] = 0;
        }
    } else {
        log_allocation_details("Attempted to free NULL pointer");
    }
}

int main() {
    size_t success_count;
    size_t n = 1000; // Example number of elements

    NFAPI_CRC_INDICATION_PDU_T *array = allocate_crc_indications(n, &success_count);
    if (array) {
        printf("Allocated %zu out of %zu structures successfully.\n", success_count, n);

        // Simulate processing...

        free_crc_indications(array, success_count);
    } else {
        printf("Failed to allocate memory for CRC indications.\n");
    }

    return 0;
}
