#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <netdb.h>
#include <arpa/inet.h>

#define MAX_DNS_RETRIES 3

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    char CRCFLAG; // '0' or '1'
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
int resolve_hostname(const char* hostname, struct in_addr* ip_address);
void* fetch_data_thread(void* arg);

int allocate_and_init_structures(int n, const char* hostname) {
    pthread_t dns_thread;
    struct in_addr resolved_ip;
    NFAPI_CRC_INDICATION_PDU_T *structures = NULL;
    int result = 0;

    // Start DNS resolution concurrently
    if (pthread_create(&dns_thread, NULL, fetch_data_thread, &resolved_ip)) {
        fprintf(stderr, "Error creating thread for DNS resolution\n");
        return -1;
    }

    // Allocate memory for structures
    structures = (NFAPI_CRC_INDICATION_PDU_T*) malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        perror("Memory allocation failed");
        result = -2;
        goto cleanup;
    }

    // Initialize structures with data from external source and random CRCFLAG
    for (int i = 0; i < n; ++i) {
        // Assume fetch_external_data is a function that fills RX_UE_INFORMATION_TAG and RNTI
        // This is a placeholder to simulate fetching real-time data
        structures[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        structures[i].RNTI = rand() % 1000;
        structures[i].CRC_INDICATION_REL8_TAG = (uint32_t)rand();
        structures[i].CRCFLAG = (char)(rand() % 2);

        // Ensure data integrity
        if (!structures[i].RX_UE_INFORMATION_TAG || !structures[i].RNTI) {
            fprintf(stderr, "Data integrity check failed\n");
            result = -3;
            goto cleanup;
        }
    }

    // Wait for DNS resolution to complete
    pthread_join(dns_thread, NULL);

cleanup:
    if (result != 0 && structures) {
        free(structures);
    }
    return result;
}

int resolve_hostname(const char* hostname, struct in_addr* ip_address) {
    struct hostent *host_info;
    int retries = 0;

    while (retries < MAX_DNS_RETRIES) {
        if ((host_info = gethostbyname(hostname)) == NULL) {
            perror("DNS resolution failed");
            retries++;
        } else {
            memcpy(ip_address, host_info->h_addr_list[0], sizeof(struct in_addr));
            return 0;
        }
    }

    fprintf(stderr, "Max DNS resolution attempts reached\n");
    return -1;
}

void* fetch_data_thread(void* arg) {
    struct in_addr* ip_address = (struct in_addr*)arg;

    if (resolve_hostname("example.com", ip_address)) {
        pthread_exit((void*)(intptr_t)-1);
    }

    printf("Resolved IP: %s\n", inet_ntoa(*ip_address));
    pthread_exit(NULL);
}

int main() {
    int num_structures = 10;
    const char* hostname = "example.com";

    if (allocate_and_init_structures(num_structures, hostname) != 0) {
        fprintf(stderr, "Failed to allocate and initialize structures\n");
        return EXIT_FAILURE;
    }

    printf("Structures allocated and initialized successfully\n");
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Concurrency**: DNS resolution is performed in a separate thread to minimize latency.
- **Error Handling**: Checks for memory allocation failures, data integrity, and DNS resolution errors. Resources are freed on failure.
- **Resource Management**: Memory is allocated once based on the required number of structures.
- **DNS Resolution**: Uses `gethostbyname` with retry logic to handle transient network issues.

This code provides a foundation that can be expanded upon for real-world applications, particularly in handling more complex data fetching and processing scenarios.']

['Below is a C implementation of a dynamically resizable and thread-safe hash table for `TX_PACKET_INFO_T` structures:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef enum {
    PENDING,
    IN_FLIGHT,
    COMPLETED
} TransmissionState;

typedef struct TX_PACKET_INFO_T {
    unsigned int PREAMBLE_SEQ_NUM;
    time_t TX_TIME_STAMP;
    char FRAME_TYPE[256];
    int ref_count;
    TransmissionState status;
    pthread_mutex_t lock; // For thread-safe reference counting
} TX_PACKET_INFO_T;

#define INITIAL_SIZE 16
#define MAX_ENTRIES 1024

typedef struct HashTableEntry {
    TX_PACKET_INFO_T *packet;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct {
    HashTableEntry **buckets;
    size_t num_buckets;
    size_t count;
    pthread_mutex_t table_lock;
} HashTable;

unsigned int hash_function(unsigned int seq_num, size_t num_buckets) {
    return seq_num % num_buckets;
}

HashTable* create_hash_table(size_t initial_size) {
    HashTable *table = malloc(sizeof(HashTable));
    table->buckets = calloc(initial_size, sizeof(HashTableEntry *));
    table->num_buckets = initial_size;
    table->count = 0;
    pthread_mutex_init(&table->table_lock, NULL);
    return table;
}

void resize_hash_table(HashTable *table);

int insert_packet(HashTable *table, TX_PACKET_INFO_T *packet) {
    if (table->count >= MAX_ENTRIES) return -1;

    unsigned int index = hash_function(packet->PREAMBLE_SEQ_NUM, table->num_buckets);
    pthread_mutex_lock(&table->table_lock);

    HashTableEntry *entry = malloc(sizeof(HashTableEntry));
    entry->packet = packet;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;

    table->count++;
    if (table->count > 0.75 * table->num_buckets) {
        resize_hash_table(table);
    }

    pthread_mutex_unlock(&table->table_lock);
    return 0;
}

TX_PACKET_INFO_T* find_packet(HashTable *table, unsigned int seq_num) {
    unsigned int index = hash_function(seq_num, table->num_buckets);
    HashTableEntry *entry = table->buckets[index];

    while (entry != NULL) {
        pthread_mutex_lock(&entry->packet->lock);
        if (entry->packet->PREAMBLE_SEQ_NUM == seq_num) {
            entry->packet->ref_count++;
            pthread_mutex_unlock(&entry->packet->lock);
            return entry->packet;
        }
        pthread_mutex_unlock(&entry->packet->lock);
        entry = entry->next;
    }

    return NULL;
}

void remove_packet(HashTable *table, unsigned int seq_num) {
    unsigned int index = hash_function(seq_num, table->num_buckets);
    HashTableEntry *entry = table->buckets[index];
    HashTableEntry *prev = NULL;

    pthread_mutex_lock(&table->table_lock);

    while (entry != NULL) {
        TX_PACKET_INFO_T *packet = entry->packet;
        pthread_mutex_lock(&packet->lock);
        if (packet->PREAMBLE_SEQ_NUM == seq_num) {
            if (--packet->ref_count <= 0) {
                if (prev == NULL) {
                    table->buckets[index] = entry->next;
                } else {
                    prev->next = entry->next;
                }
                free(entry);
                table->count--;
            }
            pthread_mutex_unlock(&packet->lock);
            break;
        }
        pthread_mutex_unlock(&packet->lock);
        prev = entry;
        entry = entry->next;
    }

    pthread_mutex_unlock(&table->table_lock);
}

void prune_old_packets(HashTable *table, time_t age_threshold) {
    for (size_t i = 0; i < table->num_buckets; i++) {
        HashTableEntry *entry = table->buckets[i];
        HashTableEntry *prev = NULL;

        pthread_mutex_lock(&table->table_lock);

        while (entry != NULL) {
            TX_PACKET_INFO_T *packet = entry->packet;
            pthread_mutex_lock(&packet->lock);
            if (difftime(time(NULL), packet->TX_TIME_STAMP) > age_threshold && --packet->ref_count <= 0) {
                if (prev == NULL) {
                    table->buckets[i] = entry->next;
                } else {
                    prev->next = entry->next;
                }
                free(entry);
                table->count--;
            }
            pthread_mutex_unlock(&packet->lock);
            prev = entry;
            entry = entry->next;
        }

        pthread_mutex_unlock(&table->table_lock);
    }
}

void resize_hash_table(HashTable *table) {
    size_t new_size = table->num_buckets * 2;
    HashTableEntry **new_buckets = calloc(new_size, sizeof(HashTableEntry *));

    for (size_t i = 0; i < table->num_buckets; i++) {
        HashTableEntry *entry = table->buckets[i];
        while (entry != NULL) {
            unsigned int new_index = hash_function(entry->packet->PREAMBLE_SEQ_NUM, new_size);
            HashTableEntry *next_entry = entry->next;

            pthread_mutex_lock(&table->table_lock);

            entry->next = new_buckets[new_index];
            new_buckets[new_index] = entry;

            pthread_mutex_unlock(&table->table_lock);
            entry = next_entry;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->num_buckets = new_size;
}

void monitor_performance(HashTable *table) {
    // Implement performance metrics collection here
}

void integrate_with_external_source(HashTable *table) {
    // Implement integration logic here
}

void cleanup_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->num_buckets; i++) {
        HashTableEntry *entry = table->buckets[i];
        while (entry != NULL) {
            TX_PACKET_INFO_T *packet = entry->packet;
            pthread_mutex_lock(&packet->lock);
            if (--packet->ref_count <= 0) {
                free(packet);
            }
            pthread_mutex_unlock(&packet->lock);
            HashTableEntry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->table_lock);
    free(table);
}
