static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Pre-allocated memory pool for payloads to minimize frequent allocations
#define MEMORY_POOL_SIZE 10
char *memory_pool[MEMORY_POOL_SIZE];
size_t available_indices[MEMORY_POOL_SIZE];

void initialize_memory_pool() {
    for (int i = 0; i < MEMORY_POOL_SIZE; ++i) {
        memory_pool[i] = malloc(MAX_PAYLOAD_SIZE);
        if (!memory_pool[i]) {
            fprintf(stderr, "Failed to allocate memory pool\n");
            exit(EXIT_FAILURE);
        }
        available_indices[i] = i;
    }
}

void free_memory_pool() {
    for (int i = 0; i < MEMORY_POOL_SIZE; ++i) {
        free(memory_pool[i]);
    }
}

FrameMetadata* initialize_frame_metadata_array(size_t count, const uint64_t *timestamps, FrameType *frame_types, size_t *payload_sizes) {
    if (!pthread_mutex_lock(&mutex)) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    FrameMetadata *frames = (FrameMetadata *)calloc(count, sizeof(FrameMetadata));
    if (!frames) {
        fprintf(stderr, "Memory allocation for frame array failed\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    initialize_memory_pool();

    for (size_t i = 0; i < count; ++i) {
        frames[i].timestamp = timestamps[i];
        frames[i].frame_type = frame_types[i];

        if (payload_sizes[i] > MAX_PAYLOAD_SIZE) {
            fprintf(stderr, "Payload size exceeds maximum allowed size: %zu\n", payload_sizes[i]);
            pthread_mutex_unlock(&mutex);
            free(frames);
            return NULL;
        }

        // Reuse memory from pool if possible
        if (available_indices[0] != -1) {
            int index = available_indices[0];
            for (int j = 0; j < MEMORY_POOL_SIZE - 1; ++j) {
                available_indices[j] = available_indices[j + 1];
            }
            available_indices[MEMORY_POOL_SIZE - 1] = -1;

            frames[i].payload_data = memory_pool[index];
            frames[i].payload_size = payload_sizes[i];
        } else {
            // Allocate new memory if pool is exhausted
            frames[i].payload_data = malloc(payload_sizes[i]);
            if (!frames[i].payload_data) {
                fprintf(stderr, "Memory allocation for payload failed\n");
                pthread_mutex_unlock(&mutex);
                free(frames);
                return NULL;
            }
        }
    }

    pthread_mutex_unlock(&mutex);

    return frames;
}

// Example usage and cleanup
int main() {
    size_t count = 5;
    uint64_t timestamps[] = {1, 2, 3, 4, 5};
    FrameType frame_types[] = {FRAME_TYPE_A, FRAME_TYPE_B, FRAME_TYPE_A, FRAME_TYPE_B, FRAME_TYPE_A};
    size_t payload_sizes[] = {100, 200, 300, 400, 500};

    FrameMetadata *frames = initialize_frame_metadata_array(count, timestamps, frame_types, payload_sizes);

    if (frames) {
        // Process frames...

        free(frames);
    }

    free_memory_pool();
    return 0;
}
