#include <string.h>
#include <stdbool.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the node for the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function prototypes
Node* create_node(uint32_t rxTag, uint16_t rnti, uint8_t crcTag);
void free_list(Node* head);
bool add_pdu(Node** head, uint32_t rxTag, uint16_t rnti, uint8_t crcTag);
Node* find_by_rnti(Node* head, uint16_t rnti);
size_t serialize_list(const Node* head, uint8_t** buffer);
Node* deserialize_list(const uint8_t* buffer, size_t bufferSize);
bool validate_uniqueness(uint16_t rnti, const Node* head);

// Create a new node
Node* create_node(uint32_t rxTag, uint16_t rnti, uint8_t crcTag) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed for new node.\n");
        return NULL;
    }

    newNode->data.RX_UE_INFORMATION_TAG = rxTag;
    newNode->data.RNTI = rnti;
    newNode->data.CRC_INDICATION_REL8_TAG = crcTag;
    newNode->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    newNode->next = NULL;

    return newNode;
}

// Free the linked list
void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Add a new PDU to the list ensuring uniqueness of RNTI
bool add_pdu(Node** head, uint32_t rxTag, uint16_t rnti, uint8_t crcTag) {
    if (!validate_uniqueness(rnti, *head)) {
        fprintf(stderr, "RNTI %u already exists in the list.\n", rnti);
        return false;
    }

    Node* newNode = create_node(rxTag, rnti, crcTag);
    if (!newNode) {
        return false; // Memory allocation failed
    }

    newNode->next = *head;
    *head = newNode;

    return true;
}

// Check for uniqueness of RNTI in the list
bool validate_uniqueness(uint16_t rnti, const Node* head) {
    while (head != NULL) {
        if (head->data.RNTI == rnti) {
            return false; // RNTI already exists
        }
        head = head->next;
    }
    return true;
}

// Serialize the linked list into a binary format
size_t serialize_list(const Node* head, uint8_t** buffer) {
    if (!head) {
        *buffer = NULL;
        return 0;
    }

    // Calculate total size needed for serialization
    const Node* current = head;
    size_t totalSize = sizeof(size_t); // To store the number of nodes

    while (current != NULL) {
        totalSize += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }

    *buffer = (uint8_t*)malloc(totalSize);
    if (!*buffer) {
        fprintf(stderr, "Memory allocation failed for serialization buffer.\n");
        return 0;
    }

    uint8_t* ptr = *buffer;
    size_t numNodes = totalSize / sizeof(NFAPI_CRC_INDICATION_PDU_T) - 1;

    memcpy(ptr, &numNodes, sizeof(size_t));
    ptr += sizeof(size_t);

    current = head;
    while (current != NULL) {
        memcpy(ptr, &(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        ptr += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }

    return totalSize;
}

// Deserialize the binary data back into a linked list
Node* deserialize_list(const uint8_t* buffer, size_t bufferSize) {
    if (!buffer || bufferSize == 0) {
        fprintf(stderr, "Invalid buffer for deserialization.\n");
        return NULL;
    }

    const uint8_t* ptr = buffer;
    size_t numNodes;

    memcpy(&numNodes, ptr, sizeof(size_t));
    ptr += sizeof(size_t);

    Node* head = NULL;

    while (numNodes-- > 0 && bufferSize >= sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        memcpy(&pdu, ptr, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        ptr += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        bufferSize -= sizeof(NFAPI_CRC_INDICATION_PDU_T);

        if (!add_pdu(&head, pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG)) {
            // Free partially created list in case of failure
            free_list(head);
            return NULL;
        }
    }

    if (numNodes > 0) {
        fprintf(stderr, "Buffer size mismatch during deserialization.\n");
        free_list(head);
        return NULL;
    }

    return head;
}

// Example usage
int main() {
    Node* list = NULL;

    add_pdu(&list, 1, 100, 5);
    add_pdu(&list, 2, 101, 6);

    uint8_t* serializedData = NULL;
    size_t dataSize = serialize_list(list, &serializedData);

    if (dataSize > 0) {
        Node* deserializedList = deserialize_list(serializedData, dataSize);
        // Use deserialized list
        free_list(deserializedList);
        free(serializedData);
    }

    free_list(list);

    return 0;
}
