#include <pthread.h>

#define MAX_PAYLOAD_SIZE 1024
#define MAX_RETRIES 3
#define CACHE_LINE_SIZE 64

typedef enum {
    FRAME_TYPE_A,
    FRAME_TYPE_B,
    // Add more frame types as needed
} FrameType;

typedef struct {
    uint64_t timestamp;
    FrameType type;
    void *payload;
    size_t payload_size;
    int priority;
