    // Future additional fields can be added here
} FrameMetadata;

// Global lock for thread safety
pthread_mutex_t frame_metadata_lock = PTHREAD_MUTEX_INITIALIZER;

FrameMetadata* initialize_frame_metadata(size_t num_frames, const void *payload_data[], size_t payload_sizes[]) {
    if (num_frames == 0) return NULL;

    pthread_mutex_lock(&frame_metadata_lock);

    FrameMetadata **frames = malloc(num_frames * sizeof(FrameMetadata *));
    if (!frames) {
        perror("Failed to allocate memory for frame pointers");
        pthread_mutex_unlock(&frame_metadata_lock);
        return NULL;
    }

    for (size_t i = 0; i < num_frames; ++i) {
        frames[i] = malloc(sizeof(FrameMetadata));
        if (!frames[i]) {
            perror("Failed to allocate memory for FrameMetadata");
            for (size_t j = 0; j < i; ++j) {
                free(frames[j]);
            }
            free(frames);
            pthread_mutex_unlock(&frame_metadata_lock);
            return NULL;
        }

        frames[i]->timestamp = time(NULL); // Example of unique timestamp
        frames[i]->type = FRAME_TYPE_A;   // Placeholder type assignment
        frames[i]->priority = 0;          // Default priority
        frames[i]->sequence_number = i;   // Simple sequence number

        size_t actual_payload_size = payload_sizes[i] > MAX_PAYLOAD_SIZE ? MAX_PAYLOAD_SIZE : payload_sizes[i];

        if (payload_data[i]) {
            frames[i]->payload = malloc(actual_payload_size);
            if (!frames[i]->payload) {
                perror("Failed to allocate memory for payload");
                free(frames[i]);
                for (size_t j = 0; j < i; ++j) {
                    free(frames[j]);
                }
                free(frames);
                pthread_mutex_unlock(&frame_metadata_lock);
                return NULL;
            }

            memcpy(frames[i]->payload, payload_data[i], actual_payload_size);
        } else {
            frames[i]->payload = NULL;
        }

        frames[i]->payload_size = actual_payload_size;

        // Padding to cache line size for optimization
        size_t padding = (CACHE_LINE_SIZE - (sizeof(FrameMetadata) % CACHE_LINE_SIZE)) % CACHE_LINE_SIZE;
        char *pad = malloc(padding);
        if (!pad && padding > 0) {
            perror("Failed to allocate memory for structure alignment");
            free(frames[i]->payload); // Free payload if needed
            free(frames[i]);
            for (size_t j = 0; j < i; ++j) {
                free(frames[j]->payload);
                free(frames[j]);
            }
            free(frames);
            pthread_mutex_unlock(&frame_metadata_lock);
            return NULL;
        }
        memset(pad, 0, padding); // Ensuring alignment
        frames[i] = (FrameMetadata *)((char *)frames[i] + padding);

        if (pad) {
            free(pad);
        }

        for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
            // Simulate network data fetching with retry logic
            int success = simulate_network_fetch();
            if (success) break;
            fprintf(stderr, "Network fetch failed on attempt %d\n", attempt + 1);
            if (attempt == MAX_RETRIES - 1) {
                fprintf(stderr, "Exceeded maximum retries for network fetch\n");
                free(frames[i]->payload);
                free(frames[i]);
                for (size_t j = 0; j < i; ++j) {
                    free(frames[j]->payload);
                    free(frames[j]);
                }
                free(frames);
                pthread_mutex_unlock(&frame_metadata_lock);
                return NULL;
            }
        }
    }

    pthread_mutex_unlock(&frame_metadata_lock);

    // Return array of pointers to FrameMetadata
    return frames;
}

int simulate_network_fetch() {
