int initialize_dynamic_array(DynamicArray* dynamic_array) {
    dynamic_array->array = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynamic_array->array) return -1; // Memory allocation failed
    dynamic_array->capacity = INITIAL_CAPACITY;
