    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    time_t timestamp;
    unsigned int reference_count;
    struct Node* next; // Pointer to the next node in LRU list
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    LTE_ENB_MESSAGE* head;
    LTE_ENB_MESSAGE* tail;
    size_t count;
    pthread_mutex_t lock;
} LTE_ENB_LIST;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* nodes[MAX_NFAPI_CRC_INDICATION_PDU];
    size_t size;
    pthread_mutex_t lock;
} LRU_CACHE;

// External logging function (simulated)
void log_message(const char* message) {
    printf("%s\n", message);
}

// Function prototypes
int add_lte_enb_message(LTE_ENB_LIST* list, LTE_ENB_MESSAGE* new_message);
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int tag1, int rnti, int tag2);
void lru_cache_insert(LRU_CACHE* cache, NFAPI_CRC_INDICATION_PDU_T* pdu);
NFAPI_CRC_INDICATION_PDU_T* lru_cache_evict(LRU_CACHE* cache);

// Function implementations
int add_lte_enb_message(LTE_ENB_LIST* list, LTE_ENB_MESSAGE* new_message) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_LTE_ENB_MESSAGES) {
        log_message("Failed to allocate: LTE_ENB_MESSAGE list is full.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    for (LTE_ENB_MESSAGE* current = list->head; current != NULL; current = current->next) {
        if (strcmp(current->IMSI, new_message->IMSI) == 0) {
            log_message("Failed to allocate: Duplicate IMSI detected.");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    LTE_ENB_MESSAGE* node = malloc(sizeof(LTE_ENB_MESSAGE));
    if (!node) {
        log_message("Memory allocation failed for LTE_ENB_MESSAGE.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    memcpy(node, new_message, sizeof(LTE_ENB_MESSAGE));

    node->next = NULL;
    if (list->tail) {
        list->tail->next = node;
    }
    list->tail = node;

    if (!list->head) {
        list->head = node;
    }

    list->count++;
    log_message("Successfully allocated LTE_ENB_MESSAGE.");

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int tag1, int rnti, int tag2) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        log_message("Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T.");
        return NULL;
    }

    pdu->RX_UE_INFORMATION_TAG = tag1;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = tag2;
    pdu->timestamp = time(NULL);
    pdu->reference_count = 1;
    pdu->next = NULL;

    log_message("Successfully allocated NFAPI_CRC_INDICATION_PDU_T.");
    return pdu;
}

void lru_cache_insert(LRU_CACHE* cache, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&cache->lock);

    if (cache->size >= MAX_NFAPI_CRC_INDICATION_PDU) {
        log_message("LRU Cache is full. Evicting an entry.");
        lru_cache_evict(cache);
    }

    cache->nodes[cache->size % MAX_NFAPI_CRC_INDICATION_PDU] = pdu;
    cache->size++;

    pthread_mutex_unlock(&cache->lock);
}

NFAPI_CRC_INDICATION_PDU_T* lru_cache_evict(LRU_CACHE* cache) {
    if (cache->size == 0) {
        log_message("LRU Cache is empty. Cannot evict.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* evicted_pdu = cache->nodes[(cache->size - 1) % MAX_NFAPI_CRC_INDICATION_PDU];
    if (evicted_pdu) {
        free(evicted_pdu);
        log_message("Evicted an entry from LRU Cache.");
    }

    pthread_mutex_lock(&cache->lock);
    for (size_t i = cache->size - 1; i > 0; --i) {
        cache->nodes[i % MAX_NFAPI_CRC_INDICATION_PDU] = cache->nodes[(i - 1) % MAX_NFAPI_CRC_INDICATION_PDU];
    }
    cache->nodes[0] = NULL;
    cache->size--;
    pthread_mutex_unlock(&cache->lock);

    return evicted_pdu;
}

// Initialize the lists
void init_lte_enb_list(LTE_ENB_LIST* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void init_lru_cache(LRU_CACHE* cache) {
    memset(cache->nodes, 0, sizeof(cache->nodes));
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
}
