    int rx_ue_tags[MAX_LIST_SIZE] = {0};
    pthread_mutex_lock(&list_mutex);

    NFAPI_CRC_INDICATION_PDU_T *current = head;
    for (int i = 1; i < num_nodes; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = custom_alloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            perror("Memory allocation failed for node");
            while (current != NULL) {
                NFAPI_CRC_INDICATION_PDU_T *temp = current;
                current = current->next;
                custom_free(temp);
            }
            pthread_mutex_unlock(&list_mutex);
            return NULL;
        }

        int tag = rand() % MAX_LIST_SIZE + 1;
        while (rx_ue_tags[tag - 1] != 0) {
            tag = (tag % MAX_LIST_SIZE) + 1;
        }

        new_node->RX_UE_INFORMATION_TAG = tag;
        rx_ue_tags[tag - 1] = 1;
        new_node->RNTI = rand();
        new_node->crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
        new_node->next = NULL;

        current->next = new_node;
        current = new_node;
    }

    pthread_mutex_unlock(&list_mutex);

    return head;
}

int validate_linked_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    if (!head) return -1;

    int seen_tags[MAX_LIST_SIZE] = {0};
    NFAPI_CRC_INDICATION_PDU_T *current = head;

    while (current != NULL) {
        if (seen_tags[current->RX_UE_INFORMATION_TAG - 1] == 1 ||
            current->RX_UE_INFORMATION_TAG <= 0 || 
            current->RNTI <= 0 || 
            (current->crc_tag.CRCFLAG != 0 && current->crc_tag.CRCFLAG != 1)) {
            return 0;
        }

        seen_tags[current->RX_UE_INFORMATION_TAG - 1] = 1;
        current = current->next;
    }

    // Check for duplicates
    memset(seen_tags, 0, sizeof(seen_tags));
    current = head;

    while (current != NULL) {
        if (seen_tags[current->RX_UE_INFORMATION_TAG - 1] == 1) {
            return 0;
        }
        seen_tags[current->RX_UE_INFORMATION_TAG - 1] = 1;
        current = current->next;
    }

    return 1; // List is valid
}

void free_linked_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    while (head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        head = head->next;
        custom_free(temp);
    }
}
