#include "loguru.hpp"

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int crcIndicationRel8Tag;
    CRC_INDICATION_REL8_TAG *crcIndicationRel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Initialize the logging library
void init_logging() {
    loguru::init(argc, argv);
}

// Function to allocate and initialize memory for an array of structures
NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_structures(size_t N) {
    if (N <= 0) {
        LOG_F(ERROR, "Invalid number of elements: %zu", N);
        return NULL;
    }

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        LOG_F(ERROR, "Memory allocation failed for %zu elements", N);
        return NULL;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < N; ++i) {
        array[i].crcIndicationRel8Tag = (unsigned int)i + 1; // Unique tag
        array[i].crcIndicationRel8 = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));

        if (!array[i].crcIndicationRel8) {
            LOG_F(ERROR, "Memory allocation failed for CRC_INDICATION_REL8_TAG at index %zu", i);
            // Cleanup previously allocated structures
            while (--i >= 0) {
                free(array[i].crcIndicationRel8);
            }
            free(array);
            return NULL;
        }

        array[i].crcIndicationRel8->RX_UE_INFORMATION_TAG = (unsigned int)i + 1; // Unique tag
        array[i].crcIndicationRel8->RNTI = (unsigned int)(i * 100) + 1; // Example RNTI
    }

    LOG_F(INFO, "Successfully allocated and initialized %zu structures", N);

    return array;
}

// Function to validate the integrity of the allocated structures
int validate_structures(NFAPI_CRC_INDICATION_PDU_T* array, size_t N) {
    if (!array) {
        LOG_F(ERROR, "Invalid structure pointer");
        return -1;
    }

    for (size_t i = 0; i < N; ++i) {
        if (!array[i].crcIndicationRel8 || 
            array[i].crcIndicationRel8Tag != ((unsigned int)i + 1) ||
            array[i].crcIndicationRel8->RX_UE_INFORMATION_TAG != ((unsigned int)i + 1)) {
            LOG_F(ERROR, "Validation failed at index %zu", i);
            return -1;
        }
    }

    LOG_F(INFO, "All structures validated successfully");
    return 0;
}

// Example of unsafe code
void* allocate_unsafe(size_t N) {
    if (N <= 0)
        return NULL;

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array)
        return NULL;

    for (size_t i = 0; i < N; ++i) {
        array[i].crcIndicationRel8Tag = (unsigned int)i + 1;
        array[i].crcIndicationRel8 = malloc(sizeof(CRC_INDICATION_REL8_TAG));

        // No error checking after allocation
        array[i].crcIndicationRel8->RX_UE_INFORMATION_TAG = (unsigned int)i + 1;
        array[i].crcIndicationRel8->RNTI = (unsigned int)(i * 100) + 1;
    }

    return array;
}

int main(int argc, char* argv[]) {
    init_logging();

    size_t N = 10; // Example number of elements
    NFAPI_CRC_INDICATION_PDU_T *structures = allocate_and_initialize_structures(N);

    if (validate_structures(structures, N) == 0) {
        LOG_F(INFO, "Structures are valid");
    } else {
        LOG_F(ERROR, "Structure validation failed");
    }

    // Cleanup
    for (size_t i = 0; i < N; ++i) {
        free(structures[i].crcIndicationRel8);
    }
    free(structures);

    return 0;
}
