['Below is a C implementation of a doubly-linked list for `NFAPI_CRC_INDICATION_PDU_T` structures, incorporating thread safety, memory management, and dynamic resizing:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t count;
    pthread_mutex_t mutex;
} CRC_LIST;

CRC_LIST* create_crc_list() {
    CRC_LIST *list = (CRC_LIST*)malloc(sizeof(CRC_LIST));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void free_crc_list(CRC_LIST *list) {
    if (!list) return;

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int insert_crc_pdu(CRC_LIST *list, uint32_t rx_ue_tag, uint16_t rnti) {
    if (!list) return -1;

    pthread_mutex_lock(&list->mutex);

    // Check for duplicate RX_UE_INFORMATION_TAG
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        if (current->RX_UE_INFORMATION_TAG == rx_ue_tag) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Duplicate found
        }
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failed
    }

    new_pdu->RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_pdu->RNTI = rnti;
    srand((unsigned int)time(NULL)); // Seed for randomness
    new_pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    new_pdu->prev = list->tail;
    new_pdu->next = NULL;

    if (list->tail) {
        list->tail->next = new_pdu;
    } else {
        list->head = new_pdu;
    }

    list->tail = new_pdu;
    list->count++;

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

void remove_crc_pdu(CRC_LIST *list, uint32_t rx_ue_tag) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current && current->RX_UE_INFORMATION_TAG != rx_ue_tag) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->mutex);
        return; // Not found
    }

    if (current->prev) {
        current->prev->next = current->next;
    } else {
        list->head = current->next;
    }

    if (current->next) {
        current->next->prev = current->prev;
    } else {
        list->tail = current->prev;
    }

    free(current);
    list->count--;

    pthread_mutex_unlock(&list->mutex);
}

void print_crc_list(CRC_LIST *list) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        printf("RX_UE_TAG: %u, RNTI: %u, CRCFLAG: %d\n",
               current->RX_UE_INFORMATION_TAG,
               current->RNTI,
               current->CRC_INDICATION_REL8_TAG.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

// Example unit test function
void test_crc_list() {
    CRC_LIST *list = create_crc_list();
    if (!list) {
        printf("Failed to create list\n");
        return;
    }

    insert_crc_pdu(list, 1, 100);
    insert_crc_pdu(list, 2, 200);
    insert_crc_pdu(list, 3, 300);

    print_crc_list(list);

    remove_crc_pdu(list, 2);
    print_crc_list(list);

    free_crc_list(list);
}

int main() {
    test_crc_list();
    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations.
- **Memory Management**: Allocates and frees memory for list nodes, checking for allocation failures.
- **Duplicate Check**: Prevents insertion of duplicate `RX_UE_INFORMATION_TAG`.
- **Dynamic Resizing**: Automatically handles resizing as new elements are added.
- **Random CRCFLAG**: Sets a random value for `CRCFLAG` using `rand()`.
- **Unit Test**: Includes a simple test function to demonstrate functionality.']

