    char network_type[4]; // "IPv4" or "IPv6"
    union {
        struct in_addr ipv4_address;
        struct in6_addr ipv6_address;
    } ip_address;

    struct NetworkAddress* prev;
    struct NetworkAddress* next;
} NetworkAddress;

// Function prototypes
NFAPI_CRC_INDICATION_PDU* init_doubly_linked_list(int num_entries, int rnti);
NetworkAddress* init_network_addresses(const char* hostname, size_t max_entries);
void free_crc_indication_list(NFAPI_CRC_INDICATION_PDU* head);
void free_network_address_list(NetworkAddress* head);

// Mutex for thread safety
pthread_mutex_t crc_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t network_lock = PTHREAD_MUTEX_INITIALIZER;

// Custom memory allocation strategy (placeholder)
void* custom_alloc(size_t size) {
    return malloc(size); // Replace with a custom allocator if needed
}

// Function to initialize and populate the doubly linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU* init_doubly_linked_list(int num_entries, int rnti) {
    pthread_mutex_lock(&crc_lock);

    NFAPI_CRC_INDICATION_PDU *head = NULL, *tail = NULL;
    for (int i = 0; i < num_entries; ++i) {
        NFAPI_CRC_INDICATION_PDU *node = custom_alloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        if (!node) {
            perror("Memory allocation failed");
            free_crc_indication_list(head);
            pthread_mutex_unlock(&crc_lock);
            return NULL;
        }

        node->RX_UE_INFORMATION_TAG = rand(); // Assign a unique tag
        node->RNTI = rnti;
        node->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

        if (head == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
    }

    pthread_mutex_unlock(&crc_lock);
    return head;
}

// Helper function to free the doubly linked list
void free_crc_indication_list(NFAPI_CRC_INDICATION_PDU* head) {
    NFAPI_CRC_INDICATION_PDU *current = head, *next;

    while (current != NULL) {
        next = current->next;
        custom_free(current);
        current = next;
    }
}

// Function to initialize and populate the list of NetworkAddress structures
NetworkAddress* init_network_addresses(const char* hostname, size_t max_entries) {
    pthread_mutex_lock(&network_lock);

    NetworkAddress *head = NULL, *tail = NULL;
    for (size_t i = 0; i < max_entries; ++i) {
        NetworkAddress *node = custom_alloc(sizeof(NetworkAddress));
        if (!node) {
            perror("Memory allocation failed");
            free_network_address_list(head);
            pthread_mutex_unlock(&network_lock);
            return NULL;
        }

        node->id = rand(); // Assign a unique ID
        strcpy(node->network_type, "IPv4"); // Assume IPv4 for simplicity

        struct addrinfo hints, *res, *p;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
        hints.ai_socktype = SOCK_STREAM;

        int status = getaddrinfo(hostname, NULL, &hints, &res);
        if (status != 0) {
            fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
            custom_free(node);
            free_network_address_list(head);
            pthread_mutex_unlock(&network_lock);
            return NULL;
        }

        for (p = res; p != NULL; p = p->ai_next) {
            if (p->ai_family == AF_INET) {
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                memcpy(&node->ip_address.ipv4_address, &ipv4->sin_addr, sizeof(struct in_addr));
            } else if (p->ai_family == AF_INET6) {
                struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                memcpy(&node->ip_address.ipv6_address, &ipv6->sin6_addr, sizeof(struct in6_addr));
            }
        }

        freeaddrinfo(res);

        if (head == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
    }

    pthread_mutex_unlock(&network_lock);
    return head;
}

// Helper function to free the network address list
void free_network_address_list(NetworkAddress* head) {
    NetworkAddress *current = head, *next;

    while (current != NULL) {
        next = current->next;
        custom_free(current);
        current = next;
    }
}

