    size_t memory_limit; // in bytes
} UEManager;

void initialize_UEManager(UEManager *manager, const char *file_path, size_t initial_capacity, size_t memory_limit) {
    manager->contexts = NULL;
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->storage_file = fopen(file_path, "w+b");
    if (!manager->storage_file) {
        perror("Failed to open storage file");
        exit(EXIT_FAILURE);
    }
    manager->memory_limit = memory_limit;
}

void destroy_UEManager(UEManager *manager) {
    UEContext *current_context, *tmp_context;
    HASH_ITER(hh, manager->contexts, current_context, tmp_context) {
        HASH_DEL(manager->contexts, current_context);
        free(current_context);
    }
    fclose(manager->storage_file);
}

void add_UEContext(UEManager *manager, int rrc_id, int mac_id, L1Metrics metrics, UECriteria criteria) {
    UEContext *context = malloc(sizeof(UEContext));
    if (!context) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    context->rrc_connection_id = rrc_id;
    context->mac_entity_id = mac_id;
    context->l1_metrics = metrics;
    context->criteria = criteria;

    HASH_ADD_INT(manager->contexts, rrc_connection_id, context);
    manager->count++;
}

void remove_UEContext(UEManager *manager, int rrc_id) {
    UEContext *context, tmp_context;
    int found = 0;

    HASH_FIND_INT(manager->contexts, &rrc_id, context);
    if (context) {
        HASH_DEL(manager->contexts, context);
        free(context);
        manager->count--;
        found = 1;
    }

    if (!found) {
        fprintf(stderr, "UE Context not found\n");
    }
}

