void manage_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T **array, int *size, int *capacity) {
    const int INITIAL_CAPACITY = 10000;
    const float GROWTH_FACTOR = 1.5;
    const float SHRINK_THRESHOLD = 0.25;

    if (*array == NULL && *capacity < INITIAL_CAPACITY) {
        // Initial allocation
        *capacity = INITIAL_CAPACITY;
        *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(*capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
