        (*array)[i].crc_indication.CRCFLAG = rand() % 2;  // Randomly set CRCFLAG to 0 or 1
    }

    if (*size >= *capacity) {
        // Need to grow the array
        int new_capacity = (int)(*capacity * GROWTH_FACTOR);
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(*array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            fprintf(stderr, "Memory allocation failed during resizing\n");
            exit(EXIT_FAILURE);
        }
        *array = new_array;
        *capacity = new_capacity;
    } else if (*size <= *capacity * SHRINK_THRESHOLD && *capacity > INITIAL_CAPACITY / GROWTH_FACTOR) {
        // Reclaim memory if usage is significantly low
        int new_capacity = (int)(*capacity / GROWTH_FACTOR);
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(*array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            fprintf(stderr, "Memory allocation failed during shrinking\n");
            // Do not exit, try to continue with the old array
        } else {
            *array = new_array;
            *capacity = new_capacity;
        }
    }

    // Initial population example - this should be replaced by actual logic as needed
    for (int i = 0; i < *size; ++i) {
        (*array)[i].ue_info.RX_UE_INFORMATION_TAG = rand() % 1000;  // Example values
