['Below is a high-performance C function to manage a dynamic list of LTE UE Context Information structures. It includes memory management strategies, thread-safety with mutexes, batch allocation, and data validation.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 50000

typedef struct {
    unsigned char* mac_pdu;   // Pointer to MAC PDU data
    int length;               // Length of the MAC PDU
    unsigned long rnti;       // RNTI associated with the packet
} LTEContextInfo;

typedef struct {
    LTEContextInfo* elements;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} LTEContextList;

void initialize_list(LTEContextList* list, size_t initial_capacity) {
    list->elements = (LTEContextInfo*)malloc(initial_capacity * sizeof(LTEContextInfo));
    if (!list->elements) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void resize_list_if_needed(LTEContextList* list) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity && list->capacity < MAX_ELEMENTS) {
        size_t new_capacity = list->capacity * 2;
        LTEContextInfo* new_elements = (LTEContextInfo*)realloc(list->elements, new_capacity * sizeof(LTEContextInfo));
        if (!new_elements) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    pthread_mutex_unlock(&list->mutex);
}

int add_context_info(LTEContextList* list, const unsigned char* mac_pdu, int length, unsigned long rnti) {
    pthread_mutex_lock(&list->mutex);

    if (length <= 0 || !mac_pdu) { // Basic validation
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    resize_list_if_needed(list);

    list->elements[list->count].mac_pdu = malloc(length);
    if (!list->elements[list->count].mac_pdu) {
        perror("Failed to allocate memory for MAC PDU");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    memcpy(list->elements[list->count].mac_pdu, mac_pdu, length);
    list->elements[list->count].length = length;
    list->elements[list->count].rnti = rnti;

    ++list->count;
    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

void cleanup_list(LTEContextList* list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->elements[i].mac_pdu);
    }
    free(list->elements);
    pthread_mutex_unlock(&list->mutex);

    pthread_mutex_destroy(&list->mutex);
}

void process_packets(LTEContextList* list, const unsigned char** packets, int* lengths, unsigned long* rntis, size_t packet_count) {
    for (size_t i = 0; i < packet_count; ++i) {
        add_context_info(list, packets[i], lengths[i], rntis[i]);
    }
}

int main() {
    LTEContextList context_list;
    initialize_list(&context_list, 1024);

    // Example usage
    const unsigned char* sample_packets[] = { /* ... packet data pointers ... */ };
    int sample_lengths[] = { /* ... packet lengths ... */ };
    unsigned long sample_rntis[] = { /* ... RNTI values ... */ };

    process_packets(&context_list, sample_packets, sample_lengths, sample_rntis, sizeof(sample_packets) / sizeof(sample_packets[0]));

    cleanup_list(&context_list);

    return 0;
}
```

### Key Features:
- **Thread Safety**: Utilizes a mutex to protect shared resources.
- **Dynamic Resizing**: Doubles the capacity when needed, up to a maximum limit.
- **Batch Allocation**: Reduces overhead by resizing less frequently.
- **Validation Checks**: Ensures valid packet data before adding it to the list.
- **Memory Management**: Frees allocated memory to prevent leaks.
- **Cache-Friendly Design**: Keeps related data together for better cache performance.']

