#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define PacketHeader structure
typedef struct {
    unsigned char src_ip[4];
    unsigned char dst_ip[4];
    unsigned short protocol;
    unsigned int payload_length;
} PacketHeader;

// Linked list node for PacketHeader
typedef struct Node {
    PacketHeader header;
    struct Node* next;
} Node;

// Function to calculate IP checksum (simplified version)
unsigned short calculateIPChecksum(unsigned char *addr) {
    unsigned long sum = 0;
    for (int i = 0; i < 4; i++) {
        sum += ((unsigned int)addr[i] << 8) + addr[i];
    }
    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return ~((unsigned short)sum);
}

// Function to validate PacketHeader
int isValidPacketHeader(PacketHeader *header) {
    if (header == NULL) return 0;

    // Check IP checksums
    if (calculateIPChecksum(header->src_ip) != 0xFFFF || 
        calculateIPChecksum(header->dst_ip) != 0xFFFF) {
        return 0;
    }

    // Ensure protocol type is within valid range
    if (header->protocol < 1 || header->protocol > 255) {
        return 0;
    }

    // Check payload length is positive
    if (header->payload_length <= 0) {
        return 0;
    }

    return 1;
}

// Function to insert a PacketHeader into the list
Node* insertPacketHeader(Node *head, PacketHeader header) {
    if (!isValidPacketHeader(&header)) {
        fprintf(stderr, "Invalid packet header\n");
        return head;
    }

    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        return head;
    }

    memcpy(&(new_node->header), &header, sizeof(PacketHeader));
    new_node->next = head;

    return new_node;
}

// Function to free the linked list
void freePacketList(Node *head) {
    Node *tmp;
    while (head != NULL) {
        tmp = head;
        head = head->next;
        free(tmp);
    }
}

// Example usage of the functions
int main() {
    Node *packet_list = NULL;

    PacketHeader packet1 = {{192, 168, 0, 1}, {10, 0, 0, 2}, 6, 512};
    PacketHeader packet2 = {{172, 16, 0, 3}, {192, 0, 2, 1}, 17, 1024};

    // Simulate inserting packets into the list
    packet_list = insertPacketHeader(packet_list, packet1);
    packet_list = insertPacketHeader(packet_list, packet2);

    // Free the list when done
    freePacketList(packet_list);

    return 0;
}
```']

