#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_NODES 1024

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} NodeList;

void initialize_node_list(NodeList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_node(unsigned int tag, unsigned int rnti, unsigned char crcflag) {
    NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    node->RX_UE_INFORMATION_TAG = tag;
    node->RNTI = rnti;
    node->crc_tag.CRCFLAG = crcflag;
    node->next = NULL;
    return node;
}

void add_node(NodeList *list, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = node;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_node_list(NodeList *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void print_node_list(NodeList *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n",
               current->RX_UE_INFORMATION_TAG,
               current->RNTI,
               current->crc_tag.CRCFLAG);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void simulate_external_data_source(NodeList *list) {
    for (int i = 0; i < MAX_NODES; ++i) {
        unsigned int tag = rand();
        unsigned int rnti = rand() % 1024;
        unsigned char crcflag = rand() & 1;
        NFAPI_CRC_INDICATION_PDU_T *node = create_node(tag, rnti, crcflag);
        add_node(list, node);
    }
}

int main() {
    NodeList list;
    initialize_node_list(&list);

    simulate_external_data_source(&list);
    print_node_list(&list);

    free_node_list(&list);
    return 0;
}
