typedef struct {
    uint8_t data[MAX_DCI_LENGTH];
    size_t length;
} DCI;

typedef struct Frame {
    // Define frame structure as needed
} Frame;

typedef struct Slot {
    // Define slot structure as needed
} Slot;

typedef struct Packet {
    Frame frame;
    Slot slot;
    DCI dci;
    struct Packet* next;
} Packet;

Packet* create_packet() {
    Packet* packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) {
        perror("Failed to allocate memory for Packet");
        exit(EXIT_FAILURE);
    }
    packet->next = NULL;
    // Initialize frame and slot as needed
    return packet;
}

void free_packets(Packet** head) {
    Packet* current = *head;
    Packet* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int validate_dci(DCI* dci) {
    return dci->length <= MAX_DCI_LENGTH;
}

void generate_dci(DCI* dci, int bandwidth_part, int numerology, int modulation_scheme) {
    if (!validate_dci(dci)) {
        fprintf(stderr, "DCI length exceeds maximum allowed\n");
        exit(EXIT_FAILURE);
    }
    // Generate DCI data based on parameters
    dci->length = 10; // Example length
}

void serialize_packets(Packet* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    Packet* current = head;
    while (current != NULL) {
        fwrite(&current->dci.length, sizeof(current->dci.length), 1, file);
        fwrite(current->dci.data, sizeof(current->dci.data[0]), current->dci.length, file);
        current = current->next;
    }

    fclose(file);
}

Packet* deserialize_packets(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return NULL;
    }

    Packet* head = NULL;
    Packet** tail = &head;

    while (1) {
        DCI dci;
        size_t read_length = fread(&dci.length, sizeof(dci.length), 1, file);
        if (read_length == 0) break; // End of file

        if (!validate_dci(&dci)) {
            fprintf(stderr, "Invalid DCI length during deserialization\n");
            free_packets(&head);
            fclose(file);
            return NULL;
        }

        read_length = fread(dci.data, sizeof(dci.data[0]), dci.length, file);
        if (read_length != dci.length) {
            fprintf(stderr, "Error reading DCI data\n");
            free_packets(&head);
            fclose(file);
            return NULL;
        }

        Packet* packet = create_packet();
        packet->dci = dci;
        *tail = packet;
        tail = &packet->next;
    }

    fclose(file);
    return head;
}

int main() {
    Packet* head = NULL;

    // Example of creating and linking packets
    for (int i = 0; i < 1000; ++i) {
        Packet* packet = create_packet();
        generate_dci(&packet->dci, BANDWIDTH_PARTS, NUMEROLOGY, MODULATION_SCHEMES);
        packet->next = head;
        head = packet;
    }

    serialize_packets(head, "packets.bin");
    free_packets(&head);

    head = deserialize_packets("packets.bin");
    if (head) {
        // Process deserialized packets
        free_packets(&head);
    }

    return 0;
}
```

