unsigned int calculate_checksum1(const unsigned char* data, size_t length) {
    unsigned int checksum = 0;
    for(size_t i = 0; i < length; ++i) {
        checksum += data[i];
    }
    return checksum & 0xFFFFFFFF;
}

// Thread-safe cache fetch
int get_metadata_from_cache(char *rnti, char **metadata, size_t *length) {
    pthread_mutex_lock(&cache_lock);

    for (size_t i = 0; i < CACHE_SIZE; ++i) {
        if (strcmp(metadata_cache[i].metadata, rnti) == 0) {
            *metadata = metadata_cache[i].metadata;
            *length = metadata_cache[i].length;
            pthread_mutex_unlock(&cache_lock);
            return 1;
        }
    }

    // Fetch metadata and update cache
    char* new_metadata;
    fetch_metadata_stub(rnti, &new_metadata, length);

    for (size_t i = 0; i < CACHE_SIZE; ++i) {
        if (!metadata_cache[i].metadata) { // find empty spot or overwrite
            metadata_cache[i].metadata = new_metadata;
            pthread_mutex_unlock(&cache_lock);
            return 1;
        }
    }

    // Cache is full, overwrite the first entry (simple strategy)
    free(metadata_cache[0].metadata);
    metadata_cache[0].metadata = new_metadata;

    pthread_mutex_unlock(&cache_lock);
    return 1;
}

// Validate RNTI and RX tag
