        if (tags->rnti_tags[i].rnti == rnti) {
            return 1;
        }
    }
    return 0;
}

// Main function to manage and populate MAC_RX_FRAME array
MAC_RX_FRAME* manage_mac_rx_frame_array(RX_UE_INFORMATION_TAGS *tags, int enable_logging,
                                        char* checksum_algo, size_t num_frames, int* frame_count) {
    MAC_RX_FRAME *frames = malloc(num_frames * sizeof(MAC_RX_FRAME));
    if (!frames) {
        perror("Memory allocation failed");
        return NULL;
    }
    memset(frames, 0, num_frames * sizeof(MAC_RX_FRAME));

    for (size_t i = 0; i < tags->count; ++i) {
        int rnti = tags->rnti_tags[i].rnti;

        if (!validate_rnti_and_tag(tags, rnti)) continue;

        MAC_RX_FRAME *frame = &frames[*frame_count];
        char* metadata;
