typedef struct {
    char ue_id[MAX_UE_ID_LENGTH + 1];
    unsigned long s_tmsi;
    PDNConnection pdn_connections[MAX_PDN_CONNECTIONS];
    int num_pdn_connections;
} LTEUEContext;

typedef struct {
    LTEUEContext* contexts;
    size_t capacity;
    pthread_mutex_t lock;
} LTEUENetworkManager;

// Function declarations
int add_ue_context(LTEUENetworkManager* manager, const char* ue_id, unsigned long s_tmsi, PDNConnection* pdn_connections, int num_pdn_connections);
void free_lte_ue_network_manager(LTEUENetworkManager* manager);

int add_ue_context(LTEUENetworkManager* manager, const char* ue_id, unsigned long s_tmsi, PDNConnection* pdn_connections, int num_pdn_connections) {
    pthread_mutex_lock(&manager->lock);

    // Validate UE ID uniqueness
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (strcmp(manager->contexts[i].ue_id, ue_id) == 0) {
            LOG_ERROR("UE ID %s already exists.\n", ue_id);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    // Allocate or reallocate memory
    size_t new_capacity = manager->capacity + 1;
    LTEUEContext* new_contexts = realloc(manager->contexts, new_capacity * sizeof(LTEUEContext));
    if (!new_contexts) {
        LOG_ERROR("Memory allocation failed.\n");
        pthread_mutex_unlock(&manager->lock);
        return -2;
    }

    // Update context manager
    manager->contexts = new_contexts;
    manager->capacity = new_capacity;

    LTEUEContext* new_context = &manager->contexts[manager->capacity - 1];
    strncpy(new_context->ue_id, ue_id, MAX_UE_ID_LENGTH);
    new_context->ue_id[MAX_UE_ID_LENGTH] = '\0';
    new_context->s_tmsi = s_tmsi;
    memcpy(new_context->pdn_connections, pdn_connections, num_pdn_connections * sizeof(PDNConnection));
    new_context->num_pdn_connections = num_pdn_connections;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void free_lte_ue_network_manager(LTEUENetworkManager* manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->contexts) {
        free(manager->contexts);
        manager->contexts = NULL;
        manager->capacity = 0;
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    LTEUENetworkManager manager = { .contexts = NULL, .capacity = 0 };
    pthread_mutex_init(&manager.lock, NULL);

    PDNConnection pdn_connections[2] = {
        {"192.168.1.10", 5},
        {"192.168.1.11", 10}
    };

    if (add_ue_context(&manager, "UE12345", 67890, pdn_connections, 2) != 0) {
        LOG_ERROR("Failed to add UE context.\n");
    }

    free_lte_ue_network_manager(&manager);
    pthread_mutex_destroy(&manager.lock);

    return 0;
}
```

