typedef struct {
    uint32_t RNTI;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint16_t CRC_INDICATION_REL8_TAG;
    // Other fields...
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node for the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    atomic_uint64_t size;  // For concurrent access
    pthread_mutex_t lock;  // Mutex for unique RNTI generation
    Node* head;
    Node* tail;
} NFAPICRCDynamicList;

// Error codes
#define SUCCESS 0
#define ALLOCATION_FAILURE -1

NFAPICRCDynamicList* init_nfa_crc_ind_list(size_t num_entries) {
    if (num_entries == 0)
        return NULL;

    NFAPICRCDynamicList* list = (NFAPICRCDynamicList*)malloc(sizeof(NFAPICRCDynamicList));
    if (!list) return NULL;

    atomic_init(&list->size, 0);
    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;

    uint32_t rnti_set[256] = {0}; // Assuming max RNTI values that can be managed are less than 256 for simplicity

    Node* prev_node = NULL;
    for (size_t i = 0; i < num_entries; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            // Clean up on failure
            while (prev_node != NULL) {
                Node* temp = prev_node->next;
                free(prev_node);
                prev_node = temp;
            }
            pthread_mutex_destroy(&list->lock);
            free(list);
            return (NFAPICRCDynamicList*)ALLOCATION_FAILURE;
        }

        // Generate a unique RNTI
        pthread_mutex_lock(&list->lock);
        uint32_t rnti;
        do {
            rnti = rand() % 256;  // Example range, adjust as needed
        } while (rnti_set[rnti] != 0);

        rnti_set[rnti] = 1;
        pthread_mutex_unlock(&list->lock);

        new_node->pdu.RNTI = rnti;
        new_node->pdu.ue_info_tag.RNTI = rnti; // Assume fields are filled similarly
        new_node->pdu.crc_indication_rel8_tag.CRC_INDICATION_REL8_TAG = rand() % 65536;
        new_node->pdu.CRCFLAG = rand() % 2;

        new_node->next = NULL;
        if (list->tail) {
            list->tail->next = new_node;
        } else {
            list->head = new_node;
        }
        list->tail = new_node;
        prev_node = new_node;

        atomic_fetch_add(&list->size, 1);
    }

    return list;
}

// Function to validate the integrity of the list
int validate_nfa_crc_ind_list(NFAPICRCDynamicList* list) {
    if (!list || !list->head)
        return -1; // Invalid list

    uint32_t rnti_set[256] = {0};
    Node* current = list->head;
    while (current) {
        if (rnti_set[current->pdu.RNTI] != 0) {
            return -2; // Duplicate RNTI found
        }
        rnti_set[current->pdu.RNTI] = 1;

        if (!current->pdu.ue_info_tag.RNTI || !current->pdu.crc_indication_rel8_tag.CRC_INDICATION_REL8_TAG) {
            return -3; // Invalid fields detected
        }
        current = current->next;
    }

    uint64_t expected_size = atomic_load(&list->size);
    Node* counter = list->head;
    size_t actual_size = 0;
    while (counter) {
        ++actual_size;
        counter = counter->next;
    }

    if (expected_size != actual_size)
        return -4; // Size mismatch

    return SUCCESS;
}

// Free the allocated memory for the list
void free_nfa_crc_ind_list(NFAPICRCDynamicList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
