#define MAX_ELEMENTS 1024

typedef struct {
    // Define the structure fields
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG; // Randomly set
    } CRC_INDICATION_REL8_TAG;
    time_t timestamp; // Timestamp when added
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_LIST;

