void init_list(NFAPI_LIST *list) {
    list->data = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to add an element to the list
int add_element(NFAPI_LIST *list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size + 1));
    if (!new_data) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    list->data = new_data;

    NFAPI_CRC_INDICATION_PDU_T *element = &list->data[list->size];
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    srand(time(NULL) + list->size); // Seed with time and size for randomness
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    element->timestamp = time(NULL);

    list->size++;
    pthread_mutex_unlock(&list->lock);
    return list->size;
}

