    if (difftime(current_time, list->last_op_timestamp) < 1.0 / (double)list->max_operations_per_second) {
        list->operation_count++;
        if (list->operation_count >= list->max_operations_per_second) {
            log_message("Reached max operations per second limit.");
            return;
        }
    } else {
        list->last_op_timestamp = current_time;
        list->operation_count = 0;
    }

