    }

    new_node->RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_node->RNTI = rnti;
    new_node->crc_indication_rel8.CRCFLAG = rand() % 2; // Random CRCFLAG
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    log_message("CRC indication added successfully.");
    pthread_mutex_unlock(&list->lock);
}

void cleanup_crc_indication_list(CRC_Indication_List *list, unsigned int threshold_time) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T **indirect = &list->head;
    while (*indirect != NULL) {
        if (difftime(current_time, (*indirect)->timestamp) > threshold_time) {
            log_message("Cleaning up outdated entry.");
            NFAPI_CRC_INDICATION_PDU_T *old_entry = *indirect;
            *indirect = old_entry->next;
            free(old_entry);
        } else {
            indirect = &(*indirect)->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

