#define MAX_RNTI 10000
#define LOG_BUFFER_SIZE 1024
#define MEMORY_THRESHOLD 1048576 // 1MB for example

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int rnti_count[MAX_RNTI];
    char log_buffer[LOG_BUFFER_SIZE];
    size_t memory_used;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    memset(list->rnti_count, 0, sizeof(list->rnti_count));
    list->memory_used = 0;

    return list;
}

void log_message(DoublyLinkedList* list, const char* message) {
    snprintf(list->log_buffer, LOG_BUFFER_SIZE, "%s", message);
    printf("%s\n", list->log_buffer);
}

int add_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || list->memory_used > MEMORY_THRESHOLD) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->rnti_count[data.RNTI] > 0) {
        char log[LOG_BUFFER_SIZE];
        snprintf(log, LOG_BUFFER_SIZE, "Duplicate RNTI detected: %d", data.RNTI);
        log_message(list, log);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }

    list->memory_used += sizeof(Node);

    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = list->head;

    if (list->head) {
        list->head->prev = new_node;
    }

    list->head = new_node;
    list->rnti_count[data.RNTI]++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void rate_limited_random_crc(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    static pthread_mutex_t crc_lock = PTHREAD_MUTEX_INITIALIZER;
    static time_t last_update = 0;

    pthread_mutex_lock(&crc_lock);

    if (difftime(time(NULL), last_update) < 1.0) { // Rate limit: 1 update per second
        pthread_mutex_unlock(&crc_lock);
        return;
    }

    data->tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    last_update = time(NULL);

    pthread_mutex_unlock(&crc_lock);
}

void remove_node(DoublyLinkedList* list, int rnti) {
    if (!list || !list->head) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current && current->data.RNTI != rnti) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (current->prev) {
        current->prev->next = current->next;
    } else {
        list->head = current->next;
    }

    if (current->next) {
        current->next->prev = current->prev;
    }

    free(current);
    list->memory_used -= sizeof(Node);
    list->rnti_count[rnti]--;

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(DoublyLinkedList* list) {
    if (!list) return;

    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free(current);
        current = next;
        list->memory_used -= sizeof(Node);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    srand(time(NULL));

    DoublyLinkedList* nfa_list = create_list();

    NFAPI_CRC_INDICATION_PDU_T data1 = { .RX_UE_INFORMATION_TAG = 100, .RNTI = 2001 };
    rate_limited_random_crc(nfa_list, &data1);
    add_node(nfa_list, data1);

    NFAPI_CRC_INDICATION_PDU_T data2 = { .RX_UE_INFORMATION_TAG = 101, .RNTI = 2002 };
    rate_limited_random_crc(nfa_list, &data2);
    add_node(nfa_list, data2);

    remove_node(nfa_list, 2001);

    destroy_list(nfa_list);

    return 0;
}
