// Custom memory pool structure
typedef struct {
    size_t elementSize;
    void* elements[MAX_STRUCTURES];
    int count;
    pthread_mutex_t lock;
} MemoryPool;

void initializeMemoryPool(MemoryPool* pool, size_t elementSize) {
    pool->elementSize = elementSize;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocateFromPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count < MAX_STRUCTURES) {
        void* element = malloc(pool->elementSize);
        if (element != NULL) {
            pool->elements[pool->count++] = element;
            pthread_mutex_unlock(&pool->lock);
            return (NFAPI_CRC_INDICATION_PDU_T*)element;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL; // Allocation failed
}

void deallocateFromPool(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->count; ++i) {
        if (pool->elements[i] == element) {
            free(element);
            memmove(&pool->elements[i], &pool->elements[i + 1],
                    sizeof(void*) * (pool->count - i - 1));
            --pool->count;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void populateNFAPICRCIndicationPDUList(int numStructures, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    MemoryPool pool;
    initializeMemoryPool(&pool, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < numStructures; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocateFromPool(&pool);
        if (!pdu) {
            // Handle memory allocation error
            break;
