        // Set CRCFLAG to a random value
        pdu->crcTag.CRCFLAG = rand() % 2; // Example: Binary flag

        callback(pdu); // Pass the structure to the callback function for processing
    }
}

void cleanupMemoryPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->count; ++i) {
        free(pool->elements[i]);
    }
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

