#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define LOG_WARNING_THRESHOLD 800

typedef struct {
    int CRCFLAG;
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* crcList;
    size_t crcCount;
} NFDataRecord;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to create a new record
NFDataRecord* create_record() {
    NFDataRecord* record = (NFDataRecord*)malloc(sizeof(NFDataRecord));
    if (!record) return NULL;
    record->crcList = NULL;
    record->crcCount = 0;
    return record;
}

// Function to add a CRC indication to a record
void add_crc_indication(NFDataRecord* record, unsigned long tag, unsigned long rnti) {
    pthread_mutex_lock(&lock);
    size_t new_count = record->crcCount + 1;
    record->crcList = realloc(record->crcList, new_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!record->crcList) {
        pthread_mutex_unlock(&lock);
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T* crcItem = &record->crcList[record->crcCount];
    crcItem->RX_UE_INFORMATION_TAG = tag;
    crcItem->RNTI = rnti;
    crcItem->CRC_INDICATION_REL8_TAG = rand() % 256; // Random CRC flag for demonstration
    crcItem->CRCFLAG = rand() % 2; // Random CRC flag
    record->crcCount = new_count;
    pthread_mutex_unlock(&lock);
}

// Function to serialize and save records to persistent storage
void save_records(NFDataRecord** records, size_t count) {
    FILE* file = fopen("records.bin", "wb");
    if (!file) return;

    fwrite(&count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < count; ++i) {
        NFDataRecord* record = records[i];
        fwrite(&record->crcCount, sizeof(size_t), 1, file);
        fwrite(record->crcList, sizeof(NFAPI_CRC_INDICATION_PDU_T), record->crcCount, file);
    }
    fclose(file);
}

// Function to load records from persistent storage
NFDataRecord** load_records(size_t* count) {
    FILE* file = fopen("records.bin", "rb");
    if (!file) return NULL;

    fread(count, sizeof(size_t), 1, file);
    NFDataRecord** records = (NFDataRecord**)malloc(*count * sizeof(NFDataRecord*));
    for (size_t i = 0; i < *count; ++i) {
        records[i] = create_record();
        fread(&records[i]->crcCount, sizeof(size_t), 1, file);
        records[i]->crcList = malloc(records[i]->crcCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        fread(records[i]->crcList, sizeof(NFAPI_CRC_INDICATION_PDU_T), records[i]->crcCount, file);
    }
    fclose(file);
    return records;
}

// Function to manage dynamic array of NFDataRecords
void manage_records() {
    static NFDataRecord** records = NULL;
    static size_t record_count = 0;
    static pthread_mutex_t count_lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&count_lock);

    if (record_count >= MAX_RECORDS) {
        printf("Warning: Maximum number of records reached.\n");
    }

    // Load records from persistent storage
    size_t loaded_count;
    NFDataRecord** loaded_records = load_records(&loaded_count);
    if (loaded_records) {
        for (size_t i = 0; i < loaded_count; ++i) {
            add_crc_indication(loaded_records[i], rand(), rand());
        }
        free(records);
        records = loaded_records;
        record_count = loaded_count;
    }

    // Add a new record if under limit
    if (record_count < MAX_RECORDS) {
        NFDataRecord* new_record = create_record();
        add_crc_indication(new_record, rand(), rand());
        records = realloc(records, (record_count + 1) * sizeof(NFDataRecord*));
        records[record_count++] = new_record;
    }

    pthread_mutex_unlock(&count_lock);

    // Save records to persistent storage
    save_records(records, record_count);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < 10; ++i) {
        manage_records();
    }

    return 0;
}
