#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_QUEUE_SIZE 1000
#define MAX_PACKETS 10000

typedef struct {
    int rrc_context_id;
    int seqno;
} DLDataPDU;

typedef void (*ProcessCallback)(DLDataPDU*);

typedef struct QueueNode {
    DLDataPDU* data;
    struct QueueNode* next;
} QueueNode;

typedef struct {
    QueueNode* head;
    QueueNode* tail;
    size_t size;
    pthread_mutex_t lock;
    ProcessCallback callback;
} DLQueue;

void initialize_queue(DLQueue* queue, ProcessCallback cb) {
    queue->head = NULL;
    queue->tail = NULL;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
    queue->callback = cb;
}

DLDataPDU* create_dl_data_pdu(int rrc_context_id, int seqno) {
    DLDataPDU* pdu = (DLDataPDU*)malloc(sizeof(DLDataPDU));
    if (!pdu) return NULL;
    pdu->rrc_context_id = rrc_context_id;
    pdu->seqno = seqno;
    return pdu;
}

void enqueue(DLQueue* queue, DLDataPDU* data) {
    pthread_mutex_lock(&queue->lock);

    QueueNode* new_node = (QueueNode*)malloc(sizeof(QueueNode));
    if (!new_node) {
        free(data);
        pthread_mutex_unlock(&queue->lock);
        return;
    }
    new_node->data = data;
    new_node->next = NULL;

    if (queue->tail) {
        queue->tail->next = new_node;
    } else {
        queue->head = new_node;
    }

    queue->tail = new_node;
    queue->size++;

    pthread_mutex_unlock(&queue->lock);
}

DLDataPDU* dequeue(DLQueue* queue) {
    pthread_mutex_lock(&queue->lock);

    if (!queue->head) {
        pthread_mutex_unlock(&queue->lock);
        return NULL;
    }

    QueueNode* node = queue->head;
    DLDataPDU* data = node->data;
    queue->head = node->next;

    if (!queue->head) {
        queue->tail = NULL;
    }

    free(node);
    queue->size--;

    pthread_mutex_unlock(&queue->lock);

    return data;
}

void process_queue(DLQueue* queue) {
    while (1) {
        DLDataPDU* pdu = dequeue(queue);
        if (!pdu) break;

        if (queue->callback) {
            queue->callback(pdu);
        }

        free(pdu);
    }
}

void adjust_queue_size(DLQueue* queue, size_t new_size) {
    pthread_mutex_lock(&queue->lock);

    while (queue->size > new_size) {
        DLDataPDU* pdu = dequeue(queue);
        if (!pdu) break;

        if (queue->callback) {
            queue->callback(pdu);
        }

        free(pdu);
    }

    pthread_mutex_unlock(&queue->lock);
}

void destroy_queue(DLQueue* queue) {
    while (dequeue(queue)) {}

    pthread_mutex_destroy(&queue->lock);
}
