typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** pool;
    size_t pool_size;
    pthread_mutex_t lock;
    Node* head;
    Node* tail;
} LinkedListPool;

void initialize_pool(LinkedListPool* list, size_t size) {
    list->pool = (Node**)malloc(size * sizeof(Node*));
    for (size_t i = 0; i < size; ++i) {
        list->pool[i] = (Node*)malloc(sizeof(Node));
    }
    pthread_mutex_init(&list->lock, NULL);
    list->pool_size = size;
    list->head = NULL;
    list->tail = NULL;
}

void destroy_pool(LinkedListPool* list) {
    for (size_t i = 0; i < list->pool_size; ++i) {
        free(list->pool[i]);
    }
    free(list->pool);
    pthread_mutex_destroy(&list->lock);
}

Node* get_node_from_pool(LinkedListPool* list) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    Node* node = list->head;
    list->head = list->head->next;
    pthread_mutex_unlock(&list->lock);
    return node;
}

void return_node_to_pool(LinkedListPool* list, Node* node) {
    pthread_mutex_lock(&list->lock);
    node->next = list->head;
    list->head = node;
    pthread_mutex_unlock(&list->lock);
}

int add_pdu_to_list(LinkedListPool* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* node = get_node_from_pool(list);
    if (!node) return -1; // Pool exhausted
    memcpy(&node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&list->lock);
    if (list->tail == NULL) {
        list->head = node;
        list->tail = node;
        node->next = NULL;
    } else {
        list->tail->next = node;
        list->tail = node;
        node->next = NULL;
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_list(LinkedListPool* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        return_node_to_pool(list, current);
        current = next;
    }
}

