}

EVP_CIPHER_CTX* initialize_aes_cipher(const char* password, const unsigned int iterations, const unsigned char* salt) {
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];

    if (1 != PKCS5_PBKDF2_HMAC(password, strlen(password), salt, 8, iterations,
                               EVP_sha256(), sizeof(key), key)) {
        return NULL;
    }

    if (!RAND_bytes(iv, sizeof(iv))) {
        return NULL;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

