#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_CAPACITY 1000
#define MAX_CAPACITY 10000

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->data = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_list(DynamicList* list) {
    if (list) {
        free(list->data);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int resize_list_if_needed(DynamicList* list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > MAX_CAPACITY) return -1;

        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return -1;

        list->data = new_data;
        list->capacity = new_capacity;
    }
    return 0;
}

int add_pdu(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    int resize_status = resize_list_if_needed(list);
    if (resize_status == -1) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->data[list->size] = pdu;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void flush_and_compress_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    size_t write_index = 0;
    for (size_t i = 0; i < list->size; ++i) {
        if (/* some condition to keep the element */) {
            list->data[write_index++] = list->data[i];
        }
    }

    list->size = write_index;

    pthread_mutex_unlock(&list->lock);
}

void update_from_external_source(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* new_data, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        add_pdu(list, new_data[i]);
    }
}

// Example usage
int main() {
    DynamicList* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

    // Simulate adding data from an external source
    NFAPI_CRC_INDICATION_PDU_T pdu_example = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 2, .crc_tag = {.CRCFLAG = rand() % 2} };
    add_pdu(list, pdu_example);

    // Periodically flush and compress the list
    flush_and_compress_list(list);

    destroy_list(list);
    return EXIT_SUCCESS;
}
```

### Key Points:

- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations on the dynamic list.
- **Dynamic Resizing**: The list doubles its capacity when needed, up to a maximum of 10,000 elements.
- **Error Handling**: Checks for memory allocation failures and handles them gracefully.
- **Performance Considerations**: Locks are used at the list level to minimize contention and improve performance.
- **Periodic Maintenance**: Includes a function to flush and compress the list based on specific conditions.']

