bool insertAtPosition(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* newNode, int position) {
    if (!newNode) return false;

    pthread_mutex_lock(&lock);

    if (position == 0 || *head == NULL) {
        newNode->next = *head;
        *head = newNode;
        pthread_mutex_unlock(&lock);
        return true;
    }

    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    int index = 0;

    while (current != NULL && index < position - 1) {
        current = current->next;
        index++;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&lock);
        free(newNode); // Fail to insert, clean up.
        return false;
    }

    newNode->next = current->next;
    current->next = newNode;

    pthread_mutex_unlock(&lock);
    return true;
}

void printList(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
