void freeList(NFAPI_CRC_INDICATION_PDU_T** head) {
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* nextNode = current->next;
        free(current);
        current = nextNode;
    }

    *head = NULL;

    pthread_mutex_unlock(&lock);
}

