EVP_CIPHER *initialize_cipher(int mode, const char *key, const char *iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    EVP_CIPHER *cipher = NULL;
    switch (mode) {
        case 1: cipher = EVP_des_ecb(); break; // ECB
        case 2: cipher = EVP_des_ede(); break; // EDE
        case 3: cipher = EVP_des_ede3(); break; // EDE3
        case 4: 
            if (iv) cipher = EVP_des_cfb128(); 
            else cipher = EVP_des_ecb();
            break;
        default: return NULL; // Null encryption or unsupported mode
    }

    int result = EVP_DecryptInit_ex(ctx, cipher, NULL, (unsigned char*)key, (unsigned char*)iv);
    if (!result) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return EVP_CIPHER_CTX_cipher(ctx);
}

int populate_rx_indication_pdu_array(NFAPI_RX_INDICATION_PDU_T *array, size_t num_pdus, int verbose) {
