#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    // Add more event types as needed.
} EventType;

typedef struct {
    EventType eventType;
    time_t timestamp;
    int priority;
    pthread_mutex_t lock;  // Mutex for thread safety on individual notification.
} Notification;

typedef struct {
    Notification *notifications;
    size_t capacity;
    size_t count;
    pthread_rwlock_t rwlock;  // Read-write lock for concurrent access.
} NotificationArray;

// Function prototypes
void initNotificationArray(NotificationArray *array);
void resizeIfNeeded(NotificationArray *array);
void addOrUpdateNotification(NotificationArray *array, EventType eventType, time_t timestamp, int priority);
void deleteNotificationsByType(NotificationArray *array, EventType eventType);
void cleanupExpiredNotifications(NotificationArray *array, time_t currentTime);
void batchUpdateOrDelete(NotificationArray *array, EventType eventType, void (*operation)(Notification *));
void saveToDatabase(const Notification *notification);  // Placeholder for database integration.
void loadFromDatabase(NotificationArray *array);         // Placeholder for database integration.

// Initialize the notification array
void initNotificationArray(NotificationArray *array) {
    pthread_rwlock_init(&array->rwlock, NULL);
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    array->notifications = malloc(sizeof(Notification) * array->capacity);
}

// Resize the notifications array if needed
void resizeIfNeeded(NotificationArray *array) {
    pthread_rwlock_wrlock(&array->rwlock);
    if (array->count == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        Notification *newNotifications = malloc(sizeof(Notification) * newCapacity);

        for (size_t i = 0; i < array->count; ++i) {
            pthread_mutex_lock(&array->notifications[i].lock);
            newNotifications[i] = array->notifications[i];
            pthread_mutex_unlock(&array->notifications[i].lock);
        }

        free(array->notifications);
        array->notifications = newNotifications;
        array->capacity = newCapacity;

    }
    pthread_rwlock_unlock(&array->rwlock);
}

// Add or update a notification
void addOrUpdateNotification(NotificationArray *array, EventType eventType, time_t timestamp, int priority) {
    resizeIfNeeded(array);

    pthread_rwlock_wrlock(&array->rwlock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->notifications[i].eventType == eventType) {
            pthread_mutex_lock(&array->notifications[i].lock);
            array->notifications[i].timestamp = timestamp;
            array->notifications[i].priority = priority;
            pthread_mutex_unlock(&array->notifications[i].lock);
            break;
        }
    }

    for (size_t i = 0; i < array->count; ++i) {
        if (pthread_mutex_trylock(&array->notifications[i].lock) == 0) {
            // Found an available slot or existing notification
            Notification newNotification = {eventType, timestamp, priority, PTHREAD_MUTEX_INITIALIZER};
            array->notifications[i] = newNotification;
            pthread_mutex_unlock(&array->notifications[i].lock);
            break;
        }
    }

    if (i == array->count) {
        // Add to the end if not updated.
        Notification newNotification = {eventType, timestamp, priority, PTHREAD_MUTEX_INITIALIZER};
        array->notifications[array->count++] = newNotification;
    }

    pthread_rwlock_unlock(&array->rwlock);
}

// Delete notifications by event type
void deleteNotificationsByType(NotificationArray *array, EventType eventType) {
    pthread_rwlock_wrlock(&array->rwlock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->notifications[i].eventType == eventType) {
            pthread_mutex_lock(&array->notifications[i].lock);
            // Move last element to the deleted spot and decrease count
            array->notifications[i] = array->notifications[--array->count];
            pthread_mutex_unlock(&array->notifications[array->count].lock);  // Un-lock new position
        }
    }

    pthread_rwlock_unlock(&array->rwlock);
}

// Cleanup expired notifications based on a TTL threshold
void cleanupExpiredNotifications(NotificationArray *array, time_t currentTime) {
    size_t ttlSeconds = 3600; // Example: 1 hour TTL

    pthread_rwlock_wrlock(&array->rwlock);

    for (size_t i = 0; i < array->count;) {
        pthread_mutex_lock(&array->notifications[i].lock);
        if ((currentTime - array->notifications[i].timestamp) > ttlSeconds) {
            // Move last element to the expired spot and decrease count
            array->notifications[i] = array->notifications[--array->count];
            pthread_mutex_unlock(&array->notifications[array->count].lock);  // Un-lock new position
        } else {
            i++;
            pthread_mutex_unlock(&array->notifications[i].lock);
        }
    }

    pthread_rwlock_unlock(&array->rwlock);
}

// Batch update or delete notifications by type using a function pointer for operations
void batchUpdateOrDelete(NotificationArray *array, EventType eventType, void (*operation)(Notification *)) {
    pthread_rwlock_wrlock(&array->rwlock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->notifications[i].eventType == eventType) {
            operation(&array->notifications[i]);
        }
    }

    pthread_rwlock_unlock(&array->rwlock);
}

// Placeholder function to save a notification to an external database
