    NotificationArray notificationArray;
    initNotificationArray(&notificationArray);

    time_t currentTime = time(NULL);
    addOrUpdateNotification(&notificationArray, EVENT_TYPE_A, currentTime, 1);
    cleanupExpiredNotifications(&notificationArray, currentTime);

    deleteNotificationsByType(&notificationArray, EVENT_TYPE_A);

    // Example batch operation
    void (*dummyOperation)(Notification *) = NULL; // Replace with actual function.
    batchUpdateOrDelete(&notificationArray, EVENT_TYPE_A, dummyOperation);

    free(notificationArray.notifications);
    pthread_rwlock_destroy(&notificationArray.rwlock);

    return 0;
}
