#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

// Define the structure for RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
typedef struct {
    uint16_t some_info;
} RX_UE_INFORMATION_TAG;

typedef uint32_t RNTI;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

// Define the NFAPI_UL_RX_FRAME_INFO structure
typedef struct {
    RX_UE_INFORMATION_TAG ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_UL_RX_FRAME_INFO;

// Define a dynamic list node
typedef struct Node {
    NFAPI_UL_RX_FRAME_INFO data;
    struct Node* next;
} Node;

// Define the dynamic list structure with thread safety support
typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void free_dynamic_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Helper function to generate random CRCFLAG
int generate_random_crc_flag() {
    return rand() % 2; // Randomly returns 0 or 1
}

void add_frame_info(DynamicList* list, NFAPI_UL_RX_FRAME_INFO frame) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    // Handle missing data by setting default values
    if (!frame.ue_information_tag.some_info) frame.ue_information_tag.some_info = 0xFFFF; // Default value
    if (!frame.rnti) frame.rnti = 0xFFFFFFFF; // Default RNTI

    new_node->data = frame;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

NFAPI_UL_RX_FRAME_INFO get_frame_info(DynamicList* list, size_t index) {
    if (index >= list->count) {
        fprintf(stderr, "Index out of bounds\n");
        return (NFAPI_UL_RX_FRAME_INFO){0}; // Return a default structure
    }

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    NFAPI_UL_RX_FRAME_INFO frame_info = current ? current->data : (NFAPI_UL_RX_FRAME_INFO){0};
    pthread_mutex_unlock(&list->lock);
    return frame_info;
}

void update_crc_flag(DynamicList* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    if (current) {
        current->data.crc_indication_rel8_tag.CRCFLAG = generate_random_crc_flag();
    } else {
        fprintf(stderr, "Index out of bounds for CRC update\n");
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage function
void* example_usage(void* arg) {
    DynamicList* list = (DynamicList*)arg;

    NFAPI_UL_RX_FRAME_INFO frame1 = {{123}, 456, {0}};
    add_frame_info(list, frame1);

    update_crc_flag(list, 0);

    NFAPI_UL_RX_FRAME_INFO retrieved_frame = get_frame_info(list, 0);
    printf("Retrieved CRCFLAG: %d\n", retrieved_frame.crc_indication_rel8_tag.CRCFLAG);

    return NULL;
}

int main() {
    DynamicList* list = create_dynamic_list();
    if (!list) {
        fprintf(stderr, "Failed to create dynamic list\n");
        return EXIT_FAILURE;
    }

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, example_usage, (void*)list);
    pthread_create(&thread2, NULL, example_usage, (void*)list);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    free_dynamic_list(list);
    return EXIT_SUCCESS;
}
