#define MAX_PDU_COUNT 100

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef void (*PduProcessingCallback)(NFAPI_CRC_INDICATION_PDU_T*);

typedef struct PDUList {
    NFAPI_CRC_INDICATION_PDU_T* PDUs[MAX_PDU_COUNT];
    size_t count;
    pthread_mutex_t mutex;
} PDUList;

void initialize_pdu_list(PDUList* list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

bool is_rnti_unique(PDUList* list, uint16_t rnti) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->PDUs[i]->RNTI == rnti) {
            return false;
        }
    }
    return true;
}

bool add_pdu(PDUList* list, NFAPI_CRC_INDICATION_PDU_T* pdu, PduProcessingCallback callback) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= MAX_PDU_COUNT || !is_rnti_unique(list, pdu->RNTI)) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    list->PDUs[list->count++] = pdu;

    // Call the external processing module's callback function
    if (callback) {
        callback(pdu);
    }

    pthread_mutex_unlock(&list->mutex);
    return true;
}

void free_pdu_list(PDUList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->PDUs[i]);
    }
    pthread_mutex_destroy(&list->mutex);
}

