    if (!pdu) return NULL;

    pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Random value
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random 0 or 1

    return pdu;
}

void example_callback(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("Processing PDU with RNTI: %u\n", pdu->RNTI);
}

int main() {
    PDUList list;
    initialize_pdu_list(&list);

    for (uint16_t rnti = 1; rnti <= MAX_PDU_COUNT + 10; ++rnti) { // More than MAX_PDU_COUNT to test uniqueness
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_random_pdu(rnti);
        if (pdu && add_pdu(&list, pdu, example_callback)) {
            printf("Added PDU with RNTI: %u\n", rnti);
        } else {
