    unsigned int max_average_tx_power;
    pthread_mutex_t mutex;
} PduManager;

PduManager manager = { .count = 0, .max_pdu_count = MAX_PDU_COUNT, .max_average_tx_power = INITIAL_MAX_AVERAGE_TX_POWER };

void log_violation(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

unsigned int generate_random_rnti() {
    return rand() & 0xFFFF;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(PduCreationCallback callback) {
    pthread_mutex_lock(&manager.mutex);

    if (manager.count >= manager.max_pdu_count) {
        // Drop the oldest PDU to make room for a new one
        free(manager.pdus[0]);
        memmove(manager.pdus, manager.pdus + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (manager.max_pdu_count - 1));
        manager.count--;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        pthread_mutex_unlock(&manager.mutex);
        return NULL;
    }

    unsigned int unique_rnti_found = 0;
    while (!unique_rnti_found) {
        new_pdu->RNTI = generate_random_rnti();
        for (size_t i = 0; i < manager.count; ++i) {
            if (manager.pdus[i]->RNTI == new_pdu->RNTI) {
                goto retry;
            }
        }
        unique_rnti_found = 1;
    }

retry:
    new_pdu->RX_UE_INFORMATION_TAG = rand() & 0xFF;
    new_pdu->CRC_INDICATION_REL8_TAG = rand() & 0xFF;
    new_pdu->CRCFLAG = rand() % 2;
    new_pdu->TX_POWER_LEVEL = rand() % 100; // Simulated random TX power level
    new_pdu->RX_QUALITY = rand() % 10;

    unsigned int cumulative_tx_power = 0;
    for (size_t i = 0; i < manager.count + 1; ++i) {
        if (i == manager.count) {
            cumulative_tx_power += new_pdu->TX_POWER_LEVEL;
        } else {
            cumulative_tx_power += manager.pdus[i]->TX_POWER_LEVEL;
        }
    }

    float average_tx_power = (float)cumulative_tx_power / (manager.count + 1);
    if (average_tx_power > manager.max_average_tx_power) {
        char message[100];
        snprintf(message, sizeof(message), "Average TX Power %f exceeds limit at index %zu", average_tx_power, manager.count);
        log_violation(message);
    }

    memmove(manager.pdus + 1, manager.pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * manager.count);
    manager.pdus[0] = new_pdu;
    manager.count++;

    if (callback) {
        callback(new_pdu);
    }

    pthread_mutex_unlock(&manager.mutex);

    return new_pdu;
}

void set_max_pdu_count(size_t new_max_count) {
    pthread_mutex_lock(&manager.mutex);
    manager.max_pdu_count = new_max_count;
    if (manager.count > manager.max_pdu_count) {
        for (size_t i = manager.max_pdu_count; i < manager.count; ++i) {
            free(manager.pdus[i]);
        }
        manager.count = manager.max_pdu_count;
    }
    pthread_mutex_unlock(&manager.mutex);
}

void set_max_average_tx_power(unsigned int new_max_power) {
    pthread_mutex_lock(&manager.mutex);
    manager.max_average_tx_power = new_max_power;
    pthread_mutex_unlock(&manager.mutex);
}

int main() {
    srand(time(NULL));
    pthread_mutex_init(&manager.mutex, NULL);

    // Example usage
    create_pdu(NULL);

    set_max_pdu_count(50);
    set_max_average_tx_power(60);

    pthread_mutex_destroy(&manager.mutex);
    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` for managing concurrent access.
- **Memory Management**: Dynamically allocates and deallocates PDUs, dropping the oldest PDU when necessary.
- **Unique RNTI Check**: Ensures each RNTI is unique within the list.
- **Queue Mechanism**: Prioritizes recent PDUs by moving new ones to the front of the list.
- **TX Power Monitoring**: Logs violations if average TX power exceeds the threshold.
- **Dynamic Reconfiguration**: Allows changing `MAX_PDU_COUNT` and `MAX_AVERAGE_TX_POWER` at runtime.']

