unsigned int generate_crc(unsigned char *data, size_t length) {
    unsigned int crc = 0;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i] << 8;
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x8000)
                crc = (crc << 1) ^ 0x1021;
            else
                crc <<= 1;
        }
    }
    return crc;
}

unsigned int fallback_crc(unsigned char *data, size_t length) {
    unsigned int crc = 0;
    for (size_t i = 0; i < length; ++i) {
        crc += data[i];
    }
    return crc % 256;
}

