        snprintf(log_msg, sizeof(log_msg), "Structure %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d", i, array[i].RX_UE_INFORMATION_TAG, array[i].RNTI, array[i].CRCFLAG);

        if (strcmp(logging_thresholds, "verbose") == 0 || strcmp(logging_thresholds, "debug") == 0) {
            log_message(LOG_DEBUG, log_msg);
        }

        pthread_mutex_unlock(&data_lock);
    }

    return array;
}

void cleanup_array(NFAPI_CRC_INDICATION_PDU_T *array) {
