using System;

public class RandomValueGenerator {
    private readonly double _minFloatRange;
    private readonly double _maxFloatRange;
    private readonly int _minIntRange;
    private readonly int _maxIntRange;

    public RandomValueGenerator(double minFloat, double maxFloat, int minInt, int maxInt) {
        _minFloatRange = minFloat;
        _maxFloatRange = maxFloat;
        _minIntRange = minInt;
        _maxIntRange = maxInt;
    }

    public double GenerateRandomFloat() {
        Random random = new Random();
        return _minFloatRange + (random.NextDouble() * (_maxFloatRange - _minFloatRange));
    }

    public int GenerateRandomInteger() {
        Random random = new Random();
        return _minIntRange + random.Next(_maxIntRange - _minIntRange);
    }

    public override string ToString() {
        return $"Float Range: {_minFloatRange} to {_maxFloatRange}, Integer Range: {_minIntRange} to {_maxIntRange}";
    }
}
