```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE_LIST 100
#define RX_UE_INFORMATION_TAG_VALID 1
#define CRCFLAG_RANDOM_THRESHOLD 0x80000000 // Example threshold for random CRC flag

typedef struct {
    unsigned int RNTI;
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int CRC_INDICATION_REL8_TAG;
} UE_Instance;

typedef struct {
    UE_Instance* UEs;
    size_t count;
    pthread_mutex_t lock;
} UE_List;

// Function prototypes
int initialize_ue_list(UE_List *ue_list, size_t num_ues);
void cleanup_ue_list(UE_List *ue_list);
static int validate_rnti(unsigned int rnti, UE_List *ue_list);

int initialize_ue_list(UE_List *ue_list, size_t num_ues) {
    if (!ue_list || num_ues == 0 || num_ues > MAX_UE_LIST) return -1;

    ue_list->count = 0;
    pthread_mutex_init(&ue_list->lock, NULL);

    ue_list->UEs = malloc(num_ues * sizeof(UE_Instance));
    if (!ue_list->UEs) {
        pthread_mutex_destroy(&ue_list->lock);
        return -2; // Memory allocation failure
    }

    for (size_t i = 0; i < num_ues; ++i) {
        unsigned int rnti;
        do {
            rnti = rand(); // Random RNTI generation
        } while (!validate_rnti(rnti, ue_list));

        UE_Instance *ue_instance = &ue_list->UEs[i];
        ue_instance->RNTI = rnti;
        ue_instance->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG_VALID;
        ue_instance->CRC_INDICATION_REL8_TAG = (rand() > CRCFLAG_RANDOM_THRESHOLD) ? 1 : 0;

        ++ue_list->count;
    }

    return 0; // Success
}

void cleanup_ue_list(UE_List *ue_list) {
    if (!ue_list) return;

    pthread_mutex_lock(&ue_list->lock);
    free(ue_list->UEs);
    ue_list->UEs = NULL;
    ue_list->count = 0;
    pthread_mutex_unlock(&ue_list->lock);

    pthread_mutex_destroy(&ue_list->lock);
}

static int validate_rnti(unsigned int rnti, UE_List *ue_list) {
    pthread_mutex_lock(&ue_list->lock);
    for (size_t i = 0; i < ue_list->count; ++i) {
        if (ue_list->UEs[i].RNTI == rnti) {
            pthread_mutex_unlock(&ue_list->lock);
            return 0; // RNTI is not unique
        }
    }
    pthread_mutex_unlock(&ue_list->lock);
    return 1; // RNTI is unique
}

// Example usage and basic test
int main() {
    UE_List ue_list;
    int result = initialize_ue_list(&ue_list, 10);

    if (result == 0) {
        printf("UE list initialized successfully with %zu UEs.\n", ue_list.count);
    } else {
        printf("Failed to initialize UE list. Error code: %d\n", result);
    }

    cleanup_ue_list(&ue_list);
    return 0;
}
```

### Key Features:
- **Initialization**: The `initialize_ue_list` function allocates memory and initializes UEs with unique RNTIs, setting appropriate tags.
- **Memory Management**: Handles allocation failures gracefully by returning error codes.
- **Concurrency**: Uses a mutex (`pthread_mutex_t`) to ensure thread-safe operations when accessing or modifying the UE list.
- **Validation**: Ensures all RNTIs are unique within the list using `validate_rnti`.
- **Cleanup**: Frees allocated resources and destroys the mutex in `cleanup_ue_list`.

### Considerations:
- **Scalability**: The design supports up to `MAX_UE_LIST` UEs, easily extendable.
- **Concurrency Control**: Mutex locks ensure safe concurrent access without data races.
- **Robustness**: Handles edge cases such as empty or full lists gracefully.']

