#define MAX_UE_COUNT 1000
#define SUCCESS 0
#define ERROR_MEMORY_ALLOCATION -1
#define ERROR_MAX_UE_EXCEEDED -2

typedef struct {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    struct {
        int crc_flag;
    } crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

