    NFAPI_CRC_INDICATION_PDU_T* pdu_list;
    size_t count;
    pthread_mutex_t lock;
} CRC_Indication_List;

// Placeholder for asynchronous loading function
int async_load_ue_information(uint16_t rnti, uint16_t* rx_tag) {
    // Simulate a network call with a delay and random failure
    if (rand() % 10 < 2) {
        return -1; // Failure
    }
    *rx_tag = rand() % 65536;
    return SUCCESS;
}

int allocate_and_populate_crc_indication_list(CRC_Indication_List* list, size_t ue_count, uint32_t bitmask) {
    pthread_mutex_lock(&list->lock);

    if (ue_count > MAX_UE_COUNT) {
        pthread_mutex_unlock(&list->lock);
        return ERROR_MAX_UE_EXCEEDED;
    }

    // Allocate memory for the structures
    list->pdu_list = malloc(ue_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdu_list) {
        pthread_mutex_unlock(&list->lock);
        return ERROR_MEMORY_ALLOCATION;
    }

    size_t filled_ues = 0;
    for (size_t i = 0; i < ue_count; ++i) {
        // Check bitmask validity
        if ((bitmask & (1 << i)) == 0) continue;

        NFAPI_CRC_INDICATION_PDU_T* pdu = &list->pdu_list[i];
        uint16_t rx_tag;

        int load_result = async_load_ue_information((uint16_t)(i + 1), &rx_tag);
        if (load_result != SUCCESS) {
            // Retry mechanism
            for (int attempt = 0; attempt < 3; ++attempt) {
                load_result = async_load_ue_information((uint16_t)(i + 1), &rx_tag);
                if (load_result == SUCCESS) break;
            }

            if (load_result != SUCCESS) {
                free(list->pdu_list);
                list->pdu_list = NULL;
                pthread_mutex_unlock(&list->lock);
                return ERROR_MEMORY_ALLOCATION; // Treat as memory error for simplicity
            }
        }

        pdu->rx_ue_information_tag = rx_tag;
        pdu->rnti = (uint16_t)(i + 1);
        pdu->crc_indication_rel8_tag.crc_flag = rand() % 2;

        filled_ues++;
    }

    list->count = filled_ues;

    pthread_mutex_unlock(&list->lock);

    return SUCCESS;
}

void cleanup_crc_indication_list(CRC_Indication_List* list) {
    pthread_mutex_lock(&list->lock);

    if (list->pdu_list) {
        free(list->pdu_list);
        list->pdu_list = NULL;
    }

    pthread_mutex_unlock(&list->lock);
}

void initialize_crc_indication_list(CRC_Indication_List* list) {
    memset(list, 0, sizeof(CRC_Indication_List));
    pthread_mutex_init(&list->lock, NULL);
}

int main() {
    CRC_Indication_List crc_list;
    initialize_crc_indication_list(&crc_list);

    size_t ue_count = 10; // Example UE count
    uint32_t bitmask = (1 << ue_count) - 1; // Enable all bits

    int result = allocate_and_populate_crc_indication_list(&crc_list, ue_count, bitmask);
    if (result != SUCCESS) {
