        free(collection);
    }

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* createNFAPICRCIndicationCollection(size_t count) {
    NFAPI_CRC_INDICATION_PDU_T *collection = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!collection) {
        fprintf(stderr, "Memory allocation failed for collection.\n");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
