        int rnti = rand() % 0x7FFE + 1; // Ensure RNTI is within valid range 0x0001 to 0x7FFF
        if (rnti == 0 || rnti > 0x7FFF) {
            fprintf(stderr, "Generated out-of-range RNTI value: %d. Assigning default.\n", rnti);
            rnti = 1; // Default valid RNTI
        }
        collection[i].RNTI = rnti;
        collection[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG: 0 or 1
    }

    return collection;
}

int findLargestInteger(int *array, size_t size) {
    if (size == 0) return INT_MIN;

    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest && array[i] <= INT_MAX) {
            largest = array[i];
        } else if (array[i] > INT_MAX) {
            fprintf(stderr, "Integer overflow detected: %d\n", array[i]);
        }
    }

    return largest;
}

void readIntegersFromInput(int **array, size_t *size) {
    int input;
    size_t capacity = 10; // Initial capacity
    *array = malloc(capacity * sizeof(int));
    if (!*array) {
        fprintf(stderr, "Memory allocation failed for integer array.\n");
        return;
    }

    *size = 0;
    while (scanf("%d", &input) == 1) {
        resizeArrayIfNeeded(array, size, (*size + 1));
        (*array)[(*size)++] = input;
    }
}

void resizeArrayIfNeeded(int **array, size_t *currentSize, size_t newElementCount) {
    if (newElementCount > *currentSize) {
        size_t newCapacity = (*currentSize == 0) ? 10 : (*currentSize) * 2;
        int *temp = realloc(*array, newCapacity * sizeof(int));
        if (!temp) {
            fprintf(stderr, "Memory reallocation failed.\n");
            free(*array);
            *array = NULL;
            return;
        }
        *array = temp;
    }
}
```

This code efficiently manages dynamic memory allocation for a collection of structures and an integer array. It handles potential overflows and ensures valid `RNTI` values while providing logging for diagnostics without excessive overhead. The resizing algorithm doubles the capacity to minimize reallocation frequency, balancing performance with memory usage.']

