#define MAX_KEY 1000

typedef struct record {
    int key;
    long offset;
    struct record* next;
} record;

record *records[MAX_KEY] = {NULL};
pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    unsigned int rnti;
    unsigned char valid_rx_ue_information_tag;
} RX_UE_INFORMATION_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T rx_ue_information_tag;
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T ue_info;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

int generate_unique_key() {
    int key;
    do {
        key = rand() % MAX_KEY;
    } while (records[key] != NULL);
    return key;
}

void initialize_record(record *rec, int lower_bound, int upper_bound) {
    rec->key = generate_unique_key();
    rec->offset = rand() % (upper_bound - lower_bound + 1) + lower_bound;
    rec->next = NULL;
}

int add_or_update_record(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&records_lock);

    record **rec_ptr = &records[pdu->ue_info.rnti];
    while (*rec_ptr != NULL && (*rec_ptr)->key != pdu->ue_info.rnti) {
        rec_ptr = &(*rec_ptr)->next;
    }

    if (*rec_ptr == NULL) {
        *rec_ptr = malloc(sizeof(record));
        initialize_record(*rec_ptr, 0, 100000);
        (*rec_ptr)->key = pdu->ue_info.rnti;
    }

    (*rec_ptr)->offset = rand() % (100000 - 0 + 1) + 0; // Randomize offset
    pthread_mutex_unlock(&records_lock);

    return MHD_YES;
}

int delete_record(int key) {
    pthread_mutex_lock(&records_lock);
    record **rec_ptr = &records[key];

    while (*rec_ptr != NULL && (*rec_ptr)->key != key) {
        rec_ptr = &(*rec_ptr)->next;
    }

    if (*rec_ptr != NULL) {
        printf("Deleting record with key %d\n", key); // Log deletion
        record *temp = *rec_ptr;
        *rec_ptr = temp->next;
        free(temp);
    }

    pthread_mutex_unlock(&records_lock);

    return MHD_YES;
}

int handle_put_request(void *cls, struct MHD_Connection *connection,
                       const char *url, const char *method,
                       const char *version, const char *upload_data,
                       size_t *upload_data_size, void **con_cls) {
    if (strcmp(method, "PUT") == 0) {
        // Parse JSON and update record
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Assume JSON parsing populates 'pdu' correctly
        add_or_update_record(&pdu);
        return MHD_YES;
    }
    return MHD_NO;
}

int handle_delete_request(void *cls, struct MHD_Connection *connection,
                          const char *url, const char *method,
                          const char *version, const char *upload_data,
                          size_t *upload_data_size, void **con_cls) {
    if (strcmp(method, "DELETE") == 0) {
        // Extract key from URL
        int key = atoi(url + strlen("/delete/"));
        delete_record(key);
        return MHD_YES;
    }
    return MHD_NO;
}

int main() {
    struct MHD_Daemon *daemon;
    srand(time(NULL));

    daemon = MHD_start_daemon(MHD_USE_SELECT_INTERNALLY, 8888, NULL, NULL,
                              &handle_put_request, NULL, MHD_OPTION_END);

    if (NULL == daemon) return 1;

    printf("Server running on port 8888\n");
    getchar(); // Wait for user input to stop the server

    MHD_stop_daemon(daemon);

    return 0;
}
```

