#define UUID_SIZE 37 // UUID string length + null terminator

typedef struct {
    char uuid[UUID_SIZE];
    time_t timestamp;
    struct device* next_device;
} device;

typedef struct {
    int event_type;
    char source_device_uuid[UUID_SIZE];
    char destination_device_uuid[UUID_SIZE];
    int status_code;
} network_event;

#define MAX_DEVICES 1000
device devices[MAX_DEVICES];
int num_devices = 0;
pthread_mutex_t devices_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_device(device* dev) {
    // Generate a unique UUID for the device
    // For simplicity, using a random string here
    const char* chars = "0123456789abcdef";
    srand(time(NULL));
    for (int i = 0; i < UUID_SIZE - 1; ++i) {
        dev->uuid[i] = chars[rand() % 16];
    }
    dev->uuid[UUID_SIZE - 1] = '\0';

    // Random timestamp within a specified range
    time_t base_time = time(NULL);
    int offset = rand() % (60 * 60); // Within the last hour
    dev->timestamp = base_time - offset;

    dev->next_device = NULL;
}

int add_device(const char* json_request) {
    pthread_mutex_lock(&devices_mutex);

    if (num_devices >= MAX_DEVICES) {
        pthread_mutex_unlock(&devices_mutex);
        return -1; // Device limit reached
    }

    for (int i = 0; i < num_devices; ++i) {
        if (strcmp(devices[i].uuid, json_request) == 0) {
            pthread_mutex_unlock(&devices_mutex);
            return -2; // UUID already exists
        }
    }

    device* new_device = &devices[num_devices++];
    initialize_device(new_device);

    pthread_mutex_unlock(&devices_mutex);
    return 0;
}

device* get_device_by_uuid(const char* uuid) {
    pthread_mutex_lock(&devices_mutex);

    for (int i = 0; i < num_devices; ++i) {
        if (strcmp(devices[i].uuid, uuid) == 0) {
            device* dev = &devices[i];
            pthread_mutex_unlock(&devices_mutex);
            return dev;
        }
    }

    pthread_mutex_unlock(&devices_mutex);
    return NULL;
}

static int answer_to_connection(void *cls, struct MHD_Connection *connection,
                                const char *url, const char *method,
                                const char *version, const char *upload_data,
                                size_t *upload_data_size, void **con_cls) {
    if (strcmp(method, "POST") == 0 && strcmp(url, "/add_device") == 0) {
        int ret = add_device(upload_data);
        const char* response;
        if (ret == 0) {
            response = "Device added successfully";
        } else if (ret == -1) {
            response = "Error: Device limit reached";
        } else {
            response = "Error: UUID already exists";
        }

        struct MHD_Response *response_struct = 
            MHD_create_response_from_buffer(strlen(response), (void *)response, MHD_RESPMEM_PERSISTENT);
        int ret2 = MHD_queue_response(connection, MHD_HTTP_OK, response_struct);
        MHD_destroy_response(response_struct);
        return ret2;
    } else if (strcmp(method, "GET") == 0) {
        const char* uuid_start = url + strlen("/device/");
        char* endptr;
        long int id = strtol(uuid_start, &endptr, 10);

        if (*endptr != '\0') {
            struct MHD_Response *response_struct = 
                MHD_create_response_from_buffer(0, (void *)"Invalid UUID", MHD_RESPMEM_PERSISTENT);
            int ret2 = MHD_queue_response(connection, MHD_HTTP_BAD_REQUEST, response_struct);
            MHD_destroy_response(response_struct);
            return ret2;
        }

        device* dev = get_device_by_uuid(uuid_start);

        if (dev == NULL) {
            struct MHD_Response *response_struct = 
                MHD_create_response_from_buffer(0, (void *)"Device not found", MHD_RESPMEM_PERSISTENT);
            int ret2 = MHD_queue_response(connection, MHD_HTTP_NOT_FOUND, response_struct);
            MHD_destroy_response(response_struct);
            return ret2;
        }

        char buffer[256];
        snprintf(buffer, sizeof(buffer), "UUID: %s\nTimestamp: %ld", dev->uuid, dev->timestamp);

        struct MHD_Response *response_struct = 
            MHD_create_response_from_buffer(strlen(buffer), (void *)buffer, MHD_RESPMEM_PERSISTENT);
        int ret2 = MHD_queue_response(connection, MHD_HTTP_OK, response_struct);
        MHD_destroy_response(response_struct);
        return ret2;
    }

    struct MHD_Response *response = MHD_create_response_from_buffer(0, (void *)"Not Found", MHD_RESPMEM_PERSISTENT);
    int ret = MHD_queue_response(connection, MHD_HTTP_NOT_FOUND, response);
    MHD_destroy_response(response);
    return ret;
}

int main() {
    struct MHD_Daemon *daemon;

    daemon = MHD_start_daemon(MHD_USE_SELECT_INTERNALLY, 8888, NULL, NULL,
                              &answer_to_connection, NULL, MHD_OPTION_END);

    if (NULL == daemon) return 1;

    printf("Server started on port 8888\n");

    getchar(); // Wait for Enter key press

    int ret = MHD_stop_daemon(daemon);
    if (ret != MHD_SUCCESS) return 2;

    return 0;
}
