// Placeholder for actual types and constants used in LTE_RRC_CriticalSection_t
typedef struct {
    int SecurityParameterSet; // Assume it's an integer for simplicity
} SecurityContext_t;

typedef struct {
    int UE_ID;
    int NRBPRB_MAP;
    SecurityContext_t SecurityContext;
} LTE_RRC_CriticalSection_t;

// Global lock for thread-safe operations
pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;

// Dynamic array structure with additional information
typedef struct {
    LTE_RRC_CriticalSection_t *sections;
    size_t capacity;
    size_t count;
} SectionArray;

// Function to initialize the dynamic array
SectionArray* create_section_array(size_t initial_capacity) {
    SectionArray* array = (SectionArray*)malloc(sizeof(SectionArray));
    if (!array) return NULL; // Handle memory allocation failure

    array->sections = (LTE_RRC_CriticalSection_t*)calloc(initial_capacity, sizeof(LTE_RRC_CriticalSection_t));
    if (!array->sections) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;

    return array;
}

// Function to reallocate memory with new capacity
int resize_section_array(SectionArray* array, size_t new_capacity) {
    LTE_RRC_CriticalSection_t *new_sections = (LTE_RRC_CriticalSection_t*)realloc(array->sections, new_capacity * sizeof(LTE_RRC_CriticalSection_t));
    if (!new_sections) return -1; // Handle memory allocation failure

    array->sections = new_sections;
    array->capacity = new_capacity;

    return 0;
}

// Function to add a critical section
int add_section(SectionArray* array, int UE_ID, int NRBPRB_MAP, int security_param_set) {
    pthread_mutex_lock(&array_lock);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        if (resize_section_array(array, new_capacity) != 0) {
            pthread_mutex_unlock(&array_lock);
            return -1; // Handle resize failure
        }
    }

    LTE_RRC_CriticalSection_t* section = &array->sections[array->count];
    section->UE_ID = UE_ID;
    section->NRBPRB_MAP = NRBPRB_MAP;
    section->SecurityContext.SecurityParameterSet = security_param_set;

    array->count++;
    pthread_mutex_unlock(&array_lock);

    return 0;
}

// Function to remove a critical section by UE_ID
int remove_section(SectionArray* array, int UE_ID) {
    pthread_mutex_lock(&array_lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->sections[i].UE_ID == UE_ID) {
            memmove(&array->sections[i], &array->sections[i + 1], (array->count - i - 1) * sizeof(LTE_RRC_CriticalSection_t));
            array->count--;
            pthread_mutex_unlock(&array_lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&array_lock);
    return -1; // UE_ID not found
}

// Function to free the dynamic array resources
void destroy_section_array(SectionArray* array) {
    pthread_mutex_lock(&array_lock);

    if (array->sections) {
        free(array->sections);
    }
    free(array);

    pthread_mutex_unlock(&array_lock);
}

// Function for logging critical section operations
void log_operation(const char *operation, int UE_ID) {
    printf("Operation: %s, UE_ID: %d\n", operation, UE_ID);
}

