#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdint.h>

#define INITIAL_CAPACITY 10
#define MAX_RNTI 0x7FFF

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG; // Assuming CRCFLAG is an integer for simplicity.
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t capacity;
    size_t count;
} Collection;

void seed_random_generator() {
    srand((unsigned int)time(NULL));
}

int generate_crcflag() {
    return rand() % 2; // Random CRCFLAG: 0 or 1
}

int validate_rnti(uint16_t rnti) {
    if (rnti >= 0x0001 && rnti <= MAX_RNTI) {
        return 1;
    } else {
        fprintf(stderr, "Invalid RNTI value detected: %u\n", rnti);
        return 0;
    }
}

void log_message(const char *message) {
    printf("LOG: %s\n", message); // Simplified logging function
}

Collection* create_collection(size_t initial_capacity) {
    Collection *collection = (Collection *)malloc(sizeof(Collection));
    collection->elements = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    collection->capacity = initial_capacity;
    collection->count = 0;
    return collection;
}

void resize_collection(Collection *collection) {
    size_t new_capacity = collection->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T *)realloc(collection->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_elements) {
        fprintf(stderr, "Memory allocation failed during resize.\n");
        return;
    }

    collection->elements = new_elements;
    collection->capacity = new_capacity;
}

void add_element(Collection *collection, uint16_t rx_ue_info_tag, uint16_t rnti) {
    if (collection->count >= collection->capacity) {
        resize_collection(collection);
    }

    if (!validate_rnti(rnti)) {
        // Handle invalid RNTI by skipping or applying a fallback
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T new_element = {rx_ue_info_tag, rnti, {generate_crcflag()}};
    collection->elements[collection->count++] = new_element;
}

void integrate_data(Collection *collection, uint16_t rx_ue_info_tag, uint16_t rnti) {
    add_element(collection, rx_ue_info_tag, rnti);
    log_message("Data integrated into the collection.");
}

void free_collection(Collection *collection) {
    free(collection->elements);
    free(collection);
}

int main() {
    seed_random_generator();

    Collection *collection = create_collection(INITIAL_CAPACITY);

    // Simulate real-time updates
    for (int i = 0; i < 100; ++i) {
        uint16_t rx_ue_info_tag = rand(); // Random RX_UE_INFORMATION_TAG
        uint16_t rnti = rand() % MAX_RNTI + 1; // Valid RNTI range

        integrate_data(collection, rx_ue_info_tag, rnti);
    }

    free_collection(collection);

    return 0;
}
```

### Key Features:

- **Dynamic Resizing**: The collection dynamically resizes itself when the capacity is exceeded.
- **Validation and Logging**: Validates `RNTI` values and logs any errors or operations for diagnostics.
- **Random CRCFLAG Generation**: Uses a seeded pseudo-random number generator to set the `CRCFLAG`.
- **Efficient Memory Management**: Allocates memory using `calloc` and resizes with `realloc`, handling potential allocation failures gracefully.

This implementation balances simplicity, performance, and robustness, making it suitable for managing large data volumes while ensuring real-time update capabilities.']

