#include <pthread.h>
#include <time.h>

#define N 10 // Example size of the array

typedef struct {
    int key;
    long offset;
    void *next;
} record;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int key;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

record *records[N];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize records with random values
void init_records() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < N; ++i) {
        record *rec = malloc(sizeof(record));
        rec->key = rand() % 1000;
        rec->offset = rand() % 10000;
        rec->next = NULL;

        // Ensure unique key
        int exists;
        do {
            exists = 0;
            for (int j = 0; j < N; ++j) {
                if (records[j] && records[j]->key == rec->key) {
                    exists = 1;
                    break;
                }
            }
            if (exists) free(rec), rec = malloc(sizeof(record)), rec->key = rand() % 1000;
        } while (exists);

        records[i] = rec;
    }
    pthread_mutex_unlock(&lock);
}

// HTTP server setup using libmicrohttpd
#include <microhttpd.h>

#define PORT 8888

static int answer_to_connection(void *cls, struct MHD_Connection *connection,
                                const char *url, const char *method,
                                const char *version, const char *upload_data,
                                size_t *upload_data_size, void **con_cls) {
    // Handle PUT and DELETE requests
    if (strcmp(method, "PUT") == 0 || strcmp(method, "DELETE") == 0) {
        int key = atoi(url + strlen("/record/"));

        if (strcmp(method, "PUT") == 0) {
            pthread_mutex_lock(&lock);
            // Parse JSON and update record with matching key
            // Example: Update offset
            for (int i = 0; i < N; ++i) {
                if (records[i] && records[i]->key == key) {
                    // Assuming new_offset is parsed from upload_data
                    long new_offset = rand() % 10000;
                    records[i]->offset = new_offset;
                    break;
                }
            }
            pthread_mutex_unlock(&lock);
        } else if (strcmp(method, "DELETE") == 0) {
            pthread_mutex_lock(&lock);
            for (int i = 0; i < N; ++i) {
                if (records[i] && records[i]->key == key) {
                    free(records[i]);
                    records[i] = malloc(sizeof(record));
                    records[i]->key = -1; // Indicating empty
                    break;
                }
            }
            pthread_mutex_unlock(&lock);
        }

        struct MHD_Response *response = MHD_create_response_from_buffer(
            13, (void *) "Deleted/Updated", MHD_RESPMEM_PERSISTENT);
        int ret = MHD_queue_response(connection, MHD_HTTP_OK, response);
        MHD_destroy_response(response);
        return ret;
    }

    // Handle GET requests for querying current state
    if (strcmp(method, "GET") == 0) {
        pthread_mutex_lock(&lock);
        char *response_buffer = malloc(1024);
        strcpy(response_buffer, "[");
        for (int i = 0; i < N; ++i) {
            if (records[i] && records[i]->key != -1) {
                strcat(response_buffer, "{");
                strcat(response_buffer, "\"key\":");
                char key_str[10];
                sprintf(key_str, "%d", records[i]->key);
                strcat(response_buffer, key_str);
                strcat(response_buffer, ",\"offset\":");
                char offset_str[20];
                sprintf(offset_str, "%ld", records[i]->offset);
                strcat(response_buffer, offset_str);
                strcat(response_buffer, "},");
            }
        }
        if (strcmp(response_buffer + strlen(response_buffer) - 1, ",") == 0)
            response_buffer[strlen(response_buffer) - 1] = ']';
        else
            strcat(response_buffer, "]");

        struct MHD_Response *response = MHD_create_response_from_buffer(
            strlen(response_buffer), (void *) response_buffer, MHD_RESPMEM_PERSISTENT);
        int ret = MHD_queue_response(connection, MHD_HTTP_OK, response);
        free(response_buffer);
        MHD_destroy_response(response);
        pthread_mutex_unlock(&lock);
        return ret;
    }

    struct MHD_Response *response = MHD_create_response_from_buffer(
        13, (void *) "Not Found", MHD_RESPMEM_PERSISTENT);
    int ret = MHD_queue_response(connection, MHD_HTTP_NOT_FOUND, response);
    MHD_destroy_response(response);
    return ret;
}

int main() {
    srand(time(NULL));
    init_records();

    struct MHD_Daemon *daemon = MHD_start_daemon(MHD_USE_THREAD_PER_CONNECTION,
                                                 PORT, NULL, NULL, &answer_to_connection,
                                                 NULL, MHD_OPTION_END);
    if (NULL == daemon) return 1;

    getchar(); // Run until user input
    MHD_stop_daemon(daemon);
    pthread_mutex_destroy(&lock);

    for (int i = 0; i < N; ++i) {
        if (records[i]) free(records[i]);
    }

    return 0;
}
