```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} LinkedList;

void init_list(LinkedList* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    *reinterpret_cast<NFAPI_CRC_INDICATION_PDU_T*>(&node->data) = *data;
    node->next = NULL;
    return node;
}

void add_to_list(LinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = create_node(data);
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new node\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
}

void print_list(const LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.crc_tag.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void process_batch_data(LinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* batch, size_t batch_size) {
    for (size_t i = 0; i < batch_size; ++i) {
        // Simulate random CRCFLAG assignment
        batch[i].crc_tag.CRCFLAG = rand() % 2;
        add_to_list(list, &batch[i]);
    }
}

// Example usage function
void example_usage(LinkedList* list) {
    init_list(list);

    const size_t batch_size = 10;
    NFAPI_CRC_INDICATION_PDU_T batch[batch_size];

    for (size_t i = 0; i < batch_size; ++i) {
        batch[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        batch[i].RNTI = rand() % 5000;
    }

