#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_GEOMETRIES 10000
#define POINT_ARRAY_SIZE 10
#define STRING_LENGTH 20

typedef struct {
    float x;
    float y;
} point_t;

typedef struct geometry {
    time_t timestamp;
    int status_flag; // Validity flag
    pthread_mutex_t lock;
    int reference_count;
    double *double_array;
    char *char_array;
    point_t *points;
    struct geometry *next_geometry;
} geometry_t;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned short RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
    int sequence_number;
    int crc_flag; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Global array of geometries
geometry_t *geometries[MAX_GEOMETRIES];
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
int initialize_geometries();
void free_geometries();
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdus(int count);
void generate_random_string(char *str, size_t length);

int main() {
    if (initialize_geometries() != 0) {
        fprintf(stderr, "Failed to initialize geometries.\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = create_crc_indication_pdus(100);
    if (!pdus) {
        fprintf(stderr, "Failed to create CRC indication PDUs.\n");
        free_geometries();
        return EXIT_FAILURE;
    }

    // Do something with the PDUs...

    free(pdus);
    free_geometries();
    return EXIT_SUCCESS;
}

int initialize_geometries() {
    pthread_mutex_lock(&global_lock);

    for (int i = 0; i < MAX_GEOMETRIES; ++i) {
        geometry_t *geometry = malloc(sizeof(geometry_t));
        if (!geometry) {
            pthread_mutex_unlock(&global_lock);
            return -1;
        }

        geometry->timestamp = time(NULL);
        geometry->status_flag = 1;
        pthread_mutex_init(&geometry->lock, NULL);
        geometry->reference_count = 0;

        // Allocate and initialize double array
        geometry->double_array = malloc(POINT_ARRAY_SIZE * sizeof(double));
        if (!geometry->double_array) {
            free(geometry);
            pthread_mutex_unlock(&global_lock);
            return -1;
        }

        for (int j = 0; j < POINT_ARRAY_SIZE; ++j) {
            geometry->double_array[j] = (double)(rand() % 100);
        }

        // Allocate and initialize char array
        geometry->char_array = malloc(STRING_LENGTH + 1);
        if (!geometry->char_array) {
            free(geometry->double_array);
            free(geometry);
            pthread_mutex_unlock(&global_lock);
            return -1;
        }
        generate_random_string(geometry->char_array, STRING_LENGTH);

        // Allocate and initialize point array
        geometry->points = malloc(POINT_ARRAY_SIZE * sizeof(point_t));
        if (!geometry->points) {
            free(geometry->char_array);
            free(geometry->double_array);
            free(geometry);
            pthread_mutex_unlock(&global_lock);
            return -1;
        }

        for (int j = 0; j < POINT_ARRAY_SIZE; ++j) {
            geometry->points[j].x = (float)(rand() % 100);
            geometry->points[j].y = (float)(rand() % 100);
        }

        // Link geometries in a chain
        if (i == 0) {
            geometries[0] = geometry;
        } else {
            geometries[i - 1]->next_geometry = geometry;
        }
    }

    pthread_mutex_unlock(&global_lock);
    return 0;
}

void free_geometries() {
    pthread_mutex_lock(&global_lock);

    for (int i = 0; i < MAX_GEOMETRIES; ++i) {
        if (geometries[i]) {
            geometry_t *geometry = geometries[i];
            while (geometry) {
                geometry_t *next = geometry->next_geometry;

                pthread_mutex_destroy(&geometry->lock);
                free(geometry->double_array);
                free(geometry->char_array);
                free(geometry->points);
                free(geometry);

                geometry = next;
            }
        }
    }

    pthread_mutex_unlock(&global_lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdus(int count) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    for (int i = 0; i < count; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 65535;
        pdus[i].RNTI = rand() % 65535;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 65535;
        pdus[i].sequence_number = i;
        pdus[i].crc_flag = rand() % 2; // Randomly set to 0 or 1
    }

    return pdus;
}

void generate_random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (length) {
        --length; // Account for the null terminator
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    } else {
        str[0] = '\0';
    }
}
