    size_t num_dl_grants;
} LTE_ENB_RRC_API_STRUCTURE;

// A cache to minimize impact of stale data
typedef struct {
    int UE_ID;
    void* MAC_entity; // Pointer cached for reuse
    time_t last_updated; // Timestamp of the last update
} MAC_ENTITY_CACHE_ENTRY;

MAC_ENTITY_CACHE_ENTRY mac_cache[MAX_UES];

void initialize_mac_cache() {
    for (int i = 0; i < MAX_UES; ++i) {
        mac_cache[i].UE_ID = -1;
        mac_cache[i].MAC_entity = NULL;
        mac_cache[i].last_updated = 0;
    }
}

// Function to get MAC entity, possibly updating cache
void* get_mac_entity(int UE_ID) {
    // Check if in cache and still valid (e.g., updated within last minute)
    for (int i = 0; i < MAX_UES; ++i) {
        if (mac_cache[i].UE_ID == UE_ID && 
            (time(NULL) - mac_cache[i].last_updated) < 60) {
            return mac_cache[i].MAC_entity;
        }
    }

    // Simulating third-party library call to get MAC entity
    void* mac_entity = malloc(sizeof(int)); // Placeholder for actual MAC entity allocation
    if (!mac_entity) {
        fprintf(stderr, "Failed to allocate memory for MAC entity.\n");
        return NULL;
    }

    // Update cache
    int index = UE_ID % MAX_UES; // Simple modulo-based indexing strategy
    mac_cache[index].UE_ID = UE_ID;
    mac_cache[index].MAC_entity = mac_entity;
    mac_cache[index].last_updated = time(NULL);

    return mac_entity;
}

// Function to check for overlapping grants
int is_overlap(DL_GRANT_INFO* grant1, DL_GRANT_INFO* grant2) {
    int overlap_time = (grant1->start_time < grant2->start_time + grant2->duration &&
                        grant2->start_time < grant1->start_time + grant1->duration);
    return overlap_time && (grant1->frequency == grant2->frequency);
}

// Function to generate non-overlapping downlink grants
void generate_dl_grants(DL_GRANT_INFO* dl_grants, size_t num_grants) {
    for (size_t i = 0; i < num_grants; ++i) {
        int frequency;
        int start_time;
        int duration;

        do {
            // Generate random parameters ensuring no overlap
            frequency = rand() % 100 + 1; // Frequency range example: 1 to 100 MHz
            start_time = rand() % (1000 - 10); // Start time within a large window, e.g., 1000 ms
            duration = rand() % 10 + 1; // Duration range: 1 to 10 ms

        } while (i > 0 && is_overlap(&dl_grants[i], &dl_grants[i - 1]));

        dl_grants[i].frequency = frequency;
        dl_grants[i].start_time = start_time;
        dl_grants[i].duration = duration;
    }
}

// Main function to manage the dynamic array
LTE_ENB_RRC_API_STRUCTURE* manage_dynamic_array(size_t num_ues) {
    if (num_ues > MAX_UES) {
        fprintf(stderr, "Number of UEs exceeds maximum allowed.\n");
        return NULL;
    }

    LTE_ENB_RRC_API_STRUCTURE* enb_rrc_api_structures = malloc(num_ues * sizeof(LTE_ENB_RRC_API_STRUCTURE));
    if (!enb_rrc_api_structures) {
        fprintf(stderr, "Failed to allocate memory for LTE_ENB_RRC_API_STRUCTURES.\n");
        return NULL;
    }

    for (size_t i = 0; i < num_ues; ++i) {
        enb_rrc_api_structures[i].UE_ID = i + 1;
        enb_rrc_api_structures[i].MAC_entity = get_mac_entity(enb_rrc_api_structures[i].UE_ID);

        if (!enb_rrc_api_structures[i].MAC_entity) {
            fprintf(stderr, "Failed to retrieve MAC entity for UE ID %d.\n", (int)enb_rrc_api_structures[i].UE_ID);
            free(enb_rrc_api_structures);
            return NULL;
        }

        // Generate random number of downlink grants per UE
        enb_rrc_api_structures[i].num_dl_grants = rand() % MAX_DL_GRANTS + 1;

        generate_dl_grants(enb_rrc_api_structures[i].dl_grants, enb_rrc_api_structures[i].num_dl_grants);
    }

    return enb_rrc_api_structures;
}

// Example usage
int main() {
    srand(time(NULL)); // Seed random number generator
    initialize_mac_cache();

    size_t num_ues = 10; // For example, managing 10 UEs

    LTE_ENB_RRC_API_STRUCTURE* structures = manage_dynamic_array(num_ues);
