class ClinicService {
    private $pdo;
    private $logger;
    private $cache;

    public function __construct(PDO $pdo, LoggerInterface $logger, CacheInterface $cache) {
        $this->pdo = $pdo;
        $this->logger = $logger;
        $this->cache = $cache;
    }

    public function updateClinicStatus($clinicId, $newStatus, $lastModifiedIp) {
        try {
            // Acquire a lock to ensure thread safety
            $lockKey = "update_lock_{$clinicId}";
            if (!$this->acquireLock($lockKey)) {
                throw new Exception("Could not acquire lock");
            }

            $currentTime = date('Y-m-d H:i:s');

            // Fetch current clinic data from cache or database
            $cachedData = $this->cache->get($clinicId);
            if (!$cachedData) {
                $stmt = $this->pdo->prepare("SELECT * FROM clinics WHERE id = :id");
                $stmt->execute([':id' => $clinicId]);
                $cachedData = $stmt->fetch(PDO::FETCH_ASSOC);
                if (!$cachedData) {
                    throw new Exception("Clinic not found");
                }
                $this->cache->set($clinicId, $cachedData);
            }

            // Update clinic status in the database
            $stmt = $this->pdo->prepare("
                UPDATE clinics 
                SET status = :status, last_modified_ip = :lastModifiedIp, last_modified_date = :currentTime 
                WHERE id = :id
            ");
            $stmt->execute([
                ':status' => $newStatus,
                ':lastModifiedIp' => $lastModifiedIp,
                ':currentTime' => $currentTime,
                ':id' => $clinicId
            ]);

            // Update cache with new data
            $cachedData['status'] = $newStatus;
            $cachedData['last_modified_ip'] = $lastModifiedIp;
            $cachedData['last_modified_date'] = $currentTime;
            $this->cache->set($clinicId, $cachedData);

            // Release the lock
            $this->releaseLock($lockKey);

            // Log success
            $this->logger->info("Updated clinic status for ID: {$clinicId}", [
                'status' => $newStatus,
                'lastModifiedIp' => $lastModifiedIp,
                'timestamp' => $currentTime
            ]);

            return "Update successful";

        } catch (Exception $e) {
            // Log error
            $this->logger->error("Failed to update clinic status for ID: {$clinicId}", [
                'exception' => $e->getMessage()
            ]);
            return "Update failed: " . $e->getMessage();
        }
    }

    private function acquireLock($key, $timeout = 5) {
        // Implement a lock acquisition mechanism (e.g., using Redis or Memcached)
        return true; // Placeholder
    }

    private function releaseLock($key) {
        // Implement a lock release mechanism
    }

    public function getDatabaseStatistics() {
        try {
            $stmt = $this->pdo->query("SELECT COUNT(*) AS active_entries FROM clinics");
            $result = $stmt->fetch(PDO::FETCH_ASSOC);
            $activeEntries = $result['active_entries'];

            $stmt = $this->pdo->query("
                SELECT AVG(TIMESTAMPDIFF(SECOND, last_modified_date, NOW())) AS avg_mod_freq 
                FROM clinics
            ");
            $result = $stmt->fetch(PDO::FETCH_ASSOC);
            $avgModFreq = $result['avg_mod_freq'];

            return [
