typedef enum {
    RRC_MESSAGE_TYPE_LC_GID_REQ,
    // Add other message types as needed
} RRC_MESSAGE_TYPE;

typedef enum {
    LCG_STATE_INVALID,
    LCG_STATE_ACTIVE,
    LCG_STATE_INACTIVE,
    // Add other states as needed
} LCG_STATE;

// Structure definitions
typedef struct {
    char *payload;
    size_t payload_size;
} MessagePayload;

typedef struct {
    RRC_MESSAGE_TYPE type;
    char *LCID;
    LCG_STATE state;
    MessagePayload payload;
} LTE_RRC_CU_PDU;

typedef struct Node {
    LTE_RRC_CU_PDU data;
    struct Node* next;
} ListNode;

// Function prototypes
ListNode* initializeLCGSetupRequests(int num_requests);
void freeList(ListNode *head);

pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

// Main function to manage dynamic list of LCG setup requests
ListNode* initializeLCGSetupRequests(int num_requests) {
    pthread_mutex_lock(&listMutex);

    ListNode *head = NULL, **lastPtr = &head;
    srand((unsigned int)time(NULL)); // Seed for random state generation

    for (int i = 0; i < num_requests; ++i) {
        LTE_RRC_CU_PDU* pdu = malloc(sizeof(LTE_RRC_CU_PDU));
        if (!pdu) {
            perror("Failed to allocate memory");
            freeList(head);
            pthread_mutex_unlock(&listMutex);
            return NULL;
        }

        // Initialize the LCID and state
        char lcid_buffer[16];
        snprintf(lcid_buffer, sizeof(lcid_buffer), "LCG_ID_%d", i + 1);
        pdu->LCID = strdup(lcid_buffer);

        pdu->type = RRC_MESSAGE_TYPE_LC_GID_REQ; // Example type, extend as needed
        pdu->state = (LCG_STATE)(rand() % 3); // Random state

        // Allocate payload based on message type
        size_t payload_size;
        switch (pdu->type) {
            case RRC_MESSAGE_TYPE_LC_GID_REQ:
                payload_size = 128; // Example size, adjust as needed
                break;
            default:
                free(pdu->LCID);
                free(pdu);
                perror("Invalid message type");
                freeList(head);
                pthread_mutex_unlock(&listMutex);
                return NULL;
        }

        pdu->payload.payload = malloc(payload_size);
        if (!pdu->payload.payload) {
            fprintf(stderr, "Failed to allocate payload memory\n");
            free(pdu->LCID);
            free(pdu);
            freeList(head);
            pthread_mutex_unlock(&listMutex);
            return NULL;
        }
        memset(pdu->payload.payload, 0, payload_size); // Initialize with zeros
        pdu->payload.payload_size = payload_size;

        // Append to the list
        ListNode *newNode = malloc(sizeof(ListNode));
        if (!newNode) {
            perror("Failed to allocate memory for node");
            free(pdu->LCID);
            free(pdu->payload.payload);
            free(pdu);
            freeList(head);
            pthread_mutex_unlock(&listMutex);
            return NULL;
        }
        newNode->data = *pdu;
        newNode->next = NULL;

        *lastPtr = newNode;
        lastPtr = &newNode->next;
    }

    pthread_mutex_unlock(&listMutex);

    // Logging allocation success
    printf("Successfully initialized %d LCG setup requests.\n", num_requests);

    return head;
}

void freeList(ListNode *head) {
    ListNode *current = head;
    while (current != NULL) {
        ListNode *nextNode = current->next;
        free(current->data.LCID);
        free(current->data.payload.payload);
        free(current);
        current = nextNode;
    }
}
