typedef struct BundleItem {
    char key[MAX_LINE_LENGTH];
    char value[MAX_LINE_LENGTH];
    struct BundleItem *next;
} BundleItem;

int load_resource_bundle(const char *path, void (*callback)(BundleItem *)) {
    FILE *file = fopen(path, "r");
    if (!file) return -1;

    size_t line_size = MAX_LINE_LENGTH;
    char *line = malloc(line_size);
    if (!line) {
        fclose(file);
        return -2;
    }

    BundleItem *head = NULL, *tail = NULL;
    int item_count = 0;

    while (fgets(line, line_size, file)) {
        // Skip empty lines and comments
        if (strchr(line, '#') || strlen(line) < 3) continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (!key || !value) continue; // Malformed line

        BundleItem *new_item = malloc(sizeof(BundleItem));
        if (!new_item) {
            fclose(file);
            free(line);
            while (head) { // Free list
                BundleItem *tmp = head;
                head = head->next;
                free(tmp);
            }
            return -3;
        }

        strncpy(new_item->key, key, MAX_LINE_LENGTH);
        strncpy(new_item->value, value, MAX_LINE_LENGTH);
        new_item->next = NULL;

        if (!head) {
            head = tail = new_item;
        } else {
            tail->next = new_item;
            tail = new_item;
        }
        item_count++;

        // Call the callback for each loaded item
        if (callback) callback(new_item);
    }

    free(line);
    fclose(file);

    return item_count; 
}

void process_bundle_item(BundleItem *item) {
    printf("Processing %s: %s\n", item->key, item->value);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <resource file path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_items = load_resource_bundle(argv[1], process_bundle_item);
    if (num_items < 0) {
        fprintf(stderr, "Failed to load resource bundle\n");
        return EXIT_FAILURE;
    }

    printf("Loaded %d items from the resource bundle.\n", num_items);

    // Create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
    int n = 5; // Example number of elements, could be parameterized
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;

