        NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) return EXIT_FAILURE;

        new_node->RX_UE_INFORMATION_TAG = rand() % 256;
        new_node->RNTI = rand() % 65536;
        new_node->CRC_INDICATION_REL8_TAG = rand();
        new_node->CRCFLAG = rand() & 1; // Randomly set to 0 or 1
        new_node->next = NULL;

        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    printf("Created a linked list with %d NFAPI_CRC_INDICATION_PDU_T structures.\n", n);

    // Cleanup
    while (head) {
        NFAPI_CRC_INDICATION_PDU_T *tmp = head;
