NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_structures(size_t *num_structs, int criteria_met[], TransactionMetrics metrics[], size_t max_metrics) {
    size_t num_bytes = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t max_structs = MEMORY_LIMIT_MB * 1024 * 1024 / num_bytes;

    if (max_structs > MAX_STRUCTS) {
        max_structs = MAX_STRUCTS;
    }

