    uint32_t tag_pool[MAX_STRUCTS];
    size_t current_size = 0;

    while (1) {
        structures = realloc(structures, num_bytes * (*num_structs));
        if (!structures) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
