    int max_transaction_id = -1;

    for (size_t i = 0; i < *num_structs; ++i) {
        // Example criteria check and metrics update
        if (criteria_met[i] && metrics[i].weighted_sum > max_weighted_sum) {
            max_weighted_sum = metrics[i].weighted_sum;
            max_transaction_id = i;
        }
    }

    printf("Max Weighted Sum: %f, Transaction ID: %d\n", max_weighted_sum, max_transaction_id);

    return structures;
}

