#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h> // For inet_pton

#define MAX_NICS 100

typedef struct {
    uint8_t MAC[6];
    struct in_addr IPv4;
    struct in6_addr IPv6;
    struct in_addr SubnetMaskIPv4;
    struct in6_addr SubnetMaskIPv6;
} NICConfig;

typedef struct {
    // Placeholder structure for RX_UE_INFORMATION_TAG and RNTI
    int RX_UE_INFORMATION_TAG; 
    int RNTI; 
} RX_UE_INFO_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFO_TAG ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NICSettingsNode {
    NICConfig config;
    NFAPI_CRC_INDICATION_PDU_T *pdus; // Dynamically allocated array
    int pdu_count;
    struct NICSettingsNode *next; 
} NICSettingsNode;

pthread_mutex_t nic_settings_lock = PTHREAD_MUTEX_INITIALIZER;
NICSettingsNode *nic_list_head = NULL;

// Function to validate IP addresses (both IPv4 and IPv6)
int is_valid_ip(const char* ip, int version) {
    if (version == 4) {
        struct in_addr addr;
        return inet_pton(AF_INET, ip, &addr) != 0;
    } else if (version == 6) {
        struct in6_addr addr;
        return inet_pton(AF_INET6, ip, &addr) != 0;
    }
    return 0;
}

// Function to generate a random MAC address
void generate_random_mac(uint8_t mac[6]) {
    for (int i = 0; i < 5; ++i)
        mac[i] = rand() % 256;
    mac[5] = (rand() % 2) * 1 | 1; // Ensure the least significant bit is 1
}

// Function to generate random CRCFLAG
void set_random_crcflag(CRC_INDICATION_REL8_TAG *crc_tag) {
    crc_tag->CRCFLAG = rand() % 256;
}

// Initialize NIC settings array and populate it with valid configurations
int initialize_nic_settings(int num_nics, const char* ipv4[], const char* ipv6[], 
                            const char* subnet_mask_ipv4[], const char* subnet_mask_ipv6[]) {
    pthread_mutex_lock(&nic_settings_lock);

    if (num_nics > MAX_NICS) {
        fprintf(stderr, "Exceeds maximum number of NIC settings.\n");
        pthread_mutex_unlock(&nic_settings_lock);
        return -1;
    }

    for (int i = 0; i < num_nics; ++i) {
        // Create a new node
        NICSettingsNode *node = malloc(sizeof(NICSettingsNode));
        if (!node) {
            fprintf(stderr, "Memory allocation failed.\n");
            pthread_mutex_unlock(&nic_settings_lock);
            return -1;
        }

        // Generate and set MAC address
        generate_random_mac(node->config.MAC);

        // Set IPv4 configuration
        if (is_valid_ip(ipv4[i], 4)) {
            inet_pton(AF_INET, ipv4[i], &node->config.IPv4);
        } else {
            fprintf(stderr, "Invalid IPv4 address.\n");
            free(node);
            pthread_mutex_unlock(&nic_settings_lock);
            return -1;
        }

        // Set IPv6 configuration
        if (is_valid_ip(ipv6[i], 6)) {
            inet_pton(AF_INET6, ipv6[i], &node->config.IPv6);
        } else {
            fprintf(stderr, "Invalid IPv6 address.\n");
            free(node);
            pthread_mutex_unlock(&nic_settings_lock);
            return -1;
        }

        // Set subnet mask for IPv4
        if (is_valid_ip(subnet_mask_ipv4[i], 4)) {
            inet_pton(AF_INET, subnet_mask_ipv4[i], &node->config.SubnetMaskIPv4);
        } else {
            fprintf(stderr, "Invalid Subnet Mask IPv4.\n");
            free(node);
            pthread_mutex_unlock(&nic_settings_lock);
            return -1;
        }

        // Set subnet mask for IPv6
        if (is_valid_ip(subnet_mask_ipv6[i], 6)) {
            inet_pton(AF_INET6, subnet_mask_ipv6[i], &node->config.SubnetMaskIPv6);
        } else {
            fprintf(stderr, "Invalid Subnet Mask IPv6.\n");
            free(node);
            pthread_mutex_unlock(&nic_settings_lock);
            return -1;
        }

        // Allocate and initialize PDUs
        node->pdu_count = 10; // Example count
        node->pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * node->pdu_count);
        if (!node->pdus) {
            fprintf(stderr, "Memory allocation for PDUs failed.\n");
            free(node);
            pthread_mutex_unlock(&nic_settings_lock);
            return -1;
        }

        for (int j = 0; j < node->pdu_count; ++j) {
            node->pdus[j].ue_info_tag.RX_UE_INFORMATION_TAG = rand();
            node->pdus[j].ue_info_tag.RNTI = rand();
            set_random_crcflag(&node->pdus[j].crc_indication_rel8_tag);
        }

        // Add to linked list
        node->next = nic_list_head;
        nic_list_head = node;
    }

    pthread_mutex_unlock(&nic_settings_lock);
    return 0;
}

// Cleanup function for NIC settings
void cleanup_nic_settings() {
    pthread_mutex_lock(&nic_settings_lock);

    NICSettingsNode *current = nic_list_head;
    while (current) {
        NICSettingsNode *next = current->next;
        free(current->pdus);
        free(current);
        current = next;
    }

    nic_list_head = NULL;

    pthread_mutex_unlock(&nic_settings_lock);
}
