    RX_UE_INFORMATION_TAG ueInformationTag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a unique RNTI based on a seed.
uint32_t generateRNTI(uint32_t seed, int index) {
    return (seed + index * 1001) % 65535; // Example logic for reproducible generation.
}

// Function to allocate memory and initialize the array of structures.
NFAPI_CRC_INDICATION_PDU_T* allocateAndInitializeArray(int numElements, uint32_t seed, uint16_t minRNTI, uint16_t maxRNTI) {
    NFAPI_CRC_INDICATION_PDU_T* pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pduArray) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Seed random number generator for CRCFLAG.
    srand(time(NULL));

    for (int i = 0; i < numElements; ++i) {
        pduArray[i].ueInformationTag.RNTI = generateRNTI(seed, i);

        if (pduArray[i].ueInformationTag.RNTI < minRNTI || pduArray[i].ueInformationTag.RNTI > maxRNTI) {
            fprintf(stderr, "RNTI validation failed for index %d: RNTI = %u\n", i, pduArray[i].ueInformationTag.RNTI);
            free(pduArray);
            return NULL;
        }

        pduArray[i].rnti = pduArray[i].ueInformationTag.RNTI;

        // Set CRCFLAG randomly.
        pduArray[i].crcIndicationRel8Tag.CRCFLAG = rand() % 2; // Randomly set to 0 or 1.

        if (pduArray[i].crcIndicationRel8Tag.CRCFLAG != 0 && pduArray[i].crcIndicationRel8Tag.CRCFLAG != 1) {
            fprintf(stderr, "CRCFLAG validation failed for index %d\n", i);
            free(pduArray);
            return NULL;
        }
    }

    return pduArray;
}

// Example usage of the function
int main() {
    int numElements = 10; // Example number of elements.
    uint32_t seed = 12345; // Example seed for reproducibility.
    uint16_t minRNTI = 1, maxRNTI = 65534; // Valid RNTI range.

    NFAPI_CRC_INDICATION_PDU_T* pduArray = allocateAndInitializeArray(numElements, seed, minRNTI, maxRNTI);

    if (pduArray) {
        // Use the array as needed.

        // Free allocated memory after usage.
        free(pduArray);
    }

    return 0;
}
