    DL_FRAME_TAG frame_tag;
    PHY_LAYER_CONTEXT *phy_layer_context;
    FRAME_INFO frame_info;
} LTE_DL_FRAME_MESSAGE;

typedef struct {
    LTE_DL_FRAME_MESSAGE **frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} FrameManager;

FrameManager* init_frame_manager(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    FrameManager *manager = malloc(sizeof(FrameManager));
    if (!manager) return NULL;

    manager->frames = malloc(initial_capacity * sizeof(LTE_DL_FRAME_MESSAGE *));
    if (!manager->frames) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void resize_frames(FrameManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    LTE_DL_FRAME_MESSAGE **new_frames = realloc(manager->frames, new_capacity * sizeof(LTE_DL_FRAME_MESSAGE *));

    if (!new_frames) {
        perror("Failed to reallocate memory for frames");
        return; // Handle error appropriately
    }

    manager->frames = new_frames;
    manager->capacity = new_capacity;
}

int add_frame(FrameManager *manager, DL_FRAME_TAG frame_tag, PHY_LAYER_CONTEXT *context, FRAME_INFO info) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count == manager->capacity) {
        resize_frames(manager);
        if (!manager->frames) { // Check for reallocation failure
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
    }

    LTE_DL_FRAME_MESSAGE *new_frame = malloc(sizeof(LTE_DL_FRAME_MESSAGE));
    if (!new_frame) {
        perror("Failed to allocate memory for new frame");
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Handle error appropriately
    }

    new_frame->frame_tag = frame_tag;
    new_frame->phy_layer_context = context;
    new_frame->frame_info = info;

    manager->frames[manager->count++] = new_frame;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

LTE_DL_FRAME_MESSAGE* get_latest_frame(FrameManager *manager) {
    if (manager->count == 0) return NULL;

    pthread_mutex_lock(&manager->mutex);
    LTE_DL_FRAME_MESSAGE *latest_frame = manager->frames[manager->count - 1];
    pthread_mutex_unlock(&manager->mutex);

    return latest_frame;
}

void cleanup_frame_manager(FrameManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->frames[i]);
    }

    free(manager->frames);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

// Example usage
int main() {
    FrameManager *frame_manager = init_frame_manager(10);

    if (!frame_manager) {
        fprintf(stderr, "Failed to initialize frame manager\n");
        return EXIT_FAILURE;
    }

    DL_FRAME_TAG tag = { .tag = 1 };
    PHY_LAYER_CONTEXT context; // Initialize as needed
    FRAME_INFO info = { .frame_number = 42, .other_metadata = 0 };

    if (add_frame(frame_manager, tag, &context, info) != 0) {
        fprintf(stderr, "Failed to add frame\n");
        cleanup_frame_manager(frame_manager);
        return EXIT_FAILURE;
    }

    LTE_DL_FRAME_MESSAGE *latest_frame = get_latest_frame(frame_manager);
    if (latest_frame) {
        printf("Latest Frame Tag: %d, Frame Number: %d\n", latest_frame->frame_tag.tag, latest_frame->frame_info.frame_number);
    } else {
        fprintf(stderr, "No frames available\n");
    }

    cleanup_frame_manager(frame_manager);

    return EXIT_SUCCESS;
}
```

### Key Points:

- **Memory Management**: The `FrameManager` structure dynamically resizes as needed using `realloc`. Memory is properly freed during cleanup to avoid leaks.

- **Concurrency Control**: A mutex (`pthread_mutex_t`) ensures thread-safe operations when adding frames or accessing the latest frame.

- **Modularity**: Functions are separated for initialization, resizing, adding frames, retrieving the latest frame, and cleanup.

- **Error Handling**: Error conditions like memory allocation failures are checked and handled gracefully.

- **Scalability**: The dynamic array resizes automatically, allowing efficient scaling with increasing data. 

This implementation balances performance, modularity, and robustness as required by the task constraints.']

