import logging

#define MAX_FRAMES 100

typedef struct {
    int tag; // DL_FRAME_TAG
} DL_FRAME_TAG;

typedef struct {
    void *context;
} PHY_LAYER_CONTEXT;

typedef struct {
    int frame_number;
} FRAME_INFO;

typedef struct LTE_DL_FRAME_MESSAGE {
    DL_FRAME_TAG dl_frame_tag;
    PHY_LAYER_CONTEXT *phy_layer_context;
    FRAME_INFO frame_info;
} LTE_DL_FRAME_MESSAGE;

typedef struct FrameManager {
    LTE_DL_FRAME_MESSAGE **frames;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    FILE *log_file;
} FrameManager;

// Initialize logging
void init_logging(FrameManager *manager) {
    manager->log_file = fopen("frame_manager.log", "a");
}

void log_event(FrameManager *manager, const char *event) {
    if (manager->log_file) {
        fprintf(manager->log_file, "%s\n", event);
        fflush(manager->log_file); // Ensure the message is written immediately
    }
}

FrameManager* init_frame_manager() {
    FrameManager *manager = malloc(sizeof(FrameManager));
    manager->capacity = MAX_FRAMES;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    init_logging(manager);
    log_event(manager, "Frame Manager initialized");

    manager->frames = calloc(manager->capacity, sizeof(LTE_DL_FRAME_MESSAGE*));

    return manager;
}

void free_frame_manager(FrameManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->frames[i]);
    }
    free(manager->frames);
    fclose(manager->log_file);
    log_event(manager, "Frame Manager reset");

    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_frame(FrameManager *manager, LTE_DL_FRAME_MESSAGE *frame) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        // Remove oldest frame
        free(manager->frames[0]);
        for (size_t i = 1; i < manager->count; ++i) {
            manager->frames[i - 1] = manager->frames[i];
        }
        --manager->count;
    }

    manager->frames[manager->count++] = frame;

    log_event(manager, "Frame added");

    pthread_mutex_unlock(&manager->lock);
}

LTE_DL_FRAME_MESSAGE* get_latest_frame(FrameManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == 0) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    LTE_DL_FRAME_MESSAGE *latest = manager->frames[manager->count - 1];

    log_event(manager, "Latest frame retrieved");

    pthread_mutex_unlock(&manager->lock);
    return latest;
}

void reset_frame_manager(FrameManager *manager) {
    free_frame_manager(manager);
    init_frame_manager();
}
