typedef enum {
    CONNECTION_ESTABLISHED,
    DATA_TRANSMISSION,
    // Add other network event types as needed
} NetworkEventType;

typedef struct {
    time_t timestamp;
    NetworkEventType eventType;
    int nodeId;
    size_t packetSize;
    double latency;  // in milliseconds or any suitable unit
} NetworkEventRecord;

// Thread-safe queue structure for high concurrency handling
typedef struct {
    NetworkEventRecord *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} EventQueue;

void initialize_queue(EventQueue *queue, size_t initial_capacity) {
    queue->records = (NetworkEventRecord *)malloc(initial_capacity * sizeof(NetworkEventRecord));
    if (!queue->records) {
        perror("Failed to allocate memory for event records");
        exit(EXIT_FAILURE);
    }
    queue->capacity = initial_capacity;
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);
}

void free_queue(EventQueue *queue) {
    free(queue->records);
    pthread_mutex_destroy(&queue->lock);
}

int add_event_record(EventQueue *queue, NetworkEventRecord record) {
    pthread_mutex_lock(&queue->lock);

    if (queue->count >= queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        NetworkEventRecord *new_records = (NetworkEventRecord *)realloc(queue->records, new_capacity * sizeof(NetworkEventRecord));
        if (!new_records) {
            pthread_mutex_unlock(&queue->lock);
            perror("Failed to reallocate memory for event records");
            return -1;
        }
        queue->records = new_records;
        queue->capacity = new_capacity;
    }

    queue->records[queue->count++] = record;

    pthread_mutex_unlock(&queue->lock);
    return 0;
}

char *serialize_to_json(const EventQueue *queue) {
    cJSON *json_array = cJSON_CreateArray();
    if (!json_array) {
        fprintf(stderr, "Failed to create JSON array\n");
        return NULL;
    }

    for (size_t i = 0; i < queue->count; ++i) {
        cJSON *event_obj = cJSON_CreateObject();

        cJSON_AddNumberToObject(event_obj, "timestamp", queue->records[i].timestamp);
        cJSON_AddStringToObject(
            event_obj,
            "eventType",
            (queue->records[i].eventType == CONNECTION_ESTABLISHED) ? "CONNECTION_ESTABLISHED" : "DATA_TRANSMISSION"
        );
        cJSON_AddNumberToObject(event_obj, "nodeId", queue->records[i].nodeId);
        cJSON_AddNumberToObject(event_obj, "packetSize", queue->records[i].packetSize);
        cJSON_AddNumberToObject(event_obj, "latency", queue->records[i].latency);

        cJSON_AddItemToArray(json_array, event_obj);
    }

    char *json_string = cJSON_PrintUnformatted(json_array);
    cJSON_Delete(json_array);

    return json_string;
}

void log_event_records(EventQueue *queue) {
    char *json_output = serialize_to_json(queue);
    if (json_output) {
        printf("%s\n", json_output);
        free(json_output);
    }
}

int main() {
    EventQueue event_queue;
    initialize_queue(&event_queue, 10);

    NetworkEventRecord record1 = { time(NULL), CONNECTION_ESTABLISHED, 1234, 1024, 20.5 };
    add_event_record(&event_queue, record1);

    NetworkEventRecord record2 = { time(NULL) + 1000, DATA_TRANSMISSION, 5678, 2048, 15.3 };
    add_event_record(&event_queue, record2);

    log_event_records(&event_queue);

    free_queue(&event_queue);

    return 0;
}
```

