#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int tag;
} DL_FRAME_TAG;

typedef struct {
    // Metadata fields
    int frame_id;
    int timestamp;
} FRAME_INFO;

typedef struct {
    // Processing context fields
