    DL_FRAME_TAG dl_frame_tag;
    PHY_LAYER_CONTEXT* phy_layer_context;
    FRAME_INFO frame_info;
} LTE_DL_FRAME_MESSAGE;

typedef struct FramePool {
    LTE_DL_FRAME_MESSAGE** frames;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
} FramePool;

FramePool* create_frame_pool(size_t initial_capacity) {
    FramePool* pool = (FramePool*)malloc(sizeof(FramePool));
    if (!pool) return NULL;

    pool->frames = (LTE_DL_FRAME_MESSAGE**)malloc(initial_capacity * sizeof(LTE_DL_FRAME_MESSAGE*));
    if (!pool->frames) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        pool->frames[i] = NULL;
    }

    pool->capacity = initial_capacity;
    pool->count = 0;

    if (pthread_rwlock_init(&pool->lock, NULL) != 0) {
        free(pool->frames);
        free(pool);
        return NULL;
    }

    return pool;
}

void destroy_frame_pool(FramePool* pool) {
    pthread_rwlock_wrlock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->frames[i]) {
            free(pool->frames[i]->phy_layer_context);
            free(pool->frames[i]);
        }
    }

    free(pool->frames);
    pthread_rwlock_unlock(&pool->lock);

    pthread_rwlock_destroy(&pool->lock);
    free(pool);
}

int add_frame(FramePool* pool, LTE_DL_FRAME_MESSAGE* frame) {
    pthread_rwlock_wrlock(&pool->lock);

    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        LTE_DL_FRAME_MESSAGE** new_frames = realloc(pool->frames, new_capacity * sizeof(LTE_DL_FRAME_MESSAGE*));

        if (!new_frames) {
            pthread_rwlock_unlock(&pool->lock);
            return -1; // Memory allocation failed
        }

        for (size_t i = pool->capacity; i < new_capacity; ++i) {
            new_frames[i] = NULL;
        }

        pool->frames = new_frames;
        pool->capacity = new_capacity;
    }

    pool->frames[pool->count++] = frame;

    pthread_rwlock_unlock(&pool->lock);
    return 0; // Success
}

LTE_DL_FRAME_MESSAGE* get_latest_frame(FramePool* pool) {
    pthread_rwlock_rdlock(&pool->lock);

    if (pool->count == 0) {
        pthread_rwlock_unlock(&pool->lock);
        return NULL;
    }

    LTE_DL_FRAME_MESSAGE* latest_frame = pool->frames[pool->count - 1];

    pthread_rwlock_unlock(&pool->lock);
    return latest_frame;
}

int main() {
    // Example usage
    FramePool* pool = create_frame_pool(10);

    if (!pool) {
        fprintf(stderr, "Failed to initialize frame pool\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 5; ++i) {
        LTE_DL_FRAME_MESSAGE* frame = (LTE_DL_FRAME_MESSAGE*)malloc(sizeof(LTE_DL_FRAME_MESSAGE));
        if (!frame) continue;

        frame->dl_frame_tag.tag = i;
        frame->phy_layer_context = malloc(sizeof(PHY_LAYER_CONTEXT));
        if (!frame->phy_layer_context) {
            free(frame);
            continue;
        }
        frame->phy_layer_context->signal_strength = 100 - i; // Example value
        frame->frame_info.frame_id = i;
        frame->frame_info.timestamp = 1234567890 + i;

        add_frame(pool, frame);
    }

    LTE_DL_FRAME_MESSAGE* latest_frame = get_latest_frame(pool);
    if (latest_frame) {
        printf("Latest Frame ID: %d\n", latest_frame->frame_info.frame_id);
    }

    destroy_frame_pool(pool);

    return EXIT_SUCCESS;
}
