### Key Points:
- **Thread Safety**: The code uses a read-write lock (`pthread_rwlock_t`) to manage concurrent access, allowing multiple threads to read simultaneously while ensuring exclusive write access.
- **Dynamic Memory Management**: It dynamically allocates memory for frames and resizes the pool when needed.
- **Error Handling**: Basic error handling is included, such as checking for successful memory allocations.
- **Modularity**: The code is designed with clear interfaces (`create_frame_pool`, `add_frame`, `get_latest_frame`, `destroy_frame_pool`) to facilitate integration into a larger framework.']

['Below is the C code implementing a dynamic list manager for `NFAPI_CRC_INDICATION_PDU_T` structures, ensuring thread safety, memory management, and performance under concurrent access:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define MAX_ENTRIES 100000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG; // Randomly set
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t bucket_count;
    pthread_mutex_t lock;
    size_t size;
} CRCList;

unsigned int hash(uint32_t tag, size_t bucket_count) {
    return (tag * 2654435761U) % bucket_count;
}

CRCList* create_list(size_t initial_bucket_count) {
    CRCList* list = malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->buckets = calloc(initial_bucket_count, sizeof(Node*));
    if (!list->buckets) {
        free(list);
        return NULL;
    }

    list->bucket_count = initial_bucket_count;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;

    return list;
}

int add_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    unsigned int index = hash(entry.RX_UE_INFORMATION_TAG, list->bucket_count);
    Node* node = list->buckets[index];
    while (node) {
        if (node->data.RX_UE_INFORMATION_TAG == entry.RX_UE_INFORMATION_TAG) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Entry already exists
        }
        node = node->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    new_node->data = entry;
    new_node->next = list->buckets[index];
    list->buckets[index] = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);

    if (list->size > list->bucket_count * 0.7) {
        resize_list(list);
    }

    return 1; // Entry added successfully
}

void resize_list(CRCList* list) {
    size_t new_bucket_count = list->bucket_count * 2;
    Node** new_buckets = calloc(new_bucket_count, sizeof(Node*));
    if (!new_buckets) {
        fprintf(stderr, "Failed to allocate memory for resizing.\n");
        return;
    }

    for (size_t i = 0; i < list->bucket_count; ++i) {
        Node* node = list->buckets[i];
        while (node) {
            Node* next_node = node->next;
            unsigned int new_index = hash(node->data.RX_UE_INFORMATION_TAG, new_bucket_count);
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;
            node = next_node;
        }
    }

    free(list->buckets);
    list->buckets = new_buckets;
    list->bucket_count = new_bucket_count;
}

void log_operation(const char* message) {
    printf("%s\n", message);
}

size_t get_list_size(CRCList* list) {
    if (!list) return 0;

    pthread_mutex_lock(&list->lock);
    size_t size = list->size;
    pthread_mutex_unlock(&list->lock);

    return size;
}

void destroy_list(CRCList* list) {
    if (!list) return;

    for (size_t i = 0; i < list->bucket_count; ++i) {
        Node* node = list->buckets[i];
        while (node) {
            Node* next_node = node->next;
            free(node);
            node = next_node;
        }
    }

    free(list->buckets);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    CRCList* list = create_list(1024);
    if (!list) {
        fprintf(stderr, "Failed to create list.\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T entry = {12345, 6789, {0}};
    if (add_entry(list, entry)) {
        log_operation("Entry added successfully.");
    } else {
        log_operation("Failed to add entry or entry already exists.");
    }

    printf("Current list size: %zu\n", get_list_size(list));

    destroy_list(list);
    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` for thread-safe operations.
- **Unique Entries**: Ensures unique `RX_UE_INFORMATION_TAG` using a hash table with separate chaining to handle collisions.
- **Dynamic Resizing**: Automatically resizes the hash table when load factor exceeds 0.7.
- **Memory Management**: Prevents memory leaks by freeing all allocated nodes and handles allocation failures gracefully.
- **Logging**: Provides basic logging for operations.
- **Scalability**: Designed to handle up to 100,000 entries efficiently.

This implementation addresses concurrency, memory fragmentation, and scalability challenges while ensuring robust error handling and resource management.']

