```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <string.h>

#define MAX_LIST_SIZE 1000 // Configurable limit

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RNTI; // Radio Network Temporary Identifier
    char RX_UE_INFORMATION_TAG[64]; // Example UE information tag size
} UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    struct NFAPI_CRC_INDICATION_PDU_T *prev; // For two-way traversal
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU *head;
    NFAPI_CRC_INDICATION_PDU *tail;
    size_t count;
    pthread_mutex_t lock;
    void* pool_memory; // Pool allocator memory block
    size_t pool_size;
} CRC_Indication_List;

// Function prototypes
void list_init(CRC_Indication_List *list, size_t pool_size);
int insert_element(CRC_Indication_List *list, const UE_INFORMATION_TAG *ue_info, int crc_flag);
void cleanup_old_entries(CRC_Indication_List *list, size_t threshold);
void print_list(const CRC_Indication_List *list);
void free_pool_memory(CRC_Indication_List *list);

// Utility function to allocate memory from pool
static inline NFAPI_CRC_INDICATION_PDU* allocate_from_pool(void* pool, size_t block_size) {
    static char *current = NULL;
    if (!current) current = (char*)pool;

    if ((size_t)((char*)pool + pool_size - current) >= block_size) {
        void* block = current;
        current += block_size;
        return (NFAPI_CRC_INDICATION_PDU*)block;
    }
    return NULL; // Pool exhausted
}

// Initialize the list and set up the memory pool
void list_init(CRC_Indication_List *list, size_t pool_size) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    // Allocate a block of memory for the pool allocator
    list->pool_memory = malloc(pool_size);
    if (!list->pool_memory) {
        fprintf(stderr, "Failed to allocate memory for pool.\n");
        exit(EXIT_FAILURE);
    }
    list->pool_size = pool_size;
}

// Insert an element into the linked list
int insert_element(CRC_Indication_List *list, const UE_INFORMATION_TAG *ue_info, int crc_flag) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    NFAPI_CRC_INDICATION_PDU* new_node = allocate_from_pool(list->pool_memory, sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Allocation from pool failed
    }

    memcpy(&new_node->ue_info, ue_info, sizeof(UE_INFORMATION_TAG));
    new_node->crc_tag.CRCFLAG = crc_flag;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
    } else {
        list->head = new_node;
        new_node->prev = NULL;
    }
    list->tail = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Print the contents of the linked list
void print_list(const CRC_Indication_List *list) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    NFAPI_CRC_INDICATION_PDU* current = list->head;
    while (current) {
        printf("RNTI: %lu, RX_TAG: %s, CRCFLAG: %d\n",
               current->ue_info.RNTI,
               current->ue_info.RX_UE_INFORMATION_TAG,
               current->crc_tag.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}

// Clean up old entries to conserve memory
void cleanup_old_entries(CRC_Indication_List *list, size_t threshold) {
    pthread_mutex_lock(&list->lock);

    while (list->head && list->count > threshold) {
        NFAPI_CRC_INDICATION_PDU* temp = list->head;
        list->head = list->head->next;
        if (list->head) list->head->prev = NULL;

        // No explicit free for pool memory
        list->count--;
    }

    pthread_mutex_unlock(&list->lock);
}

// Free allocated pool memory when done with the list
void free_pool_memory(CRC_Indication_List *list) {
    if (list && list->pool_memory) {
        free(list->pool_memory);
        list->pool_memory = NULL;
    }
}

int main() {
    CRC_Indication_List list;
    list_init(&list, 1024 * 64); // Example pool size

    UE_INFORMATION_TAG ue_info = { .RNTI = 12345, .RX_UE_INFORMATION_TAG = "ExampleTag" };
    insert_element(&list, &ue_info, rand() % 2);

    print_list(&list);

    cleanup_old_entries(&list, MAX_LIST_SIZE / 2); // Example threshold

    free_pool_memory(&list);
    return 0;
}
```

This implementation efficiently manages a thread-safe linked list with a pool allocator. The synchronization is handled using mutexes to prevent race conditions during concurrent access. The code also supports two-way traversal and insertion, with appropriate error handling for scenarios such as full lists or failed memory allocations.']

