#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int UE_ID;
    int RNTI;
} UE_RNTI_T;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG_T CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Pre-defined UE identifiers and RNTIs
const UE_RNTI_T predefined_uers[] = {
    {1, 100}, {2, 101}, {3, 102},
    // Add more entries as required
};

int get_random_crcflag() {
    return rand() % 2; // Random CRCFLAG: 0 or 1
}

void log_message(const char* message) {
    printf("%s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T** initialize_nfa_list(size_t num_elements, int* actual_count) {
    if (num_elements > MAX_ELEMENTS) {
        *actual_count = 0;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** nfa_list = malloc(num_elements * sizeof(NFAAPI_CRC_INDICATION_PDU_T*));
    if (!nfa_list) {
        log_message("Memory allocation failed for list pointer.");
        *actual_count = 0;
        return NULL;
    }

    int crc_tags[MAX_ELEMENTS] = {0};
    int used_crcs = 0;

    size_t count = 0;
    srand((unsigned)time(NULL));

    while (count < num_elements && used_crcs < MAX_ELEMENTS) {
        pthread_mutex_lock(&lock);

        int ue_index = rand() % (sizeof(predefined_uers) / sizeof(UE_RNTI_T));
        if (crc_tags[predefined_uers[ue_index].RNTI]) continue;

        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            log_message("Memory allocation failed for structure.");
            pthread_mutex_unlock(&lock);
            break;
        }

        int crc_flag = get_random_crcflag();

        // Find a unique CRC tag
        int crc_tag_index;
        do {
            crc_tag_index = rand() % MAX_ELEMENTS;
        } while (crc_tags[crc_tag_index]);

        crc_tags[crc_tag_index] = 1; // Mark as used
        used_crcs++;

        pdu->RX_UE_INFORMATION_TAG = predefined_uers[ue_index].UE_ID;
        pdu->RNTI = predefined_uers[ue_index].RNTI;
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = crc_flag;

        nfa_list[count++] = pdu;
        pthread_mutex_unlock(&lock);
    }

    *actual_count = count;
    return nfa_list;
}

void serialize_nfa_list(NFAPI_CRC_INDICATION_PDU_T** list, size_t num_elements, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_message("Failed to open file for serialization.");
        return;
    }

    fwrite(&num_elements, sizeof(size_t), 1, file);

    for (size_t i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = list[i];
        fwrite(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);
}

void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T** list, size_t num_elements) {
    for (size_t i = 0; i < num_elements; ++i) {
        if (list[i]) {
            free(list[i]);
        }
    }
    free(list);
}
