DataPacket* initialize_data_packets(int num_packets, const size_t max_payload_size) {
    if (num_packets <= 0 || max_payload_size == 0) return NULL;

    // Allocate array of pointers to DataPackets
    DataPacket **packets = malloc(num_packets * sizeof(DataPacket *));
    if (!packets) {
        perror("Memory allocation failed for packet array");
        return NULL;
    }

    for (int i = 0; i < num_packets; ++i) {
        // Allocate memory for each DataPacket
        packets[i] = malloc(sizeof(DataPacket));
        if (!packets[i]) {
            fprintf(stderr, "Memory allocation failed for packet %d\n", i);
            // Free previously allocated packets in case of failure
            for (int j = 0; j < i; ++j) {
                free(packets[j]);
            }
            free(packets);
            return NULL;
        }

        // Initialize DataPacket fields
        packets[i]->packet_id = i + 1;
        packets[i]->timestamp = time(NULL); // Capture current timestamp

        // Dynamically allocate payload with size between 0 and max_payload_size
        size_t payload_size = rand() % (max_payload_size + 1);
        packets[i]->payload = malloc(payload_size);

        if (!packets[i]->payload) {
            fprintf(stderr, "Memory allocation failed for packet %d payload\n", i);
            free(packets[i]); // Free the DataPacket structure
            continue;         // Attempt to allocate next packet despite failure
        }

        // Simulate external data source payload fill (here just filled with 'X')
        memset(packets[i]->payload, 'X', payload_size);

        printf("Initialized Packet ID %d with timestamp %ld and payload size %zu\n", 
               packets[i]->packet_id, packets[i]->timestamp, payload_size);
    }

    return packets;
}

void free_data_packets(DataPacket **packets, int num_packets) {
    if (!packets) return;

    for (int i = 0; i < num_packets; ++i) {
        if (packets[i]) {
            free(packets[i]->payload); // Free the payload memory
            free(packets[i]);          // Free the DataPacket structure
        }
    }

    free(packets); // Finally, free the array of pointers to DataPackets
}

