} NFAPI_MESSAGE_PDU_T;

typedef struct {
    NFAPI_MESSAGE_PDU_T *array;
    size_t capacity;
    size_t count;
} DynamicArray;

void init_array(DynamicArray *da) {
    da->capacity = 10; // Initial capacity
    da->count = 0;
    da->array = malloc(da->capacity * sizeof(NFAPI_MESSAGE_PDU_T));
}

void free_array(DynamicArray *da) {
    free(da->array);
    da->array = NULL;
    da->capacity = 0;
    da->count = 0;
}

static void resize_array(DynamicArray *da) {
    size_t new_capacity = da->capacity * 2;
    NFAPI_MESSAGE_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_MESSAGE_PDU_T));
    if (new_array != NULL) {
        da->array = new_array;
        da->capacity = new_capacity;
    } else {
        // Handle memory allocation failure
        fprintf(stderr, "Failed to resize array\n");
        exit(EXIT_FAILURE);
    }
}

void insert_message(DynamicArray *da, NFAPI_MSG_TYPE msg_type, void *parameters) {
    if (da->count == da->capacity) {
        resize_array(da);
    }

    // Simulate MAC_ADDRESS generation and error handling
    unsigned char mac_address[6] = {0};
    int success = 1; // Simulate network call success

    if (success) {
        for (int i = 0; i < 6; ++i) {
            mac_address[i] = rand() % 256;
        }
    } else {
        // Handle failure
        fprintf(stderr, "Failed to generate MAC address\n");
        return;
    }

    NFAPI_MESSAGE_PDU_T pdu;
    pdu.msg_type = msg_type;
    pdu.parameters = parameters;
    memcpy(pdu.mac_timestamp.mac_address, mac_address, 6);
    pdu.mac_timestamp.timestamp = time(NULL);

    da->array[da->count++] = pdu;
}

NFAPI_MESSAGE_PDU_T *retrieve_message(DynamicArray *da, size_t index) {
    if (index < da->count) {
        return &da->array[index];
    }
    return NULL; // Index out of bounds
}

void serialize_array(const DynamicArray *da, FILE *file) {
    fwrite(&da->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < da->count; ++i) {
        fwrite(&da->array[i], sizeof(NFAPI_MESSAGE_PDU_T), 1, file);
    }
}

void deserialize_array(DynamicArray *da, FILE *file) {
    free_array(da);
    fread(&da->count, sizeof(size_t), 1, file);
    da->capacity = da->count;
    da->array = malloc(da->capacity * sizeof(NFAPI_MESSAGE_PDU_T));
    for (size_t i = 0; i < da->count; ++i) {
        fread(&da->array[i], sizeof(NFAPI_MESSAGE_PDU_T), 1, file);
    }
}

// Example usage
int main() {
    srand(time(NULL)); // Seed random number generator

    DynamicArray da;
    init_array(&da);

    void *params = NULL; // Placeholder for additional parameters
    insert_message(&da, NFAPI_MSG_TYPE_1, params);
    insert_message(&da, NFAPI_MSG_TYPE_2, params);

    FILE *file = fopen("data.bin", "wb");
    if (file) {
        serialize_array(&da, file);
        fclose(file);
    }

    DynamicArray da_copy;
    init_array(&da_copy);

    file = fopen("data.bin", "rb");
    if (file) {
        deserialize_array(&da_copy, file);
        fclose(file);
    }

    free_array(&da);
    free_array(&da_copy);

    return 0;
}
