```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

// Define constants for maximum sizes
#define MAX_UE_CONTEXTS 1000000
#define MAX_RRC_STATES 10

// Define the UE Context structure
typedef struct {
    uint64_t ue_id;
    char **rrc_states; // List of RRC states
    size_t rrc_state_count;
    char **mme_messages; // List of MME messages
    size_t mme_message_count;
} UE_Context;

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_flag; // Pseudo-randomly generated CRCFLAG
    char *crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a global array of UE Contexts and a mutex for thread safety
static UE_Context ue_contexts[MAX_UE_CONTEXTS];
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to seed the pseudo-random number generator
void seed_rng() {
    srand((unsigned int)time(NULL));
}

// Function to generate a pseudo-random CRC flag
uint8_t generate_crc_flag() {
    return rand() % 256;
}

// Function to validate and correct RNTI values
uint16_t validate_rnti(uint16_t rnti) {
    if (rnti < 1 || rnti > 0x7FFF) {
        fprintf(stderr, "Invalid RNTI value: %u. Correcting...\n", rnti);
        return rand() % 0x7FFF + 1;
    }
    return rnti;
}

// Function to create a new UE Context
UE_Context* create_ue_context(uint64_t ue_id) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < MAX_UE_CONTEXTS; ++i) {
        if (!ue_contexts[i].ue_id) { // Check if the slot is empty
            UE_Context *context = &ue_contexts[i];
            context->ue_id = ue_id;
            context->rrc_states = NULL;
            context->rrc_state_count = 0;
            context->mme_messages = NULL;
            context->mme_message_count = 0;

            pthread_mutex_unlock(&lock);
            return context;
        }
    }

    fprintf(stderr, "No available UE Context slots.\n");
    pthread_mutex_unlock(&lock);
    return NULL;
}

// Function to delete a UE Context
void delete_ue_context(uint64_t ue_id) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < MAX_UE_CONTEXTS; ++i) {
        if (ue_contexts[i].ue_id == ue_id) {
            // Free dynamically allocated memory
            free(ue_contexts[i].rrc_states);
            free(ue_contexts[i].mme_messages);

            // Reset the context
            ue_contexts[i].ue_id = 0;
            ue_contexts[i].rrc_state_count = 0;
            ue_contexts[i].mme_message_count = 0;

            pthread_mutex_unlock(&lock);
            return;
        }
    }

    fprintf(stderr, "UE Context with ID %llu not found.\n", ue_id);
    pthread_mutex_unlock(&lock);
}

// Function to create a new NFAPI_CRC_INDICATION_PDU_T
NFAPI_CRC_INDICATION_PDU_T* create_crc_pdu(uint32_t rx_ue_information_tag, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Memory allocation failed for CRC PDU.\n");
        return NULL;
    }

    pdu->rx_ue_information_tag = rx_ue_information_tag;
    pdu->rnti = validate_rnti(rnti);
    pdu->crc_flag = generate_crc_flag();
    pdu->crc_indication_rel8_tag = strdup("CRC_INDICATION_REL8_TAG");

    return pdu;
}

// Function to delete an NFAPI_CRC_INDICATION_PDU_T
void delete_crc_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu) {
        free(pdu->crc_indication_rel8_tag);
        free(pdu);
    }
}

// Serialize a UE Context to binary format
size_t serialize_ue_context(const UE_Context *context, uint8_t **buffer) {
    size_t total_size = sizeof(uint64_t) + 4; // ue_id + count for rrc_states and mme_messages
    total_size += context->rrc_state_count * (strlen(context->rrc_states[0]) + 1);
    total_size += context->mme_message_count * (strlen(context->mme_messages[0]) + 1);

    *buffer = malloc(total_size);
    if (!*buffer) {
        fprintf(stderr, "Memory allocation failed for UE Context serialization.\n");
        return 0;
    }

    size_t offset = 0;
    memcpy(*buffer + offset, &context->ue_id, sizeof(uint64_t));
    offset += sizeof(uint64_t);

    uint32_t rrc_state_count = context->rrc_state_count;
    memcpy(*buffer + offset, &rrc_state_count, sizeof(uint32_t));
    offset += sizeof(uint32_t);

    for (size_t i = 0; i < rrc_state_count; ++i) {
        size_t len = strlen(context->rrc_states[i]) + 1;
        memcpy(*buffer + offset, context->rrc_states[i], len);
        offset += len;
    }

    uint32_t mme_message_count = context->mme_message_count;
    memcpy(*buffer + offset, &mme_message_count, sizeof(uint32_t));
    offset += sizeof(uint32_t);

    for (size_t i = 0; i < mme_message_count; ++i) {
        size_t len = strlen(context->mme_messages[i]) + 1;
        memcpy(*buffer + offset, context->mme_messages[i], len);
        offset += len;
    }

    return total_size;
}

// Deserialize a UE Context from binary format
UE_Context* deserialize_ue_context(const uint8_t *buffer, size_t buffer_size) {
    if (buffer_size < sizeof(uint64_t) + 4) {
        fprintf(stderr, "Invalid buffer size for UE Context deserialization.\n");
        return NULL;
    }

    UE_Context *context = malloc(sizeof(UE_Context));
    if (!context) {
        fprintf(stderr, "Memory allocation failed for UE Context.\n");
        return NULL;
    }

    size_t offset = 0;
    memcpy(&context->ue_id, buffer + offset, sizeof(uint64_t));
    offset += sizeof(uint64_t);

    uint32_t rrc_state_count;
    memcpy(&rrc_state_count, buffer + offset, sizeof(uint32_t));
    offset += sizeof(uint32_t);

    context->rrc_states = malloc(rrc_state_count * sizeof(char*));
    if (!context->rrc_states) {
        fprintf(stderr, "Memory allocation failed for RRC states.\n");
        free(context);
        return NULL;
    }

    context->rrc_state_count = rrc_state_count;
    for (size_t i = 0; i < rrc_state_count; ++i) {
        size_t len;
        memcpy(&len, buffer + offset, sizeof(size_t));
        offset += sizeof(size_t);

        context->rrc_states[i] = malloc(len);
        if (!context->rrc_states[i]) {
            fprintf(stderr, "Memory allocation failed for RRC state.\n");
            free(context->rrc_states);
            free(context);
            return NULL;
        }

        memcpy(context->rrc_states[i], buffer + offset, len);
        offset += len;
    }

    uint32_t mme_message_count;
    memcpy(&mme_message_count, buffer + offset, sizeof(uint32_t));
    offset += sizeof(uint32_t);

    context->mme_messages = malloc(mme_message_count * sizeof(char*));
    if (!context->mme_messages) {
        fprintf(stderr, "Memory allocation failed for MME messages.\n");
        free(context->rrc_states);
        free(context);
        return NULL;
    }

    context->mme_message_count = mme_message_count;
    for (size_t i = 0; i < mme_message_count; ++i) {
        size_t len;
        memcpy(&len, buffer + offset, sizeof(size_t));
        offset += sizeof(size_t);

        context->mme_messages[i] = malloc(len);
        if (!context->mme_messages[i]) {
            fprintf(stderr, "Memory allocation failed for MME message.\n");
            free(context->mme_messages);
            free(context->rrc_states);
            free(context);
            return NULL;
        }

        memcpy(context->mme_messages[i], buffer + offset, len);
        offset += len;
    }

    return context;
}

// Serialize an NFAPI_CRC_INDICATION_PDU_T to binary format
size_t serialize_crc_pdu(const NFAPI_CRC_INDICATION_PDU_T *pdu, uint8_t **buffer) {
    size_t total_size = sizeof(uint32_t) + sizeof(uint16_t) + sizeof(uint8_t) + strlen(pdu->crc_indication_rel8_tag) + 1;

    *buffer = malloc(total_size);
    if (!*buffer) {
        fprintf(stderr, "Memory allocation failed for CRC PDU serialization.\n");
        return 0;
    }

    size_t offset = 0;
    memcpy(*buffer + offset, &pdu->rx_ue_information_tag, sizeof(uint32_t));
    offset += sizeof(uint32_t);

    memcpy(*buffer + offset, &pdu->rnti, sizeof(uint16_t));
    offset += sizeof(uint16_t);

    memcpy(*buffer + offset, &pdu->crc_flag, sizeof(uint8_t));
    offset += sizeof(uint8_t);

    size_t len = strlen(pdu->crc_indication_rel8_tag) + 1;
    memcpy(*buffer + offset, pdu->crc_indication_rel8_tag, len);
    offset += len;

    return total_size;
}

// Deserialize an NFAPI_CRC_INDICATION_PDU_T from binary format
NFAPI_CRC_INDICATION_PDU_T* deserialize_crc_pdu(const uint8_t *buffer, size_t buffer_size) {
    if (buffer_size < sizeof(uint32_t) + sizeof(uint16_t) + sizeof(uint8_t)) {
        fprintf(stderr, "Invalid buffer size for CRC PDU deserialization.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Memory allocation failed for CRC PDU.\n");
        return NULL;
    }

    size_t offset = 0;
    memcpy(&pdu->rx_ue_information_tag, buffer + offset, sizeof(uint32_t));
    offset += sizeof(uint32_t);

    memcpy(&pdu->rnti, buffer + offset, sizeof(uint16_t));
    offset += sizeof(uint16_t);

    memcpy(&pdu->crc_flag, buffer + offset, sizeof(uint8_t));
    offset += sizeof(uint8_t);

    size_t len;
    memcpy(&len, buffer + offset, sizeof(size_t));
    offset += sizeof(size_t);

    pdu->crc_indication_rel8_tag = malloc(len);
    if (!pdu->crc_indication_rel8_tag) {
        fprintf(stderr, "Memory allocation failed for CRC indication tag.\n");
        free(pdu);
        return NULL;
    }

    memcpy(pdu->crc_indication_rel8_tag, buffer + offset, len);

    return pdu;
}

// Main function to demonstrate usage
int main() {
    seed_rng();

    UE_Context *context = create_ue_context(12345ULL);
    if (context) {
        context->rrc_states = malloc(MAX_RRC_STATES * sizeof(char*));
        context->rrc_state_count = 1;
        context->rrc_states[0] = strdup("RRC_CONNECTED");

        context->mme_messages = malloc(1 * sizeof(char*));
        context->mme_message_count = 1;
        context->mme_messages[0] = strdup("MME_MESSAGE");

        uint8_t *serialized_context;
        size_t serialized_size = serialize_ue_context(context, &serialized_context);
        if (serialized_size) {
            printf("Serialized UE Context size: %zu\n", serialized_size);

            UE_Context *deserialized_context = deserialize_ue_context(serialized_context, serialized_size);
            free(serialized_context);

            delete_ue_context(12345ULL);
        } else {
            fprintf(stderr, "Failed to serialize UE Context.\n");
        }

        free(context->rrc_states[0]);
        free(context->mme_messages[0]);
        free(context->rrc_states);
        free(context->mme_messages);
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = create_crc_pdu(1, 10000);
    if (pdu) {
        uint8_t *serialized_pdu;
        size_t serialized_size = serialize_crc_pdu(pdu, &serialized_pdu);
        if (serialized_size) {
            printf("Serialized CRC PDU size: %zu\n", serialized_size);

            NFAPI_CRC_INDICATION_PDU_T *deserialized_pdu = deserialize_crc_pdu(serialized_pdu, serialized_size);
            free(serialized_pdu);
            delete_crc_pdu(deserialized_pdu);
        } else {
            fprintf(stderr, "Failed to serialize CRC PDU.\n");
        }

        delete_crc_pdu(pdu);
    }

    return 0;
}
