#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Hash)]
struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: String,
    rnti: u16,
    crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Hash)]
