    crcflag: bool,
}

fn create_directory_and_set_env_var(dir_name: &str) -> std::io::Result<()> {
    let path = format!("./{}", dir_name);
    if !path.exists() {
        fs::create_dir_all(&path)?;
    }

    let env_var_name = "MY_CUSTOM_PATH";
    let current_value = env::var(env_var_name).unwrap_or_default();
    if current_value.is_empty() {
        env::set_var(env_var_name, &path);
    }

    Ok(())
}

fn manage_nfa_pi_collection(ue_ids: Vec<String>, rnti_values: Vec<u16>) -> Result<Vec<NFAPI_CRC_INDICATION_PDU_T>, &'static str> {
    let mut unique_rntis = HashSet::new();
    let mut crc_tags_set = HashSet::new();

    let log_mutex = Arc::new(Mutex::new(Vec::new()));

    let max_elements = 10_000;
    let collection: Vec<NFAPI_CRC_INDICATION_PDU_T> = ue_ids
        .into_iter()
        .zip(rnti_values.into_iter())
        .filter_map(|(ue_id, rnti)| {
            if unique_rntis.contains(&rnti) {
                return None;
            }
            let crcflag: bool = rand::random();
            let crc_tag = CRC_INDICATION_REL8_TAG { crcflag };

            if !crc_tags_set.insert(crc_tag.clone()) {
                return None;
            }

            unique_rntis.insert(rnti);

            let pdu = NFAPI_CRC_INDICATION_PDU_T {
                rx_ue_information_tag: ue_id,
                rnti,
                crc_indication_rel8_tag: crc_tag,
            };

            match Arc::try_unwrap(Arc::new(Mutex::new(()))) {
                Ok(_) => info!("Created structure for UE ID {:?}", ue_id),
                Err(_) => error!("Mutex could not be unwrapped"),
            }

            Some(pdu)
        })
        .take(max_elements)
        .collect();

    if collection.len() < max_elements {
        let mut logs = log_mutex.lock().unwrap();
        logs.push("Completed with fewer elements due to constraints".to_string());
    }

    // Serialize the collection for later use
    let serialized_data = bincode::serialize(&collection).map_err(|_| "Serialization failed")?;

    Ok(collection)
}

fn main() {
    if let Err(e) = create_directory_and_set_env_var("my_directory") {
        eprintln!("Error creating directory or setting env var: {}", e);
    }

    // Dummy data
    let ue_ids = vec!["UE1".to_string(), "UE2".to_string()];
    let rnti_values = vec![100, 200];

    match manage_nfa_pi_collection(ue_ids, rnti_values) {
        Ok(collection) => info!("Managed collection: {:?}", collection),
        Err(e) => error!("Failed to manage collection: {}", e),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_unique_rntis() {
        let ue_ids = vec!["UE1".to_string(), "UE2".to_string()];
        let rnti_values = vec![100, 200];

        let collection = manage_nfa_pi_collection(ue_ids.clone(), rnti_values).unwrap();
        assert_eq!(collection.len(), 2);
    }

    #[test]
    fn test_duplicate_rntis() {
        let ue_ids = vec!["UE1".to_string(), "UE1".to_string()];
        let rnti_values = vec![100, 100];

        let collection = manage_nfa_pi_collection(ue_ids, rnti_values).unwrap();
        assert_eq!(collection.len(), 1);
    }

    #[test]
    fn test_directory_creation() {
        if let Err(e) = create_directory_and_set_env_var("test_dir") {
            eprintln!("Error creating directory: {}", e);
        }

        // Check environment variable
        let path = env::var("MY_CUSTOM_PATH").unwrap_or_default();
        assert!(path.contains("test_dir"));
    }
}
