    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_message("Memory allocation failed for the list.");
        return NULL;
    }

    pthread_rwlock_t rwlock;
    pthread_rwlock_init(&rwlock, NULL);

    unsigned int existing_rntis[MAX_ELEMENTS] = {0};
    CRC_INDICATION_REL8_TAG crc_tags[MAX_ELEMENTS] = {{0}};
    size_t rnti_count = 0, tag_count = 0;

