            crc_tags[tag_count++] = list[i].CRC_INDICATION_REL8_TAG;

            pthread_rwlock_unlock(&rwlock);

            if (is_memory_usage_excessive()) {
                log_message("Memory usage exceeded threshold. Re-allocating resources.");
                // Handle re-allocation logic
            }
        } else {
            unsigned int new_rnti = rnti;
            while (existing_rntis[new_rnti] && new_rnti < MAX_ELEMENTS) ++new_rnti;

            if (new_rnti >= MAX_ELEMENTS) {
                log_message("Failed to find a unique RNTI. Discarding entry.");
                continue; // Handle gracefully
            }

            existing_rntis[new_rnti] = 1;
            pthread_rwlock_wrlock(&rwlock);

            list[i].RX_UE_INFORMATION_TAG = "RX_Info_Tag"; // Placeholder
            list[i].RNTI = new_rnti;
            list[i].CRC_INDICATION_REL8_TAG = create_unique_crc_indication_tag(crc_tags, tag_count);

            crc_tags[tag_count++] = list[i].CRC_INDICATION_REL8_TAG;

            pthread_rwlock_unlock(&rwlock);
        }

        rnti_count++;
    }

    log_message("NFAPI_CRC_INDICATION_PDU_T initialization completed.");

    pthread_rwlock_destroy(&rwlock);
    return list;
}
