    pthread_mutex_destroy(&manager->lock);
}

void addLogEntry(EventLogManager *manager, NetworkEventLogEntry entry) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        manager->capacity *= 2;
        manager->entries = (NetworkEventLogEntry *)realloc(manager->entries, manager->capacity * sizeof(NetworkEventLogEntry));
    }

    manager->entries[manager->count++] = entry;

    pthread_mutex_unlock(&manager->lock);
}

void removeEntriesByType(EventLogManager *manager, EventType eventType) {
