    size_t write_index = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i].eventType != eventType) {
            manager->entries[write_index++] = manager->entries[i];
        }
    }

    manager->count = write_index;

    pthread_mutex_unlock(&manager->lock);
}

double calculateAverageDuration(EventLogManager *manager, EventType eventType) {
    pthread_mutex_lock(&manager->lock);

    double total_duration = 0;
    size_t event_count = 0;

    for (size_t i = 1; i < manager->count; ++i) {
        if (manager->entries[i].eventType == eventType && 
            manager->entries[i - 1].eventType == eventType) {

            time_t duration = difftime(manager->entries[i].timestamp, manager->entries[i - 1].timestamp);
            total_duration += duration;
            event_count++;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return (event_count > 0) ? (total_duration / event_count) : 0.0;
}

void flushLogEntries(EventLogManager *manager, void (*flushFunction)(NetworkEventLogEntry *, size_t)) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count > 0) {
        flushFunction(manager->entries, manager->count);
        // Reset the log after flushing
        manager->count = 0;
    }

    pthread_mutex_unlock(&manager->lock);
}

