        size_t newCapacity = array->capacity * 2;
        UserSessionActivity *newSessions = realloc(array->sessions, newCapacity * sizeof(UserSessionActivity));
        if (!newSessions) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->sessions = newSessions;
        array->capacity = newCapacity;
    }
    array->sessions[array->count++] = session;
    validateSessionWithAPI(session); // Validate with external API
}

// Update the logout time for a specific session by its ID
void updateLogoutTime(SessionArray *array, int sessionId, time_t logoutTime) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->sessions[i].sessionId == sessionId) {
            array->sessions[i].logoutTime = logoutTime;
            break;
        }
    }
}

// Remove sessions based on a specified IP address
void removeSessionsByIp(SessionArray *array, const char *ipAddress) {
    size_t i = 0;
    while (i < array->count) {
        if (strcmp(array->sessions[i].userIp, ipAddress) == 0) {
            for (size_t j = i; j < array->count - 1; ++j) {
                array->sessions[j] = array->sessions[j + 1];
            }
            --array->count;
        } else {
            ++i;
        }
    }
}

// Calculate the average duration between consecutive activities for each user
double calculateAverageDuration(SessionArray *array) {
    double totalDuration = 0.0;
    size_t count = 0;

    // Assuming sessions are sorted by loginTime for simplicity
    for (size_t i = 1; i < array->count; ++i) {
        if (strcmp(array->sessions[i - 1].userIp, array->sessions[i].userIp) == 0) {
            time_t duration = difftime(array->sessions[i].loginTime, array->sessions[i - 1].logoutTime);
            totalDuration += duration;
            ++count;
        }
    }

    return count ? (totalDuration / count) : 0.0;
}

// Filter sessions by activity type
size_t filterSessionsByType(const SessionArray *array, const char *activityType, SessionArray *result) {
    initSessionArray(result, array->count); // Initialize result with the same capacity

    for (size_t i = 0; i < array->count; ++i) {
        if (strcmp(array->sessions[i].activityType, activityType) == 0) {
            addSession(result, array->sessions[i]);
        }
    }

    return result->count;
}

// Count the number of active sessions in a given time window
