} CHANNEL_SUBFRAME_INFO;

typedef struct PHY_RX_PDU_T {
    CHANNEL_SUBFRAME_INFO channel_info;
    PHY_RX_DATA_TAG rx_data;
    struct PHY_RX_PDU_T *next;
} PHY_RX_PDU_T;

// Logging interface
void log_operation(const char *message) {
    printf("%s\n", message);
}

// Simulated function to fetch real-time SNR and BER values
bool get_real_time_sensor_data(int subframe_number, int channel_info_tag, int *snr, float *ber) {
