    *snr = rand() % 100; // Random SNR value between 0-99
    *ber = (float)rand() / RAND_MAX; // Random BER value between 0.0 - 1.0
    return true;
}

// Function to validate RX_CHANNEL_INFO_TAG and SUBFRAME_NUMBER
bool is_valid_data(int rx_channel_info_tag, int subframe_number) {
    // Placeholder validation logic
    return (rx_channel_info_tag > 0 && subframe_number >= 0);
}

// Cache mechanism for quick lookups
typedef struct {
    int key;
    PHY_RX_PDU_T *value;
} CacheEntry;

#define CACHE_SIZE 100
CacheEntry cache[CACHE_SIZE];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void cache_put(int key, PHY_RX_PDU_T *value) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache[i].key == 0 || cache[i].key == key) { // Empty slot or existing entry
            cache[i].key = key;
            cache[i].value = value;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);
}

PHY_RX_PDU_T* cache_get(int key) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache[i].key == key) {
            PHY_RX_PDU_T *value = cache[i].value;
            pthread_mutex_unlock(&cache_lock);
            return value;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

// Linked list management
PHY_RX_PDU_T* create_node(int rx_channel_info_tag, int subframe_number) {
    PHY_RX_PDU_T *node = (PHY_RX_PDU_T*)malloc(sizeof(PHY_RX_PDU_T));
    if (!node) {
        log_operation("Memory allocation failed for new node");
        return NULL;
    }

    node->channel_info.RX_CHANNEL_INFO_TAG = rx_channel_info_tag;
    node->channel_info.SUBFRAME_NUMBER = subframe_number;

    int snr;
    float ber;
    if (get_real_time_sensor_data(subframe_number, rx_channel_info_tag, &snr, &ber)) {
        node->rx_data.SNR = snr;
        node->rx_data.BER = ber;
    } else {
        log_operation("Failed to fetch real-time sensor data");
        free(node);
        return NULL;
    }

    node->next = NULL;
    return node;
}

void add_to_list(PHY_RX_PDU_T **head, PHY_RX_PDU_T *new_node) {
    if (!*head || (*head)->channel_info.SUBFRAME_NUMBER > new_node->channel_info.SUBFRAME_NUMBER) {
        new_node->next = *head;
        *head = new_node;
    } else {
        PHY_RX_PDU_T *current = *head;
        while (current->next && current->next->channel_info.SUBFRAME_NUMBER < new_node->channel_info.SUBFRAME_NUMBER) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

void free_list(PHY_RX_PDU_T *head) {
    PHY_RX_PDU_T *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Main function to construct and populate the linked list
PHY_RX_PDU_T* construct_phy_rx_pdu_list(int num_elements, int rx_channel_info_tags[], int subframe_numbers[]) {
    if (num_elements <= 0) return NULL;

    PHY_RX_PDU_T *head = NULL;

    for (int i = 0; i < num_elements; ++i) {
        int tag = rx_channel_info_tags[i];
        int number = subframe_numbers[i];

        if (!is_valid_data(tag, number)) {
            log_operation("Invalid data encountered");
            continue;
        }

        PHY_RX_PDU_T *cached_node = cache_get(tag);
        if (cached_node) {
            add_to_list(&head, cached_node);
            continue;
        }

        PHY_RX_PDU_T *new_node = create_node(tag, number);
        if (!new_node) continue;

        add_to_list(&head, new_node);
        cache_put(tag, new_node);
    }

    return head;
}

// Unit tests
void test_phy_rx_pdu_list() {
    int rx_channel_info_tags[] = {1, 2, 3, 4};
    int subframe_numbers[] = {10, 20, 30, 40};

    PHY_RX_PDU_T *list = construct_phy_rx_pdu_list(4, rx_channel_info_tags, subframe_numbers);

    // Verify list integrity and order
    PHY_RX_PDU_T *current = list;
    while (current) {
        printf("Subframe: %d, SNR: %d, BER: %.2f\n", current->channel_info.SUBFRAME_NUMBER, current->rx_data.SNR, current->rx_data.BER);
        current = current->next;
    }

    // Free the list
    free_list(list);
}

int main() {
    test_phy_rx_pdu_list();
    return 0;
}
