typedef struct {
    int crc_flag;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
} DynamicArray;

int initialize_dynamic_array(DynamicArray *dynamic_array) {
    dynamic_array->capacity = MAX_ENTRIES;
    dynamic_array->count = 0;

    dynamic_array->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(dynamic_array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynamic_array->array) {
        return -1; // Memory allocation failure
    }
    return 0;
}

int add_entry(DynamicArray *dynamic_array, int crc_flag) {
    if (dynamic_array->count >= dynamic_array->capacity) {
        fprintf(stderr, "Reached maximum capacity\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T new_entry = { .crc_flag = crc_flag };

    // Validate CRC flag
    if (new_entry.crc_flag != CRC_FLAG_VALID_CRITERIA) {
        fprintf(stderr, "Invalid CRC flag encountered: %d\n", new_entry.crc_flag);
        return -1;
    }

    dynamic_array->array[dynamic_array->count++] = new_entry;

    return 0;
}

void cleanup_dynamic_array(DynamicArray *dynamic_array) {
    if (dynamic_array->array) {
        free(dynamic_array->array);
        dynamic_array->array = NULL;
        dynamic_array->count = 0;
        dynamic_array->capacity = 0;
    }
}

int main() {
    DynamicArray dynamic_array;

    if (initialize_dynamic_array(&dynamic_array) != 0) {
        fprintf(stderr, "Failed to initialize dynamic array\n");
        return EXIT_FAILURE;
    }

    // Simulate adding entries
    for (int i = 0; i < 1005; ++i) { // Testing over capacity
        if (add_entry(&dynamic_array, CRC_FLAG_VALID_CRITERIA + (i % 2)) != 0) {
            fprintf(stderr, "Error adding entry: %d\n", i);
        }
    }

    cleanup_dynamic_array(&dynamic_array);

    return EXIT_SUCCESS;
}
