#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

// Constants
#define MAX_ELEMENTS 10000
#define RF_CHANNEL_CONFIG_BAND_LIMIT 1000

typedef struct {
    int PHY_TX_FRAME_CONFIG;
    uint8_t TX_POWER_LEVEL;
    int RF_CHANNEL_CONFIG;
} LTE_PHY_TX_RECORD;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe dynamic array structure
typedef struct {
    LTE_PHY_TX_RECORD *records;
    size_t count;
    pthread_mutex_t mutex;
    pthread_rwlock_t rwlock;
} DynamicArray;

// Cache mechanism for RF_CHANNEL_CONFIG and TX_POWER_LEVEL updates
typedef struct {
    int *RF_CHANNEL_CONFIG_cache;
    uint8_t *TX_POWER_LEVEL_cache;
    int cache_size;
} Cache;

// Initialize dynamic array
void initDynamicArray(DynamicArray *array) {
    array->records = NULL;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    pthread_rwlock_init(&array->rwlock, NULL);
}

// Free dynamic array resources
void freeDynamicArray(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->records);
    array->records = NULL;
    array->count = 0;
    pthread_mutex_unlock(&array->mutex);

    pthread_mutex_destroy(&array->mutex);
    pthread_rwlock_destroy(&array->rwlock);
}

// Add new element to the dynamic array
int addElement(DynamicArray *array, LTE_PHY_TX_RECORD record) {
    pthread_rwlock_wrlock(&array->rwlock);

    if (record.TX_POWER_LEVEL > 63 || record.RF_CHANNEL_CONFIG > RF_CHANNEL_CONFIG_BAND_LIMIT) {
        pthread_rwlock_unlock(&array->rwlock);
        return -1; // Invalid power level or RF channel
    }

    size_t new_size = array->count + 1;
    if (new_size > MAX_ELEMENTS) {
        pthread_rwlock_unlock(&array->rwlock);
        return -2; // Maximum elements reached
    }

    LTE_PHY_TX_RECORD *temp = realloc(array->records, sizeof(LTE_PHY_TX_RECORD) * new_size);
    if (!temp) {
        pthread_rwlock_unlock(&array->rwlock);
        return -3; // Memory allocation failed
    }

    array->records = temp;
    array->records[array->count] = record;
    array->count++;

    pthread_rwlock_unlock(&array->rwlock);
    return 0;
}

// Update existing element in the dynamic array
int updateElement(DynamicArray *array, size_t index, LTE_PHY_TX_RECORD new_record) {
    if (index >= array->count) {
        return -1; // Index out of bounds
    }

    pthread_rwlock_wrlock(&array->rwlock);
    if (new_record.TX_POWER_LEVEL > 63 || new_record.RF_CHANNEL_CONFIG > RF_CHANNEL_CONFIG_BAND_LIMIT) {
        pthread_rwlock_unlock(&array->rwlock);
        return -2; // Invalid power level or RF channel
    }

    array->records[index] = new_record;
    pthread_rwlock_unlock(&array->rwlock);
    return 0;
}

// Iterate over the list to check for specific conditions
void iterateArray(DynamicArray *array, void (*callback)(LTE_PHY_TX_RECORD *)) {
    pthread_rwlock_rdlock(&array->rwlock);

    for (size_t i = 0; i < array->count; ++i) {
        callback(&(array->records[i]));
    }

    pthread_rwlock_unlock(&array->rwlock);
}

// Create and populate list of NFAPI_CRC_INDICATION_PDU_T structures
void createCRCList(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size) {
    srand(time(NULL));
    *size = 10; // Example fixed size for demonstration
    *list = malloc(*size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (size_t i = 0; i < *size; ++i) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        (*list)[i].RNTI = rand() % 65536;
        (*list)[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        (*list)[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }
}

// Example callback function for iteration
void checkCondition(LTE_PHY_TX_RECORD *record) {
    if (record->RF_CHANNEL_CONFIG == 500) { // Example condition
        printf("Record with RF_CHANNEL_CONFIG 500 found\n");
    }
}

// Initialize cache
void initCache(Cache *cache, int size) {
    cache->cache_size = size;
    cache->RF_CHANNEL_CONFIG_cache = malloc(size * sizeof(int));
    cache->TX_POWER_LEVEL_cache = malloc(size * sizeof(uint8_t));
}

// Free cache resources
void freeCache(Cache *cache) {
    free(cache->RF_CHANNEL_CONFIG_cache);
    free(cache->TX_POWER_LEVEL_cache);
}

int main() {
    DynamicArray array;
    Cache cache;

    initDynamicArray(&array);
    initCache(&cache, 100);

    LTE_PHY_TX_RECORD record = {1, 30, 200};
    addElement(&array, record);

    iterateArray(&array, checkCondition);

    NFAPI_CRC_INDICATION_PDU_T *crcList;
    size_t crcSize;
    createCRCList(&crcList, &crcSize);

    for (size_t i = 0; i < crcSize; ++i) {
        printf("CRC List Element %zu: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRC_INDICATION_REL8_TAG=%u, CRCFLAG=%d\n",
               i, crcList[i].RX_UE_INFORMATION_TAG, crcList[i].RNTI,
               crcList[i].CRC_INDICATION_REL8_TAG, crcList[i].CRCFLAG);
    }

    freeDynamicArray(&array);
    freeCache(&cache);
    free(crcList);

    return 0;
}
