['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

#define BUFFER_SIZE 1024

void process_files(const char *directory, int overwrite) {
    DIR *dir = opendir(directory);
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            char filepath[PATH_MAX];
            snprintf(filepath, PATH_MAX, "%s/%s", directory, entry->d_name);

            struct stat st;
            if (stat(filepath, &st) != 0) continue;

            FILE *file = fopen(filepath, "rb");
            if (!file) continue;

            fseek(file, 0, SEEK_END);
            long size = ftell(file);
            rewind(file);

            char buffer[BUFFER_SIZE];
            int bytesRead;
            while ((bytesRead = fread(buffer, 1, BUFFER_SIZE, file)) > 0 && size > 0) {
                size -= bytesRead;
            }

            fclose(file);

            if (size < 0) continue;

            char hexSize[9];
            snprintf(hexSize, sizeof(hexSize), "%lx", st.st_size);
            strcat(hexSize, ".custom");

            char newFilename[PATH_MAX];
            snprintf(newFilename, PATH_MAX, "%s.%s", filepath, hexSize);

            if (overwrite || access(newFilename, F_OK) == -1) {
                rename(filepath, newFilename);
            }
        }
    }

    closedir(dir);
}
