#include <pthread.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>

#define MAX_BATCH_SIZE 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t TX_CRC_COUNT;
    uint32_t RX_CRC_COUNT;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t count;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *buffer;
    pthread_mutex_t mutex;
} DynamicBuffer;

DynamicBuffer* create_dynamic_buffer(size_t initial_capacity) {
    DynamicBuffer* db = malloc(sizeof(DynamicBuffer));
    if (!db) return NULL;

    db->count = 0;
    db->capacity = initial_capacity;
    db->buffer = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&db->mutex, NULL);

    return db;
}

void resize_dynamic_buffer(DynamicBuffer* db, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_buffer = realloc(db->buffer, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_buffer) {
        db->buffer = new_buffer;
        db->capacity = new_capacity;
    }
}

void add_pdu_to_buffer(DynamicBuffer* db, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&db->mutex);

    if (db->count == db->capacity) {
        resize_dynamic_buffer(db, db->capacity * 2);
    }

    db->buffer[db->count++] = pdu;
    pthread_mutex_unlock(&db->mutex);
}

void compute_md5_hash(const char* input, unsigned char hash_output[MD5_DIGEST_LENGTH]) {
    MD5((unsigned char*)input, strlen(input), hash_output);
}

void fill_random_crc_flag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    static const int crc_flags[] = {0x01, 0x02}; // Example CRC flags
    pdu->crcIndicationRel8Tag.crcFlag = crc_flags[rand() % (sizeof(crc_flags) / sizeof(crc_flags[0]))];
}

void process_batch(DynamicBuffer* db, size_t batch_size) {
    pthread_mutex_lock(&db->mutex);

    for (size_t i = 0; i < batch_size && db->count > 0; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = db->buffer[--db->count];
        fill_random_crc_flag(&pdu);

        char* example_string = "example"; // Example string for hashing
        unsigned char md5_hash[MD5_DIGEST_LENGTH];
        compute_md5_hash(example_string, md5_hash);

        memcpy(pdu.crcIndicationRel8Tag.md5Hash, md5_hash, MD5_DIGEST_LENGTH);
    }

    pthread_mutex_unlock(&db->mutex);
}

void serialize_buffer(const DynamicBuffer* db, uint8_t** output, size_t* output_size) {
    *output = malloc(db->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*output) return;

    memcpy(*output, db->buffer, db->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    *output_size = db->count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
}

void deserialize_buffer(DynamicBuffer* db, const uint8_t* input, size_t input_size) {
    pthread_mutex_lock(&db->mutex);

    size_t pdu_count = input_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (pdu_count > db->capacity) resize_dynamic_buffer(db, pdu_count);

    memcpy(db->buffer, input, input_size);
    db->count = pdu_count;

    pthread_mutex_unlock(&db->mutex);
}

void cleanup_dynamic_buffer(DynamicBuffer* db) {
    free(db->buffer);
    pthread_mutex_destroy(&db->mutex);
    free(db);
}

// Stress-test function to simulate high-volume concurrent access
void* stress_test(void* arg) {
    DynamicBuffer* db = (DynamicBuffer*)arg;

    for (int i = 0; i < 10000; ++i) { // Example high volume of data processing
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = rand(), .RNTI = rand() };
        add_pdu_to_buffer(db, pdu);
    }

    return NULL;
}

