#include <stdint.h>
#include <time.h>
#include <openssl/md5.h>

// Define structure for NFAPI_CRC_INDICATION_PDU_T with necessary fields
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_linked_list(size_t num_elements, const char* source_string, unsigned int seed) {
    if (num_elements <= 0 || !source_string) return NULL;

    srand(seed);
    Node* head = NULL;
    Node** current = &head;

    // Function to compute MD5 hash
    auto compute_md5_hash = [](const char* str, unsigned char* md5sum) {
        MD5((unsigned char*)str, strlen(str), md5sum);
    };

    for (size_t i = 0; i < num_elements; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            // Free previously allocated nodes in case of failure
            while (*current != NULL) {
                Node* temp = *current;
                *current = (*current)->next;
                free(temp);
            }
            return NULL; // Memory allocation error
        }

        new_node->data.RX_UE_INFORMATION_TAG = rand() % 0xFFFF;
        new_node->data.RNTI = rand() % 0xFFFF;
        new_node->data.CRCFLAG = (rand() & 1); // Randomly set to 0 or 1

        compute_md5_hash(source_string, new_node->data.md5_hash);

        new_node->next = NULL;
        *current = new_node;
        current = &new_node->next;
    }

    return head;
}

// Example of freeing the linked list
void free_linked_list(Node* head) {
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}
