} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
    uint8_t crc_flags[MAX_ELEMENTS];
} CRCLinkedList;

uint8_t generate_unique_crc_flag(uint8_t* used_flags, size_t max_flags) {
    uint8_t crc_flag;
    srand((unsigned int)time(NULL));
    do {
        crc_flag = rand() % 256; // Assume CRCFLAG is an 8-bit value
    } while (used_flags[crc_flag] == 1);
    return crc_flag;
}

CRCLinkedList* create_crc_list() {
    CRCLinkedList* list = (CRCLinkedList*)malloc(sizeof(CRCLinkedList));
    if (!list) {
        perror("Failed to allocate memory for CRCLinkedList");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    memset(list->crc_flags, 0, sizeof(list->crc_flags));
    return list;
}

void insert_crc_indication(CRCLinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (pthread_mutex_lock(&list->lock)) {
        perror("Failed to lock mutex");
        exit(EXIT_FAILURE);
    }

    if (list->size >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Maximum list size reached. Cannot insert new element.\n");
        return;
    }

    // Generate a unique CRCFLAG
    uint8_t crc_flag = generate_unique_crc_flag(list->crc_flags, sizeof(list->crc_flags));
    pdu.CRC_INDICATION_REL8_TAG.crcflag = crc_flag;
    list->crc_flags[crc_flag] = 1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        pthread_mutex_unlock(&list->lock);
        exit(EXIT_FAILURE);
    }
    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
}

void flush_crc_list(CRCLinkedList* list) {
    if (pthread_mutex_lock(&list->lock)) {
        perror("Failed to lock mutex");
        exit(EXIT_FAILURE);
    }

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->size = 0;
    memset(list->crc_flags, 0, sizeof(list->crc_flags));

    pthread_mutex_unlock(&list->lock);
}

void destroy_crc_list(CRCLinkedList* list) {
    flush_crc_list(list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
