    pthread_mutex_t mac_id_lock; // Mutex for thread-safe access to MAC ID pool
} MacIdManager;

// Function to initialize an array of NFAPI_UL_CCCH_INDICATION_PDU_T structures
NFAPI_UL_CCCH_INDICATION_PDU_T* init_ul_ccch_indication_pdu_array(size_t num_indications, 
                                                                 const int *ul_ccch_tags, 
                                                                 const int *ue_indices,
                                                                 MacIdManager *mac_id_manager) {
    // Allocate memory for the array of structures
    NFAPI_UL_CCCH_INDICATION_PDU_T* indications = (NFAPI_UL_CCCH_INDICATION_PDU_T*)
        malloc(num_indications * sizeof(NFAPI_UL_CCCH_INDICATION_PDU_T));

    if (!indications) {
        // Handle memory allocation failure
        return NULL;
    }

    // Iterate through each indication to initialize it
    for (size_t i = 0; i < num_indications; ++i) {
        indications[i].UL_CCCH_INDICATION_TAG = ul_ccch_tags[i];
        indications[i].UE_INDEX = ue_indices[i];

        pthread_mutex_lock(&mac_id_manager->mac_id_lock);

        if (mac_id_manager->mac_id_count == 0) {
            // Handle case where MAC ID pool is depleted
            free(indications);
            pthread_mutex_unlock(&mac_id_manager->mac_id_lock);
            return NULL;
        }

        // Allocate a unique MAC entity ID from the predefined pool
        indications[i].MAC_ENTITY_ID = mac_id_manager->mac_id_pool[--mac_id_manager->mac_id_count];

        pthread_mutex_unlock(&mac_id_manager->mac_id_lock);
    }

    return indications;
}

