    manager->crc_array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(crc_count, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!manager->ul_ccch_array || !manager->crc_array) {
        free(manager->ul_ccch_array);
        free(manager->crc_array);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
        return NULL;
    }

    manager->ul_ccch_count = ul_ccch_count;
    manager->crc_count = crc_count;

