    for (size_t i = 0; i < ul_ccch_count; ++i) {
        pthread_mutex_lock(&manager->lock);
        manager->ul_ccch_array[i].tag = UL_CCCH_INDICATION_TAG;
        manager->ul_ccch_array[i].ue_index = rand() % 10000; // Random UE index
        manager->ul_ccch_array[i].mac_entity_id = get_mac_entity_id();
        if (manager->ul_ccch_array[i].mac_entity_id == -1) {
