            break;
        }
        pthread_mutex_unlock(&manager->lock);
    }

    // Initialize CRC_INDICATION_PDU_T
    for (size_t i = 0; i < crc_count; ++i) {
        pthread_mutex_lock(&manager->lock);
        manager->crc_array[i].tag = RX_UE_INFORMATION_TAG;
        manager->crc_array[i].rnti = rand() % 1000000000ULL; // Random RNTI
        manager->crc_array[i].crc_indication_rel8_tag = rand(); // Random CRC tag
        pthread_mutex_unlock(&manager->lock);
    }

    return manager;
}

void free_indication_manager(IndicationManager* manager) {
