void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array);
int generate_random_crcflag();

// Implementation of functions

NFAPI_CRC_INDICATION_PDU_T* initialize_crc_pdu_array(size_t num_elements, int (*data_source)(uint32_t*, uint16_t*)) {
    if (num_elements > MAX_ELEMENTS) {
        fprintf(stderr, "Requested number of elements exceeds the maximum allowed limit.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for CRC indication PDU array.\n");
        return NULL;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        uint32_t rx_ue_info_tag;
        uint16_t rnti;

        if (!data_source(&rx_ue_info_tag, &rnti)) {
            fprintf(stderr, "Failed to retrieve data source information for element %zu.\n", i);
            free_crc_pdu_array(array); // Clean up on failure
            return NULL;
