        array[i].RX_UE_INFORMATION_TAG = rx_ue_info_tag;
        array[i].RNTI = rnti;
        array[i].CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 256); // Example tag value
        array[i].CRCFLAG = generate_random_crcflag();
    }

    return array;
}

void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}

int generate_random_crcflag() {
