void adjustPoolSize(ContextPool *pool, size_t new_capacity) {
    pthread_mutex_lock(&pool->lock);
    PduSessionContext *new_contexts = realloc(pool->contexts, new_capacity * sizeof(PduSessionContext));
    if (new_contexts) {
        pool->contexts = new_contexts;
        pool->capacity = new_capacity;
    } else {
        log_status("Failed to adjust context pool size");
    }
    pthread_mutex_unlock(&pool->lock);
}

void freePduSessionContextPool(ContextPool *pool) {
