        exit(EXIT_FAILURE);
    }
}

// Resize the dynamic array when necessary
void resizeArray(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);

    size_t newCapacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *newData = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newData == NULL) {
        handleError("Failed to reallocate memory for the dynamic array");
        pthread_mutex_unlock(&array->lock);
        exit(EXIT_FAILURE);
    }
    array->data = newData;
    array->capacity = newCapacity;

    pthread_mutex_unlock(&array->lock);
}

// Add an element to the dynamic array
void addElement(DynamicArray *array, const NFAPI_CRC_INDICATION_PDU_T *element) {
    if (!verifyElement(element)) {
        handleError("Invalid element data");
        return;
    }

    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        resizeArray(array);
    }
    memcpy(&array->data[array->size], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size++;

    pthread_mutex_unlock(&array->lock);
}

// Free the dynamic array
void freeDynamicArray(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);

    if (array->data != NULL) {
        free(array->data);
        array->data = NULL;
    }
    array->size = 0;
    array->capacity = 0;

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

// Example usage
int main() {
    DynamicArray array;
    initDynamicArray(&array);

    // Example data for testing
    NFAPI_CRC_INDICATION_PDU_T exampleElement = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 1234, .CRC_INDICATION_REL8_TAG = {.CRCFLAG = 0} };

    addElement(&array, &exampleElement);

    // Add more elements as needed...

    freeDynamicArray(&array);

    return 0;
}
