} NR_PDU_HEADER_RRC_PDCP_SN;

typedef struct NR_PDU_HEADER_T_ {
    NR_PDU_HEADER_RRC_CUCI cuci;
    NR_PDU_HEADER_RRC_CCCH ccch;
    NR_PDU_HEADER_RRC_PDCP_SN pdcp_sn;
} NR_PDU_HEADER_T;

typedef struct NFAPI_CRC_INDICATION_PDU_TAG_RX_UE_INFORMATION_TAG_ {
    int tag;
} NFAPI_CRC_INDICATION_PDU_TAG_RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned long rnti;
} RNTI;

typedef struct {
    bool crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T_ {
    NFAPI_CRC_INDICATION_PDU_TAG_RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T_ *next;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_PDUS 1024

typedef struct {
    NR_PDU_HEADER_T *pdus[MAX_PDUS];
    size_t count;
    pthread_mutex_t mutex;
    bool initialized;
} DynamicArray;

void init_dynamic_array(DynamicArray *array) {
    array->count = 0;
    array->initialized = false;
    pthread_mutex_init(&array->mutex, NULL);
}

bool add_pdu_to_array(DynamicArray *array, NR_PDU_HEADER_T pdu) {
    if (array->count >= MAX_PDUS || !array->initialized) return false;

    for (size_t i = 0; i < array->count; ++i) {
        if (array->pdus[i]->pdp_sn.tag == pdu.pdp_sn.tag && array->pdus[i]->pdp_sn.valid_sequence_number) {
            // Handle duplicate sequence number
            return false;
        }
    }

    pthread_mutex_lock(&array->mutex);
    array->pdus[array->count++] = &pdu;
    pthread_mutex_unlock(&array->mutex);

    return true;
}

void reset_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; ++i) {
        free(array->pdus[i]);
    }
    array->count = 0;
    pthread_mutex_unlock(&array->mutex);
}

void destroy_dynamic_array(DynamicArray *array) {
    reset_dynamic_array(array);
    pthread_mutex_destroy(&array->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_pdu(NFAPI_CRC_INDICATION_PDU_TAG_RX_UE_INFORMATION_TAG rx_tag,
                                           RNTI rnti, CRC_INDICATION_REL8_TAG crc_tag) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->rx_ue_information_tag = rx_tag;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag = crc_tag;
    pdu->next = NULL;

    return pdu;
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t mutex;
} CRCList;

void init_crc_list(CRCList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

bool add_to_crc_list(CRCList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!pdu) return false;

    pthread_mutex_lock(&list->mutex);

    pdu->next = list->head;
    list->head = pdu;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

void free_crc_list(CRCList *list) {
    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->mutex);
}

void destroy_crc_list(CRCList *list) {
    free_crc_list(list);
    pthread_mutex_destroy(&list->mutex);
}

// Monitoring mechanism
typedef struct {
    size_t memory_usage;
    double processing_latency; // In milliseconds
    int error_count;
} MonitorData;

MonitorData monitor = {0, 0.0, 0};

void update_monitor(size_t used_memory, double latency) {
    pthread_mutex_lock(&monitor.mutex);
    monitor.memory_usage += used_memory;
    monitor.processing_latency += latency;
    pthread_mutex_unlock(&monitor.mutex);
}

// Example usage
int main() {
    DynamicArray pdu_array;
    CRCList crc_list;

    init_dynamic_array(&pdu_array);
    init_crc_list(&crc_list);

    // Create and add PDUs to the array and list...

    reset_dynamic_array(&pdu_array);
    destroy_dynamic_array(&pdu_array);
    free_crc_list(&crc_list);
    destroy_crc_list(&crc_list);

    return 0;
}
