typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG:1;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct UE_RECORD {
    time_t timestamp;
    int sequence_number;
    // Add other necessary fields
} UE_RECORD;

// Function prototypes
void log_event(const char *message);
int process_log_file(const char *filename, int *last_sequence_number);
NFAPI_CRC_INDICATION_PDU_T* generate_nfa_pi_list(int count, size_t *size);

// Logger function for integration with logging framework
void log_event(const char *message) {
    // Integration with existing logging framework
    printf("Log: %s\n", message);  // Placeholder for actual logging mechanism
}

// Function to process the UE log file and extract last sequence number
int process_log_file(const char *filename, int *last_sequence_number) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open log file");
        return -1;
    }

    UE_RECORD record;
    size_t num_records = 0;
    while (fscanf(file, "%ld %d", &record.timestamp, &record.sequence_number) == 2) {
        // Store records in a dynamically allocated array
        UE_RECORD *records = realloc(NULL, sizeof(UE_RECORD) * (num_records + 1));
        if (!records) {
            perror("Memory allocation failed");
            fclose(file);
            return -1;
        }

        records[num_records] = record;
        num_records++;
    }

    if (ferror(file)) {
        perror("Error reading log file");
        fclose(file);
        return -1;
    }
    fclose(file);

    // Sort records by timestamp
    qsort(records, num_records, sizeof(UE_RECORD), [](const void *a, const void *b) -> int {
        UE_RECORD *recordA = (UE_RECORD *)a;
        UE_RECORD *recordB = (UE_RECORD *)b;
        return recordA->timestamp > recordB->timestamp;  // Descending order
    });

    if (num_records > 0) {
        *last_sequence_number = records[num_records - 1].sequence_number;
    }

    free(records);
    return 0;
}

// Function to dynamically generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generate_nfa_pi_list(int count, size_t *size) {
    log_event("Generating NF-API CRC indication PDU list");

    // Allocate memory for the structures array
    NFAPI_CRC_INDICATION_PDU_T *nfa_pi_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    if (!nfa_pi_list) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < count; ++i) {
        nfa_pi_list[i].RX_UE_INFORMATION_TAG = rand();
        nfa_pi_list[i].RNTI = rand();
        nfa_pi_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;
    }

    *size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * count;

    return nfa_pi_list;
}

// Example of using the functions
int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int last_sequence_number = -1;
    if (process_log_file(argv[1], &last_sequence_number) == 0) {
        printf("Last sequence number from log: %d\n", last_sequence_number);
    } else {
        fprintf(stderr, "Failed to process the log file.\n");
        return EXIT_FAILURE;
    }

