        log_error("Failed to fetch configuration");
        return -2; // Error code for fetching failure
    }

    new_settings.channel_bandwidth = bandwidth_config; // Example assignment

    // Cache the settings
    if (cache_count < CACHE_SIZE) {
        phy_cache[cache_count++] = (PhyCacheEntry){.frequency_band = frequency_band, .settings = new_settings, .last_updated = get_current_timestamp()};
    } else {
        log_error("Cache overflow");
        return -3; // Error code for cache issues
    }

