typedef struct USER_SESSION_INFO_T {
    char SESSION_ID[64];
    char CLIENT_IP[16]; // IPv4 format
    int PORT;
    int CONNECTION_STATUS; // e.g., 1 for active, 0 for inactive
} USER_SESSION_INFO_T;

typedef struct ListNode {
    USER_SESSION_INFO_T session_info;
    struct ListNode *next;
} ListNode;

ListNode *head = NULL;

// Function prototypes
void add_session(const char *session_id, const char *client_ip, int port, int status);
void cleanup_inactive_sessions();
int validate_ip_address(const char *ip);

void manage_sessions() {
    while (1) { // Assuming this is a continuous process in high-load server

        char ip[16];
        int port;

        if (!external_monitoring_system_get_client_info(ip, &port)) {
            log_warning("External system timeout. Using default IP and port.");
            snprintf(ip, sizeof(ip), "%s", DEFAULT_IP);
            port = DEFAULT_PORT;
        } else {
            if (!validate_ip_address(ip)) {
                log_warning("Invalid IP address received: %s. Using default IP.", ip);
                snprintf(ip, sizeof(ip), "%s", DEFAULT_IP);
                port = DEFAULT_PORT;
            }
        }

        char session_id[64];
        // Generate a unique SESSION_ID here
        snprintf(session_id, sizeof(session_id), "session_%ld", time(NULL));

        add_session(session_id, ip, port, 1);

        cleanup_inactive_sessions();

        // Simulate processing delay or waiting for the next update
        sleep(1);
    }
}

void add_session(const char *session_id, const char *client_ip, int port, int status) {
    ListNode *new_node = (ListNode *)malloc(sizeof(ListNode));
    if (!new_node) {
        log_error("Memory allocation failed for new session.");
        return;
    }

    snprintf(new_node->session_info.SESSION_ID, sizeof(new_node->session_info.SESSION_ID), "%s", session_id);
    snprintf(new_node->session_info.CLIENT_IP, sizeof(new_node->session_info.CLIENT_IP), "%s", client_ip);
    new_node->session_info.PORT = port;
    new_node->session_info.CONNECTION_STATUS = status;
    new_node->next = head;
    head = new_node;
}

void cleanup_inactive_sessions() {
    ListNode **current = &head;
    while (*current) {
        if ((*current)->session_info.CONNECTION_STATUS == 0) { // Assuming inactive means status is 0
            ListNode *to_delete = *current;
            *current = to_delete->next;
            free(to_delete);
        } else {
            current = &(*current)->next;
        }
    }
}

int validate_ip_address(const char *ip) {
    int parts[4];
    return sscanf(ip, "%d.%d.%d.%d", &parts[0], &parts[1], &parts[2], &parts[3]) == 4 &&
           parts[0] >= 0 && parts[0] <= 255 &&
           parts[1] >= 0 && parts[1] <= 255 &&
           parts[2] >= 0 && parts[2] <= 255 &&
           parts[3] >= 0 && parts[3] <= 255;
}

// Example logging functions
void log_warning(const char *message, ...) {
    // Implement logging of warning messages here
    va_list args;
