#include <pthread.h>
#include <time.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_node(Node* node) {
    free(node);
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        destroy_node(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void* thread_function(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    srand(time(NULL) ^ pthread_self());

    for (int i = 0; i < 1000; ++i) { // Simulate large-scale updates
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand() % 1000;
        data.RNTI = rand() % 10000;
        data.CRC_INDICATION_REL8_TAG = rand() % 500;
        data.CRCFLAG = rand() % 2;

        if (add_to_list(list, data) != 0) {
            fprintf(stderr, "Failed to add node: Memory allocation error\n");
            break;
        }
    }

    return NULL;
}

int main() {
    LinkedList* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create linked list.\n");
        return EXIT_FAILURE;
    }

    const int num_threads = 10;
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, list) != 0) {
            fprintf(stderr, "Failed to create thread.\n");
            destroy_list(list);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup
    destroy_list(list);

    return EXIT_SUCCESS;
}
