        pdu.RNTI = rand() % 1000000;

        // Randomly set CRCFLAG to 0 or 1
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        if (validate_crc(&pdu)) {
            Node* new_node = create_node(&pdu);
            new_node->next = head;
            head = new_node;
        }
    }

    // Sort the list based on RNTI
    sort_list(&head);

    return head;
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) exit(EXIT_FAILURE); // Handle memory allocation failure

    node->data.RX_UE_INFORMATION_TAG = pdu->RX_UE_INFORMATION_TAG;
    node->data.RNTI = pdu->RNTI;
    node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = pdu->CRC_INDICATION_REL8_TAG.CRCFLAG;

    return node;
}

void free_list(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int validate_crc(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Example validation logic for CRCFLAG
    return (pdu->CRC_INDICATION_REL8_TAG.CRCFLAG == 0 || 
            pdu->CRC_INDICATION_REL8_TAG.CRCFLAG == 1);
}

void sort_list(Node** head) {
    if (!head || !*head) return;

    Node *sorted = NULL, *current = *head;

    while (current != NULL) {
        Node* next = current->next;

        // Insert node into sorted linked list
        if (!sorted || sorted->data.RNTI >= current->data.RNTI) {
            current->next = sorted;
            sorted = current;
        } else {
            Node* temp = sorted;
            while (temp->next != NULL && temp->next->data.RNTI < current->data.RNTI) {
                temp = temp->next;
            }
            current->next = temp->next;
            temp->next = current;
        }

        current = next;
    }

    *head = sorted;
}

void process_batch(Node** head, int batch_size) {
    Node* current = *head;
    while (batch_size-- > 0 && current != NULL) {
        // Process the current node
        printf("Processing RNTI: %u\n", current->data.RNTI);

        // Move to next node in the list
        Node* temp = current;
        current = current->next;

        // Free the processed node
        free(temp);
    }

    *head = current; // Update head if the first element was processed and freed
}

// Example usage function
int main() {
    int num_elements = 10000;

    Node* list_head = create_dynamic_linked_list(num_elements);

    // Process data in batches of up to 1,000 elements at a time
    while (list_head != NULL) {
        process_batch(&list_head, 1000);
    }

    free_list(&list_head); // Ensure all memory is freed

    return 0;
}
```

