    struct CacheNode* next;
} CacheNode;

CacheNode* cacheHead = NULL;

// Function to add an entry to the cache
void addToCache(int identifier, const char *details) {
    CacheNode* newNode = (CacheNode*)malloc(sizeof(CacheNode));
    if (!newNode) return; // Handle malloc failure gracefully

    newNode->eventIdentifier = identifier;
    newNode->eventDetails = strdup(details);
    newNode->next = cacheHead;
    cacheHead = newNode;
}

// Function to retrieve from cache
char* getFromCache(int identifier) {
    CacheNode *current = cacheHead;
    while (current != NULL) {
        if (current->eventIdentifier == identifier) {
            return current->eventDetails;
        }
        current = current->next;
    }
    return NULL; // Not found in cache
}

// Function to clean up the cache
void cleanupCache() {
    CacheNode *current = cacheHead, *nextNode;
    while (current != NULL) {
        nextNode = current->next;
        free(current->eventDetails);
        free(current);
        current = nextNode;
    }
    cacheHead = NULL;
}

// Function to generate unique identifiers
int generateUniqueIdentifier(int baseId) {
    static int idCounter = 0;
    int uniqueId = baseId + idCounter++;
    return uniqueId;
}

NetworkEventStruct* initializeNetworkEvents(size_t numEvents, size_t bytesToCopy, char** bufferOutput) {
    NetworkEventStruct *events = (NetworkEventStruct*)malloc(numEvents * sizeof(NetworkEventStruct));
    if (!events) {
        // Handle malloc failure gracefully
        *bufferOutput = NULL;
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed random number generator

    for (size_t i = 0; i < numEvents; ++i) {
        events[i].eventIdentifier = generateUniqueIdentifier(rand() % 100);

        // Ensure timestamp is unique
        time(&events[i].timestamp);
        while (difftime(time(NULL), events[i].timestamp) < 1.0) {
            time(&events[i].timestamp);
        }

        const char *detailsTemplate = eventTemplates[rand() % (sizeof(eventTemplates) / sizeof(char*))];

        // Check cache first
        char* cachedDetails = getFromCache(events[i].eventIdentifier);
        if (!cachedDetails) {
            // If not in cache, generate new details
            size_t detailLength = strlen(detailsTemplate) + 20;
            events[i].eventDetails = (char*)malloc(detailLength);
            snprintf(events[i].eventDetails, detailLength, "%s [Generated at %ld]", detailsTemplate, events[i].timestamp);

            // Add to cache
            addToCache(events[i].eventIdentifier, events[i].eventDetails);
        } else {
            events[i].eventDetails = strdup(cachedDetails);  // Copy from cache
        }
    }

    // Allocate buffer and copy specified number of bytes
    *bufferOutput = (char*)malloc(bytesToCopy);
    if (*bufferOutput) {
        size_t totalBytesCopied = 0;
        for (size_t i = 0; i < numEvents && totalBytesCopied < bytesToCopy; ++i) {
            size_t eventDetailsLength = strlen(events[i].eventDetails) + 1;
            size_t bytesToCopyFromEvent = eventDetailsLength > (bytesToCopy - totalBytesCopied) ? 
                                          (bytesToCopy - totalBytesCopied) : eventDetailsLength;

            memcpy(*bufferOutput + totalBytesCopied, events[i].eventDetails, bytesToCopyFromEvent);
            totalBytesCopied += bytesToCopyFromEvent;
        }
    }

    // Cleanup cache after use
    cleanupCache();

    return events;
}

int main() {
    size_t numEvents = 10;
    size_t bytesToCopy = 512;
    char *bufferOutput;

    NetworkEventStruct* events = initializeNetworkEvents(numEvents, bytesToCopy, &bufferOutput);

    if (events) {
        printf("Buffered Data:\n%s\n", bufferOutput);

        for(size_t i = 0; i < numEvents; ++i){
            free(events[i].eventDetails);
        }
        free(events);
    }

    if(bufferOutput) {
        free(bufferOutput);
    }

    return 0;
}
