typedef struct {
    int eventIdentifier;
    time_t timestamp;
    char *eventDetails;
} NetworkEventStruct;

#define MAX_THREADS 10
#define TEMPLATE_SIZE 100
#define EVENT_WINDOW_MS 60000

static pthread_mutex_t eventMutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t eventCondVar = PTHREAD_COND_INITIALIZER;
static int globalEventCounter = 0;
static const char *eventTemplates[] = {
    "Network connection established.",
    "Data packet received.",
    "Connection timeout.",
    "Error in data transmission."
};

void freeNetworkEvents(NetworkEventStruct **events, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (events[i] && events[i]->eventDetails) {
            free(events[i]->eventDetails);
        }
        free(events[i]);
    }
    free(events);
}

char *generateEventDetail(int templateIndex, time_t timestamp) {
    char *detail = malloc(TEMPLATE_SIZE + 50);
    if (!detail) return NULL;

    snprintf(detail, TEMPLATE_SIZE + 50,
             "%s at %ld - Unique ID: %d",
             eventTemplates[templateIndex % (sizeof(eventTemplates) / sizeof(char*))],
             timestamp, rand());

    return detail;
}

NetworkEventStruct **initializeNetworkEvents(size_t *eventCount, int threadId) {
    size_t count = 0;
    NetworkEventStruct **events = NULL;

    pthread_mutex_lock(&eventMutex);

    while (1) {
        if (count % MAX_THREADS == threadId) {
            time_t currentTimestamp = time(NULL);
            NetworkEventStruct *newEvent = malloc(sizeof(NetworkEventStruct));
            if (!newEvent) break;

            newEvent->eventIdentifier = globalEventCounter++;
            newEvent->timestamp = currentTimestamp;
            int templateIndex = rand() % (sizeof(eventTemplates) / sizeof(char*));
            newEvent->eventDetails = generateEventDetail(templateIndex, currentTimestamp);
            if (!newEvent->eventDetails) {
                free(newEvent);
                break;
            }

            events = realloc(events, (count + 1) * sizeof(NetworkEventStruct *));
            if (!events) {
                freeNetworkEvents(events, count);
                pthread_mutex_unlock(&eventMutex);
                return NULL;
            }

            events[count++] = newEvent;
        }

        // Simulate waiting for more events
        if (pthread_cond_wait(&eventCondVar, &eventMutex)) break;

        // Check time window constraint
        if (difftime(time(NULL), currentTimestamp) > EVENT_WINDOW_MS / 1000.0)
            break;
    }

    pthread_mutex_unlock(&eventMutex);

    *eventCount = count;
    return events;
}

void eventGeneratorThread(void *arg) {
    int threadId = *(int *)arg;
    size_t eventCount;
    NetworkEventStruct **events = initializeNetworkEvents(&eventCount, threadId);

    if (events) {
        for (size_t i = 0; i < eventCount; ++i) {
            printf("Thread %d: Event ID %d, Timestamp %ld, Details: %s\n",
                   threadId, events[i]->eventIdentifier, events[i]->timestamp, events[i]->eventDetails);
        }

        freeNetworkEvents(events, eventCount);
    } else {
        fprintf(stderr, "Failed to generate network events for thread %d\n", threadId);
    }
}

int main() {
    pthread_t threads[MAX_THREADS];
    int threadIds[MAX_THREADS];

    srand((unsigned) time(NULL));

    for (int i = 0; i < MAX_THREADS; ++i) {
        threadIds[i] = i;
        if (pthread_create(&threads[i], NULL, (void *(*)(void *))eventGeneratorThread, &threadIds[i])) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
