#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PDU_COUNT 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void log_error(const char *message) {
    // Centralized logging implementation
    fprintf(stderr, "%s\n", message);
}

int allocate_memory(void **ptr, size_t size) {
    for (int i = 0; i < 3; ++i) { // Retry mechanism with exponential backoff
        *ptr = malloc(size);
        if (*ptr != NULL)
            return 1;

        log_error("Memory allocation failed. Retrying...");
        usleep((1 << i) * 100000); // Exponential backoff in microseconds
    }
    return 0;
}

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list)
        return NULL;

    allocate_memory(&list->head, sizeof(Node));
    if (!list->head) {
        free(list);
        return NULL;
    }

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(LinkedList* list) {
    Node *current = list->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_pdu(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!allocate_memory((void**)&pdu, sizeof(pdu))) {
        log_error("Failed to allocate memory for PDU data.");
        return 0;
    }

    pthread_mutex_lock(&list->lock);

    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        free(pdu);
        return 0;
    }

    new_node->data = pdu;
    new_node->next = NULL;

    if (list->head == NULL || list->head == NULL) {
        list->head = new_node;
    } else {
        Node *current = list->head;
        while (current->next != NULL && current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return 1;
}

int serialize_list(const LinkedList* list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file)
        return 0;

    Node *current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    return 1;
}

int deserialize_list(LinkedList* list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file)
        return 0;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_pdu(list, pdu);
    }

    fclose(file);
    return 1;
}

void generate_random_crcflag(unsigned char *crcflag) {
    srand(time(NULL)); // Seed with current time for randomness
    *crcflag = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

int main() {
    LinkedList* list = create_list();
    if (!list) {
        log_error("Failed to create linked list.");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    for (int i = 0; i < MAX_PDU_COUNT; ++i) {
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand();
        pdu.CRC_INDICATION_REL8_TAG = rand();
        generate_random_crcflag(&pdu.CRCFLAG);

        if (!add_pdu(list, pdu)) {
            log_error("Failed to add PDU to list.");
        }
    }

    serialize_list(list, "nfa_data.bin");

    LinkedList* new_list = create_list();
    deserialize_list(new_list, "nfa_data.bin");

    destroy_list(list);
    destroy_list(new_list);

    return 0;
}
