        current = next;
    }
    *head = NULL;
}

// Insert a new node with unique CRCFLAG
int insert_unique_crcflag(NFAPI_CRC_INDICATION_PDU_T** head, int rnti, uint32_t crc_flag) {
    pthread_mutex_lock(&list_mutex);

    NFAPI_CRC_INDICATION_PDU_T* current = *head;

    // Check for duplicate CRCFLAG or RNTI
    while (current != NULL) {
        if (current->crc_indication.CRCFLAG == crc_flag || current->ue_info.RNTI == rnti) {
            pthread_mutex_unlock(&list_mutex);
            return 0; // Duplicate found, do not insert
        }
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(rnti, crc_flag);
    if (!new_node) {
        pthread_mutex_unlock(&list_mutex);
        return -1; // Allocation failed
    }

    // Insert at the beginning for O(1) complexity
    new_node->next = *head;
    *head = new_node;

    pthread_mutex_unlock(&list_mutex);
    return 1; // Success
}

// Example usage of the linked list management
void manage_list() {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;

    // Simulate adding nodes with unique CRCFLAG values
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        uint32_t crc_flag = rand() % 1000000; // Example random generation
        int rnti = rand() % 500; // Example RNTI value

        if (insert_unique_crcflag(&head, rnti, crc_flag) != 1) {
            fprintf(stderr, "Failed to insert or duplicate found for RNTI: %d, CRCFLAG: %u\n", rnti, crc_flag);
        }
    }

    // Free the list when done
    free_list(&head);
}

int main() {
    manage_list();
    return 0;
}
```

### Key Considerations:
- **Thread Safety**: The use of `pthread_mutex_t` ensures that concurrent access to the linked list is managed safely.
- **Unique CRCFLAG and RNTI Handling**: Before inserting a new node, the function checks for existing nodes with the same `CRCFLAG` or `RNTI`.
- **Memory Management**: Nodes are dynamically allocated on the heap, and memory is freed appropriately to avoid leaks.
- **Error Handling**: The code handles allocation failures gracefully by returning an error status.
- **Efficiency**: Insertions are performed at the head of the list for O(1) complexity.

This implementation addresses the requirements for managing a linked list with unique constraints in a multi-threaded environment.']

