#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

// Define MAC address size
#define MAC_ADDRESS_SIZE 6

typedef struct {
    uint8_t mac[MAC_ADDRESS_SIZE];
} MAC_HEADER;

typedef struct {
    uint8_t *data;
    size_t length;
} MAC_PAYLOAD;

typedef struct {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
    time_t timestamp;
} MAC_PDU_T;

// Define a structure for dynamic array management
typedef struct {
    MAC_PDU_T **pdus;
    size_t capacity;
    size_t count;
} DynamicArray;

// Function prototypes
DynamicArray* create_dynamic_array(size_t initial_capacity);
void free_dynamic_array(DynamicArray *array);
int add_mac_pdu(DynamicArray *array, MAC_PDU_T *pdu, uint8_t default_mac[MAC_ADDRESS_SIZE]);
int is_duplicate(const DynamicArray *array, const MAC_HEADER *header, time_t timestamp);
void log_message(const char *message);

// Implementations
DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->pdus = (MAC_PDU_T **)malloc(initial_capacity * sizeof(MAC_PDU_T *));
    if (!array->pdus) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;

    log_message("Dynamic array created.");
    return array;
}

void free_dynamic_array(DynamicArray *array) {
    if (!array) return;

    for (size_t i = 0; i < array->count; ++i) {
        free(array->pdus[i]->payload.data);
        free(array->pdus[i]);
    }

    free(array->pdus);
    free(array);

    log_message("Dynamic array freed.");
}

int add_mac_pdu(DynamicArray *array, MAC_PDU_T *pdu, uint8_t default_mac[MAC_ADDRESS_SIZE]) {
    if (!array || !pdu) return -1;

    // Validate MAC address
    int is_valid = 0;
    for (size_t i = 0; i < MAC_ADDRESS_SIZE; ++i) {
        if (pdu->header.mac[i] == 0xFF) { // Assume FF indicates unknown/invalid
            memcpy(pdu->header.mac, default_mac, MAC_ADDRESS_SIZE);
            is_valid = 1;
            log_message("Default MAC address assigned.");
            break;
        }
    }

    if (!is_valid) {
        log_message("Invalid MAC address detected.");
        return -2; // Invalid MAC address
    }

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        MAC_PDU_T **new_pdus = (MAC_PDU_T **)realloc(array->pdus, new_capacity * sizeof(MAC_PDU_T *));
        if (!new_pdus) {
            log_message("Memory allocation failed.");
            return -3; // Memory allocation failure
        }

        array->pdus = new_pdus;
        array->capacity = new_capacity;
    }

    if (is_duplicate(array, &pdu->header, pdu->timestamp)) {
        log_message("Duplicate entry detected. Ignoring PDU.");
        free(pdu->payload.data);
        free(pdu);
        return -4; // Duplicate entry
    }

    array->pdus[array->count++] = pdu;
    time(&pdu->timestamp); // Set the current timestamp

    log_message("MAC_PDU_T added successfully.");

    return 0; // Success
}

int is_duplicate(const DynamicArray *array, const MAC_HEADER *header, time_t timestamp) {
    for (size_t i = 0; i < array->count; ++i) {
        if (memcmp(array->pdus[i]->header.mac, header->mac, MAC_ADDRESS_SIZE) == 0 &&
            difftime(array->pdus[i]->timestamp, timestamp) < 1.0) { // Allow a 1-second window
            return 1;
        }
    }
    return 0;
}

void log_message(const char *message) {
    printf("[%s] %s\n", ctime(&time(NULL)), message);
}

int main() {
    uint8_t default_mac[MAC_ADDRESS_SIZE] = {0x00, 0x11, 0x22, 0x33, 0x44, 0x55};
    DynamicArray *array = create_dynamic_array(10);

    // Example usage
    MAC_PDU_T *pdu = (MAC_PDU_T *)malloc(sizeof(MAC_PDU_T));
    if (!pdu) return -1;

    uint8_t data[128];
    pdu->payload.data = (uint8_t *)malloc(128);
    memcpy(pdu->payload.data, data, 128);
    pdu->payload.length = 128;
    memcpy(pdu->header.mac, default_mac, MAC_ADDRESS_SIZE);

    add_mac_pdu(array, pdu, default_mac);

    free_dynamic_array(array);
    return 0;
}
```

