#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
import "nfacpi_types.h"  // Assume this header contains definitions for NFAPI_RRC_PDU_T, PDCP_PDU, SRB_ID, SNR_INFO

#define MAX_STRUCTURES 100000
#define LOG_LEVEL_DEBUG 3
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_WARN 1
#define LOG_LEVEL_ERROR 0

typedef struct {
    int verbosity;
} Logger;

Logger logger = {LOG_LEVEL_INFO};

pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_RRC_PDU_T *nfa_pdu_array = NULL;
size_t current_size = 0;

void log_message(int level, const char *message) {
    if (logger.verbosity >= level) {
        printf("%s\n", message);
    }
}

int check_srb_id(const NFAPI_RRC_PDU_T *array, size_t size, SRB_ID srb_id) {
    for (size_t i = 1; i < size; ++i) {
        if (array[i].SRB_ID == srb_id && array[i - 1].SRB_ID == srb_id) {
            log_message(LOG_LEVEL_WARN, "Duplicate consecutive SRB_ID detected.");
            return 0;
        }
    }
    return 1;
}

void* manage_nfa_array(void *arg) {
    NFAPI_RRC_PDU_T new_pdu = *(NFAPI_RRC_PDU_T*)arg;

    pthread_mutex_lock(&array_lock);

    if (current_size >= MAX_STRUCTURES) {
        log_message(LOG_LEVEL_ERROR, "Max array size reached. Cannot add more structures.");
        pthread_mutex_unlock(&array_lock);
        return NULL;
    }

    NFAPI_RRC_PDU_T *new_array = realloc(nfa_pdu_array, (current_size + 1) * sizeof(NFAPI_RRC_PDU_T));
    if (!new_array) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed.");
        pthread_mutex_unlock(&array_lock);
        return NULL;
    }

    nfa_pdu_array = new_array;

    size_t pos = current_size;
    while (pos > 0 && nfa_pdu_array[pos - 1].SRB_ID > new_pdu.SRB_ID) {
        nfa_pdu_array[pos] = nfa_pdu_array[pos - 1];
        --pos;
    }

    if (!check_srb_id(nfa_pdu_array, current_size + 1, new_pdu.SRB_ID)) {
        // Rollback on failure
        pthread_mutex_unlock(&array_lock);
        return NULL;
    }

    nfa_pdu_array[pos] = new_pdu;
    ++current_size;

    log_message(LOG_LEVEL_INFO, "Successfully added PDU to array.");

    pthread_mutex_unlock(&array_lock);

    return NULL;
}

void configure_logging(int verbosity) {
    logger.verbosity = verbosity;
}

// Example usage
int main() {
    configure_logging(LOG_LEVEL_DEBUG);

    // Assuming some way of filling NFAPI_RRC_PDU_T structures...
    NFAPI_RRC_PDU_T pdu_example = { /* Fill fields */ };

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, manage_nfa_array, &pdu_example) != 0) {
        log_message(LOG_LEVEL_ERROR, "Thread creation failed.");
    }

    // Wait for the thread to finish
    pthread_join(thread_id, NULL);

    free(nfa_pdu_array);

    return 0;
}
```

### Key Points:
- **Concurrency**: Managed with `pthread_mutex` to ensure thread safety.
- **Dynamic Memory Management**: Efficiently reallocates memory as needed.
- **Logging Framework**: Allows for varying verbosity levels.
- **SRB_ID Validation**: Checks for consecutive identical SRB_IDs before adding new structures.

This implementation assumes certain definitions and mechanisms (`NFAPI_RRC_PDU_T`, `PDCP_PDU`, etc.) are provided in an external header file, which you would typically find in a real-world setup.']

