```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define the structure for CRC indication PDU
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Linked list structure with a mutex for thread safety
typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int element_count;
} CRC_Indication_List;

// Function to initialize the linked list
void init_list(CRC_Indication_List* list, unsigned int valid_RNTI_min, unsigned int valid_RNTI_max) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->element_count = 0;
}

// Function to validate RNTI
int is_valid_RNTI(unsigned int rnti, unsigned int min, unsigned int max) {
    return (rnti >= min && rnti <= max);
}

// Function to add a new element to the linked list
int add_crc_indication(CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU_T pdu, unsigned int valid_RNTI_min, unsigned int valid_RNTI_max) {
    if (!is_valid_RNTI(pdu.RNTI, valid_RNTI_min, valid_RNTI_max)) {
        return -1; // Invalid RNTI
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        return -2; // Memory allocation failure
    }

    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->element_count++;
    pthread_mutex_unlock(&list->lock);

    // Log the successful addition
    printf("Element added. Total count: %d\n", list->element_count);

    return 0; // Success
}

// Function to generate a random CRC indication PDU
NFAPI_CRC_INDICATION_PDU_T generate_random_pdu(unsigned int valid_RNTI_min, unsigned int valid_RNTI_max) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    srand(time(NULL));
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = (rand() % (valid_RNTI_max - valid_RNTI_min + 1)) + valid_RNTI_min;
    pdu.CRC_INDICATION_REL8_TAG = rand() % 256; // Example value
    pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

// Function to free the linked list
void free_list(CRC_Indication_List* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->element_count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    CRC_Indication_List list;
    unsigned int valid_RNTI_min = 100; // Example range
    unsigned int valid_RNTI_max = 200;

    init_list(&list, valid_RNTI_min, valid_RNTI_max);

    for (int i = 0; i < 10000; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_random_pdu(valid_RNTI_min, valid_RNTI_max);
        int result = add_crc_indication(&list, pdu, valid_RNTI_min, valid_RNTI_max);
        if (result != 0) {
            printf("Failed to add element: %d\n", result);
        }
    }

    free_list(&list);

    return 0;
}
