#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long timestamp;  // Assuming a simple numeric representation for timestamps
    int messageID;
    int priority;
} Message;

// Node structure for linked list to store messages by ID for quick access
typedef struct Node {
    int messageID;
    Message *message;
    struct Node *next;
} Node;

// Dynamic array of messages, maintaining order by timestamp
typedef struct {
    Message **messages;  // Array of pointers to Message structures
    size_t capacity;
    size_t size;
    Node *head;  // Linked list for quick access by messageID
} MessageArray;

// Function prototypes
MessageArray* create_message_array(size_t initial_capacity);
void free_message_array(MessageArray *ma);
int add_message(MessageArray *ma, Message *new_msg);
int remove_message_by_id(MessageArray *ma, int id);
int update_message(MessageArray *ma, int id, Message *updated_msg);
Message* find_message_by_id(MessageArray *ma, int id);

// Internal utility functions
static void resize_if_needed(MessageArray *ma);
static int compare_messages(const void *a, const void *b);
static Node* find_node(Node *head, int id);

MessageArray* create_message_array(size_t initial_capacity) {
    MessageArray *ma = (MessageArray *)malloc(sizeof(MessageArray));
    ma->messages = (Message **)malloc(initial_capacity * sizeof(Message *));
    ma->capacity = initial_capacity;
    ma->size = 0;
    ma->head = NULL;
    return ma;
}

void free_message_array(MessageArray *ma) {
    for (size_t i = 0; i < ma->size; ++i) {
        free(ma->messages[i]);
    }
    while (ma->head != NULL) {
        Node *temp = ma->head;
        ma->head = ma->head->next;
        free(temp);
    }
    free(ma->messages);
    free(ma);
}

int add_message(MessageArray *ma, Message *new_msg) {
    resize_if_needed(ma);

    // Insert in sorted order by timestamp
    size_t pos = 0;
    while (pos < ma->size && ma->messages[pos]->timestamp < new_msg->timestamp) {
        ++pos;
    }

    for (size_t i = ma->size; i > pos; --i) {
        ma->messages[i] = ma->messages[i - 1];
    }
    ma->messages[pos] = new_msg;

    // Insert into linked list by messageID
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->messageID = new_msg->messageID;
    new_node->message = new_msg;
    new_node->next = find_node(ma->head, new_msg->messageID);
    if (ma->head == NULL || ma->head->messageID > new_msg->messageID) {
        new_node->next = ma->head;
        ma->head = new_node;
    }

    ++(ma->size);

    return 0; // Success
}

int remove_message_by_id(MessageArray *ma, int id) {
    Node **curr = &(ma->head);
    while (*curr != NULL && (*curr)->messageID != id) {
        curr = &((*curr)->next);
    }

    if (*curr == NULL) return -1; // Not found

    Message *msg_to_remove = (*curr)->message;

    for (size_t i = 0; i < ma->size; ++i) {
        if (ma->messages[i] == msg_to_remove) {
            for (size_t j = i; j < ma->size - 1; ++j) {
                ma->messages[j] = ma->messages[j + 1];
            }
            --(ma->size);
            break;
        }
    }

    Node *temp = *curr;
    *curr = (*curr)->next;
    free(temp);

    return 0; // Success
}

int update_message(MessageArray *ma, int id, Message *updated_msg) {
    Node *node = find_node(ma->head, id);
    if (node == NULL || node->message == NULL) return -1;

    remove_message_by_id(ma, id);
    add_message(ma, updated_msg);

    return 0; // Success
}

Message* find_message_by_id(MessageArray *ma, int id) {
    Node *node = find_node(ma->head, id);
    if (node == NULL || node->message == NULL) return NULL;
    return node->message;
}

static void resize_if_needed(MessageArray *ma) {
    if (ma->size >= ma->capacity) {
        size_t new_capacity = ma->capacity * 2;
        Message **new_messages = (Message **)realloc(ma->messages, new_capacity * sizeof(Message *));
        if (!new_messages) return; // Handle memory allocation failure
        memset(new_messages + ma->capacity, 0, (new_capacity - ma->capacity) * sizeof(Message *));
        ma->messages = new_messages;
        ma->capacity = new_capacity;
    }
}

static int compare_messages(const void *a, const void *b) {
    Message **msgA = (Message **)a;
    Message **msgB = (Message **)b;
    return (*msgA)->timestamp - (*msgB)->timestamp;
}

// Linked list utility
static Node* find_node(Node *head, int id) {
    while (head != NULL && head->messageID != id) {
        head = head->next;
    }
    return head;
}
