['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <arpa/inet.h>
#include <stdbool.h>

typedef struct {
    char ip[INET6_ADDRSTRLEN];
    int port;
} IpAddress;

typedef enum { CONNECTION_DOWN, CONNECTION_UP } ConnectionStatusTag;

typedef struct {
    IpAddress ipAddress;
    int portNumber;
    ConnectionStatusTag connectionStatus;
    time_t lastUpdated;
} NetworkInterfaceStatus;

typedef struct Node {
    NetworkInterfaceStatus data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

bool add_or_update_entry(DynamicArray* array, const char* ip_str, int port, ConnectionStatusTag status) {
    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current != NULL) {
        if (strcmp(current->data.ipAddress.ip, ip_str) == 0 && current->data.portNumber == port) {
            current->data.connectionStatus = status;
            current->data.lastUpdated = time(NULL);
            pthread_mutex_unlock(&array->lock);
            return true; // Updated
        }
        current = current->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&array->lock);
        return false; // Allocation failure
    }

    inet_pton(AF_INET6, ip_str, &((struct in_addr*)&(new_node->data.ipAddress.ip))[0]);
    new_node->data.portNumber = port;
    new_node->data.connectionStatus = status;
    new_node->data.lastUpdated = time(NULL);
    new_node->next = array->head;
    array->head = new_node;
    array->count++;

    pthread_mutex_unlock(&array->lock);
    return true; // Added
}

void cleanup_stale_entries(DynamicArray* array, int timeout_seconds) {
    pthread_mutex_lock(&array->lock);

    time_t current_time = time(NULL);
    Node **current = &(array->head), *temp;

    while (*current != NULL) {
        if (difftime(current_time, (*current)->data.lastUpdated) > timeout_seconds) {
            temp = *current;
            *current = (*current)->next;
            free(temp);
            array->count--;
        } else {
            current = &((*current)->next);
        }
    }

    pthread_mutex_unlock(&array->lock);
}

void* periodic_cleanup(void* arg) {
    DynamicArray* array = (DynamicArray*)arg;
    int timeout_seconds = 60; // Configurable timeout

    while (1) {
        sleep(timeout_seconds); // Wait before cleaning up
        cleanup_stale_entries(array, timeout_seconds);
    }

    return NULL;
}

int main() {
    DynamicArray* array = create_dynamic_array();

    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, periodic_cleanup, array) != 0) {
        perror("Failed to create cleanup thread");
        destroy_dynamic_array(array);
        return EXIT_FAILURE;
    }

    add_or_update_entry(array, "2001:db8::1", 8080, CONNECTION_UP);
    add_or_update_entry(array, "192.168.1.1", 80, CONNECTION_DOWN);

    // Simulate application running
    sleep(120); 

    pthread_cancel(cleanup_thread);
    pthread_join(cleanup_thread, NULL);

    destroy_dynamic_array(array);
    return EXIT_SUCCESS;
}
