#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define PROBABILITY_THRESHOLD 0.5

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function prototypes
Node* create_node(uint32_t tag);
void free_list(Node** head);
int add_element(Node** head, uint32_t tag);
int remove_by_tag(Node** head, uint32_t tag);
void iterate_and_display(Node* head);

// Utility functions
uint16_t generate_random_rnti();
uint8_t toggle_crc_flag();

Node* create_node(uint32_t tag) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    // Initialize the data with random values
    new_node->data.RX_UE_INFORMATION_TAG = tag;
    new_node->data.RNTI = generate_random_rnti();
    new_node->data.CRC_INDICATION_REL8_TAG = toggle_crc_flag();

    new_node->next = NULL;
    return new_node;
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int add_element(Node** head, uint32_t tag) {
    if (!head || !(*head)) {
        *head = create_node(tag);
        return (*head) ? 0 : -1; // Return 0 on success, -1 on failure
    }

    Node* current = *head;
    while (current->next != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == tag)
            return -2; // Element already exists

        current = current->next;
    }

    current->next = create_node(tag);
    return current->next ? 0 : -1; // Return 0 on success, -1 on failure
}

int remove_by_tag(Node** head, uint32_t tag) {
    if (!head || !(*head)) return -1;

    Node* current = *head;
    Node* prev = NULL;

    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != tag) {
        prev = current;
        current = current->next;
    }

    if (!current) return -1; // Element not found

    if (prev == NULL) { // Removing the head
        *head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    return 0; // Success
}

void iterate_and_display(Node* head) {
    Node* current = head;

    while (current != NULL) {
        printf("Tag: %u, RNTI: %hu, CRC Tag: %hhu\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG);

        current = current->next;
    }
}

uint16_t generate_random_rnti() {
    srand(time(NULL) + rand()); // Seed with more entropy
    return (uint16_t)(rand() % 65536); // Random RNTI in the range [0, 65535]
}

uint8_t toggle_crc_flag() {
    return ((double)rand() / RAND_MAX) < PROBABILITY_THRESHOLD ? 1 : 0;
}
