typedef struct {
    LTE_UE_MEASUREMENTS_TAG *array;
    size_t size;
    pthread_mutex_t lock;
} MeasurementManager;

// Initialize the measurement manager
void init_measurement_manager(MeasurementManager *manager, size_t initial_size) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->size = initial_size;
    manager->array = (LTE_UE_MEASUREMENTS_TAG *)malloc(manager->size * sizeof(LTE_UE_MEASUREMENTS_TAG));
    if (!manager->array) {
        perror("Failed to allocate memory for measurement manager");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < manager->size; ++i) {
        manager->array[i].measurements = NULL;
        manager->array[i].capacity = 0;
        manager->array[i].count = 0;
    }
}

// Resize the array within the measurement manager
static void resize_array(MeasurementManager *manager, size_t new_size) {
    LTE_UE_MEASUREMENTS_TAG *new_array = (LTE_UE_MEASUREMENTS_TAG *)realloc(manager->array, new_size * sizeof(LTE_UE_MEASUREMENTS_TAG));
    if (!new_array) {
        perror("Failed to resize measurement manager array");
        exit(EXIT_FAILURE);
    }
    for (size_t i = manager->size; i < new_size; ++i) {
        new_array[i].measurements = NULL;
        new_array[i].capacity = 0;
        new_array[i].count = 0;
    }
    manager->array = new_array;
    manager->size = new_size;
}

// Add a new measurement for a specific LTE carrier
void add_measurement(MeasurementManager *manager, int ue_id, CarrierMeasurement measurement) {
    pthread_mutex_lock(&manager->lock);

    if (ue_id >= manager->size) {
        size_t new_size = (ue_id + 1) > (manager->size * 2) ? (ue_id + 1) : manager->size * 2;
        resize_array(manager, new_size);
    }

    LTE_UE_MEASUREMENTS_TAG *entry = &manager->array[ue_id];
    if (entry->count == entry->capacity) {
        size_t new_capacity = entry->capacity ? entry->capacity * 2 : 4;
        CarrierMeasurement *new_measurements = realloc(entry->measurements, new_capacity * sizeof(CarrierMeasurement));
        if (!new_measurements) {
            perror("Failed to allocate memory for measurements");
            exit(EXIT_FAILURE);
        }
        entry->measurements = new_measurements;
        entry->capacity = new_capacity;
    }

    entry->measurements[entry->count++] = measurement;

    pthread_mutex_unlock(&manager->lock);
}

// Update a measurement for a specific LTE carrier
void update_measurement(MeasurementManager *manager, int ue_id, CarrierMeasurement measurement) {
    pthread_mutex_lock(&manager->lock);

    if (ue_id < manager->size) {
        LTE_UE_MEASUREMENTS_TAG *entry = &manager->array[ue_id];
        for (size_t i = 0; i < entry->count; ++i) {
            if (entry->measurements[i].carrier_id == measurement.carrier_id) {
                entry->measurements[i] = measurement;
                break;
            }
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Retrieve measurements for a specific LTE carrier
CarrierMeasurement *get_measurements(MeasurementManager *manager, int ue_id, size_t *count) {
    pthread_mutex_lock(&manager->lock);

    if (ue_id < manager->size) {
        LTE_UE_MEASUREMENTS_TAG *entry = &manager->array[ue_id];
        *count = entry->count;
        pthread_mutex_unlock(&manager->lock);
        return entry->measurements;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Free all allocated resources
void free_measurement_manager(MeasurementManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].measurements) {
            free(manager->array[i].measurements);
        }
    }

    free(manager->array);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Example usage
int main() {
    MeasurementManager manager;
    init_measurement_manager(&manager, 10);

    CarrierMeasurement measurement = {1, -70.5f, 15, 3};
    add_measurement(&manager, 0, measurement);

    size_t count;
    CarrierMeasurement *measurements = get_measurements(&manager, 0, &count);
    if (measurements) {
        for (size_t i = 0; i < count; ++i) {
            printf("Carrier ID: %d, Signal Strength: %.1f, CQI: %d, PMI: %d\n",
                   measurements[i].carrier_id,
                   measurements[i].signal_strength,
                   measurements[i].cqi,
                   measurements[i].pmi);
        }
    }

    free_measurement_manager(&manager);
    return 0;
}
