```java
// Java Component: Connection Management

import java.io.IOException;
import javax.websocket.ClientEndpoint;
import javax.websocket.CloseReason;
import javax.websocket.EndpointConfig;
import javax.websocket.OnClose;
import javax.websocket.OnOpen;
import javax.websocket.Session;

@ClientEndpoint
public class PersistentConnectionManager {

    private Session session;
    private static final int RETRY_DELAY_MS = 2000; // Retry delay in milliseconds

    public void establishAndMaintainConnection(String uri) {
        while (true) {
            try {
                connect(uri);
                break;
            } catch (IOException e) {
                System.err.println("Connection failed, retrying...");
                sleepWithInterruptHandling(RETRY_DELAY_MS);
            }
        }

        // Maintain connection
        Thread maintenanceThread = new Thread(() -> {
            try {
                while (session.isOpen()) {
                    session.getBasicRemote().sendText("KeepAlive");
                    Thread.sleep(10000); // Send keep-alive every 10 seconds
                }
            } catch (IOException | InterruptedException e) {
                System.err.println("Error maintaining connection: " + e.getMessage());
                establishAndMaintainConnection(uri);
            }
        });

        maintenanceThread.setDaemon(true);
        maintenanceThread.start();
    }

    private void connect(String uri) throws IOException {
        WebSocketContainer container = ContainerProvider.getWebSocketContainer();
        session = container.connectToServer(this, new URI(uri));
    }

    @OnOpen
    public void onOpen(Session session, EndpointConfig config) {
        this.session = session;
        System.out.println("Connection established.");
    }

    @OnClose
    public void onClose(CloseReason closeReason) {
        System.err.println("Connection closed: " + closeReason.getReasonPhrase());
        establishAndMaintainConnection(session.getRequestURI().toString()); // Reconnect using the same URI
    }

    private static void sleepWithInterruptHandling(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
```

