['Below is a C function that initializes and configures a scalable network service capable of handling multiple concurrent TCP connections using threading and efficient resource management:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <errno.h>

#define MAX_CONNECTIONS 1024

typedef enum {
    STATE_IDLE,
    STATE_ACTIVE,
    STATE_CLOSED
} ConnectionState;

typedef struct TCPSessionInfo {
    int cid;
    int socket_fd;
    ConnectionState state;
    pthread_mutex_t lock;
} TCPSessionInfo;

typedef struct {
    TCPSessionInfo *sessions[MAX_CONNECTIONS];
    pthread_mutex_t sessions_lock;
    int next_cid;
} NetworkService;

NetworkService* initialize_network_service(int port) {
    NetworkService *service = (NetworkService *)malloc(sizeof(NetworkService));
    if (!service) return NULL;

    service->next_cid = 1;
    memset(service->sessions, 0, sizeof(service->sessions));
    pthread_mutex_init(&service->sessions_lock, NULL);

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket creation failed");
        free(service);
        return NULL;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        free(service);
        return NULL;
    }

    if (listen(server_fd, MAX_CONNECTIONS) < 0) {
        perror("listen failed");
        close(server_fd);
        free(service);
        return NULL;
    }

    service->server_fd = server_fd;

    printf("Network Service initialized on port %d\n", port);

    return service;
}

void handle_new_connection(NetworkService *service, int client_fd) {
    pthread_mutex_lock(&service->sessions_lock);

    TCPSessionInfo *session = (TCPSessionInfo *)malloc(sizeof(TCPSessionInfo));
    if (!session) {
        close(client_fd);
        pthread_mutex_unlock(&service->sessions_lock);
        return;
    }

    session->cid = service->next_cid++;
    session->socket_fd = client_fd;
    session->state = STATE_ACTIVE;

    pthread_mutex_init(&session->lock, NULL);

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (!service->sessions[i]) {
            service->sessions[i] = session;
            break;
        }
    }

    printf("New connection established with CID: %d\n", session->cid);

    pthread_mutex_unlock(&service->sessions_lock);

    // Handle client communication in a separate thread
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, handle_client_communication, (void *)session);
}

void *handle_client_communication(void *arg) {
    TCPSessionInfo *session = (TCPSessionInfo *)arg;

    pthread_mutex_lock(&session->lock);

    // Simulate data handling
    char buffer[1024] = {0};
    int valread = read(session->socket_fd, buffer, 1024);
    if (valread > 0) {
        printf("Received: %s\n", buffer);
        send(session->socket_fd, "Hello from server", strlen("Hello from server"), 0);
    }

    // Close the connection
    close(session->socket_fd);
    session->state = STATE_CLOSED;

    pthread_mutex_unlock(&session->lock);

    pthread_mutex_destroy(&session->lock);
    free(session);

    return NULL;
}

void run_service(NetworkService *service) {
    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(service->server_fd, (struct sockaddr *)&client_addr, &client_len);

        if (client_fd < 0) {
            perror("accept failed");
            continue;
        }

        handle_new_connection(service, client_fd);
    }
}

void cleanup_network_service(NetworkService *service) {
    close(service->server_fd);
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (service->sessions[i]) {
            pthread_mutex_lock(&service->sessions[i]->lock);
            close(service->sessions[i]->socket_fd);
            free(service->sessions[i]);
            pthread_mutex_unlock(&service->sessions[i]->lock);
        }
    }

    pthread_mutex_destroy(&service->sessions_lock);
    free(service);
}
```

This code provides a basic setup for handling TCP connections concurrently, using threads to manage each connection individually. It includes efficient resource management and is designed to scale by adding more sessions dynamically. The use of mutexes ensures thread safety, which is critical when managing shared resources such as the list of active sessions.']

