CRCLinkedList* create_crc_linked_list(size_t maxStructs) {
    CRCLinkedList* list = (CRCLinkedList*)malloc(sizeof(CRCLinkedList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for linked list\n");
        exit(EXIT_FAILURE);
    }

    list->table = (Node**)calloc(HASH_TABLE_SIZE, sizeof(Node*));
    pthread_mutex_init(&list->lock, NULL);
    list->allocated_count = 0;
    list->maxStructs = maxStructs;

    return list;
}

void free_crc_linked_list(CRCLinkedList* list) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node* node = list->table[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free_node(temp);
        }
    }

    pthread_mutex_destroy(&list->lock);
    free(list->table);
    free(list);
}

bool insert_crc_linked_list(CRCLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->allocated_count >= list->maxStructs) {
        fprintf(stderr, "Reached maximum structure count\n");
        return false;
    }

    pthread_mutex_lock(&list->lock);

    unsigned int index = hash(data.RNTI);
    Node* node = create_node(data);

    // Insert at the beginning
    node->next = list->table[index];
    list->table[index] = node;

    ++list->allocated_count;
    pthread_mutex_unlock(&list->lock);

    return true;
}

void cleanup_crc_linked_list(CRCLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    // Example: Remove nodes if certain conditions are met (e.g., stale data)
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node** node = &list->table[i];
        while (*node) {
            Node* temp = *node;
            if (/* condition to remove */) { // Define your cleanup condition here
                *node = temp->next;
                free_node(temp);
                --list->allocated_count;
            } else {
                node = &temp->next;
            }
        }
    }

    pthread_mutex_unlock(&list->lock);
