#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Define a custom message structure
typedef struct {
    time_t timestamp;
    char session_id[64];
    int status_flag;
} Message;

// Node for linked list to store messages
typedef struct MessageNode {
    Message data;
    struct MessageNode* next;
} MessageNode;

// Dynamic array of messages with thread safety
typedef struct {
    MessageNode* head;
    pthread_mutex_t lock;  // Mutex for synchronizing access
} MessageArray;

// Function prototypes
void init_message_array(MessageArray* arr);
void add_message(MessageArray* arr, const char* session_id, int status_flag);
Message* find_message_by_session_id(MessageArray* arr, const char* session_id);
int update_status_by_session_id(MessageArray* arr, const char* session_id, int new_status);
void remove_message_by_session_id(MessageArray* arr, const char* session_id);

// Initialize the message array
void init_message_array(MessageArray* arr) {
    arr->head = NULL;
    pthread_mutex_init(&arr->lock, NULL);
}

// Add a new message to the array
void add_message(MessageArray* arr, const char* session_id, int status_flag) {
    MessageNode* newNode = (MessageNode*)malloc(sizeof(MessageNode));
    if (!newNode) return; // Handle allocation failure

    pthread_mutex_lock(&arr->lock);

    newNode->data.timestamp = time(NULL);
    strncpy(newNode->data.session_id, session_id, sizeof(newNode->data.session_id) - 1);
    newNode->data.status_flag = status_flag;
    newNode->next = arr->head;
    arr->head = newNode;

    pthread_mutex_unlock(&arr->lock);
}

// Find a message by its session ID
Message* find_message_by_session_id(MessageArray* arr, const char* session_id) {
    pthread_mutex_lock(&arr->lock);

    MessageNode* current = arr->head;
    while (current) {
        if (strcmp(current->data.session_id, session_id) == 0) {
            pthread_mutex_unlock(&arr->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&arr->lock);
    return NULL; // Not found
}

// Update the status flag of a message by its session ID
int update_status_by_session_id(MessageArray* arr, const char* session_id, int new_status) {
    MessageNode* current = arr->head;

    pthread_mutex_lock(&arr->lock);

    while (current) {
        if (strcmp(current->data.session_id, session_id) == 0) {
            current->data.status_flag = new_status;
            pthread_mutex_unlock(&arr->lock);
            return 1; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&arr->lock);
    return 0; // Not found
}

// Remove a message by its session ID
void remove_message_by_session_id(MessageArray* arr, const char* session_id) {
    MessageNode **current = &arr->head;

    pthread_mutex_lock(&arr->lock);

    while (*current) {
        if (strcmp((*current)->data.session_id, session_id) == 0) {
            MessageNode* temp = *current;
            *current = (*current)->next;
            free(temp);
            pthread_mutex_unlock(&arr->lock);
            return; // Exit after removal
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&arr->lock); // Unlock even if not found
}

// Free the entire message array (for cleanup purposes)
void destroy_message_array(MessageArray* arr) {
    MessageNode *current, *temp;

    pthread_mutex_lock(&arr->lock);

    current = arr->head;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
}
```

This implementation uses a mutex to ensure thread-safe operations on the dynamic array of message structures. The linked list structure allows efficient addition and removal of messages, which is important for maintaining low latency even as the number of sessions grows. Trade-offs are made by choosing memory allocation (linked list nodes) over potentially faster but more complex data structures like concurrent hash maps or lock-free queues to ensure simplicity and maintainability while still achieving necessary concurrency control. The design provides a fallback by allowing graceful handling when session metadata is unavailable, through checking for `NULL` pointers in message search operations without failing the system as a whole.']

