typedef struct {
    int key;
    // Other fields...
} SECURITY_CONTEXT_T;

typedef enum {
    IDLE,
    CONNECTED,
    HANDOVER,
    TERMINATED
} RRC_STATE;

typedef struct LTE_ENB_RRC_INST {
    int UE_ID;
    RRC_STATE rrc_state;
    SECURITY_CONTEXT_T *security_context;
} LTE_ENB_RRC_INST_T;

typedef struct Node {
    LTE_ENB_RRC_INST_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_security_context(SECURITY_CONTEXT_T *context) {
    // Free any allocated resources within SECURITY_CONTEXT_T
    free(context);
}

int initialize_security_context(LTE_ENB_RRC_INST_T* inst, RRC_STATE new_state) {
    if (inst->security_context) {
        free_security_context(inst->security_context);
    }
    inst->security_context = (SECURITY_CONTEXT_T*)malloc(sizeof(SECURITY_CONTEXT_T));
    if (!inst->security_context) return -1;

    // Initialize SECURITY_CONTEXT_T based on new_state
    inst->rrc_state = new_state;
    // e.g., inst->security_context->key = fetch_key_based_on(new_state);

    return 0;
}

int add_element(DynamicList* list, int ue_id, RRC_STATE state) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }

    LTE_ENB_RRC_INST_T inst;
    inst.UE_ID = ue_id;
    inst.rrc_state = state;

    if (initialize_security_context(&inst, state)) {
        free(new_node);
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure in security context
    }

    new_node->data = inst;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_element(DynamicList* list, int ue_id) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current) {
        if (current->data.UE_ID == ue_id) {
            if (prev)
                prev->next = current->next;
            else
                list->head = current->next;

            free_security_context(current->data.security_context);
            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0; // Successfully removed
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Element not found
}

int update_element(DynamicList* list, int ue_id, RRC_STATE new_state) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        if (current->data.UE_ID == ue_id) {
            if (initialize_security_context(&current->data, new_state)) {
                pthread_mutex_unlock(&list->lock);
                return -1; // Memory allocation failure in security context
            }
            current->data.rrc_state = new_state;
            pthread_mutex_unlock(&list->lock);
            return 0; // Successfully updated
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Element not found
}

void free_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *next_node;
    while (current) {
        next_node = current->next;
        free_security_context(current->data.security_context);
        free(current);
        current = next_node;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    DynamicList* list = create_list();

    if (add_element(list, 1, CONNECTED) == 0) printf("Element added\n");
    if (update_element(list, 1, HANDOVER) == 0) printf("Element updated\n");
    if (remove_element(list, 1) == 0) printf("Element removed\n");

    free_list(list);
    return 0;
}
