#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int packetID;
    time_t timestamp;
    size_t payloadSize;
} DataPacket;

DataPacket* initializeDataPackets(size_t numPackets, const char** error) {
    if (numPackets == 0) {
        *error = "Number of packets must be greater than zero.";
        return NULL;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    DataPacket* packets = malloc(numPackets * sizeof(DataPacket));
    if (!packets) {
        *error = "Memory allocation failed for data packets.";
        return NULL;
    }

    for (size_t i = 0; i < numPackets; ++i) {
        packets[i].packetID = i + 1;
        packets[i].timestamp = time(NULL);
        packets[i].payloadSize = rand() % 1024 + 1; // Random payload size between 1 and 1024 bytes
    }

    return packets;
}

void freeDataPackets(DataPacket* packets) {
    if (packets) {
        free(packets);
    }
}

int main() {
    const char* error = NULL;
    size_t numPackets = 1000; // Example number of packets

    DataPacket* dataPackets = initializeDataPackets(numPackets, &error);
    if (!dataPackets) {
        fprintf(stderr, "Error: %s\n", error);
        return EXIT_FAILURE;
    }

    // Simulate processing
    for (size_t i = 0; i < numPackets; ++i) {
        printf("Packet ID: %d, Timestamp: %ld, Payload Size: %zu bytes\n",
               dataPackets[i].packetID,
               dataPackets[i].timestamp,
               dataPackets[i].payloadSize);
    }

    freeDataPackets(dataPackets);
    return EXIT_SUCCESS;
}
```

### Key Points:
