int find_duplicate_UE_ID(DoublyLinkedList* list, int UE_ID) {
    LTE_ENB_RRC_INST_T* current = list->head;
    while (current != NULL) {
        if (current->UE_ID == UE_ID) {
            return 1; // Duplicate found
