        printf("Duplicate UE_ID detected: %d\n", UE_ID);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    LTE_ENB_RRC_INST_T* new_node = malloc(sizeof(LTE_ENB_RRC_INST_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->UE_ID = UE_ID;
    new_node->RRC_STATE = rrc_state;
    new_node->security_context = malloc(sizeof(SECURITY_CONTEXT_T));
    init_security_context(new_node->security_context, rrc_state);

    new_node->next = list->head;
    if (list->head != NULL) {
        list->head->prev = new_node;
    }
    new_node->prev = NULL;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void remove_element(DoublyLinkedList* list, int UE_ID) {
    pthread_mutex_lock(&list->lock);

    LTE_ENB_RRC_INST_T *current = list->head;
    while (current != NULL) {
        if (current->UE_ID == UE_ID) {
            if (current->prev) current->prev->next = current->next;
            if (current->next) current->next->prev = current->prev;
            if (list->head == current) list->head = current->next;

            free(current->security_context);
            free(current);

            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void update_element(DoublyLinkedList* list, int UE_ID, RRC_STATE new_state) {
    pthread_mutex_lock(&list->lock);

