    while (current != NULL) {
        if (current->UE_ID == UE_ID) {
            current->RRC_STATE = new_state;
            init_security_context(current->security_context, new_state);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_elements(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    LTE_ENB_RRC_INST_T *current = list->head;
    while (current != NULL) {
        printf("UE_ID: %d, RRC_STATE: %d\n", current->UE_ID, current->RRC_STATE);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    LTE_ENB_RRC_INST_T *current = list->head;
    while (current != NULL) {
        LTE_ENB_RRC_INST_T *next_node = current->next;
        free(current->security_context);
        free(current);
        current = next_node;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
