void log_state_transition(int ue_id, RRC_STATE old_state, RRC_STATE new_state) {
    if (log_file) {
        fprintf(log_file, "UE_ID: %d, Transition from %d to %d\n", ue_id, old_state, new_state);
    }
}

// Initialize the list
void init_list(RRC_LIST_T* list) {
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    list->elements = malloc(list->capacity * sizeof(LTE_ENB_RRC_INST_T));
    if (!list->elements) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

// Resize the list
void resize_list(RRC_LIST_T* list) {
    size_t new_capacity = list->capacity * 2;
    LTE_ENB_RRC_INST_T* new_elements = realloc(list->elements, new_capacity * sizeof(LTE_ENB_RRC_INST_T));
    if (!new_elements) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->elements = new_elements;
    list->capacity = new_capacity;
}

// Add an element to the list
void add_element(RRC_LIST_T* list, LTE_ENB_RRC_INST_T instance) {
    pthread_mutex_lock(&list_mutex);

    if (list->size == list->capacity) {
        resize_list(list);
    }

    list->elements[list->size++] = instance;

    pthread_mutex_unlock(&list_mutex);
}

// Remove an element from the list
void remove_element(RRC_LIST_T* list, int ue_id) {
    pthread_mutex_lock(&list_mutex);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->elements[i].UE_ID == ue_id) {
            free(list->elements[i].security_context);
            memmove(&list->elements[i], &list->elements[i + 1],
                    (list->size - i - 1) * sizeof(LTE_ENB_RRC_INST_T));
            list->size--;
            break;
        }
    }

    pthread_mutex_unlock(&list_mutex);
