#define MAX_MEMORY_LIMIT 1024 * 1024 // Example memory limit: 1MB

typedef struct {
    double traffic_rate;
    double packet_loss;
    double latency;
} NIC_Stats;

typedef struct {
    int interface_id;
    NIC_Stats stats[MAX_MEMORY_LIMIT / sizeof(NIC_Stats)]; // Dynamic size based on memory limit
    size_t current_size;
    pthread_mutex_t lock; // For thread safety
} NIC_Interface;

// Function to initialize the NIC interface with dynamic allocation
int init_nic_interface(NIC_Interface *interface, int threshold) {
    if (!interface || threshold <= 0 || (threshold * sizeof(NIC_Stats)) > MAX_MEMORY_LIMIT) {
        fprintf(stderr, "Invalid parameters for initialization.\n");
        return -1;
    }

    interface->current_size = 0;

    // Allocate memory based on the threshold
    NIC_Stats *stats_array = malloc(threshold * sizeof(NIC_Stats));
    if (!stats_array) {
        fprintf(stderr, "Memory allocation failed!\n");
        return -2; // Allocation error
    }

    interface->interface_id = rand(); // Assign a random ID for demonstration purposes
    memcpy(interface->stats, stats_array, threshold * sizeof(NIC_Stats));

    free(stats_array);
    pthread_mutex_init(&interface->lock, NULL);

    return 0;
}

// Function to update NIC statistics (stub for data feed integration)
void update_nic_stats(NIC_Interface *interface, int index, double traffic_rate, double packet_loss, double latency) {
    if (!interface || interface->current_size <= index) {
        fprintf(stderr, "Invalid parameters or index out of bounds!\n");
        return;
    }

    pthread_mutex_lock(&interface->lock);
    NIC_Stats *stats = &interface->stats[index];
    stats->traffic_rate = traffic_rate;
    stats->packet_loss = packet_loss;
    stats->latency = latency;
    pthread_mutex_unlock(&interface->lock);

    // Example logging
    printf("Updated stats for interface %d: rate=%.2f, loss=%.2f, latency=%.2f\n",
           interface->interface_id, traffic_rate, packet_loss, latency);
}

// Function to free NIC resources
void free_nic_interface(NIC_Interface *interface) {
    if (!interface) return;

    pthread_mutex_destroy(&interface->lock);
}

int main() {
    NIC_Interface nic;

    int threshold = 100; // Example threshold value

    if (init_nic_interface(&nic, threshold) != 0) {
        fprintf(stderr, "Failed to initialize NIC interface.\n");
        return EXIT_FAILURE;
    }

    // Simulate data feed update
    update_nic_stats(&nic, 0, 100.0, 1.5, 10.2);

    free_nic_interface(&nic);

    return EXIT_SUCCESS;
}
