#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define LTE_PHY_TEST_FRAME_CONFIG structure
typedef struct {
    int modulation_scheme;
    int bandwidth;
    int num_symbols;
} LTE_PHY_TEST_FRAME_CONFIG;

// Dynamic array wrapper with thread safety
typedef struct {
    LTE_PHY_TEST_FRAME_CONFIG *configs;
    size_t count;
    pthread_mutex_t lock; // Mutex for synchronization
} ConfigArray;

// Function to initialize and populate the dynamic array
int init_config_array(ConfigArray *array, size_t initial_size, const char *data_source) {
    if (!array || !data_source) return -1;

    pthread_mutex_init(&array->lock, NULL);
    array->configs = (LTE_PHY_TEST_FRAME_CONFIG *)malloc(initial_size * sizeof(LTE_PHY_TEST_FRAME_CONFIG));
    if (!array->configs) return -1;

    array->count = 0;

    // Load configurations from data source
    FILE *file = fopen(data_source, "r");
    if (!file) {
        free(array->configs);
        pthread_mutex_destroy(&array->lock);
        return -1;
    }

    LTE_PHY_TEST_FRAME_CONFIG config;
    while (fscanf(file, "%d %d %d", &config.modulation_scheme,
                          &config.bandwidth, &config.num_symbols) == 3) {
        // Validate and sanitize input data
        if (config.modulation_scheme <= 0 || config.bandwidth <= 0 || config.num_symbols <= 0) continue;

        pthread_mutex_lock(&array->lock);
        if (array->count >= initial_size) {
            size_t new_size = initial_size * 2;
            LTE_PHY_TEST_FRAME_CONFIG *new_configs = realloc(array->configs, new_size * sizeof(LTE_PHY_TEST_FRAME_CONFIG));
            if (!new_configs) {
                pthread_mutex_unlock(&array->lock);
                fclose(file);
                free(array->configs);
                pthread_mutex_destroy(&array->lock);
                return -1;
            }
            array->configs = new_configs;
            initial_size = new_size;
        }

        array->configs[array->count++] = config;
        pthread_mutex_unlock(&array->lock);
    }

    fclose(file);
    return 0;
}

// Function to free the dynamic array
void free_config_array(ConfigArray *array) {
    if (array) {
        pthread_mutex_lock(&array->lock);
        free(array->configs);
        pthread_mutex_unlock(&array->lock);
        pthread_mutex_destroy(&array->lock);
    }
}

// Example usage
int main() {
    ConfigArray array;
    if (init_config_array(&array, 10, "config_data.txt") == 0) {
        printf("Configurations loaded successfully. Total: %zu\n", array.count);
    } else {
        fprintf(stderr, "Failed to load configurations.\n");
    }

    free_config_array(&array);
    return 0;
}
```

### Assumptions and Design Decisions:
1. **Memory Management**: The code uses dynamic memory allocation with `malloc` and `realloc` to manage the array size efficiently. This minimizes fragmentation by doubling the array size when needed.

2. **Thread Safety**: A mutex (`pthread_mutex_t`) is used to ensure thread safety during access to the dynamic array, providing a balance between simplicity and performance in multi-threaded environments.

3. **Error Handling**: The function includes robust error handling for file operations and memory allocation failures, returning appropriate error codes.

4. **Input Validation**: Input data from the external source is validated to ensure only positive values are accepted, which helps maintain integrity.

5. **Scalability**: The design supports scaling by dynamically resizing the array as more configurations are loaded.

6. **Synchronization Overhead**: Mutexes introduce some synchronization overhead but provide a straightforward way to manage concurrent access without complex lock-free algorithms.

7. **External Data Source**: Assumes data is provided in a simple text format for ease of parsing and validation.

This implementation aims to balance efficiency, usability, and maintainability while considering the impact on cache performance and CPU utilization.']

