typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crcTag;
    unsigned char CRCFLAG; // 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t count;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T* data;
} DynamicArray;

// Custom allocator functions
void* custom_alloc(size_t size) {
    return malloc(size);
}

void custom_free(void* ptr) {
    free(ptr);
}

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)custom_alloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->count = 0;
    array->capacity = 10; // Initial capacity
    array->data = (NFAPI_CRC_INDICATION_PDU_T*)custom_alloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        custom_free(array);
        return NULL;
    }
    return array;
}

int expand_dynamic_array(DynamicArray* array) {
    size_t new_capacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)custom_alloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return -1;
    memcpy(new_data, array->data, array->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    custom_free(array->data);
    array->data = new_data;
    array->capacity = new_capacity;
    return 0;
}

int add_pdu(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (array->count == array->capacity && expand_dynamic_array(array) != 0) {
        return -1;
    }
    array->data[array->count++] = pdu;
    return 0;
}

void free_dynamic_array(DynamicArray* array) {
    custom_free(array->data);
    custom_free(array);
}

