    size_t num_messages = sizeof(messages) / sizeof(messages[0]);

    for (size_t i = 0; i < num_messages; ++i) {
        process_s1ap_message(messages[i], array);
    }

    // Output processed data
    for (size_t i = 0; i < array->count; ++i) {
        printf("PDU %zu: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%d\n",
               i, array->data[i].crcTag.RX_UE_INFORMATION_TAG,
               array->data[i].crcTag.RNTI, array->data[i].CRCFLAG);
    }

    free_dynamic_array(array);
    return 0;
}
