#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char name[50];
    int age;
    // Add other personal details as needed
} UserProfile;

typedef struct {
    double sessionDuration;  // in seconds
    int activityCount;
    int errorOccurrences;
} SessionMetrics;

typedef struct UserSession {
    unsigned long sessionID;
    UserProfile profile;
    SessionMetrics metrics;
    time_t lastActiveTime;
    struct UserSession* next;
} UserSession;

#define MAX_SESSIONS 10000000

// Node for hash table
typedef struct HashNode {
    UserSession* session;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    size_t capacity;
    pthread_rwlock_t lock;
} SessionHashTable;

unsigned long hashFunction(unsigned long sessionID, size_t capacity) {
    return sessionID % capacity;
}

UserSession* createUserSession(unsigned long sessionID, UserProfile profile) {
    UserSession* newSession = (UserSession*)malloc(sizeof(UserSession));
    if (!newSession) return NULL;
    newSession->sessionID = sessionID;
    memcpy(&newSession->profile, &profile, sizeof(UserProfile));
    newSession->metrics.sessionDuration = 0.0;
    newSession->metrics.activityCount = 0;
    newSession->metrics.errorOccurrences = 0;
    time(&newSession->lastActiveTime);
    newSession->next = NULL;
    return newSession;
}

SessionHashTable* createSessionTable(size_t capacity) {
    SessionHashTable* table = (SessionHashTable*)malloc(sizeof(SessionHashTable));
    if (!table) return NULL;

    table->buckets = (HashNode**)calloc(capacity, sizeof(HashNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = capacity;
    pthread_rwlock_init(&table->lock, NULL);

    return table;
}

void addUserSession(SessionHashTable* table, UserSession* session) {
    unsigned long index = hashFunction(session->sessionID, table->capacity);
    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    if (!newNode) return;

    newNode->session = session;
    newNode->next = NULL;

    pthread_rwlock_wrlock(&table->lock);
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    pthread_rwlock_unlock(&table->lock);
}

UserSession* getUserSession(SessionHashTable* table, unsigned long sessionID) {
    unsigned long index = hashFunction(sessionID, table->capacity);

    pthread_rwlock_rdlock(&table->lock);
    HashNode* current = table->buckets[index];
    while (current) {
        if (current->session->sessionID == sessionID) {
            pthread_rwlock_unlock(&table->lock);
            return current->session;
        }
        current = current->next;
    }
    pthread_rwlock_unlock(&table->lock);

    return NULL;
}

void updateUserProfile(SessionHashTable* table, unsigned long sessionID, UserProfile newProfile) {
    UserSession* session = getUserSession(table, sessionID);
    if (session) {
        memcpy(&session->profile, &newProfile, sizeof(UserProfile));
    }
}

SessionMetrics getSessionMetrics(SessionHashTable* table, unsigned long sessionID) {
    UserSession* session = getUserSession(table, sessionID);
    SessionMetrics metrics;
    memset(&metrics, 0, sizeof(metrics));

    if (session) {
        metrics.sessionDuration = session->metrics.sessionDuration;
        metrics.activityCount = session->metrics.activityCount;
        metrics.errorOccurrences = session->metrics.errorOccurrences;
    }

    return metrics;
}

void cleanupInactiveSessions(SessionHashTable* table, int thresholdSeconds) {
    time_t now = time(NULL);

    for (size_t i = 0; i < table->capacity; ++i) {
        pthread_rwlock_wrlock(&table->lock);
        HashNode *current = table->buckets[i], *prev = NULL;

        while (current) {
            if ((now - current->session->lastActiveTime) > thresholdSeconds) {
                if (prev) {
                    prev->next = current->next;
                } else {
                    table->buckets[i] = current->next;
                }
                UserSession* toDelete = current->session;
                free(current);
                free(toDelete);
            } else {
                prev = current;
            }

            current = current->next;
        }

        pthread_rwlock_unlock(&table->lock);
    }
}

// Example usage
int main() {
    UserProfile profile = {"John Doe", 30};
    SessionHashTable* table = createSessionTable(1024);

    unsigned long sessionID = 12345;
    UserSession* newSession = createUserSession(sessionID, profile);
    addUserSession(table, newSession);

    UserProfile updatedProfile = {"Jane Doe", 31};
    updateUserProfile(table, sessionID, updatedProfile);

    SessionMetrics metrics = getSessionMetrics(table, sessionID);
    printf("Activity Count: %d\n", metrics.activityCount);

    cleanupInactiveSessions(table, 3600); // Cleanup sessions inactive for more than an hour

    return 0;
}
