}

CRCList* create_crc_list(size_t initial_size) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) {
        perror("Failed to allocate CRCList");
        exit(EXIT_FAILURE);
    }

    list->buckets = (Node**)calloc(initial_size, sizeof(Node*));
    if (!list->buckets) {
        free(list);
        perror("Failed to allocate buckets");
        exit(EXIT_FAILURE);
    }
    list->size = initial_size;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_crc_list(CRCList* list) {
    if (!list) return;

    for (size_t i = 0; i < list->size; ++i) {
        Node* current = list->buckets[i];
        while (current) {
            Node* to_delete = current;
            current = current->next;
            free(to_delete);
        }
    }

    free(list->buckets);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void resize_crc_list(CRCList* list);

int add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (list->count >= MAX_ELEMENTS) {
        fprintf(stderr, "Maximum size reached\n");
        return -1;
    }

    pthread_mutex_lock(&list->mutex);

    unsigned int index = hash(element.rnti, list->size);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate Node");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    new_node->data = element;
    new_node->next = list->buckets[index];
    list->buckets[index] = new_node;

    ++list->count;

    if (list->count > list->size * 0.75) {
        resize_crc_list(list);
    }

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

int remove_element(CRCList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->mutex);

    unsigned int index = hash(rnti, list->size);
    Node* current = list->buckets[index];
    Node* prev = NULL;

    while (current) {
        if (current->data.rnti == rnti) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->buckets[index] = current->next;
            }
            free(current);
            --list->count;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return -1; // Element not found
}

int update_crcflag(CRCList* list, unsigned int rnti, unsigned char new_crcflag) {
    pthread_mutex_lock(&list->mutex);

    unsigned int index = hash(rnti, list->size);
    Node* current = list->buckets[index];

    while (current) {
        if (current->data.rnti == rnti) {
            current->data.crc_indication.CRCFLAG = new_crcflag;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return -1; // Element not found
}

void resize_crc_list(CRCList* list) {
    size_t new_size = list->size * 2;
    if (new_size > MAX_ELEMENTS) {
        fprintf(stderr, "Cannot resize beyond maximum limit\n");
        return;
    }

    Node** new_buckets = (Node**)calloc(new_size, sizeof(Node*));
    if (!new_buckets) {
        perror("Failed to allocate new buckets during resizing");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    for (size_t i = 0; i < list->size; ++i) {
        Node* current = list->buckets[i];
        while (current) {
            Node* next_node = current->next;
            unsigned int new_index = hash(current->data.rnti, new_size);
            current->next = new_buckets[new_index];
            new_buckets[new_index] = current;
            current = next_node;
        }
    }

    free(list->buckets);
    list->buckets = new_buckets;
    list->size = new_size;

    fprintf(stdout, "Resized CRCList to %zu\n", new_size);
}

// Logging and monitoring functions can be added here
```

### Key Points:
- **Thread Safety**: Achieved using `pthread_mutex_t` for locking the critical sections.
- **Dynamic Resizing**: List resizes when load factor exceeds 0.75, doubling its size.
- **Error Handling**: Handles memory allocation failures and maximum list size constraints.
- **Efficiency**: Uses a hash table with chaining to manage collisions efficiently.

This implementation ensures that the list can grow dynamically while maintaining thread safety and efficient access times.']

