- **Data Structures and Thread Safety:** The `PDU_List` structure manages a dynamic array of `NFAPI_CRC_INDICATION_PDU_T` structures. It uses a read-write lock (`pthread_rwlock_t`) for thread-safe operations.
- **Logging:** A simple logging mechanism allows enabling/disabling logs at runtime, protected by a mutex to ensure consistency across threads.
- **Memory Management:** Functions include initialization (`init_pdu_list`), adding elements with dynamic resizing (`add_pdu`), and cleanup (`free_pdu_list`). Memory allocation errors are handled gracefully.
- **Serialization/Deserialization:** Supports writing the list of PDUs to a binary file, ensuring data integrity. Deserialization reads from a binary file, reconstructing the PDU list in memory.
- **Concurrency Considerations:** Thread-safe mechanisms ensure safe concurrent access and modification of shared resources without race conditions.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define POOL_SIZE 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp;
    unsigned int reference_count;
    struct Node* next;
} Node;

typedef struct {
    Node pool[POOL_SIZE];
    Node* free_list_head;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool nfa_crc_pool = {0};

void initialize_memory_pool(MemoryPool* pool) {
    for (int i = 0; i < POOL_SIZE - 1; ++i) {
        pool->pool[i].next = &pool->pool[i + 1];
    }
    pool->pool[POOL_SIZE - 1].next = NULL;
    pool->free_list_head = &pool->pool[0];
    pthread_mutex_init(&pool->mutex, NULL);
}

Node* allocate_node(MemoryPool* pool) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->free_list_head == NULL) {
        pthread_mutex_unlock(&pool->mutex);
        fprintf(stderr, "Memory pool exhausted\n");
        return NULL;
    }

    Node* node = pool->free_list_head;
    pool->free_list_head = node->next;

    pthread_mutex_unlock(&pool->mutex);

    node->reference_count = 1;
    time(&(node->timestamp));
    return node;
}

void deallocate_node(MemoryPool* pool, Node* node) {
    pthread_mutex_lock(&pool->mutex);

    node->next = pool->free_list_head;
    pool->free_list_head = node;

    pthread_mutex_unlock(&pool->mutex);
}

Node* find_or_allocate_duplicate_rnti_entry(MemoryPool* pool, int rnti) {
    Node* current = NULL;
    pthread_mutex_lock(&pool->mutex);

    for (current = &nfa_crc_pool.pool[0]; current != NULL; current = current->next) {
        if (current->data.RNTI == rnti) {
            break;
        }
    }

    if (current == NULL) { // No duplicate found, allocate a new node
        pthread_mutex_unlock(&pool->mutex);
        Node* new_node = allocate_node(pool);
        if (!new_node) return NULL;  // Allocation failed

        pthread_mutex_lock(&pool->mutex);

        // Assign random CRCFLAG and other fields to the new node
        new_node->data.RX_UE_INFORMATION_TAG = rand() % 1000;
        new_node->data.CRC_INDICATION_REL8_TAG = rand() % 1000;
        new_node->data.CRCFLAG = rand() % 2;

        // Add to head for simplicity
        new_node->next = &nfa_crc_pool.pool[0];
        &nfa_crc_pool.pool[0] = *new_node;

    }

    current->reference_count++;
    pthread_mutex_unlock(&pool->mutex);
    return current;
}

void print_list(MemoryPool* pool) {
    Node* current = NULL;
    pthread_mutex_lock(&pool->mutex);

    for (current = &nfa_crc_pool.pool[0]; current != NULL; current = current->next) {
        printf("RNTI: %d, Timestamp: %ld, CRCFLAG: %d\n",
               current->data.RNTI,
               current->timestamp,
               current->data.CRCFLAG);
    }

    pthread_mutex_unlock(&pool->mutex);
}

int main() {
    initialize_memory_pool(&nfa_crc_pool);

    srand(time(NULL));

    for (int i = 0; i < 10000; ++i) {
        int rnti = rand() % 500;
        find_or_allocate_duplicate_rnti_entry(&nfa_crc_pool, rnti);
    }

    print_list(&nfa_crc_pool);

    return 0;
}
