    for (size_t i = 0; i < N; ++i) {
        uint32_t tag;
        uint16_t rnti;

        // Retry logic with exponential backoff
        int attempt = 0, max_attempts = 5;
        while ((attempt < max_attempts) && (!get_RX_UE_INFORMATION_TAG(&tag) || !get_RNTI(&rnti))) {
            if (attempt == max_attempts - 1) {
                free(array);
                log_message("Allocation failed: Unable to obtain RX_UE_INFORMATION_TAG or RNTI.");
                return NULL;
