    memcpy(new_struct, structure, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    nfa_list[nfa_count++] = new_struct;
    pthread_cond_signal(&cond_var);

    if (logging_enabled) {
        log_debug("Added new NFA structure");
    }

    pthread_mutex_unlock(&list_mutex);
}

// Function to free memory
void free_dynamic_list() {
    pthread_mutex_lock(&list_mutex);
    for (size_t i = 0; i < nfa_count; ++i) {
        free(nfa_list[i]->extended_data); // Free extended data if allocated
        free(nfa_list[i]);
    }
    free(nfa_list);
    nfa_count = 0;
    pthread_mutex_unlock(&list_mutex);
}

// Function to serialize the list to a binary file
void serialize_to_file(const char *filename) {
    pthread_mutex_lock(&list_mutex);

    for (size_t i = 0; i < nfa_count; ++i) {
        if (async_file_write(filename, nfa_list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T)) != 0) {
            log_info("Failed to write structure to file");
        }
    }

    pthread_mutex_unlock(&list_mutex);
}

// Function to handle asynchronous events
void process_async_events() {
    while (true) {
        pthread_mutex_lock(&list_mutex);

        if (nfa_count == 0) {
            pthread_cond_wait(&cond_var, &list_mutex);
        }

        // Process structures here
        for (size_t i = 0; i < nfa_count; ++i) {
            // Handle each structure
            if (logging_enabled) {
                log_debug("Processing NFA structure");
            }
        }

        pthread_mutex_unlock(&list_mutex);
    }
}

// Function to toggle logging
void set_logging(bool enable) {
    logging_enabled = enable;
}
