['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 512

typedef struct {
    int id;
    time_t timestamp;
    char **packets;
    size_t packet_count;
} FrameData;

typedef struct {
    FrameData *frames[MAX_ENTRIES];
    pthread_mutex_t lock;
    size_t count;
    size_t added, retrieved, updated, deleted;
    double total_latency, avg_packet_length;
    int network_status; // 1 for connected, 0 for disconnected
    pthread_cond_t cond_var;
} FrameManager;

FrameManager* create_frame_manager() {
    FrameManager *manager = malloc(sizeof(FrameManager));
    if (!manager) return NULL;

    manager->count = 0;
    manager->added = manager->retrieved = manager->updated = manager->deleted = 0;
    manager->total_latency = 0.0;
    manager->avg_packet_length = 0.0;
    manager->network_status = 1; // Assume network is initially connected
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond_var, NULL);

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        manager->frames[i] = NULL;
    }

    return manager;
}

void destroy_frame_manager(FrameManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        FrameData *frame = manager->frames[i];
        for (size_t j = 0; j < frame->packet_count; ++j) {
            free(frame->packets[j]);
        }
        free(frame->packets);
        free(frame);
    }

    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond_var);
    free(manager);
}

int add_frame(FrameManager *manager, int id, time_t timestamp, char **packets, size_t packet_count) {
    if (manager->count >= MAX_ENTRIES) return -1;

    FrameData *frame = malloc(sizeof(FrameData));
    if (!frame) return -2;

    frame->id = id;
    frame->timestamp = timestamp;
    frame->packets = malloc(packet_count * sizeof(char*));
    if (!frame->packets) {
        free(frame);
        return -3;
    }

    for (size_t i = 0; i < packet_count; ++i) {
        frame->packets[i] = strdup(packets[i]);
        if (!frame->packets[i]) {
            for (size_t j = 0; j < i; ++j) free(frame->packets[j]);
            free(frame->packets);
            free(frame);
            return -4;
        }
    }

    frame->packet_count = packet_count;

    pthread_mutex_lock(&manager->lock);
    manager->frames[manager->count++] = frame;
    manager->added++;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

FrameData* get_frame_by_id(FrameManager *manager, int id) {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    FrameData *result = NULL;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->frames[i]->id == id) {
            result = manager->frames[i];
            manager->retrieved++;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);

    clock_gettime(CLOCK_MONOTONIC, &end);
    double latency = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    manager->total_latency += latency;

    return result;
}

int update_frame_packets(FrameManager *manager, int id, char **new_packets, size_t new_packet_count) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->frames[i]->id == id) {
            FrameData *frame = manager->frames[i];

            for (size_t j = 0; j < frame->packet_count; ++j) {
                free(frame->packets[j]);
            }
            free(frame->packets);

            frame->packets = malloc(new_packet_count * sizeof(char*));
            if (!frame->packets) {
                pthread_mutex_unlock(&manager->lock);
                return -1;
            }

            for (size_t j = 0; j < new_packet_count; ++j) {
                frame->packets[j] = strdup(new_packets[j]);
                if (!frame->packets[j]) {
                    for (size_t k = 0; k < j; ++k) free(frame->packets[k]);
                    free(frame->packets);
                    pthread_mutex_unlock(&manager->lock);
                    return -2;
                }
            }

            frame->packet_count = new_packet_count;
            manager->updated++;

            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -3; // Frame not found
}

int delete_frame(FrameManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->frames[i]->id == id) {
            FrameData *frame = manager->frames[i];

            for (size_t j = 0; j < frame->packet_count; ++j) {
                free(frame->packets[j]);
            }
            free(frame->packets);
            free(frame);

            memmove(&manager->frames[i], &manager->frames[i + 1], (manager->count - i - 1) * sizeof(FrameData*));
            manager->count--;
            manager->deleted++;

            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Frame not found
}

void flush_buffered_frames(FrameManager *manager) {
    if (!manager->network_status) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        // Simulate logging service update
        printf("Logging frame ID: %d\n", manager->frames[i]->id);
    }

    pthread_cond_broadcast(&manager->cond_var);
    pthread_mutex_unlock(&manager->lock);
}

void set_network_status(FrameManager *manager, int status) {
    pthread_mutex_lock(&manager->lock);

    if (status != manager->network_status) {
        manager->network_status = status;
        if (status == 1) { // Network reconnected
            flush_buffered_frames(manager);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void print_statistics(FrameManager *manager) {
    double avg_latency = manager->count > 0 ? manager->total_latency / manager->retrieved : 0.0;
    double avg_packet_length = manager->added > 0 ? (double)(/* sum of all packet lengths */) / manager->added : 0.0;

    printf("Frames added: %zu\n", manager->added);
    printf("Frames retrieved: %zu\n", manager->retrieved);
    printf("Frames updated: %zu\n", manager->updated);
    printf("Frames deleted: %zu\n", manager->deleted);
    printf("Average latency (s): %.6f\n", avg_latency);
    printf("Average packet sequence length: %.2f\n", avg_packet_length);
}

int main() {
    FrameManager *manager = create_frame_manager();
    if (!manager) {
        fprintf(stderr, "Failed to create frame manager\n");
        return 1;
    }

    // Example usage
    char *packets[] = {"packet1", "packet2"};
    add_frame(manager, 1, time(NULL), packets, 2);

    FrameData *frame = get_frame_by_id(manager, 1);
    if (frame) {
        printf("Retrieved frame ID: %d\n", frame->id);
    }

    char *new_packets[] = {"packet3"};
    update_frame_packets(manager, 1, new_packets, 1);

    delete_frame(manager, 1);

    print_statistics(manager);

    destroy_frame_manager(manager);
    return 0;
}
