['Below is a high-performance C implementation using a hash table to manage a dynamic list of `MAC_PDU` structures, ensuring thread safety and efficient memory usage.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PDUS 10000

typedef struct {
    int sequence_number;
    // Other fields like L2_PDU, MAC_Header
} L2_PDU;

typedef struct {
    char pdu_identifier[256];
    L2_PDU l2_pdu;
    pthread_mutex_t lock;
} MAC_PDU;

typedef struct PDU_Node {
    MAC_PDU mac_pdu;
    struct PDU_Node* next;
} PDU_Node;

typedef struct {
    PDU_Node** table;
    size_t size;
    pthread_mutex_t global_lock;
    int count;
} PDU_List;

unsigned long hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash;
}

PDU_List* create_pdu_list(size_t size) {
    PDU_List* list = (PDU_List*)malloc(sizeof(PDU_List));
    if (!list) {
        perror("Failed to allocate memory for PDU_List");
        exit(EXIT_FAILURE);
    }
    list->table = (PDU_Node**)calloc(size, sizeof(PDU_Node*));
    if (!list->table) {
        perror("Failed to allocate memory for hash table");
        free(list);
        exit(EXIT_FAILURE);
    }
    list->size = size;
    pthread_mutex_init(&list->global_lock, NULL);
    list->count = 0;
    return list;
}

void destroy_pdu_list(PDU_List* list) {
    if (!list) return;

    for (size_t i = 0; i < list->size; ++i) {
        PDU_Node* node = list->table[i];
        while (node) {
            PDU_Node* temp = node;
            node = node->next;
            pthread_mutex_destroy(&temp->mac_pdu.lock);
            free(temp);
        }
    }

    free(list->table);
    pthread_mutex_destroy(&list->global_lock);
    free(list);
}

int add_pdu(PDU_List* list, MAC_PDU pdu) {
    if (list->count >= MAX_PDUS) return -1;

    unsigned long index = hash(pdu.pdu_identifier) % list->size;
    PDU_Node* node = (PDU_Node*)malloc(sizeof(PDU_Node));
    if (!node) {
        perror("Failed to allocate memory for PDU_Node");
        return -2;
    }

    pthread_mutex_lock(&list->global_lock);
    node->mac_pdu = pdu;
    pthread_mutex_init(&node->mac_pdu.lock, NULL);
    node->next = list->table[index];
    list->table[index] = node;
    list->count++;
    pthread_mutex_unlock(&list->global_lock);

    return 0;
}

int remove_pdu(PDU_List* list, const char* pdu_identifier) {
    unsigned long index = hash(pdu_identifier) % list->size;
    PDU_Node *node = list->table[index], *prev = NULL;

    pthread_mutex_lock(&list->global_lock);
    while (node) {
        if (strcmp(node->mac_pdu.pdu_identifier, pdu_identifier) == 0) {
            if (prev) prev->next = node->next;
            else list->table[index] = node->next;

            pthread_mutex_destroy(&node->mac_pdu.lock);
            free(node);
            list->count--;
            pthread_mutex_unlock(&list->global_lock);
            return 0;
        }
        prev = node;
        node = node->next;
    }
    pthread_mutex_unlock(&list->global_lock);

    return -1;
}

int update_sequence(PDU_List* list, const char* pdu_identifier, int new_sequence) {
    unsigned long index = hash(pdu_identifier) % list->size;
    PDU_Node* node = list->table[index];

    while (node) {
        pthread_mutex_lock(&node->mac_pdu.lock);
        if (strcmp(node->mac_pdu.pdu_identifier, pdu_identifier) == 0) {
            node->mac_pdu.sequence_number = new_sequence;
            pthread_mutex_unlock(&node->mac_pdu.lock);
            return 0;
        }
        pthread_mutex_unlock(&node->mac_pdu.lock);
        node = node->next;
    }

    return -1;
}

void log_operation(const char* message) {
    printf("%s\n", message); // Replace with a more sophisticated logging mechanism
}
