bool manage_sessions(UserSession **sessions, size_t *session_count);

int main() {
    UserSession *sessions = NULL;
    size_t session_count = 0;

    // Assume some mechanism to periodically update sessions
    while (true) { 
        if (!manage_sessions(&sessions, &session_count)) {
            fprintf(stderr, "Failed to manage sessions\n");
            break;
        }

        // Simulate delay for periodic updates
        sleep(1);
    }

    free(sessions);
    return 0;
}

void log_message(const char *message, int env) {
    if (env == ENV_DEVELOPMENT || env == ENV_PRODUCTION) {
        printf("%s\n", message);
    }
}

bool manage_sessions(UserSession **sessions, size_t *session_count) {
    // Example logic for memory limits and eviction
    struct rlimit rl;
    getrlimit(RLIMIT_AS, &rl);
    size_t total_memory = rl.rlim_cur; 
    size_t max_allowed_usage = total_memory * MEMORY_THRESHOLD_PERCENTAGE / 100;

    size_t current_memory_usage = *session_count * sizeof(UserSession);

    if (current_memory_usage > max_allowed_usage) {
        log_message("Memory usage exceeded the threshold, performing cleanup.", ENV_PRODUCTION);

        for (size_t i = 0; i < *session_count; ++i) {
            if ((*sessions)[i].sessionState == SESSION_EXPIRED) {
                memmove(&(*sessions)[i], &(*sessions)[i + 1],
                        (*session_count - i - 1) * sizeof(UserSession));
                --*session_count;
                i--; // recheck the current index
            }
        }

        if (*session_count > MAX_SESSIONS) {
            size_t sessions_to_remove = *session_count - MAX_SESSIONS;
            memmove(*sessions, &(*sessions)[sessions_to_remove],
                    (MAX_SESSIONS) * sizeof(UserSession));
            *session_count = MAX_SESSIONS;
        }
    }

    // Simulate checking session expiration
    time_t now = time(NULL);
    for (size_t i = 0; i < *session_count; ++i) {
        if ((*sessions)[i].sessionTimeout <= now && (*sessions)[i].sessionState != SESSION_EXPIRED) {
            log_message("Session expired, marking as expired.", ENV_DEVELOPMENT);
            (*sessions)[i].sessionState = SESSION_EXPIRED;
        }
    }

    // Simulate receiving an update from an external session API
    UserSession new_session;
    if (rand() % 2 == 0) { // Randomly simulate a new session update
        snprintf(new_session.sessionID, sizeof(new_session.sessionID), "session_%zu", *session_count);
        new_session.sessionState = SESSION_ACTIVE;
        new_session.sessionTimeout = now + rand() % 3600; // Session lasts between 1-60 minutes

        if (*session_count >= MAX_SESSIONS) {
            log_message("Maximum session capacity reached, unable to add new session.", ENV_DEVELOPMENT);
            return false;
        }

        *sessions = realloc(*sessions, (*session_count + 1) * sizeof(UserSession));
        if (*sessions == NULL) {
            log_message("Failed to allocate memory for a new session.", ENV_PRODUCTION);
            return false;
        }

        (*sessions)[*session_count] = new_session;
        ++*session_count;

        log_message("New session added successfully.", ENV_DEVELOPMENT);
    }

    return true;
}
