#include <pthread.h>
#include <string.h>

#define MAX_TRAFFIC_CLASS 10

typedef struct {
    int priorityLevel;
} FlowControlConfig;

typedef struct {
    int flowID;
    int trafficClass;
    FlowControlConfig flowControlConfig;
} TrafficFlowConfiguration;

// Custom memory pool allocator
typedef struct MemoryPool {
    size_t blockSize;
    unsigned char *pool;
    size_t poolSize;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t blockSize, size_t initialSize) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->blockSize = blockSize;
    mp->poolSize = initialSize;
    mp->pool = (unsigned char*)calloc(mp->poolSize, blockSize);
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->pool == NULL || (char*)mp->pool + mp->blockSize * mp->poolSize <= mp->pool + mp->poolSize * mp->blockSize) {
        // Reallocate memory pool
        size_t newPoolSize = 2 * mp->poolSize;
        unsigned char *newPool = (unsigned char*)realloc(mp->pool, newPoolSize * mp->blockSize);
        if (!newPool) {
            pthread_mutex_unlock(&mp->lock);
            return NULL; // Failed to allocate memory
        }
        memset(newPool + mp->poolSize * mp->blockSize, 0, (newPoolSize - mp->poolSize) * mp->blockSize);
        mp->pool = newPool;
        mp->poolSize = newPoolSize;
    }

    void *ptr = mp->pool;
    mp->pool += mp->blockSize; // Move the pointer for next allocation
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

// Function to initialize dynamic array of TrafficFlowConfiguration
TrafficFlowConfiguration* init_traffic_flows(size_t numFlows, MemoryPool **mp) {
    size_t blockSize = sizeof(TrafficFlowConfiguration);
    *mp = create_memory_pool(blockSize, numFlows);

    if (!*mp) return NULL;

    TrafficFlowConfiguration *flows = (TrafficFlowConfiguration*)malloc(numFlows * blockSize);
    if (!flows) {
        destroy_memory_pool(*mp);
        return NULL;
    }

    for (size_t i = 0; i < numFlows; ++i) {
        flows[i].flowID = i + 1;
        flows[i].trafficClass = rand() % MAX_TRAFFIC_CLASS;
        flows[i].flowControlConfig.priorityLevel = rand() % 100;

        // Allocate each structure from the memory pool
        void *allocatedMemory = pool_alloc(*mp);
        if (!allocatedMemory) {
            free(flows);
            destroy_memory_pool(*mp);
            return NULL; // Allocation failed, clean up and exit
        }
        memcpy(allocatedMemory, &flows[i], blockSize);
    }

    return flows;
}

void cleanup_traffic_flows(TrafficFlowConfiguration *flows, size_t numFlows, MemoryPool **mp) {
    if (flows) free(flows);
    if (*mp) destroy_memory_pool(*mp);
}
```

