#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint32_t rnti;
    bool crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t validTag; // Placeholder for RX_UE_INFORMATION_TAG
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void log_operation(const char* operation) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), operation);
}

bool add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node** current = &(list->head);
    while (*current && (*current)->data.rnti < data.rnti) {
        current = &((*current)->next);
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    newNode->data = data;
    newNode->next = *current;
    *current = newNode;

    log_operation("Added element");
    pthread_mutex_unlock(&list->lock);
    return true;
}

bool remove_from_list(List* list, uint32_t rnti) {
    pthread_mutex_lock(&list->lock);

    Node** current = &(list->head);
    while (*current && (*current)->data.rnti != rnti) {
        current = &((*current)->next);
    }

    if (!(*current)) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    Node* toDelete = *current;
    *current = (*current)->next;
    free(toDelete);

    log_operation("Removed element");
    pthread_mutex_unlock(&list->lock);
    return true;
}

void iterate_and_print(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        printf("RNTI: %u, CRCFLAG: %d\n", current->data.rnti, current->data.crcIndicationRel8Tag.crcFlag);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

bool merge_sorted_lists(List* dest, List* src) {
    if (!src || !dest) return false;

    pthread_mutex_lock(&dest->lock);
    pthread_mutex_lock(&src->lock);

    Node dummy;
    Node* tail = &dummy;
    dummy.next = dest->head;

    Node* s1 = dest->head;
    Node* s2 = src->head;

    while (s1 && s2) {
        if (s1->data.rnti < s2->data.rnti) {
            tail->next = s1;
            s1 = s1->next;
        } else {
            tail->next = s2;
            s2 = s2->next;
        }
        tail = tail->next;
    }

    tail->next = (s1) ? s1 : s2;

    dest->head = dummy.next;
    src->head = NULL;

    pthread_mutex_unlock(&src->lock);
    pthread_mutex_unlock(&dest->lock);

    log_operation("Merged lists");
    return true;
}

bool update_crcflag(List* list, uint32_t rnti, bool newFlag) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current && current->data.rnti != rnti) {
        current = current->next;
    }

    if (current) {
        current->data.crcIndicationRel8Tag.crcFlag = newFlag;
        log_operation("Updated CRCFLAG");
    }

    pthread_mutex_unlock(&list->lock);
    return current ? true : false;
}

List* filter_crcflag_true(List* list) {
    List* result = create_list();
    if (!result) return NULL;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.crcIndicationRel8Tag.crcFlag) {
            add_to_list(result, current->data);
        }
        current = current->next;
    }

    log_operation("Filtered CRCFLAG true");
    pthread_mutex_unlock(&list->lock);

    return result;
}

void destroy_list(List* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    List* list1 = create_list();
    List* list2 = create_list();

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T data1 = { .validTag = 1, .rnti = 100, .crcIndicationRel8Tag = {.crcFlag = false} };
    add_to_list(list1, data1);

    NFAPI_CRC_INDICATION_PDU_T data2 = { .validTag = 1, .rnti = 200, .crcIndicationRel8Tag = {.crcFlag = true} };
    add_to_list(list2, data2);

    merge_sorted_lists(list1, list2);
    iterate_and_print(list1);

    update_crcflag(list1, 100, true);
    List* filteredList = filter_crcflag_true(list1);
    iterate_and_print(filteredList);

    destroy_list(list1);
    destroy_list(list2);
    destroy_list(filteredList);

    return 0;
}
