unsigned int rx_ue_info_tag_pool[MAX_POOL_SIZE];
int pool_index = 0;
pthread_mutex_t tag_pool_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    // Placeholder for async logging service integration
