void* allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        log_message("Memory allocation failed.");
        pthread_exit(NULL);  // Or handle more gracefully depending on your needs
    }
    return ptr;
}

unsigned int generate_crc_tag(unsigned int base_value, unsigned char checksum_flag) {
    // Placeholder for CRC tag generation logic
    return (base_value ^ checksum_flag) & 0xFFFF; // Example operation
}

unsigned int get_next_rx_ue_info_tag() {
    pthread_mutex_lock(&tag_pool_lock);
    if (pool_index >= MAX_POOL_SIZE) {
        log_message("RX_UE_INFORMATION_TAG pool exhausted.");
        pthread_mutex_unlock(&tag_pool_lock);
        return 0; // Or handle according to your design
    }
    unsigned int tag = rx_ue_info_tag_pool[pool_index++];
    pthread_mutex_unlock(&tag_pool_lock);
    return tag;
}

void release_rx_ue_info_tag(unsigned int tag) {
    pthread_mutex_lock(&tag_pool_lock);
    if (pool_index > 0) {
        pool_index--;
        rx_ue_info_tag_pool[pool_index] = tag;
    }
    pthread_mutex_unlock(&tag_pool_lock);
}

NFAPI_CRC_INDICATION_PDU_T* initialize_nfa_crc_indication_array(int n, int verbose_logging) {
    pthread_t current_thread_id = pthread_self();

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*) allocate_memory(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    for (int i = 0; i < n; i++) {
        pthread_mutex_lock(&array_lock);

        array[i].RX_UE_INFORMATION_TAG = get_next_rx_ue_info_tag();
        array[i].RNTI = i + 1;
        array[i].CRC_INDICATION_REL8_TAG = generate_crc_tag(array[i].RNTI, 0x01); // Example checksum flag
        array[i].checksum_validation_flag = 0xFF;  // Example validation flag

        pthread_mutex_unlock(&array_lock);

        if (verbose_logging) {
            printf("Thread %lu: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRC_INDICATION_REL8_TAG=%u\n",
                   current_thread_id, array[i].RX_UE_INFORMATION_TAG,
                   array[i].RNTI, array[i].CRC_INDICATION_REL8_TAG);
        }
    }

    if (!verbose_logging) {
        for (int i = 0; i < n; i++) {
            printf("Thread %lu: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRC_INDICATION_REL8_TAG=%u\n",
                   current_thread_id, array[i].RX_UE_INFORMATION_TAG,
                   array[i].RNTI, array[i].CRC_INDICATION_REL8_TAG);
        }
    }

    return array;
}

void cleanup_resources(NFAPI_CRC_INDICATION_PDU_T *array, int n) {
    if (!array) return;

    for (int i = 0; i < n; i++) {
        release_rx_ue_info_tag(array[i].RX_UE_INFORMATION_TAG);
    }

    free(array);
}

void example_usage() {
    int num_elements = 10;
    int verbose_logging = 1;

    NFAPI_CRC_INDICATION_PDU_T *array = initialize_nfa_crc_indication_array(num_elements, verbose_logging);

    if (array) {
        // Use the array for processing...

        cleanup_resources(array, num_elements);
    }
}

int main() {
    example_usage();
    return 0;
}
