#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_INTS 1000
#define SUM_THRESHOLD 50000

typedef struct {
    int measured_value;
} MEASUREMENT_REPORT_T;

typedef struct {
    unsigned long UE_ID;
    bool additional_info_flag;
    MEASUREMENT_REPORT_T* measurement_reports;
    size_t num_measurement_reports;
} NFAPI_RRC_CONNECTION_RECONFIGURATION_IND_T;

void handle_memory_allocation_failure(void *ptr) {
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

NFAPI_RRC_CONNECTION_RECONFIGURATION_IND_T* create_structure(unsigned long ue_id, bool additional_info_flag,
                                                             MEASUREMENT_REPORT_T reports[], size_t num_reports) {
    NFAPI_RRC_CONNECTION_RECONFIGURATION_IND_T* structure = (NFAPI_RRC_CONNECTION_RECONFIGURATION_IND_T*)malloc(sizeof(NFAPI_RRC_CONNECTION_RECONFIGURATION_IND_T));
    handle_memory_allocation_failure(structure);

    structure->UE_ID = ue_id;
    structure->additional_info_flag = additional_info_flag;
    structure->measurement_reports = (MEASUREMENT_REPORT_T*)malloc(num_reports * sizeof(MEASUREMENT_REPORT_T));
    handle_memory_allocation_failure(structure->measurement_reports);
    for (size_t i = 0; i < num_reports; ++i) {
        structure->measurement_reports[i] = reports[i];
    }
    structure->num_measurement_reports = num_reports;
    return structure;
}

void free_structure(NFAPI_RRC_CONNECTION_RECONFIGURATION_IND_T* structure) {
    if (structure) {
        free(structure->measurement_reports);
        free(structure);
    }
}

bool validate_and_process_integers(int integers[], size_t num_ints, int processed_integers[]) {
    bool seen[MAX_INTS] = {false};
    int sum = 0;

    for (size_t i = 0; i < num_ints; ++i) {
        if (seen[integers[i]]) {
            fprintf(stderr, "Duplicate value detected: %d\n", integers[i]);
            return false;
        }
        seen[integers[i]] = true;

        sum += integers[i];
        if (sum > SUM_THRESHOLD) {
            fprintf(stderr, "Sum exceeds threshold: %d\n", sum);
            return false;
        }

        processed_integers[i] = integers[i];
    }

    return true;
}

void process_input_and_manage_structures() {
    int input_ints[MAX_INTS], processed_ints[MAX_INTS];
    size_t num_inputs = 0;

    printf("Enter up to %d integers, one per line. Enter a non-integer to finish:\n", MAX_INTS);

    while (num_inputs < MAX_INTS) {
        if (scanf("%d", &input_ints[num_inputs]) != 1) {
            break;
        }
        ++num_inputs;
    }

    if (!validate_and_process_integers(input_ints, num_inputs, processed_ints)) {
        fprintf(stderr, "Error processing input integers\n");
        exit(EXIT_FAILURE);
    }

    // Example of creating and managing structures
    MEASUREMENT_REPORT_T example_reports[2] = {{100}, {200}};
    NFAPI_RRC_CONNECTION_RECONFIGURATION_IND_T* structure1 = create_structure(12345, true, example_reports, 2);

    printf("Structure created with UE_ID: %lu\n", structure1->UE_ID);

    // Freeing the dynamically allocated memory
    free_structure(structure1);

    for (size_t i = 0; i < num_inputs; ++i) {
        printf("%d ", processed_ints[i]);
    }
    printf("\n");
}

int main() {
    process_input_and_manage_structures();
    return 0;
}
