#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    char *buffer;
} record;

record* allocate_records(int n, size_t m, char c, int min, int max, size_t T) {
    // Calculate memory requirements
    size_t sizeof_long = sizeof(long);
    size_t sizeof_int = sizeof(int);
    size_t total_memory = n * (sizeof_long + sizeof_int + m);

    if (total_memory > T) {
        fprintf(stderr, "Memory allocation exceeds threshold\n");
        return NULL;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Allocate memory for offsets and keys arrays
    long *offsets = (long*)malloc(n * sizeof_long);
    int *keys = (int*)malloc(n * sizeof_int);

    if (!offsets || !keys) {
        fprintf(stderr, "Failed to allocate memory for offsets or keys\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Allocate memory for the records array
    record *records = (record*)malloc(n * sizeof(record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize records and their buffers
    for (int i = 0; i < n; ++i) {
        offsets[i] = i * (sizeof_long + sizeof_int + m); // Example offset calculation

        keys[i] = min + rand() % (max - min + 1);

        records[i].offset = offsets[i];
        records[i].key = keys[i];

        records[i].buffer = (char*)malloc(m);
        if (!records[i].buffer) {
            fprintf(stderr, "Failed to allocate memory for buffer\n");

            // Free already allocated resources
            while (--i >= 0) {
                free(records[i].buffer);
            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        // Initialize the buffer with character 'c'
        for (size_t j = 0; j < m; ++j) {
            records[i].buffer[j] = c;
        }
    }

    // Free offsets and keys as they are no longer needed
    free(offsets);
    free(keys);

    return records;
}

int main() {
    int n = 1000;
    size_t m = 256;
    char c = 'A';
    int min = 1, max = 100;
    size_t T = 5 * 1024 * 1024; // Example threshold in bytes

    record* records = allocate_records(n, m, c, min, max, T);
    if (records) {
        printf("Records allocated successfully.\n");
        // Use the records...

        // Free each record's buffer and the records array itself
        for (int i = 0; i < n; ++i) {
            free(records[i].buffer);
        }
        free(records);
    } else {
        printf("Failed to allocate records.\n");
    }

    return 0;
}
