```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int phy_tx_frame_config;
} PHY_TX_FRAME_CONFIG;

typedef struct {
    int tx_power_level;
} TX_POWER_LEVEL;

typedef struct {
    int rf_channel_frequency;
} RF_CHANNEL_CONFIG;

typedef struct {
    PHY_TX_FRAME_CONFIG frame_config;
    TX_POWER_LEVEL power_level;
    RF_CHANNEL_CONFIG channel_config;
} LTE_PHY_TX_RECORD;

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheNode {
    int key;
    int value;
    struct CacheNode *prev, *next;
} CacheNode;

typedef struct {
    int capacity;
    CacheNode *head, *tail;
    void (*evict)(void *);
    void *data; // Store array or other data structures
    pthread_mutex_t lock;
} LRUCache;

// Global dynamic array and metadata
LTE_PHY_TX_RECORD *phy_tx_records = NULL;
size_t num_elements = 0;
pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;

// LRU Cache functions
void lruEvict(void *data) {
    // Placeholder for eviction logic (e.g., removing oldest entry)
}

CacheNode* createCacheNode(int key, int value) {
    CacheNode *node = malloc(sizeof(CacheNode));
    node->key = key;
    node->value = value;
    node->prev = node->next = NULL;
    return node;
}

LRUCache* newLRU(int capacity, void (*evict)(void *)) {
    LRUCache *cache = malloc(sizeof(LRUCache));
    cache->capacity = capacity;
    cache->head = cache->tail = NULL;
    cache->evict = evict;
    cache->data = NULL; // Set to appropriate data structure
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void moveToHead(LRUCache *cache, CacheNode *node) {
    if (cache->head == node) return;

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;
    if (cache->tail == node) cache->tail = node->prev;

    node->next = cache->head;
    node->prev = NULL;
    if (cache->head) cache->head->prev = node;
    cache->head = node;
    if (!cache->tail) cache->tail = node;
}

void insertIntoCache(LRUCache *cache, int key, int value) {
    pthread_mutex_lock(&cache->lock);

    CacheNode *node = createCacheNode(key, value);
    if (cache->capacity <= num_elements) {
        // Evict least recently used item
        cache->evict(cache->data); 
    }
    moveToHead(cache, node);
    num_elements++;

    pthread_mutex_unlock(&cache->lock);
}

// Function to add or update LTE_PHY_TX_RECORD in the dynamic array
int managePhyTxRecords(int index, PHY_TX_FRAME_CONFIG frame_config, TX_POWER_LEVEL power_level, RF_CHANNEL_CONFIG channel_config) {
    pthread_mutex_lock(&array_lock);

    if (index >= num_elements && index >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&array_lock);
        return -1; // Overflow or invalid index
    }

    if (index == num_elements) { // Adding new element
        LTE_PHY_TX_RECORD *new_array = realloc(phy_tx_records, sizeof(LTE_PHY_TX_RECORD) * (num_elements + 1));
        if (!new_array) {
            pthread_mutex_unlock(&array_lock);
            return -2; // Memory allocation failed
        }
        phy_tx_records = new_array;
    }

    phy_tx_records[index].frame_config = frame_config;
    phy_tx_records[index].power_level = power_level;
    phy_tx_records[index].channel_config = channel_config;

    pthread_mutex_unlock(&array_lock);
    return 0; // Success
}

// Function to iterate over records and check conditions
void iteratePhyTxRecords(void (*callback)(LTE_PHY_TX_RECORD *)) {
    pthread_mutex_lock(&array_lock);

    for (size_t i = 0; i < num_elements; ++i) {
        callback(&phy_tx_records[i]);
    }

    pthread_mutex_unlock(&array_lock);
}

// Callback example function to check RF_CHANNEL_CONFIG
void checkRfChannelConfig(LTE_PHY_TX_RECORD *record) {
    // Example condition: Check frequency against a band plan
    if (record->channel_config.rf_channel_frequency == 1800) { 
        printf("Record with valid channel frequency found.\n");
    }
}

// Function to populate NFAPI_CRC_INDICATION_PDU_T list
NFAPI_CRC_INDICATION_PDU_T* populateCrcIndicationList(size_t *size, int random_seed) {
    srand(random_seed);
    size_t list_size = num_elements;
    NFAPI_CRC_INDICATION_PDU_T *crc_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list_size);

    pthread_mutex_lock(&array_lock);

    for (size_t i = 0; i < list_size; ++i) {
        crc_list[i].rx_ue_information_tag = rand() % 100;
        crc_list[i].rnti = rand() % 1000;
        crc_list[i].crc_indication_rel8_tag = rand() % 10;
        crc_list[i].crcflag = rand() % 2; // Random CRC flag
    }

    pthread_mutex_unlock(&array_lock);
    *size = list_size;
    return crc_list;
}

int main() {
    LRUCache *cache = newLRU(100, lruEvict);

    managePhyTxRecords(0, (PHY_TX_FRAME_CONFIG){.phy_tx_frame_config=1}, 
                       (TX_POWER_LEVEL){.tx_power_level=20}, (RF_CHANNEL_CONFIG){.rf_channel_frequency=1800});

    iteratePhyTxRecords(checkRfChannelConfig);

    size_t crc_size;
    NFAPI_CRC_INDICATION_PDU_T *crc_list = populateCrcIndicationList(&crc_size, 12345);

    free(crc_list);
    free(phy_tx_records);
    pthread_mutex_destroy(&array_lock);
    pthread_mutex_destroy(&cache->lock);
    free(cache);

    return 0;
}
