    populate_crc_indication_list(DEFAULT_NUM_ELEMENTS, [](int status) {
        if (status == 0)
            printf("Population complete successfully.\n");
        else
            printf("Population failed with error code: %d\n", status);
    });
}

// To be called periodically based on system configuration
void periodic_update(int interval_seconds, size_t num_elements) {
    while (1) {
        populate_crc_indication_list(num_elements, [](int status) {
            if (status != 0)
                log_error("Error during CRC population.");
        });

        sleep(interval_seconds);
    }
}

// Entry point for the program
int main() {
    // Example periodic updates every 10 seconds with default number of elements.
    pthread_t thread;
    pthread_create(&thread, NULL, (void *(*)(void *))periodic_update, (void *)(intptr_t)10);

    example_usage();

    return 0;
}
```

### Key Features Explained:

- **Dynamic Memory Allocation**: Uses `malloc` to handle up to millions of elements without stack overflow.
