#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_CONTEXTS 10000

typedef struct {
    unsigned long incomingBytes;
    unsigned long outgoingBytes;
} TrafficStatistics;

typedef struct {
    char imsi[16];
    void *radioResourceManager; // Placeholder for actual type
    TrafficStatistics trafficStats;
} UEContext;

typedef struct {
    UEContext *contexts[MAX_CONTEXTS];
    pthread_mutex_t lock;
    int count;
} ContextManager;

// Function prototypes
void initializeManager(ContextManager *manager);
int addOrUpdateContext(ContextManager *manager, const char *imsi, void *radioResourceManager);
UEContext* getContext(ContextManager *manager, const char *imsi);
void updateTrafficStats(UEContext *context, unsigned long incomingBytes, unsigned long outgoingBytes);
void cleanupManager(ContextManager *manager);

// Initialize the context manager
void initializeManager(ContextManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
}

// Add or update a UEContext in the manager
int addOrUpdateContext(ContextManager *manager, const char *imsi, void *radioResourceManager) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_CONTEXTS; ++i) {
        if (manager->contexts[i] == NULL || strcmp(manager->contexts[i]->imsi, imsi) == 0) {
            UEContext *context;
            if (manager->contexts[i] == NULL) {
                context = malloc(sizeof(UEContext));
                manager->contexts[manager->count++] = context;
            } else {
                context = manager->contexts[i];
            }

            strncpy(context->imsi, imsi, sizeof(context->imsi) - 1);
            context->radioResourceManager = radioResourceManager;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Error: No space available
}

// Retrieve a UEContext by IMSI
UEContext* getContext(ContextManager *manager, const char *imsi) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_CONTEXTS; ++i) {
        if (manager->contexts[i] != NULL && strcmp(manager->contexts[i]->imsi, imsi) == 0) {
            UEContext *context = manager->contexts[i];
            pthread_mutex_unlock(&manager->lock);
            return context;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

// Update traffic statistics for a given context
void updateTrafficStats(UEContext *context, unsigned long incomingBytes, unsigned long outgoingBytes) {
    if (context != NULL) {
        context->trafficStats.incomingBytes += incomingBytes;
        context->trafficStats.outgoingBytes += outgoingBytes;
    }
}

// Cleanup the manager and free resources
void cleanupManager(ContextManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_CONTEXTS; ++i) {
        if (manager->contexts[i] != NULL) {
            free(manager->contexts[i]);
            manager->contexts[i] = NULL;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Example function to simulate interaction with an external network service
void* trafficUpdateThread(void *arg) {
    ContextManager *manager = (ContextManager *)arg;

    while (1) { // Simulate continuous updates
        sleep(1); // Simulate delay

        pthread_mutex_lock(&manager->lock);

        for (int i = 0; i < manager->count; ++i) {
            if (manager->contexts[i] != NULL) {
                unsigned long incomingBytes = rand() % 100;
                unsigned long outgoingBytes = rand() % 100;

                updateTrafficStats(manager->contexts[i], incomingBytes, outgoingBytes);
            }
        }

        pthread_mutex_unlock(&manager->lock);
    }

    return NULL;
}

int main() {
    ContextManager manager;
    initializeManager(&manager);

    // Example usage
    addOrUpdateContext(&manager, "123456789012345", NULL);
    UEContext *context = getContext(&manager, "123456789012345");
    if (context != NULL) {
        printf("Found IMSI: %s\n", context->imsi);
    }

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, trafficUpdateThread, &manager);

    // Run for a while to simulate application activity
    sleep(10);

    cleanupManager(&manager);
    pthread_cancel(thread_id); // Clean up the update thread

    return 0;
}
