        total_payload_size += sizeof(RFUNION) + strlen((char*)rfunion->data) + 1; // +1 for null terminator
    }

    frame_pdu->payload_data = (char*)malloc(total_payload_size);
    if (!frame_pdu->payload_data) {
        free_nfa_rx_frame_pdu(frame_pdu);
        return NULL;
    }

    char *current_position = frame_pdu->payload_data;

