#define MAX_PACKETS 1000

typedef struct {
    size_t timestamp;
    int interface_id;
    int packet_sizes[MAX_PACKETS];
    size_t num_packets;
} NetworkStatsRecord;

typedef struct Node {
    NetworkStatsRecord record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray* array) {
    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
}

void freeNode(Node* node) {
    if (node) {
        free(node);
    }
}

void addOrUpdateRecord(DynamicArray* array, NetworkStatsRecord new_record) {
    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    Node* prev = NULL;

    while (current != NULL && current->record.interface_id < new_record.interface_id) {
        prev = current;
        current = current->next;
    }

    if (current != NULL && current->record.interface_id == new_record.interface_id) {
        // Update existing record
        memcpy(current->record.packet_sizes, new_record.packet_sizes, sizeof(new_record.packet_sizes));
        current->record.num_packets = new_record.num_packets;
        current->record.timestamp = new_query_time;
