        // Add new record
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&array->lock);
            return;
        }
        memcpy(newNode->record.packet_sizes, new_record.packet_sizes, sizeof(new_record.packet_sizes));
        newNode->record.interface_id = new_record.interface_id;
        newNode->record.num_packets = new_record.num_packets;
        newNode->record.timestamp = new_record.timestamp;

        newNode->next = current;
        if (prev == NULL) {
            array->head = newNode;
        } else {
            prev->next = newNode;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

void queryStatistics(DynamicArray* array, int interface_id, size_t start_time, size_t end_time, NetworkStatsRecord** results, size_t* result_count) {
    pthread_mutex_lock(&array->lock);

