DoublyLinkedList* init_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL; // Handle memory allocation failure

    list->head = NULL;
    list->tail = NULL;

    return list;
}

// Function to append a new node with random data
int append_node(DoublyLinkedList* list, int TLV_TYPE, int RNTI) {
    if (!list) return -1; // Handle invalid list pointer

    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) return -2; // Handle memory allocation failure

    // Populate the data
    newNode->data.TLV_TYPE = TLV_TYPE;
    newNode->data.RNTI = RNTI;

    // Generate random SN and PDCP_SN
