    newNode->data.SN = rand() % 65536;   // Random number between 0 and 65535
    newNode->data.PDCP_SN = rand() % 65536;

    newNode->prev = list->tail;
    newNode->next = NULL;

    if (list->tail) {
        list->tail->next = newNode;
    } else {
        list->head = newNode; // First node in the list
    }

    list->tail = newNode;
    return 0; // Success
}

// Function to free the doubly linked list
void free_list(DoublyLinkedList* list) {
    if (!list) return;

    ListNode* current = list->head;
    while (current) {
        ListNode* nextNode = current->next;
        free(current);
        current = nextNode;
    }

    free(list);
}

