        (*nfa_messages)[i].rx_ue_info->rx_ue_information_tag = i + 1; // Example tag assignment

        // Set CRC_FLAG based on the predefined pattern for error simulation
        int crc_index = i % pattern_size;
        (*nfa_messages)[i].rx_ue_info->crc_indication_rel8.crc_flag = crc_patterns[crc_index];
    }
}

