#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>

typedef struct {
    uint16_t PDCP_SN;
    int PSM_MODE;
} STATUS_PDU;

typedef struct MAC_PDU {
    uint16_t PDCP_SN;
    int PSM_MODE;
    STATUS_PDU status_pdu;
    struct MAC_PDU *next;
} MAC_PDU;

// Function to create a new node
MAC_PDU* create_mac_pdu(uint16_t pdcp_sn, int psm_mode, STATUS_PDU status_pdu) {
    MAC_PDU* new_node = (MAC_PDU*)malloc(sizeof(MAC_PDU));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->PDCP_SN = pdcp_sn;
    new_node->PSM_MODE = psm_mode;
    new_node->status_pdu = status_pdu;
    new_node->next = NULL;
    return new_node;
}

// Function to insert a node at the head of the list
void insert_mac_pdu(MAC_PDU **head, MAC_PDU *new_node) {
    if (!(*head)) {
        (*head) = new_node;
    } else {
        new_node->next = *head;
        (*head) = new_node;
    }
}

// Function to delete a node from the list
void delete_mac_pdu(MAC_PDU **head, uint16_t pdcp_sn) {
    MAC_PDU *temp = *head, *prev = NULL;

    if (temp && temp->PDCP_SN == pdcp_sn) {
        *head = temp->next;
        free(temp);
        return;
    }

    while (temp && temp->PDCP_SN != pdcp_sn) {
        prev = temp;
        temp = temp->next;
    }

    if (!temp) return;

    prev->next = temp->next;
    free(temp);
}

// Function to find a node by PDCP_SN
MAC_PDU* find_mac_pdu(MAC_PDU *head, uint16_t pdcp_sn) {
    while (head != NULL) {
        if (head->PDCP_SN == pdcp_sn)
            return head;
        head = head->next;
    }
    return NULL;
}

// Function to free the entire list
void free_mac_pdu_list(MAC_PDU *head) {
    MAC_PDU *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Utility function for logging state changes in the linked list
void log_state_change(const char* action, MAC_PDU* node) {
    if (!node) return;
    printf("Action: %s | PDCP_SN: %u | PSM_MODE: %d\n", action, node->PDCP_SN, node->PSM_MODE);
}

// Example usage and testing
int main() {
    MAC_PDU *list = NULL;

    // Simulate insertion
    STATUS_PDU status1 = { .PDCP_SN = 0x01, .PSM_MODE = 1 };
    insert_mac_pdu(&list, create_mac_pdu(0x01, 2, status1));

    STATUS_PDU status2 = { .PDCP_SN = 0x02, .PSM_MODE = 3 };
    insert_mac_pdu(&list, create_mac_pdu(0x02, 4, status2));

    // Log state
    MAC_PDU *node = list;
    while (node) {
        log_state_change("INSERT", node);
        node = node->next;
    }

    // Simulate deletion
    delete_mac_pdu(&list, 0x01);

    // Log state after deletion
    node = list;
    while (node) {
        log_state_change("DELETE", node);
        node = node->next;
    }

    free_mac_pdu_list(list);

    return 0;
}
```

