    dynamic_array->count = 0;
    pthread_mutex_init(&dynamic_array->lock, NULL);

    log_operation("Created dynamic array with capacity: " + std::to_string(initial_capacity));
    return dynamic_array;
}

// Function to add or update a PDU in the dynamic array.
bool add_or_update_pdu(DynamicArray *dynamic_array, unsigned long RNTI, int RX_UE_INFORMATION_TAG, bool validate_only) {
    if (!dynamic_array || !pthread_mutex_lock(&dynamic_array->lock)) {
        perror("Failed to lock mutex");
        return false;
    }

    // Check for existing entry with the same RNTI.
    for (size_t i = 0; i < dynamic_array->count; ++i) {
        if (dynamic_array->array[i].RNTI == RNTI) {
            pthread_mutex_unlock(&dynamic_array->lock);

            // Update CRCFLAG with a random value
            dynamic_array->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

            log_operation("Updated PDU for RNTI: " + std::to_string(RNTI));
            return true;
        }
    }

    if (dynamic_array->count == dynamic_array->capacity) {
        size_t new_capacity = dynamic_array->capacity * 2; // Double the capacity.
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(dynamic_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_array) {
            pthread_mutex_unlock(&dynamic_array->lock);
            perror("Failed to reallocate memory for dynamic array");
            return false;
        }

        dynamic_array->array = new_array;
        dynamic_array->capacity = new_capacity;

        log_operation("Resized dynamic array to capacity: " + std::to_string(new_capacity));
    }

    if (!check_unique_tag(dynamic_array, RX_UE_INFORMATION_TAG)) {
        pthread_mutex_unlock(&dynamic_array->lock);
        return false; // Tag is not unique.
    }

    if (validate_only) {
        pthread_mutex_unlock(&dynamic_array->lock);
        return true;
    }

    // Add new PDU
    NFAPI_CRC_INDICATION_PDU_T *pdu = &dynamic_array->array[dynamic_array->count++];
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag.

    log_operation("Added new PDU for RNTI: " + std::to_string(RNTI));

    pthread_mutex_unlock(&dynamic_array->lock);
    return true;
}

// Function to free the dynamic array.
void free_dynamic_array(DynamicArray *dynamic_array) {
    if (dynamic_array) {
        free(dynamic_array->array);
        pthread_mutex_destroy(&dynamic_array->lock);
        free(dynamic_array);
        log_operation("Freed dynamic array");
    }
}

// Function to check for unique RX_UE_INFORMATION_TAG.
bool check_unique_tag(const DynamicArray *dynamic_array, int RX_UE_INFORMATION_TAG) {
    for (size_t i = 0; i < dynamic_array->count; ++i) {
        if (dynamic_array->array[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            return false;
        }
    }
    return true;
}

// Function to log operations.
void log_operation(const char *operation) {
    // Simple logging mechanism for debugging purposes.
    printf("%s\n", operation);
}
