void* customMalloc(size_t size) {
    pthread_mutex_lock(&memoryPool.lock);

    if (size > memoryPool.maxCapacity - memoryPool.currentSize) {
        // Adjust pool size or handle error
        pthread_mutex_unlock(&memoryPool.lock);
        return NULL;
    }

    MemoryPoolNode *node = memoryPool.head;

    while (node && node->blockSize < size) {
        node = node->next;
    }

    if (!node) {
        node = customMalloc(sizeof(MemoryPoolNode));
        if (!node) {
            pthread_mutex_unlock(&memoryPool.lock);
            return NULL;
        }
        node->blockSize = size;
        node->block = malloc(size);
        node->next = memoryPool.head;
        memoryPool.head = node;
    }

    memoryPool.currentSize += node->blockSize;

    void *allocatedMemory = node->block;
    node->block = NULL; // Mark as used

    pthread_mutex_unlock(&memoryPool.lock);
    return allocatedMemory;
}

void customFree(void *ptr) {
    pthread_mutex_lock(&memoryPool.lock);

    MemoryPoolNode *node = memoryPool.head;

    while (node && node->block != ptr) {
        node = node->next;
    }

    if (!node) {
        printf("Attempt to free unallocated memory\n");
        pthread_mutex_unlock(&memoryPool.lock);
        return;
    }

    node->block = ptr; // Mark as available
    memoryPool.currentSize -= node->blockSize;

    pthread_mutex_unlock(&memoryPool.lock);
}

