#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <string.h>
#include <time.h>
#include <errno.h>

#define MAX_ELEMENTS 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    pthread_rwlock_t lock;
} NFAPI_CRC_ARRAY_T;

// Utility function to generate a unique RX_UE_INFORMATION_TAG
unsigned int generate_unique_tag(size_t index) {
    return rand() ^ (index << 16);
}

// Function to initialize the array
int nfa_crc_array_init(NFAPI_CRC_ARRAY_T *array, size_t initial_capacity) {
    if (initial_capacity > MAX_ELEMENTS) {
        return -1;
    }
    array->elements = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->elements) {
        return errno; // Memory allocation failed
    }
    array->count = 0;
    pthread_rwlock_init(&array->lock, NULL);
    return 0;
}

// Function to add or update an element in the array based on RNTI
int nfa_crc_array_add_or_update(NFAPI_CRC_ARRAY_T *array, unsigned int rnti, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_rwlock_wrlock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->elements[i].RNTI == rnti) {
            memcpy(&array->elements[i], data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_rwlock_unlock(&array->lock);
            return 0;
        }
    }

    // Add new element
    if (array->count >= MAX_ELEMENTS) {
        pthread_rwlock_unlock(&array->lock);
        return -1; // Array full
    }
    data->RX_UE_INFORMATION_TAG = generate_unique_tag(array->count);
    memcpy(&array->elements[array->count], data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->count++;
    pthread_rwlock_unlock(&array->lock);
    return 0;
}

// Function to validate all structures are initialized
int nfa_crc_array_validate(NFAPI_CRC_ARRAY_T *array) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->elements[i].RX_UE_INFORMATION_TAG == 0 ||
            array->elements[i].RNTI == 0 || 
            array->elements[i].CRC_INDICATION_REL8_TAG == 0) {
            return -1;
        }
    }
    return 0;
}

// Function to export the array to a binary file with optional compression
int nfa_crc_array_export(NFAPI_CRC_ARRAY_T *array, const char *filename, int compression_level) {
    pthread_rwlock_rdlock(&array->lock);
    FILE *file = fopen(filename, "wb");
    if (!file) {
        pthread_rwlock_unlock(&array->lock);
        return errno;
    }

    // Optionally compress data here based on the compression_level

    size_t written = fwrite(array->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->count, file);
    fclose(file);
    pthread_rwlock_unlock(&array->lock);

    return (written == array->count) ? 0 : -1;
}

// Function to import the array from a binary file with optional decompression
int nfa_crc_array_import(NFAPI_CRC_ARRAY_T *array, const char *filename, int compression_level) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        return errno;
    }

    // Optionally decompress data here based on the compression_level

    size_t read_count;
    pthread_rwlock_wrlock(&array->lock);
    fread(array->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_ELEMENTS, file);
    read_count = fread(NULL, 0, 1, file); // To check EOF
    fclose(file);

    if (read_count == 0) {
        array->count = ftell(file) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    } else {
        pthread_rwlock_unlock(&array->lock);
        return -1; // Error reading file
    }

    pthread_rwlock_unlock(&array->lock);
    return 0;
}

// Cleanup function to remove entries based on residency time
void nfa_crc_array_cleanup(NFAPI_CRC_ARRAY_T *array, unsigned int min_residency_time) {
    time_t current_time = time(NULL);

    pthread_rwlock_wrlock(&array->lock);
    for (size_t i = 0; i < array->count;) {
        if ((current_time - array->elements[i].RX_UE_INFORMATION_TAG) >= min_residency_time) {
            memmove(&array->elements[i], &array->elements[i + 1],
                    (--array->count - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        } else {
            ++i;
        }
    }
    pthread_rwlock_unlock(&array->lock);
}

// Function to cleanup resources
void nfa_crc_array_destroy(NFAPI_CRC_ARRAY_T *array) {
    if (array->elements) {
        free(array->elements);
        array->elements = NULL;
    }
    pthread_rwlock_destroy(&array->lock);
}
