    size_t count;
    pthread_rwlock_t lock;
    atomic_bool initialized;
} BufferManager;

// Function prototypes
bool initializeBuffer(BufferManager* manager);
void cleanupBuffer(BufferManager* manager);
bool addElement(BufferManager* manager, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG);
bool isInitialized(BufferManager* manager);

// External logging mechanism (asynchronous)
void logEvent(const char* event) {
    // Simulate asynchronous logging
    printf("LOG: %s\n", event); // Simplified for demonstration purposes
}

BufferManager* createBufferManager() {
    BufferManager* manager = malloc(sizeof(BufferManager));
    if (!manager) {
        logEvent("Memory allocation failed for BufferManager");
        return NULL;
    }

    pthread_rwlock_init(&manager->lock, NULL);
    atomic_store(&manager->initialized, false);
    manager->count = 0;

    // Initialize the dynamically allocated array
    bool success = initializeBuffer(manager);

    if (!success) {
        cleanupBuffer(manager);
        free(manager);
        logEvent("Failed to allocate memory for buffer elements");
        return NULL;
    }

    return manager;
}

bool initializeBuffer(BufferManager* manager) {
    manager->array = calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        logEvent("Memory allocation failed for array");
        return false;
    }
    return true;
}

void cleanupBuffer(BufferManager* manager) {
    free(manager->array);
    pthread_rwlock_destroy(&manager->lock);
    atomic_store(&manager->initialized, false);
}

bool addElement(BufferManager* manager, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG) {
    if (atomic_load(&manager->initialized)) return false;

    pthread_rwlock_wrlock(&manager->lock);

    // Check for unique RX_UE_INFORMATION_TAG
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            pthread_rwlock_unlock(&manager->lock);
            logEvent("Duplicate RX_UE_INFORMATION_TAG detected");
            return false;
        }
    }

    // Add element to buffer
    if (manager->count < MAX_ELEMENTS) {
        NFAPI_CRC_INDICATION_PDU_T* new_elem = &manager->array[manager->count];
        new_elem->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        new_elem->RNTI = RNTI;
        new_elem->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        new_elem->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        manager->count++;
        atomic_store(&manager->initialized, true);

        pthread_rwlock_unlock(&manager->lock);
        logEvent("Element added successfully");
        return true;
    } else {
        pthread_rwlock_unlock(&manager->lock);
        logEvent("Buffer full");
        return false;
    }
}

bool isInitialized(BufferManager* manager) {
    // Lazy initialization check
    if (!atomic_load(&manager->initialized)) {
        pthread_rwlock_rdlock(&manager->lock);

        for (size_t i = 0; i < manager->count; ++i) {
            if (!manager->array[i].RX_UE_INFORMATION_TAG || !manager->array[i].RNTI || !manager->array[i].CRC_INDICATION_REL8_TAG) {
                pthread_rwlock_unlock(&manager->lock);
                logEvent("Buffer contains uninitialized elements");
                return false;
            }
        }

        atomic_store(&manager->initialized, true);
        pthread_rwlock_unlock(&manager->lock);
    }
    return true;
}

// Usage example
int main() {
    BufferManager* manager = createBufferManager();

    if (manager) {
        // Add elements to the buffer
        addElement(manager, 1, 100, 10);  // Example tags
        addElement(manager, 2, 101, 11);

        // Validate initialization
        if (isInitialized(manager)) {
            logEvent("Buffer is initialized and ready for use");
        }

        cleanupBuffer(manager);
        free(manager);
    }

    return 0;
}
