// Function to add a new message.
int addMessage(MessageManager *manager, const NAS_MESSAGE *nas_message, unsigned short rrc_transaction_id) {
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_Ngap_RRC_Message *new_messages = (LTE_Ngap_RRC_Message *)realloc(manager->messages, new_capacity * sizeof(LTE_Ngap_RRC_Message));
