        manager->messages = new_messages;
        manager->capacity = new_capacity;
    }

    LTE_Ngap_RRC_Message *message = &manager->messages[manager->count++];
    message->nas_message = *nas_message;
    message->rrc_transaction_id = rrc_transaction_id;

