    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->messages[i].rrc_transaction_id == rrc_transaction_id) {
            memmove(&manager->messages[i], &manager->messages[i + 1], (manager->count - i - 1) * sizeof(LTE_Ngap_RRC_Message));
            --manager->count;
            return 0; // Success.
        }
    }
