#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char *buffer;
} Record;

typedef struct {
    int offset;
    char *key;
    Record *record;
} DataStruct;

#define MAX_MEMORY_USAGE 1024 * 1024 // Example threshold of 1MB
#define STRING_LITERAL "Sample String"
#define VALUE_RANGE_MIN 0
#define VALUE_RANGE_MAX 100

int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

DataStruct* initialize_data_structs(size_t num_structs, const char *key_str) {
    if (!num_structs || !key_str) return NULL;

    DataStruct *data_structs = malloc(num_structs * sizeof(DataStruct));
    if (!data_structs) return NULL;

    size_t key_length = strlen(key_str);
    size_t total_memory_usage = 0;
    const size_t buffer_size = sizeof(char) * (key_length + 1);

    for (size_t i = 0; i < num_structs; ++i) {
        data_structs[i].offset = generate_random_int(0, 100);

        char *key_copy = malloc(buffer_size);
        if (!key_copy) {
            // Clean up in case of allocation failure
            for (size_t j = 0; j < i; ++j) free(data_structs[j].record->buffer);
            for (size_t j = 0; j <= i; ++j) free(data_structs[j].record);
            free(data_structs);
            return NULL;
        }

        strcpy(key_copy, key_str);
        data_structs[i].key = key_copy;

        size_t record_memory_usage = sizeof(Record) + sizeof(int) + strlen(STRING_LITERAL) + 1;
        if (total_memory_usage + record_memory_usage > MAX_MEMORY_USAGE) {
            free(key_copy);
            for (size_t j = 0; j < i; ++j) free(data_structs[j].key);
            for (size_t j = 0; j <= i; ++j) free(data_structs[j].record->buffer);
            for (size_t j = 0; j <= i; ++j) free(data_structs[j].record);
            free(data_structs);
            return NULL;
        }

        total_memory_usage += record_memory_usage;

        Record *record = malloc(sizeof(Record));
        if (!record) {
            free(key_copy);
            for (size_t j = 0; j < i; ++j) free(data_structs[j].key);
            for (size_t j = 0; j <= i; ++j) free(data_structs[j].record->buffer);
            for (size_t j = 0; j <= i; ++j) free(data_structs[j].record);
            free(data_structs);
            return NULL;
        }

        record->value = generate_random_int(VALUE_RANGE_MIN, VALUE_RANGE_MAX);

        char *buffer = malloc(strlen(STRING_LITERAL) + 1);
        if (!buffer) {
            free(record);
            for (size_t j = 0; j < i; ++j) free(data_structs[j].key);
            for (size_t j = 0; j <= i; ++j) free(data_structs[j].record->buffer);
            for (size_t j = 0; j <= i; ++j) free(data_structs[j].record);
            free(data_structs);
            return NULL;
        }

        strcpy(buffer, STRING_LITERAL);
        record->buffer = buffer;

        data_structs[i].record = record;
    }

    return data_structs;
}

void free_data_structs(DataStruct *data_structs, size_t num_structs) {
    if (!data_structs) return;

    for (size_t i = 0; i < num_structs; ++i) {
        free(data_structs[i].key);
        free(data_structs[i].record->buffer);
        free(data_structs[i].record);
    }

    free(data_structs);
}

int main() {
    srand(time(NULL));

    size_t num_structs = 10;
    DataStruct *data_structs = initialize_data_structs(num_structs, "Key");
    if (!data_structs) {
        fprintf(stderr, "Failed to allocate data structures.\n");
        return EXIT_FAILURE;
    }

    // Use the data_structs...

    free_data_structs(data_structs, num_structs);

    return EXIT_SUCCESS;
}
```']

['Below is an implementation for managing a dynamic array of `NetworkEventLogEntry` structures in C. The implementation considers memory constraints, thread safety, periodic flushing, compression, and configuration flexibility:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef enum {
    EVENT_TYPE_INFO,
    EVENT_TYPE_WARNING,
    EVENT_TYPE_ERROR
} EventType;

typedef struct {
    time_t timestamp;
    EventType event_type;
    char message[256];
} NetworkEventLogEntry;

#define MAX_ENTRIES 10000

typedef struct {
    NetworkEventLogEntry *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    int flush_interval_seconds; // Interval for flushing buffered events
    int compression_threshold_percent; // Threshold to trigger compression
} LogManager;

// Function prototypes
void initialize_log_manager(LogManager *manager, size_t initial_capacity, int flush_interval, int compression_threshold);
void log_event(LogManager *manager, EventType type, const char *message);
void flush_logs(LogManager *manager);
void compress_and_archive_old_entries(LogManager *manager);
void cleanup_log_manager(LogManager *manager);

// Initialize the LogManager
void initialize_log_manager(LogManager *manager, size_t initial_capacity, int flush_interval, int compression_threshold) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->entries = (NetworkEventLogEntry *)malloc(initial_capacity * sizeof(NetworkEventLogEntry));
    if (!manager->entries) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->flush_interval_seconds = flush_interval;
    manager->compression_threshold_percent = compression_threshold;

    pthread_t flush_thread;
    pthread_create(&flush_thread, NULL, (void *(*)(void *))[](void *arg) -> void* {
        LogManager *manager = (LogManager *)arg;
        while (1) {
            sleep(manager->flush_interval_seconds);
            pthread_mutex_lock(&manager->lock);
            flush_logs(manager);
            compress_and_archive_old_entries(manager);
            pthread_mutex_unlock(&manager->lock);
        }
        return NULL;
    }, manager);

    pthread_detach(flush_thread);
}

// Log a new event
void log_event(LogManager *manager, EventType type, const char *message) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > MAX_ENTRIES) {
            fprintf(stderr, "Log capacity exceeded. Cannot log more events.\n");
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        NetworkEventLogEntry *new_entries = (NetworkEventLogEntry *)realloc(manager->entries, new_capacity * sizeof(NetworkEventLogEntry));
        if (!new_entries) {
            perror("Failed to reallocate memory for logs");
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        manager->entries = new_entries;
        manager->capacity = new_capacity;
    }

    NetworkEventLogEntry entry;
    time(&entry.timestamp);
    entry.event_type = type;
    strncpy(entry.message, message, sizeof(entry.message) - 1);
    manager->entries[manager->count++] = entry;

    pthread_mutex_unlock(&manager->lock);
}

// Flush logs to disk or a persistent store
void flush_logs(LogManager *manager) {
    // Placeholder for actual flushing logic
    printf("Flushing %zu log entries...\n", manager->count);
    // Reset the count after flushing
    manager->count = 0;
}

// Compress and archive old entries
void compress_and_archive_old_entries(LogManager *manager) {
    size_t threshold = (manager->capacity * manager->compression_threshold_percent) / 100;
    if (manager->count > threshold) {
        printf("Compressing and archiving log entries...\n");
        // Placeholder for actual compression logic
        manager->count = threshold; // Simulate freeing up space by keeping only a portion of the logs
    }
}

// Cleanup resources used by LogManager
void cleanup_log_manager(LogManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->entries);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
```

### Key Points:
- **Thread Safety**: Mutexes are used to protect shared resources.
- **Dynamic Memory Management**: `malloc` and `realloc` manage dynamic memory for the log entries, with careful handling of potential allocation failures.
- **Periodic Flushing & Compression**: A detached thread periodically flushes logs and compresses old entries based on configurable thresholds.
- **Error Handling**: The code gracefully handles out-of-memory situations without crashing the application.

This setup is designed to be flexible and robust, accommodating different deployment scenarios through configurable parameters.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ARRAY_SIZE 1024
#define SECONDARY_POOL_SIZE 100
#define BATCH_LIMIT 512

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array[MAX_ARRAY_SIZE];
    int array_size;
    int sum_RNTIs;
    int error_flag; // 0: no error, 1: allocation failed
} LogStruct;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static int secondary_pool[SECONDARY_POOL_SIZE] = {0};

int allocate_secondary(int retries) {
    for (int i = 0; i < SECONDARY_POOL_SIZE && retries > 0; ++i) {
        if (secondary_pool[i] == 0) {
            secondary_pool[i] = 1;
            return 1;
        }
        --retries;
    }
    return 0;
}

void release_secondary(int index) {
    if (index >= 0 && index < SECONDARY_POOL_SIZE) {
        secondary_pool[index] = 0;
    }
}

NFAPI_CRC_INDICATION_PDU_T** populate_arrays(int num_batches, LogStruct *log) {
    NFAPI_CRC_INDICATION_PDU_T **all_arrays = malloc(num_batches * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!all_arrays) {
        log->error_flag = 1;
        return NULL;
    }

    pthread_mutex_lock(&lock);

    for (int batch = 0; batch < num_batches && batch < BATCH_LIMIT; ++batch) {
        int array_size = rand() % MAX_ARRAY_SIZE + 1; // Random size, ensuring it doesn't exceed constraints
