['Below is a C implementation that manages a dynamic pool of `NFAPI_CRC_INDICATION_PDU_T` structures, ensuring thread-safe allocation and deallocation with minimal contention:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRUCTURES 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T structures[MAX_STRUCTURES];
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    int available_count;
    int active_structures[MAX_STRUCTURES];
} PoolManager;

PoolManager pool_manager = { .available_count = MAX_STRUCTURES, .lock = PTHREAD_MUTEX_INITIALIZER, .cond_var = PTHREAD_COND_INITIALIZER };

int allocate_structure() {
    pthread_mutex_lock(&pool_manager.lock);

    while (pool_manager.available_count == 0) {
        pthread_cond_wait(&pool_manager.cond_var, &pool_manager.lock);
    }

    int index = -1;
    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        if (pool_manager.active_structures[i] == 0) {
            pool_manager.active_structures[i] = 1;
            pool_manager.available_count--;
            index = i;
            break;
        }
    }

    pthread_mutex_unlock(&pool_manager.lock);

    if (index != -1) {
        // Initialize with unique identifiers
        pool_manager.structures[index].RX_UE_INFORMATION_TAG = rand() % 1000 + 1; // Example range
        pool_manager.structures[index].RNTI = rand() % 1000 + 1;
        pool_manager.structures[index].CRC_INDICATION_REL8_TAG = rand() % 1000 + 1;

        return index;
    }

    return -1;
}

void free_structure(int index) {
    if (index < 0 || index >= MAX_STRUCTURES) return;

    pthread_mutex_lock(&pool_manager.lock);

    pool_manager.active_structures[index] = 0;
    pool_manager.available_count++;

    pthread_cond_signal(&pool_manager.cond_var);

    pthread_mutex_unlock(&pool_manager.lock);
}

void free_all_resources() {
    pthread_mutex_lock(&pool_manager.lock);

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        if (pool_manager.active_structures[i] == 1) {
            pool_manager.active_structures[i] = 0;
            pool_manager.available_count++;
        }
    }

    pthread_mutex_unlock(&pool_manager.lock);
}

int main() {
    // Example usage
    int index = allocate_structure();
    if (index != -1) {
        printf("Allocated structure at index %d\n", index);
        free_structure(index);
        printf("Freed structure at index %d\n", index);
    } else {
        printf("Failed to allocate structure.\n");
    }

    free_all_resources();

    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex` and `pthread_cond` for synchronization.
- **Efficient Allocation/Deallocation**: Minimizes contention by using a condition variable to wait when no structures are available.
- **Unique Identifiers**: Randomly generated within a range for demonstration purposes.
- **Resource Management**: `free_all_resources()` resets the pool, allowing all resources to be reused.']

