#define INITIAL_CAPACITY 10000
#define RESIZE_THRESHOLD 5000

typedef struct {
    uint32_t provided_crc;
    uint32_t data[];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CRCArrayManager;

// Function prototypes
void initialize_manager(CRCArrayManager *manager);
void destroy_manager(CRCArrayManager *manager);
int add_pdu(CRCArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T pdu);
int verify_crc(const NFAPI_CRC_INDICATION_PDU_T *pdu, uint32_t computed_crc);

// Initialize the manager
void initialize_manager(CRCArrayManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->array = malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Destroy the manager and free resources
void destroy_manager(CRCArrayManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->array);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Add a PDU to the array, resizing if necessary
int add_pdu(CRCArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&manager->lock);

    // Resize array if needed
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    memcpy(manager->array + manager->count, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) + sizeof(uint32_t) * (sizeof(pdu.data) / sizeof(uint32_t)));
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Verify CRC for each PDU in the array
void verify_pdus(CRCArrayManager *manager, uint32_t (*compute_crc_func)(const uint32_t *)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = manager->array + i;
        uint32_t computed_crc = compute_crc_func(pdu->data);

        if (computed_crc != pdu->provided_crc) {
            fprintf(stderr, "Error: CRC mismatch for PDU at index %zu\n", i);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

