#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_UES 256

typedef enum { ESTABLISHMENT, RECONFIGURATION, RELEASE } LTE_RRC_UE_EVENT_T;

typedef struct {
    int UE_ID;
    int CELL_ID;
    LTE_RRC_UE_EVENT_T event_sequence[10];
    int event_count;
} LTE_RRC_UE_CONTEXT_T;

typedef struct {
    LTE_RRC_UE_CONTEXT_T contexts[MAX_UES];
    int active_contexts;
    pthread_mutex_t lock;
} ContextManager;

ContextManager context_manager = { .active_contexts = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

int add_ue_context(int ue_id, int cell_id) {
    pthread_mutex_lock(&context_manager.lock);

    if (context_manager.active_contexts >= MAX_UES) {
        pthread_mutex_unlock(&context_manager.lock);
        return -1; // No available slots
    }

    for (int i = 0; i < context_manager.active_contexts; ++i) {
        if (context_manager.contexts[i].UE_ID == ue_id || context_manager.contexts[i].CELL_ID == cell_id) {
            pthread_mutex_unlock(&context_manager.lock);
            return -1; // UE_ID or CELL_ID already exists
        }
    }

    int index = context_manager.active_contexts++;
    context_manager.contexts[index].UE_ID = ue_id;
    context_manager.contexts[index].CELL_ID = cell_id;
    context_manager.contexts[index].event_count = 0;

    pthread_mutex_unlock(&context_manager.lock);
    return index; // Return the index of the newly added context
}

void remove_ue_context(int index) {
    if (index < 0 || index >= context_manager.active_contexts) {
        return;
    }

    pthread_mutex_lock(&context_manager.lock);

    for (int i = index; i < context_manager.active_contexts - 1; ++i) {
        context_manager.contexts[i] = context_manager.contexts[i + 1];
    }
    context_manager.active_contexts--;

    pthread_mutex_unlock(&context_manager.lock);
}

void add_ue_event(int ue_index, LTE_RRC_UE_EVENT_T event) {
    if (ue_index < 0 || ue_index >= context_manager.active_contexts) {
        return;
    }

    pthread_mutex_lock(&context_manager.lock);

    int index = ue_index;
    if (context_manager.contexts[index].event_count < 10) {
        context_manager.contexts[index].event_sequence[context_manager.contexts[index].event_count++] = event;
    }

    pthread_mutex_unlock(&context_manager.lock);
}

void free_all_resources() {
    pthread_mutex_lock(&context_manager.lock);

    // No need to deallocate memory since we are using a fixed-size array
    context_manager.active_contexts = 0;

    pthread_mutex_unlock(&context_manager.lock);
}
