        log_error("Validation failed.");
    }

    // Export to CSV
    export_to_csv(*arr, count, "stats_output.csv");

    free(*arr);
    return NULL;
}

int validate_stats(const LTE_ENB_STATS_T* stats, size_t count, double snr_min, double snr_max, double avg_fer_threshold) {
    double cumulative_snr = 0.0;
    double cumulative_fer = 0.0;

    for (size_t i = 0; i < count; ++i) {
        cumulative_snr += stats[i].phyLayerStats.SNR;
        cumulative_fer += stats[i].phyLayerStats.FER;
    }

    if (cumulative_snr / count < snr_min || cumulative_snr / count > snr_max) {
        return 0; // Validation failed
    }
    if (cumulative_fer / count > avg_fer_threshold) {
        return 0; // Validation failed
    }

    return 1; // Validation passed
}

void log_error(const char* message) {
