}

void export_to_csv(const LTE_ENB_STATS_T* stats, size_t count, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        log_error("Failed to open CSV file.");
        return;
    }

    fprintf(file, "ENB_ID,CELL_ID,SNR,BER,FER\n");
    for (size_t i = 0; i < count; ++i) {
        const LTE_ENB_STATS_T* stat = &stats[i];
        fprintf(file, "%d,%d,%.2f,%.5f,%.5f\n",
                stat->ENB_ID,
                stat->CELL_ID,
                stat->phyLayerStats.SNR,
                stat->phyLayerStats.BER,
                stat->phyLayerStats.FER);
    }

    fclose(file);
}
