        if (!File.Exists(xmlFilePath))
            throw new FileNotFoundException("The specified XML file was not found.");

        _xmlContent = File.ReadAllText(xmlFilePath);
        _cache = cache;
    }

    public List<T> GetElementsPage(
        string elementName,
        int pageNumber,
        int pageSize = DefaultPageSize,
        string primarySortAttribute = null,
        string fallbackSortAttribute = null)
    {
        if (pageNumber <= 0 || pageSize <= 0)
            throw new ArgumentOutOfRangeException("Page number and page size must be positive integers.");

        try
        {
            var cacheKey = $"Elements_{elementName}_Page_{pageNumber}_Size_{pageSize}_Sort_{primarySortAttribute}_{fallbackSortAttribute}";
            if (!_cache.TryGetValue(cacheKey, out List<T> result))
            {
                using (var reader = XmlReader.Create(new StringReader(_xmlContent)))
                {
                    XPathDocument document = new XPathDocument(reader);
                    XPathNavigator navigator = document.CreateNavigator();

                    var query = $"//{elementName}";
                    XPathNodeIterator nodes = navigator.Select(query);

                    List<T> elements = new List<T>();

                    while (nodes.MoveNext())
                    {
                        T element = (T)nodes.Current.Evaluate("string(.)"); // Assumes T can be parsed from string
                        if (element != null)
                            elements.Add(element);
                    }

                    var sortedElements = SortElements(elements, primarySortAttribute, fallbackSortAttribute);

                    result = Paginate(sortedElements, pageNumber, pageSize).ToList();
                }

                _cache.Set(cacheKey, result, TimeSpan.FromMinutes(5)); // Cache for 5 minutes
            }

            return result;
        }
        catch (XPathException)
        {
            throw new InvalidOperationException("There was an error parsing the XML document.");
        }
    }

    private IEnumerable<T> SortElements(List<T> elements, string primarySortAttribute, string fallbackSortAttribute)
    {
        if (primarySortAttribute != null && elements.Any())
        {
            var sorted = elements
                .OrderBy(e => e.GetType().GetProperty(primarySortAttribute)?.GetValue(e, null) ?? "")
                .ToList();

            if (!sorted.Any(e => e.GetType().GetProperty(primarySortAttribute)?.GetValue(e, null) is string))
            {
                sorted = elements
                    .OrderByDescending(e => e.GetType().GetProperty(fallbackSortAttribute)?.GetValue(e, null) ?? "")
                    .ToList();
            }

            return sorted;
        }

        if (fallbackSortAttribute != null && elements.Any())
        {
            return elements.OrderByDescending(e => e.GetType().GetProperty(fallbackSortAttribute)?.GetValue(e, null) ?? "").ToList();
        }

        return elements;
    }

    private IEnumerable<T> Paginate(IEnumerable<T> sortedElements, int pageNumber, int pageSize)
    {
        return sortedElements
            .Skip((pageNumber - 1) * pageSize)
            .Take(pageSize);
    }
}
