const fetch = require('node-fetch');

// List of Old and New Testament books with common variations
const bibleBooks = {
    genesis: ["genesis", "gen"],
    exodus: ["exodus", "exod"],
    leviticus: ["leviticus", "lev"],
    numbers: ["numbers", "num"],
    deuteronomy: ["deuteronomy", "deut"],
    // ... add all other books similarly
    matthew: ["matthew", "matt"],
    mark: ["mark", "mar"],
    luke: ["luke", "luk"],
    john: ["john"],
    acts: ["acts"],
    romans: ["romans", "rom"],
    // ... add all other New Testament books similarly
};

// Function to fetch additional metadata (simulated here)
async function fetchBookMetadata() {
    try {
        const response = await fetch('https://api.example.com/bible-metadata');
        if (!response.ok) throw new Error("Network response was not ok");
        return response.json();
    } catch (error) {
        console.error("Failed to fetch metadata:", error);
        // Return fallback data or empty object
        return {};
    }
}

// Function to normalize input text and match against book names
function processText(documentText) {
    const wordPattern = /\b(\w+)\b/g;
    let matches = {};

    // Fetch additional metadata if needed (for future scalability)
    const metadata = fetchBookMetadata().then(data => data);

    for (const [canonicalName, variations] of Object.entries(bibleBooks)) {
        variations.push(canonicalName);  // Include canonical name in variations
    }

    let match;
    while ((match = wordPattern.exec(documentText.toLowerCase()))) {
        const word = match[1];

        for (const [canonicalName, variations] of Object.entries(bibleBooks)) {
            if (variations.includes(word) || metadata.then(data => data.some(v => v.includes(word)))) {
                matches[canonicalName] = (matches[canonicalName] || 0) + 1;
            }
        }
    }

    return matches;
}

// Main function to process a large text document
async function identifyBookReferences(documentText) {
    try {
        // Process the text and get book reference counts
        const bookCounts = await Promise.resolve(processText(documentText));

        return bookCounts;
    } catch (error) {
        console.error("Error processing document:", error);
        return {};
    }
}

module.exports = { identifyBookReferences };
