// JavaScript module to dynamically load and execute multiple JS files as plugins

(function() {
    const pluginRegistry = new Map();
    const executionQueue = [];
    let activeLoads = 0;

    function simulateNetworkDelay(callback) {
        const delay = Math.random() * 1000; // Simulate network delay
        setTimeout(callback, delay);
    }

    async function validateFileIntegrity(fileUrl, expectedHash) {
        // Mock hash validation for the file
        return new Promise((resolve) => {
            simulateNetworkDelay(() => resolve(true)); // Assume always valid for simulation
        });
    }

    function loadPlugin(pluginInfo) {
        return new Promise((resolve, reject) => {
            const { url, expectedHash, dependencies } = pluginInfo;

            if (pluginRegistry.has(url)) {
                resolve();
                return;
            }

            activeLoads++;
            simulateNetworkDelay(async () => {
                try {
                    const isValid = await validateFileIntegrity(url, expectedHash);

                    if (!isValid) throw new Error('File integrity check failed');

                    fetch(url)
                        .then(response => response.text())
                        .then(scriptContent => {
                            const scriptElement = document.createElement('script');
                            scriptElement.textContent = scriptContent;
                            document.head.appendChild(scriptElement);

                            pluginRegistry.set(url, { status: 'loaded' });
                            resolve();
                        })
                        .catch(error => {
                            console.error(`Error loading ${url}:`, error);
                            pluginRegistry.set(url, { status: 'error', error });
                            reject(error);
                        });

                    activeLoads--;
                } catch (error) {
                    console.error(`Integrity check failed for ${url}:`, error);
                    pluginRegistry.set(url, { status: 'error', error });
                    activeLoads--;
                    reject(error);
                }
            });
        });
    }

    function executePlugins() {
        const results = { success: [], failure: [] };

        while (executionQueue.length > 0) {
            const pluginInfo = executionQueue.shift();
            const { url } = pluginInfo;

            if (pluginRegistry.get(url).status !== 'loaded') continue; // Skip if not loaded or already executed

            try {
                const scriptContent = pluginRegistry.get(url).content;
                eval(scriptContent);
                results.success.push(url);
            } catch (error) {
                console.error(`Error executing ${url}:`, error);
                results.failure.push({ url, error });
            }
        }

        return results;
    }

    function loadAndExecutePlugins(pluginList) {
        const pluginLoadPromises = [];

        // First pass: load all plugins
        pluginList.forEach((pluginInfo, index) => {
            if (!pluginInfo.dependencies || pluginInfo.dependencies.every(depUrl => 
                pluginRegistry.has(depUrl) && pluginRegistry.get(depUrl).status === 'loaded')) {

                executionQueue.push(pluginInfo);
                const promise = loadPlugin(pluginInfo)
                    .then(() => {
                        // Add to registry with content for later execution
                        const scriptContent = document.querySelector(`script[src="${pluginInfo.url}"]`).textContent;
                        pluginRegistry.set(pluginInfo.url, { status: 'loaded', content: scriptContent });
                    })
                    .catch(error => console.error(`Failed loading ${pluginInfo.url}:`, error));

                pluginLoadPromises.push(promise);
            }
        });

        return Promise.all(pluginLoadPromises).then(() => executePlugins());
    }

    // Example usage
    const plugins = [
        { url: 'https://example.com/plugin1.js', expectedHash: 'hash1', dependencies: [] },
        { url: 'https://example.com/plugin2.js', expectedHash: 'hash2', dependencies: ['plugin1.js'] }
    ];

    loadAndExecutePlugins(plugins).then(results => {
        console.log('Loading and execution results:', results);
    });

})();
