<?php

use GuzzleHttp\Client;
use GuzzleHttp\Exception\RequestException;
use Psr\Log\LoggerInterface;

class OAuth2Authenticator {
    private $httpClient;
    private $logger;
    private $clientId;
    private $clientSecret;
    private $tokenUrl;
    private $userInfoUrl;
    private $cache;
    private $rateLimitStore;

    public function __construct(
        Client $httpClient,
        LoggerInterface $logger,
        string $clientId,
        string $clientSecret,
        string $tokenUrl,
        string $userInfoUrl,
        CacheInterface $cache, // Assume a PSR-16 compatible cache
        RateLimitStoreInterface $rateLimitStore // Custom rate limit store interface
    ) {
        $this->httpClient = $httpClient;
        $this->logger = $logger;
        $this->clientId = $clientId;
        $this->clientSecret = $clientSecret;
        $this->tokenUrl = $tokenUrl;
        $this->userInfoUrl = $userInfoUrl;
        $this->cache = $cache;
        $this->rateLimitStore = $rateLimitStore;
    }

    public function authenticate(string $authorizationCode): ?array {
        try {
            if (!$this->checkRateLimit('authenticate')) {
                return null;
            }

            // Exchange authorization code for access token
            $tokenResponse = $this->exchangeAuthorizationCode($authorizationCode);
            $accessToken = $tokenResponse['access_token'] ?? '';

            // Save session data in Redis or similar storage
            $sessionId = bin2hex(random_bytes(16));
            $sessionData = [
                'access_token' => $accessToken,
                'expires_at' => time() + ($tokenResponse['expires_in'] ?? 3600),
                'refresh_token' => $tokenResponse['refresh_token'] ?? '',
            ];
            $this->cache->set("session:$sessionId", $sessionData, $tokenResponse['expires_in'] ?? 3600);

            return ['sessionId' => $sessionId];
        } catch (Exception $e) {
            $this->logger->error('Authentication failed: ' . $e->getMessage());
            return null;
        }
    }

    public function getUserInfo(string $sessionId): ?array {
        try {
            if (!$this->checkRateLimit('getUserInfo')) {
                return null;
            }

            $sessionData = $this->cache->get("session:$sessionId");
            if ($sessionData === null) {
                $this->logger->warning("Session not found: $sessionId");
                return null;
            }

            // Check for token expiration
            if (time() >= $sessionData['expires_at']) {
                $refreshed = $this->refreshAccessToken($sessionData);
                if (!$refreshed) {
                    $this->logger->error('Token refresh failed');
                    return null;
                }
            }

            // Retrieve user info from cache or API
            $userInfo = $this->cache->get("userinfo:$sessionId");
            if ($userInfo === null) {
                $userInfo = $this->fetchUserInfo($sessionData['access_token']);
                if ($userInfo !== false) {
                    $this->cache->set("userinfo:$sessionId", $userInfo, 3600);
                } else {
                    return null;
                }
            }

            return $userInfo;
        } catch (Exception $e) {
            $this->logger->error('Failed to get user info: ' . $e->getMessage());
            return null;
        }
    }

    private function exchangeAuthorizationCode(string $authorizationCode): array {
        try {
            $response = $this->httpClient->post($this->tokenUrl, [
                'form_params' => [
                    'grant_type' => 'authorization_code',
                    'code' => $authorizationCode,
                    'client_id' => $this->clientId,
                    'client_secret' => $this->clientSecret,
                ],
            ]);

            return json_decode((string) $response->getBody(), true);
        } catch (RequestException $e) {
            throw new Exception('Failed to exchange authorization code: ' . $e->getMessage());
        }
    }

    private function refreshAccessToken(array $sessionData): bool {
        try {
            $response = $this->httpClient->post($this->tokenUrl, [
                'form_params' => [
                    'grant_type' => 'refresh_token',
                    'refresh_token' => $sessionData['refresh_token'],
                    'client_id' => $this->clientId,
                    'client_secret' => $this->clientSecret,
                ],
            ]);

            $newTokenData = json_decode((string) $response->getBody(), true);

            // Update session with new token data
            $sessionData['access_token'] = $newTokenData['access_token'];
            $sessionData['expires_at'] = time() + ($newTokenData['expires_in'] ?? 3600);
            $sessionData['refresh_token'] = $newTokenData['refresh_token'] ?? '';

            $this->cache->set("session:" . $sessionData['sessionId'], $sessionData, $newTokenData['expires_in'] ?? 3600);

            return true;
        } catch (RequestException $e) {
            throw new Exception('Failed to refresh access token: ' . $e->getMessage());
        }
    }

    private function fetchUserInfo(string $accessToken): ?array {
        try {
            $response = $this->httpClient->get($this->userInfoUrl, [
                'headers' => ['Authorization' => "Bearer $accessToken"],
            ]);

            return json_decode((string) $response->getBody(), true);
        } catch (RequestException $e) {
            if ($e->getCode() == 401) { // Unauthorized due to expired token
                return false;
            }
            throw new Exception('Failed to fetch user info: ' . $e->getMessage());
        }
    }

    private function checkRateLimit(string $action): bool {
        $key = "rate_limit:$action";
        if ($this->rateLimitStore->isAllowed($key)) {
            $this->rateLimitStore->increment($key);
            return true;
        }
        $this->logger->warning("Rate limit exceeded for action: $action");
        return false;
    }
}

// Interfaces that would be implemented elsewhere
interface CacheInterface {
    public function get(string $key);
    public function set(string $key, $value, int $ttl = 0);
}

interface RateLimitStoreInterface {
    public function isAllowed(string $key): bool;
    public function increment(string $key);
}
```

