#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_ARRAY_SIZE 1000000 // Define a suitable maximum size for your use case

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    struct {
        uint8_t CRCFLAG;
        uint8_t CRC_INDICATION_REL8_TAG;
    } crc_info;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t current_size;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} DynamicArray;

DynamicArray* initialize_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->head = NULL;
    array->current_size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void free_dynamic_array(DynamicArray* array) {
    Node* current = array->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_to_array(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!array || array->current_size >= MAX_ARRAY_SIZE) return -1;

    Node** ptr = &(array->head);
    while (*ptr) {
        ptr = &((*ptr)->next);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1; // Memory allocation failure

    new_node->data = data;
    new_node->next = NULL;

    *ptr = new_node;
    array->current_size++;

    return 0;
}

void generate_random_crc(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        pdu->RX_UE_INFORMATION_TAG = rand(); // Generate random values
        pdu->RNTI = rand();
        pdu->crc_info.CRCFLAG = rand() % 256;
