#define MAX_NODES 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[16];
    int checksum_validation_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
    int verbose_logging;
} LinkedList;

LinkedList* create_linked_list(int verbose) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->verbose_logging = verbose;

    return list;
}

void free_linked_list(LinkedList* list);

NFAPI_CRC_INDICATION_PDU_T generate_pdu(unsigned int tag, unsigned int rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = tag;
    pdu.RNTI = rnti;

    // Generate CRC_INDICATION_REL8_TAG
    for (int i = 0; i < sizeof(pdu.CRC_INDICATION_REL8_TAG); ++i) {
        pdu.CRC_INDICATION_REL8_TAG[i] = rand() % 256;
    }

    pdu.checksum_validation_flag = (rand() % 2) ? 1 : 0;

    return pdu;
}

int add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= MAX_NODES) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2;

    new_node->data = data;
    new_node->next = NULL;
    new_node->prev = list->tail;

    pthread_mutex_lock(&list->lock);
    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    if (list->verbose_logging) {
        printf("Added Node: RX_UE_INFORMATION_TAG=%u, RNTI=%u\n", data.RX_UE_INFORMATION_TAG, data.RNTI);
    }

    return 0;
}

void print_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        printf("Node: RX_UE_INFORMATION_TAG=%u, RNTI=%u, Checksum Validation Flag=%d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.checksum_validation_flag);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Asynchronous data processing and external integration would require additional setup,
// including thread management, condition variables, etc.

void cleanup_old_entries(LinkedList* list) {
    // Implement a mechanism to clean up old entries
    pthread_mutex_lock(&list->lock);

    while (list->size > 0 && /* some condition to identify old entries */) {
        Node* temp = list->head;
        if (temp) {
            list->head = list->head->next;
            if (list->head) {
                list->head->prev = NULL;
            } else {
                list->tail = NULL;
            }
            free(temp);
            list->size--;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Usage example
int main() {
    LinkedList* list = create_linked_list(1);

    for (unsigned int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_pdu(i, rand());
        add_node(list, pdu);
    }

    print_linked_list(list);
    cleanup_old_entries(list);

    free_linked_list(list);
    return 0;
}
```

