    packetList->packets = (NetworkPacket **)calloc(initialCapacity, sizeof(NetworkPacket *));
    if (!packetList->packets) return false;

    packetList->packetCount = 0;
    packetList->capacity = initialCapacity;

    srand(time(NULL));

    // Example of generating a single packet
    for (size_t i = 0; i < initialCapacity; ++i) {
        NetworkPacket *packet = (NetworkPacket *)malloc(sizeof(NetworkPacket));
        if (!packet) {
            // Handle memory allocation failure gracefully
            while (--i >= 0) free(packetList->packets[i]);
            free(packetList->packets);
            return false;
        }

        packet->header.RX_UE_INFORMATION_TAG = rand();
        packet->header.RNTI = rand();
        packet->header.CRC_INDICATION_REL8_TAG = rand();
        packet->header.CRCFLAG = rand() % 2;

        snprintf(packet->metadata.flowIdentifier, sizeof(packet->metadata.flowIdentifier), "Flow_%zu", i);

        // Example IP addresses; replace with actual logic for setting IPs
        strcpy(packet->metadata.sourceIP, "192.168.1.1"); 
        strcpy(packet->metadata.destinationIP, "192.168.1.2");
        packet->metadata.timestamp = time(NULL);
        packet->metadata.FlowSequenceNumber = i;

        if (packetList->packetCount >= packetList->capacity) {
            size_t newCapacity = packetList->capacity * 2;
            NetworkPacket **newPackets = (NetworkPacket **)realloc(packetList->packets, newCapacity * sizeof(NetworkPacket *));
            if (!newPackets) {
                free(packet);
                while (--i >= 0) free(packetList->packets[i]);
                free(packetList->packets);
                return false;
            }
            packetList->packets = newPackets;
            packetList->capacity = newCapacity;
        }

        packetList->packets[packetList->packetCount++] = packet;
    }

    // Additional configuration logic for rate limiting and traffic prioritization
    // goes here...

    return true; // Successfully initialized
}

void cleanup_packet_list(PacketList *packetList) {
    if (packetList && packetList->packets) {
        for (size_t i = 0; i < packetList->packetCount; ++i) {
            free(packetList->packets[i]);
        }
        free(packetList->packets);
        packetList->packets = NULL;
        packetList->packetCount = 0;
        packetList->capacity = 0;
    }
}

int main() {
    NetworkConfig config = { .mtuSize = 1500, .supportIPv4 = true, .supportIPv6 = false };
    PacketList packetList;

    if (initialize_network_processor(&packetList, config)) {
        printf("Network processor initialized with %zu packets.\n", packetList.packetCount);
    } else {
        fprintf(stderr, "Failed to initialize network processor.\n");
    }

    cleanup_packet_list(&packetList);

    return 0;
}
