    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->node_count = 0;
    return list;
}

// Free the doubly-linked list and all its nodes
void free_list(NFAPI_CRC_LIST_T* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a new node to the list
int add_node(NFAPI_CRC_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;
    memcpy(&new_node->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = list->tail = new_node;
        new_node->prev = new_node->next = NULL;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        new_node->next = NULL;
        list->tail = new_node;
    }
    ++list->node_count;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Remove a node from the list by RNTI
int remove_node(NFAPI_CRC_LIST_T* list, uint16_t RNTI) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current && current->data.RNTI != RNTI) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (current == list->head) {
        list->head = current->next;
        if (list->head) list->head->prev = NULL;
    } else {
        current->prev->next = current->next;
    }

    if (current == list->tail) {
        list->tail = current->prev;
        if (list->tail) list->tail->next = NULL;
    } else {
        current->next->prev = current->prev;
    }

    free(current);
    --list->node_count;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Find a node by RNTI
Node* find_node(NFAPI_CRC_LIST_T* list, uint16_t RNTI) {
    if (!list) return NULL;

    Node* current = list->head;
    while (current && current->data.RNTI != RNTI) {
        current = current->next;
    }
    return current;
}

// Periodic garbage collection to remove unused nodes
void garbage_collect(NFAPI_CRC_LIST_T* list) {
    // Implementation-specific logic for identifying "unused" nodes
    // For example, nodes that have not been accessed within a certain timeframe

