typedef struct {
    unsigned long Timestamp;
    char Source_IP[16];
    char Destination_IP[16];
    int Packet_Size;
} LTE_Packet_Stats;

int is_ip_in_range(const char *ip, const char *range) {
    struct in_addr ip_addr, range_start, range_end;

    if (inet_aton(ip, &ip_addr) == 0 || inet_aton(range, &range_start) == 0)
        return 0;

    // Assuming range is given as "192.168.1.0/24"
    char *slash_pos = strchr(range, '/');
    int prefix_length = slash_pos ? atoi(slash_pos + 1) : 32;

    unsigned long start_mask = ~(~(unsigned long)0 << prefix_length);
    unsigned long end_mask = (1UL << (32 - prefix_length)) - 1;

    range_end.s_addr = range_start.s_addr & start_mask | end_mask;

    return ip_addr.s_addr >= range_start.s_addr && ip_addr.s_addr <= range_end.s_addr;
}

LTE_Packet_Stats* generate_LTE_Packet_Stats(int max_size, int *success_count) {
    LTE_Packet_Stats *packet_stats = (LTE_Packet_Stats*)malloc(max_size * sizeof(LTE_Packet_Stats));
    if (!packet_stats) return NULL;

    int count = 0;
    int invalid_entries = 0;

