    for (int i = 0; i < max_size; ++i) {
        LTE_Packet_Stats stats;

        // Populate with dummy data, replace this logic as per real requirements.
        stats.Timestamp = i; 
        snprintf(stats.Source_IP, sizeof(stats.Source_IP), "192.168.1.%d", rand() % 256);
        snprintf(stats.Destination_IP, sizeof(stats.Destination_IP), "192.168.1.%d", rand() % 256);
        stats.Packet_Size = rand() % 1500 + 40; // Typical packet size range

        if (is_ip_in_range(stats.Source_IP, ip_range) && is_ip_in_range(stats.Destination_IP, ip_range)) {
            packet_stats[count++] = stats;
        } else {
            invalid_entries++;
            fprintf(stderr, "Invalid IP detected: %s -> %s\n", stats.Source_IP, stats.Destination_IP);
        }

        // Simulate varying network conditions
        if (rand() % 10 == 0) {
            usleep(10000); // simulate delay under certain network conditions
        }
    }

    *success_count = count;
    printf("Total entries successfully created: %d\n", count);
    printf("Invalid IP entries skipped: %d\n", invalid_entries);

    return packet_stats;
}

int main() {
