#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long long timestamp; // Using a high-resolution clock time
} RX_UE_INFORMATION_TAG_T;

typedef struct {
    uint16_t RNTI;
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T rx_ue_information_tag;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // For thread safety
} DynamicArray;

void init_dynamic_array(DynamicArray *da) {
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    da->capacity = INITIAL_CAPACITY;
    da->size = 0;
    pthread_mutex_init(&da->lock, NULL);
}

void free_dynamic_array(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->lock);
}

void resize_dynamic_array_if_needed(DynamicArray *da) {
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
}

void initialize_ues(DynamicArray *da, size_t n) {
    pthread_mutex_lock(&da->lock);

    resize_dynamic_array_if_needed(da);

    for (size_t i = 0; i < n; ++i) {
        da->array[da->size].rx_ue_information_tag.RX_UE_INFORMATION_TAG = rand() % 10000;
        da->array[da->size].rx_ue_information_tag.timestamp = time(NULL);

        da->array[da->size].crc_indication_rel8_tag.RNTI = rand() % 65536; // Example RNTI range
        da->array[da->size].crc_indication_rel8_tag.CRCFLAG = rand() % 2;

        da->size++;
    }

    pthread_mutex_unlock(&da->lock);
}

void update_crcflag_for_rnti(DynamicArray *da, uint16_t rnti, int condition) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].crc_indication_rel8_tag.RNTI == rnti && condition) {
            da->array[i].crc_indication_rel8_tag.CRCFLAG = !da->array[i].crc_indication_rel8_tag.CRCFLAG;
        }
    }

    pthread_mutex_unlock(&da->lock);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    DynamicArray da;
    init_dynamic_array(&da);

    initialize_ues(&da, 15); // Initialize with more than initial capacity to test resizing

    update_crcflag_for_rnti(&da, 1234, 1); // Example RNTI and condition

    free_dynamic_array(&da);
    return 0;
}
```

### Key Points:
- **Memory Management**: Uses `malloc` and `realloc` for dynamic memory management. Handles out-of-memory errors by exiting the program.
- **Concurrency**: Protects shared resources with a mutex (`pthread_mutex_t`) to ensure thread safety.
- **Logging**: Logs errors using standard error output.
- **Performance & Scalability**: Resizes array dynamically when needed, doubling capacity each time it's exceeded. Uses `time(NULL)` for timestamps.']

