// Function prototypes
UE_INSTANCE_MANAGER* create_ue_manager(size_t initial_size);
void destroy_ue_manager(UE_INSTANCE_MANAGER *manager);
bool validate_crc(NFAPI_CRC_INDICATION_PDU_T *pdu);
bool populate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, size_t index);
void log_error(const char *message, size_t instance_index);

UE_INSTANCE_MANAGER* create_ue_manager(size_t initial_size) {
    UE_INSTANCE_MANAGER *manager = (UE_INSTANCE_MANAGER*)malloc(sizeof(UE_INSTANCE_MANAGER));
    if (!manager) return NULL;

    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->count = initial_size;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void destroy_ue_manager(UE_INSTANCE_MANAGER *manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->array[i].crc_tag.payload.data);
        }
        free(manager->array);
        pthread_mutex_destroy(&manager->mutex);
        free(manager);
    }
}

