}

bool populate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, size_t index) {
    pdu->RX_UE_INFORMATION_TAG = (uint16_t)index;  // Simulating unique UE information tag
    pdu->RNTI = (uint16_t)(index + 1);              // Simulating a random RNTI

    size_t payload_length = rand() % 1024 + 1;      // Random payload length between 1 and 1024 bytes
    pdu->crc_tag.payload.data = (uint8_t *)malloc(payload_length);
    if (!pdu->crc_tag.payload.data) return false;

    pdu->crc_tag.payload.length = payload_length;
    memset(pdu->crc_tag.payload.data, rand() % 256, payload_length); // Fill with random data

    pdu->crc_tag.CRCFLAG = (bool)(rand() % 2);
    return true;
}

void log_error(const char *message, size_t instance_index) {
    logging_framework_log("Error at index %zu: %s", instance_index, message);
}

void manage_ue_instance(UE_INSTANCE_MANAGER *manager, size_t index, bool add) {
    pthread_mutex_lock(&manager->mutex);

    if (add) {
        manager->array[index].RX_UE_INFORMATION_TAG = 0;
        manager->array[index].RNTI = 0;

        if (!populate_pdu(&manager->array[index], index)) {
            log_error("Failed to populate PDU", index);
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
    } else {
        free(manager->array[index].crc_tag.payload.data);
        manager->array[index] = manager->array[manager->count - 1];
        --manager->count;
    }

    bool isValid = validate_crc(&manager->array[index]);
    if (!isValid) {
        log_error("CRC validation failed", index);

        free(manager->array[index].crc_tag.payload.data);
        if (!populate_pdu(&manager->array[index], index)) {
            pthread_mutex_unlock(&manager->mutex);
            return;
        }

        isValid = validate_crc(&manager->array[index]);
        if (!isValid) {
            log_error("CRC validation failed again after retry", index);
        } else {
            logging_framework_log("CRC validation succeeded after retry at index %zu", index);
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

// Example usage
int main() {
    UE_INSTANCE_MANAGER *manager = create_ue_manager(10);

    // Dynamically manage UEs
    for (size_t i = 0; i < manager->count; ++i) {
        manage_ue_instance(manager, i, true);   // Add and validate each instance
    }

    // Remove an instance example
    manage_ue_instance(manager, 5, false);

    destroy_ue_manager(manager);
    return 0;
}
