void init_dynamic_array(size_t N) {
    pthread_mutex_lock(&lock);
    if (N > capacity) {
        fprintf(stderr, "Requested size exceeds maximum capacity.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    current_size = N;
