    srand((unsigned int)time(NULL)); // Seed for random number generation
    for (size_t i = 0; i < N; ++i) {
        dynamic_array[i].RNTI = rand() % 65536;
        dynamic_array[i].ue_info.timestamp = time(NULL);
        dynamic_array[i].crc_indication.CRCFLAG = rand() & 1;

        if (dynamic_array[i].crc_indication.CRCFLAG) {
            true_crc_count++;
        }
    }

    pthread_mutex_unlock(&lock);
}

// Function to insert a new element at position pos
void insert_element(size_t pos, NFAPI_CRC_INDICATION_PDU_T *new_element) {
    pthread_mutex_lock(&lock);

    if (current_size >= capacity) {
        fprintf(stderr, "Array is full. Cannot insert new element.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    memmove(&dynamic_array[pos + 1], &dynamic_array[pos],
            (current_size - pos) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    dynamic_array[pos] = *new_element;

    if (new_element->crc_indication.CRCFLAG) {
        true_crc_count++;
    }

    current_size++;

    log_operation("Insert", pos, new_element->RNTI);
    pthread_mutex_unlock(&lock);
}

// Function to remove an element at position pos
void remove_element(size_t pos) {
    pthread_mutex_lock(&lock);

    if (pos >= current_size) {
        fprintf(stderr, "Invalid index. Cannot remove element.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    if (dynamic_array[pos].crc_indication.CRCFLAG) {
        true_crc_count--;
    }

    memmove(&dynamic_array[pos], &dynamic_array[pos + 1],
            (current_size - pos - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    current_size--;

    log_operation("Remove", pos, dynamic_array[pos].RNTI);
    pthread_mutex_unlock(&lock);
}

// Logging function integrated with existing logging framework
void log_operation(const char* operation, size_t position, uint16_t RNTI) {
