           operation, now);
}

// Function to provide statistics on the current state of the array
void print_statistics() {
    pthread_mutex_lock(&lock);

    float average_rnti = 0;
    for (size_t i = 0; i < current_size; ++i) {
        average_rnti += dynamic_array[i].RNTI;
    }
    average_rnti /= current_size;

    printf("Active entries: %zu\n", current_size);
    printf("Average RNTI usage: %.2f\n", average_rnti);
    printf("CRCFLAG set to true frequency: %.2f%%\n",
           (true_crc_count * 100.0 / capacity));

    pthread_mutex_unlock(&lock);
}

// Function to free the dynamic array
void free_dynamic_array() {
    pthread_mutex_lock(&lock);

    if (dynamic_array != NULL) {
        free(dynamic_array);
        dynamic_array = NULL;
    }

    current_size = 0;
    true_crc_count = 0;

    pthread_mutex_unlock(&lock);
}

int main() {
