```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t lock;
    time_t last_access_time[MAX_ELEMENTS]; // For tracking access times
} NFAPI_ARRAY_MANAGER;

static const int CLEANUP_THRESHOLD_SECONDS = 300; // Example threshold

void log_operation(const char* operation) {
    printf("Operation: %s\n", operation);
}

NFAPI_ARRAY_MANAGER* create_manager() {
    NFAPI_ARRAY_MANAGER *manager = malloc(sizeof(NFAPI_ARRAY_MANAGER));
    if (!manager) return NULL;

    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    memset(manager->elements, 0, sizeof(manager->elements));

    log_operation("Manager created");
    return manager;
}

int add_element(NFAPI_ARRAY_MANAGER *manager, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_ELEMENTS) {
        log_operation("Add failed: array full");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->elements[manager->count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->elements[manager->count]) {
        log_operation("Add failed: memory allocation error");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    *manager->elements[manager->count] = element;
    manager->last_access_time[manager->count] = time(NULL);
    manager->count++;

    log_operation("Element added");
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

int remove_element(NFAPI_ARRAY_MANAGER *manager, size_t index) {
    pthread_mutex_lock(&manager->lock);

    if (index >= manager->count) {
        log_operation("Remove failed: invalid index");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    free(manager->elements[index]);
    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->elements[i] = manager->elements[i + 1];
        manager->last_access_time[i] = manager->last_access_time[i + 1];
    }
    manager->elements[manager->count - 1] = NULL;
    manager->count--;

    log_operation("Element removed");
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* get_element_by_rnti(NFAPI_ARRAY_MANAGER *manager, int rnti) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->elements[i]->RNTI == rnti) {
            manager->last_access_time[i] = time(NULL);
            log_operation("Element retrieved by RNTI");
            pthread_mutex_unlock(&manager->lock);
            return manager->elements[i];
        }
    }

    log_operation("Get failed: element not found");
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

int update_crcflag(NFAPI_ARRAY_MANAGER *manager, size_t index, int condition) {
    pthread_mutex_lock(&manager->lock);

    if (index >= manager->count || !manager->elements[index]) {
        log_operation("Update failed: invalid index");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    // Example condition logic
    if (condition) {
        manager->elements[index]->CRCFLAG = 1;
    } else {
        manager->elements[index]->CRCFLAG = 0;
    }

    log_operation("CRCFLAG updated");
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

void periodic_cleanup(NFAPI_ARRAY_MANAGER *manager) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count;) {
        if (difftime(current_time, manager->last_access_time[i]) > CLEANUP_THRESHOLD_SECONDS) {
            free(manager->elements[i]);
            log_operation("Element cleaned up");
            for (; i < manager->count - 1; ++i) {
                manager->elements[i] = manager->elements[i + 1];
                manager->last_access_time[i] = manager->last_access_time[i + 1];
            }
            manager->elements[--manager->count] = NULL;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void destroy_manager(NFAPI_ARRAY_MANAGER *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->elements[i]);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);

    log_operation("Manager destroyed");
}
```

