        if (manager->array == NULL) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Memory allocation failed
        }
    }

    memcpy(&manager->array[manager->count], &element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->count++;

