            free(key_arrays);
            for (size_t j = 0; j < n; ++j) free(long_arrays[j]);
            free(long_arrays);
            return NULL;
        }
    }

    // Allocate and initialize record structures
    Record *records = calloc(n * m, sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed for records\n");
        for (size_t i = 0; i < k; ++i) free(key_arrays[i]);
        free(key_arrays);
        for (size_t i = 0; i < n; ++i) free(long_arrays[i]);
        free(long_arrays);
