        for (size_t i = 0; i < k; ++i) free(key_arrays[i]);
        free(key_arrays);
        for (size_t j = 0; j < n; ++j) free(long_arrays[j]);
        free(long_arrays);
        return NULL;
    }

    impl->long_arrays = long_arrays;
    impl->key_arrays = key_arrays;
    impl->records = records;

    return (DataStructures)impl;
}

// Implementation of the deallocation function
void deallocate_data_structures(DataStructures ds) {
    if (!ds) return;

    DataStructuresImpl *impl = (DataStructuresImpl *)ds;

    for (size_t i = 0; impl->long_arrays && i < n; ++i) free(impl->long_arrays[i]);
    free(impl->long_arrays);

    for (size_t j = 0; impl->key_arrays && j < k; ++j) free(impl->key_arrays[j]);
    free(impl->key_arrays);

    free(impl->records);
    free(impl);
}

// Helper function to initialize key arrays with unique values
