#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <time.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    int checksum_validation_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    long offset;
} offset_t;

typedef struct {
    int key;
} key_t;

typedef struct {
    int value;
} record_t;

typedef struct {
    size_t offset_array_size;
    size_t key_array_size;
    int record_value_range_min;
    int record_value_range_max;
    char* ciphers_to_register[];
    char* digests_to_register[];
} Config;

void initialize_framework_and_records(Config config, int verbose) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
    size_t pdu_count = 0;
    offset_t *offset_array = (offset_t *)malloc(config.offset_array_size * sizeof(offset_t));
    key_t *key_array = (key_t *)malloc(config.key_array_size * sizeof(key_t));
    record_t *record_array = (record_t *)malloc(config.key_array_size * sizeof(record_t));

    if (!offset_array || !key_array || !record_array) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offset_array);
        free(key_array);
        free(record_array);
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < config.key_array_size; ++i) {
        key_array[i].key = rand() % 10000;
        record_array[i].value = rand() % (config.record_value_range_max - config.record_value_range_min + 1) + config.record_value_range_min;

        if (verbose) {
            printf("Key: %d, Record Value: %d\n", key_array[i].key, record_array[i].value);
        }
    }

    for (size_t i = 0; i < sizeof(config.ciphers_to_register) / sizeof(char*); ++i) {
        if (!EVP_add_cipherbyname(config.ciphers_to_register[i])) {
            fprintf(stderr, "Failed to add cipher: %s\n", config.ciphers_to_register[i]);
        }
    }

    for (size_t i = 0; i < sizeof(config.digests_to_register) / sizeof(char*); ++i) {
        if (!EVP_add_digestbyname(config.digests_to_register[i])) {
            fprintf(stderr, "Failed to add digest: %s\n", config.digests_to_register[i]);
        }
    }

    // Example of adding unique RX_UE_INFORMATION_TAG and RNTI pairs
    while (pdu_count < config.key_array_size) {
        NFAPI_CRC_INDICATION_PDU_T new_pdu = {
            .RX_UE_INFORMATION_TAG = rand() % 1000,
            .RNTI = rand() % 1000,
            .CRC_INDICATION_REL8_TAG = rand() % 256,
            .checksum_validation_flag = rand() % 2
        };

        // Ensure uniqueness (simple check for demonstration)
        int unique = 1;
        for (size_t j = 0; j < pdu_count; ++j) {
            if ((pdu_list[j].RX_UE_INFORMATION_TAG == new_pdu.RX_UE_INFORMATION_TAG) &&
                (pdu_list[j].RNTI == new_pdu.RNTI)) {
                unique = 0;
                break;
            }
        }

        if (unique) {
            pdu_list = realloc(pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (pdu_count + 1));
            if (!pdu_list) {
                fprintf(stderr, "Memory allocation failed during PDU list expansion\n");
                free(offset_array);
                free(key_array);
                free(record_array);
                return;
            }
            pdu_list[pdu_count++] = new_pdu;

            if (verbose) {
                printf("Added PDU: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRC_INDICATION_REL8_TAG=%u, Checksum Validation Flag=%d\n",
                       new_pdu.RX_UE_INFORMATION_TAG, new_pdu.RNTI, new_pdu.CRC_INDICATION_REL8_TAG, new_pdu.checksum_validation_flag);
            }
        }
    }

    // Clean up
    free(pdu_list);
    free(offset_array);
    free(key_array);
    free(record_array);

    if (verbose) {
        printf("Initialization complete\n");
    }
}
