    if (logger.log_file != NULL) {
        fprintf(logger.log_file, "%s\n", message);
        fflush(logger.log_file);
    }
    pthread_mutex_unlock(&logger.lock);
}

bool validate_rnti_unique(NFAPI_CRC_INDICATION_PDU_T* users, int count, unsigned int rnti) {
    for (int i = 0; i < count; ++i) {
        if (users[i].RNTI == rnti) {
            return false;
        }
    }
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_users(int num_users) {
