['Below is an implementation of a thread-safe dynamic list managing `NFAPI_CRC_INDICATION_PDU_T` structures in C, using a hash table for efficient lookups and pthreads for synchronization:

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

#define HASH_TABLE_SIZE 1024

typedef struct {
    uint16_t RNTI;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    bool crc_flag;
    // Other fields...
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    uint16_t rnti;
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    size_t count;
    pthread_mutex_t lock;
} CRCIndicationList;

CRCIndicationList* crc_ind_list_init(size_t initial_size) {
    CRCIndicationList* list = malloc(sizeof(CRCIndicationList));
    if (!list) return NULL;

    list->table = calloc(HASH_TABLE_SIZE, sizeof(Node*));
    if (!list->table) {
        free(list);
        return NULL;
    }

    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    for (size_t i = 0; i < initial_size; ++i) {
        uint16_t rnti = rand() % HASH_TABLE_SIZE;
        if (!crc_ind_list_add(list, rnti)) {
            crc_ind_list_cleanup(list);
            return NULL;
        }
    }

    return list;
}

bool crc_ind_list_add(CRCIndicationList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    size_t index = rnti % HASH_TABLE_SIZE;
    Node* current = list->table[index];

    while (current) {
        if (current->rnti == rnti) {
            pthread_mutex_unlock(&list->lock);
            return false; // RNTI already exists
        }
        current = current->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    new_node->rnti = rnti;
    new_node->data.ue_info_tag.RNTI = rnti;
    new_node->data.crc_indication_rel8_tag.crc_flag = rand() % 2 == 0;
    new_node->next = list->table[index];
    list->table[index] = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

bool crc_ind_list_remove(CRCIndicationList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    size_t index = rnti % HASH_TABLE_SIZE;
    Node *current = list->table[index], *prev = NULL;

    while (current) {
        if (current->rnti == rnti) {
            if (prev) prev->next = current->next;
            else list->table[index] = current->next;

            free(current);
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return false; // RNTI not found
}

NFAPI_CRC_INDICATION_PDU_T* crc_ind_list_get_all(CRCIndicationList* list, size_t* count) {
    pthread_mutex_lock(&list->lock);

    *count = list->count;
    NFAPI_CRC_INDICATION_PDU_T* entries = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (*count));
    if (!entries) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    size_t i = 0;
    for (size_t j = 0; j < HASH_TABLE_SIZE; ++j) {
        Node* current = list->table[j];
        while (current) {
            entries[i++] = current->data;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return entries;
}

void crc_ind_list_cleanup(CRCIndicationList* list) {
    if (!list) return;

    for (size_t i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node* current = list->table[i];
        while (current) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }

    free(list->table);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
```

### Key Points:
- **Concurrency**: Uses `pthread_mutex_t` for thread safety.
- **Scalability and Performance**: Hash table ensures efficient lookups, insertions, and deletions.
- **Memory Management**: Efficient allocation and deallocation of nodes. Cleanup function ensures no memory leaks.
- **Modularity**: Functions are self-contained, making the code reusable and maintainable.']

