}

bool is_valid_rnti(unsigned int rnti, unsigned int min, unsigned int max) {
    return rnti >= min && rnti <= max;
}

CRCManager* create_crc_manager(unsigned int valid_rnti_min, unsigned int valid_rnti_max) {
    CRCManager* manager = (CRCManager*)malloc(sizeof(CRCManager));
    if (!manager) {
        log_error("Failed to allocate memory for CRCManager");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->array = (EventStruct*)calloc(INITIAL_CAPACITY, sizeof(EventStruct));
    if (!manager->array) {
        log_error("Failed to allocate initial array");
        free(manager);
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->valid_rnti_min = valid_rnti_min;
    manager->valid_rnti_max = valid_rnti_max;

    return manager;
}

void resize_array(CRCManager* manager) {
    size_t new_capacity = manager->capacity * 2;
    EventStruct* new_array = (EventStruct*)realloc(manager->array, new_capacity * sizeof(EventStruct));
    if (!new_array) {
        log_error("Failed to reallocate array");
        return;
    }
    manager->array = new_array;
    manager->capacity = new_capacity;
}

void update_valid_rnti_range(CRCManager* manager, unsigned int valid_rnti_min, unsigned int valid_rnti_max) {
    pthread_mutex_lock(&manager->lock);
    manager->valid_rnti_min = valid_rnti_min;
    manager->valid_rnti_max = valid_rnti_max;
    pthread_mutex_unlock(&manager->lock);
}

bool add_event(CRCManager* manager, char* rx_ue_information_tag, unsigned int rnti) {
    if (!rx_ue_information_tag || !is_valid_rnti(rnti, manager->valid_rnti_min, manager->valid_rnti_max)) {
        log_error("Invalid RX_UE_INFORMATION_TAG or RNTI");
        return false;
    }

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity * RESIZE_THRESHOLD) {
        resize_array(manager);
    }

    EventStruct new_event = {rx_ue_information_tag, rnti, {.tag = {.CRCFLAG = rand() % 2}}};
    manager->array[manager->count++] = new_event;

    pthread_mutex_unlock(&manager->lock);

    return true;
}

void destroy_crc_manager(CRCManager* manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->array);
        free(manager);
    }
}
