void init_list(DynamicList* list) {
    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);
}

void free_list(DynamicList* list) {
    free(list->entries);
    pthread_mutex_destroy(&list->lock);
}

static void resize_if_needed(DynamicList* list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_entries = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
}

static bool is_rnti_unique(DynamicList* list, uint16_t rnti) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->entries[i].RNTI == rnti) {
            return false;
        }
    }
    return true;
}

void add_entry(DynamicList* list, uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);

    if (!is_rnti_unique(list, RNTI)) {
        fprintf(stderr, "RNTI %u is not unique.\n", RNTI);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    resize_if_needed(list);

    list->entries[list->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->entries[list->size].RNTI = RNTI;
    list->entries[list->size].CRC_INDICATION_REL8_TAG.crc_flag = rand() % 2;

    list->size++;

    pthread_mutex_unlock(&list->lock);
}

void remove_entry(DynamicList* list, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->entries[i].RNTI == RNTI) {
            memmove(&list->entries[i], &list->entries[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->size--;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void retrieve_all_entries(const DynamicList* list, NFAPI_CRC_INDICATION_PDU_T** out_entries, size_t* out_size) {
    pthread_mutex_lock((DynamicList*)list);

    *out_entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!(*out_entries)) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    memcpy(*out_entries, list->entries, list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    *out_size = list->size;

    pthread_mutex_unlock((DynamicList*)list);
}

int main() {
