typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

typedef struct {
    Node **buckets;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

typedef struct {
    DynamicList list;
    int retry_count;
    // Additional fields for batch processing
} ProcessState;

// Hash function for RNTI
unsigned int hash_rnti(unsigned int rnti, size_t capacity) {
    return rnti % capacity;
}

DynamicList* init_dynamic_list(size_t initial_size) {
    DynamicList *list = (DynamicList *)malloc(sizeof(DynamicList));
    list->buckets = (Node **)calloc(initial_size, sizeof(Node *));
    list->capacity = initial_size;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_dynamic_list(DynamicList *list) {
    for (size_t i = 0; i < list->capacity; ++i) {
        Node *node = list->buckets[i];
        while (node) {
            Node *temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(list->buckets);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_dynamic_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    unsigned int index = hash_rnti(pdu.RNTI, list->capacity);

    pthread_mutex_lock(&list->lock);
    Node *node = list->buckets[index];
    while (node) {
        if (node->data.RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return 0; // RNTI already exists
        }
        node = node->next;
    }

    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->data = pdu;
    new_node->next = list->buckets[index];
    list->buckets[index] = new_node;

    pthread_mutex_unlock(&list->lock);
    return 1; // Successfully added
}

void* manageDynamicListAndProcessBatch(void *arg) {
    ProcessState *state = (ProcessState *)arg;
    DynamicList *list = &state->list;

    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand() % 1000; // Example RNTI
    pdu.CRC_INDICATION_REL8_TAG = rand() % 2;

    if (!add_to_dynamic_list(list, pdu)) {
        printf("RNTI already exists.\n");
        return NULL;
    }

    // Batch processing logic
    DATA_TRANSFORM_REQUEST_T request = {NULL, NULL, NULL}; // Example request

    for (int i = 0; i < state->retry_count; ++i) {
        if (process_request(&request)) {
            printf("Request processed successfully.\n");
            break;
        } else {
            fprintf(stderr, "Processing failed, retrying... (%d/%d)\n", i + 1, MAX_RETRIES);
            sleep(1); // Simulate delay before retry
        }
    }

    return NULL;
}

int process_request(DATA_TRANSFORM_REQUEST_T *request) {
    // Simulate request processing
    return rand() % 2; // Random success or failure
}

int main() {
    ProcessState state = {0};
    state.list = *(init_dynamic_list(INITIAL_LIST_SIZE));
    state.retry_count = MAX_RETRIES;

    pthread_t thread;
    if (pthread_create(&thread, NULL, manageDynamicListAndProcessBatch, &state)) {
        fprintf(stderr, "Error creating thread: %s\n", strerror(errno));
        return 1;
    }

    pthread_join(thread, NULL);

    free_dynamic_list(&state.list);
    return 0;
}
