            process_args->valid_pairs[process_args->valid_count] = malloc(sizeof(ValidPDUIntegerTagPair));
            if (!process_args->valid_pairs[process_args->valid_count]) {
                fprintf(stderr, "Memory allocation failed for valid pair\n");
                // Handle memory allocation failure
            } else {
                process_args->valid_pairs[process_args->valid_count]->pdu = pdus[i];
                process_args->valid_pairs[process_args->valid_count]->integer_tag = tags[i];
                process_args->valid_count++;
            }
            pthread_mutex_unlock(&process_args->mutex);
        }
    }

    // Clean up
    for (int i = 0; i < process_args->valid_count; ++i) {
        free(process_args->valid_pairs[i]);
    }
    free(process_args->valid_pairs);

    return NULL;
}

// Example usage of the function with threading
void example_usage() {
    int num_elements = 1000;
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    IntegerTag *tags = malloc(num_elements * sizeof(IntegerTag));

