// RandomValueGenerator class
typedef struct {
    int minInt;
    int maxInt;
    float minFloat;
    float maxFloat;
    pthread_mutex_t mutex;
} RandomValueGenerator;

RandomValueGenerator* createRandomValueGenerator(int minInt, int maxInt, float minFloat, float maxFloat) {
    RandomValueGenerator* rng = (RandomValueGenerator*)malloc(sizeof(RandomValueGenerator));
    if (!rng) return NULL;
    rng->minInt = minInt;
    rng->maxInt = maxInt;
    rng->minFloat = minFloat;
    rng->maxFloat = maxFloat;
    pthread_mutex_init(&rng->mutex, NULL);
    return rng;
}

int getRandomInteger(RandomValueGenerator* rng) {
    pthread_mutex_lock(&rng->mutex);
    int randomInt = rand() % (rng->maxInt - rng->minInt + 1) + rng->minInt;
    pthread_mutex_unlock(&rng->mutex);
    return randomInt;
}

float getRandomFloat(RandomValueGenerator* rng) {
    pthread_mutex_lock(&rng->mutex);
    float range = rng->maxFloat - rng->minFloat;
    float randomFloat = (rand() / (RAND_MAX + 1.0)) * range + rng->minFloat;
    pthread_mutex_unlock(&rng->mutex);
    return randomFloat;
}

void freeRandomValueGenerator(RandomValueGenerator* rng) {
    pthread_mutex_destroy(&rng->mutex);
    free(rng);
}

