#include <arpa/inet.h>

typedef struct {
    uint8_t mac[6];
    char ipv4[16]; // IPv4 address string (e.g., "192.168.1.1")
    char ipv6[46]; // IPv6 address string
    char subnet_mask[18]; // Subnet mask (IPv4 or IPv6)
} NICConfig;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRCFLAG;  // Randomly set to 0 or 1
    uint8_t CRC_INDICATION_REL8_TAG[20]; // Arbitrary size for demo
} NFAPI_CRC_INDICATION_PDU;

typedef struct ListNode {
    NICConfig data;
    struct ListNode* next;
} ListNode;

pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

ListNode* head = NULL;
int maxCapacity = 1000; // Example maximum capacity

// Function to check if MAC address is valid
int isValidMAC(uint8_t mac[6]) {
    for (int i = 0; i < 6; ++i) {
        if (mac[i] > 255)
            return 0;
    }
    return 1;
}

// Function to validate IP addresses and subnet mask
int isValidIP(const char* ip, const char* subnet_mask) {
    struct in_addr ipv4_addr;
    struct in6_addr ipv6_addr;

    if (inet_pton(AF_INET, ip, &ipv4_addr) > 0 ||
        inet_pton(AF_INET6, ip, &ipv6_addr) > 0)
        return 1;

    // Add additional validation for subnet mask if necessary
    return 0;
}

// Function to insert a NIC configuration into the list
int insertNICConfig(NICConfig config) {
    pthread_mutex_lock(&listMutex);

    if (!isValidMAC(config.mac) || !isValidIP(config.ipv4, config.subnet_mask))
        goto cleanup;

    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        goto cleanup;
    }

    newNode->data = config;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&listMutex);
    return 0;

cleanup:
    pthread_mutex_unlock(&listMutex);
    free(newNode);
    return -1;
}

// Function to clear the list
void clearList() {
    ListNode* current = head;
    while (current) {
        ListNode* temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;
}

// Function to populate NIC settings from NFAPI_CRC_INDICATION_PDU structures
int populateNICSettings(NFAPI_CRC_INDICATION_PDU* pdus, size_t num_pdus) {
    pthread_mutex_lock(&listMutex);

    int listSize = 0;
    ListNode* current = head;

    while (current && listSize < maxCapacity) {
        current = current->next;
        listSize++;
    }

    if (listSize >= maxCapacity)
        goto cleanup;

    for (size_t i = 0; i < num_pdus; ++i) {
        NICConfig config = {0};

        // Simulate MAC, IP and subnet configuration
        memcpy(config.mac, pdus[i].CRC_INDICATION_REL8_TAG, sizeof(config.mac));
        snprintf(config.ipv4, sizeof(config.ipv4), "192.168.%d.%d", (pdus[i].RX_UE_INFORMATION_TAG % 255), (pdus[i].RNTI % 255));
        snprintf(config.ipv6, sizeof(config.ipv6), "fe80::%x:%x", pdus[i].RX_UE_INFORMATION_TAG, pdus[i].RNTI);
        strncpy(config.subnet_mask, "255.255.255.0", sizeof(config.subnet_mask));

        config.mac[5] = (uint8_t)rand() % 2; // Random CRCFLAG as MAC end byte for demo
        if (insertNICConfig(config) != 0)
            goto cleanup;
    }

    pthread_mutex_unlock(&listMutex);
    return 0;

cleanup:
    clearList();
    pthread_mutex_unlock(&listMutex);
    return -1;
}

// Example use-case function to demonstrate integration with external API
int exampleNetworkAPIIntegration() {
    // Simulating receiving data from an API
    NFAPI_CRC_INDICATION_PDU* receivedData = (NFAPI_CRC_INDICATION_PDU*)malloc(10 * sizeof(NFAPI_CRC_INDICATION_PDU));

