        receivedData[i].RX_UE_INFORMATION_TAG = rand();
        receivedData[i].RNTI = rand() % 65535;
        memset(receivedData[i].CRC_INDICATION_REL8_TAG, rand() % 256, sizeof(receivedData[i].CRC_INDICATION_REL8_TAG));
    }

    int result = populateNICSettings(receivedData, 10);

    free(receivedData);
    return result;
}

int main() {
    srand(time(NULL));

    if (exampleNetworkAPIIntegration() != 0) {
