    CRC_INDICATION_REL8_TAG crc_info;
    uint16_t RNTI;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

// External dependencies
extern void* memory_pool_alloc(size_t size);
extern void memory_pool_free(void* ptr);

typedef struct {
    // Example fields for a hash table, implementation-dependent
} ThreadSafeHashTable;

extern int thread_safe_hash_table_insert(ThreadSafeHashTable* ht, uint16_t rnti);
extern int thread_safe_hash_table_contains(ThreadSafeHashTable* ht, uint16_t rnti);

// Global variables
ThreadSafeHashTable* rnti_hash_table;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(uint32_t n) {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** current = &head;

    for (uint32_t i = 0; i < n; ++i) {
        // Allocate memory using the memory pool manager
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool_alloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_node) {
            // Handle allocation failure
            continue;
        }

        pthread_mutex_lock(&list_mutex);

        uint16_t rnti;
        int valid_rnti = 0;

        do {
            rnti = (uint16_t)(rand() % UINT16_MAX); // Random RNTI generation
            if (!thread_safe_hash_table_contains(rnti_hash_table, rnti)) {
                thread_safe_hash_table_insert(rnti_hash_table, rnti);
                valid_rnti = 1;
            }
        } while (!valid_rnti);

        new_node->ue_info.RNTI = rnti; // Set RNTI
        new_node->crc_info.CRCFLAG = rand() % 2; // Random CRC flag
        new_node->RNTI = rnti;
        new_node->next = NULL;

        *current = new_node;
        current = &new_node->next;

        pthread_mutex_unlock(&list_mutex);
    }

    return head;
}
