        free(array);
        pthread_mutex_unlock(&mutex);
        return allocate_nfa_api_crc_pdu_array(n, handle); // Retry allocation on failure
    }

    log_message("Successfully allocated memory for NFAPI_CRC_INDICATION_PDU_T array.");
    pthread_mutex_unlock(&mutex);

    return array;
}

void free_nfa_api_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array) {
