#include <stdbool.h>
#include <time.h>

#define MAX_LIST_SIZE 50000

typedef struct {
    int signal_strength;
    float frequency;
    time_t timestamp;
} PHY_RX_METADATA;

typedef struct {
    bool is_valid; // Validity flag determined by heuristic
    int packet_loss_rate; // Example additional data for validity check
    PHY_RX_STREAM stream; // Assuming this structure exists elsewhere
} PHY_RX_CONTEXT;

typedef struct {
    PHY_RX_CONTEXT *elements;
    size_t count;
} DynamicList;

// Heuristic function to determine if a stream is valid
bool isValidStream(const PHY_RX_CONTEXT* context) {
    const int signal_threshold = 20; // Example threshold value
    const float packet_loss_limit = 0.1f; // Example limit for acceptable packet loss

    return (context->stream.signal_strength >= signal_threshold &&
            context->packet_loss_rate < (int)(100 * packet_loss_limit));
}

// Function to initialize the list
void initList(DynamicList* list) {
    list->elements = malloc(MAX_LIST_SIZE * sizeof(PHY_RX_CONTEXT));
    if (!list->elements) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    list->count = 0;
}

// Function to add a new context to the list
bool addContext(DynamicList* list, const PHY_RX_STREAM* stream, int signal_strength,
                float frequency, int packet_loss_rate) {
    if (list->count >= MAX_LIST_SIZE) {
        return false; // List is full
    }

    PHY_RX_CONTEXT new_context;
    new_context.stream = *stream;
    new_context.packet_loss_rate = packet_loss_rate;

    // Set metadata
    new_context.stream.metadata.signal_strength = signal_strength;
    new_context.stream.metadata.frequency = frequency;
    new_context.stream.metadata.timestamp = time(NULL);

    // Determine validity using heuristic algorithm
    new_context.is_valid = isValidStream(&new_context);

    list->elements[list->count++] = new_context;

    return true;
}

// Function to remove a context by index
bool removeContext(DynamicList* list, size_t index) {
    if (index >= list->count) {
        return false; // Index out of bounds
    }

    for (size_t i = index; i < list->count - 1; ++i) {
        list->elements[i] = list->elements[i + 1];
    }
    --list->count;

    return true;
}

// Function to free the allocated memory
void freeList(DynamicList* list) {
    free(list->elements);
    list->elements = NULL;
    list->count = 0;
}
