#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>

#define MAX_RNTI 0xFFFFFFFF

typedef struct {
    uint32_t RNTI;
    uint8_t RX_UE_INFORMATION_TAG;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} RNTICollection;

RNTICollection* init_rnti_collection() {
    RNTICollection* collection = (RNTICollection*)malloc(sizeof(RNTICollection));
    if (!collection) return NULL;

    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

int is_duplicate(RNTICollection* collection, uint32_t rnti) {
    Node* current = collection->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

void add_rnti_entry(RNTICollection* collection, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&collection->lock);

    if (is_duplicate(collection, entry.RNTI)) {
        printf("Duplicate RNTI detected: %u\n", entry.RNTI);
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    new_node->data = entry;
    new_node->next = collection->head;
    collection->head = new_node;

    pthread_mutex_unlock(&collection->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_rnti_entry(RNTICollection* collection, uint32_t rnti) {
    pthread_mutex_lock(&collection->lock);

    Node* current = collection->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* result = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            *result = current->data;
            pthread_mutex_unlock(&collection->lock);
            return result;
        }
        current = current->next;
    }

    printf("RNTI not found: %u\n", rnti);
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

void free_rnti_collection(RNTICollection* collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    Node* current = collection->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void generate_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (!entry) return;

    // Randomly set the CRCFLAG to either 0 or 1
    entry->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
}
