        for (int i = 0; i < RNTI_SIZE; ++i) {
            existing_ues[ue_count][i] = rand() % 256;
        }
        // Check uniqueness.
        int is_unique = 1;
        for (int i = 0; i < ue_count && is_unique; ++i) {
            if (memcmp(existing_ues[i], existing_ues[ue_count], RNTI_SIZE * sizeof(int)) == 0) {
                is_unique = 0;
            }
        }
        if (is_unique) return 1;
    }
}

