    NFAPI_CRC_INDICATION_PDU_T *head = NULL, **tail = &head;

    int existing_ues[MAX_UE_COUNT][RNTI_SIZE] = {0};
    int ue_count = 0;

    for (size_t i = 0; i < n && ue_count < MAX_UE_COUNT; ++i) {
