#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define structures
typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG; // Ensure CRCFLAG is unique across all nodes
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for managing unique CRCFLAG and thread safety
int current_crcflag = 0;
pthread_mutex_t crc_lock = PTHREAD_MUTEX_INITIALIZER;

// Pool allocator setup (simplified)
#define POOL_SIZE 1024
NFAPI_CRC_INDICATION_PDU_T *pool[POOL_SIZE];
unsigned int pool_index = 0;

void init_pool() {
    for (int i = 0; i < POOL_SIZE; ++i) {
        pool[i] = NULL;
    }
}

// Function to allocate a new node from the pool
NFAPI_CRC_INDICATION_PDU_T *allocate_node() {
    pthread_mutex_lock(&crc_lock);

    if (pool_index < POOL_SIZE && pool[pool_index]) {
        NFAPI_CRC_INDICATION_PDU_T *node = pool[pool_index++];
        pthread_mutex_unlock(&crc_lock);
        return node;
    }

    // Allocate from heap if pool is empty
    pthread_mutex_unlock(&crc_lock);

    return malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Function to deallocate a node back into the pool
void deallocate_node(NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&crc_lock);

    if (pool_index < POOL_SIZE) {
        pool[--pool_index] = node;
    } else {
        free(node);
    }

    pthread_mutex_unlock(&crc_lock);
}

// Function to insert a new node ensuring CRCFLAG is unique and RNTI integrity
void insert_node(NFAPI_CRC_INDICATION_PDU_T **head, unsigned long rx_ue_info_tag, unsigned int rnti) {
    NFAPI_CRC_INDIGATION_PDU_T *new_node = allocate_node();

    if (!new_node) return;

    new_node->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->RNTI = rnti;

    pthread_mutex_lock(&crc_lock);
    current_crcflag++;
    new_node->crc_tag.CRCFLAG = current_crcflag; // Ensure unique CRCFLAG
    pthread_mutex_unlock(&crc_lock);

    new_node->next = *head;
    *head = new_node;

    validate_integrity(head);
}

// Function to validate the integrity of the list
void validate_integrity(NFAPI_CRC_INDICATION_PDU_T **head) {
    NFAPI_CRC_INDICATION_PDU_T *current = *head, *prev = NULL;

    while (current) {
        if (prev && prev->RNTI == current->RNTI) {
            fprintf(stderr, "Integrity violation: Adjacent nodes with same RNTI detected.\n");
            deallocate_node(current); // Clean up the faulty node
            if (prev) {
                prev->next = current->next; // Remove from list
                current = prev;
            } else {
                *head = NULL;
                current = NULL;
            }
        } else {
            prev = current;
            current = current->next;
        }
    }
}

int main() {
    init_pool();

    NFAPI_CRC_INDICATION_PDU_T *list_head = NULL;

    // Example insertions
    insert_node(&list_head, 12345, 1);
    insert_node(&list_head, 12346, 2);
    insert_node(&list_head, 12347, 2); // This will trigger an integrity violation

    // Clean up the list
    while (list_head) {
        NFAPI_CRC_INDICATION_PDU_T *temp = list_head;
        list_head = list_head->next;
        deallocate_node(temp);
    }

    return 0;
}
