ReportNode* report_list = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety

// Function prototypes
int add_report(uint32_t network_id, time_t timestamp, Session *sessions, size_t session_count);
int update_session_duration(uint64_t session_id, int new_duration);
void free_reports();
int serialize_report(const Report* report, uint8_t** buffer, size_t* buffer_size);

// Add a new report
int add_report(uint32_t network_id, time_t timestamp, Session *sessions, size_t session_count) {
    pthread_mutex_lock(&mutex);

    ReportNode* new_node = (ReportNode*)malloc(sizeof(ReportNode));
    if (!new_node) {
        pthread_mutex_unlock(&mutex);
        return -1; // Memory allocation failure
    }

    new_node->report.network_id = network_id;
    new_node->report.timestamp = timestamp;
    new_node->report.session_count = session_count;

    new_node->report.sessions = (Session*)malloc(session_count * sizeof(Session));
    if (!new_node->report.sessions) {
        free(new_node);
        pthread_mutex_unlock(&mutex);
        return -1; // Memory allocation failure
    }

    for (size_t i = 0; i < session_count; ++i) {
        new_node->report.sessions[i] = sessions[i];
    }

    new_node->next = report_list;
    report_list = new_node;

    pthread_mutex_unlock(&mutex);
    return 0;
}

// Update the duration of a session
int update_session_duration(uint64_t session_id, int new_duration) {
    pthread_mutex_lock(&mutex);

    for (ReportNode* node = report_list; node != NULL; node = node->next) {
        for (size_t i = 0; i < node->report.session_count; ++i) {
            if (node->report.sessions[i].session_id == session_id) {
                node->report.sessions[i].duration = new_duration;
                pthread_mutex_unlock(&mutex);
                return 0; // Success
            }
        }
    }

    pthread_mutex_unlock(&mutex);
    return -1; // Session not found
}

// Free all allocated reports
void free_reports() {
    pthread_mutex_lock(&mutex);

    ReportNode* current = report_list;
    while (current) {
        ReportNode* temp = current;
        current = current->next;

        free(temp->report.sessions);
        free(temp);
    }

    report_list = NULL;
    pthread_mutex_unlock(&mutex);
}

// Serialize a report into a custom binary format
int serialize_report(const Report* report, uint8_t** buffer, size_t* buffer_size) {
    // Calculate the required buffer size (example calculation)
    *buffer_size = sizeof(uint32_t) + sizeof(time_t) + report->session_count * (sizeof(uint64_t) + sizeof(int));

    *buffer = (uint8_t*)malloc(*buffer_size);
    if (!*buffer) return -1; // Memory allocation failure

    uint8_t* ptr = *buffer;
    memcpy(ptr, &report->network_id, sizeof(report->network_id)); ptr += sizeof(report->network_id);
    memcpy(ptr, &report->timestamp, sizeof(report->timestamp)); ptr += sizeof(report->timestamp);
    for (size_t i = 0; i < report->session_count; ++i) {
        memcpy(ptr, &report->sessions[i].session_id, sizeof(report->sessions[i].session_id)); ptr += sizeof(report->sessions[i].session_id);
        memcpy(ptr, &report->sessions[i].duration, sizeof(report->sessions[i].duration)); ptr += sizeof(report->sessions[i].duration);
    }

    return 0; // Success
}
```

### Key Considerations

1. **Memory Management**: Uses a linked list to handle dynamic report entries efficiently, avoiding fragmentation and allowing for easy reallocation.

2. **Concurrency**: Utilizes a mutex to ensure thread safety during read/write operations.

3. **Scalability**: Linked list structure supports large-scale data management with low overhead per node.

4. **Integration**: Includes a `serialize_report` function designed for custom binary protocol serialization, mindful of data alignment and endianness considerations.

5. **Error Handling**: Checks for memory allocation failures and returns appropriate error codes.

6. **Usability**: Provides clear interfaces (`add_report`, `update_session_duration`) for easy interaction with the report system.']

