// Define the structures used in NFAPI_RX_FRAME_INFO
typedef struct {
    uint16_t tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint16_t rnti;
} RNTI;

typedef struct {
    uint8_t crc_indication;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    time_t timestamp;  // For tracking when the frame was added
} NFAPI_RX_FRAME_INFO;

// Global variables for managing dynamic array and concurrency
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_RX_FRAME_INFO *frame_array = NULL;
size_t current_capacity = 0;
size_t active_frames_count = 0;
time_t clear_threshold;  // Time threshold to clear outdated frames

void initialize_frame_manager(size_t initial_capacity, time_t initial_clear_threshold) {
    pthread_mutex_lock(&mutex);
    if (frame_array != NULL) {
        free(frame_array);
    }

    current_capacity = initial_capacity;
    frame_array = (NFAPI_RX_FRAME_INFO *)calloc(current_capacity, sizeof(NFAPI_RX_FRAME_INFO));
    clear_threshold = initial_clear_threshold;

    active_frames_count = 0;
    pthread_mutex_unlock(&mutex);
}

void resize_frame_manager(size_t new_capacity) {
    pthread_mutex_lock(&mutex);
    if (new_capacity > current_capacity) {
        NFAPI_RX_FRAME_INFO *temp_array = (NFAPI_RX_FRAME_INFO *)realloc(frame_array, new_capacity * sizeof(NFAPI_RX_FRAME_INFO));
        if (temp_array != NULL) {
            frame_array = temp_array;
            current_capacity = new_capacity;
        } else {
            // Handle memory allocation failure
            fprintf(stderr, "Failed to resize frame array.\n");
        }
    }
    pthread_mutex_unlock(&mutex);
}

int add_frame(const NFAPI_RX_FRAME_INFO *frame_info) {
    pthread_mutex_lock(&mutex);

    if (active_frames_count >= current_capacity) {
        // Attempt to double the capacity
        resize_frame_manager(current_capacity * 2);
    }

    if (active_frames_count < current_capacity && frame_info != NULL) {
        frame_array[active_frames_count] = *frame_info;
        frame_array[active_frames_count].timestamp = time(NULL);  // Set timestamp to current time
        active_frames_count++;
        pthread_mutex_unlock(&mutex);
        return 0;  // Success
    }

    pthread_mutex_unlock(&mutex);
    return -1;  // Failure, array is full or invalid input
}

void clear_outdated_frames() {
    pthread_mutex_lock(&mutex);

    time_t current_time = time(NULL);
    size_t new_active_count = 0;

    for (size_t i = 0; i < active_frames_count; ++i) {
        if ((current_time - frame_array[i].timestamp) > clear_threshold) {
            // Frame is outdated
            continue;
        }
        // Move valid frames to the beginning of the array
        if (new_active_count != i) {
            frame_array[new_active_count] = frame_array[i];
        }
        new_active_count++;
    }

    active_frames_count = new_active_count;

    pthread_mutex_unlock(&mutex);
}

void set_clear_threshold(time_t new_threshold) {
    pthread_mutex_lock(&mutex);
    clear_threshold = new_threshold;
    pthread_mutex_unlock(&mutex);
}

size_t get_active_frame_count() {
    pthread_mutex_lock(&mutex);
    size_t count = active_frames_count;
    pthread_mutex_unlock(&mutex);
    return count;
}

void shutdown_frame_manager() {
    pthread_mutex_lock(&mutex);
    if (frame_array != NULL) {
        free(frame_array);
        frame_array = NULL;
    }
    current_capacity = 0;
    active_frames_count = 0;
    pthread_mutex_unlock(&mutex);
}
