```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

// Forward declarations for the logger
typedef void (*LoggerCallback)(const char*);

#define INITIAL_CAPACITY 1024

// A struct to represent a TCP connection record.
typedef struct {
    uint32_t CONNECTION_ID;
    char REMOTE_ADDRESS[16];
    uint16_t LOCAL_PORT;
    time_t CREATED_AT; // For calculating average lifetime
} TCP_CONNECTION_RECORD;

// Hash table entry
struct HashEntry {
    TCP_CONNECTION_RECORD record;
    struct HashEntry* next;
};

// Dynamic array manager structure
typedef struct {
    struct HashEntry** table;
    size_t capacity;
    size_t count;
    LoggerCallback logger;
} ConnectionManager;

// Function prototypes
ConnectionManager* create_connection_manager(LoggerCallback logger);
int hash_function(const char* remote_address, uint16_t local_port, size_t capacity);
void log_event(ConnectionManager* manager, const char* event);

int insert_connection(ConnectionManager* manager, TCP_CONNECTION_RECORD new_record);
TCP_CONNECTION_RECORD* get_connection(ConnectionManager* manager, const char* remote_address, uint16_t local_port);
int delete_connection(ConnectionManager* manager, const char* remote_address, uint16_t local_port);

void resize_table(ConnectionManager* manager);

// Function implementations

ConnectionManager* create_connection_manager(LoggerCallback logger) {
    ConnectionManager* manager = malloc(sizeof(ConnectionManager));
    if (!manager) return NULL;

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->table = calloc(manager->capacity, sizeof(struct HashEntry*));
    manager->logger = logger;

    if (!manager->table) {
        free(manager);
        return NULL;
    }

    log_event(manager, "Connection Manager Created");
    return manager;
}

int hash_function(const char* remote_address, uint16_t local_port, size_t capacity) {
    return (hash(remote_address) ^ (uint32_t)local_port) % capacity;
}

void log_event(ConnectionManager* manager, const char* event) {
    if (manager->logger) {
        manager->logger(event);
    }
}

int insert_connection(ConnectionManager* manager, TCP_CONNECTION_RECORD new_record) {
    size_t index = hash_function(new_record.REMOTE_ADDRESS, new_record.LOCAL_PORT, manager->capacity);
    struct HashEntry* entry = manager->table[index];

    while (entry) {
        if (strcmp(entry->record.REMOTE_ADDRESS, new_record.REMOTE_ADDRESS) == 0 &&
            entry->record.LOCAL_PORT == new_record.LOCAL_PORT) {
            log_event(manager, "Duplicate Connection Detected");
            return -1;
        }
        entry = entry->next;
    }

    struct HashEntry* new_entry = malloc(sizeof(struct HashEntry));
    if (!new_entry) return -2;

    new_entry->record = new_record;
    new_entry->next = manager->table[index];
    manager->table[index] = new_entry;
    manager->count++;

    log_event(manager, "Connection Inserted");

    if (manager->count >= manager->capacity * 0.7) {
        resize_table(manager);
    }

    return 0;
}

TCP_CONNECTION_RECORD* get_connection(ConnectionManager* manager, const char* remote_address, uint16_t local_port) {
    size_t index = hash_function(remote_address, local_port, manager->capacity);
    struct HashEntry* entry = manager->table[index];

    while (entry) {
        if (strcmp(entry->record.REMOTE_ADDRESS, remote_address) == 0 &&
            entry->record.LOCAL_PORT == local_port) {
            return &entry->record;
        }
        entry = entry->next;
    }

    return NULL;
}

int delete_connection(ConnectionManager* manager, const char* remote_address, uint16_t local_port) {
    size_t index = hash_function(remote_address, local_port, manager->capacity);
    struct HashEntry *entry = manager->table[index], *prev = NULL;

    while (entry) {
        if (strcmp(entry->record.REMOTE_ADDRESS, remote_address) == 0 &&
            entry->record.LOCAL_PORT == local_port) {

            if (prev) {
                prev->next = entry->next;
            } else {
                manager->table[index] = entry->next;
            }

            free(entry);
            manager->count--;
            log_event(manager, "Connection Deleted");
            return 0;
        }
        prev = entry;
        entry = entry->next;
    }

    return -1; // Not found
}

void resize_table(ConnectionManager* manager) {
    size_t new_capacity = manager->capacity * 2;
    struct HashEntry** new_table = calloc(new_capacity, sizeof(struct HashEntry*));

    if (!new_table) return;

    for (size_t i = 0; i < manager->capacity; ++i) {
        struct HashEntry* entry = manager->table[i];

        while (entry) {
            size_t index = hash_function(entry->record.REMOTE_ADDRESS, entry->record.LOCAL_PORT, new_capacity);
            struct HashEntry* next_entry = entry->next;

            entry->next = new_table[index];
            new_table[index] = entry;

            entry = next_entry;
        }
    }

    free(manager->table);
    manager->table = new_table;
    manager->capacity = new_capacity;
    log_event(manager, "Hash Table Resized");
}
```

### Explanation
- **Data Structures**: The implementation uses a hash table with chaining for efficient insertion and retrieval. Each entry in the hash table points to a linked list of records (`struct HashEntry`) that share the same hash index.

- **Memory Management**: It dynamically allocates memory for new connection records and resizes the hash table when it's 70% full, which helps maintain performance under high-load conditions.

- **Concurrency and Fault Tolerance**: The basic structure provided does not include explicit concurrency control mechanisms. For real-world applications with concurrent access, consider using mutexes or atomic operations to manage shared resources safely.

- **Logging**: Logging is abstracted through a callback function pointer (`LoggerCallback`), allowing integration with various logging backends.

- **Scalability and Performance**: The hash table handles resizing automatically to maintain performance as the number of connections increases. For further scalability, especially in distributed environments or high-load scenarios, consider additional optimizations such as sharding or using concurrent data structures like lock-free queues.

This code provides a solid foundation but would need enhancements for complete production use, including error handling improvements, advanced concurrency control, and integration with an actual logging system.']

