#define MAX_STRUCTS 100000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Global mutex for thread safety
pthread_mutex_t rnti_lock = PTHREAD_MUTEX_INITIALIZER;

int is_rnti_unique(unsigned int *rntis, unsigned int new_rnti, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (rntis[i] == new_rnti) return 0;
    }
    return 1;
}

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications(size_t n, int *error_count) {
    if (n > MAX_STRUCTS) {
        fprintf(stderr, "Requested number exceeds maximum allowed structures.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        perror("Failed to allocate memory for indications");
        return NULL;
    }

    unsigned int rntis[MAX_STRUCTS] = {0};
    size_t count = 0;
    srand(time(NULL));

    *error_count = 0;

    while (count < n) {
        pthread_mutex_lock(&rnti_lock);

        int rx_ue_info_tag = rand();
        unsigned int rnti = rand() % MAX_STRUCTS + 1; // Avoid zero RNTI
        int crcflag = rand() & 1; // Randomly set CRCFLAG to 0 or 1

        if (is_rnti_unique(rntis, rnti, count)) {
            indications[count].RX_UE_INFORMATION_TAG = rx_ue_info_tag;
            indications[count].RNTI = rnti;
            indications[count].CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;

            rntis[count] = rnti;
            ++count;
        } else {
            fprintf(stderr, "Duplicate RNTI detected: %u. Skipping...\n", rnti);
            pthread_mutex_unlock(&rnti_lock);

            (*error_count)++;
        }

        pthread_mutex_unlock(&rnti_lock);
    }

    return indications;
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T* indications) {
    if (indications) {
        free(indications);
    }
}
