typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    unsigned short RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG UEInfoTag;
    CRC_INDICATION_REL8_TAG CRCInfoTag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

#define SUCCESS 0
#define MEMORY_ALLOCATION_FAILURE -1
#define INVALID_RNTI_VALUE -2

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random RNTI value in the valid range
unsigned short generateRandomRNTI() {
    return (rand() % (0x7FFF - 0x0001 + 1)) + 0x0001;
}

// Create and initialize NFAPI_CRC_INDICATION_PDU_T linked list
int createNfapiPduList(NFAPI_CRC_INDICATION_PDU_T **head, int N, size_t maxMemorySize, int crcLimit) {
    srand(42); // Seed for consistent results across runs
    pthread_mutex_lock(&mutex);

    if (*head != NULL) {
        freeNfaPiPduList(*head);
    }

    *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current, *last = NULL;
    int count = 0;
    unsigned int usedMemory = 0;

    for (int i = 0; i < N; ++i) {
        current = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!current) {
            pthread_mutex_unlock(&mutex);
            return MEMORY_ALLOCATION_FAILURE;
        }

        usedMemory += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (usedMemory > maxMemorySize) {
            freeNfaPiPduList(*head);
            pthread_mutex_unlock(&mutex);
            return MEMORY_ALLOCATION_FAILURE;
        }

        current->UEInfoTag.RNTI = generateRandomRNTI();
        if (current->UEInfoTag.RNTI == 0x0000 || current->UEInfoTag.RNTI > 0x7FFF) {
            freeNfaPiPduList(*head);
            pthread_mutex_unlock(&mutex);
            return INVALID_RNTI_VALUE;
        }

        // Randomly set CRCFLAG ensuring crcLimit is not exceeded
        int maxCrcFlag = crcLimit - count;
        current->CRCInfoTag.CRCFLAG = (rand() % 2) && (maxCrcFlag > 0);

        if (current->CRCInfoTag.CRCFLAG == 1) {
            ++count;
        }

        current->next = NULL;

        if (*head == NULL) {
            *head = current;
        } else {
            last->next = current;
        }
        last = current;
    }

    pthread_mutex_unlock(&mutex);
    return SUCCESS;
}

void freeNfaPiPduList(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head, *tmp;

    while (current != NULL) {
        tmp = current;
        current = current->next;
        free(tmp);
    }
}

void printNfapiPduList(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;

    pthread_mutex_lock(&mutex);

    while (current != NULL) {
        printf("RNTI: %u, CRCFLAG: %d\n", current->UEInfoTag.RNTI, current->CRCInfoTag.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *listHead = NULL;
    int errorCode = createNfapiPduList(&listHead, 1000, 65536, 100);

    if (errorCode != SUCCESS) {
        fprintf(stderr, "Error creating NFAPI PDU list: %d\n", errorCode);
        return EXIT_FAILURE;
    }

    printNfapiPduList(listHead);
    freeNfaPiPduList(listHead);

    return EXIT_SUCCESS;
}
