    size_t capacity;
    size_t count;
    pthread_mutex_t lock;  // Mutex for thread-safe operations
} LTE_UE_CONFIG_MANAGER;

// Function to initialize the manager
LTE_UE_CONFIG_MANAGER* init_ue_config_manager(size_t initial_capacity) {
    LTE_UE_CONFIG_MANAGER* manager = (LTE_UE_CONFIG_MANAGER*)malloc(sizeof(LTE_UE_CONFIG_MANAGER));
    if (!manager) return NULL;

    manager->configs = (LTE_UE_CONFIG*)calloc(initial_capacity, sizeof(LTE_UE_CONFIG));
    if (!manager->configs) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Function to add or update a configuration
int set_ue_config(LTE_UE_CONFIG_MANAGER* manager, LTE_UE_CONFIG config) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->configs[i].ue_id == config.ue_id) {
            // Update existing configuration
            manager->configs[i] = config;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    // Expand capacity if needed
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_UE_CONFIG* new_configs = (LTE_UE_CONFIG*)realloc(manager->configs, new_capacity * sizeof(LTE_UE_CONFIG));
        if (!new_configs) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failure
        }
        manager->configs = new_configs;
        manager->capacity = new_capacity;
    }

    // Add new configuration
    manager->configs[manager->count++] = config;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to retrieve a configuration by UE ID
LTE_UE_CONFIG* get_ue_config(LTE_UE_CONFIG_MANAGER* manager, int ue_id) {
    if (!manager) return NULL;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->configs[i].ue_id == ue_id) {
            LTE_UE_CONFIG* config = &manager->configs[i];
            pthread_mutex_unlock(&manager->lock);
            return config;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Function to clean up resources
void free_ue_config_manager(LTE_UE_CONFIG_MANAGER* manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->lock);
    free(manager->configs);
    free(manager);
}

