    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    long filesize = ftell(file);
    *num_structures = filesize / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(*num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fclose(file);
        return NULL;
    }

    fseek(file, 0, SEEK_SET);
    pthread_mutex_lock(&list_lock);
    fread(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), *num_structures, file);
    pthread_mutex_unlock(&list_lock);

    fclose(file);
    return list;
}

// Cleanup
void free_structures(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list) free(list);
}
