void rotate_log_file() {
    static time_t last_rotation_time = 0;
    time_t current_time = time(NULL);

    if (current_time - last_rotation_time >= 86400) { // Rotate daily
        pthread_mutex_lock(&logger_ctx.lock);

        if (logger_ctx.log_file != NULL) {
            fclose(logger_ctx.log_file);
            char rotated_filename[256];
            snprintf(rotated_filename, sizeof(rotated_filename), "%s.%ld", LOG_FILE, last_rotation_time);
            rename(LOG_FILE, rotated_filename);
            logger_ctx.log_file = fopen(LOG_FILE, "a");
        } else {
            logger_ctx.log_file = fopen(LOG_FILE, "a");
        }

        pthread_mutex_unlock(&logger_ctx.lock);

        last_rotation_time = current_time;
    }
}

void log_error(const char* message) {
    rotate_log_file();

    pthread_mutex_lock(&logger_ctx.lock);
    if (logger_ctx.log_file != NULL) {
        fprintf(logger_ctx.log_file, "%s\n", message);
        fflush(logger_ctx.log_file);
    } else {
        fprintf(stderr, "Failed to log error: %s\n", message);  // Fallback logging
    }
    pthread_mutex_unlock(&logger_ctx.lock);
}

