// Define the necessary structures as placeholders
typedef struct {
    uint16_t UL_CCCH_INDICATION_TAG;
    int UE_INDEX;
    uint32_t MAC_ENTITY_ID;
} NFAPI_UL_CCCH_INDICATION_PDU_T;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_POOL_SIZE 100
#define LOG_BUFFER_SIZE 1024

// Predefined pools and mutex for thread safety
uint32_t mac_entity_id_pool[MAX_POOL_SIZE];
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct Node {
    void *data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    size_t count;
} List;

// Logging function
void log_operation(const char *operation, uint32_t rnti) {
    time_t now = time(NULL);
    FILE *log_file = fopen("network_operations.log", "a");
    if (log_file) {
        fprintf(log_file, "[%ld] %s RNTI: 0x%08X\n", now, operation, rnti);
        fclose(log_file);
    }
}

// Memory allocation wrapper with error handling
void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

List* create_list() {
    List *list = safe_malloc(sizeof(List));
    list->head = NULL;
    list->count = 0;
    return list;
}

void destroy_list(List **list_ptr) {
    if (!list_ptr || !*list_ptr) return;

    Node *current = (*list_ptr)->head;
    while (current) {
        Node *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    free(*list_ptr);
    *list_ptr = NULL;
}

void add_to_list(List *list, void *data) {
    pthread_mutex_lock(&list_mutex);

    Node *new_node = safe_malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;

    list->count++;
    pthread_mutex_unlock(&list_mutex);
}

// Function to generate a random MAC entity ID from the pool
uint32_t get_random_mac_entity_id() {
    return rand() % MAX_POOL_SIZE;
}

void populate_ul_ccch_list(List *ul_ccch_list, int num_indications) {
    for (int i = 0; i < num_indications; ++i) {
        NFAPI_UL_CCCH_INDICATION_PDU_T *pdu = safe_malloc(sizeof(NFAPI_UL_CCCH_INDICATION_PDU_T));
        pdu->UL_CCCH_INDICATION_TAG = rand(); // Assuming valid tags are any value
        pdu->UE_INDEX = i;
        pdu->MAC_ENTITY_ID = mac_entity_id_pool[get_random_mac_entity_id()];

        add_to_list(ul_ccch_list, pdu);
    }
}

void populate_crc_indication_list(List *crc_indication_list, int num_indications) {
    for (int i = 0; i < num_indications; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = safe_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->RX_UE_INFORMATION_TAG = rand(); // Assuming valid tags are any value
        pdu->RNTI = rand();
        pdu->CRC_INDICATION_REL8_TAG = rand() % 256; // Random CRC tag

        add_to_list(crc_indication_list, pdu);

        // Log operation with timestamp and RNTI
        log_operation("CRC Indication Added", pdu->RNTI);
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    List *ul_ccch_list = create_list();
    List *crc_indication_list = create_list();

    int num_ul_ccch = 100; // Example number of indications
    int num_crc_indications = 150; // Example number of CRC indications

    populate_ul_ccch_list(ul_ccch_list, num_ul_ccch);
    populate_crc_indication_list(crc_indication_list, num_crc_indications);

    destroy_list(&ul_ccch_list);
    destroy_list(&crc_indication_list);

    return 0;
}
