    if (new_size > global_config.max_structures) {
        log_error("Validation error: Exceeded max number of structures.");
        pthread_mutex_unlock(&list_lock);
        return VALIDATION_ERROR;
    }

    NFAPI_CRC_INDICATION_PDU_T **temp_list = realloc(nfa_list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!temp_list) {
        log_error("Allocation failure when resizing structure list.");
        pthread_mutex_unlock(&list_lock);
        return ALLOCATION_FAILURE;
    }

    nfa_list = temp_list;

    for (size_t i = 0; i < new_size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            log_error("Allocation failure for new PDU structure.");
            while (--i >= 0) free(nfa_list[i]);
            free(nfa_list);
            nfa_list = NULL;
            pthread_mutex_unlock(&list_lock);
            return ALLOCATION_FAILURE;
        }

        // Simulate RNTI initialization (could be extended based on config)
        new_pdu->rnti.type = strdup("default_rnti_type");  // Placeholder for dynamic type
        new_pdu->rnti.data = malloc(10);  // Allocate space for data

        if (!new_pdu->rnti.data) {
