            new_pdu->optional_extension = malloc(20);  // Placeholder size
            if (!new_pdu->optional_extension) {
                log_error("Allocation failure for optional extension.");
                free(new_pdu->rnti.data);
                free(new_pdu->rnti.type);
                free(new_pdu);
                while (--i >= 0) free(nfa_list[i]);
                free(nfa_list);
                nfa_list = NULL;
                pthread_mutex_unlock(&list_lock);
                return ALLOCATION_FAILURE;
            }
        } else {
            new_pdu->optional_extension = NULL;
        }

        nfa_list[i] = new_pdu;
    }

    nfa_count = new_size;  // Update the count of structures
    pthread_mutex_unlock(&list_lock);

    return SUCCESS;
}

void log_error(const char *message) {
