#define MAX_RETRIES 3
#define MIN_BUFFER_SIZE 128
#define MAX_BUFFER_SIZE 4096

typedef struct {
    int ue_info_tag;
    unsigned long rnti;
    void *buffer;
} NFAPI_MESSAGE_PDU_T;

typedef struct {
    // Placeholder for external network parameters source
    size_t (*get_payload_size)(int ue_info_tag);
    int available;
} NetworkParameterSource;

// Simulated function to check system hardware compatibility
int is_hardware_compatible() {
    return 1; // Assume always compatible in this simulation
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

NFAPI_MESSAGE_PDU_T* initialize_nfa_message(int ue_info_tag, unsigned long rnti, NetworkParameterSource source) {
    if (!is_hardware_compatible()) {
        log_error("Incompatible hardware platform.");
        return NULL;
    }

    NFAPI_MESSAGE_PDU_T *message = malloc(sizeof(NFAPI_MESSAGE_PDU_T));
    if (!message) {
        log_error("Memory allocation failed for NFAPI_MESSAGE_PDU_T structure.");
        return NULL;
    }

    message->ue_info_tag = ue_info_tag;
    message->rnti = rnti;

    size_t payload_size = 0;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (source.available) {
            payload_size = source.get_payload_size(ue_info_tag);
            if (payload_size > 0 && payload_size <= MAX_BUFFER_SIZE) {
                break;
            }
        } else {
            log_error("Network parameter source temporarily unavailable.");
        }
        retries++;
        time_t delay = rand() % 1000 / 100.0; // Random sleep between 0 and 1 second
        sleep(delay);
    }

    if (payload_size == 0) {
        free(message);
        return NULL;
    }

    size_t buffer_size = payload_size > MIN_BUFFER_SIZE ? payload_size : MIN_BUFFER_SIZE;
    message->buffer = malloc(buffer_size);
    if (!message->buffer) {
        log_error("Memory allocation failed for downlink data buffer.");
        free(message);
        return NULL;
    }

    // Zero out the buffer
    memset(message->buffer, 0, buffer_size);

    return message;
}

void free_nfa_message(NFAPI_MESSAGE_PDU_T *message) {
    if (message) {
        if (message->buffer) {
            free(message->buffer);
        }
        free(message);
    }
}
