#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_LIST_SIZE 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} NFAList;

void log_message(const char* message) {
    time_t now = time(NULL);
    printf("%s: %s\n", ctime(&now), message);
}

int isValidRNTI(unsigned short rnti) {
    return (rnti >= 0x0001 && rnti <= 0xFFFF);
}

NFAList* createList() {
    NFAList* list = (NFAList*)malloc(sizeof(NFAList));
    if (!list) {
        log_message("Memory allocation failed for NFAList");
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void freeList(NFAList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int addElement(NFAList* list, NFAPI_CRC_INDICATION_PDU_T element, int logFlag) {
    if (!isValidRNTI(element.RNTI)) {
        log_message("Invalid RNTI value");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_LIST_SIZE) {
        log_message("Warning: List size exceeded, capping at 10,000 elements.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        log_message("Memory allocation failed for new node");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    newNode->data = element;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;

    if (logFlag) {
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "Created NFAPI_CRC_INDICATION_PDU_T: RX_UE_INFORMATION_TAG=%d, RNTI=0x%04X, CRCFLAG=%d",
                 element.RX_UE_INFORMATION_TAG, element.RNTI, element.CRCFLAG);
        log_message(buffer);
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int main() {
    NFAList* list = createList();
    if (!list) return -1;

    srand(time(NULL));

    for (size_t i = 0; i < MAX_LIST_SIZE + 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element = { .RX_UE_INFORMATION_TAG = i,
                                               .RNTI = rand() % 0x10000,
                                               .CRC_INDICATION_REL8_TAG = i * 2,
                                               .CRCFLAG = rand() % 2 };
        addElement(list, element, 1);
    }

    freeList(list);
    return 0;
}
