// Mock structures representing database and network operations
typedef struct {
    int status;
    char *error_message;
} DatabaseResult;

DatabaseResult db_store_ue_context(const void *context, size_t size);
DatabaseResult db_retrieve_ue_context(uint64_t imsi, void **context, size_t *size);

// External tags
#define RX_UE_INFORMATION_TAG 0x01
#define RNTI_TAG               0x02
#define CRC_INDICATION_REL8_TAG 0x03

typedef struct {
    uint64_t imsi; // Unique IMSI
    uint32_t rnti; // Unique RNTI
    int crcflag;   // Randomly set CRCFLAG
} UEContext;

typedef struct {
    uint64_t incoming_bytes;
    uint64_t outgoing_bytes;
} TrafficStats;

struct UEContextFull {
    UEContext base;
    TrafficStats stats;
};

// Mutex for thread safety and dynamic array management
pthread_mutex_t context_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    struct UEContextFull *contexts;
    size_t capacity;
    size_t count;
} ContextManager;

void init_context_manager(ContextManager *manager) {
    manager->capacity = 10; // Initial capacity
    manager->count = 0;
    manager->contexts = malloc(manager->capacity * sizeof(struct UEContextFull));
}

void free_context_manager(ContextManager *manager) {
    free(manager->contexts);
    pthread_mutex_destroy(&context_lock);
}

// Add or update a context in the dynamic array and database
void add_or_update_context(ContextManager *manager, const struct UEContextFull *new_context) {
    pthread_mutex_lock(&context_lock);

    // Check for existing context by IMSI
    size_t index = 0;
    while (index < manager->count && manager->contexts[index].base.imsi != new_context->base.imsi) {
        index++;
    }

    if (index < manager->count) {
        // Update existing context
        memcpy(&manager->contexts[index], new_context, sizeof(struct UEContextFull));
    } else {
        // Add new context
        if (manager->count == manager->capacity) {
            manager->capacity *= 2;
            manager->contexts = realloc(manager->contexts, manager->capacity * sizeof(struct UEContextFull));
        }
        memcpy(&manager->contexts[manager->count], new_context, sizeof(struct UEContextFull));
        manager->count++;
    }

    // Store in database with error handling
    DatabaseResult result = db_store_ue_context(new_context, sizeof(*new_context));
    if (result.status != 0) {
        fprintf(stderr, "Database Error: %s\n", result.error_message);
    }

    pthread_mutex_unlock(&context_lock);
}

// Retrieve statistics for a specific IMSI
TrafficStats* get_traffic_stats(ContextManager *manager, uint64_t imsi) {
    pthread_mutex_lock(&context_lock);

    size_t index = 0;
    while (index < manager->count && manager->contexts[index].base.imsi != imsi) {
        index++;
    }

    if (index == manager->count) {
        pthread_mutex_unlock(&context_lock);
        return NULL; // IMSI not found
    }

    TrafficStats *stats = &manager->contexts[index].stats;
    pthread_mutex_unlock(&context_lock);

    // Optionally retrieve from database as a fallback
    void *context;
    size_t context_size;
    DatabaseResult db_result = db_retrieve_ue_context(imsi, &context, &context_size);
    if (db_result.status == 0 && context != NULL) {
        memcpy(stats, ((struct UEContextFull*)context)->stats, sizeof(TrafficStats));
    } else if (db_result.status != 0) {
        fprintf(stderr, "Database Error: %s\n", db_result.error_message);
    }

    return stats;
}

// Main function for testing
int main() {
    ContextManager manager;
    init_context_manager(&manager);

    srand(time(NULL)); // Seed random number generator

    struct UEContextFull context = {
        .base = { .imsi = 123456789, .rnti = 987654321 },
        .stats = { .incoming_bytes = 0, .outgoing_bytes = 0 }
    };
    context.base.crcflag = rand() % 2; // Randomly set CRCFLAG

    add_or_update_context(&manager, &context);

    TrafficStats *retrieved_stats = get_traffic_stats(&manager, 123456789);
    if (retrieved_stats != NULL) {
        printf("Traffic Stats - Incoming: %lu, Outgoing: %lu\n", retrieved_stats->incoming_bytes, retrieved_stats->outgoing_bytes);
    }

    free_context_manager(&manager);
    return 0;
}
