        try {
            processBuilder.redirectErrorStream(true);
            processBuilder.redirectOutput(ProcessBuilder.Redirect.to(tempFile = File.createTempFile("output", ".txt")));
            Process process = processBuilder.start();

            InputStream inputStream = process.getInputStream();
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }
            }

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                System.err.println("Command exited with error code: " + exitCode);
            }
        } catch (IOException | InterruptedException e) {
            e.printStackTrace(); // Handle exceptions appropriately
        } finally {
            if (tempFile != null && tempFile.exists()) {
                boolean deleted = tempFile.delete();
                if (!deleted) {
                    System.err.println("Temporary file could not be deleted: " + tempFile.getAbsolutePath());
                }
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
