// Thread-local storage for random number generation
__thread unsigned int tls_rnd_seed;

// Mutex for thread safety across multiple allocations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int generate_nfa_pdu_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t n) {
    if (n == 0 || list == NULL) return -1;

    *list = calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) return -2;

    pthread_mutex_lock(&mutex);

    // Generate unique RNTIs and random CRC flags
    for (size_t i = 0; i < n; ++i) {
        do {
            (*list)[i].rnti = rand_r(&tls_rnd_seed);
        } while (is_duplicate_rnti(*list, i));

        (*list)[i].ue_info_tag.rnti = (*list)[i].rnti;
        (*list)[i].crc_tag.CRCFLAG = rand_r(&tls_rnd_seed) & 1; // Randomize CRCFLAG to be either 0 or 1
    }

    pthread_mutex_unlock(&mutex);

    return 0;
}

int is_duplicate_rnti(const NFAPI_CRC_INDICATION_PDU_T *list, size_t current_index) {
    for (size_t i = 0; i < current_index; ++i) {
        if (list[i].rnti == list[current_index].rnti) return 1;
    }
    return 0;
}

void free_nfa_pdu_list(NFAPI_CRC_INDICATION_PDU_T *list, size_t n) {
    if (list != NULL) {
        free(list);
    }
}

int serialize_to_binary_file(const NFAPI_CRC_INDICATION_PDU_T *list, size_t n, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), n, file);

    fclose(file);
    return 0;
}

int main() {
