        }

        // Check for duplicate RNTIs
        for (size_t j = 0; j < i; ++j) {
            if (list->data[j].rnti == rnti) {
                log_error("Duplicate RNTI detected.");
                pthread_mutex_unlock(&list->lock);
                return;
            }
        }

        // Set RX_UE_INFORMATION_TAG
        pdu->ueTag = (RX_UE_INFORMATION_TAG){.rnti = rnti};

        // Populate CRC_INDICATION_REL8_TAG with random CRCFLAG based on threshold
        srand(time(NULL) + i);  // Seed for randomness
        int crcFlag = rand() % 100 < crc_threshold ? 1 : 0;
        pdu->crcIndication.crcFlag = crcFlag;

        // Save to database, handle potential errors gracefully
        if (db_save_pdu(pdu) != 0) {
            log_error("Failed to save PDU to the database.");
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    log_info("Successfully populated PDU list.");
    pthread_mutex_unlock(&list->lock);
}

void cleanup_pdu_list(PDUList* list) {
    if (list) {
        free(list->data);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}
```

