// Assuming the structures are defined as follows:
typedef struct {
    // Dummy fields for illustration purposes
    int id;
} TX_RRC_UE_CONTEXT;

typedef struct {
    // Dummy fields for illustration purposes
    int id;
} RX_RRC_UE_CONTEXT;

typedef struct {
    TX_RRC_UE_CONTEXT txContext;
    RX_RRC_UE_CONTEXT rxContext;
    char *uplinkBuffer;
    char *downlinkBuffer;
    size_t bufferLength; // Length of the allocated buffers
} LTE_PHY_TX_RX_CONTEXT;

// Global dynamic array management structure
typedef struct {
    LTE_PHY_TX_RX_CONTEXT **contexts;
    size_t capacity;
    size_t count;
} DynamicArrayManager;

// Function prototypes
void initDynamicArray(DynamicArrayManager *manager, size_t initialCapacity);
void freeResources(DynamicArrayManager *manager);

LTE_PHY_TX_RX_CONTEXT* addOrUpdateContext(
    DynamicArrayManager *manager,
    int ueId,
    const TX_RRC_UE_CONTEXT *newTxContext,
    const RX_RRC_UE_CONTEXT *newRxContext,
    size_t bufferLength
) {
    // Find existing context or create a new one if not found
    LTE_PHY_TX_RX_CONTEXT *context = NULL;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->txContext.id == ueId) {
            context = manager->contexts[i];
            break;
        }
    }

    if (!context) {
        // Resize array if needed
        if (manager->count >= manager->capacity) {
            size_t newCapacity = manager->capacity > 0 ? manager->capacity * 2 : 16;
            LTE_PHY_TX_RX_CONTEXT **newContexts = realloc(manager->contexts, newCapacity * sizeof(LTE_PHY_TX_RX_CONTEXT*));
            if (!newContexts) {
                perror("Failed to reallocate memory");
                exit(EXIT_FAILURE);
            }
            memset(newContexts + manager->count, 0, (newCapacity - manager->capacity) * sizeof(LTE_PHY_TX_RX_CONTEXT*));
            manager->contexts = newContexts;
            manager->capacity = newCapacity;
        }

        // Allocate and initialize a new context
        context = malloc(sizeof(LTE_PHY_TX_RX_CONTEXT));
        if (!context) {
            perror("Failed to allocate memory for context");
            exit(EXIT_FAILURE);
        }
        context->txContext = *newTxContext;
        context->rxContext = *newRxContext;
        context->bufferLength = bufferLength;
        context->uplinkBuffer = malloc(bufferLength);
        context->downlinkBuffer = malloc(bufferLength);

        if (!context->uplinkBuffer || !context->downlinkBuffer) {
            perror("Failed to allocate buffers");
            free(context->uplinkBuffer);
            free(context->downlinkBuffer);
            free(context);
            exit(EXIT_FAILURE);
        }

        manager->contexts[manager->count++] = context;
    } else {
        // Update existing context
        context->txContext = *newTxContext;
        context->rxContext = *newRxContext;

        if (context->bufferLength < bufferLength) {
            char *newUplinkBuffer = realloc(context->uplinkBuffer, bufferLength);
            char *newDownlinkBuffer = realloc(context->downlinkBuffer, bufferLength);

            if (!newUplinkBuffer || !newDownlinkBuffer) {
                perror("Failed to reallocate buffers");
                exit(EXIT_FAILURE);
            }
            context->uplinkBuffer = newUplinkBuffer;
            context->downlinkBuffer = newDownlinkBuffer;
        }

        context->bufferLength = bufferLength;
    }

    return context;
}

void freeResources(DynamicArrayManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        LTE_PHY_TX_RX_CONTEXT *context = manager->contexts[i];
        if (context) {
            free(context->uplinkBuffer);
            free(context->downlinkBuffer);
            free(context);
        }
    }
    free(manager->contexts);
    manager->contexts = NULL;
    manager->capacity = 0;
    manager->count = 0;
}

void initDynamicArray(DynamicArrayManager *manager, size_t initialCapacity) {
    manager->contexts = malloc(initialCapacity * sizeof(LTE_PHY_TX_RX_CONTEXT*));
    if (!manager->contexts) {
        perror("Failed to allocate memory for contexts");
        exit(EXIT_FAILURE);
    }
    memset(manager->contexts, 0, initialCapacity * sizeof(LTE_PHY_TX_RX_CONTEXT*));
    manager->capacity = initialCapacity;
    manager->count = 0;
}

// Usage example
int main() {
    DynamicArrayManager manager;
    initDynamicArray(&manager, 10);

    TX_RRC_UE_CONTEXT txContext = {.id = 1};
    RX_RRC_UE_CONTEXT rxContext = {.id = 1};

    addOrUpdateContext(&manager, txContext.id, &txContext, &rxContext, 1024);

    freeResources(&manager);
    return 0;
}
