typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;  // Mutex for thread safety
} DynamicArray;

// Helper function to initialize the dynamic array
DynamicArray* init_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicArray *da = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(alignof(NFAPI_CRC_INDICATION_PDU_T), initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->size = 0;
    da->capacity = initial_capacity;
    pthread_mutex_init(&da->lock, NULL);

    return da;
}

// Helper function to resize the dynamic array
int resize_dynamic_array(DynamicArray *da, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)aligned_realloc(da->array, alignof(NFAPI_CRC_INDICATION_PDU_T), new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return -1;

    da->array = new_array;
    da->capacity = new_capacity;

    return 0;
}

// Helper function to check for unique RNTI
int is_unique_rnti(DynamicArray *da, RNTI rnti) {
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].rnti == rnti) return 0;
    }
    return 1;
}

// Function to add an element at a specified position
int add_element(DynamicArray *da, size_t pos, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&da->lock);

    if (pos > da->size) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Invalid position
    }

    if (!is_unique_rnti(da, item.rnti)) {
        pthread_mutex_unlock(&da->lock);
        fprintf(stderr, "Error: Duplicate RNTI detected. Discarding element.\n");
        return -2;
    }

    if (da->size == da->capacity) {
        if (resize_dynamic_array(da, da->capacity * 2) != 0) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Allocation failure
        }
    }

    memmove(&da->array[pos + 1], &da->array[pos], (da->size - pos) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->array[pos] = item;
    ++da->size;

    pthread_mutex_unlock(&da->lock);
    return 0; // Success
}

// Function to periodically update elements from an external source
void update_from_external_source(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);

    // Simulate network latency and data retrieval with a sleep call
    // This is where you'd integrate actual network logic
    struct timespec delay = {0, 500000000}; // 0.5 second
    nanosleep(&delay, NULL);

    for (size_t i = 0; i < da->size; ++i) {
        // Simulate data update - this would be replaced with actual updates from the external source
        da->array[i].rx_ue_info_tag = /* ... */; 
        da->array[i].rnti = /* ... */;
    }

    pthread_mutex_unlock(&da->lock);
}

// Function to free memory allocated by the dynamic array manager
void free_dynamic_array(DynamicArray *da) {
    if (da) {
        pthread_mutex_destroy(&da->lock);
        if (da->array) aligned_free(da->array);
        free(da);
    }
}
