    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    unsigned long successful_allocations;
    unsigned long allocation_failures;
} CRC_Indication_Manager;

bool validate_handle(void* handle) {
    // Placeholder for actual validation logic
    return handle != NULL;
}

bool are_network_settings_valid() {
    // Placeholder for network configuration checks
    return true;  // Assume settings are valid for now
}

void log_message(const char *message) {
    printf("%s\n", message);
}

int compare_RNTI(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pduA = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *pduB = (NFAPI_CRC_INDICATION_PDU_T *)b;
    return pduA->RNTI - pduB->RNTI;
}

CRC_Indication_Manager* create_crc_indication_manager() {
    CRC_Indication_Manager *manager = malloc(sizeof(CRC_Indication_Manager));
    if (!manager) {
        log_message("Failed to allocate memory for manager.");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->array = NULL;
    manager->size = 0;
    manager->capacity = 0;
    manager->successful_allocations = 0;
    manager->allocation_failures = 0;

    return manager;
}

void destroy_crc_indication_manager(CRC_Indication_Manager *manager) {
    if (manager) {
        pthread_mutex_lock(&manager->lock);
        free(manager->array);
        pthread_mutex_unlock(&manager->lock);

        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

bool resize_array(CRC_Indication_Manager *manager, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        manager->allocation_failures++;
        log_message("Failed to reallocate memory for CRC indication array.");
        return false;
    }

    manager->array = new_array;
    manager->capacity = new_capacity;

    manager->successful_allocations++;

    return true;
}

bool insert_crc_indication(CRC_Indication_Manager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!validate_handle(manager)) {
        log_message("Invalid handle provided.");
        return false;
    }

    if (!are_network_settings_valid()) {
        log_message("Network configuration is invalid or outdated.");
        return false;
    }

    pthread_mutex_lock(&manager->lock);

    // Check for duplicate RNTI
    qsort(manager->array, manager->size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_RNTI);
    if (manager->size > 0 && manager->array[manager->size - 1].RNTI == pdu.RNTI) {
        log_message("Duplicate RNTI detected. Insertion discarded.");
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    // Resize array if necessary
    if (manager->size >= manager->capacity && !resize_array(manager, manager->capacity > 0 ? manager->capacity * 2 : 16)) {
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    // Insert new element
    manager->array[manager->size] = pdu;
    manager->size++;

    log_message("CRC indication inserted successfully.");

    pthread_mutex_unlock(&manager->lock);

    return true;
}

void example_usage() {
    CRC_Indication_Manager *manager = create_crc_indication_manager();
    if (!manager) return;

    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = i, .RNTI = rand() % 100000, .crcTag = { .CRCFLAG = rand() & 1 } };
        insert_crc_indication(manager, pdu);
    }

    destroy_crc_indication_manager(manager);
}

int main() {
    example_usage();
    return 0;
}
