#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG CRC;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_unique(NFAPI_CRC_INDICATION_PDU_T* pdu, List* list) {
    Node* current = list->head;
    while (current != NULL) {
        if ((current->data.RX_UE_INFORMATION_TAG == pdu->RX_UE_INFORMATION_TAG) &&
            (current->data.RNTI == pdu->RNTI)) {
            return 0; // Not unique
        }
        current = current->next;
    }
    return 1; // Unique
}

int add_pdu(List* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!list || !pdu) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -2; // List full
    }

    if (!is_unique(pdu, list)) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Duplicate entry
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -4; // Memory allocation failed
    }
    memcpy(&new_node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void free_list(List* list) {
    if (!list) return;

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void generate_random_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, unsigned int seed) {
    if (!pdu) return;

    pdu->RX_UE_INFORMATION_TAG = rand_r(&seed) % (1 << 32);
    pdu->RNTI = rand_r(&seed) % (1 << 16);
    pdu->CRC.CRCFLAG = rand_r(&seed) & 0x01;
}

void manage_nfa_list(List* list, size_t n) {
    if (!list || n == 0) return;

    unsigned int seed = time(NULL);

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        generate_random_pdu(&pdu, seed);
        int result = add_pdu(list, &pdu);

        if (result != 0 && result != -2) { // Handle non-failure and full list
            fprintf(stderr, "Error: Unable to add PDU. Error code: %d\n", result);
            break;
        }
    }
}

int main() {
    List* nfa_list = create_list();
    if (!nfa_list) {
        fprintf(stderr, "Failed to create NFA list.\n");
        return -1;
    }

    manage_nfa_list(nfa_list, 10000);

    free_list(nfa_list);
    return 0;
}
