#define MAX_TAG_LENGTH 256

typedef struct {
    char RX_UE_INFORMATION_TAG[MAX_TAG_LENGTH];
    int RNTI;
    unsigned int CRCFLAG; // Ensure bit width compatibility
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    SUCCESS,
    MEMORY_ALLOCATION_ERROR,
    INVALID_INPUT_FORMAT,
    DNS_RESOLUTION_FAILED,
    INTEGER_READING_ERROR,
    NETWORK_CONDITIONS_ERROR
} ErrorCode;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

ErrorCode dynamicArrayAndMaxValue(const char* hostname, u_char *statusMessage) {
    pthread_mutex_lock(&lock);

    int N;
    if (scanf("%d", &N) != 1 || N < 0) {
        strncpy((char *)statusMessage, "Invalid input for number of structures.", MAX_TAG_LENGTH);
        pthread_mutex_unlock(&lock);
        return INTEGER_READING_ERROR;
    }

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        strncpy((char *)statusMessage, "Memory allocation failed.", MAX_TAG_LENGTH);
        pthread_mutex_unlock(&lock);
        return MEMORY_ALLOCATION_ERROR;
    }

    // Populate the array
    for (int i = 0; i < N; ++i) {
        printf("Enter RX_UE_INFORMATION_TAG: ");
        if (scanf("%255s", array[i].RX_UE_INFORMATION_TAG) != 1 || strlen(array[i].RX_UE_INFORMATION_TAG) == 0) {
            free(array);
            strncpy((char *)statusMessage, "Invalid tag format.", MAX_TAG_LENGTH);
            pthread_mutex_unlock(&lock);
            return INVALID_INPUT_FORMAT;
        }

        printf("Enter RNTI: ");
        if (scanf("%d", &array[i].RNTI) != 1 || array[i].RNTI <= 0) {
            free(array);
            strncpy((char *)statusMessage, "Invalid RNTI format.", MAX_TAG_LENGTH);
            pthread_mutex_unlock(&lock);
            return INVALID_INPUT_FORMAT;
        }

        // Randomly set CRCFLAG within specified bit width
        array[i].CRCFLAG = rand() & 0x1F; // Example: limit to 5 bits
    }

    int *integers = (int*)malloc(N * sizeof(int));
    if (!integers) {
        free(array);
        strncpy((char *)statusMessage, "Memory allocation failed.", MAX_TAG_LENGTH);
        pthread_mutex_unlock(&lock);
        return MEMORY_ALLOCATION_ERROR;
    }

    printf("Enter sequence of integers: ");
    for (int i = 0; i < N; ++i) {
        if (scanf("%d", &integers[i]) != 1) {
            free(array);
            free(integers);
            strncpy((char *)statusMessage, "Invalid integer format.", MAX_TAG_LENGTH);
            pthread_mutex_unlock(&lock);
            return INTEGER_READING_ERROR;
        }
    }

    // Find the largest integer
    int max = integers[0];
    for (int i = 1; i < N; ++i) {
        if (integers[i] > max) {
            max = integers[i];
        }
    }
    printf("Largest integer: %d\n", max);

    // Resolve hostname to IP address
    struct hostent *host;
    struct in_addr addr;
    char ipString[INET_ADDRSTRLEN];

    if ((host = gethostbyname(hostname)) == NULL) {
        free(array);
        free(integers);
        strncpy((char *)statusMessage, "DNS resolution failed.", MAX_TAG_LENGTH);
        pthread_mutex_unlock(&lock);
        return DNS_RESOLUTION_FAILED;
    }

    addr.s_addr = *(u_long *) host->h_addr_list[0];
    if (inet_ntop(AF_INET, &addr, ipString, INET_ADDRSTRLEN) == NULL) {
        free(array);
        free(integers);
        strncpy((char *)statusMessage, "IP address conversion failed.", MAX_TAG_LENGTH);
        pthread_mutex_unlock(&lock);
        return NETWORK_CONDITIONS_ERROR;
    }

    printf("Resolved IP Address: %s\n", ipString);

    // Convert to u_char array
    inet_pton(AF_INET, ipString, (u_char *)statusMessage + 1); // Skip first byte for error code

    free(array);
    free(integers);
    pthread_mutex_unlock(&lock);
    return SUCCESS;
}

int main() {
    u_char statusMessage[MAX_TAG_LENGTH];
    ErrorCode result = dynamicArrayAndMaxValue("example.com", statusMessage);

    if (result != SUCCESS) {
        printf("Error: %d\n", result);
        printf("Status Message: %s\n", (char *)statusMessage + 1); // Skip first byte
    }

    return 0;
}
