    }

    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond_var, NULL);
    return list;
}

bool is_unique(const CRCList *list, unsigned int rx_tag, unsigned int rnti) {
    for (size_t i = 0; i < list->count; i++) {
        if (list->entries[i]->RX_UE_INFORMATION_TAG == rx_tag &&
            list->entries[i]->RNTI == rnti) {
            return false;
        }
    }
    return true;
}

int add_crc_indication(CRCList *list, unsigned int rx_tag, unsigned int rnti) {
    if (!list || !is_unique(list, rx_tag, rnti)) {
        return ERROR_MEMORY_FULL; // or another error code for duplicate
    }

    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return ERROR_MEMORY_FULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry) {
        pthread_mutex_unlock(&list->lock);
        return ERROR_MEMORY_FULL;
    }

    entry->RX_UE_INFORMATION_TAG = rx_tag;
    entry->RNTI = rnti;
    entry->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    list->entries[list->count++] = entry;

    // Notify any waiting threads
    pthread_cond_signal(&list->cond_var);
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void free_crc_list(CRCList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; i++) {
        free(list->entries[i]);
    }
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond_var);
    free(list);
}

void populate_crc_list(CRCList *list, int num_entries) {
    srand(time(NULL));
    for (int i = 0; i < num_entries; ++i) {
        unsigned int rx_tag = rand() % 100000;
        unsigned int rnti = rand() % 100000;

        if (add_crc_indication(list, rx_tag, rnti) != 0) {
            printf("Error: Unable to add CRC indication. List may be full or memory issue.\n");
            break;
        }
    }
}

int main() {
    CRCList *list = create_crc_list();
    if (!list) {
        fprintf(stderr, "Failed to create CRC list\n");
        return EXIT_FAILURE;
    }

    populate_crc_list(list, 15000); // Example with more entries than max

    free_crc_list(list);
    return EXIT_SUCCESS;
}
