#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
} UNIQUE_ID_T;

typedef struct {
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    UNIQUE_ID_T unique_id;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    unsigned int size;
    pthread_mutex_t lock;
} LRUCache;

LRUCache* create_cache(unsigned int capacity) {
    LRUCache* cache = (LRUCache*)malloc(sizeof(LRUCACHE));
    if (!cache) return NULL;

    cache->head = NULL;
    cache->tail = NULL;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void free_node(Node* node) {
    if (node) free(node);
}

void move_to_head(LRUCache* cache, Node* node) {
    if (node == cache->head) return;

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;

    if (cache->tail == node) cache->tail = node->prev;

    node->next = cache->head;
    node->prev = NULL;

    if (cache->head) cache->head->prev = node;
    cache->head = node;

    if (!cache->tail) cache->tail = node;
}

void remove_node(LRUCache* cache, Node* node) {
    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;

    if (cache->head == node) cache->head = node->next;
    if (cache->tail == node) cache->tail = node->prev;

    free_node(node);
}

Node* get_node(LRUCache* cache, UNIQUE_ID_T unique_id) {
    Node* current = cache->head;
    while (current) {
        if (current->data.unique_id.RX_UE_INFORMATION_TAG == unique_id.RX_UE_INFORMATION_TAG &&
            current->data.unique_id.RNTI == unique_id.RNTI) {
            move_to_head(cache, current);
            return current;
        }
        current = current->next;
    }
    return NULL;
}

int add_node(LRUCache* cache, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&cache->lock);

    UNIQUE_ID_T unique_id = data.unique_id;

    Node* existing_node = get_node(cache, unique_id);
    if (existing_node) {
        pthread_mutex_unlock(&cache->lock);
        return 0;
    }

    if (cache->size >= INITIAL_CAPACITY) {
        remove_node(cache, cache->tail);
        cache->size--;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&cache->lock);
        return -1;
    }

    new_node->data = data;
    new_node->next = cache->head;
    new_node->prev = NULL;

    if (cache->head) cache->head->prev = new_node;
    cache->head = new_node;

    if (!cache->tail) cache->tail = new_node;

    cache->size++;
    pthread_mutex_unlock(&cache->lock);
    return 1;
}

void free_cache(LRUCache* cache) {
    Node* current = cache->head;
    while (current) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

int populate_dynamic_list(NFAPI_CRC_INDICATION_PDU_T** list, unsigned int max_entries) {
    if (!list || !max_entries) return -1;

    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) return -1;

    LRUCache* cache = create_cache(INITIAL_CAPACITY);
    if (!cache) {
        free(*list);
        return -1;
    }

    srand(time(NULL));

    for (unsigned int i = 0; i < max_entries; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        entry.unique_id.RX_UE_INFORMATION_TAG = rand() % 10000;
        entry.unique_id.RNTI = rand() % 10000;
        entry.crc_indication_rel8_tag.CRCFLAG = rand() & 1;

        if (add_node(cache, entry) != 1) {
            // Handle graceful degradation
            printf("Cache is full or memory allocation failed.\n");
            break;
        }
    }

    free_cache(cache);
    return 0;
}

void process_list(NFAPI_CRC_INDICATION_PDU_T* list, unsigned int entries) {
    if (!list || !entries) return;

    for (unsigned int i = 0; i < entries; ++i) {
        // Process each entry
        printf("Processing UE ID: %u, RNTI: %u\n", list[i].unique_id.RX_UE_INFORMATION_TAG,
               list[i].unique_id.RNTI);
    }
}

void* process_thread(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    unsigned int entries = 10000; // Example size
    process_list(list, entries);
    return NULL;
}

int main() {
    pthread_t thread1, thread2;

    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    if (populate_dynamic_list(&list, 10000) != 0) {
        printf("Failed to populate the list.\n");
        return -1;
    }

    pthread_create(&thread1, NULL, process_thread, list);
    pthread_create(&thread2, NULL, process_thread, list);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    free(list);
    return 0;
}
