    UPLINK_NAS_MESSAGE message;
    struct Node* next;
} Node;

typedef struct {
    Node** array;  // Array of pointers to nodes (linked list)
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

// Function Prototypes
DynamicArray* create_dynamic_array();
void destroy_dynamic_array(DynamicArray* da);
int add_message(DynamicArray* da, UPLINK_NAS_MESSAGE message);
int update_message(DynamicArray* da, int nas_message_id, UPLINK_NAS_MESSAGE new_message);
