// Create a dynamic array with initial capacity
DynamicArray* create_dynamic_array() {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) {
        log_error("Failed to allocate memory for dynamic array");
        return NULL;
    }

    da->capacity = INITIAL_CAPACITY;
    da->size = 0;
    da->array = (Node**)calloc(da->capacity, sizeof(Node*));
    pthread_mutex_init(&da->lock, NULL);

    if (!da->array) {
        log_error("Failed to allocate memory for dynamic array nodes");
        free(da);
        return NULL;
    }

    return da;
}

// Destroy the dynamic array and free all resources
void destroy_dynamic_array(DynamicArray* da) {
    if (da) {
        pthread_mutex_lock(&da->lock);

        for (size_t i = 0; i < da->capacity; ++i) {
            Node* current = da->array[i];
            while (current) {
                Node* temp = current;
                current = current->next;
                free(temp);
            }
        }

        pthread_mutex_unlock(&da->lock);
        pthread_mutex_destroy(&da->lock);
        free(da->array);
        free(da);
    }
}

// Add a new message to the dynamic array
int add_message(DynamicArray* da, UPLINK_NAS_MESSAGE message) {
    if (!da) return -1;

    pthread_mutex_lock(&da->lock);

    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        Node** new_array = (Node**)realloc(da->array, new_capacity * sizeof(Node*));
        if (!new_array) {
            log_error("Failed to reallocate memory for dynamic array");
            pthread_mutex_unlock(&da->lock);
            return -1;
        }

        da->array = new_array;
        memset(new_array + da->capacity, 0, (new_capacity - da->capacity) * sizeof(Node*));
        da->capacity = new_capacity;
    }

    size_t index = message.nas_message_id % da->capacity;
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Failed to allocate memory for new node");
        pthread_mutex_unlock(&da->lock);
        return -1;
    }

    new_node->message = message;
    new_node->next = da->array[index];
    da->array[index] = new_node;
    ++da->size;

    pthread_mutex_unlock(&da->lock);

    // Compact array if necessary
    compact_array(da);

    return 0; 
}

// Update an existing message by its identifier
int update_message(DynamicArray* da, int nas_message_id, UPLINK_NAS_MESSAGE new_message) {
    if (!da) return -1;

    pthread_mutex_lock(&da->lock);

    size_t index = nas_message_id % da->capacity;
    Node* current = da->array[index];
    while (current) {
        if (current->message.nas_message_id == nas_message_id) {
            current->message = new_message;
            pthread_mutex_unlock(&da->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&da->lock);

    log_error("Message with specified NAS MESSAGE ID not found");
    return -1; 
}

// Remove a message by its identifier
int remove_message(DynamicArray* da, int nas_message_id) {
    if (!da) return -1;

    pthread_mutex_lock(&da->lock);

    size_t index = nas_message_id % da->capacity;
    Node* current = da->array[index];
    Node* prev = NULL;
    while (current) {
        if (current->message.nas_message_id == nas_message_id) {
            if (prev)
                prev->next = current->next;
            else
                da->array[index] = current->next;

            free(current);
            --da->size;

            pthread_mutex_unlock(&da->lock);

            // Compact array if necessary
            compact_array(da);

            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&da->lock);

    log_error("Message with specified NAS MESSAGE ID not found");
    return -1; 
}

// Periodically compact the array to reduce fragmentation
void compact_array(DynamicArray* da) {
    // Implementation of compaction logic here if necessary
