} LTE_UE_CONTEXT;

// Node for the linked list
typedef struct ListNode {
    LTE_UE_CONTEXT context;
    struct ListNode* next;
} ListNode;

// Dynamic List structure with thread safety and persistence capabilities
typedef struct {
    ListNode* head;
    ListNode* tail;
    pthread_mutex_t lock; // Mutex for concurrency control
    FILE* file;           // File pointer for persistence
    size_t max_entries;   // Maximum number of entries
    size_t current_size;  // Current list size
} DynamicList;

// Function to create a new list
DynamicList* create_dynamic_list(size_t max_entries, const char* filename) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->file = fopen(filename, "wb+");
    if (!list->file) {
        free(list);
        return NULL;
    }
    list->max_entries = max_entries;
    list->current_size = 0;

    // Load existing data from file
    load_from_file(list);

    return list;
}

// Function to destroy the list and clean up resources
void destroy_dynamic_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current) {
        ListNode* temp = current;
        current = current->next;
        free(temp);
    }
    fclose(list->file);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Function to add a new LTE_UE_CONTEXT
int add_context(DynamicList* list, LTE_UE_CONTEXT context) {
    if (pthread_mutex_lock(&list->lock) != 0) return -1;

    // Check for max entries and implement LRU eviction policy
    if (list->current_size >= list->max_entries) {
        evict_lru_entry(list);
    }

    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->context = context;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->current_size++;

    pthread_mutex_unlock(&list->lock);

    // Persist to disk
    persist_to_file(list);
    return 0;
}

// Function to remove a context by RNTI
int remove_context(DynamicList* list, int rnti) {
    if (pthread_mutex_lock(&list->lock) != 0) return -1;

    ListNode *current = list->head, *prev = NULL;
    while (current && current->context.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Not found
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }
    if (current == list->tail) {
        list->tail = prev;
    }

    free(current);
    list->current_size--;

    pthread_mutex_unlock(&list->lock);

    // Persist to disk
    persist_to_file(list);
    return 0;
}

// Function to iterate over the list and apply a function to each context
void iterate_list(DynamicList* list, void (*func)(LTE_UE_CONTEXT)) {
    if (pthread_mutex_lock(&list->lock) != 0) return;

    ListNode* current = list->head;
    while (current) {
        func(current->context);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to persist the list to disk
void persist_to_file(DynamicList* list) {
    if (fseek(list->file, 0, SEEK_SET) != 0) return;

    ListNode* current = list->head;
    while (current) {
        fwrite(&(current->context), sizeof(LTE_UE_CONTEXT), 1, list->file);
        current = current->next;
    }

    // Seek to the end of file after writing
    if (fseek(list->file, 0, SEEK_END) != 0) return;
}

// Function to load the list from disk
void load_from_file(DynamicList* list) {
    LTE_UE_CONTEXT context;
    while (fread(&context, sizeof(LTE_UE_CONTEXT), 1, list->file)) {
        add_context(list, context);
