#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define MAX_ENTRIES 1000 // Configurable maximum number of entries
#define HASH_TABLE_SIZE 1024

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG; 
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashNode {
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_PDU_T data;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** table;
    size_t count;
    pthread_mutex_t lock;
} ThreadSafeHashTable;

static unsigned int hash(uint16_t rnti) {
    return rnti % HASH_TABLE_SIZE;
}

ThreadSafeHashTable* create_hash_table() {
    ThreadSafeHashTable* ht = malloc(sizeof(ThreadSafeHashTable));
    if (!ht) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    ht->table = calloc(HASH_TABLE_SIZE, sizeof(HashNode*));
    if (!ht->table) {
        perror("Failed to allocate memory for hash table buckets");
        free(ht);
        exit(EXIT_FAILURE);
    }
    ht->count = 0;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

int insert_entry(ThreadSafeHashTable* ht, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (ht->count >= MAX_ENTRIES) return -1; // Table full

    unsigned int index = hash(entry.RNTI);

    pthread_mutex_lock(&ht->lock);

    for (HashNode* node = ht->table[index]; node != NULL; node = node->next) {
        if (node->RNTI == entry.RNTI) { // Duplicate RNTI found
            pthread_mutex_unlock(&ht->lock);
            return -2;
        }
    }

    HashNode* newNode = malloc(sizeof(HashNode));
    if (!newNode) {
        perror("Failed to allocate memory for new hash node");
        pthread_mutex_unlock(&ht->lock);
        return -3; // Memory allocation error
    }

    newNode->RNTI = entry.RNTI;
    newNode->data = entry;
    newNode->next = ht->table[index];
    ht->table[index] = newNode;

    ht->count++;

    pthread_mutex_unlock(&ht->lock);
    return 0; // Success
}

void free_hash_table(ThreadSafeHashTable* ht) {
    for (size_t i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashNode* node = ht->table[i];
        while (node != NULL) {
            HashNode* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(ht->table);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

void test_insertions() {
    ThreadSafeHashTable* ht = create_hash_table();

    // Simulate concurrent inserts
    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        entry.RX_UE_INFORMATION_TAG = rand() % 256;
        entry.RNTI = rand() % HASH_TABLE_SIZE;
        entry.CRCFLAG = rand() & 1;

        pthread_create(&threads[i], NULL, (void *(*)(void *))insert_entry, ht);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_hash_table(ht);
}

int main() {
    test_insertions();
    return 0;
}
```

### Key Points:
- A simple hash table is implemented to manage the entries, allowing efficient lookups and insertions.
- The `pthread_mutex` is used for thread safety during modifications to shared resources like the hash table.
- Error handling is included for memory allocation failures, duplicates, and reaching maximum entry count.
- Memory management ensures no leaks by freeing allocated nodes when deleting the hash table.
- The function is designed with future extensibility in mind.']

