#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 10000
#define MEMORY_THRESHOLD_PERCENTAGE 90

typedef struct {
    int RNTI;
    int CRCFLAG;
    time_t last_update_timestamp;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    char CRC_INDICATION_REL8_TAG[64];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    int priority;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PriorityQueue;

PriorityQueue* create_priority_queue() {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    pq->head = NULL;
    pthread_mutex_init(&pq->lock, NULL);
    return pq;
}

void destroy_priority_queue(PriorityQueue* pq) {
    Node* current = pq->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&pq->lock);
    free(pq);
}

int is_duplicate(RX_UE_INFORMATION_TAG* entries, int count, RX_UE_INFORMATION_TAG new_entry) {
    for (int i = 0; i < count; ++i) {
        if (entries[i].RNTI == new_entry.RNTI) {
            return 1;
        }
    }
    return 0;
}

void log_message(const char* message) {
    // Asynchronous logging implementation
    printf("%s\n", message);
}

int get_system_memory_usage_percentage() {
    // Mock function to simulate system memory usage retrieval
    return rand() % 100; // Random percentage for demonstration purposes
}

void alert_if_memory_exceeds_threshold(int threshold) {
    int current_usage = get_system_memory_usage_percentage();
    if (current_usage > threshold) {
        log_message("Memory usage exceeded the threshold.");
    }
}

int compare_priority(Node* a, Node* b) {
    // User-defined function to evaluate priority
    return a->priority - b->priority;
}

void insert_with_priority(PriorityQueue* pq, NFAPI_CRC_INDICATION_PDU_T data, int priority) {
    pthread_mutex_lock(&pq->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed.");
        pthread_mutex_unlock(&pq->lock);
        return;
    }
    new_node->data = data;
    new_node->priority = priority;
    new_node->next = NULL;

    if (pq->head == NULL || compare_priority(new_node, pq->head) > 0) {
        new_node->next = pq->head;
        pq->head = new_node;
    } else {
        Node* current = pq->head;
        while (current->next != NULL && compare_priority(current->next, new_node) >= 0) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&pq->lock);
}

void serialize_list_to_disk(const PriorityQueue* pq, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_message("Failed to open file for serialization.");
        return;
    }

    Node* current = pq->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    fclose(file);
}

void deserialize_list_from_disk(PriorityQueue* pq, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_message("Failed to open file for deserialization.");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        insert_with_priority(pq, data, rand() % 100); // Random priority
    }
    fclose(file);
}

void cleanup_expired_entries(PriorityQueue* pq) {
    pthread_mutex_lock(&pq->lock);

    time_t current_time = time(NULL);
    Node** current = &(pq->head);
    while (*current != NULL) {
        if (difftime(current_time, (*current)->data.ue_info_tag.last_update_timestamp) > 3600) { // 1 hour threshold
            Node* to_delete = *current;
            *current = (*current)->next;
            free(to_delete);
        } else {
            current = &((*current)->next);
        }
    }

    pthread_mutex_unlock(&pq->lock);
}

void batch_process(PriorityQueue* pq, int batch_size) {
    pthread_mutex_lock(&pq->lock);

    for (int i = 0; i < batch_size && pq->head != NULL; ++i) {
        Node* to_process = pq->head;
        pq->head = pq->head->next;
        free(to_process);
    }

    pthread_mutex_unlock(&pq->lock);
}

void test_cases() {
    PriorityQueue* pq = create_priority_queue();

    // Test case: Maximum number of entries
    for (int i = 0; i < MAX_ENTRIES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.ue_info_tag.RNTI = rand();
        pdu.ue_info_tag.last_update_timestamp = time(NULL);
        strcpy(pdu.CRC_INDICATION_REL8_TAG, "Test");
        insert_with_priority(pq, pdu, rand() % 100);

        if (i > 0 && i % 100 == 0) {
            alert_if_memory_exceeds_threshold(MEMORY_THRESHOLD_PERCENTAGE);
        }
    }

    // Test case: Handling duplicate entries
    RX_UE_INFORMATION_TAG test_entry = {12345, time(NULL)};
    log_message("Checking for duplicates...");
    if (is_duplicate(pq->head, MAX_ENTRIES, test_entry)) {
        log_message("Duplicate entry found.");
    } else {
        log_message("No duplicate entry found.");
    }

    // Test case: Performance under high concurrency
    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, (void*)batch_process, pq);
    }
    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Test case: Serialization/Deserialization
    serialize_list_to_disk(pq, "nfa_data.bin");
    PriorityQueue* pq_deserialized = create_priority_queue();
    deserialize_list_from_disk(pq_deserialized, "nfa_data.bin");

    destroy_priority_queue(pq);
    destroy_priority_queue(pq_deserialized);
}

int main() {
    test_cases();
    return 0;
}
