    }

    pool->size = pool_size;
    pthread_mutex_init(&pool->lock, NULL);
    pool->current_entries = 0;

    return pool;
}

void destroy_pool(NFAPI_CRC_POOL *pool) {
    if (!pool) return;

    for (size_t i = 0; i < pool->size; ++i) {
        HashNode *node = pool->buckets[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(pool->buckets);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int add_entry(NFAPI_CRC_POOL *pool, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!pool || pool->current_entries >= MAX_ENTRIES) return -1;

    size_t index = hash_function(pdu.RNTI, pool->size);

    pthread_mutex_lock(&pool->lock);

    HashNode *node = pool->buckets[index];
    while (node) {
        if (node->RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&pool->lock);
            return 0; // Duplicate entry
        }
        node = node->next;
    }

    HashNode *new_node = (HashNode*)malloc(sizeof(HashNode));
    if (!new_node) {
        perror("Failed to allocate memory for new hash node");
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    new_node->RNTI = pdu.RNTI;
    new_node->data = pdu;
    new_node->next = pool->buckets[index];
    pool->buckets[index] = new_node;

    pool->current_entries++;

    pthread_mutex_unlock(&pool->lock);

    printf("Entry added for RNTI: %u\n", pdu.RNTI);
    return 1; // Success
}

int populateNfaapiCrcIndicationPduPool(NFAPI_CRC_POOL *pool, NFAPI_CRC_INDICATION_PDU_T *pdu_list, size_t num_pdus) {
    if (!pool || !pdu_list) return -1;

    for (size_t i = 0; i < num_pdus; ++i) {
        int result = add_entry(pool, pdu_list[i]);
        if (result == 0)
            printf("Duplicate RNTI: %u\n", pdu_list[i].RNTI);
        else if (result == -1) {
            perror("Failed to add entry");
            return -1;
        }
    }

    return 0; // Success
}

void usage_example() {
    NFAPI_CRC_POOL *pool = create_pool(256);
    if (!pool) return;

    NFAPI_CRC_INDICATION_PDU_T pdu_list[3] = {
        { .RNTI = 1001 },
        { .RNTI = 1002 },
        { .RNTI = 1001 } // Duplicate entry
    };

    populateNfaapiCrcIndicationPduPool(pool, pdu_list, 3);

    destroy_pool(pool);
}
