}

// Function to check RNTI uniqueness
int is_rnti_unique(NFALIST *list, unsigned int rnti) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].rnti == rnti) return 0;
    }
    return 1;
}

// Function to manage the NFAPI_CRC_INDICATION_PDU_T structures
int add_crc_indication_pdu(NFALIST *list, unsigned int rnti) {
    if (!list || list->count >= MAX_ENTRIES) return -1;

    pthread_mutex_lock(&list->lock);

    UE_INFORMATION_TAG ue_info_tag;
    if (fetch_ue_information_tag(rnti, &ue_info_tag) != 0) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Network failure
    }

    if (!is_rnti_unique(list, rnti)) {
        pthread_mutex_unlock(&list->lock);
        return -3; // RNTI not unique
    }

    NFAPI_CRC_INDICATION_PDU_T new_pdu;
    new_pdu.ue_info_tag = ue_info_tag;
    new_pdu.rnti = rnti;
    new_pdu.crc_indication_rel8.crcflag = rand() % 2; // Random CRC flag

    list->entries[list->count++] = new_pdu;

    pthread_mutex_unlock(&list->lock);

    printf("Added PDU for RNTI: %u\n", rnti); // Logging
    return 0;
}

// Initialize the NFALIST structure
void init_nfalist(NFALIST *list) {
    if (!list) return;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Destroy the NFALIST structure
void destroy_nfalist(NFALIST *list) {
    if (!list) return;
    pthread_mutex_destroy(&list->lock);
}

int main() {
    srand(time(NULL));

