    // Allocate memory for configurations
    *configs = (LTE_PHY_TEST_FRAME_CONFIG*)malloc(*count * sizeof(LTE_PHY_TEST_FRAME_CONFIG));
    if (!*configs) {
        fclose(file);
        return -2;
    }

    // Load each configuration
    for (size_t i = 0; i < *count; ++i) {
        fscanf(file, "%s %d %d", (*configs)[i].modulation_scheme,
               &(*configs)[i].bandwidth, &(*configs)[i].num_of_symbols);

        // Validate and sanitize data
        if (strcmp((*configs)[i].modulation_scheme, "QPSK") != 0 &&
            strcmp((*configs)[i].modulation_scheme, "16QAM") != 0 &&
            strcmp((*configs)[i].modulation_scheme, "64QAM") != 0) {
            // Handle invalid modulation scheme
            fprintf(stderr, "Invalid modulation scheme found.\n");
            fclose(file);
            free(*configs);
            return -3;
        }
    }

