    // Example traversal logic: find indices of configurations with specific criteria
    size_t *indices = (size_t*)malloc(config_count * sizeof(size_t));
    size_t found_count = 0;

    for (size_t i = 0; i < config_count; ++i) {
        if (config_array[i].bandwidth > 20 && strcmp(config_array[i].modulation_scheme, "16QAM") == 0) {
            indices[found_count++] = i;
        }
    }

    // Adjust found_count to the actual number of elements
    size_t* result_indices = realloc(indices, found_count * sizeof(size_t));

    printf("Found %zu configurations meeting criteria.\n", found_count);
    for (size_t i = 0; i < found_count; ++i) {
        printf("Index: %zu\n", result_indices[i]);
    }

    free(result_indices);

    // Free resources on completion
    pthread_mutex_lock(&lock);
    free(config_array);
