            return NULL;
        }

        if (rnti_map[new_node->data.RNTI] == 1) {
            fprintf(stderr, "Duplicate RNTI found: %d\n", new_node->data.RNTI);
            free(new_node);
            continue; // Skip duplicate
        }

        rnti_map[new_node->data.RNTI] = 1;

        if (head == NULL) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }

        log_creation(new_node);
    }

    pthread_mutex_unlock(&list_mutex);
    return head;
}

void log_creation(Node* node) {
    time_t now;
    char timestamp[20];
    time(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    printf("[%s] Created PDU with RNTI: %d, RX_UE_INFORMATION_TAG: %d, CRCFLAG: %d\n",
           timestamp, node->data.RNTI, node->data.RX_UE_INFORMATION_TAG, node->data.crc_tag.CRCFLAG);
}

void free_list(Node* head) {
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator
    int N = 100; // Number of PDUs to generate

    Node* list_head = populate_nfa_pi_crc_indications(N);

    if (list_head) {
        printf("List populated successfully.\n");
    } else {
        fprintf(stderr, "Failed to populate the list.\n");
    }

    free_list(list_head);
    return 0;
}
```

### Explanation:
- **Data Structures:** A linked list of `NFAPI_CRC_INDICATION_PDU_T` structures is used.
- **Unique RNTI Management:** Uses an array (`rnti_map`) to ensure no two PDUs share the same RNTI value.
- **Thread Safety:** A mutex (`list_mutex`) ensures thread-safe access when populating the list, preventing race conditions in concurrent environments.
- **Error Handling:** Handles memory allocation failures gracefully by cleaning up already allocated nodes and logging errors.
- **Logging:** Logs each creation of a PDU with timestamps for debugging purposes. This is crucial for performance analysis.
- **Scalability Considerations:** The solution uses efficient data structures (linked list) to handle a potentially large number of entries (`N`) while ensuring memory management is robust.']

