    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} DynamicArrayManager;

DynamicArrayManager* create_dynamic_array(size_t initial_size) {
    DynamicArrayManager *manager = (DynamicArrayManager *)malloc(sizeof(DynamicArrayManager));
    if (!manager) return NULL;

    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

int populate_dynamic_array(DynamicArrayManager *manager, size_t n) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[manager->count];

        // Generate sample data, replace with actual logic
        pdu->RX_UE_INFORMATION_TAG = rand() % 100;
        unsigned long rnti_candidate = rand() % 2000000;

        if (!validate_RNTI(rnti_candidate)) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // RNTI validation failed
        }

        pdu->RNTI = rnti_candidate;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 100;
        pdu->CRCFLAG = rand() % 2;

        manager->count++;

        if (manager->count == n) break; // Successfully populated

        // Handle reallocation for more elements
        NFAPI_CRC_INDICATION_PDU_T *temp_array = realloc(manager->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (manager->count + 1));
        if (!temp_array) {
            pthread_mutex_unlock(&manager->lock);
            return -3; // Memory allocation failed
        }
        manager->array = temp_array;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

size_t get_population_count(DynamicArrayManager *manager) {
    if (!manager) return (size_t)-1;

    pthread_mutex_lock(&manager->lock);
    size_t count = manager->count;
    pthread_mutex_unlock(&manager->lock);

    return count;
}

void free_dynamic_array_manager(DynamicArrayManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    free(manager->array);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
