#include <iostream>
#include <unordered_map>
#include <shared_mutex>
#include <thread>
#include <chrono>
#include <vector>
#include <atomic>

class Timestamp {
public:
    using time_point = std::chrono::steady_clock::time_point;
    explicit Timestamp(time_point tp = std::chrono::steady_clock::now())
        : timestamp(tp) {}

    bool isExpired(std::chrono::seconds timeout) const {
        return (std::chrono::steady_clock::now() - timestamp) > timeout;
    }

private:
    time_point timestamp;
};

class SessionEntry {
public:
    SessionEntry(Timestamp ts, int userId, int sessionId)
        : timestamp(ts), userId(userId), sessionId(sessionId) {}

    Timestamp getTimestamp() const { return timestamp; }
    int getUserId() const { return userId; }
    int getSessionId() const { return sessionId; }

private:
    Timestamp timestamp;
    int userId;
    int sessionId;
};

class SessionManager {
public:
    using Lock = std::shared_mutex;

    void addEntry(const SessionEntry& entry) {
        std::unique_lock<Lock> lock(mutex_);
        entries_[entry.getSessionId()] = entry;
    }

    bool removeEntry(int sessionId) {
        std::unique_lock<Lock> lock(mutex_);
        auto it = entries_.find(sessionId);
        if (it != entries_.end()) {
            entries_.erase(it);
            return true;
        }
        return false;
    }

    SessionEntry* getEntry(int sessionId) {
        std::shared_lock<Lock> lock(mutex_);
        auto it = entries_.find(sessionId);
        if (it != entries_.end()) {
            return &it->second;
        }
        return nullptr;
    }

    void startCleanupProcess(std::chrono::seconds inactivityThreshold, size_t cleanupIntervalMs) {
        stopCleanupProcess();
        cleanupThread_ = std::thread([this, inactivityThreshold, cleanupIntervalMs]() {
            while (running_) {
                std::unique_lock<Lock> lock(mutex_);
                auto now = std::chrono::steady_clock::now();
                for (auto it = entries_.begin(); it != entries_.end();) {
                    if (it->second.getTimestamp().isExpired(inactivityThreshold)) {
                        it = entries_.erase(it);
                    } else {
                        ++it;
                    }
                }
                lock.unlock();

                std::this_thread::sleep_for(cleanupIntervalMs);
            }
        });
    }

    void stopCleanupProcess() {
        if (cleanupThread_.joinable()) {
            running_ = false;
            cleanupThread_.join();
        }
    }

private:
    std::unordered_map<int, SessionEntry> entries_;
    mutable Lock mutex_;
    std::thread cleanupThread_;
    std::atomic<bool> running_{true};
};

int main() {
    // Example usage
    SessionManager manager;

    manager.addEntry(SessionEntry(Timestamp(), 1, 101));
    manager.addEntry(SessionEntry(Timestamp(), 2, 102));

    auto* entry = manager.getEntry(101);
    if (entry) {
        std::cout << "Found session: " << entry->getSessionId() << std::endl;
    }

    manager.startCleanupProcess(std::chrono::seconds{60}, std::chrono::milliseconds{5000});
    // Simulate operations...
    std::this_thread::sleep_for(std::chrono::seconds{2});

    manager.stopCleanupProcess();
    return 0;
}
```

### Key Considerations:
- **Concurrency Control**: Utilized `std::shared_mutex` to allow concurrent reads and exclusive writes.
- **Data Structures**: Chose `std::unordered_map` for fast lookup, insertion, and deletion operations.
- **Cleanup Process**: Implemented a background thread that periodically removes inactive sessions based on the inactivity threshold.
- **Scalability**: Designed with concurrency and minimal blocking in mind; further scaling might require distributed data management solutions.']

