```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <uuid/uuid.h>
#include <microhttpd.h>
#include <time.h>

#define PORT 8888

typedef enum { CONNECTION_SUCCESS, CONNECTION_FAILED } StatusCode;
typedef enum { EVENT_CONNECTED, EVENT_DISCONNECTED } EventType;

// Linked list for event logs
typedef struct EventLogEntry {
    EventType event_type;
    char source_device_uuid[37];
    char destination_device_uuid[37];
    StatusCode status_code;
    time_t timestamp;
    struct EventLogEntry *next;
} EventLogEntry;

// Device structure
typedef struct Device {
    char uuid[37];
    time_t last_connection_timestamp;
    EventLogEntry *network_event_log;
    struct Device *next;
} Device;

// Global device list and mutex for concurrency control
Device *device_list = NULL;
pthread_mutex_t device_lock;

// UUID validation function (stub for external registry)
int validate_uuid(const char *uuid) {
    // Simulate UUID check with a stub; replace this with actual registry call
    return 1; // Assume always valid for simplicity
}

// Add event to the log
void add_event(Device *device, EventType type, const char *source_uuid, const char *dest_uuid, StatusCode status) {
    EventLogEntry *new_entry = (EventLogEntry *)malloc(sizeof(EventLogEntry));
    if (!new_entry) return;

    new_entry->event_type = type;
    strncpy(new_entry->source_device_uuid, source_uuid, 36);
    new_entry->source_device_uuid[36] = '\0';
    strncpy(new_entry->destination_device_uuid, dest_uuid, 36);
    new_entry->destination_device_uuid[36] = '\0';
    new_entry->status_code = status;
    time(&new_entry->timestamp);

    pthread_mutex_lock(&device_lock);
    new_entry->next = device->network_event_log;
    device->network_event_log = new_entry;
    pthread_mutex_unlock(&device_lock);
}

// Create a new device
Device *create_device(const char *uuid) {
    Device *new_device = (Device *)malloc(sizeof(Device));
    if (!new_device) return NULL;

    strncpy(new_device->uuid, uuid, 36);
    new_device->uuid[36] = '\0';
    time(&new_device->last_connection_timestamp);
    new_device->network_event_log = NULL;
    new_device->next = NULL;

    pthread_mutex_lock(&device_lock);
    new_device->next = device_list;
    device_list = new_device;
    pthread_mutex_unlock(&device_lock);

    return new_device;
}

// HTTP request handler for adding a new device
int add_device_handler(void *cls, struct MHD_Connection *connection,
                       const char *url, const char *method,
                       const char *version, const char *upload_data,
                       size_t *upload_data_size, void **ptr) {
    if (strcmp(method, "POST") != 0)
        return MHD_NO;

    pthread_mutex_lock(&device_lock);
    uuid_t uid;
    uuid_generate(uid);

    char uuid_str[37];
    uuid_unparse(uid, uuid_str);

    // Validate UUID
    if (!validate_uuid(uuid_str)) {
        pthread_mutex_unlock(&device_lock);
        return MHD_HTTP_INTERNAL_SERVER_ERROR;
    }

    Device *new_device = create_device(uuid_str);
    pthread_mutex_unlock(&device_lock);

    if (!new_device) {
        return MHD_NO; // Failed to allocate memory for new device
    }

    const char *response = "Device added successfully";
    struct MHD_Response *reply = MHD_create_response_from_buffer(strlen(response), (void *)response, MHD_RESPMEM_PERSISTENT);
    int ret = MHD_queue_response(connection, MHD_HTTP_OK, reply);
    MHD_destroy_response(reply);

    return ret;
}

// HTTP request handler for retrieving device information
int get_device_handler(void *cls, struct MHD_Connection *connection,
                       const char *url, const char *method,
                       const char *version, const char *upload_data,
                       size_t *upload_data_size, void **ptr) {
    if (strcmp(method, "GET") != 0)
        return MHD_NO;

    pthread_mutex_lock(&device_lock);
    char response[1024] = "";
    for (Device *d = device_list; d != NULL; d = d->next) {
        strcat(response, "{\"uuid\":\"");
        strcat(response, d->uuid);
        strcat(response, "\", \"last_connection_timestamp\": ");
        time_t now;
        time(&now);
        char buffer[30];
        struct tm *local_tm = localtime(&d->last_connection_timestamp);
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", local_tm);
        strcat(response, "\"");
        strcat(response, buffer);
        strcat(response, "\", \"event_log\": [");

        EventLogEntry *entry;
        for (entry = d->network_event_log; entry != NULL; entry = entry->next) {
            strcat(response, "{\"event_type\": ");
            strcat(response, event_type_to_string(entry->event_type));
            strcat(response, ", \"source_device_uuid\":\"");
            strcat(response, entry->source_device_uuid);
            strcat(response, "\", \"destination_device_uuid\":\"");
            strcat(response, entry->destination_device_uuid);
            strcat(response, "\", \"status_code\": ");
            strcat(response, status_code_to_string(entry->status_code));
            strcat(response, ", \"timestamp\":\"");
            char timestamp[30];
            strftime(timestamp, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", localtime(&entry->timestamp));
            strcat(response, timestamp);
            if (entry->next) {
                strcat(response, "}, ");
            } else {
                strcat(response, "}]}");
            }
        }

        if (d->next) {
            strcat(response, "], \"next\": ");
        } else {
            strcat(response, "]}");
        }
    }
    pthread_mutex_unlock(&device_lock);

    struct MHD_Response *reply = MHD_create_response_from_buffer(strlen(response), (void *)response, MHD_RESPMEM_PERSISTENT);
    int ret = MHD_queue_response(connection, MHD_HTTP_OK, reply);
    MHD_destroy_response(reply);

    return ret;
}

// Error handling and utility functions
const char* event_type_to_string(EventType type) {
    switch(type) {
        case EVENT_CONNECTED: return "\"connected\"";
        case EVENT_DISCONNECTED: return "\"disconnected\"";
        default: return "\"unknown\"";
    }
}

const char* status_code_to_string(StatusCode code) {
    switch(code) {
        case CONNECTION_SUCCESS: return "\"success\"";
        case CONNECTION_FAILED: return "\"failed\"";
        default: return "\"unknown\"";
    }
}

// Cleanup and shutdown functions
void free_devices(Device *device_list) {
    while (device_list != NULL) {
        Device *temp = device_list;
        device_list = device_list->next;

        EventLogEntry *entry;
        while ((entry = temp->network_event_log) != NULL) {
            temp->network_event_log = entry->next;
            free(entry);
        }

        free(temp);
    }
}

int main() {
    struct MHD_Daemon *daemon;

    pthread_mutex_init(&device_lock, NULL);

    daemon = MHD_start_daemon(MHD_USE_SELECT_INTERNALLY,
                              PORT, NULL, NULL,
                              &add_device_handler, NULL,
                              MHD_OPTION_END);

    if (NULL == daemon) return 1;

    printf("Server running on port %d\n", PORT);
    getchar();

    MHD_stop_daemon(daemon);
    pthread_mutex_destroy(&device_lock);
    free_devices(device_list);

    return 0;
}
```

