```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000
#define TIMEOUT_PERIOD 30 // seconds

typedef struct {
    int RNTI;
    unsigned char RX_UE_INFORMATION_TAG;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned int CRCFLAG;
    time_t last_access_time;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
    size_t count;
    int max_consecutive_duplicates;
    time_t cleanup_threshold;
} StructureList;

StructureList list = {NULL, PTHREAD_MUTEX_INITIALIZER, 0, 3, time(NULL) - TIMEOUT_PERIOD};

void log_event(const char *event) {
    printf("%s: %s\n", event, ctime(&list.cleanup_threshold));
}

int create_structure(NFAPI_CRC_INDICATION_PDU_T **new_struct) {
    if (list.count >= MAX_STRUCTURES) {
        return -1;
    }

    *new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*new_struct) {
        return -1;
    }

    (*new_struct)->RNTI = rand() % 1000; // Example RNTI generation
    (*new_struct)->RX_UE_INFORMATION_TAG = rand() % 256;
    (*new_struct)->CRC_INDICATION_REL8_TAG = rand() % 256;
    (*new_struct)->CRCFLAG = rand() % 2;

    (*new_struct)->last_access_time = time(NULL);
    log_event("Structure created");

    return 0;
}

void add_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    pthread_mutex_lock(&list.lock);

    Node **tracer = &list.head;
    int consecutive_count = 0;

    while (*tracer) {
        if ((*tracer)->data->RNTI == structure->RNTI) {
            consecutive_count++;
        } else {
            consecutive_count = 0;
        }

        if (consecutive_count > list.max_consecutive_duplicates) {
            log_event("RNTI uniqueness constraint violated");
            pthread_mutex_unlock(&list.lock);
            return;
        }

        tracer = &(*tracer)->next;
    }

    Node *new_node = malloc(sizeof(Node));
    new_node->data = structure;
    new_node->next = list.head;
    list.head = new_node;
    list.count++;

    pthread_mutex_unlock(&list.lock);
}

void cleanup_unused_structures() {
    pthread_mutex_lock(&list.lock);

    time_t now = time(NULL);
    Node **tracer = &list.head;
    while (*tracer) {
        if (difftime(now, (*tracer)->data->last_access_time) > TIMEOUT_PERIOD) {
            Node *to_delete = *tracer;
            *tracer = to_delete->next;
            free(to_delete->data);
            free(to_delete);
            list.count--;
            log_event("Structure cleaned up");
        } else {
            tracer = &(*tracer)->next;
        }
    }

    pthread_mutex_unlock(&list.lock);
}

void access_structure(int rnti) {
    pthread_mutex_lock(&list.lock);

    Node *current = list.head;
    while (current) {
        current->data->last_access_time = time(NULL);

        if (current->data->RNTI == rnti) {
            log_event("Structure accessed");
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list.lock);
}

void configure_list(int max_consecutive_duplicates, int timeout_period) {
    list.max_consecutive_duplicates = max_consecutive_duplicates;
    list.cleanup_threshold = time(NULL) - timeout_period;

    log_event("Configuration updated");
}

int main() {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T *new_struct;
    if (create_structure(&new_struct) == 0) {
        add_structure(new_struct);
    }

    configure_list(3, TIMEOUT_PERIOD);

    while (1) {
        cleanup_unused_structures();
        sleep(5); // Simulate periodic cleanup
    }

    return 0;
}
