#define INITIAL_CAPACITY 1000
#define MAX_CAPACITY 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->capacity = INITIAL_CAPACITY;
    da->size = 0;
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(da->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray* da) {
    if (da) {
        pthread_mutex_destroy(&da->lock);
        free(da->array);
        free(da);
    }
}

int resize_if_needed(DynamicArray* da) {
    if (da->size >= da->capacity && da->capacity < MAX_CAPACITY) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_array) return -1;

        da->array = temp_array;
        da->capacity = new_capacity;
    }
    return 0;
}

int add_element(DynamicArray* da, uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI, int CRCFLAG) {
    pthread_mutex_lock(&da->lock);

    if (resize_if_needed(da) != 0) {
        pthread_mutex_unlock(&da->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* element = &da->array[da->size];
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = CRCFLAG;

    da->size++;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

int remove_element(DynamicArray* da, size_t index) {
    if (index >= da->size) return -1;

    pthread_mutex_lock(&da->lock);

    memmove(&da->array[index], &da->array[index + 1],
            (da->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    da->size--;
    pthread_mutex_unlock(&da->lock);
