```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_STRUCTURES 10000
#define TIMESTAMP_SIZE sizeof(time_t)

typedef struct {
    unsigned int RNTI;
    unsigned char CRCFLAG;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    time_t timestamp;
    void *metadata[3];  // Optional metadata fields
} ManagedPdu;

typedef struct {
    ManagedPdu *pdus[MAX_STRUCTURES];
    size_t count;
    unsigned int last_rnti;  // To track the last used RNTI
    pthread_mutex_t mutex;
    time_t cleanup_interval;
    time_t last_cleanup_time;
} PduManager;

void initialize_manager(PduManager *manager, time_t cleanup_interval) {
    manager->count = 0;
    manager->last_rnti = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->cleanup_interval = cleanup_interval;
    manager->last_cleanup_time = time(NULL);
}

void cleanup_memory(PduManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->pdus[i]) {
            free(manager->pdus[i]->metadata[0]);
            free(manager->pdus[i]->metadata[1]);
            free(manager->pdus[i]->metadata[2]);
            free(manager->pdus[i]);
            manager->pdus[i] = NULL;
        }
    }
    manager->count = 0;
    pthread_mutex_unlock(&manager->mutex);
}

int add_pdu(PduManager *manager, unsigned int rnti, void **metadata_fields) {
    if (rnti == manager->last_rnti || manager->count >= MAX_STRUCTURES) return -1;

    time_t current_time = time(NULL);
    if (current_time - manager->last_cleanup_time > manager->cleanup_interval) {
        cleanup_memory(manager);
        manager->last_cleanup_time = current_time;
    }

    pthread_mutex_lock(&manager->mutex);

    ManagedPdu *new_pdu = (ManagedPdu *)malloc(sizeof(ManagedPdu));
    if (!new_pdu) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    new_pdu->pdu.RNTI = rnti;
    new_pdu->pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_pdu->timestamp = current_time;

    for (int i = 0; i < 3; ++i) {
        if (metadata_fields[i]) {
            new_pdu->metadata[i] = malloc(sizeof(*metadata_fields[i]));
            memcpy(new_pdu->metadata[i], metadata_fields[i], sizeof(*metadata_fields[i]));
        }
    }

    manager->pdus[manager->count++] = new_pdu;
    manager->last_rnti = rnti;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void destroy_manager(PduManager *manager) {
    cleanup_memory(manager);
    pthread_mutex_destroy(&manager->mutex);
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations.
- **Memory Management**: Allocates each structure on the heap and periodically cleans up unused memory.
- **Optional Metadata**: Supports up to three optional metadata fields, dynamically allocated at runtime.
- **Timestamp**: Adds a timestamp field for logging purposes.
- **RNTI Tracking**: Ensures no two consecutive structures have the same RNTI value.
- **Error Handling**: Includes basic error handling for memory allocation failures and invalid operations.']

