['Here's an implementation in C using a doubly linked list with thread-safe operations:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int SRS_INDEX;
    int RB_ID;
    int PHY_DOWNLINK_FRAME; // Placeholder for actual frame data type
} DL_FRAME_INFO;

typedef struct Node {
    DL_FRAME_INFO info;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* createList() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void freeNode(Node* node) {
    if (node) {
        free(node);
    }
}

void insertFrame(DoublyLinkedList* list, DL_FRAME_INFO info) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return; // Handle memory allocation failure

    newNode->info = info;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = list->tail = newNode;
        newNode->prev = NULL;
    } else {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }

    pthread_mutex_unlock(&list->lock);
}

DL_FRAME_INFO removeFrame(DoublyLinkedList* list) {
    DL_FRAME_INFO info = {0, 0, 0};

    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        pthread_mutex_unlock(&list->lock);
        return info; // List is empty
    }

    Node* node = list->head;
    info = node->info;

    if (node == list->tail) {
        list->head = list->tail = NULL;
    } else {
        list->head = node->next;
        list->head->prev = NULL;
    }

    freeNode(node);

    pthread_mutex_unlock(&list->lock);
    return info;
}

void iterateFrames(DoublyLinkedList* list, void (*process)(DL_FRAME_INFO)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        process(current->info);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void destroyList(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        freeNode(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
void processFrame(DL_FRAME_INFO info) {
    // Process the frame (placeholder)
    printf("Processing frame: SRS_INDEX=%d, RB_ID=%d\n", info.SRS_INDEX, info.RB_ID);
}

int main() {
    DoublyLinkedList* list = createList();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return 1;
    }

    DL_FRAME_INFO frame1 = {1, 2, 3};
    DL_FRAME_INFO frame2 = {4, 5, 6};

    insertFrame(list, frame1);
    insertFrame(list, frame2);

    iterateFrames(list, processFrame);

    removeFrame(list);
    iterateFrames(list, processFrame);

    destroyList(list);
    return 0;
}
```

### Key Points:

