#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE 1024 // Maximum number of UE instances

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to check if an RNTI already exists in the array
int is_unique_RNTI(NFAPI_CRC_INDICATION_PDU_T *array, size_t count, unsigned long rnti) {
    for (size_t i = 0; i < count; ++i) {
        if (array[i].RNTI == rnti) return 0;
    }
    return 1;
}

// Custom memory management strategy
NFAPI_CRC_INDICATION_PDU_T* allocate_ues(size_t size, size_t *allocated_size) {
    const size_t chunk_size = 64; // Adjust based on typical use cases and available memory
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    for (size_t current_size = 0; current_size < size; ) {
        size_t new_size = current_size + chunk_size > size ? size : current_size + chunk_size;

        NFAPI_CRC_INDICATION_PDU_T *temp_array = realloc(array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_array) {
            free(array);
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        array = temp_array;
        current_size = new_size;
    }

    *allocated_size = size;
    return array;
}

// Thread-safe function to populate UE instances
int populate_ue_instances(size_t num_ues, NFAPI_CRC_INDICATION_PDU_T **ue_array) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    int status = 0;
    size_t allocated_size = 0;

    *ue_array = allocate_ues(num_ues, &allocated_size);
    if (!*ue_array) {
        fprintf(stderr, "Failed to allocate memory for UE instances\n");
        status = -1;
        goto cleanup;
    }

    pthread_mutex_lock(&lock);

    srand(time(NULL)); // Seed random number generator

    unsigned long used_rntis[MAX_UE] = {0};
    size_t count = 0;

    for (size_t i = 0; i < num_ues; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &(*ue_array)[i];
        pdu->RX_UE_INFORMATION_TAG = rand() % 10000;
        unsigned long rnti = rand() % (1 << 20);

        if (!is_unique_RNTI(*ue_array, count, rnti)) {
            fprintf(stderr, "Duplicate RNTI detected: %lu\n", rnti);
            status = -2; // Error code for duplicate RNTI
            goto cleanup;
        }

        pdu->RNTI = rnti;
        used_rntis[count++] = rnti;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 1000;
        pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }

cleanup:
    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    if (status != 0) {
        free(*ue_array);
        *ue_array = NULL;
    }

    return status;
}

int main() {
    size_t num_ues = 100; // Number of UE instances to manage
    NFAPI_CRC_INDICATION_PDU_T *ue_instances = NULL;

    int result = populate_ue_instances(num_ues, &ue_instances);
    if (result == 0) {
        printf("UE instances populated successfully.\n");
    } else {
        printf("Error populating UE instances. Status: %d\n", result);
    }

    free(ue_instances);
    return result;
}
