#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define MAX_TOTAL_SIZE 1024 * 1024 // Maximum total size in bytes
#define CHUNK_SIZE 256             // Initial chunk size for allocations

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
void log_error(const char *message);
int allocate_and_populate_NF_API_CrcIndications(int num_ues, NFAPI_CRC_INDICATION_PDU_T **indication_array, int *allocation_success);

// Global mutex for thread safety
pthread_mutex_t allocation_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

int allocate_and_populate_NF_API_CrcIndications(int num_ues, NFAPI_CRC_INDICATION_PDU_T **indication_array, int *allocation_success) {
    pthread_mutex_lock(&allocation_mutex);

    if (num_ues <= 0 || allocation_success == NULL) {
        log_error("Invalid number of UEs or allocation success pointer is NULL");
        pthread_mutex_unlock(&allocation_mutex);
        return -1;
    }

    *indication_array = NULL;
    int current_size = 0;
    int allocated_count = 0;
    *allocation_success = 1;

    while (allocated_count < num_ues && current_size + CHUNK_SIZE <= MAX_TOTAL_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T *temp_array = realloc(*indication_array, (current_size + CHUNK_SIZE) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!temp_array) {
            log_error("Memory allocation failed");
            free(*indication_array);
            *allocation_success = 0;
            pthread_mutex_unlock(&allocation_mutex);
            return -1;
        }
        *indication_array = temp_array;

        for (int i = allocated_count; i < allocated_count + CHUNK_SIZE && allocated_count < num_ues; ++i) {
            (*indication_array)[i].RX_UE_INFORMATION_TAG = rand();
            (*indication_array)[i].RNTI = (uint16_t)(rand() % 0xFFFF);
            (*indication_array)[i].CRCFLAG = rand() & 1;

            for (int j = 0; j < i; ++j) {
                if ((*indication_array)[i].RNTI == (*indication_array)[j].RNTI) {
                    log_error("Duplicate RNTI detected");
                    free(*indication_array);
                    *allocation_success = 0;
                    pthread_mutex_unlock(&allocation_mutex);
                    return -1;
                }
            }

#ifdef LOGGING_ENABLED
            printf("Allocated structure: Time=%ld, RNTI=0x%04X, CRCFLAG=%d\n", time(NULL), (*indication_array)[i].RNTI, (*indication_array)[i].CRCFLAG);
#endif

            allocated_count++;
        }

        current_size += CHUNK_SIZE;
    }

    if (allocated_count < num_ues) {
        log_error("Memory exhausted before fulfilling all requests");
        free(*indication_array);
        *allocation_success = 0;
    } else {
        *allocation_success = 1;
    }

