#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_BEARERS 10

typedef struct {
    int data; // Placeholder for measurement data
} MeasurementData;

typedef struct {
    MeasurementData measurements[5]; // Example size
    pthread_rwlock_t lock;
} MeasurementReport;

typedef struct {
    int bearerId;
    pthread_mutex_t mutex;
} BearerContext;

typedef struct {
    int ueId;
    BearerContext* bearers;
    size_t bearerCount;
    MeasurementReport report;
} UEContext;

// Function prototypes
UEContext* initializeUEContext(int ueId, size_t initialBearerCapacity);
void addBearer(UEContext* ueContext, int bearerId);
void removeBearer(UEContext* ueContext, int bearerId);
void updateMeasurement(UEContext* ueContext, MeasurementData data);
void cleanupUEContext(UEContext* ueContext);

// Initialize UE context
UEContext* initializeUEContext(int ueId, size_t initialBearerCapacity) {
    UEContext* ueContext = (UEContext*)malloc(sizeof(UEContext));
    if (!ueContext) return NULL;

    ueContext->ueId = ueId;
    ueContext->bearers = (BearerContext*)calloc(initialBearerCapacity, sizeof(BearerContext));
    if (!ueContext->bearers) {
        free(ueContext);
        return NULL;
    }
    ueContext->bearerCount = 0;
    pthread_rwlock_init(&ueContext->report.lock, NULL);

    for (size_t i = 0; i < initialBearerCapacity; ++i) {
        pthread_mutex_init(&ueContext->bearers[i].mutex, NULL);
    }

    return ueContext;
}

// Add a bearer context
void addBearer(UEContext* ueContext, int bearerId) {
    if (ueContext->bearerCount >= MAX_BEARERS) return;

    BearerContext* newBearers = realloc(ueContext->bearers, (ueContext->bearerCount + 1) * sizeof(BearerContext));
    if (!newBearers) return;

    ueContext->bearers = newBearers;
    pthread_mutex_init(&ueContext->bearers[ueContext->bearerCount].mutex, NULL);
    ueContext->bearers[ueContext->bearerCount].bearerId = bearerId;
    ++ueContext->bearerCount;
}

// Remove a bearer context
void removeBearer(UEContext* ueContext, int bearerId) {
    for (size_t i = 0; i < ueContext->bearerCount; ++i) {
        if (ueContext->bearers[i].bearerId == bearerId) {
            pthread_mutex_destroy(&ueContext->bearers[i].mutex);
            memmove(&ueContext->bearers[i], &ueContext->bearers[i + 1], (ueContext->bearerCount - i - 1) * sizeof(BearerContext));
            --ueContext->bearerCount;
            BearerContext* newBearers = realloc(ueContext->bearers, ueContext->bearerCount * sizeof(BearerContext));
            if (newBearers) ueContext->bearers = newBearers;
            break;
        }
    }
}

// Update measurement report
void updateMeasurement(UEContext* ueContext, MeasurementData data) {
    pthread_rwlock_wrlock(&ueContext->report.lock);
    // Example update logic: find a free slot or replace oldest data
    for (int i = 0; i < 5; ++i) {
        if (ueContext->report.measurements[i].data == 0) { // Assuming '0' indicates unused
            ueContext->report.measurements[i] = data;
            pthread_rwlock_unlock(&ueContext->report.lock);
            return;
        }
    }
    pthread_rwlock_unlock(&ueContext->report.lock);
}

// Cleanup UE context
void cleanupUEContext(UEContext* ueContext) {
    if (!ueContext) return;

    for (size_t i = 0; i < ueContext->bearerCount; ++i) {
        pthread_mutex_destroy(&ueContext->bearers[i].mutex);
    }
    free(ueContext->bearers);
    pthread_rwlock_destroy(&ueContext->report.lock);
    free(ueContext);
}
```

This code provides a basic framework for managing UE contexts with thread-safe operations. It includes functions to initialize, add/remove bearers, update measurements, and clean up resources. The use of mutexes and read-write locks ensures thread safety during concurrent access."]

