    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} LinkedList;

// Function prototypes
LinkedList* create_list();
void destroy_list(LinkedList* list);
int add_entry(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T entry);
void cleanup_list(LinkedList* list);
size_t serialize_list(const LinkedList* list, uint8_t** buffer);
void deserialize_list(uint8_t* buffer, size_t buffer_size, LinkedList* list);

// Implementations
LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_entry(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void cleanup_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current) {
        if (!/* condition to mark as processed */) { // Replace with actual condition
            if (prev)
                prev->next = current->next;
            else
                list->head = current->next;

            free(current);
            list->size--;
            current = (prev ? prev->next : list->head);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

size_t serialize_list(const LinkedList* list, uint8_t** buffer) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    size_t total_size = sizeof(size_t); // Store the size of the list
    for (Node* current = list->head; current; current = current->next)
        total_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);

    *buffer = (uint8_t*)malloc(total_size);
    if (!*buffer) {
        pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
        return 0;
    }

    size_t offset = 0;
    memcpy(*buffer, &list->size, sizeof(size_t));
    offset += sizeof(size_t);

    for (Node* current = list->head; current; current = current->next) {
        memcpy(*buffer + offset, &(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        offset += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return total_size;
}

void deserialize_list(uint8_t* buffer, size_t buffer_size, LinkedList* list) {
    if (buffer_size < sizeof(size_t)) return; // Invalid data

    size_t list_size;
    memcpy(&list_size, buffer, sizeof(size_t));

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    Node** current = &(list->head);

    for (size_t i = 0; i < list_size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        memcpy(&entry, buffer + sizeof(size_t) + i * sizeof(NFAPI_CRC_INDICATION_PDU_T), sizeof(NFAPI_CRC_INDICATION_PDU_T));

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) break; // Memory allocation failed

        new_node->data = entry;
        new_node->next = NULL;
        *current = new_node;
        current = &new_node->next;
    }

    list->size = i;
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}

// Unit tests
void test_add_entry() {
    LinkedList* list = create_list();
    NFAPI_CRC_INDICATION_PDU_T entry = {1, 2, 3, rand() % 2};
    int result = add_entry(list, entry);
