    destroy_list(list);
}

void test_serialize_deserialize() {
    LinkedList* list = create_list();
    NFAPI_CRC_INDICATION_PDU_T entry1 = {1, 2, 3, rand() % 2};
    NFAPI_CRC_INDICATION_PDU_T entry2 = {4, 5, 6, rand() % 2};

    add_entry(list, entry1);
    add_entry(list, entry2);

    uint8_t* buffer;
    size_t buffer_size = serialize_list(list, &buffer);
    if (buffer_size > 0) {
        printf("Serialization successful\n");
        LinkedList* new_list = create_list();
        deserialize_list(buffer, buffer_size, new_list);
        printf("Deserialization completed. New list size: %zu\n", new_list->size);
        destroy_list(new_list);
        free(buffer);
