#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

// Define the structures for frame information and metadata.
typedef struct {
    uint32_t rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t frame_length;
    time_t timestamp;
} NFAPI_RX_FRAME_INFO_T;

// Dynamic array manager structure
typedef struct {
    NFAPI_RX_FRAME_INFO_T **frames; // Array of pointers to frames.
    size_t capacity;
    size_t count;
    _Atomic(size_t) next_free_index;
    pthread_mutex_t resize_lock;
} FrameArrayManager;

// Function prototypes
FrameArrayManager* init_frame_array_manager(size_t initial_capacity);
void free_frame_array_manager(FrameArrayManager *manager);
int add_frame_info(FrameArrayManager *manager, NFAPI_RX_FRAME_INFO_T *frame_info);
void garbage_collect_frames(FrameArrayManager *manager);
size_t serialize_frame_data(const FrameArrayManager *manager, uint8_t **buffer);
int deserialize_frame_data(FrameArrayManager *manager, const uint8_t *buffer, size_t length);

// Function implementations
FrameArrayManager* init_frame_array_manager(size_t initial_capacity) {
    FrameArrayManager *manager = (FrameArrayManager *)malloc(sizeof(FrameArrayManager));
    if (!manager) return NULL;

    manager->frames = (NFAPI_RX_FRAME_INFO_T **)calloc(initial_capacity, sizeof(NFAPI_RX_FRAME_INFO_T *));
    if (!manager->frames) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    atomic_store(&manager->next_free_index, 0);

    pthread_mutex_init(&manager->resize_lock, NULL);
    return manager;
}

void free_frame_array_manager(FrameArrayManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->frames[i]) {
            free(manager->frames[i]);
        }
    }
    free(manager->frames);
    pthread_mutex_destroy(&manager->resize_lock);
    free(manager);
}

int add_frame_info(FrameArrayManager *manager, NFAPI_RX_FRAME_INFO_T *frame_info) {
    size_t index = atomic_fetch_add(&manager->next_free_index, 1);

    if (index >= manager->capacity) {
        pthread_mutex_lock(&manager->resize_lock);
        if (index >= manager->capacity) { // Double-check locking
            size_t new_capacity = manager->capacity * 2;
            NFAPI_RX_FRAME_INFO_T **new_frames = realloc(manager->frames, new_capacity * sizeof(NFAPI_RX_FRAME_INFO_T *));
            if (!new_frames) {
                pthread_mutex_unlock(&manager->resize_lock);
                return -1; // Memory allocation failed
            }

            manager->capacity = new_capacity;
            manager->frames = new_frames;

            for (size_t i = manager->count; i < manager->capacity; ++i) {
                manager->frames[i] = NULL;
            }
        }
        pthread_mutex_unlock(&manager->resize_lock);
    }

    if (index >= manager->count) {
        manager->frames[index] = frame_info;
        atomic_fetch_add(&manager->count, 1);
    } else {
        free(manager->frames[index]);
        manager->frames[index] = frame_info;
    }

    // Simulate external logging
    printf("Frame added at index %zu\n", index);

    return 0;
}

void garbage_collect_frames(FrameArrayManager *manager) {
    pthread_mutex_lock(&manager->resize_lock);
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->frames[i]) {
            // Placeholder for checking if the frame is still valid or can be recycled.
            // For demonstration, assume all frames are stale and need to be freed:
            free(manager->frames[i]);
            manager->frames[i] = NULL;
        }
    }
    pthread_mutex_unlock(&manager->resize_lock);

    atomic_store(&manager->count, 0); // Reset count after garbage collection
    printf("Garbage collection completed\n");
}

size_t serialize_frame_data(const FrameArrayManager *manager, uint8_t **buffer) {
    size_t total_size = sizeof(size_t); // Store the number of frames first.
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->frames[i]) {
            total_size += sizeof(RX_UE_INFORMATION_TAG) + sizeof(uint16_t) + sizeof(time_t);
        }
    }

    *buffer = (uint8_t *)malloc(total_size);
    if (!*buffer) return 0;

    size_t offset = 0;
    memcpy(*buffer, &manager->count, sizeof(size_t));
    offset += sizeof(size_t);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->frames[i]) {
            memcpy((*buffer + offset), &(manager->frames[i]->ue_info_tag), sizeof(RX_UE_INFORMATION_TAG));
            offset += sizeof(RX_UE_INFORMATION_TAG);

            memcpy((*buffer + offset), &manager->frames[i]->frame_length, sizeof(uint16_t));
            offset += sizeof(uint16_t);

            memcpy((*buffer + offset), &manager->frames[i]->timestamp, sizeof(time_t));
            offset += sizeof(time_t);
        }
    }

    return total_size;
}

int deserialize_frame_data(FrameArrayManager *manager, const uint8_t *buffer, size_t length) {
    if (length < sizeof(size_t)) return -1;

    size_t frame_count = *(const size_t *)buffer;
    buffer += sizeof(size_t);
    length -= sizeof(size_t);

    pthread_mutex_lock(&manager->resize_lock);
    for (size_t i = 0; i < frame_count && length >= sizeof(RX_UE_INFORMATION_TAG) + sizeof(uint16_t) + sizeof(time_t); ++i) {
        NFAPI_RX_FRAME_INFO_T *frame_info = malloc(sizeof(NFAPI_RX_FRAME_INFO_T));
        if (!frame_info) {
            pthread_mutex_unlock(&manager->resize_lock);
            return -1; // Memory allocation failed
        }

        memcpy(&(frame_info->ue_info_tag), buffer, sizeof(RX_UE_INFORMATION_TAG));
        buffer += sizeof(RX_UE_INFORMATION_TAG);
        length -= sizeof(RX_UE_INFORMATION_TAG);

        memcpy(&(frame_info->frame_length), buffer, sizeof(uint16_t));
        buffer += sizeof(uint16_t);
        length -= sizeof(uint16_t);

        memcpy(&(frame_info->timestamp), buffer, sizeof(time_t));
        buffer += sizeof(time_t);
        length -= sizeof(time_t);

        add_frame_info(manager, frame_info);
    }
    pthread_mutex_unlock(&manager->resize_lock);

    return 0;
