#include <time.h>

#define MAX_RETRIES 5
#define BACKOFF_BASE_MS 100
#define TIMEOUT_SEC 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Global mutex for thread-safe operations
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

unsigned short generate_rnti(unsigned int seed, size_t index, unsigned short min_value, unsigned short max_value) {
    srand(seed + index); // Seed based on provided seed and index
    return (rand() % (max_value - min_value + 1)) + min_value;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_crc_indication_pdu(size_t n, unsigned int seed, unsigned short rnti_min, unsigned short rnti_max) {
    pthread_mutex_lock(&memory_lock);

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    size_t retries = 0;
    time_t start_time = time(NULL);

    while (retries < MAX_RETRIES) {
        array = realloc(array, n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (array != NULL) {
            break; // Successful allocation
        } else {
            sleep(BACKOFF_BASE_MS / 1000.0 * (1 << retries)); // Exponential backoff
            retries++;
        }

        if ((time(NULL) - start_time) >= TIMEOUT_SEC) {
            log_error("Timeout occurred during memory allocation.");
            break;
        }
    }

    if (array == NULL) {
        log_error("Failed to allocate memory after multiple attempts.");
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        array[i].RNTI = generate_rnti(seed, i, rnti_min, rnti_max);
        array[i].CRCFLAG = (array[i].RNTI & 1) ^ (i % 2); // Example CRC flag calculation
    }

    pthread_mutex_unlock(&memory_lock);
    return array;
}

void free_nfa_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array != NULL) {
        free(array);
    }
}

// A sample function to demonstrate batch processing and async handling.
void process_batch_async(size_t count, size_t n, unsigned int seed, unsigned short rnti_min, unsigned short rnti_max) {
    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *array = allocate_nfa_crc_indication_pdu(n, seed + i, rnti_min, rnti_max);

        if (array != NULL) {
            // Process array...

            free_nfa_crc_indication_pdu(array);
        }
    }
}

int main() {
