memory_pool* create_memory_pool(size_t size) {
    memory_pool* pool = malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->size = size;
    pool->start = malloc(size);
    if (!pool->start) {
        free(pool);
        return NULL;
    }

    pool->current = pool->start;
    return pool;
}

void* memory_pool_alloc(memory_pool* pool, size_t size) {
