void init_dynamic_array(DynamicArray *array) {
    array->count = 0;
    array->capacity = 10; // Initial capacity
    array->elements = (NFAPI_CRC_INDICATION_PDU_T *)malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->elements) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&array->lock, NULL);
}

void free_dynamic_array(DynamicArray *array) {
    free(array->elements);
    pthread_mutex_destroy(&array->lock);
}

int resize_if_needed(DynamicArray *array) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        if (new_capacity > MAX_ELEMENTS) return -1; // Exceeds limit

        NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            perror("Failed to reallocate memory");
            return -1;
        }
        array->elements = new_elements;
        array->capacity = new_capacity;

        return 0; // Success
