```javascript
class ScriptExecutor {
    constructor() {
        this.loadedScripts = new Set();
    }

    async executeScript(fileUrl) {
        try {
            if (this.loadedScripts.has(fileUrl)) {
                console.log(`Script ${fileUrl} is already loaded.`);
                return;
            }

            const response = await fetch(fileUrl);
            if (!response.ok) throw new Error(`Failed to load script: ${fileUrl}`);

            const scriptContent = await response.text();
            this.evaluateScript(scriptContent, fileUrl);
        } catch (error) {
            console.error(error.message);
        }
    }

    evaluateScript(scriptContent, fileUrl) {
        try {
            // Create a new function from the script content and execute it
            const scriptFunction = new Function(scriptContent);
            scriptFunction();
            this.loadedScripts.add(fileUrl);
            console.log(`Successfully executed script: ${fileUrl}`);
        } catch (error) {
            console.error(`Error executing script (${fileUrl}):`, error.message);
        }
    }

    unloadScript(fileUrl) {
        if (this.loadedScripts.has(fileUrl)) {
            console.log(`Unloading script: ${fileUrl}`);
            this.loadedScripts.delete(fileUrl);
        }
    }
}

// Usage example
const executor = new ScriptExecutor();
executor.executeScript('path/to/script1.js')
    .then(() => executor.executeScript('path/to/script2.js'))
    .catch(err => console.error('Execution error:', err));

```

