NFAPI_CRC_INDICATION_PDU_T* nfa_list = NULL;
size_t current_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void create_and_populate_list(size_t new_entries);
void serialize_to_file(const char* filename);
int deserialize_from_file(const char* filename);
void log_usage();
