void create_and_populate_list(size_t new_entries) {
    pthread_mutex_lock(&lock);

    size_t new_size = current_size + new_entries;
    if (new_size > MAX_STRUCTURES) {
        fprintf(stderr, "Exceeded maximum number of structures.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    resize_list(new_size);

    for (size_t i = current_size; i < new_size; ++i) {
        nfa_list[i].crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        nfa_list[i].timestamp = time(NULL);
    }

    current_size = new_size;

    pthread_mutex_unlock(&lock);
}

void resize_list(size_t new_capacity) {
    if (nfa_list == NULL || new_capacity <= current_size) return;

    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(nfa_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!temp) {
        fprintf(stderr, "Memory allocation failed during resize.\n");
    } else {
        nfa_list = temp;
    }
}

void serialize_to_file(const char* filename) {
    pthread_mutex_lock(&lock);

    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("File open error");
        pthread_mutex_unlock(&lock);
        return;
    }

    size_t written_bytes = fwrite(nfa_list, sizeof(NFAPI_CRC_INDICATION_PDU_T), current_size, file);

    if (written_bytes != current_size) {
        fprintf(stderr, "Write operation incomplete.\n");
    }

    fclose(file);
    pthread_mutex_unlock(&lock);
}

int deserialize_from_file(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("File open error");
        return -1;
    }

    size_t read_entries = fread(nfa_list, sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_STRUCTURES, file);

    fclose(file);

    current_size = read_entries;
    pthread_mutex_unlock(&lock);
    return 0;
}

void log_usage() {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Log file open error");
        return;
    }

    fprintf(log_file, "Memory usage: %zu structures\n", current_size);

    fclose(log_file);
}

// Function to monitor and manage memory usage
void* monitoring_thread(void* arg) {
    while (1) {
        sleep(5); // Monitor every 5 seconds
        log_usage();
    }
    return NULL;
}

int main() {
    pthread_t monitor_tid;

    if (pthread_create(&monitor_tid, NULL, &monitoring_thread, NULL)) {
        fprintf(stderr, "Error creating monitoring thread\n");
        return EXIT_FAILURE;
