    deserialize_from_file("nfa_data.bin");

    pthread_mutex_destroy(&lock);

    free(nfa_list);  // Clean up

    pthread_cancel(monitor_tid);
    pthread_join(monitor_tid, NULL);

    return EXIT_SUCCESS;
}
