typedef struct {
    int symbol_id; // Example field representing demodulated symbol data
} NFAPI_RX_SYMBOL_T;

typedef struct {
    NFAPI_RX_SYMBOL_T *symbol_list;
    size_t symbol_count;
    pthread_mutex_t lock;
} SYMBOL_LIST_T;

typedef struct {
    int UE_INDEX;
    char RRC_status; // 'A' for Active, 'I' for Inactive
    time_t timestamp;
    SYMBOL_LIST_T symbols;
} NFAPI_RX_FRAME_T;

#define FRAME_AGE_THRESHOLD 5 * 60 // seconds

typedef struct {
    NFAPI_RX_FRAME_T **frame_list;
    size_t frame_count;
    pthread_mutex_t lock;
} FRAME_MANAGER_T;

void initialize_frame_manager(FRAME_MANAGER_T *manager) {
    manager->frame_list = NULL;
    manager->frame_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

NFAPI_RX_FRAME_T* create_frame(int UE_INDEX, char RRC_status) {
    NFAPI_RX_FRAME_T *frame = (NFAPI_RX_FRAME_T *)malloc(sizeof(NFAPI_RX_FRAME_T));
    if (!frame) return NULL;

    frame->UE_INDEX = UE_INDEX;
    frame->RRC_status = RRC_status;
    frame->timestamp = time(NULL);
    frame->symbol_list = NULL;
    frame->symbol_count = 0;
    pthread_mutex_init(&frame->symbols.lock, NULL);

    return frame;
}

void add_symbol_to_frame(NFAPI_RX_FRAME_T *frame, NFAPI_RX_SYMBOL_T symbol) {
    if (!frame) return;

    pthread_mutex_lock(&frame->symbols.lock);

    size_t new_count = frame->symbol_count + 1;
    frame->symbol_list = (NFAPI_RX_SYMBOL_T *)realloc(frame->symbol_list, new_count * sizeof(NFAPI_RX_SYMBOL_T));
    if (frame->symbol_list) {
        frame->symbol_list[frame->symbol_count] = symbol;
        frame->symbol_count = new_count;
    }

    pthread_mutex_unlock(&frame->symbols.lock);
}

void update_frame_metadata(FRAME_MANAGER_T *manager, int UE_INDEX, char RRC_status) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->frame_count; ++i) {
        NFAPI_RX_FRAME_T *frame = manager->frame_list[i];
        if (frame && frame->UE_INDEX == UE_INDEX) {
            frame->RRC_status = RRC_status;
            frame->timestamp = time(NULL);
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void discard_outdated_frames(FRAME_MANAGER_T *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    time_t now = time(NULL);
    size_t new_count = 0;

    for (size_t i = 0; i < manager->frame_count; ++i) {
        NFAPI_RX_FRAME_T *frame = manager->frame_list[i];
        if (frame && (now - frame->timestamp <= FRAME_AGE_THRESHOLD)) {
            manager->frame_list[new_count++] = frame;
        } else {
            pthread_mutex_lock(&frame->symbols.lock);
            free(frame->symbol_list);
            pthread_mutex_unlock(&frame->symbols.lock);
            pthread_mutex_destroy(&frame->symbols.lock);
            free(frame);
        }
    }

    manager->frame_count = new_count;
    if (manager->frame_count < manager->frame_count) {
        manager->frame_list = (NFAPI_RX_FRAME_T **)realloc(manager->frame_list, manager->frame_count * sizeof(NFAPI_RX_FRAME_T *));
    }

    pthread_mutex_unlock(&manager->lock);
}

void free_frame_manager(FRAME_MANAGER_T *manager) {
    if (!manager) return;

    discard_outdated_frames(manager);

    for (size_t i = 0; i < manager->frame_count; ++i) {
        NFAPI_RX_FRAME_T *frame = manager->frame_list[i];
        pthread_mutex_lock(&frame->symbols.lock);
        free(frame->symbol_list);
        pthread_mutex_unlock(&frame->symbols.lock);
        pthread_mutex_destroy(&frame->symbols.lock);
        free(frame);
    }

    free(manager->frame_list);
    pthread_mutex_destroy(&manager->lock);
}
