['Below is an example implementation of the `MessageQueue` class in C++ that meets your requirements:

```cpp
#include <iostream>
#include <memory>
#include <mutex>
#include <condition_variable>
#include <deque>
#include <thread>
#include <chrono>
#include <atomic>
#include <cstring>

struct Message {
    std::uint64_t timestamp;
    std::uint32_t id;
    std::vector<char> payload;

    bool operator==(const Message& other) const {
        return timestamp == other.timestamp && id == other.id && payload == other.payload;
    }
};

class MessageQueue {
public:
    using MessagePtr = std::shared_ptr<Message>;

    void push(const MessagePtr& message) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push_back(message);
        cv_.notify_one();
    }

    bool try_pop(MessagePtr& message) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (queue_.empty()) {
            return false;
        }
        message = queue_.front();
        queue_.pop_front();
        return true;
    }

    void wait_and_pop(MessagePtr& message) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this]() { return !queue_.empty(); });
        message = queue_.front();
        queue_.pop_front();
    }

private:
    mutable std::mutex mutex_;
    std::condition_variable cv_;
    std::deque<MessagePtr> queue_;
};

// Example usage
int main() {
    MessageQueue mq;

    auto producer = [&mq]() {
        for (std::uint32_t i = 0; i < 10; ++i) {
            auto message = std::make_shared<Message>();
            message->timestamp = std::chrono::system_clock::now().time_since_epoch().count();
            message->id = i;
            message->payload.push_back('A' + (i % 26));
            mq.push(message);
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    };

    auto consumer = [&mq]() {
        for (int i = 0; i < 10; ++i) {
            MessageQueue::MessagePtr message;
            mq.wait_and_pop(message);
            std::cout << "Consumed: ID=" << message->id << ", Payload=" << message->payload[0] << "\n";
        }
    };

    std::thread t1(producer);
    std::thread t2(consumer);

    t1.join();
    t2.join();

    return 0;
}
```

### Key Features:

- **Concurrency Control**: Uses a `std::mutex` and `std::condition_variable` to manage concurrent access, allowing multiple threads to read/write safely.
- **Memory Management**: Utilizes `std::shared_ptr` for automatic memory management of messages.
- **Serialization**: Not explicitly shown but can be added by implementing serialization functions within the `Message` struct.
- **Scalability**: Designed to handle high-throughput scenarios with minimal lock contention using condition variables to manage thread waiting efficiently.
- **Error Handling**: Basic error handling is demonstrated through safe checks before accessing queue elements.

This implementation provides a foundation for further enhancements, such as integrating more sophisticated serialization mechanisms or optimizing memory usage with custom allocators.']

