// Define the structure
typedef struct {
    uint16_t DL_USER_INFO_TAG;
    uint16_t RNTI;
    bool CRC_INDICATION;
} LTE_Downlink_Data_Pdu;

// Define a dynamic array manager with custom allocator and mutex for thread safety
typedef struct {
    LTE_Downlink_Data_Pdu *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread-safety
} LTE_Array_Manager;

// Custom memory allocator functions (simple example, can be replaced with more complex logic)
void* custom_alloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr && size > 0) { 
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE); // Handle failure as needed
    }
    return ptr;
}

void custom_free(void *ptr) {
    free(ptr);
}

// Initialize the LTE Array Manager
void init_manager(LTE_Array_Manager* manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->array = (LTE_Downlink_Data_Pdu*)custom_alloc(initial_capacity * sizeof(LTE_Downlink_Data_Pdu));
    manager->capacity = initial_capacity;
    manager->count = 0;
}

// Resize the dynamic array
void resize_manager(LTE_Array_Manager* manager) {
    size_t new_capacity = manager->capacity * 2;
    LTE_Downlink_Data_Pdu* temp_array = (LTE_Downlink_Data_Pdu*)custom_alloc(new_capacity * sizeof(LTE_Downlink_Data_Pdu));

    if (!temp_array && manager->count > 0) {
        fprintf(stderr, "Memory allocation failed during resize\n");
        // Implement fallback mechanism
    }

    for (size_t i = 0; i < manager->count; ++i) {
        temp_array[i] = manager->array[i];
    }

    custom_free(manager->array);
    manager->array = temp_array;
    manager->capacity = new_capacity;
}

// Insert data into the array
void insert_data(LTE_Array_Manager* manager, LTE_Downlink_Data_Pdu data) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resize_manager(manager);
    }

    manager->array[manager->count++] = data;

    pthread_mutex_unlock(&manager->lock);
}

// Delete the last element from the array
void delete_last(LTE_Array_Manager* manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count > 0) {
        manager->count--;
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    LTE_Array_Manager manager;
    init_manager(&manager, 4); // Initial capacity of 4

    // Example usage
    for (size_t i = 0; i < 10; ++i) {
        LTE_Downlink_Data_Pdu data = { .DL_USER_INFO_TAG = i,
                                       .RNTI = i + 1,
                                       .CRC_INDICATION = (i % 2 == 0) };
        insert_data(&manager, data);
    }

    delete_last(&manager);

    // Cleanup
    custom_free(manager.array);
    pthread_mutex_destroy(&manager.lock);

    return 0;
}
