Here's a Java application to manage the lifecycle of a network service with integration for messaging and robust handling:

```java
import java.util.Random;
import java.util.concurrent.*;
import javax.jms.*;

public class NetworkServiceManager {

    private static final int MAX_PDUS = 100;
    private ScheduledExecutorService scheduler;
    private JMSContext context; // Assuming ActiveMQ or similar

    public NetworkServiceManager() throws Exception {
        this.scheduler = Executors.newScheduledThreadPool(1);
        setupMessaging();
    }

    private void setupMessaging() throws JMSException {
        // Initialize the messaging system (example using ActiveMQ)
        ConnectionFactory factory = new ActiveMQConnectionFactory("tcp://localhost:61616");
        context = factory.createContext();
    }

    public void startServiceCycle(int startInterval, int stopInterval) {
        scheduler.scheduleAtFixedRate(this::startService, 0, startInterval, TimeUnit.MILLISECONDS);
        scheduler.scheduleAtFixedRate(this::stopAndProcess, startInterval + stopInterval / 2, 
                                      startInterval + stopInterval, TimeUnit.MILLISECONDS);
    }

    private void startService() {
        // Logic to start the network service
        System.out.println("Network Service Started");
    }

    private void stopAndProcess() {
        NFAPI_CRC_INDICATION_PDU_T[] pdus = generatePDUs();

        try (JMSProducer producer = context.createProducer()) {
            for (NFAPI_CRC_INDICATION_PDU_T pdu : pdus) {
                sendStatusMessage(producer, "Processed PDU: " + pdu);
            }
        } catch (Exception e) {
            handleUnexpectedError(e);
        }

        // Logic to stop the network service
        System.out.println("Network Service Stopped");
    }

    private NFAPI_CRC_INDICATION_PDU_T[] generatePDUs() {
        Random random = new Random();
        NFAPI_CRC_INDICATION_PDU_T[] pdus = new NFAPI_CRC_INDICATION_PDU_T[Math.min(MAX_PDUS, 100)];

        for (int i = 0; i < pdus.length; i++) {
            int crcFlag = random.nextBoolean() ? 1 : 0;
            pdus[i] = new NFAPI_CRC_INDICATION_PDU_T(i + 1, i + 2, crcFlag);
        }

        return pdus;
    }

    private void sendStatusMessage(JMSProducer producer, String message) throws JMSException {
        TextMessage textMessage = context.createTextMessage(message);
        producer.send(context.createQueue("ServiceStatus"), textMessage);
    }

    private void handleUnexpectedError(Exception e) {
        // Logic for handling exceptions and reporting
        System.err.println("An error occurred: " + e.getMessage());
    }

    public static void main(String[] args) {
        try {
            NetworkServiceManager manager = new NetworkServiceManager();
            manager.startServiceCycle(1000, 5000); // Start every 1s, stop every 5s
        } catch (Exception e) {
            System.err.println("Failed to initialize Network Service Manager: " + e.getMessage());
        }
    }

    static class NFAPI_CRC_INDICATION_PDU_T {
        int RX_UE_INFORMATION_TAG;
        int RNTI;
        int CRCFLAG;

        public NFAPI_CRC_INDICATION_PDU_T(int rxTag, int rnti, int crcFlag) {
            this.RX_UE_INFORMATION_TAG = rxTag;
            this.RNTI = rnti;
            this.CRCFLAG = crcFlag;
        }

        @Override
        public String toString() {
            return "NFAPI_CRC_INDICATION_PDU_T{" +
                    "RX_UE_INFORMATION_TAG=" + RX_UE_INFORMATION_TAG +
                    ", RNTI=" + RNTI +
                    ", CRCFLAG=" + CRCFLAG +
                    '}';
        }
    }
}
