            if (!payload_data) {
                fprintf(stderr, "Memory allocation failed for payload data.\n");
                free(packets[i].cpcs_pdu_list);
                cleanup_packets(packets, i);
                return NULL;
            }
            memset(payload_data, rand() % 256, packets[i].PayloadSize);
        }
    }

    return packets;
}

void cleanup_packets(NetworkLayerPacketInfo *packets, size_t packet_count) {
    for (size_t i = 0; i < packet_count; ++i) {
        if (packets[i].cpcs_pdu_list) {
            free(packets[i].cpcs_pdu_list);
        }
    }
    free(packets);
}

int generate_packets(const char *config_file) {
    struct json_object *parsed_json;
    struct json_object *packet_generation_parameters;

    parsed_json = json_object_from_file(config_file);
    if (!parsed_json) {
        fprintf(stderr, "Failed to parse configuration file.\n");
        return -1;
    }

    if (!json_object_object_get_ex(parsed_json, "packet_generation_parameters", &packet_generation_parameters)) {
        fprintf(stderr, "Invalid configuration format.\n");
        json_object_put(parsed_json);
        return -1;
    }

    int max_packets_per_second = 0;
    struct json_object *max_pps;
    if (json_object_object_get_ex(packet_generation_parameters, "max_packets_per_second", &max_pps)) {
        max_packets_per_second = json_object_get_int(max_pps);
    } else {
        fprintf(stderr, "Missing packet generation parameter.\n");
        json_object_put(parsed_json);
        return -1;
    }

    size_t packet_count = min(MAX_PACKETS, (size_t)max_packets_per_second);

    pthread_mutex_lock(&mutex);
    NetworkLayerPacketInfo *packets = initialize_packet_info(packet_count);
    pthread_mutex_unlock(&mutex);

    if (!packets) {
        fprintf(stderr, "Failed to generate packets.\n");
        return -1;
    }

    // Simulate network operations
    for (size_t i = 0; i < packet_count; ++i) {
        printf("Packet %zu: Dest: %s, Src: %s, Size: %zu\n",
               i, packets[i].DestinationAddress, packets[i].SourceAddress, packets[i].PayloadSize);
    }

    cleanup_packets(packets, packet_count);

    json_object_put(parsed_json);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return -1;
    }

    return generate_packets(argv[1]);
}
