['Here's an implementation of a C function that manages a scalable queue of `MediaStreamFrame` structures, populating a list of `NFAPI_PHY_RX_PDU_T` structures with random payload data while ensuring memory efficiency and thread safety:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_FRAME_COUNT 1000

typedef struct {
    uint64_t Timestamp;
    int FrameID;
    size_t PayloadSize;
} MediaStreamFrame;

typedef enum {
    CRC_OK,
    CRC_ERROR
} CRC_STATUS;

typedef struct {
    uint32_t RX_FRAME_INDICATION_TAG;
    char FRAME_TYPE; // e.g., 'A', 'B', etc.
    CRC_STATUS CRC_CHECK_RESULT_TAG;
    void* PayloadData;
} NFAPI_PHY_RX_PDU_T;

typedef struct Node {
    MediaStreamFrame frame;
    NFAPI_PHY_RX_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} FrameQueue;

// Initialize the queue
void initFrameQueue(FrameQueue* q) {
    q->head = NULL;
    pthread_mutex_init(&q->lock, NULL);
}

// Add a frame to the queue
int addFrameToQueue(FrameQueue* q, MediaStreamFrame frame) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1;

    newNode->frame = frame;
    newNode->next = NULL;

    pthread_mutex_lock(&q->lock);
    newNode->pdu.PayloadData = malloc(frame.PayloadSize);
    if (!newNode->pdu.PayloadData) {
        free(newNode);
        pthread_mutex_unlock(&q->lock);
        return -1;
    }

    // Populate the NFAPI_PHY_RX_PDU_T structure
    newNode->pdu.RX_FRAME_INDICATION_TAG = rand();
    newNode->pdu.FRAME_TYPE = 'A'; // Example frame type
    newNode->pdu.CRC_CHECK_RESULT_TAG = (CRC_STATUS)(rand() % 2);

    // Fill payload with random data
    memset(newNode->pdu.PayloadData, rand(), frame.PayloadSize);

    // Add to queue
    if (!q->head) {
        q->head = newNode;
    } else {
        Node* current = q->head;
        while (current->next) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&q->lock);
    return 0;
}

// Process and remove a frame from the queue
int processFrameFromQueue(FrameQueue* q, NFAPI_PHY_RX_PDU_T* pdu) {
    if (!pdu || !q->head) return -1;

    pthread_mutex_lock(&q->lock);

    Node* nodeToRemove = q->head;
    *pdu = nodeToRemove->pdu;
    q->head = nodeToRemove->next;

    free(nodeToRemove->pdu.PayloadData);
    free(nodeToRemove);

    pthread_mutex_unlock(&q->lock);
    return 0;
}

// Clean up the queue
void cleanupFrameQueue(FrameQueue* q) {
    Node* current = q->head;
    while (current) {
        Node* next = current->next;
        free(current->pdu.PayloadData);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&q->lock);
}

// Example usage
int main() {
    srand(time(NULL));
    FrameQueue queue;
    initFrameQueue(&queue);

    MediaStreamFrame frame1 = {123456789, 1, 1024};
    addFrameToQueue(&queue, frame1);

    NFAPI_PHY_RX_PDU_T pdu;
    if (processFrameFromQueue(&queue, &pdu) == 0) {
        printf("Processed Frame ID: %d\n", pdu.RX_FRAME_INDICATION_TAG);
    }

    cleanupFrameQueue(&queue);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The function uses a mutex to ensure thread-safe access to the queue.
- **Memory Management**: Memory is dynamically allocated and freed, with checks for allocation failures.
- **Random Data**: Payload data is filled with random bytes using `rand()`.
- **Scalability**: Designed to handle multiple frames efficiently, with considerations for memory constraints.
- **Error Handling**: Returns error codes on failure, such as `-1` for allocation errors.']

