        }
    }

    // Determine the optimal network configuration mode
    NetworkConfigMode selected_mode = select_optimal_modes();

    // Log the usage of the chosen configuration mode
    log_configuration_usage(selected_mode);

    *size = num_channels;
    return channel_info_array;
