#define MAX_THREADS 10
#define ARRAY_SIZE 100

typedef struct {
    uint64_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_TAG;
} NFAPI_RX_FRAME_INFO;

// Seed for the pseudo-random sequence generator
static uint32_t seed = 0xACE1u;

uint8_t generate_crc_flag() {
    // Custom Linear Congruential Generator (LCG) algorithm
    seed = (1664525 * seed + 1013904223) & 0xFFFFFFFF;
    return (seed >> 16) & 1; // Return the least significant bit as CRC flag
}

void* initialize_rx_frame_info_array(void* arg) {
    NFAPI_RX_FRAME_INFO* array = (NFAPI_RX_FRAME_INFO*)arg;
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < ARRAY_SIZE; ++i) {
        pthread_mutex_lock(&lock);

        // Populate the structure
        array[i].RX_UE_INFORMATION_TAG = (uint64_t)(i + 1) << 32 | (uint32_t)i;
        array[i].RNTI = (uint16_t)((i * 12345) % 65535); // Example pattern for RNTI
        array[i].CRC_INDICATION_TAG = generate_crc_flag();

        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
    return NULL;
}

NFAPI_RX_FRAME_INFO* create_rx_frame_info_array() {
    NFAPI_RX_FRAME_INFO* array = (NFAPI_RX_FRAME_INFO*)malloc(ARRAY_SIZE * sizeof(NFAPI_RX_FRAME_INFO));
    if (!array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        int rc = pthread_create(&threads[i], NULL, initialize_rx_frame_info_array, array);
        if (rc != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return array;
}

void free_rx_frame_info_array(NFAPI_RX_FRAME_INFO* array) {
    free(array);
}

