['Below is a C implementation of the described functionality:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    size_t capacity;
    size_t count;
    record *records;
    pthread_mutex_t mutex;
    int last_value;
} dynamic_array;

// Function to initialize the array
dynamic_array* init_dynamic_array(size_t initial_capacity) {
    dynamic_array *arr = (dynamic_array*)malloc(sizeof(dynamic_array));
    if (!arr) return NULL;

    arr->capacity = initial_capacity;
    arr->count = 0;
    arr->records = (record*)malloc(initial_capacity * sizeof(record));
    if (!arr->records) {
        free(arr);
        return NULL;
    }

    pthread_mutex_init(&arr->mutex, NULL);
    arr->last_value = -1; // Initialize to an invalid value

    return arr;
}

// Function to resize the array
int resize_dynamic_array(dynamic_array *arr, size_t new_capacity) {
    record *new_records = (record*)realloc(arr->records, new_capacity * sizeof(record));
    if (!new_records) return -1;

    arr->capacity = new_capacity;
    arr->records = new_records;

    return 0; // Success
}

// Function to initialize records with random values ensuring no two consecutive are the same
int init_record_with_random_value(dynamic_array *arr, int min_val, int max_val) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->count >= arr->capacity && resize_dynamic_array(arr, arr->capacity * 2) != 0) {
        fprintf(stderr, "Failed to resize dynamic array\n");
        pthread_mutex_unlock(&arr->mutex);
        return -1;
    }

    int new_value = rand() % (max_val - min_val + 1) + min_val;

    // Ensure the value is different from the last one
    while (new_value == arr->last_value) {
        new_value = rand() % (max_val - min_val + 1) + min_val;
    }

    arr->records[arr->count].value = new_value;
    arr->last_value = new_value;

    // Log initialization
    printf("Initialized record at index %zu with value: %d\n", arr->count, new_value);

    arr->count++;

    pthread_mutex_unlock(&arr->mutex);
    return 0; // Success
}

// Function to free the dynamic array resources
void free_dynamic_array(dynamic_array *arr) {
    if (!arr) return;

    pthread_mutex_lock(&arr->mutex);

    if (arr->records) {
        free(arr->records);
    }

    pthread_mutex_unlock(&arr->mutex);
    pthread_mutex_destroy(&arr->mutex);

    // Log deallocation
    printf("Deallocated dynamic array with %zu records\n", arr->count);

    free(arr);
}

// Function to fetch data and initialize the array
int fetch_and_initialize(dynamic_array *arr, size_t num_records, int min_val, int max_val) {
    for (size_t i = 0; i < num_records; ++i) {
        if (init_record_with_random_value(arr, min_val, max_val) != 0) {
            fprintf(stderr, "Error initializing record at index %zu\n", i);
            return -1;
        }
    }

    // Log completion of initialization
    printf("Completed initialization with %zu records\n", arr->count);

    return 0; // Success
}

int main() {
    srand((unsigned)time(NULL)); // Seed for random number generation

    dynamic_array *arr = init_dynamic_array(10);
    if (!arr) {
        fprintf(stderr, "Failed to initialize array\n");
        return -1;
    }

    int min_val = 0, max_val = 100;
    size_t num_records = 20;

    if (fetch_and_initialize(arr, num_records, min_val, max_val) != 0) {
        fprintf(stderr, "Failed during data fetch and initialization\n");
    } else {
        printf("Data fetching and initialization completed successfully.\n");
    }

    free_dynamic_array(arr);

    return 0;
}
```

### Key Features:

- **Thread-Safe Initialization**: Uses `pthread_mutex_t` to ensure thread-safe access when initializing records.
