```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_USERS 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *data;
    pthread_mutex_t mutex;
} DynamicArray;

int init_dynamic_array(DynamicArray *array, size_t initial_capacity) {
    if (pthread_mutex_init(&array->mutex, NULL) != 0) return -1;
    array->capacity = initial_capacity;
    array->count = 0;
    array->data = malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return array->data == NULL ? -1 : 0;
}

void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_destroy(&array->mutex);
    free(array->data);
}

int resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data == NULL) return -1;
    array->capacity = new_capacity;
    array->data = new_data;
    return 0;
}

int add_pdu(DynamicArray *array, unsigned int user_id, unsigned int seed) {
    pthread_mutex_lock(&array->mutex);

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        if (resize_dynamic_array(array, new_capacity) != 0) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = user_id;
    pdu.RNTI = seed + array->count; // Simple generation based on seed
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    array->data[array->count++] = pdu;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void initialize_array_from_data(DynamicArray *array, unsigned int *user_ids, size_t n, unsigned int seed) {
    if (init_dynamic_array(array, n) != 0) return;

    for (size_t i = 0; i < n; ++i) {
        if (add_pdu(array, user_ids[i], seed) != 0) {
            fprintf(stderr, "Failed to add PDU for user ID %u\n", user_ids[i]);
            free_dynamic_array(array);
            return;
        }
    }
}

// Example usage
int main() {
    DynamicArray array;
    unsigned int user_ids[MAX_USERS];

    // Fill user_ids with some values (for example, 1 to MAX_USERS)
    for (unsigned int i = 0; i < MAX_USERS; ++i) {
        user_ids[i] = i + 1;
    }

    initialize_array_from_data(&array, user_ids, MAX_USERS / 2, 42);

    // Perform operations on the array...

    free_dynamic_array(&array);
    return 0;
}
```

### Key Points:
- **Dynamic Array Management**: The `DynamicArray` structure manages a dynamic array with mutex protection for thread safety.
- **Concurrency**: Uses `pthread_mutex_t` to ensure safe concurrent access.
- **Memory Management**: Efficiently handles memory allocation and resizing using `malloc`, `realloc`, and `free`.
- **Initialization**: Initializes the array with user IDs and generates RNTI values based on a seed.
- **Graceful Error Handling**: Handles failures in memory operations gracefully.']

