#include <openssl/evp.h>
#include <openssl/conf.h>
#include <openssl/engine.h>
#include <openssl/crypto.h>
#include <pthread.h>

// Error handling omitted for brevity

typedef struct {
    EVP_CIPHER_CTX *cipher_ctx;
    EVP_MD_CTX *digest_ctx;
    ENGINE *engine;
} CryptoContext;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int initialize_crypto_context(CryptoContext *ctx, const char *algorithm) {
    if (algorithm == NULL || ctx == NULL) return -1;

    ENGINE_load_builtin_engines();
    ENGINE *e = ENGINE_by_id("dynamic");
    if (!ENGINE_init(e)) return -1;

    // Lazy initialization for cipher context
    pthread_mutex_lock(&lock);
    if (ctx->cipher_ctx == NULL && EVP_get_cipherbyname(algorithm) != NULL) {
        ctx->cipher_ctx = EVP_CIPHER_CTX_new();
        ENGINE_set_default_RSA(e, NULL);  // Set default engine for RSA
    }
    pthread_mutex_unlock(&lock);

    // Lazy initialization for digest context
    if (ctx->digest_ctx == NULL && EVP_get_digestbyname(algorithm) != NULL) {
        ctx->digest_ctx = EVP_MD_CTX_new();
    }

    ctx->engine = e;
    return 0;
}

int clean_up_crypto_context(CryptoContext *ctx) {
    if (ctx->cipher_ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx->cipher_ctx);
        ctx->cipher_ctx = NULL;
    }
    if (ctx->digest_ctx != NULL) {
        EVP_MD_CTX_free(ctx->digest_ctx);
        ctx->digest_ctx = NULL;
    }
    if (ctx->engine != NULL && ENGINE_finish(ctx->engine)) {
        ENGINE_free(ctx->engine);
        ctx->engine = NULL;
    }
    return 0;
}

int perform_cryptography(CryptoContext *ctx, const unsigned char *input, size_t input_len,
                         unsigned char *output, size_t *output_len) {
    if (input == NULL || output == NULL || output_len == NULL || ctx == NULL)
        return -1;

    // Assuming cipher context is used; similar for digest
    int len;
    int ret = EVP_EncryptInit_ex(ctx->cipher_ctx, EVP_get_cipherbyname("aes-256-cbc"), 
                                 ctx->engine, NULL, NULL);
    if (ret <= 0) return ret;

    ret = EVP_EncryptUpdate(ctx->cipher_ctx, output, &len, input, input_len);
    if (ret <= 0) return ret;
    *output_len = len;

    // Finalize encryption
    ret = EVP_EncryptFinal_ex(ctx->cipher_ctx, output + len, &len);
    if (ret > 0) (*output_len) += len;

    return ret;
}

// Additional helper functions for RSA and SHA1 omitted for brevity

void test_crypto_library() {
