    initialize_crypto_context(&ctx, "aes-256-cbc");

    unsigned char input[] = "Test data";
    unsigned char output[1024];
    size_t output_len;

    if (perform_cryptography(&ctx, input, sizeof(input), output, &output_len) > 0) {
        // Handle successful encryption
    }

    clean_up_crypto_context(&ctx);
}

int main() {
    test_crypto_library();
    return 0;
}
